      out+="${out:+,}{\"id\":0,\"name\":\"$n\",\"width\":${wh%x*},\"height\":${wh#*x},${mon/\"x\":0,\"y\":0,\"scale\":1.0/\"x\":${x:-0},\"y\":${y:-0},\"scale\":${s:-1.0}}}"
