if want == "closed" and (not made or any(n not in closed for n in made)):
    bad.append("made %s, closed %s" % (made, closed))
if want == "kept" and (not made or closed):
    bad.append("made %s, closed %s" % (made, closed))
if want.isdigit() and len(made) != int(want):
