  check_eq "...WAYLAND-2 and WAYLAND-3 recorded" "WAYLAND-2 WAYLAND-3" "$(cut -d' ' -f1 "$r/rt/omabox/fki/run/omabox.monitors" | sort | paste -sd' ')"
