    cat > "$H/viewports.py" <<'PY'
import gi, sys
gi.require_version("Gtk", "4.0")
gi.require_version("Gsk", "4.0")
gi.require_version("Graphene", "1.0")
from gi.repository import Gtk, Gdk, Gsk, Graphene
keep = []
def bare(display, title):
    s = Gdk.Surface.new_toplevel(display)
    s.set_title(title)
    r = Gsk.CairoRenderer()
    r.realize(s)
    def draw(s, w, h):
        c = Gdk.RGBA(); c.parse("#336699")
        r.render(Gsk.ColorNode.new(c, Graphene.Rect().init(0, 0, w, h)), None)
    s.connect("compute-size", lambda s, sz: sz.set_size(300, 300))
    s.connect("layout", draw)
    s.present(Gdk.ToplevelLayout.new())
    keep.extend((s, r))
def build(app):
    w = Gtk.ApplicationWindow(application=app, title="Root viewport")
    w.set_child(Gtk.Button(label="Root button"))
    w.present()
    for i in range(int(sys.argv[1])):
        bare(w.get_display(), "%s viewport %d" % (sys.argv[2], i + 1))
app = Gtk.Application(application_id="org.omabox.Viewports")
app.connect("activate", build)
app.run(None)
PY
    # Alone on the workspace, so tiled: two windows of one size, then the root beside two halves.
    ob run -b "$B" -- pkill -f 'tree-demo|mute-a11y' >/dev/null 2>&1 || true
    ob wait -b "$B" --timeout 10s window 'title:^Tree demo GTK4$' --gone >/dev/null 2>&1 || true
    ob wait -b "$B" --timeout 10s window 'title:^Tree demo QML$' --gone >/dev/null 2>&1 || true
    ob run -b "$B" -d -- env GSK_RENDERER=cairo python3 /home/sbx/viewports.py 1 Twin >/dev/null 2>&1
    ob wait -b "$B" --timeout 20s window 'title:^Twin viewport 1$' >/dev/null
    rc=0; out=$(ob tree -b "$B" --window 'title:^Twin viewport 1$' 2>&1) || rc=$?
    check_eq "an app's only frame, the size of two of its windows: cannot be told, exit 1" "1 yes" \
      "$rc $(grep -q 'publishes one window, "Root viewport", and 2 of its windows are this one.s size.*cannot be told' <<<"$out" && echo yes)"
    check_match "...the window it names still has its tree" '^frame "Root viewport" ' "$(ob tree -b "$B" --window 'title:^Root viewport$' 2>&1)"
    ob run -b "$B" -- pkill -f viewports.py >/dev/null 2>&1 || true
    ob wait -b "$B" --timeout 10s window 'title:^Twin viewport 1$' --gone >/dev/null 2>&1 || true
    ob run -b "$B" -d -- env GSK_RENDERER=cairo python3 /home/sbx/viewports.py 2 Child >/dev/null 2>&1
    ob wait -b "$B" --timeout 20s window 'title:^Child viewport 2$' >/dev/null
    rc=0; out=$(ob tree -b "$B" --window 'title:^Child viewport 2$' 2>&1) || rc=$?
    check_eq "...one of another size: no tree for it (not the root's), exit 1" "1 yes" \
      "$rc $(grep -qE 'no accessibility tree for this window: its application publishes one window, "Root viewport" [0-9]+x[0-9]+, and this one is [0-9]+x[0-9]+' <<<"$out" && echo yes)"
    ob run -b "$B" -- pkill -f viewports.py >/dev/null 2>&1 || true
  else
    skip "tree of a GTK4 window" "no GTK4 or python-gobject"
  fi
  # #341: an editable combo box (an input with suggestions: Chromium, Qt WebEngine) holds its typed
  # text itself, with no entry under it; a closed select's choice stays its value.
  if ob run -b "$B" -- sh -c 'command -v chromium' >/dev/null 2>&1; then
    cat > "$H/tree-combo.html" <<'HTML'
<!doctype html><title>Tree combo web</title>
<label>new path <input list="s" value="/home/sbx/typed path"></label>
<datalist id="s"><option value="/home/sbx/old"></option></datalist>
<p><select aria-label="closed"><option>one</option><option selected>two</option></select></p>
HTML
    ob run -b "$B" -d -- chromium --force-renderer-accessibility --no-first-run --user-data-dir=/home/sbx/tree-chromium \
      --app=file:///home/sbx/tree-combo.html >/dev/null 2>&1
    ob wait -b "$B" --timeout 30s window 'title:Tree combo web' >/dev/null
    until_ok 15 bash -c "'$CLI' tree -b '$B' --window 'Tree combo web' --find closed >/dev/null 2>&1" || true
    check_match "Chromium: an editable combo box's typed text, found by it" \
      "combo box \"new path\" '/home/sbx/typed path' \\[editable\\] @" "$(ob tree -b "$B" --window 'Tree combo web' --find 'typed path' 2>&1)"
    check_eq "...in --json" "/home/sbx/typed path" \
      "$(ob tree -b "$B" --window 'Tree combo web' --json --find 'typed path' 2>&1 | jq -r '.[0].text' 2>&1)"
    check_match "...a closed select still says its choice as its value, no text" \
      'combo box "closed" =two @' "$(ob tree -b "$B" --window 'Tree combo web' --find closed 2>&1)"
    ob run -b "$B" -- pkill -f tree-chromium >/dev/null 2>&1 || true
  else
    skip "tree of an editable combo box (Chromium)" "no chromium"
  fi
  ob run -b "$B" -d -- foot --app-id=omabox.tree >/dev/null 2>&1
  ob wait -b "$B" --timeout 20s window omabox.tree >/dev/null
  rc=0; out=$(ob tree -b "$B" --window omabox.tree 2>&1) || rc=$?
  check_eq "foot: no accessibility tree, said, exit 1" "1 yes" "$rc $(grep -q 'no accessibility tree' <<<"$out" && echo yes)"
  check_match "...and where one is to be had" "force-renderer-accessibility.*terminals" "$out"
  # #237: AccessKit before 0.22 (egui apps on eframe 0.36 and older) registers only once
  # ScreenReaderEnabled is on: `tree` sets it with IsEnabled (no egui app here: checked by hand).
  # Without one (finding 368), an app not on the bus is said to be possibly such an app.
  if [ "$sre" = 1 ]; then
    check_eq "after tree, ScreenReaderEnabled is on (older AccessKit apps watch only it)" "b true" \
      "$(ob run -b "$B" -- busctl --user get-property org.a11y.Bus /org/a11y/bus org.a11y.Status ScreenReaderEnabled 2>&1)"
  else
    check_match "...not on the bus, with no ScreenReaderEnabled to set: an older AccessKit app's reason said" \
      "not on the box's accessibility bus \(an egui/winit app on AccessKit before accesskit_unix 0.22 never joins it here" "$out"
  fi
  check_match "a window that is not there: the box's windows listed" "no window matches nosuchwindow" "$(ob tree -b "$B" --window nosuchwindow 2>&1)"
  check "down" ob down "$B"
}

# click --find TEXT (#318): the one node named TEXT, read fresh, clicked at the middle of what of it
# is in view with the real pointer; several, hidden, scrolled out or disabled said, nothing clicked.
t_click_find() {
  local B=$P-cf H out rc
  check "up" ob up "$B" --no-shell
  H=$(ob path -b "$B")/home
  check_eq "--find and X Y: exit 2" 2 "$(ob click -b "$B" --find x 10 10 >/dev/null 2>&1; echo $?)"
  check_eq "--index without --find: exit 2" 2 "$(ob click -b "$B" --index 1 10 10 >/dev/null 2>&1; echo $?)"
  check_eq "--index 0: exit 2" 2 "$(ob click -b "$B" --find x --index 0 >/dev/null 2>&1; echo $?)"
  check_eq "--find with no name: exit 2" 2 "$(ob click -b "$B" --find "" >/dev/null 2>&1; echo $?)"
  check_eq "--window and --layer: exit 2" 2 "$(ob click -b "$B" --find x --window a --layer b >/dev/null 2>&1; echo $?)"
  if ! ob run -b "$B" -- python3 -c 'import gi; gi.require_version("Gtk", "4.0")' >/dev/null 2>&1; then
    skip "click --find in a GTK4 window" "no GTK4 or python-gobject"; ob down "$B" >/dev/null; return
  fi
  cat > "$H/find-demo.py" <<'PY'
import gi
gi.require_version("Gtk", "4.0")
from gi.repository import Gtk
def build(app):
    win = Gtk.ApplicationWindow(application=app, title="Find demo")
    box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=6, margin_top=12, margin_start=12, margin_end=12)
    box.append(Gtk.CheckButton(label="Dark mode", active=False))
    count = Gtk.Button(label="Count 0")
    count.connect("clicked", lambda b: b.set_label("Count %d" % (int(b.get_label().split()[1]) + 1)))
    box.append(count)
    row = Gtk.Box(spacing=6)
    for n in (1, 2):
        b = Gtk.Button(label="Save")
        b.connect("clicked", lambda b, n=n: win.set_title("Saved %d" % n))
        row.append(b)
    box.append(row)
    box.append(Gtk.Button(label="Delete", sensitive=False))
    lab = Gtk.Label.new_with_mnemonic("_Email")
    ent = Gtk.Entry()
    lab.set_mnemonic_widget(ent)
    box.append(lab)
    box.append(ent)
    sw = Gtk.ScrolledWindow(min_content_height=80)
    inner = Gtk.Box(orientation=Gtk.Orientation.VERTICAL)
    for i in range(30):
        inner.append(Gtk.Label(label="Line %d" % i))
    inner.append(Gtk.Button(label="Below the fold"))
    sw.set_child(inner)
    box.append(sw)
    win.set_child(box)
    win.present()
app = Gtk.Application(application_id="org.omabox.FindDemo")
app.connect("activate", build)
app.run(None)
PY
  ob run -b "$B" -d -- python3 /home/sbx/find-demo.py >/dev/null 2>&1
  ob wait -b "$B" --timeout 20s window 'title:^Find demo$' >/dev/null
  out=$(ob click -b "$B" --find 'dark mode' --wait 2>&1); rc=$?
  check_match "the active window by default: its line said, and where the pointer went" \
    '^omabox: click: check box "Dark mode" \[[a-z ]*unchecked\] @[0-9]+,[0-9]+ [0-9]+x[0-9]+: at [0-9]+,[0-9]+' "$out"
  check "...it checks it" until_ok 5 \
    bash -c "'$CLI' tree -b '$B' --window 'Find demo' --find 'dark mode' | grep -q '^check box \"Dark mode\" \[focused checked\]'"
  ob click -b "$B" --window 'Find demo' --find 'count' --wait >/dev/null 2>&1
  check "a part of a name, any case: the button pressed" until_ok 5 \
    bash -c "'$CLI' tree -b '$B' --window 'Find demo' --find 'count 1' | grep -q 'button \"Count 1\"'"
  out=$(ob click -b "$B" --window 'Find demo' --find 'line 1' 2>&1)
  check_match "an exact name wins over a part of one (Line 1, not Line 10 to 19)" 'label "Line 1" @' "$out"
  out=$(ob click -b "$B" --window 'Find demo' --find email 2>&1)
  check_match "a control wins over a label of its name (GTK names the entry after its label)" '^omabox: click: text "Email" ' "$out"
  out=$(ob click -b "$B" --window 'Find demo' --find save 2>&1); rc=$?
  check_eq "two in view: exit 2, nothing clicked" "2 Find demo" "$rc $(ob windows -b "$B" --json | jq -r '.[] | select(.class == "org.omabox.FindDemo") | .title')"
  check_match "...both listed, numbered for --index" $'2 in view are named "save": pick one with --index N\n  1: button "Save" @[^\n]*\n  2: button "Save" @' "$out"
  ob click -b "$B" --window 'Find demo' --find save --index 2 >/dev/null 2>&1
  check "...--index 2 clicks the second" until_ok 5 bash -c "'$CLI' windows -b '$B' | grep -q 'Saved 2'"
  check_eq "...--index past them: exit 2" 2 "$(ob click -b "$B" --window FindDemo --find save --index 3 >/dev/null 2>&1; echo $?)"
  out=$(ob click -b "$B" --window FindDemo --find delete 2>&1); rc=$?
  check_eq "a disabled button: exit 1, said" "1 yes" "$rc $(grep -q 'button "Delete" \[disabled\] @.*: disabled' <<<"$out" && echo yes)"
  out=$(ob click -b "$B" --window FindDemo --find 'below the fold' 2>&1); rc=$?
  check_eq "a button scrolled out of its scrolled window, though inside the window: exit 1" 1 "$rc"
  check_match "...said: scroll it into view" 'button "Below the fold" @[^:]*: not in view .*scroll it into view first' "$out"
  out=$(ob click -b "$B" --window FindDemo --find 'no such words' 2>&1); rc=$?
  check_eq "nothing named so: exit 1, said" "1 yes" "$rc $(grep -q 'nothing in the window is named "no such words"' <<<"$out" && echo yes)"
  ob run -b "$B" -- pkill -f find-demo.py >/dev/null 2>&1 || true
  # Finding 244: a QDockWidget's contents say they are at 0,0, relative to the dock; Qt's screen
  # coordinates have where they are drawn (its filter field, under the dock's title).
  if ob run -b "$B" -- sh -c 'command -v designer6' >/dev/null 2>&1; then
    ob run -b "$B" -d -- designer6 >/dev/null 2>&1
    if ob wait -b "$B" --timeout 30s window 'title:^New Form' >/dev/null 2>&1; then
      ob click -b "$B" --window 'title:^New Form' --find close --wait >/dev/null 2>&1
      check "Qt widgets: click --find close closes Designer's New Form dialog" until_ok 5 \
        bash -c "! '$CLI' windows -b '$B' | grep -q 'New Form'"
      out=$(ob tree -b "$B" --window 'title:^Qt Widgets Designer$' 2>&1)
      check_match "...a dock's contents under its title, not at 0,0 (finding 244)" \
        $'\n *panel "Widget Box" @0,([0-9]+) [0-9x]+\n *frame @0,[1-9][0-9]* ' $'\n'"$out"
      out=$(ob click -b "$B" --window 'title:^Qt Widgets Designer$' --find close 2>&1); rc=$?
      check_eq "...its docks' Close buttons: exit 2, each with its dock" "2 yes" \
        "$rc $(grep -q '1: panel "Widget Box" > button "Close"' <<<"$out" && echo yes || echo "no: $out")"
    else no "designer6's New Form dialog opens" "it did not"; fi
  else
    skip "click --find in Qt widgets and a dock" "no designer6 (qt6-tools)"
  fi
  check "down" ob down "$B"
}

# tree --layer (#254, finding 384): which layer SEL names, and the hint that tells two frames of one
# pid and size apart (the launcher over the wallpaper: the one with the keyboard), with Hyprland's
# keyboard answer and the box stubbed.
t_unit_tree_layer() {
  local J out rc
  J='{"DP-1": {"levels": {"0": [{"address": "0xa", "namespace": "omarchy-background", "pid": 7, "x": 0, "y": 0, "w": 1920, "h": 1080}],
      "1": [], "2": [{"address": "0xb", "namespace": "omarchy-bar", "pid": 7, "x": 0, "y": 0, "w": 42, "h": 1080},
                     {"address": "0xm", "namespace": "omarchy-menu", "pid": 7, "x": 0, "y": 0, "w": 1, "h": 1}],
      "3": [{"address": "0xc", "namespace": "omarchy-launcher", "pid": 7, "x": 0, "y": 0, "w": 1920, "h": 1080}]}},
    "DP-2": {"levels": {"2": [{"address": "0xd", "namespace": "omarchy-bar", "pid": 7, "x": 1920, "y": 0, "w": 42, "h": 1080},
      {"address": "0xe", "namespace": "solo", "pid": 9, "x": 2100, "y": 300, "w": 200, "h": 60}]}}}'
  out=$(probe layer_select "$J" omarchy-background 2>&1); rc=$?
  check_eq "a namespace: its layer, with its level and monitor" \
    '0 {"namespace":"omarchy-background","address":"0xa","pid":7,"x":0,"y":0,"w":1920,"h":1080,"monitor":"DP-1","level":"background"}' "$rc $out"
  out=$(probe layer_select "$J" omarchy-bar 2>&1); rc=$?
  check_eq "a namespace on two monitors: exit 2" 2 "$rc"
  check_match "...both listed, to name one by its address" "omarchy-bar matches 2 layers: name one by its address.*0xb .* on DP-1 .*0xd .* at 1920,0 on DP-2" "$(tr '\n' ' ' <<<"$out")"
  check_eq "address:0xd" "0xd DP-2" "$(probe layer_select "$J" address:0xd | jq -r '"\(.address) \(.monitor)"')"
  check_eq "pid:9" solo "$(probe layer_select "$J" pid:9 | jq -r .namespace)"
  out=$(probe layer_select "$J" omarchy-menu 2>&1); rc=$?
  check_eq "a layer mapped at 1x1 only (a closed menu): exit 1" 1 "$rc"
  check_match "...said so" "layer omarchy-menu is mapped at 1x1, not drawn" "$out"
  out=$(probe layer_select "$J" nope 2>&1); rc=$?
  check_eq "no such layer: exit 2" 2 "$rc"
  check_match "...the box's layers listed" '"solo"  pid 9  top 200x60 at 2100,300 on DP-2' "$out"
  # (layer_read: what it asks the box's tools/tree, the keyboard's layers given: layer.rs
  # layer_argv_as_bash; #324 wave 6-suite.)
  # #282: AccessKit's requirement on at-spi2-core 2.61+ is named where an agent reads about tree.
  out=$(ob help tree --long | tr '\n' ' ')
  check_match "help tree --long names AccessKit's requirement (accesskit_unix 0.22+, eframe 0.37+, #282)" \
    "accesskit_unix 0.22\+ \(eframe 0.37\+\) with at-spi2-core 2.61\+" "$out"
  check_fails "...and no longer says tree gives older AccessKit its property" grep -q "ScreenReaderEnabled, which older" <<<"$out"
  check_match "the skill reference names it too" "accesskit_unix 0.22\+ \(eframe 0.37\+\) on at-spi2-core 2.61\+" \
    "$(tr '\n' ' ' < "$ROOT/skill/reference.md" | tr -s ' ')"
}

# tree --layer (#254, finding 384) in a box: a Quickshell config with a named button in a layer and
# a layer with no roles, read through the box's AT-SPI bus; a click at the button's middle (the
# screen's coordinates) lands; the shell's own bar; the launcher told from the wallpaper (both
# full-screen, one pid) by the keyboard; two layers of one size that cannot be told apart.
t_tree_layer() {
  local B=$P-tl D out rc v x y mid
  up_ok "$B" --net isolated "${OM[@]}" || { no "up" "$UP_OUT"; return; }
  D=$(ob path -b "$B")
  out=$(ob tree -b "$B" 2>&1); rc=$?
  check_eq "tree with no window at all: exit 2" 2 "$rc"
  check_match "...pointing at --layer" "the box has no window; the shell's bar, panels and menus are layers: tree --layer NAMESPACE" "$out"
  check_eq "--window and --layer: exit 2" 2 "$(ob tree -b "$B" --window x --layer y >/dev/null 2>&1; echo $?)"
  out=$(ob tree -b "$B" --layer nope 2>&1); rc=$?
  check_eq "--layer naming no layer: exit 2" 2 "$rc"
  check_match "...the box's layers listed" '"omarchy-bar"  pid [0-9]+  top ' "$out"
  v=$(ob ls --json | jq -r --arg b "$B" '.[] | select(.name == $b) | .quickshell_version // ""')
  if ! [[ $v =~ Quickshell\ 0\.([4-9]|3\.([2-9]|[1-9][0-9])) ]] && ! [[ $v =~ Quickshell\ [1-9] ]]; then
    out=$(ob tree -b "$B" --layer omarchy-bar 2>&1); rc=$?
    check_eq "the bar on a Quickshell before 0.3.2 ($v): exit 1" 1 "$rc"
    check_match "...no tree, which releases have one" "no accessibility tree.*Quickshell publishes its windows' accessibility trees from 0.3.2 on" "$(tr '\n' ' ' <<<"$out")"
    skip "tree --layer on a stub panel" "the installed Quickshell publishes no tree ($v)"
    ob down "$B" >/dev/null; return
  fi
  out=$(ob tree -b "$B" --layer omarchy-bar 2>&1); rc=$?
  check_eq "the shell's bar ($v): exit 1" 1 "$rc"
  check_match "...it publishes no accessible items (Omarchy's QML sets no roles)" \
    'tree: layer "omarchy-bar" \(pid [0-9]+, [0-9]+x[0-9]+ at [0-9]+,[0-9]+\): the layer publishes no accessible items \(nothing in it sets an Accessible role\)' "$out"
  cat > "$D/home/t254.qml" <<'QML'
import QtQuick
import Quickshell
import Quickshell.Wayland
ShellRoot {
  PanelWindow {
    anchors { top: true; left: true }
    margins { top: 200; left: 300 }
    implicitWidth: 400; implicitHeight: 120
    WlrLayershell.namespace: "t254"
    color: "#202020"
    Rectangle {
      id: btn
      x: 150; y: 40; width: 120; height: 50; color: "#4060c0"
      property int hits: 0
      Accessible.role: Accessible.Button
      Accessible.name: ["a named button", "clicked button", "clicked again"][Math.min(hits, 2)]
      MouseArea { anchors.fill: parent; onClicked: btn.hits++ }
    }
  }
  PanelWindow {
    anchors { bottom: true; right: true }
    implicitWidth: 200; implicitHeight: 60
    WlrLayershell.namespace: "t254-empty"
    Text { text: "no roles here" }
  }
}
QML
  ob run -b "$B" -d -q -- qs -p /home/sbx/t254.qml >/dev/null 2>&1
  if ! ob wait -b "$B" layer t254 >/dev/null 2>&1 || ! ob wait -b "$B" layer t254-empty >/dev/null 2>&1; then
    no "the stub's layers map" "no t254 / t254-empty layer"; ob down "$B" >/dev/null; return
  fi
  read -r x y < <(ob hyprctl -b "$B" -j layers | jq -r '[.. | objects | select(.namespace? == "t254")][0] | "\(.x) \(.y)"')
  out=$(ob tree -b "$B" --layer t254 2>&1); rc=$?
  check_eq "tree --layer: the frame and its named button, in the screen's coordinates (the layer at $x,$y)" \
    "0 frame @$x,$y 400x120"$'\n'"  button \"a named button\" @$((x + 150)),$((y + 40)) 120x50" "$rc $out"
  check_eq "...--json the same bounds" "$((x + 150)) $((y + 40)) 120 50" \
    "$(ob tree -b "$B" --layer t254 --json | jq -r '.[] | select(.role == "button") | "\(.x) \(.y) \(.w) \(.h)"')"
  out=$(ob tree -b "$B" --layer t254 --find 'named button' 2>&1)
  check_eq "...--find, one line" "button \"a named button\" @$((x + 150)),$((y + 40)) 120x50" "$out"
  if mid=$(tree_mid "$out"); then
    # shellcheck disable=SC2086 # X Y
    ob click -b "$B" $mid >/dev/null 2>&1
    check "...a plain click at its middle ($mid) lands on it" until_ok 5 \
      bash -c "'$CLI' tree -b '$B' --layer t254 --find clicked | grep -q '^button \"clicked button\"'"
  else no "...a click at its middle lands" "no bounds in [$out]"; fi
  out=$(ob click -b "$B" --layer t254 --find 'clicked button' 2>&1)
  check_match "...click --layer --find: its line, at its middle on the screen" \
    "^omabox: click: button \"clicked button\" @$((x + 150)),$((y + 40)) 120x50: at $((x + 210)),$((y + 65))\$" "$out"
  check "...it lands on it" until_ok 5 \
    bash -c "'$CLI' tree -b '$B' --layer t254 --find again | grep -q '^button \"clicked again\"'"
  check_eq "...--find matching nothing: exit 1" 1 "$(ob tree -b "$B" --layer t254 --find zzz >/dev/null 2>&1; echo $?)"
  out=$(ob tree -b "$B" --layer t254-empty 2>&1); rc=$?
  check_eq "a layer whose items set no role: exit 1" 1 "$rc"
  check_match "...said so, not as no tree" "the layer publishes no accessible items" "$out"
  check_eq "pid:PID with two layers: exit 2" 2 \
    "$(ob tree -b "$B" --layer "pid:$(ob hyprctl -b "$B" -j layers | jq -r '[.. | objects | select(.namespace? == "t254")][0].pid')" >/dev/null 2>&1; echo $?)"
  # Two layers of one size in one process, each with an item: their frames cannot be told apart. (Two
  # empty ones publish nothing whichever is the layer's: said so, finding 547.)
  cat > "$D/home/t254b.qml" <<'QML'
import QtQuick
import Quickshell
import Quickshell.Wayland
ShellRoot {
  PanelWindow { anchors { bottom: true; left: true } implicitWidth: 100; implicitHeight: 100; WlrLayershell.namespace: "t254-a"
    Rectangle { width: 50; height: 50; Accessible.role: Accessible.Button; Accessible.name: "a" } }
  PanelWindow { anchors { top: true; right: true } implicitWidth: 100; implicitHeight: 100; WlrLayershell.namespace: "t254-b"
    Rectangle { width: 50; height: 50; Accessible.role: Accessible.Button; Accessible.name: "b" } }
  PanelWindow { anchors { bottom: true; right: true } implicitWidth: 80; implicitHeight: 80; WlrLayershell.namespace: "t254-c" }
  PanelWindow { anchors { top: true; left: true } implicitWidth: 80; implicitHeight: 80; WlrLayershell.namespace: "t254-d" }
}
QML
  ob run -b "$B" -d -q -- qs -p /home/sbx/t254b.qml >/dev/null 2>&1
  if ob wait -b "$B" layer t254-a >/dev/null 2>&1 && ob wait -b "$B" layer t254-b >/dev/null 2>&1; then
    out=$(ob tree -b "$B" --layer t254-a 2>&1); rc=$?
    check_eq "two layers of one process and size: exit 1" 1 "$rc"
    check_match "...said so, both listed" "2 of its application's \(pid [0-9]+\) windows are 100x100.*cannot be told.*\"t254-a\".*\"t254-b\"" "$(tr '\n' ' ' <<<"$out")"
    ob wait -b "$B" layer t254-c >/dev/null 2>&1; ob wait -b "$B" layer t254-d >/dev/null 2>&1
    out=$(ob tree -b "$B" --layer t254-c 2>&1); rc=$?
    check_eq "...two of one size with nothing in either: the layer publishes nothing, exit 1 (finding 547)" \
      "1 yes" "$rc $(grep -q 'the layer publishes no accessible items' <<<"$out" && echo yes || echo "no: $out")"
  else no "two layers of one size map" "no t254-a / t254-b layer"; fi
  # #315: Omarchy 4.5's bar popups are a full-screen overlay beside the full-screen wallpaper (one
  # pid) and take the keyboard on demand, not exclusively: the panel is the one of them that can
  # hold it, so its frame is the active one.
  cat > "$D/home/t315.qml" <<'QML'
import QtQuick
import Quickshell
import Quickshell.Wayland
ShellRoot {
  PanelWindow { anchors { top: true; bottom: true; left: true; right: true }
    WlrLayershell.namespace: "t315-wall"; WlrLayershell.layer: WlrLayer.Background; exclusionMode: ExclusionMode.Ignore }
  PanelWindow { anchors { top: true; bottom: true; left: true; right: true }
    WlrLayershell.namespace: "t315-panel"; WlrLayershell.layer: WlrLayer.Overlay; exclusionMode: ExclusionMode.Ignore
    WlrLayershell.keyboardFocus: WlrKeyboardFocus.OnDemand; color: "transparent"
    Rectangle { x: 600; y: 300; width: 80; height: 40; Accessible.role: Accessible.Button; Accessible.name: "in the panel" } }
}
QML
  ob run -b "$B" -d -q -- qs -p /home/sbx/t315.qml >/dev/null 2>&1
  if ob wait -b "$B" layer t315-panel >/dev/null 2>&1 && ob wait -b "$B" layer t315-wall >/dev/null 2>&1; then
    out=$(ob tree -b "$B" --layer t315-panel 2>&1); rc=$?
    check_eq "a full-screen panel taking the keyboard on demand, beside a wallpaper of its size (#315): its tree" \
      "0 button \"in the panel\" @600,300 80x40" "$rc $(grep -o 'button.*' <<<"$out")"
    out=$(ob tree -b "$B" --layer t315-wall 2>&1); rc=$?
    check_eq "...and the wallpaper's: it publishes nothing, exit 1" \
      "1 yes" "$rc $(grep -q 'the layer publishes no accessible items' <<<"$out" && echo yes || echo "no: $out")"
  else no "a full-screen panel and wallpaper map" "no t315-panel / t315-wall layer"; fi
  # The launcher and the wallpaper: one pid, both 1920x1080; the launcher holds the keyboard.
  ob keys -b "$B" super+space >/dev/null
  if ob wait -b "$B" layer omarchy-menu >/dev/null 2>&1; then
    out=$(ob tree -b "$B" --layer omarchy-menu --all 2>&1); rc=$?
    # 4.5's launcher has a search field first, focused (#311); 4.0's starts with its rows.
    if omarchy45; then
      check_match "the launcher (the size of the wallpaper): its frame, the active one, its search field, and its rows" \
        $'^frame \\[active\\] @0,0 1920x1080\n  text \\[focused editable\\][^\n]*\n  filler @' "$out"
    else   # omarchy<4.5
      check_match "the launcher (the size of the wallpaper): its frame, the active one, and its rows" $'^frame \\[active\\] @0,0 1920x1080\n  filler @' "$out"
    fi
    check_eq "...exit 0" 0 "$rc"
    out=$(ob tree -b "$B" --layer omarchy-background 2>&1)
    check_match "...and the wallpaper's frame, not the launcher's" "layer \"omarchy-background\".*publishes no accessible items" "$out"
    ob keys -b "$B" Escape >/dev/null
  else no "the launcher opens (super+space)" "no omarchy-menu layer"; fi
  ob down "$B" >/dev/null
}

t_systemd() {
  local B=$P-sd
  check "up --systemd --net isolated" ob up "$B" --systemd --net isolated
  check_box_safety "$B"
  check_match "user manager up" '^(running|degraded)$' "$(ob run -b "$B" -- systemctl --user is-system-running 2>&1)"
  check_eq "only the document portal may fail" "" \
    "$(ob run -b "$B" -- systemctl --user --failed --no-legend --plain | awk '{print $1}' | grep -v '^xdg-document-portal.service$')"
  check "manager has the session environment" bash -c "'$CLI' run -b '$B' -- systemctl --user show-environment | grep -q '^WAYLAND_DISPLAY='"
  check "...with the box's name, for what its units start (#172)" bash -c "'$CLI' run -b '$B' -- systemctl --user show-environment | grep -qx 'OMABOX_BOX=$B'"
  ob run -b "$B" -- systemd-run --user --on-active=1 --timer-property=AccuracySec=100ms --unit t1 touch /tmp/fired >/dev/null 2>&1
  check "a timer fires" until_ok 10 ob run -b "$B" -- test -e /tmp/fired
  check "notify-send works" ob run -b "$B" -- notify-send omabox-test
  # The browser bind's shape with a real user manager: omabox's uwsm-app detaches the app, and a unit
  # around it ended with the app inside (finding 131).
  ob run -b "$B" -- systemd-run --user --quiet --collect --unit=omarchy-browser-1 uwsm-app -- foot --app-id=omabox.sdrun sleep 60 >/dev/null
  check "systemd-run --user uwsm-app -- APP: the app stays" until_ok 10 \
    bash -c "'$CLI' hyprctl -b '$B' -j clients | jq -e '.[] | select(.class == \"omabox.sdrun\")'"
  dbus_user_app "$B"
  # #234: a unit's output (StandardOutput=journal, the stream socket) in the box's journal log.
  ob run -b "$B" -- systemd-run --user --quiet --unit omabox-say echo omabox unit output >/dev/null 2>&1
  check "a unit's output in omabox log journal (#234)" until_ok 10 \
    bash -c "'$CLI' log -b '$B' journal --grep 'omabox unit output$' | grep -q ."
  local scope; scope=$(systemctl --user list-units --no-legend "omabox-$B-*" | awk '{print $1}')
  check_match "host scope exists" "^omabox-$B-" "$scope"
  check "down" ob down "$B"
  check "host scope gone" until_ok 5 bash -c "[ -z \"\$(systemctl --user list-units --no-legend 'omabox-$B-*')\" ]"
}

# A box must not be able to aim the host-side tools elsewhere (finding 63): its runtime dir is its
# own to write, so a socket swapped for a symlink to another compositor's must not be followed.
t_hostile() {
  local A=$P-hostA B=$P-hostB
  check "up A 1024x768" ob up "$A" --size 1024x768 --no-shell
  check "up B 800x600" ob up "$B" --size 800x600 --no-shell
  local DB; DB=$(ob path -b "$B")
  # (env's path, taken before A tampers with its runtime dir: finding 493)
  local ea; ea=$(ob env -b "$A" | sed -n 's/^export WAYLAND_DISPLAY=//p')
  ob run -b "$A" -- sh -c "mv \$XDG_RUNTIME_DIR/wayland-1 \$XDG_RUNTIME_DIR/wayland-orig && ln -s '$DB/run/wayland-1' \$XDG_RUNTIME_DIR/wayland-1" >/dev/null 2>&1
  local out; out=$(ob shot -b "$A" -o "$TMP/hostile.png" 2>&1) || true
  if [ -s "$TMP/hostile.png" ]; then
    check_fails "shot does not follow the box's symlink to another screen" grep -q '800 x 600' <<<"$(file "$TMP/hostile.png")"
  else
    # (#110) A failure counts only as the one expected: grim could not reach that display.
    check_match "shot does not follow the box's symlink to another screen (it failed: no display)" \
      "grim failed: .*(connect|display)" "$out"
  fi
  check "...and the honest box's shot still works" ob shot -b "$B" -o "$TMP/honest.png"
  # env: a host tool given its path reaches the box's own display, never what the box put in its
  # socket's place (a link that leads to the desktop's, here B's): a hard link in the box dir (finding
  # 493; bash printed the run dir's path, which led to B's).
  check_match "env refuses a box whose Wayland socket is a link now" "its Wayland socket \(run/wayland-1\) is not a socket: refused" "$(ob env -b "$A" 2>&1)"
  if command -v grim >/dev/null; then
    rm -f "$TMP/hostile-env.png"; WAYLAND_DISPLAY=$ea grim -t png "$TMP/hostile-env.png" 2>/dev/null
    check_match "...the path it gave before still leads to that box's own display" '1024 x 768' "$(file "$TMP/hostile-env.png" 2>&1)"
  else skip "env's path and a host Wayland client" "no grim"; fi
  # a tampered omabox.env: a WAYLAND_DISPLAY with a path in it is refused
  ob run -b "$A" -- sh -c 'tr "\0" "\n" < $XDG_RUNTIME_DIR/omabox.env | sed "s|^WAYLAND_DISPLAY=.*|WAYLAND_DISPLAY=../../../run/user/1000/wayland-1|" | tr "\n" "\0" > $XDG_RUNTIME_DIR/e && mv $XDG_RUNTIME_DIR/e $XDG_RUNTIME_DIR/omabox.env'
  check_match "a path in WAYLAND_DISPLAY is refused" "no WAYLAND_DISPLAY" "$(ob hyprctl -b "$A" monitors 2>&1)"
  check "down both" ob down "$A" "$B"
}

# Two `up`s of one name at once: one box, and nothing left behind by `down` (finding 63).
t_race() {
  local B=$P-race
  ob up "$B" --no-shell >/dev/null 2>&1 & local a=$!
  ob up "$B" --no-shell >/dev/null 2>&1 & local b=$!
  wait "$a"; wait "$b"
  # One bwrap is two processes (its monitor, and the box's PID 1), under one pasta. Anchored: pasta's
  # own command line holds bwrap's too.
  check_eq "one box" 2 "$(pgrep -fc "^bwrap .*--bind $XDG_RUNTIME_DIR/omabox/$B/run " || true)"
  check_eq "...behind one pasta" 1 "$(pgrep -fc "^pasta .* -P $XDG_RUNTIME_DIR/omabox/$B/pasta\.pid " || true)"
  check "down" ob down "$B"
  check "nothing of it left running" until_ok 5 none_running "$B"
  # An up holds the name's lock a moment before it makes the box dir (finding 147): a down then waits
  # for it, not "no box" while the box comes up behind it. The suite holds the lock, standing in for it.
  local lk out; exec {lk}>"$XDG_RUNTIME_DIR/omabox/.lock-$B"; flock "$lk"
  ob down "$B" > "$TMP/race-down" 2>&1 & a=$!
  until_ok 5 grep -q "waiting for its up" "$TMP/race-down" >/dev/null; out=$(cat "$TMP/race-down")
  flock -u "$lk"; exec {lk}>&-; wait "$a"
  check_match "a down while an up holds the lock, before its box dir, waits for it" "waiting for its up" "$out"
  check_match "...then says no box when that up made none" "no box '$B'" "$(cat "$TMP/race-down")"
  # Earlier still, before the up has the lock: the down finds nothing, and the up cancels itself.
  local C=$P-race2 rc
  ob up "$C" --no-shell > "$TMP/race-up" 2>&1 & a=$!
  ob down "$C" >/dev/null 2>&1; wait "$a"; rc=$?
  if [ "$rc" = 0 ]; then
    check_eq "a down while its up starts: the box is gone (the down waited for it)" "" "$(ob ls --json | jq -r --arg n "$C" '.[] | select(.name == $n) | .name')"
  else
    check_match "a down while its up starts: the up says it was cancelled" "cancelled: omabox down $C came while it was starting" "$(cat "$TMP/race-up")"
  fi
  check "...nothing of it running" until_ok 5 none_running "$C"
  check "a down before an up does not cancel it" ob up "$C" --no-shell
  check "...down" ob down "$C"
  # A down from another pid namespace (#404): its pids say nothing of the up's, and an up made first
  # but 6 ms slower to its first line (busy, not asleep) than the whole down was taken for one made
  # after it by the calls' times: the box stayed up (at 24d53d6, 6 in 6). Three goes, each in one
  # 10 ms tick or not; either way the up must not outlast the down.
  local i e
  # shellcheck disable=SC2329 # run in the background below
  spin_up() { e=$((${EPOCHREALTIME//[!0-9]/} + 6000)); while ((${EPOCHREALTIME//[!0-9]/} < e)); do :; done; exec "$CLI" up "$1" --no-shell; }
  for i in 1 2 3; do
    C=$P-race3$i
    spin_up "$C" > "$TMP/race-up" 2>&1 & a=$!
    unshare -Upf --map-current-user --mount-proc --propagation slave "$CLI" down "$C" >/dev/null 2>&1
    rc=0; wait "$a" || rc=$?
    if [ "$rc" = 0 ]; then
      check_eq "a down of another pid namespace while its up starts ($i): the box is gone" "" "$(ob ls --json | jq -r --arg n "$C" '.[] | select(.name == $n) | .name')"
    else
      check_match "a down of another pid namespace while its up starts ($i): the up says it was cancelled" "cancelled: omabox down $C came while it was starting" "$(cat "$TMP/race-up")"
    fi
    ob down "$C" >/dev/null 2>&1
  done
  # ...and one before an up, in the same tick or the next, does not cancel it.
  C=$P-race4
  unshare -Upf --map-current-user --mount-proc --propagation slave "$CLI" down "$C" >/dev/null 2>&1
  check "a down of another pid namespace before an up does not cancel it" ob up "$C" --no-shell
  check "...down" ob down "$C"
  # A pid namespace of its own with the host's /proc (no --mount-proc): /proc/<its pid> is another
  # process, /proc/1 the host's init. A down there took init's start for its own (a marker older than
  # any up), and an up there took it for its own, so any down in 10 minutes cancelled it (#404).
  C=$P-race5
  local me; me=$(cut -d' ' -f22 "/proc/$BASHPID/stat")
  unshare -Upf --map-current-user "$CLI" down "$C" >/dev/null 2>&1
  local dt; dt=$(head -n1 "$XDG_RUNTIME_DIR/omabox/.down-$C" | cut -d' ' -f1)
  check "a down in a pid namespace with the host's /proc: its own start in its marker ($dt, this shell's $me)" test "${dt:-0}" -ge "$me"
  ob down "$C" >/dev/null 2>&1
  out=$(timeout 60 unshare -Upf --map-current-user "$CLI" up "$C" --no-shell 2>&1)
  check_fails "...an up there, after that down: not cancelled by it" grep -q "cancelled" <<<"$out"
  ob down "$C" >/dev/null 2>&1
}

# A failed `up` does not leave a box running unseen (finding 63): the box is killed, its dir kept for
# the logs, `ls` shows it dead, `down` clears it.
t_failed_up() {
  local B=$P-fail
  local out
  # Disable the shell inside the box while up still expects it. A one-second timeout alone can pass
  # on a fast machine, so it does not reliably exercise failed-start cleanup.
  if out=$(env OMABOX_READY_TIMEOUT=2 "$CLI" up "$B" --env OMABOX_SHELL=0 2>&1); then
    no "up fails when the expected shell never starts" "$out"
  else
    ok "up fails when the expected shell never starts"
  fi
  # kill_box waits for PID 1 (up to 10 s, saying so past that): a failed up returns with its box gone.
  # Its own message is in the evidence when not (#86). (This passed on the old trap too, #91:
  # ready.rs kill_box_ends_pid1_and_pasta is what guards finding 157's fix.)
  check_eq "...and returns with the box dead (up said: ${out//$'\n'/ | })" dead \
    "$(ob ls --json | jq -r --arg n "$B" '.[] | select(.name == $n) | .state')"
  # The namespace and bwrap parent can take a moment to exit after the failed command returns.
  # shellcheck disable=SC2329 # called through until_ok
  failed_box_dead() { [ "$(ob ls --json | jq -r --arg n "$B" '.[] | select(.name == $n) | .state')" = dead ]; }
  # shellcheck disable=SC2329 # called through until_ok
  failed_box_processes_gone() { [ "$(pgrep -fc "bwrap .*--bind $XDG_RUNTIME_DIR/omabox/$B/run " || true)" = 0 ]; }
  check "the box becomes dead, not running" until_ok 10 failed_box_dead
  check "nothing of it remains running" until_ok 10 failed_box_processes_gone
  check "down clears it" ob down "$B"
  # A throwaway that fails the same way keeps its logs outside the box dir its own `down` removes, and
  # says where (finding 167). The suite's own state dir: never the user's failed-runs.
  local repo st=$TMP/state-fr kept; repo=$(tmp_repo fr)
  out=$(cd "$repo" && exec env -u OMABOX XDG_STATE_HOME="$st" OMABOX_READY_TIMEOUT=2 "$CLI" run --env OMABOX_SHELL=0 -- true 2>&1) &&
    no "a throwaway whose up fails fails" "$out"
  check_match "a failed throwaway says where its logs are kept" "logs are kept in $st/omabox/failed-runs/$P-fr-run[0-9]+-[0-9]{8}-[0-9]{6}$" "$out"
  kept=${out##*logs are kept in }
  check "...a dir with its Hyprland log or box.log" bash -c '[ -f "$1/hyprland.log" ] || [ -f "$1/box.log" ]' _ "$kept"
  check_eq "...and no box of it is left" "" "$(ob ls --json | jq -r --arg p "$P-fr-run" '.[] | select(.name | startswith($p)) | .name')"
  # (Past 10 kept dirs the oldest go, and only dirs a box name can have: run.rs
  # keep_run_logs_keeps_ten; #324 wave 6-suite.)
  rm -rf "$st"
}

# #396 (finding 568): a box whose labwc cannot render on its GPU says why, not only "died while
# starting". A VM's virtio-gpu without virgl renders in software only, which wlroots refuses; no EGL
# vendor and no Vulkan driver at all fail the same way on any GPU (here): labwc gets no renderer of
# the GPU's, goes on with pixman, and the box's Hyprland aborts (CBackend::create() failed!).
t_up_software() {
  local B=$P-soft out
  out=$(OMABOX_READY_TIMEOUT=10 "$CLI" up "$B" --no-shell --env __EGL_VENDOR_LIBRARY_FILENAMES=/nonexistent.json \
    --env VK_ICD_FILENAMES=/nonexistent.json 2>&1) && no "up with no EGL for its GPU fails" "$out"
  check_match "a box with no EGL for its GPU says why, naming its node" \
    "box '$B' died while starting \\(a box needs GPU rendering: labwc found no EGL on /dev/dri/renderD[0-9]+[;)]" "$out"
  check_match "...and where its logs are, as before" \
    "\\); logs: $XDG_RUNTIME_DIR/omabox/$B/home/\\*\\.log $XDG_RUNTIME_DIR/omabox/$B/box\\.log$" "$out"
  ob down "$B" >/dev/null 2>&1
}

# An up that fails before box.json leaves no half-made dir that ls and down --all would not see
# (finding 163). /dev/dri/card9 is only a path render_node refuses (not a render node): never bound.
t_up_aborted() {
  local B=$P-abort S=$P-abs out
  out=$(OMABOX_RENDER_NODE=/dev/dri/card9 "$CLI" up "$B" --no-shell 2>&1) && no "up with no usable render node fails" "$out"
  check_eq "up with no usable render node fails, saying so once" "omabox: no usable GPU render node (/dev/dri/renderD*); set OMABOX_RENDER_NODE" "$out"
  check_fails "...and leaves no box dir" test -e "$XDG_RUNTIME_DIR/omabox/$B"
  check_fails "...nor a box HOME" test -e "${XDG_CACHE_HOME:-$HOME/.cache}/omabox/$B"
  check_eq "...nor a box ls lists" "" "$(ob ls --json | jq -r --arg n "$B" '.[] | select(.name == $n) | .name')"
  # A failure after the dir is made (a save cp cannot read) is cleared by up's EXIT trap.
  mkdir -p "$TMP/data/omabox/saves/$S/home/locked" && chmod 700 "$TMP/data/omabox/saves"
  chmod 000 "$TMP/data/omabox/saves/$S/home/locked"
  check_match "up --from a save it cannot copy fails" "could not copy save '$S'" "$(sv up "$B" --no-shell --from "$S" 2>&1)"
  chmod 700 "$TMP/data/omabox/saves/$S/home/locked"
  check_fails "...and leaves no box dir" test -e "$XDG_RUNTIME_DIR/omabox/$B"
  check_fails "...nor a box HOME" test -e "${XDG_CACHE_HOME:-$HOME/.cache}/omabox/$B"
}

# An up cut short by INT, TERM or HUP after its box started takes the box down (finding 434): bash
# 5.3 runs the EXIT trap of a shell a signal ends with $? 0, so up's `[ $? = 0 ] ||` left the box
# running, unseen, its `starting` file kept. Here while up waits for the box's shell (wait_ready),
# each signal to up's group and to up alone (an INT to up alone used to let it go on), INT, TERM and
# HUP at their defaults (a test run in the background ignores INT): bash's code, and the box gone:
# not up, not listed dead, no dir, `starting` or reaper left (#388: a signal is a stop, not a failure
# with logs to keep).
t_up_signals() {
  local r=$TMP/upsig B i=0 sig how rc bd st
  mkdir -p "$r"; rp_sig_write "$r/rp-sig"
  for sig in TERM HUP INT; do
    for how in group alone; do
      i=$((i + 1)) B=$P-usig$i
      bd=$(ob path "$B")
      local s=$sig; [ "$how" = alone ] || s=group-$sig
      rc=0; RP_DEADLINE=90 "$r/rp-sig" "$s" "$bd/run/omabox.env" env --default-signal=INT,TERM,HUP "$CLI" up "$B" --net isolated >/dev/null 2>"$r/err.$i" || rc=$?
      if grep -q "box '$B' up (" "$r/err.$i"; then
        skip "up and $how $sig while it waits for the shell" "up was done before the signal (load)"; ob down "$B" >/dev/null 2>&1; continue
      fi
      check_eq "up and $how $sig while it waits for the shell: bash's code" "$(( 128 + $(kill -l "$sig") ))" "$rc"
      st=$(ob ls --json 2>/dev/null | jq -r --arg n "$B" 'first(.[] | select(.name == $n) | .state) // "gone"')
      check_eq "...the box gone, not left dead (#388)" gone "$st"
      check_fails "...no box dir left" test -e "$bd"
      check_eq "...no reaper left" "" "$(pgrep -f "_reap $B " | tr '\n' ' ')"
      ob down "$B" >/dev/null 2>&1
    done
  done
  # And at the other steps from the box dir on (finding 460, #356): while it seeds the HOME (the dir
  # just made), and once bwrap has started (its info file), each its signal's code and the box ended;
  # a dir with no box.json yet goes whole.
  local mark
  for mark in jobs-noted info.json; do
    for sig in HUP TERM; do
      for how in group alone; do
        i=$((i + 1)) B=$P-usig$i
        bd=$(ob path "$B")
        local s=$sig; [ "$how" = alone ] || s=group-$sig
        rc=0; RP_WAIT=0.05 RP_DEADLINE=90 "$r/rp-sig" "$s" "$bd/$mark" env --default-signal=INT,TERM,HUP "$CLI" up "$B" --net isolated >/dev/null 2>"$r/err.$i" || rc=$?
        if grep -q "box '$B' up (" "$r/err.$i"; then
          skip "up and $how $sig at $mark" "up was done before the signal (load)"; ob down "$B" >/dev/null 2>&1; continue
        fi
        check_eq "up and $how $sig at $mark: the signal's code" "$(( 128 + $(kill -l "$sig") ))" "$rc"
        st=$(ob ls --json 2>/dev/null | jq -r --arg n "$B" 'first(.[] | select(.name == $n) | .state) // "gone"')
        check_eq "...the box gone, not left dead (#388)" gone "$st"
        check_fails "...no box dir left" test -e "$bd"
        check_eq "...no reaper left" "" "$(pgrep -f "_reap $B " | tr '\n' ' ')"
        ob down "$B" >/dev/null 2>&1
      done
    done
  done
  # Between the launch's hand-off and the box's first pid (finding 460): the launcher held 2 s (the
  # suite's seam, OMABOX_TEST_LAUNCH_DELAY), the signal sent to up once it has handed the launch off.
  # The box comes up after the stop began: it is waited for and ended, none left once the hold is over.
  for sig in TERM HUP; do
    i=$((i + 1)) B=$P-usig$i
    bd=$(ob path "$B")
    rc=0; OMABOX_TEST_LAUNCH_DELAY=2 RP_WAIT=0.3 RP_DEADLINE=90 "$r/rp-sig" "$sig" "$bd/starting" env --default-signal=INT,TERM,HUP "$CLI" up "$B" --net isolated --no-shell >/dev/null 2>"$r/err.$i" || rc=$?
    check_eq "up and $sig after the launch's hand-off, before the box's pid: the signal's code" "$(( 128 + $(kill -l "$sig") ))" "$rc"
    sleep 4
    check_eq "...no box of it left running once the launcher's hold is over" "" "$(pgrep -f "pasta .* $bd/pasta\.pid" | tr '\n' ' ')"
    st=$(ob ls --json 2>/dev/null | jq -r --arg n "$B" 'first(.[] | select(.name == $n) | .state) // "gone"')
    check_eq "...the box gone, not left dead (#388)" gone "$st"
    check_fails "...no box dir left" test -e "$bd"
    ob down "$B" >/dev/null 2>&1
  done
}

# The same during `up --interactive --monitor`'s add (finding 434; finding 435's stopgap held it on
# the 1.0.1 line): in a box standing in for the host (finding 26), each signal once the add has
# recorded its monitor (omabox.monitors), to up's group (the add's subshell gets it too, and removes its output) and to up
# alone (the add finishes first): bash's code, the box not up, none of its windows left on the
# stand-in, no `starting` left.
t_up_signals_window() {
  local S=$P-usw
  up_ok "$S" --no-shell --net isolated || { no "up the stand-in" "$UP_OUT"; return; }
  local in=("$CLI" run -b "$S" -- "${GUARDED[@]}" "$CLI")
  if aq_unfixed "${in[@]}"; then skip "up -i --monitor and a signal" "the stand-in's aquamarine lacks the fix"; ob down "$S" >/dev/null; return; fi
  if ! "${in[@]}" --version 2>/dev/null | grep -q '^aquamarine: a private build, .*+appid'; then
    skip "up -i --monitor and a signal" "not omabox's aquamarine build with +appid (omabox setup --aquamarine)"; ob down "$S" >/dev/null; return
  fi
  local r=$TMP/upsigw sig how i=0 B bd rc out st
  mkdir -p "$r"; rp_sig_write "$r/rp-sig"
  # shellcheck disable=SC2329 # called through until_ok
  nowins() { [ "$(ob hyprctl -b "$S" -j clients | jq '[.[] | select(.class | startswith("aquamarine"))] | length')" = 0 ]; }
  for sig in TERM HUP INT; do
    for how in group alone; do
      i=$((i + 1)) B=usw$i
      bd=$("${in[@]}" path "$B")
      local s=$sig; [ "$how" = alone ] || s=group-$sig
      rc=0; out=$("$CLI" run -b "$S" -- "${GUARDED[@]}" env RP_DEADLINE=90 RP_WAIT=0.05 bash -c "$(cat "$r/rp-sig")" rp-sig "$s" "$bd/run/omabox.monitors" \
        env --default-signal=INT,TERM,HUP "$CLI" up "$B" --interactive --no-shell --monitor 800x600 2>&1 >/dev/null) || rc=$?
      if grep -q "box '$B' up (" <<<"$out"; then
        skip "up -i --monitor and $how $sig during its add" "up was done before the signal (load)"; "${in[@]}" down "$B" >/dev/null 2>&1; continue
      fi
      check_eq "up -i --monitor and $how $sig during its add: bash's code" "$(( 128 + $(kill -l "$sig") ))" "$rc"
      st=$("${in[@]}" ls --json 2>/dev/null | jq -r --arg n "$B" 'first(.[] | select(.name == $n) | .state) // "gone"')
      check "...the box not up ($st)" test "$st" != up
      check "...none of its windows left on the stand-in" until_ok 5 nowins
      check_fails "...no starting file left" "$CLI" run -b "$S" -- test -e "$bd/starting"
      "${in[@]}" down "$B" >/dev/null 2>&1
    done
  done
  ob down "$S" >/dev/null
}

# A plugin's settings in the desk's extensions/ that hold what looks like a key, token or password
# stay out of the box HOME (finding 458; --desk-shell's files had the check, extensions/ did not):
# said by name, never by value; what holds none, and a setting that only names one, go in as before.
t_extensions_secret() {
  local B=$P-exs d=$TMP/exs out e
  rm -rf "$d"; mkdir -p "$d/desk/extensions/plug/deep"
  printf '{"apiToken": "ghp_abcdefghijklmnopqrstuvwxyz0123"}\n' > "$d/desk/extensions/plug/settings.json"
  printf 'password = hunter2hunter2\n' > "$d/desk/extensions/plug/deep/creds.conf"
  # (a name tar's .[!.]* exclude lets through: two dots in front)
  printf '{"token": "ghp_zyxwvutsrqponmlkjihgfedcba9876"}\n' > "$d/desk/extensions/plug/..cfg"
  printf '{"maxTokens": 4, "tokenizer": "x"}\n' > "$d/desk/extensions/plug/ok.json"
  printf 'theme = dark\n' > "$d/desk/extensions/plain.conf"
  e=$XDG_RUNTIME_DIR/omabox/$B/home/.config/omarchy/extensions
  out=$(OMABOX_DESK_CONFIG=$d/desk ob up "$B" --no-shell --net isolated 2>&1) || { no "up" "$out"; return; }
  check_fails "a token in extensions/ is not seeded" test -e "$e/plug/settings.json"
  check_fails "...nor a password in a folder below" test -e "$e/plug/deep/creds.conf"
  check_fails "...nor a token in a file named ..cfg, which tar copies" test -e "$e/plug/..cfg"
  check_eq "...what holds none is" '{"maxTokens": 4, "tokenizer": "x"}|theme = dark' "$(cat "$e/plug/ok.json")|$(cat "$e/plain.conf")"
  check_match "...each said by name" "not seeded: extensions/plug/deep/creds.conf from $d/desk \(it holds what looks like a key, token or password\)" "$out"
  check_match "...the other too" "not seeded: extensions/plug/settings.json from $d/desk" "$out"
  check_fails "...its value never said" grep -q 'ghp_\|hunter2' <<<"$out"
  ob down "$B" >/dev/null 2>&1
}

# A box whose Hyprland died reads dead, not up (finding 63).
t_hyprland_dies() {
  local B=$P-hdie
  check "up" ob up "$B" --no-shell
  ob run -b "$B" -- pkill -KILL -x Hyprland >/dev/null 2>&1
  check "the box ends with its Hyprland" until_ok 10 bash -c "'$CLI' ls --json | jq -e '.[] | select(.name == \"$B\" and .state == \"dead\")'"
  ob down "$B" >/dev/null 2>&1
}

# #232: a Lua call that crashes the box's Hyprland (a Hyprland bug: two binds of one key, both unbound)
# is said as a crash with its signal, not "did not answer (hung?)": its socket closed before its pid
# went, and lua read the box as up. Under gdb --watch, it names the backtrace instead.
t_hyprland_crash() {
  local B=$P-hcrash out rc
  local crash='local a = hl.bind("F9", function() end, {}); local b = hl.bind("F9", function() end, {}); a:unbind(); b:unbind(); return "x"'
  check "up" ob up "$B" --no-shell --net isolated
  rc=0; out=$(timeout 30 "$CLI" lua -b "$B" "$crash" 2>&1) || rc=$?
  check_eq "lua that crashes Hyprland: exit 1" 1 "$rc"
  check_match "...said as a crash with its signal, and how to get a backtrace" \
    "^omabox: box '$B' went down: its Hyprland crashed \\(SIGSEGV\\) \\(a backtrace: .*omabox gdb --watch; boxes keep no core dumps; clear it with: omabox down $B\\)$" "$out"
  check_match "...a later call: dead, and why" "box '$B' is dead: its Hyprland crashed \\(SIGSEGV\\)" "$(ob lua -b "$B" 'return 1' 2>&1)"
  ob down "$B" >/dev/null 2>&1
  check "up again" ob up "$B" --no-shell --net isolated
  check "gdb --watch" ob gdb -b "$B" --watch
  rc=0; out=$(timeout 30 "$CLI" lua -b "$B" "$crash" 2>&1) || rc=$?
  check_eq "...under gdb --watch: exit 1" 1 "$rc"
  check_match "...a crash, its backtrace in the gdb log (held, or after)" \
    "^omabox: box '$B'( went down: its Hyprland crashed \\(SIGSEGV\\) \\(its backtrace|: its Hyprland crashed \\(SIGSEGV\\), held by gdb --watch).*omabox log -b $B gdb --crash" "$out"
  check "...which has it" until_ok 15 bash -c "'$CLI' log -b '$B' gdb --crash 2>/dev/null | grep -q 'received signal SIGSEGV'"
  ob down "$B" >/dev/null 2>&1
  # The moment between the crash and the box going down (finding 350), held open: labwc stopped, so
  # nothing reaps the Hyprland and the box stays up. ls: going, not hung.
  check "up again" ob up "$B" --no-shell --net isolated
  ob run -b "$B" -- pkill -STOP -x omabox-labwc
  timeout 30 "$CLI" lua -b "$B" "$crash" >/dev/null 2>&1
  check_eq "ls in the moment before a crashed box ends: going, not hung" going "$(ob ls | awk -v n="$B" '$1 == n { print $4 }')"
  check_eq "...ls --json too: hung false" "going false" "$(ob ls --json | jq -r --arg n "$B" '.[] | select(.name == $n) | "\(.state) \(.hung)"')"
  ob run -b "$B" -- pkill -CONT -x omabox-labwc
  check "...then dead, once labwc has reaped it" until_ok 10 bash -c "'$CLI' ls | awk -v n='$B' '\$1 == n { print \$4 }' | grep -qx dead"
  ob down "$B" >/dev/null 2>&1
  # An interactive box has no labwc: session.sh writes how its Hyprland ended (in a box standing in
  # for the host, finding 26).
  check "up (the stand-in host)" ob up "$B" --no-shell --net isolated
  local in=("$CLI" run -b "$B" -- "$CLI")
  if UP_OUT=$("${in[@]}" up hc --interactive --no-shell 2>&1); then
    rc=0; out=$(timeout 30 "${in[@]}" lua -b hc "$crash" 2>&1) || rc=$?
    check_match "an interactive box's crash: said with its signal" "^omabox: box 'hc' went down: its Hyprland crashed \\(SIGSEGV\\)" "$out"
    "${in[@]}" down hc >/dev/null 2>&1
  else no "up --interactive in the stand-in" "$UP_OUT"; fi
  ob down "$B" >/dev/null 2>&1
}

# A box whose pasta died (OOM, a killall) ends with it rather than stay up with no network (finding 89).
t_pasta_dies() {
  local B=$P-pdie
  check "up" ob up "$B" --no-shell
  kill -KILL "$(cat "$XDG_RUNTIME_DIR/omabox/$B/pasta.pid")"
  check "the box ends with its pasta" until_ok 10 bash -c "'$CLI' ls --json | jq -e '.[] | select(.name == \"$B\" and .state == \"dead\")'"
  check "down" ob down "$B"
}

# From another user namespace (a sandbox that makes its own) a live box's pid namespace is unreadable:
# box_pid read that as dead, and `up` cleared the live box's dir, orphaning the box. It stops instead.
t_other_userns() {
  local B=$P-uns D=$XDG_RUNTIME_DIR/omabox/$P-uns out rc created
  check "up" ob up "$B" --no-shell
  created=$(jq -r .created "$D/box.json")
  rc=0; out=$(unshare -Ur "$CLI" up "$B" 2>&1) || rc=$?
  check_match "up from another user namespace stops: it cannot tell" "cannot tell whether box '$B' is up from this user namespace" "$out"
  check_eq "...with an error" 1 "$rc"
  check_eq "...and the box is the same one, still up" "$created up" "$(jq -r .created "$D/box.json" 2>&1) $(ob ls --json | jq -r --arg n "$B" '.[] | select(.name == $n) | .state')"
  check "...which run still reaches" ob run -b "$B" -- true
  # A down from there (finding 473): refused the same way, the box left as it was.
  rc=0; out=$(unshare -Ur "$CLI" down "$B" 2>&1) || rc=$?
  check_eq "down from another user namespace stops too, with an error" "1 omabox: cannot tell whether box '$B' is up from this user namespace (a sandbox's?): run omabox outside it" "$rc $out"
  check_eq "...the box the same one, still up" "$created up" "$(jq -r .created "$D/box.json" 2>&1) $(ob ls --json | jq -r --arg n "$B" '.[] | select(.name == $n) | .state')"
  check "...which run still reaches" ob run -b "$B" -- true
  check "down" ob down "$B"
}

# A no_new_privs process (an agent's sandbox) cannot start pasta's bwrap (finding 89): a connected box
# started from one gets a network namespace with only a loopback, as a nested box does, and says so.
t_no_new_privs() {
  local B=$P-nnp D=$XDG_RUNTIME_DIR/omabox/$P-nnp before out rc ns
  before=$(grep -o '@/tmp/\.X11-unix/X[0-9]*' /proc/net/unix | LC_ALL=C sort -u)
  rc=0; out=$(setpriv --no-new-privs "$CLI" up "$B" --no-shell 2>&1) || rc=$?
  check_eq "up from a no_new_privs process" 0 "$rc"
  check_match "...says the box has no network, and why" "box '$B' has no network: .*no_new_privs" "$out"
  check_match "ls shows it with none" "$B +headless .* up +[^ ]+ +none " "$(ob ls)"
  check_fails "...and it has no pasta" test -e "$D/pasta.pid"
  ns=$(ob run -b "$B" -- readlink /proc/self/ns/net)
  if [[ $ns == net:* ]] && [ "$ns" != "$(readlink /proc/self/ns/net)" ]; then ok "the box has a network namespace of its own"
  else no "the box has a network namespace of its own" "box [$ns], host [$(readlink /proc/self/ns/net)]"; fi
  check_eq "no abstract X11 socket of the box's on the host" "" "$(new_x11 "$before" "$(jq -r .pidns "$D/box.json")")"
  check "run works in it from a no_new_privs process too" setpriv --no-new-privs "$CLI" run -b "$B" -- true
  check "down" ob down "$B"
}

# finding 256: `up` from a dir the user cannot read (an `su`/`runuser` that kept root's cwd): `find
# -delete` went back to it after, failed, and `up` ended with only find's message.
t_up_cwd_unreadable() {
  local B=$P-cwd d=$TMP/cwd-noread out
  mkdir -p "$d"
  out=$(cd "$d" && chmod 000 "$d" && "$CLI" up "$B" 2>&1); local rc=$?
  chmod 700 "$d"
  check_eq "up from a dir the user cannot read: exit 0" "0" "$rc"
  check_eq "...no find (or other) complaint about it" "" "$(grep -i -e 'find:' -e 'permission denied' <<<"$out")"
  check "...the box is up" bash -c "'$CLI' ls --json | jq -e --arg n '$B' '.[] | select(.name == \$n and .state == \"up\")' >/dev/null"
  # Every find runs from / there, not only up's (finding 262: shot's pruning of its references ended it).
  out=$(cd "$d" && chmod 000 "$d" && "$CLI" shot -b "$B" -o "$TMP/$B.png" 2>&1); rc=$?
  chmod 700 "$d"
  check_eq "shot from there: exit 0, no complaint" "0 " "$rc $(grep -i -e 'find:' -e 'permission denied' <<<"$out")"
  check "...the shot written" test -s "$TMP/$B.png"
  out=$(cd "$d" && chmod 000 "$d" && "$CLI" down "$B" 2>&1); rc=$?
  chmod 700 "$d"
  check_eq "down from there: exit 0, no complaint" "0 " "$rc $(grep -i -e 'find:' -e 'permission denied' <<<"$out")"
  ob down "$B" >/dev/null 2>&1 || true
}

# --no-shell is a bare compositor.
t_no_shell() {
  local B=$P-bare
  check "up --no-shell" ob up "$B" --no-shell
  check "no quickshell starts" holds 2 bash -c "! '$CLI' run -b '$B' -- pgrep -x quickshell"
  check "down" ob down "$B"
}

# finding 122 (nvidia-modprobe -c MINOR for a missing /dev/nvidiaN, -c 255 for /dev/nvidiactl, finding
# 254; what to run when still missing) and nvidia_card (finding 294): render.rs
# nvidia_node_asks_the_helper_as_bash, on a stand-in helper.
# finding 126 (issue #49): omabox setup makes a user's links, settings dir and guard; --remove undoes
# them, only links that still point here. In a temp HOME and XDG dirs: never the user's.
t_unit_setup() {
  local h=$TMP/$P-setup out
  mkdir -p "$h/.codex" "$h/.config/omarchy"
  echo '{"bar": {"layout": {"right": [{"id": "x.y"}]}}}' > "$h/.config/omarchy/shell.json"
  # (The XDG dirs too: the user's session sets them, and --remove deletes the aquamarine build there.)
  # omarchy and omarchy-shell are stand-ins: setup's widget step talks to the running shell (#397),
  # which is the real desktop's whatever HOME says. The shell's stand-in logs each call to
  # $h/shell.log and answers as $h/shell-mode says: none (no file) is no shell running; known, a
  # shell that lists the widget; unknown, one that lists it once a rescan has been asked and a list
  # made after it (a rescan returns before the scan is done); stuck, one a rescan does not change.
  local hst=$TMP/$P-setup-shell
  mkdir -p "$hst"
  printf '#!/bin/sh\necho "omarchy $*" >> "$HOME/shell.log"; exit 1\n' > "$hst/omarchy"
  cat > "$hst/omarchy-shell" <<'EOF'
#!/bin/sh
echo "omarchy-shell $*" >> "$HOME/shell.log"
m=$(cat "$HOME/shell-mode" 2>/dev/null) || { echo "omarchy-shell is not running" >&2; exit 1; }
[ "$1" != -q ] || shift
case $2 in
  rescanPlugins) [ "$m" = stuck ] || : > "$HOME/rescanned" ;;
  listPlugins)
    if [ "$m" = known ] || { [ -e "$HOME/rescanned" ] && [ -e "$HOME/listed" ]; }; then
      echo '[{"id":"x.y","enabled":true},{"id":"chaves.omabox","enabled":false}]'
    else
      [ ! -e "$HOME/rescanned" ] || : > "$HOME/listed"
      echo '[{"id":"x.y","enabled":true}]'
    fi ;;
esac
EOF
  chmod +x "$hst/omarchy" "$hst/omarchy-shell"
  in_h() { HOME=$h XDG_DATA_HOME=$h/.local/share XDG_CACHE_HOME=$h/.cache XDG_CONFIG_HOME=$h/.config XDG_STATE_HOME=$h/.local/state PATH=$hst:$PATH "$CLI" "$@" 2>&1; }
  out=$(in_h setup); local rc=$?
  check_eq "setup in a clean HOME" 0 "$rc"
  # (No ~/.local/bin/omabox for a system install: its command is /usr/bin/omabox.)
  local bin="$ROOT/bin/omabox "; [[ $ROOT != /usr/* ]] || bin=""
  check_eq "...omabox, the skill (Claude Code, the shared dir, Codex: it is there) and the widget linked" \
    "$bin$ROOT/skill $ROOT/skill $ROOT/skill $ROOT/plugin" \
    "$(readlink "$h/.local/bin/omabox" "$h/.claude/skills/omabox" "$h/.agents/skills/omabox" "$h/.codex/skills/omabox" "$h/.config/omarchy/plugins/chaves.omabox" | tr '\n' ' ' | sed 's/ $//')"
  [[ $ROOT != /usr/* ]] || check_fails "...no ~/.local/bin/omabox for a system install" test -e "$h/.local/bin/omabox"
  check_fails "...not for an agent that is not installed" test -e "$h/.hermes"
  check "...the settings dir" test -d "$h/.config/omabox"
  check_match "...the guard not turned on without a terminal" "not asked \(no terminal\): omabox guard on" "$out"
  # finding 539 (#397): the widget's line without a terminal works as soon as setup is done. The
  # running shell had not seen the new link yet, so `omarchy plugin enable` said "is not known". A shell
  # that does not list the widget is asked to rescan, and setup waits until it lists it.
  local sl
  setup_shell() { rm -f "$h/shell.log" "$h/rescanned" "$h/listed"; if [ "$1" = none ]; then rm -f "$h/shell-mode"; else echo "$1" > "$h/shell-mode"; fi; out=$(in_h setup); sl=$(cat "$h/shell.log" 2>/dev/null); }
  check_match "...no shell running: the line as it was" "bar widget: not asked \(no terminal\): omarchy plugin enable chaves\.omabox" "$out"
  setup_shell unknown
  check_match "a shell that has not seen the new link: the same line" "bar widget: not asked \(no terminal\): omarchy plugin enable chaves\.omabox" "$out"
  check_eq "...after a rescan, and a wait until the shell lists the widget (#397)" \
    "omarchy-shell shell listPlugins|omarchy-shell -q shell rescanPlugins|omarchy-shell shell listPlugins|omarchy-shell shell listPlugins" "$(tr '\n' '|' <<<"$sl" | sed 's/|$//')"
  setup_shell known
  check_eq "a shell that lists it already: no rescan (it reloads every plugin)" "omarchy-shell shell listPlugins" "$sl"
  setup_shell none
  check_eq "no shell running: asked once, no rescan" "omarchy-shell shell listPlugins" "$sl"
  setup_shell stuck
  check_match "a shell that still does not list it after the rescan: the line names both steps" \
    "bar widget: not asked \(no terminal\): omarchy-shell shell rescanPlugins, then omarchy plugin enable chaves\.omabox" "$out"
  date -Is > "$h/.config/omabox/widget-declined"; setup_shell unknown
  check_eq "...a no remembered: not a call to the shell" "" "$sl"
  rm -f "$h/.config/omabox/widget-declined" "$h/shell-mode" "$h/shell.log"
  # finding 326: the feedback skill is opt-in. No link from a plain setup; --feedback-skill links it
  # where the omabox skill goes, a later plain setup keeps it, --no-feedback-skill takes it out.
  local fbl=(.claude/skills/omabox-feedback .agents/skills/omabox-feedback .codex/skills/omabox-feedback) l
  fb_links() { local o=""; for l in "${fbl[@]}"; do o+="$(readlink "$h/$l" || echo -) "; done; echo "${o% }"; }
  check_eq "plain setup: no feedback skill link, it is opt-in (finding 326)" "- - -" "$(fb_links)"
  out=$(in_h setup --feedback-skill)
  check_eq "setup --feedback-skill: linked where the omabox skill is" \
    "$ROOT/skill-feedback $ROOT/skill-feedback $ROOT/skill-feedback" "$(fb_links)"
  check_match "...saying it asks before posting, and how to take it out" "asks before posting; omabox setup --no-feedback-skill" "$out"
  ln -sfn /old/checkout/skill-feedback "$h/.codex/skills/omabox-feedback"
  in_h setup >/dev/null
  check_eq "...a later plain setup keeps it (one an older omabox linked, pointed here)" \
    "$ROOT/skill-feedback $ROOT/skill-feedback $ROOT/skill-feedback" "$(fb_links)"
  out=$(in_h setup --no-feedback-skill)
  check_eq "setup --no-feedback-skill: unlinked" "- - -" "$(fb_links)"
  check_eq "...the omabox skill kept" "$ROOT/skill" "$(readlink "$h/.claude/skills/omabox")"
  in_h setup >/dev/null
  check_eq "...and a plain setup does not bring it back" "- - -" "$(fb_links)"
  in_h setup --feedback-skill >/dev/null
  check_eq "setup again: the same (idempotent)" 0 "$(in_h setup >/dev/null; echo $?)"
  # An answer with blanks around it is read as bash's read took it (finding 482): " n" and "n " are a
  # no. In a terminal (script's pty), the widget's question; omarchy and omarchy-shell stand-ins that
  # log, on a HOME of its own.
  if command -v script >/dev/null; then
    local sh2=$TMP/$P-setup-pty sst=$TMP/$P-setup-stub a
    mkdir -p "$sst"
    for a in omarchy omarchy-shell; do printf '#!/bin/sh
echo "%s $*" >> "$HOME/stub.log"
' "$a" > "$sst/$a"; chmod +x "$sst/$a"; done
    for a in ' n' 'n ' $'	N'; do
      rm -rf "$sh2"; mkdir -p "$sh2"
      printf '%s\n' "$a" | env -u CLAUDE_CONFIG_DIR -u CODEX_HOME HOME="$sh2" XDG_DATA_HOME="$sh2/.local/share" XDG_CACHE_HOME="$sh2/.cache" \
        XDG_CONFIG_HOME="$sh2/.config" PATH="$sst:$PATH" script -qec "$(printf %q "$CLI") setup" /dev/null >/dev/null 2>&1
      check "setup in a terminal, answer [${a}]: a no, remembered" test -e "$sh2/.config/omabox/widget-declined"
      check_fails "...and no widget enabled" grep -q "plugin enable" "$sh2/stub.log"
    done
  else skip "setup's answers with blanks" "no script(1)"; fi
  check_match "setup --force alone is refused" "--force is for --aquamarine" "$(in_h setup --force)"
  check_match "...and --aquamarine with --remove" "one of --aquamarine, --remove," "$(in_h setup --aquamarine --remove)"
  check_match "...and --feedback-skill with --remove" "one of --aquamarine, --remove," "$(in_h setup --feedback-skill --remove)"
  # What --remove takes away, and what it leaves: a link moved elsewhere, a real dir, the settings.
  in_h guard on claude >/dev/null
  ln -sfn /elsewhere "$h/.codex/skills/omabox"
  ln -sfn /elsewhere "$h/.codex/skills/omabox-feedback"
  mkdir -p "$h/.pi/agent/skills/omabox" "$h/.local/share/omabox/aquamarine/lib" "$h/.cache/omabox-aquamarine" "$h/.local/share/omabox/saves/s1" "$h/.cache/omabox"
  echo bar-icon=auto > "$h/.config/omabox/config"
  out=$(in_h setup --remove); rc=$?
  check_eq "setup --remove" 0 "$rc"
  local f gone=""
  for f in .local/bin/omabox .claude/skills/omabox .agents/skills/omabox .claude/skills/omabox-feedback .agents/skills/omabox-feedback .config/omarchy/plugins/chaves.omabox .local/share/omabox/aquamarine .cache/omabox-aquamarine; do
    [ -e "$h/$f" ] || [ -L "$h/$f" ] || gone+="$f "
  done
  check_eq "...removes the links and the user's aquamarine build" ".local/bin/omabox .claude/skills/omabox .agents/skills/omabox .claude/skills/omabox-feedback .agents/skills/omabox-feedback .config/omarchy/plugins/chaves.omabox .local/share/omabox/aquamarine .cache/omabox-aquamarine " "$gone"
  check_eq "...not a link that points elsewhere now" "/elsewhere /elsewhere" "$(readlink "$h/.codex/skills/omabox" "$h/.codex/skills/omabox-feedback" | tr '\n' ' ' | sed 's/ $//')"
  check "...nor a real dir" test -d "$h/.pi/agent/skills/omabox"
  check_eq "...keeps the settings and saves, saying so" "bar-icon=auto|yes" \
    "$(cat "$h/.config/omabox/config")|$([ -d "$h/.local/share/omabox/saves/s1" ] && grep -q "kept: your settings" <<<"$out" && echo yes)"
  check_fails "...turns the guard off" grep -q omabox-guard "$h/.claude/settings.json"
  check_match "...and names the backup that leaves (#398)" "kept: the guard's backups .*/\\.claude/settings\\.json\\.bak-[0-9]" "$out"
  check_fails "...and leaves a widget this HOME has not enabled alone (no omarchy call)" grep -q "plugin disable" <<<"$out"
  check_fails "...and the boxes' home dir, empty (finding 130)" test -e "$h/.cache/omabox"
  check_eq "--remove again: nothing left to do" 0 "$(in_h setup --remove >/dev/null; echo $?)"
  mkdir -p "$h/.cache/omabox/b/home"; in_h setup --remove >/dev/null
  check "...a box's home still in it stays" test -d "$h/.cache/omabox/b/home"
}

# finding 130: a user Omarchy has set no theme for (an account that never logged in) is told why,
# before anything of the box is made (it once died on a bare cp, leaving the box's dirs behind).
t_unit_no_theme() {
  local h=$TMP/$P-notheme rt=$TMP/$P-notheme-run out rc
  mkdir -p "$h/.local/state/omarchy" "$rt"; chmod 700 "$rt"
  out=$(HOME=$h XDG_RUNTIME_DIR=$rt XDG_CACHE_HOME=$h/.cache XDG_DATA_HOME=$h/.local/share XDG_CONFIG_HOME=$h/.config XDG_STATE_HOME=$h/.local/state \
    OMABOX_AQUAMARINE=system "$CLI" up nt 2>&1); rc=$?
  check_eq "up with no Omarchy theme fails" 1 "$rc"
  check_match "...saying why and what to do" "has not set a theme for you yet .*log into Omarchy once" "$out"
  check_fails "...before the box's dirs are made" test -e "$h/.cache/omabox/nt"
  check_fails "...or its runtime dir" test -e "$rt/omabox/nt"
  # up --theme (finding 245) needs no theme of the user's: past that check, it stops at a `down`'s
  # marker from the future (finding 147: "cancelled"), the first check after it that needs no
  # aquamarine without #415's fix (the earlier stop, `--monitor` on an interactive box, is only
  # refused without that fix; with it a unit test would have started an interactive box).
  mkdir -p "$rt/omabox"; echo 9999999999999 > "$rt/omabox/.down-nt"
  out=$(HOME=$h XDG_RUNTIME_DIR=$rt XDG_CACHE_HOME=$h/.cache XDG_DATA_HOME=$h/.local/share XDG_CONFIG_HOME=$h/.config XDG_STATE_HOME=$h/.local/state \
    OMABOX_AQUAMARINE=system "$CLI" up nt --theme tokyo-night 2>&1)
  check_match "with --theme: not refused for want of a theme of the user's" "up: cancelled: omabox down nt came|a headless box on NVIDIA" "$out"
  check_fails "...(and not for the theme)" grep -q "has not set a theme" <<<"$out"
  rm -f "$rt/omabox/.down-nt"
  out=$(HOME=$h XDG_RUNTIME_DIR=$rt XDG_CACHE_HOME=$h/.cache XDG_DATA_HOME=$h/.local/share XDG_CONFIG_HOME=$h/.config XDG_STATE_HOME=$h/.local/state \
    OMABOX_AQUAMARINE=system "$CLI" up nt --theme nope 2>&1)
  check_match "...one that is not there refused" "--theme: no theme nope in " "$out"
  check_fails "...neither makes the box's dirs" test -e "$h/.cache/omabox/nt" -o -e "$rt/omabox/nt"
}

# finding 125 (issue #47): which aquamarine a box runs (aq_pick), and what is refused without the fix.
t_unit_aquamarine() {
  local d=$TMP/$P-aq so=libaquamarine.so.14
  mkdir -p "$d/sys" "$d/co/lib" "$d/user/lib" "$d/stale/lib" "$d/home"
  : > "$d/sys/libaquamarine.so.0.15.0"; ln -s libaquamarine.so.0.15.0 "$d/sys/$so"
  : > "$d/user/lib/libaquamarine.so.0.15.1"; ln -s libaquamarine.so.0.15.1 "$d/user/lib/$so"; echo abc1234 > "$d/user/.omabox-commit"
  pick() { OMABOX_AQUAMARINE="" probe aq_pick_dirs "$@" 2>&1; }
  check_eq "no private build: the system's, 0.15.0 lacks the fix" "system||0.15.0|0" "$(pick "$so" "$d/sys" "$d/co/lib")"
  check_eq "a private build with the soname: used, with its commit, fixed" "private|$d/user/lib|0.15.1@abc1234|1" \
    "$(pick "$so" "$d/sys" "$d/co/lib" "$d/user/lib")"
  : > "$d/co/lib/libaquamarine.so.0.15.1"; ln -s libaquamarine.so.0.15.1 "$d/co/lib/$so"
  check_eq "...the first one listed (a checkout's before the user's)" "private|$d/co/lib|0.15.1|1" \
    "$(pick "$so" "$d/sys" "$d/co/lib" "$d/user/lib")"
  check_eq "OMABOX_AQUAMARINE=system: the system's all the same" "system||0.15.0|0" \
    "$(OMABOX_AQUAMARINE=system probe aq_pick_dirs "$so" "$d/sys" "$d/co/lib" 2>&1)"
  check_match "...anything else refused" "OMABOX_AQUAMARINE is system or unset" "$(OMABOX_AQUAMARINE=yes probe aq_pick_dirs "$so" "$d/sys" "$d/co/lib" 2>&1)"
  if command -v cc >/dev/null; then
    echo 'int aq(void) { return 0; }' > "$d/aq.c"
    cc -shared -fPIC -Wl,-soname,libaquamarine.so.13 -o "$d/stale/lib/libaquamarine.so.0.14.0" "$d/aq.c"
  else : > "$d/stale/lib/libaquamarine.so.0.14.0"; fi
  local out; out=$(pick "$so" "$d/sys" "$d/stale/lib")
  check_match "a private build with another soname (stale): skipped, saying so" \
    "skipping the aquamarine in $d/stale/lib: Hyprland links $so, it has (libaquamarine.so.13|another)" "$out"
  check_match "...and the system's used" $'\n''system\|\|0.15.0\|0$' "$out"
  local v
  for v in 0.15.1:0 0.15.2:1 0.15.10:1 0.16.0:1 1.0:1 0.9.9:0; do
    : > "$d/sys/libaquamarine.so.${v%:*}"; ln -sf "libaquamarine.so.${v%:*}" "$d/sys/$so"
    check_eq "the system's ${v%:*}: fixed ${v#*:}" "system||${v%:*}|${v#*:}" "$(pick "$so" "$d/sys")"
  done
  aq_symbol_checks "$d"
  check_match "a soname the system lacks" "Hyprland links libaquamarine.so.99, which is not in $d/sys" "$(pick libaquamarine.so.99 "$d/sys")"
  check_fails "no soname at all: no answer (not a match on the dir)" probe aq_pick_dirs "" "$d/sys" "$d/user/lib"
  # What needs the fix, on this machine's system aquamarine (OMABOX_AQUAMARINE=system).
  if aq_unfixed env OMABOX_AQUAMARINE=system "$CLI"; then
    check_match "without the fix: up --confirm-close refused, saying why and what to run" \
      "--confirm-close .*needs aquamarine's fix .*hyprwm/aquamarine#415.*omabox setup --aquamarine" \
      "$(OMABOX_AQUAMARINE=system ob up "$P-aq" --interactive --confirm-close 2>&1)"
    check_fails "...nothing made" test -e "$XDG_RUNTIME_DIR/omabox/$P-aq"
    check_match "...config confirm-close on: set, with a note" "note: confirm-close needs aquamarine's fix.*confirm-close=on" \
      "$(HOME=$d/home OMABOX_AQUAMARINE=system "$CLI" config confirm-close on 2>&1 | tr '\n' ' ')"
    local n nv=""
    for n in /dev/dri/renderD*; do [ "$(probe render_driver "$n")" != nvidia ] || { nv=$n; break; }; done
    if [ -n "$nv" ]; then
      check_match "...a headless box on NVIDIA refused, saying what to run" "a headless box on NVIDIA \($nv\) needs aquamarine's fix.*omabox setup --aquamarine" \
        "$(OMABOX_AQUAMARINE=system OMABOX_RENDER_NODE=$nv ob up "$P-aq" 2>&1)"
      check_fails "...nothing made" test -e "$XDG_RUNTIME_DIR/omabox/$P-aq"
    else
      skip "a headless box on NVIDIA without the fix is refused" "no NVIDIA render node"
    fi
  else
    skip "what needs aquamarine's fix is refused without it" "the system's aquamarine has it"
  fi
  # The widget's confirm-close switch reads this (greyed while false).
  if aq_unfixed env OMABOX_AQUAMARINE=system "$CLI"; then
    check_eq "config --json: confirm-close unavailable without the fix" false \
      "$(HOME=$d/home OMABOX_AQUAMARINE=system "$CLI" config --json | jq .confirm_close_available)"
  fi
  if aq_unfixed "$CLI"; then
    skip "config --json: confirm-close available with the fix" "boxes use an aquamarine without it"
  else
    check_eq "config --json: confirm-close available with the fix" true "$(HOME=$d/home "$CLI" config --json | jq .confirm_close_available)"
  fi
  check_match "setup: an unknown option, refused before anything is done" "unknown option --nope" "$("$CLI" setup --aquamarine --nope 2>&1)"
}

# finding 271 (issue #182): a linked worktree with no build/prefix of its own runs its boxes on the main
# checkout's (aq_main_lib), found from the files git reads, never by running git. A scratch main
# checkout and worktrees of it (one with a relative gitdir, one with a space in its path).
t_unit_aq_worktree() {
  local d=$TMP/$P-aqwt so=libaquamarine.so.14 M W X S SW out
  M=$d/main W="$d/wt one" X=$d/wt-rel S=$d/sub SW=$d/subwt
  gw() { git -c user.name=t -c user.email=t@t -c protocol.file.allow=always "$@" >/dev/null 2>&1; }
  mkdir -p "$M" "$S" "$d/sys" "$d/bin" "$d/root/usr"; ln -s "$d/sys" "$d/root/usr/lib"
  for r in "$M" "$S"; do gw -C "$r" init -q && echo x > "$r/f" && gw -C "$r" add f && gw -C "$r" commit -qm one; done
  gw -C "$M" worktree add -q -b "$P-aqwt" "$W"
  gw -C "$M" worktree add -q -b "$P-aqwt-rel" "$X"
  printf 'gitdir: ../main/.git/worktrees/%s\n' "${X##*/}" > "$X/.git"   # as worktree.useRelativePaths writes it
  gw -C "$M" submodule add -q "$S" sm
  gw -C "$M/sm" worktree add -q -b "$P-aqwt-sub" "$SW"
  : > "$d/sys/libaquamarine.so.0.15.0"; ln -s libaquamarine.so.0.15.0 "$d/sys/$so"
  # A git that records being run: aq_main_lib never runs it, in a jail or out.
  printf '#!/bin/sh\necho "$*" >> %q/git-ran\nexit 1\n' "$d" > "$d/bin/git"; chmod +x "$d/bin/git"
  main_lib() { PATH=$d/bin:$PATH probe aq_main_lib "$@" 2>&1; }
  check_eq "a worktree, no build in the main checkout: nothing" "" "$(main_lib "$W")"
  mkdir -p "$M/build/prefix/lib"
  : > "$M/build/prefix/lib/libaquamarine.so.0.15.1"; ln -s libaquamarine.so.0.15.1 "$M/build/prefix/lib/$so"
  probe aq_const AQ_BUILD > "$M/build/prefix/.omabox-commit"
  local common; common=$(git -C "$W" rev-parse --path-format=absolute --git-common-dir 2>/dev/null)
  check_eq "a worktree: the main checkout's build/prefix/lib, where git's common dir says" "${common%/.git}/build/prefix/lib" "$(main_lib "$W")"
  check_eq "...one whose .git names its gitdir relative to it: the same" "$M/build/prefix/lib" "$(main_lib "$X")"
  check_eq "...for a jailed caller's broker: the same" "$M/build/prefix/lib" "$(OMABOX_JAIL='{"roots":[]}' main_lib "$W")"
  check_fails "...and git was never run" test -e "$d/git-ran"
  check_eq "the main checkout itself: nothing (its own build/prefix is first already)" "" "$(main_lib "$M")"
  check_eq "a submodule's worktree: nothing (its common dir is in .git/modules)" "" "$(main_lib "$SW")"
  check_eq "no checkout (an installed omabox): nothing" "" "$(main_lib "$d/sys")"
  # resolve DIR: which aquamarine a box from checkout DIR runs, and how --version says it (the system's
  # in the root's /usr/lib, no build in the user's data dir).
  resolve() { PATH=$d/bin:$PATH XDG_DATA_HOME=$d/user OMABOX_AQUAMARINE='' probe aq_resolve "$so" "$1" "$d/root" 2>&1; }
  out=$(resolve "$W")
  check_match "a box from the worktree runs the main checkout's build" "^private\|$M/build/prefix/lib\|$M/build/prefix\|" "$out"
  check_match "...said so" "a private build, 0\.15\.1@[^ ]* \($M/build/prefix, the main checkout's: this worktree has no usable one\)$" "$out"
  mkdir -p "$W/build/prefix/lib"; : > "$W/build/prefix/lib/libaquamarine.so.0.15.1"; ln -s libaquamarine.so.0.15.1 "$W/build/prefix/lib/$so"
  check_eq "...its own build, once it has one: first, not said to be the main's" "private|$W/build/prefix/lib||a private build, 0.15.1 ($W/build/prefix)" "$(resolve "$W")"
  rm -rf "$W/build"
  check_eq "the main checkout's own boxes: its build, nothing borrowed" "private|$M/build/prefix/lib|" "$(resolve "$M" | cut -d'|' -f1-3)"
  if [ "$(id -u)" != 0 ]; then
    chmod 000 "$M/build/prefix/lib"
    check_eq "a main checkout's lib dir not readable: nothing" "" "$(main_lib "$W")"
    check_match "...the worktree's boxes on the system's" "^system\|\|\|" "$(resolve "$W")"
    chmod 755 "$M/build/prefix/lib"
    chmod 000 "$M/build/prefix/lib/libaquamarine.so.0.15.1"
    out=$(resolve "$W")
    check_match "a build whose library is not readable: skipped, saying so" "skipping the aquamarine in $M/build/prefix/lib: $so is not readable" "$out"
    check_match "...the system's used" $'\n''system\|\|\|' "$out"
    chmod 644 "$M/build/prefix/lib/libaquamarine.so.0.15.1"
  else
    skip "a build not readable is not used" "running as root reads everything"
  fi
  rm -rf "$M/build"
  check_eq "the main checkout's build gone: nothing, quietly" "" "$(main_lib "$W")"
  # up from a worktree whose tools are not built (a fresh one): make, never install.sh there. The
  # binary in a stand-in checkout with no tools/ (.git a file: a worktree's; a dir: a main checkout's).
  local co
  for co in "$d/co-wt" "$d/co-main"; do mkdir -p "$co/build"; cp "$PROBE" "$co/build/omabox"; done
  echo "gitdir: $M/.git/worktrees/x" > "$d/co-wt/.git"; mkdir -p "$d/co-main/.git"
  check_match "up from a worktree without its tools: build them with make, not install.sh" \
    "missing .*: in a git worktree, build them: for m in .*/tools/\*/Makefile; do make -C" "$("$d/co-wt/build/omabox" _rust probe check_install 2>&1)"
  check_match "...a main checkout's: install.sh" "missing .*: run install.sh$" "$("$d/co-main/build/omabox" _rust probe check_install 2>&1)"
}

# finding 246 (issue #48): the system's aquamarine has the fix when it exports what #415 added, whatever
# its version says (a package patched with #415 keeps the version it patched); what needs the fix
# follows. On real libraries: omabox's build (0.15.1@7bb8bdf4 and its patches) and the stock 0.15.0.
aq_symbol_checks() {
  local d=$1/sym so out real="" c common
  so=$(probe hypr_aq_soname) || { no "the soname Hyprland links"; return; }
  local gt=$d/gt
  mkdir -p "$d/stub" "$d/patched" "$d/stock" "$gt/dev/dri" "$gt/sys/class/drm/renderD129" "$gt/sys/bus/pci/devices/0000:01:00.0" "$d/drivers/nvidia"
  # sys DIR: which aquamarine boxes run when DIR is the system's (no private build).
  sys() { probe aq_pick "$so" "$1" 2>&1; }
  # A library of the stock version exporting #415's CWaylandOutput::applyConfigure, and nothing else.
  if command -v cc >/dev/null; then
    printf 'void f(void) __asm__("%s");\nvoid f(void) {}\n' "$(probe aq_const AQ_FIX_SYMBOL)" > "$d/fix.c"
    cc -shared -fPIC -Wl,-soname,"$so" -o "$d/stub/libaquamarine.so.0.15.0" "$d/fix.c"
    ln -s libaquamarine.so.0.15.0 "$d/stub/$so"
    check_match "a system 0.15.0 exporting #415's applyConfigure: fixed, said patched" \
      "^system\|0\.15\.0\|1\|the system's, 0\.15\.0, patched with the fix" "$(sys "$d/stub")"
    aq_setup_checks "$d" "$so"
  else
    skip "a stub 0.15.0 exporting #415's symbol has the fix" "no C compiler"
  fi
  # omabox's own build: this checkout's, the main checkout's for a worktree, or the user's.
  common=$(git -C "$ROOT" rev-parse --path-format=absolute --git-common-dir 2>/dev/null) || common=""
  for c in "$ROOT/build/prefix/lib/$so" "${common:+${common%/.git}/build/prefix/lib/$so}" \
    "${XDG_DATA_HOME:-$HOME/.local/share}/omabox/aquamarine/lib/$so"; do
    [ -n "$c" ] && [ -e "$c" ] && { real=$(readlink -f "$c"); break; }
  done
  if [ -n "$real" ]; then
    check "omabox's build ($real) exports #415's symbol" probe aq_has_fix "$real"
    # As the system's, under the stock version's name: the version says unfixed, the symbol fixed.
    cp "$real" "$d/patched/libaquamarine.so.0.15.0"; ln -s libaquamarine.so.0.15.0 "$d/patched/$so"
    check_match "...as the system's 0.15.0 (a patched package): fixed, not by its version" "^system\|0\.15\.0\|1\|" "$(sys "$d/patched")"
  else
    skip "omabox's aquamarine build has the fix by its symbol" "no build (omabox setup --aquamarine)"
  fi
  # The system's own, whatever its package revision: a release up to AQ_FIXED_AFTER lacks the fix unless
  # a package patched it in, which is news (UPSTREAM.md's drop list), not a failure; a later release
  # has it by its version, the symbol or not.
  local sysv=""
  if [ -e "/usr/lib/$so" ]; then
    sysv=$(readlink -f "/usr/lib/$so"); sysv=${sysv##*.so.}
    cp "$(readlink -f "/usr/lib/$so")" "$d/stock/libaquamarine.so.$sysv"; ln -s "libaquamarine.so.$sysv" "$d/stock/$so"
    if probe aq_ver_fixed "$sysv"; then
      note "the system's aquamarine is $sysv: time for UPSTREAM.md's drop list"
      check_match "the system's $sysv, a release after $(probe aq_const AQ_FIXED_AFTER): fixed by its version" "^system\|[^|]*\|1\|" "$(sys "$d/stock")"
    elif probe aq_has_fix "/usr/lib/$so"; then
      note "the system's aquamarine $sysv exports #415's symbol (a patched package): time for UPSTREAM.md's drop list"
      check_match "the system's $sysv, patched with #415: fixed, said patched" "^system\|[^|]*\|1\|.*patched with the fix" "$(sys "$d/stock")"
    else
      check_match "the system's stock $sysv lacks #415's symbol, so unfixed, said so" "^system\|[^|]*\|0\|.*without the fix" "$(sys "$d/stock")"
    fi
  else
    skip "the system's aquamarine has the fix as its library says" "no /usr/lib/$so here"
  fi
  # What follows the answer: confirm-close in the settings (the widget's switch, config --json's), and
  # up's refusal of a headless box on NVIDIA (t_unit_gpu's fake GPU), each as config and up ask it, on
  # a root whose /usr/lib is that system dir and whose devices are the fake GPU's (no checkout build).
  : > "$gt/dev/dri/renderD129"; ln -s "$gt/sys/bus/pci/devices/0000:01:00.0" "$gt/sys/class/drm/renderD129/device"
  ln -s "$d/drivers/nvidia" "$gt/sys/bus/pci/devices/0000:01:00.0/driver"
  local dir avail refused rt
  for dir in stub patched stock; do
    [ -e "$d/$dir/$so" ] || continue
    rt=$d/root-$dir; mkdir -p "$rt/usr"; ln -sfn "$d/$dir" "$rt/usr/lib"; ln -sfn "$gt/dev" "$rt/dev"; ln -sfn "$gt/sys" "$rt/sys"
    if [ "$(sys "$d/$dir" | cut -d'|' -f3)" = 1 ]; then avail=true refused=0; else avail=false refused=1; fi
    check_eq "the $dir system's: config --json confirm-close-available $avail" "$avail" \
      "$(OMABOX_AQUAMARINE=system probe confirm_close_available "$d/noco" "$rt" 2>/dev/null)"
    out=$(OMABOX_AQUAMARINE=system probe nvidia_needs_fix /dev/dri/renderD129 "$d/noco" "$rt" 2>&1; echo "rc=$?")
    if [ "$refused" = 1 ]; then
      check_match "...up's check of a headless box on NVIDIA: refused" "a headless box on NVIDIA \(/dev/dri/renderD129\) needs aquamarine's fix.*rc=1$" "$(tr '\n' ' ' <<<"$out" | sed 's/ $//')"
    else
      check_eq "...up's check of a headless box on NVIDIA: not refused" "rc=0" "$out"
    fi
    aq_up_gate "$d" "$dir" "$so" "$refused"
  done
}

# aq_up_gate D DIR SONAME REFUSED: `up` itself on aq_symbol_checks' fake NVIDIA GPU, with DIR's library
# as the system's aquamarine: a user and mount namespace puts the fake tree over /dev/dri and
# /sys/class/drm and DIR's library over the system's (its file: the decision is by the symbol, the
# version said is the system's), with a scratch HOME and runtime dir. Refused: before its lock (no
# lock file, nothing made); let through: as far as its lock, where a down marker from the future
# cancels it (the lock taken, no box). The marker is there for a refusal too: an up that should have
# refused and did not stops at its lock, never starting a box on the fake GPU.
aq_up_gate() {
  local d=$1 dir=$2 so=$3 refused=$4 rt=$1/up-$2 out
  [ -e "/usr/lib/$so" ] || { skip "...up itself on the $dir system's aquamarine" "no /usr/lib/$so here"; return; }
  unshare -r -m --propagation slave true 2>/dev/null || { skip "...up itself on the $dir system's aquamarine" "no user namespaces here"; return; }
  mkdir -p "$rt/run/omabox" "$d/up-home/.local/state/omarchy/current/theme"; chmod 700 "$rt/run"
  echo 99999999999 > "$rt/run/omabox/.down-$P-aqs"
  # shellcheck disable=SC2016 # expanded by the namespace's shell
  out=$(unshare -r -m --propagation slave bash -c '
    gt=$1/gt; mount --bind "$gt/dev/dri" /dev/dri && mount --bind "$gt/sys/class/drm" /sys/class/drm &&
      mount --bind "$(readlink -f "$1/$2/$3")" "/usr/lib/$3" || exit 99
    env HOME="$1/up-home" XDG_RUNTIME_DIR="$4" XDG_CACHE_HOME="$1/up-home/.cache" XDG_STATE_HOME="$1/up-home/.local/state" OMABOX_AQUAMARINE=system OMABOX_RENDER_NODE=/dev/dri/renderD129 "$5" up "$6"
  ' _ "$d" "$dir" "$so" "$rt/run" "$CLI" "$P-aqs" 2>&1; echo "rc=$?")
  if [ "$refused" = 1 ]; then
    check_match "...up itself refuses it" "^omabox: a headless box on NVIDIA \(/dev/dri/renderD129\) needs aquamarine's fix.*rc=1$" "$(tr '\n' ' ' <<<"$out" | sed 's/ $//')"
    check_fails "...before its lock: no lock file" test -e "$rt/run/omabox/.lock-$P-aqs"
  else
    check_match "...up itself goes on to its lock (cancelled there by a down)" "^omabox: up: cancelled: omabox down $P-aqs came while it was starting rc=1$" "$(tr '\n' ' ' <<<"$out" | sed 's/ $//')"
    check "...its lock taken" test -e "$rt/run/omabox/.lock-$P-aqs"
  fi
  check_fails "...no box made" test -e "$rt/run/omabox/$P-aqs"
}

# finding 247 (issue #186): `setup --aquamarine` builds whenever boxes would run without omabox's own
# patches, a system aquamarine with #415 (aq_symbol_checks's stub) included; only this omabox's build
# is a no-op. Stopped at the clone: the build tools on PATH are stubs that log and fail, and the
# stand-in checkout setup runs from has no .git, so it builds into the scratch data dir, never a real one.
aq_setup_checks() {
  local d=$1 so=$2 t out build
  local tools=$d/setup-tools data=$d/setup-data cache=$d/setup-cache
  mkdir -p "$tools" "$data" "$cache"
  for t in git cmake ninja hyprwayland-scanner pkg-config c++; do
    printf '#!/bin/sh\necho "%s $*" >> "%s/log"\nexit 1\n' "$t" "$tools" > "$tools/$t"; chmod +x "$tools/$t"
  done
  # What setup decides over the stub as the system's (its root's /usr/lib), from no checkout build.
  local sr=$d/setup-root; mkdir -p "$sr/usr"; ln -sfn "$d/stub" "$sr/usr/lib"
  out=$(probe aq_build_needed 0 "$d/noco" "$sr" 2>&1; echo "rc=$?")
  check_fails "setup --aquamarine over a system aquamarine with #415: not \"nothing to build\"" grep -q "nothing to build" <<<"$out"
  check_match "...says it lacks omabox's own fixes, and builds them" \
    "has the fix for nested Wayland outputs but not omabox's own \(keys held .*\).*rc=0$" "$(tr '\n' ' ' <<<"$out" | sed 's/ $//')"
  # setup_aq [--force]: setup --aquamarine itself, run by a stand-in checkout's binary (the real one's
  # files but for build/ and .git, so it builds into the data dir), on stub build tools, the system's
  # aquamarine the machine's; nothing of the user's: HOME and the XDG dirs are scratch ones.
  local fr=$d/setup-co e
  mkdir -p "$fr/build"; for e in "$ROOT"/*; do [ "${e##*/}" = build ] || ln -s "$e" "$fr/${e##*/}"; done
  cp "$PROBE" "$fr/build/omabox"
  setup_aq() {
    : > "$tools/log"
    HOME=$d/setup-home XDG_DATA_HOME=$data XDG_CACHE_HOME=$cache PATH=$tools:$PATH "$fr/build/omabox" setup --aquamarine "$@" 2>&1
  }
  out=$(setup_aq)
  check_match "setup --aquamarine with no build: builds, into the data dir" "building aquamarine [^ ]+ .* into $data/omabox/aquamarine" "$out"
  check_match "...as far as the clone (the stub git), into the scratch cache" \
    "^git clone -q https://github.com/hyprwm/aquamarine $cache/omabox-aquamarine$" "$(cat "$tools/log")"
  # A build of this omabox's (AQ_BUILD) in the data dir: the only no-op, and --force builds all the same.
  build=$(probe aq_const AQ_BUILD)
  mkdir -p "$data/omabox/aquamarine/lib"
  cp "$d/stub/libaquamarine.so.0.15.0" "$data/omabox/aquamarine/lib/libaquamarine.so.0.15.1"
  ln -s libaquamarine.so.0.15.1 "$data/omabox/aquamarine/lib/$so"
  echo "$build" > "$data/omabox/aquamarine/.omabox-commit"
  out=$(setup_aq)
  check_match "...over this omabox's build ($build): nothing to build" "this omabox's build: nothing to build" "$out"
  check_eq "...no tool run" "" "$(cat "$tools/log")"
  out=$(setup_aq --force)
  check_match "...--force builds it all the same" "building aquamarine .*could not clone" "$(tr '\n' ' ' <<<"$out")"
  echo 7bb8bdf4+keys > "$data/omabox/aquamarine/.omabox-commit"
  out=$(setup_aq)
  check_match "...over an older build of omabox's: builds" "building aquamarine .*could not clone" "$(tr '\n' ' ' <<<"$out")"
  rm -rf "$data/omabox/aquamarine"
  # What `setup` says of each (aq_note). (`monitor add` refuses a box's aquamarine without +appid:
  # t_unit_monitor_add_window.)
  note_of() { probe aq_note "$1" "$data/lib" "$2" "$3" 2>&1; }
  check_match "setup's note on a system aquamarine with #415: omabox's own fixes, setup --aquamarine" \
    "^note: the system's aquamarine has the fix .*, but not omabox's own fixes \(keys held .*\): omabox setup --aquamarine$" "$(note_of system 0.15.0 1)"
  check_match "...without #415: both" "^note: headless boxes on NVIDIA and confirm-close need .*, and interactive boxes omabox's own fixes .*: omabox setup --aquamarine$" \
    "$(note_of system 0.15.0 0)"
  check_match "...an older build of omabox's: older" "^note: the aquamarine build in $data is older than this omabox's" "$(note_of private 0.15.1@7bb8bdf4+keys 1)"
  check_eq "...this omabox's build: nothing" "" "$(note_of private "0.15.1@$build" 1)"
  check_match "...this omabox's build gives each monitor's window a class of its own (finding 429)" "\+appid$" "$build"
}

# finding 116: up --hyprland PATH refuses what the box could not run, before anything is made.
t_unit_hyprland() {
  local d=$TMP/$P-hyp out
  mkdir -p "$d/fh" "$d/proj/build" "$d/other"
  printf '#!/bin/sh\nexec /usr/bin/Hyprland "$@"\n' > "$d/wrapper"; chmod +x "$d/wrapper"
  cp /usr/bin/true "$d/noaq"; cp /usr/bin/true "$d/fh/Hyprland"; : > "$d/plain"
  check_match "a missing file" "no such file" "$(ob up "$P-h1" --hyprland "$d/nosuch" 2>&1)"
  check_match "a file that is not executable" "is not executable" "$(ob up "$P-h1" --hyprland "$d/plain" 2>&1)"
  check_match "a script is not an ELF binary" "is not an ELF binary" "$(ob up "$P-h1" --hyprland "$d/wrapper" 2>&1)"
  check_match "an ELF with no libaquamarine" "links no libaquamarine" "$(ob up "$P-h1" --hyprland "$d/noaq" 2>&1)"
  check_match "its folder is refused as --ro-bind's are (here: all of HOME)" "refusing to mount $d/fh \(the binary's folder\).*it contains" \
    "$(HOME=$d/fh "$CLI" up "$P-h1" --hyprland "$d/fh/Hyprland" 2>&1)"
  check_match "run takes it for a throwaway (and refuses the same)" "is not an ELF binary" "$(ob run --hyprland "$d/wrapper" -- true 2>&1)"
  if command -v cc >/dev/null; then
    # A build against another aquamarine: a stub library with another soname, and a program linking it.
    echo 'int aq(void) { return 0; }' > "$d/aq.c"; echo 'int aq(void); int main(void) { return aq(); }' > "$d/m.c"
    mkdir -p "$d/aq99" "$d/aq14" "$d/b99" "$d/b14"
    local so; so=$(probe hypr_aq_soname)
    cc -shared -fPIC -Wl,-soname,libaquamarine.so.99 -o "$d/aq99/libaquamarine.so" "$d/aq.c" &&
      cc -o "$d/b99/Hyprland" "$d/m.c" -L"$d/aq99" -laquamarine
    check_match "a build against another libaquamarine soname is refused, saying which" \
      "links libaquamarine.so.99, which neither the system nor a private build of omabox's has \(the system has $so\)" \
      "$(ob up "$P-h1" --hyprland "$d/b99/Hyprland" 2>&1)"
    # The right soname, but a library the box does not have.
    cc -shared -fPIC -Wl,-soname,"$so" -o "$d/aq14/libaquamarine.so" "$d/aq.c" &&
      cc -shared -fPIC -Wl,-soname,libomaboxmissing.so.1 -o "$d/aq14/libomaboxmissing.so" "$d/aq.c" &&
      cc -o "$d/b14/Hyprland" "$d/m.c" -L"$d/aq14" -laquamarine -lomaboxmissing -Wl,--no-as-needed
    check_match "...and one needing a library the box lacks" "needs libomaboxmissing.so.1, which the box lacks" \
      "$(ob up "$P-h1" --hyprland "$d/b14/Hyprland" 2>&1)"
  else
    skip "builds against another aquamarine are refused" "no C compiler"
  fi
  # A jailed agent (finding 99): the binary's folder is one of the jail's, whole, or the binary is in its
  # project (in the box already). Past that, --size junk stops `up` before anything starts.
  git -C "$d/proj" init -q
  cp /usr/bin/true "$d/proj/build/Hyprland"; cp /usr/bin/true "$d/proj/Hyprland"; cp /usr/bin/true "$d/other/Hyprland"
  local J; J=$(jq -nc --arg p "$d/proj" --arg c "$d/proj" '{id: "1 2", net: false, cwd: $c, roots: [{path: $p, masked: false}]}')
  check_match "jail: a build outside the jail's folders is refused" "not in this jail's project nor in a folder it was given whole" \
    "$(OMABOX_JAIL=$J "$CLI" up "$P-h2" --hyprland "$d/other/Hyprland" --size huge 2>&1)"
  check_match "jail: one in its project passes" "a size is WxH" "$(OMABOX_JAIL=$J "$CLI" up "$P-h2" --hyprland "$d/proj/build/Hyprland" --size huge 2>&1)"
  check_match "jail: one in a folder of its, whole, passes" "a size is WxH" "$(OMABOX_JAIL=$J "$CLI" up "$P-h2" --hyprland "$d/proj/Hyprland" --size huge 2>&1)"
  # The jailed caller's omabox sends the path absolute (the broker is not in its directory).
  # (The jailed caller's omabox sends the path absolute, the broker not being in its directory:
  # t_unit_jailed_caller's "--hyprland goes absolute".)
  # (Another version than the installed hyprctl's: a warning; box.json gets the box's version line
  # either way, #238: install.rs hypr_version_as_bash, an #[ignore] test, the box's answers given;
  # #324 wave 6-suite.)
  local left; left=$(ob ls --json | jq -r '.[].name' | grep -c "^$P-h[12]$" || true)
  check_eq "refusals left no box behind" 0 "$left"
}

# finding 116: a box on a Hyprland build of its own (a copy of the installed one stands in for it).
t_hyprland() {
  local B=$P-hyp h=$TMP/$P-hbuild/Hyprland D=$XDG_RUNTIME_DIR/omabox/$P-hyp
  mkdir -p "${h%/*}"; cp /usr/bin/Hyprland "$h"
  check "up --hyprland (a copy of the installed one), shell and bar up" ob up "$B" --hyprland "$h"
  check_box_safety "$B"
  check_eq "the box's Hyprland runs it" "$h" "$(ob run -b "$B" -- sh -c 'readlink /proc/$(pgrep -x Hyprland)/exe')"
  check_match "ls says so, under its line" "^  Hyprland: $h \(Hyprland [0-9.]+ built from" "$(ob ls | grep -A1 "^$B " | tail -n 1)"
  check_eq "ls --json has the binary" "$h" "$(ob ls --json | jq -r --arg b "$B" '.[] | select(.name == $b) | .hyprland')"
  check_match "windows says so first" "^box $B runs Hyprland $h \(Hyprland " "$(ob windows -b "$B" | head -n 1)"
  check "box.log has hyprctl version's first line, from inside" until_ok 10 grep -qF "session.sh: Hyprland $h: Hyprland " "$D/box.log"
  # finding 358: a box without --quickshell is unchanged: its shell is the installed Quickshell.
  check_eq "its shell runs the installed Quickshell" /usr/bin/quickshell "$(ob run -b "$B" -- sh -c 'p=$(cat "$XDG_RUNTIME_DIR/omabox-shell.pid") && readlink "/proc/$p/exe"')"
  check_eq "...ls --json has no build and the installed one's version line" "null true" \
    "$(ob ls --json | jq -r --arg b "$B" '.[] | select(.name == $b) | "\(.quickshell) \(.quickshell_version | test("^Quickshell [0-9]"))"')"
  check "its folder is read-only in the box" bash -c "! '$CLI' run -b '$B' -- touch '${h%/*}/x' 2>/dev/null"
  check "restart-shell" ob restart-shell -b "$B"
  check "down" ob down "$B"
}

# finding 358: `up --quickshell PATH`'s refusals, before any box starts, and what it records.
t_unit_quickshell() {
  local d=$TMP/$P-qs out
  mkdir -p "$d/fh" "$d/proj/build" "$d/other"
  printf '#!/bin/sh\nexec /usr/bin/quickshell "$@"\n' > "$d/wrapper"; chmod +x "$d/wrapper"
  cp /usr/bin/true "$d/noqt"; cp /usr/bin/true "$d/fh/quickshell"; : > "$d/plain"
  check_match "a missing file" "--quickshell: no such file" "$(ob up "$P-q1" --quickshell "$d/nosuch" 2>&1)"
  check_match "a file that is not executable" "--quickshell: .* is not executable" "$(ob up "$P-q1" --quickshell "$d/plain" 2>&1)"
  check_match "a script is not an ELF binary" "--quickshell: .* is not an ELF binary" "$(ob up "$P-q1" --quickshell "$d/wrapper" 2>&1)"
  check_match "an ELF with no Qt" "links no libQt6Core.so.6 \(readelf -d\): not a Quickshell build" "$(ob up "$P-q1" --quickshell "$d/noqt" 2>&1)"
  check_match "its folder is refused as --ro-bind's are (here: all of HOME)" "refusing to mount $d/fh \(the binary's folder\).*it contains" \
    "$(HOME=$d/fh "$CLI" up "$P-q1" --quickshell "$d/fh/quickshell" 2>&1)"
  check_match "...and with --no-shell, which starts no shell" "--quickshell runs the box's shell, and --no-shell starts none" \
    "$(ob up "$P-q1" --quickshell /usr/bin/quickshell --no-shell 2>&1)"
  check_match "run takes it for a throwaway (and refuses the same)" "is not an ELF binary" "$(ob run --quickshell "$d/wrapper" -- true 2>&1)"
  if command -v cc >/dev/null && [ -n "$(probe qt_box)" ]; then
    # A build against another Qt minor: what qt_version_tag it refers to (every Qt program does).
    local qt; qt=$(probe qt_box)
    mkdir -p "$d/b0" "$d/b1" "$d/lib"
    printf 'extern const char qt_version_tag;\n__asm__(".symver qt_version_tag, qt_version_tag@Qt_%s");\nconst char *const tag = &qt_version_tag;\nint main(void) { return tag == 0; }\n' "6.0" > "$d/old.c"
    cc -fPIC -pie -o "$d/b0/quickshell" "$d/old.c" -l:libQt6Core.so.6 2>/dev/null
    check_match "a build against another Qt is refused, naming both" \
      "was built against Qt 6.0, but the box has Qt $(probe qt_version).*Qt's private API" "$(ob up "$P-q1" --quickshell "$d/b0/quickshell" 2>&1)"
    # The box's Qt, but a library the box lacks.
    sed "s/Qt_6\.0/Qt_$qt/" "$d/old.c" > "$d/same.c"; echo 'int aq(void) { return 0; }' > "$d/miss.c"
    cc -shared -fPIC -Wl,-soname,libomaboxmissing.so.1 -o "$d/lib/libomaboxmissing.so" "$d/miss.c" &&
      cc -fPIC -pie -o "$d/b1/quickshell" "$d/same.c" -l:libQt6Core.so.6 -L"$d/lib" -Wl,--no-as-needed -lomaboxmissing 2>/dev/null
    check_match "...and one needing a library the box lacks" "needs libomaboxmissing.so.1, which the box lacks" \
      "$(ob up "$P-q1" --quickshell "$d/b1/quickshell" 2>&1)"
  else
    skip "builds against another Qt are refused" "no C compiler, or no Qt 6 (libQt6Core)"
  fi
  # A jailed agent (finding 99): as --hyprland's, the folder one of the jail's, whole, or the binary in
  # its project. Past that, --size junk stops `up` before anything starts.
  git -C "$d/proj" init -q
  cp /usr/bin/true "$d/proj/build/quickshell"; cp /usr/bin/true "$d/other/quickshell"
  local J; J=$(jq -nc --arg p "$d/proj" --arg c "$d/proj" '{id: "1 2", net: false, cwd: $c, roots: [{path: $p, masked: false}]}')
  check_match "jail: a build outside the jail's folders is refused" "not in this jail's project nor in a folder it was given whole \(or is not a Quickshell" \
    "$(OMABOX_JAIL=$J "$CLI" up "$P-q2" --quickshell "$d/other/quickshell" --size huge 2>&1)"
  check_match "jail: one in its project passes" "a size is WxH" "$(OMABOX_JAIL=$J "$CLI" up "$P-q2" --quickshell "$d/proj/build/quickshell" --size huge 2>&1)"
  # (relay: --quickshell goes absolute: t_unit_jailed_caller's.)
  # (The version line, from inside the box, every box's, the build's run by its path: install.rs
  # qs_version_as_bash, the box's answers given; #324 wave 6-suite.)
  local left; left=$(ob ls --json | jq -r '.[].name' | grep -c "^$P-q[12]$" || true)
  check_eq "refusals left no box behind" 0 "$left"
}

# finding 358: a box whose shell runs a Quickshell build of its own (a copy of the installed one stands
# in for it): the shell, restarted either way, what calls it by name, the records; a build that is not
# the box's Qt's ends the box as it starts, saying both versions.
t_quickshell() {
  local B=$P-qsb q=$TMP/$P-qsbuild/quickshell S=$P-qss exe
  mkdir -p "${q%/*}"; cp /usr/bin/quickshell "$q"
  exe='p=$(cat "$XDG_RUNTIME_DIR/omabox-shell.pid") && readlink "/proc/$p/exe"'
  check "up --quickshell (a copy of the installed one), shell and bar up" ob up "$B" --quickshell "$q"
  check_box_safety "$B"
  check_eq "the box's shell runs it" "$q" "$(ob run -b "$B" -- sh -c "$exe")"
  check_eq "...and is the box's quickshell and qs by name" "$q $q" "$(ob run -b "$B" -- sh -c 'echo "$(readlink -f "$(command -v quickshell)") $(readlink -f "$(command -v qs)")"')"
  check_fails "...without OMABOX_QUICKSHELL in the session's environment" ob run -b "$B" -- sh -c 'env | grep -q ^OMABOX_QUICKSHELL='
  check_match "ls says so, under its line" "^  Quickshell: $q \(Quickshell [0-9.]+" "$(ob ls | grep -A3 "^$B " | grep '^  Quickshell')"
  check_eq "ls --json has the binary and its version line" "$q true" \
    "$(ob ls --json | jq -r --arg b "$B" '.[] | select(.name == $b) | "\(.quickshell) \(.quickshell_version | test("^Quickshell [0-9]"))"')"
  check_match "windows says so first" "^box $B runs its shell on Quickshell $q \(Quickshell " "$(ob windows -b "$B" | head -n 1)"
  check "restart-shell" ob restart-shell -b "$B"
  check_eq "...keeps it" "$q" "$(ob run -b "$B" -- sh -c "$exe")"
  # Omarchy's own restart (its launcher, through the systemd-cat stand-in), from the box's session.
  ob run -b "$B" -- omarchy-restart-shell >/dev/null 2>&1
  check "...and so does omarchy's restart" until_ok 15 sh -c "[ \"\$('$CLI' run -b '$B' -- sh -c '$exe' 2>/dev/null)\" = '$q' ] && '$CLI' run -b '$B' -- sh -c 'kill -0 \$(cat \$XDG_RUNTIME_DIR/omabox-shell.pid)'"
  check_match "up again with it: the box as it is" "is already up" "$(ob up "$B" --quickshell "$q" 2>&1)"
  check_match "...with another: refused, naming both" "already up, without what you asked for: --quickshell /usr/bin/quickshell \(its shell runs $q\)" \
    "$(ob up "$B" --quickshell /usr/bin/quickshell 2>&1)"
  check "save" sv save "$S" -b "$B"
  check_eq "...records it" "$q" "$(jq -r .quickshell "$TMP/data/omabox/saves/$S/save.json")"
  # (Stopped right after the note by a binary that is no Quickshell build: no box starts.)
  cp /usr/bin/true "${q%/*}/true"
  check_match "...and up --from it on another one notes so" "note: save '$S' was made in a box whose shell ran $q, this one's runs ${q%/*}/true" \
    "$(sv up "$P-qsn" --from "$S" --quickshell "${q%/*}/true" 2>&1)"
  check "down" ob down "$B"
  sv saves rm "$S" >/dev/null 2>&1
  # A build against another patch release of the box's Qt (the binary does not say which): its own
  # --private-check-compat, asked in the box before the session starts, ends the box (a stub of it).
  if command -v cc >/dev/null && [ -n "$(probe qt_box)" ]; then
    local d=$TMP/$P-qscompat; mkdir -p "$d/b"
    printf '%s\n' '#include <stdio.h>' '#include <string.h>' 'extern const char qt_version_tag;' \
      "__asm__(\".symver qt_version_tag, qt_version_tag@Qt_$(probe qt_box)\");" 'const char *const tag = &qt_version_tag;' \
      'int main(int c, char **v) { if (c > 1 && !strcmp(v[1], "--private-check-compat")) {' \
      '  printf("\033[31mCOMPATIBILITY WARNING: Quickshell was built against Qt 6.0.1 but the system has updated to Qt 6.0.2 without rebuilding the package.\n\033[0m"); return 1; }' \
      '  return tag == 0; }' > "$d/c.c"
    cc -fPIC -pie -o "$d/b/quickshell" "$d/c.c" -l:libQt6Core.so.6
    check_match "a build against another Qt patch release: the box ends as it starts, naming both" \
      "died while starting \(--quickshell: built against Qt 6.0.1, the box has Qt 6.0.2" "$(ob up "$P-qsc" --quickshell "$d/b/quickshell" 2>&1)"
    ob down "$P-qsc" >/dev/null 2>&1
  else
    skip "a build against another Qt patch release ends the box" "no C compiler, or no Qt 6 (libQt6Core)"
  fi
}

# finding 91: no global git identity (a fresh machine) is no reason for `up` to fail.
t_no_git_identity() {
  local B=$P-nogit
  check "up with no git identity" env GIT_CONFIG_GLOBAL=/dev/null "$CLI" up "$B" --no-shell
  check_fails "...and the box has none" ob run -b "$B" -- git config --global user.email
  check "down" ob down "$B"
}

# finding 250 (#183): what of a repo's git data `up` mounts besides its top level. A scratch main
# checkout, a linked worktree (a space in its path), a submodule, a worktree of that submodule, a
# worktree whose main checkout is gone, and a dir that is no repo.
t_unit_git_dirs() {
  local M=$TMP/$P-gd-main S=$TMP/$P-gd-sub W="$TMP/$P-gd wt" SW="$TMP/$P-gd subwt" X=$TMP/$P-gd-gone N=$TMP/$P-gd-none r
  gd() { git -c user.name=t -c user.email=t@t -c protocol.file.allow=always "$@" >/dev/null 2>&1; }
  gdirs() { (cd "$1" && probe repo_git_dirs); }
  for r in "$M" "$S" "$X"; do mkdir -p "$r" && gd -C "$r" init -q && echo x > "$r/f" && gd -C "$r" add f && gd -C "$r" commit -qm one; done
  gd -C "$M" worktree add -q -b "$P-gd" "$W"
  gd -C "$M" submodule add -q "$S" sm
  gd -C "$M/sm" worktree add -q -b "$P-gd-sub" "$SW"
  gd -C "$X" worktree add -q -b "$P-gd-gone" "$X-wt"; rm -rf "$X"
  mkdir -p "$N"
  check_eq "a main checkout: nothing (its .git is in it)" "" "$(gdirs "$M")"
  check_eq "a linked worktree: the main checkout's .git alone, which holds its gitdir" "$M/.git" "$(gdirs "$W")"
  check_eq "a submodule: its git dir in the superproject's .git/modules" "$M/.git/modules/sm" "$(gdirs "$M/sm")"
  check_eq "a submodule's worktree: the same" "$M/.git/modules/sm" "$(gdirs "$SW")"
  check_eq "a worktree whose main checkout is gone: nothing, quietly" "" "$(gdirs "$X-wt" 2>&1)"
  check_eq "no repo: nothing" "" "$(gdirs "$N" 2>&1)"
  check_eq "a jailed caller whose jail has no folders: nothing" "" \
    "$(cd "$W" && OMABOX_JAIL='{"roots":[]}' probe repo_git_dirs "$W" 2>&1)"
  # A jailed caller (#193, finding 275): the files git reads, read inside the jail's folders, git never
  # run (a stub that records being run first on PATH). JAIL CWD ROOT...: the jail's policy as
  # jail_policy writes it (ai-jail --worktree maps the common dir and the gitdir inside it: masked).
  local B=$TMP/$P-gd-bin G C=$M/.git jmask=""
  mkdir -p "$B"
  printf '#!/bin/sh\necho "$*" >> %q/git-ran\nexit 1\n' "$TMP/$P-gd" > "$B/git"; chmod +x "$B/git"
  jdirs() {
    local cwd=$1 j; shift
    j=$(jq -nc --arg c "$cwd" --arg m "${jmask:-}" '{net: false, cwd: $c, roots: ($ARGS.positional | map({path: ., masked: false})),
      masks: (if $m == "" then [] else [$m] end)}' --args "$@")
    j=$(jq -c --arg c "$C" '.roots |= map(if .path == $c then .masked = true else . end)' <<<"$j")
    (cd "$cwd" && PATH=$B:$PATH OMABOX_JAIL=$j probe repo_git_dirs 2>&1)
  }
  G=$(sed -n '1s/^gitdir: //p' "$W/.git")
  check_eq "a jailed caller in a linked worktree, its jail sees the common dir (ai-jail --worktree): it" "$C" "$(jdirs "$W" "$W" "$C" "$G")"
  check_eq "...the common dir alone a folder of the jail's: the same" "$C" "$(jdirs "$W" "$W" "$C")"
  # #198 security: a path the jail hides in the common dir (ai-jail --mask on its config) would be the
  # host's in the box, which mounts it from the host. #210: the common dir goes, and `up` covers it
  # (jail_cover); unless git's files read here are hidden, or where a hidden path could have moved.
  jmask=$C/config
  check_eq "...the jail hiding its config: it, to be mounted with that covered (#210)" "$C" "$(jdirs "$W" "$W" "$C" "$G")"
  jmask=$G/commondir
  check_eq "...the jail hiding the gitdir's commondir (read here): nothing" "" "$(jdirs "$W" "$W" "$C" "$G")"
  jmask=$C/hooks/x
  check_eq "...a hidden path below a folder of the common dir, the gitdir in it: nothing (one could be moved to the file read)" "" "$(jdirs "$W" "$W" "$C")"
  check_eq "...the gitdir a folder of the jail's itself (ai-jail --worktree): it" "$C" "$(jdirs "$W" "$W" "$C" "$G")"
  jmask=$W/.git
  check_eq "...the jail hiding the worktree's .git file: nothing" "" "$(jdirs "$W" "$W" "$C" "$G")"
  jmask=$M/other
  check_eq "...a path hidden elsewhere: the common dir still" "$C" "$(jdirs "$W" "$W" "$C" "$G")"
  jmask=""
  check_eq "...the jail does not see it: nothing" "" "$(jdirs "$W" "$W")"
  check_eq "...it sees the gitdir only: nothing" "" "$(jdirs "$W" "$W" "$G")"
  check_eq "...it sees it only inside a folder of its own (the main checkout, which it could swap for a link): nothing" "" "$(jdirs "$W" "$W" "$M")"
  check_eq "...a stale gitdir (the main checkout gone): nothing" "" "$(jdirs "$X-wt" "$X-wt" "$X/.git")"
  check_eq "a jailed caller in a submodule (no commondir): nothing" "" "$(jdirs "$M/sm" "$M/sm" "$M/.git/modules/sm")"
  # What the jail writes in its .git file is the jail's: a gitdir that is no worktree's, or a common dir
  # not named .git (a folder of the jail's whose own masks the box would not have), is nothing.
  local F=$TMP/$P-gd-fake; mkdir -p "$F/w" "$F/root/worktrees/x"
  printf 'gitdir: %s\n' "$F/root/worktrees/x" > "$F/w/.git"; echo ../.. > "$F/root/worktrees/x/commondir"
  check_eq "...a common dir not named .git: nothing" "" "$(jdirs "$F/w" "$F/w" "$F/root")"
  printf 'gitdir: %s\n' "$C" > "$F/w/.git"
  check_eq "...a gitdir that is the common dir itself: nothing" "" "$(jdirs "$F/w" "$F/w" "$C")"
  # (A link out to a link back in: readlink would land in the common dir; the jail cannot follow it.)
  mkdir -p "$F/out"; ln -s "$G" "$F/out/g"; ln -s "$F/out/g" "$F/w/lnk"; printf 'gitdir: lnk\n' > "$F/w/.git"
  check_eq "...a gitdir through a link out of the jail's folders, though it leads back in: nothing" "" "$(jdirs "$F/w" "$F/w" "$C")"
  check_eq "...the same link, the jail seeing where it goes: the common dir" "$C" "$(jdirs "$F/w" "$F/w" "$C" "$F/out")"
  rm "$F/w/lnk" "$F/w/.git"; ln -s "$W/.git" "$F/w/.git"
  check_eq "...a .git that is a link out of the jail's folders: nothing" "" "$(jdirs "$F/w" "$F/w" "$C")"
  check_fails "...and git was never run" test -e "$TMP/$P-gd/git-ran"
}

# finding 250 (#183): a box started from a linked worktree has git there. Its gitdir and the main
# checkout's .git are mounted read-only at their own paths; the main checkout's files are not.
t_git_worktree() {
  local B=$P-gitwt M W out
  M=$(tmp_repo gitwt-main)
  echo main-file > "$M/f"
  git -C "$M" add f && git -C "$M" -c user.name=t -c user.email=t@t commit -qm one
  W="$TMP/$P-gitwt wt"   # a space in its path
  git -C "$M" worktree add -q -b "$P-gitwt" "$W" 2>/dev/null
  out=$(cd "$W" && ob up "$B" --no-shell 2>&1) || { no "up from a linked worktree" "$out"; return; }
  check "git status in the box, on the worktree" ob run -b "$B" -- git -C "$W" status
  check_eq "git describe --always: the host's" "$(git -C "$W" describe --always)" "$(ob run -b "$B" -- git -C "$W" describe --always 2>&1)"
  check_eq "git log: the host's" "$(git -C "$W" log --oneline -1)" "$(ob run -b "$B" -- git -C "$W" log --oneline -1 2>&1)"
  check_eq "git rev-parse --show-toplevel" "$W" "$(ob run -b "$B" -- git -C "$W" rev-parse --show-toplevel 2>&1)"
  check_fails "the main checkout's files outside .git are not in the box" ob run -b "$B" -- test -e "$M/f"
  # (An identity given: without one git fails for that, on a host that set none.)
  check_fails "...its .git is read-only: git cannot commit (intended)" ob run -b "$B" -- env GIT_AUTHOR_NAME=t GIT_AUTHOR_EMAIL=t@t \
    GIT_COMMITTER_NAME=t GIT_COMMITTER_EMAIL=t@t git -C "$W" commit --allow-empty -qm x
  check "down" ob down "$B"
}

# A stale pid (the box died, the pid now belongs to someone else) is never killed or entered.
t_stale_pid() {
  local B=$P-stale D=$XDG_RUNTIME_DIR/omabox/$P-stale
  sleep 300 & local victim=$!
  mkdir -p "$D"
  echo "{\"child-pid\": $victim}" > "$D/info.json"
  echo '{"name": "x", "mode": "headless", "net": "host", "pidns": "pid:[1]"}' > "$D/box.json"
  check_eq "reads dead" dead "$(ob ls --json | jq -r ".[] | select(.name == \"$B\") | .state")"
  check_fails "run refuses to enter it" ob run -b "$B" -- true
  ob down "$B" >/dev/null 2>&1
  check "down did not kill the process that has its pid now" kill -0 "$victim"
  kill "$victim" 2>/dev/null
  # Nor a pasta.pid whose pid is now another process named pasta: pasta never removes its pid file,
  # and a name alone proves nothing (finding 89): box_pasta also wants the command line to name the
  # pid file.
  cp /usr/bin/sleep "$TMP/pasta"
  "$TMP/pasta" 300 & local fake=$!
  mkdir -p "$D"
  echo '{"child-pid": 2}' > "$D/info.json"
  echo '{"name": "x", "mode": "headless", "net": "connected"}' > "$D/box.json"
  echo "$fake" > "$D/pasta.pid"
  check_eq "a stale pasta.pid reads dead" dead "$(ob ls --json | jq -r ".[] | select(.name == \"$B\") | .state")"
  ob down "$B" >/dev/null 2>&1
  check "down did not kill another process named pasta" kill -0 "$fake"
  kill "$fake" 2>/dev/null
  # Nor one whose command line names the pid file as pasta's does, but which is not pasta (its comm).
  bash -c 'sleep 300 & wait' decoy -P "$D/pasta.pid" x & local decoy=$!
  until_ok 5 grep -qF decoy "/proc/$decoy/cmdline"
  mkdir -p "$D"
  echo '{"child-pid": 2}' > "$D/info.json"
  echo '{"name": "x", "mode": "headless", "net": "connected"}' > "$D/box.json"
  echo "$decoy" > "$D/pasta.pid"
  ob down "$B" >/dev/null 2>&1
  check "down did not kill a process that only names the pid file" kill -0 "$decoy"
  pkill -P "$decoy"; kill "$decoy" 2>/dev/null
}

# Finding 584: a box's HOME (on disk, in the cache) goes only once its box is gone in the runtime dir it
# was made in, and never while a box uses it. An `up` with another runtime dir (a test's stand-in,
# another login) and the same cache took every box of this one as gone and removed their HOMEs while
# they ran. Every box here keeps its HOME in a cache of the test's own.
t_home_sweep() {
  local B=$P-hs c=$TMP/hs-cache rt=$TMP/hs-rt st=$TMP/hs-state out rc
  mkdir -p "$c" "$rt" "$st"; chmod 700 "$rt"
  hs() { XDG_CACHE_HOME=$c "$CLI" "$@"; }
  hs2() { XDG_CACHE_HOME=$c XDG_RUNTIME_DIR=$rt XDG_STATE_HOME=$st "$CLI" "$@"; }
  check "up, its HOME in the test's own cache" hs up "$B" --no-shell
  local H=$c/omabox/$B/home
  hs run -b "$B" -- sh -c 'echo kept > "$HOME/mark"' >/dev/null 2>&1
  check_eq "...the box writes its HOME" kept "$(cat "$H/mark" 2>&1)"
  # What a sweep may take: a HOME whose box is gone in the runtime dir it was made in (neither this one
  # nor the next up's), and an older omabox's (no record of it) whose box is gone and unused.
  mkdir -p "$c/omabox/$P-hsgone/home" "$c/omabox/$P-hsold/home"
  printf '%s\n' "$TMP/hs-gone-rt/omabox/$P-hsgone" > "$c/omabox/$P-hsgone/box-dir"
  check "an up with another runtime dir (and state), the same cache" hs2 up "$B-2" --no-shell
  check_eq "...leaves the first box's HOME as it was" kept "$(cat "$H/mark" 2>&1)"
  check_eq "...which that box still reads" kept "$(hs run -b "$B" -- sh -c 'cat "$HOME/mark"' 2>&1)"
  check_fails "...and takes a HOME whose box is gone where it was made" test -e "$c/omabox/$P-hsgone"
  check_fails "...and an older omabox's whose box is gone and unused" test -e "$c/omabox/$P-hsold"
  check "...its own box comes down" hs2 down "$B-2"
  # The same name from there: the HOME is the running box's, so that up is refused and changes nothing.
  rc=0; out=$(hs2 up "$B" --no-shell 2>&1) || rc=$?
  check_eq "an up of the same name from another runtime dir is refused" 1 "$rc"
  check_match "...saying whose HOME it is" "box '$B''s HOME .* is a box's in $XDG_RUNTIME_DIR/omabox" "$out"
  check_fails "...no box made there" test -e "$rt/omabox/$B"
  check_eq "...the HOME as it was" kept "$(cat "$H/mark" 2>&1)"
  # A HOME an older omabox made has no record of its runtime dir: while its box uses it, it stays.
  rm -f "$c/omabox/$B/box-dir"
  check "an older omabox's box (its HOME's record taken away): an up from another runtime dir" hs2 up "$B-3" --no-shell
  check_eq "...leaves that HOME, which its box uses" kept "$(cat "$H/mark" 2>&1)"
  check "...its own box comes down" hs2 down "$B-3"
  rc=0; out=$(hs2 up "$B" --no-shell 2>&1) || rc=$?
  check_eq "...and its name from there is refused too" "1" "$rc"
  check_match "...saying the HOME is in use" "box '$B''s HOME .* is in use" "$out"
  check_eq "...the HOME as it was" kept "$(cat "$H/mark" 2>&1)"
  check "down" hs down "$B"
  check_fails "...takes its own HOME" test -e "$c/omabox/$B"
  # (what may be left of a refused or failed check's boxes)
  hs2 down "$B-2" >/dev/null 2>&1; hs2 down "$B-3" >/dev/null 2>&1; hs2 down "$B" >/dev/null 2>&1
}

# #220: a headless box at --idle 0 with no agent or owner has no reaper. `ls` calls it an orphan once
# what started it is gone, `down --orphans` takes it down, and nothing else does. Four boxes: one up
# from a script that exits (an orphan at once), one from a script that stays (not one, then one once it
# is killed), one with an idle limit and one started at a terminal (never one).
t_orphan() {
  local A=$P-or-a B=$P-or-b C=$P-or-c T=$P-or-t bd=$XDG_RUNTIME_DIR/omabox
  printf '%s\n' 'echo "$$" > "$1.pid"' '"$2" up "$3" --no-shell --net isolated "${@:4}" </dev/null >/dev/null 2>"$1.err"' 'true' > "$TMP/or-short.sh"
  printf '%s\n' 'echo "$$" > "$1.pid"' '"$2" up "$3" --no-shell --net isolated --idle 0 </dev/null >/dev/null 2>"$1.err"' 'exec sleep 300' > "$TMP/or-long.sh"
  orphan_of() { "$CLI" ls --json | jq -r --arg n "$1" '[.[] | select(.name == $n) | if .orphan then "orphan" else .state end][0] // "gone"'; }
  idle_col() { "$CLI" ls 2>/dev/null | awk -v n="$1" '$1 == n { print $7 }'; }
  bash "$TMP/or-short.sh" "$TMP/or-a" "$CLI" "$A" --idle 0
  bash "$TMP/or-long.sh" "$TMP/or-b" "$CLI" "$B" & local holder=$!
  bash "$TMP/or-short.sh" "$TMP/or-c" "$CLI" "$C" --idle 30m
  # A person at a terminal: up's stdin a terminal (script(1)'s), outside any agent session.
  bash -c 'script -qec "$1 up $2 --no-shell --net isolated --idle 0" /dev/null </dev/null >"$3" 2>&1; true' _ "$CLI" "$T" "$TMP/or-t.err"
  check "the boxes start" until_ok 40 bash -c "[ -s '$TMP/or-b.err' ] && jq -e .pidns '$bd/$A/box.json' '$bd/$B/box.json' '$bd/$C/box.json' '$bd/$T/box.json' >/dev/null"
  check_eq "up records its starter: the script that ran it" "$(cat "$TMP/or-a.pid") bash false" \
    "$(jq -r '.starter | "\(.pid) \(.command) \(.terminal)"' "$bd/$A/box.json")"
  check_match "up --idle 0 with no agent says nothing takes the box down but down" \
    "note: box '$A' has no idle limit and goes with no agent: nothing takes it down but omabox down $A; once what started it \(bash, pid $(cat "$TMP/or-a.pid")\) is gone, ls calls it an orphan" \
    "$(cat "$TMP/or-a.err")"
  check_fails "...not with an idle limit" grep -q 'no idle limit' "$TMP/or-c.err"
  check_eq "its starter gone: ls --json says orphan" orphan "$(orphan_of "$A")"
  check_eq "...and ls, under IDLE" orphan "$(idle_col "$A")"
  check_match "...naming it on stderr with what takes it down" "orphan: .*$A.*omabox down --orphans does" "$("$CLI" ls 2>&1 >/dev/null)"
  check_eq "its starter still running: not an orphan" up "$(orphan_of "$B")"
  check_eq "...ls says never" never "$(idle_col "$B")"
  check_eq "an idle limit, its starter gone: not an orphan" up "$(orphan_of "$C")"
  check_eq "started at a terminal (a person's), its starter gone: not an orphan" "up true" \
    "$(orphan_of "$T") $(jq -r .starter.terminal "$bd/$T/box.json")"
  check "...its up said so at the terminal" grep -q "box '$T' up (" "$TMP/or-t.err"
  check_fails "...without the note" grep -q 'no idle limit' "$TMP/or-t.err"
  kill "$holder" 2>/dev/null; wait "$holder" 2>/dev/null
  check_eq "the starter killed: an orphan now" orphan "$(orphan_of "$B")"
  check_eq "...and nothing takes it down by itself (no reaper)" "up up 0" \
    "$("$CLI" ls --json | jq -r --arg a "$A" --arg b "$B" '[.[] | select(.name == $a or .name == $b) | .state] | join(" ")') $(pgrep -fc "omabox _reap ($A|$B) ")"
  # down --orphans takes every orphan of the user's: not when one up is not this run's.
  local others; others=$("$CLI" ls --json | jq -r --arg p "$P-or-" '.[] | select(.orphan and (.name | startswith($p) | not)) | .name')
  if [ -n "$others" ]; then
    skip "down --orphans" "orphans up that are not this test's (${others//$'\n'/ }): it would take them down too"
  else
    local out; out=$("$CLI" down --orphans 2>&1)
    check_match "down --orphans names each orphan and its starter" "box '$A': an orphan \(no idle limit; what started it, bash, pid [0-9]+, is gone\): taking it down" "$out"
    check_match "...takes them down" "box '$B' down" "$out"
    check_eq "...them only" "gone gone up up" "$(orphan_of "$A") $(orphan_of "$B") $(orphan_of "$C") $(orphan_of "$T")"
  fi
  ob down "$A" "$B" "$C" "$T" >/dev/null 2>&1
}

# An up killed once its box started (SIGKILL: no EXIT trap; a killed suite run, a harness's timeout)
# left a box with no reaper, up for good (#137). Its reaper starts with the box now, and does not
# count a slow start as idle time.
t_up_killed() {
  local B=$P-uk
  "$CLI" up "$B" --idle 20s --net isolated >/dev/null 2>"$TMP/uk.err" & local up=$!   # $!: omabox itself, not a subshell
  until_ok 30 jq -e .pidns "$XDG_RUNTIME_DIR/omabox/$B/box.json" >/dev/null
  kill -KILL "$up" 2>/dev/null; wait "$up" 2>/dev/null
  check_fails "the up killed once its box started, before it was done" grep -q "box '$B' up (" "$TMP/uk.err"
  check "...its box has a reaper all the same (#137)" until_ok 3 pgrep -f "omabox _reap $B "
  # shellcheck disable=SC2329 # called through until_ok
  gone() { ! "$CLI" ls --json | jq -e --arg n "$B" '.[] | select(.name == $n)' >/dev/null; }
  check "...which takes it down at its idle limit" until_ok 60 gone
  ob down "$B" >/dev/null 2>&1
  # Finding 237: killed sooner, once bwrap has started (info.json) but before up has found the box's
  # PID 1 and recorded its pid namespace (up waits up to 10 s for that): stopped there, then killed.
  B=$P-uk3
  local bd=$XDG_RUNTIME_DIR/omabox/$B end=$((SECONDS + 30))
  "$CLI" up "$B" --idle 20s --no-shell --net isolated >/dev/null 2>&1 & up=$!
  until [ -s "$bd/info.json" ] || [ "$SECONDS" -ge "$end" ]; do sleep 0.002; done
  kill -STOP "$up" 2>/dev/null
  if [ ! -s "$bd/info.json" ]; then no "up ($B): bwrap started" "no info.json in 30 s"
  elif jq -e .pidns "$bd/box.json" >/dev/null 2>&1; then
    kill -KILL "$up" 2>/dev/null
    skip "an up killed before it recorded its box's pid namespace" "it recorded it before it could be stopped (load)"
  else
    kill -KILL "$up" 2>/dev/null
    check "an up killed before it recorded its box's pid namespace: the box has a reaper (finding 237)" until_ok 3 pgrep -f "omabox _reap $B "
    check "...which records it" until_ok 20 jq -e .pidns "$bd/box.json"
    check "...and takes the box down at its idle limit" until_ok 60 gone
  fi
  ob down "$B" >/dev/null 2>&1
  # While its up still runs (here: this shell, as up writes itself in `starting`), idle time is not
  # counted; once that process is gone, it is.
  B=$P-uk2
  up_ok "$B" --idle 20s --no-shell --net isolated || { no "up" "$UP_OUT"; return; }
  local D; D=$(ob path "$B")
  sleep 30 & local starter=$!
  echo "$starter $(probe proc_start "$starter")" > "$D/starting"; touch -d '-1 hour' "$D/used"
  check "a box whose up still runs is not idle, whatever its last use" holds 12 bash -c "'$CLI' ls --json | jq -e --arg n '$B' '.[] | select(.name == \$n and .state == \"up\")'"
  kill "$starter" 2>/dev/null; wait "$starter" 2>/dev/null
  check "...its up gone, the idle limit counts" until_ok 20 gone
  ob down "$B" >/dev/null 2>&1
}

# An isolated box whose host pid file is missing is still taken down (finding 63).
t_isolated_no_pidfile() {
  local B=$P-isopid
  check "up --net isolated" ob up "$B" --net isolated --no-shell
  rm -f "$XDG_RUNTIME_DIR/omabox/$B/pid"
  check "down" ob down "$B"
  check "nothing of it left running" until_ok 5 none_running "$B"
}

# `run` into a box counts as use; after it expires, `run` says so instead of starting a throwaway.
t_run_idle() {
  local repo=$TMP/$P-exp
  mkdir -p "$repo" && git -C "$repo" init -q
  # 15 s: a run every 3 s, and room for one slow under load (#116: 10 s left a gap near the limit).
  (cd "$repo" && "$CLI" up --idle 15s --no-shell --net isolated >/dev/null 2>&1)
  for _ in 1 2 3 4 5; do (cd "$repo" && "$CLI" run -- true); sleep 3; done
  check "a box used only through run stays up" bash -c "'$CLI' ls --json | jq -e '.[] | select(.name == \"$P-exp\" and .state == \"up\")'"
  until_ok 40 bash -c "! '$CLI' ls --json | jq -e '.[] | select(.name == \"$P-exp\")'"
  held "$P-exp" check_match "after expiry run reports it (no throwaway)" "went down after 15s idle" "$(cd "$repo" && "$CLI" run -- true 2>&1)"
  ob down "$P-exp" >/dev/null 2>&1
}

# A throwaway run from ~ (no repo) does not put HOME in the box (finding 63).
t_throwaway_home() {
  # From ~ (no repo) the throwaway is named after "default": a box of the user's with that name
  # would take the run instead.
  # An expiry note from a 'default' box that idled out makes `run` refuse the same way.
  if [ -e "$XDG_RUNTIME_DIR/omabox/default" ] || [ -e "$XDG_RUNTIME_DIR/omabox/.expired-default" ]; then
    no "a box named 'default' is up or idled out: run it again after omabox down default"; return
  fi
  local out; out=$(cd "$HOME" && env -u OMABOX "$CLI" run -- sh -c "test -e '$HOME/.config' && echo LEAK || echo ok; pwd" 2>&1)
  # (run's note that the box has no $HOME/.config, #301, goes before the command's own output)
  check_match "HOME not visible in a throwaway run from ~" '^ok' "$(grep -v '^omabox: note: ' <<<"$out")"
  check_match "it runs in the box HOME" '/home/sbx$' "$out"
}

# A throwaway run killed outright (SIGKILL: no EXIT trap) does not leave its box behind.
t_throwaway_killed() {
  local repo; repo=$(tmp_repo tk)
  (cd "$repo" && exec env -u OMABOX "$CLI" run -- sleep 300) & local r=$!
  until_ok 30 bash -c "'$CLI' ls --json | jq -e '.[] | select(.name | startswith(\"$P-tk-run\"))'"
  local j=("$XDG_RUNTIME_DIR"/omabox/"$P"-tk-run*/box.json)
  check "its box.json records its owner's start time (a reused pid is not it)" \
    jq -e --arg s "$(probe proc_start "$r")" '.owner_start == $s and $s != ""' "${j[0]}"
  # Where the time goes, kept for a failure (#222: 20 s under the full suite's load, 4-5 s otherwise):
  # every 0.25 s from the kill, its up (`starting`) and the reaper's last word. The box dir goes with
  # the box, its reap.log too.
  local d=${j[0]%/box.json} tl=$TMP/tk-timeline
  kill -KILL "$r"; wait "$r" 2>/dev/null   # reaped here: no "Killed" job line from bash later
  (t0=$(date +%s%3N); while [ -d "$d" ]; do
     printf '%s ms: starting=[%s] reap=[%s]\n' $(($(date +%s%3N) - t0)) "$(cat "$d/starting" 2>/dev/null)" "$(tail -n 1 "$d/reap.log" 2>/dev/null)"
     sleep 0.25; done) > "$tl" 2>&1 & local tp=$!
  if until_ok 15 bash -c "! '$CLI' ls --json | jq -e '.[] | select(.name | startswith(\"$P-tk-run\"))'" >/dev/null; then ok "its box goes within 15 s"
  else no "its box goes within 15 s" "$(uniq -f 2 "$tl" | tail -n 30)"; fi
  kill "$tp" 2>/dev/null; wait "$tp" 2>/dev/null
}

# (An up whose `omabox run` is gone, #222, finding 309: ready.rs up_stops_when_its_run_is_gone,
# #324 wave 6-suite.)

# The keyboard and pointer tools (finding 64): keys named as binds name them, input checked before any
# of it is sent, spare keycodes X11 apps can see, and a lost box is a failure.
t_keys() {
  local B=$P-keys
  up_ok "$B" --no-shell --net isolated --xwayland || { no "up" "$UP_OUT"; return; }
  check_box_safety "$B"
  # #211: labwc holds no X display now, so Hyprland's Xwayland is :0 (it was :1, behind labwc's lazy one).
  check_eq "--xwayland: run's DISPLAY is Hyprland's Xwayland on :0" ":0" "$(ob run -b "$B" -- printenv DISPLAY 2>&1)"
  # #294 (finding 407): Hyprland starts it with -core, which raised its soft core limit to the hard one
  # (unlimited): a box going down made it abort with a core the desktop announced. Now 1 byte, hard too.
  check_match "...its core limit stays 1 byte, the hard one too (its -core raised it)" "^Max core file size +1 +1 +bytes" \
    "$(ob run -b "$B" -- sh -c 'p=$(pidof Xwayland) && grep "^Max core file size" "/proc/$p/limits"' 2>&1)"
  ob hyprctl -b "$B" eval "hl.bind('SUPER + CTRL + ALT + J', hl.dsp.exec_cmd('touch /tmp/lower'))
    hl.bind('SUPER + CTRL + ALT + SHIFT + J', hl.dsp.exec_cmd('touch /tmp/upper'))
    hl.bind('SUPER + CTRL + ALT + slash', hl.dsp.exec_cmd('touch /tmp/slash'))" >/dev/null
  ob keys -b "$B" SUPER+CTRL+ALT+J super+ctrl+alt+/ >/dev/null
  check "SUPER+CTRL+ALT+J fires the J bind" until_ok 3 ob run -b "$B" -- test -e /tmp/lower
  check_fails "...not the SHIFT+J one" ob run -b "$B" -- test -e /tmp/upper
  check "a single-character key (super+ctrl+alt+/)" ob run -b "$B" -- test -e /tmp/slash
  ob run -b "$B" -d -- foot sh -c 'cat > /tmp/typed' >/dev/null
  until_ok 10 bash -c "'$CLI' hyprctl -b '$B' -j activewindow | jq -e '.class == \"foot\"'"
  check_fails "a bad token fails" ob keys -b "$B" x no_such_key
  check_eq "junk -s refused (was 49 days)" 2 "$(timeout 5 "$CLI" keys -b "$B" -s -1 >/dev/null 2>&1; echo $?)"
  check_eq "junk -s refused (was 0)" 2 "$(ob keys -b "$B" -s abc x >/dev/null 2>&1; echo $?)"
  check_eq "junk --delay refused" 2 "$(ob keys -b "$B" --delay -1 x >/dev/null 2>&1; echo $?)"
  check_match "bad UTF-8 refused" "bad UTF-8" "$(ob keys -b "$B" -t $'\xe9x' 2>&1)"
  # Control characters (#104, finding 173): xkb maps them to keys (BackSpace, Escape, Delete, Return).
  check_eq "a control character in -t refused: exit 2" 2 "$(ob keys -b "$B" -t $'ab\x08c' >/dev/null 2>&1; echo $?)"
  check_match "...said, with where" "control character \(U\+0008\) at byte 2; only newline and tab are typed" "$(ob keys -b "$B" -t $'ab\x08c' 2>&1)"
  check_eq "...escape, delete and a carriage return too" "2 2 2" "$(for c in $'\x1b' $'\x7f' $'\r'; do ob keys -b "$B" -t "x${c}y" >/dev/null 2>&1; printf '%s ' $?; done | xargs)"
  check_eq "...in a --pass value too" 2 "$(T_BS=$'a\x08b' "$CLI" keys -b "$B" --pass T_BS >/dev/null 2>&1; echo $?)"
  ob keys -b "$B" --active + - / shift+a -t $'\t1' Return ctrl+d >/dev/null
  until_ok 5 ob run -b "$B" -- test -s /tmp/typed
  check_eq "+ - / and a tab typed (to --active, #273), nothing from the refused runs" $'+-/A\t1' "$(ob run -b "$B" -- cat /tmp/typed)"
  # keys --pass (finding 84): the caller's variable is typed, and no process's argv has it meanwhile.
  ob run -b "$B" -d -- foot sh -c 'cat > /tmp/secret' >/dev/null
  until_ok 10 bash -c "'$CLI' hyprctl -b '$B' -j clients | jq -e '[.[] | select(.class == \"foot\")] | length == 1'"
  local seen=""
  T_PW="pw-$P x=y Ü" T_CR=$'cr\r' "$CLI" keys -b "$B" -t a --pass T_PW -s 1500ms -t -T --pass T_PW --pass T_CR Return ctrl+d & local kp=$!
  if until_ok 10 pgrep -f 'omabox-keyboard .* -T -s 1500'; then
    seen=$(grep -l "pw-$P" /proc/[0-9]*/cmdline 2>/dev/null)
    check_eq "keys --pass: the value is in no /proc/*/cmdline while typing" "" "$seen"
  else no "keys --pass: the keyboard ran (to scan while typing)"; fi
  wait "$kp"; check_eq "keys --pass exits 0" 0 $?
  until_ok 5 ob run -b "$B" -- test -s /tmp/secret
  check_eq "keys --pass types the value, in order with -t (and -t -T is text; a trailing \\r dropped, not a Return)" "apw-$P x=y Ü-Tpw-$P x=y Ücr"$'\n.' "$(ob run -b "$B" -- sh -c 'cat /tmp/secret; echo .')"
  check_match "keys --pass: an unset variable refused" "not in this command's environment" "$(env -u T_NONE "$CLI" keys -b "$B" --pass T_NONE 2>&1)"
  check_match "keys --pass: a bad name refused" "takes a variable name" "$(ob keys -b "$B" --pass 'a b' 2>&1)"
  if command -v zenity >/dev/null; then
    ob run -b "$B" -d -- sh -c 'GDK_BACKEND=x11 zenity --entry --text t > /tmp/x11' >/dev/null
    until_ok 15 bash -c "'$CLI' hyprctl -b '$B' -j activewindow | jq -e '.class == \"zenity\" and .xwayland'"
    sleep 1   # mapped is not yet taking keys
    # € too (#85: it did not arrive here in 2026-09, with Ü and α on the same kind of spare keycode).
    ob keys -b "$B" -t 'aÜb€α😀' -s 300ms Return >/dev/null
    until_ok 5 ob run -b "$B" -- test -s /tmp/x11
    check_eq "an X11 app gets characters outside the layout" 'aÜb€α😀' "$(ob run -b "$B" -- cat /tmp/x11)"
  else skip "an X11 app gets characters outside the layout" "no zenity"; fi
  check "pointer: click, then move" ob pointer -b "$B" -- click move 10 10
  check_eq "pointer: sleep -1 refused" 2 "$(timeout 5 "$CLI" pointer -b "$B" -- sleep -1 >/dev/null 2>&1; echo $?)"
  # A compositor alive but stopped (#108, finding 177): each tool gives up after 10 s with exit 3
  # instead of waiting forever (timeout 40: on the old tools, 124). Stopped once they are past the
  # CLI's own hyprctl calls, in their -s / sleep.
  timeout 40 "$CLI" keys -b "$B" -s 3003ms a >/dev/null 2>"$TMP/stop.k" & local k=$!
  timeout 40 "$CLI" pointer -b "$B" -- sleep 3004ms move 10 10 >/dev/null 2>"$TMP/stop.p" & local p=$!
  until_ok 10 pgrep -f 'omabox-keyboard .* -s 3003 a$' >/dev/null; until_ok 10 pgrep -f 'omabox-pointer .* sleep 3004 ' >/dev/null
  ob run -b "$B" -- sh -c 'kill -STOP $(pidof Hyprland)'
  local t0=$SECONDS rk=0 rp=0
  wait "$k" || rk=$?; wait "$p" || rp=$?
  local took=$((SECONDS - t0))
  ob run -b "$B" -- sh -c 'kill -CONT $(pidof Hyprland)'
  check_eq "keys and pointer give up on a stopped compositor: exit 3" "3 3" "$rk $rp"
  check_match "...said" "keyboard: .*no answer in 10 s.*pointer: .*no answer in 10 s" "$(cat "$TMP/stop.k" "$TMP/stop.p" | tr '\n' ' ')"
  check "...in about 10 s ($took s after the stop)" test "$took" -le 16
  check "...and the box answers again once it goes on" until_ok 10 ob keys -b "$B" shift
  ob keys -b "$B" -s 3001ms a >/dev/null 2>&1 & k=$!
  ob pointer -b "$B" -- sleep 3002ms move 10 10 >/dev/null 2>&1 & p=$!
  # (#110) Once each tool runs in the box: before that, "not up" is exit 1 too.
  until_ok 10 pgrep -f 'omabox-keyboard .* -s 3001 a$' >/dev/null; until_ok 10 pgrep -f 'omabox-pointer .* sleep 3002 ' >/dev/null
  ob down "$B" >/dev/null
  wait "$k"; check_eq "keys exits 1 when the box goes mid-run" 1 $?
  wait "$p"; check_eq "pointer exits 1 when the box goes mid-run" 1 $?
}

# keys --window and a layer with the keyboard (#201, finding 276): Omarchy's launcher, open on one
# monitor, keeps it against a terminal on the other (exclusive): refused before anything is sent or
# focused. Closed with the pointer over no window, it leaves the terminal active without the keyboard,
# as an on-demand layer clicked does: keys --window focuses the active window again, the pointer kept.
t_keys_layer() {
  local B=$P-kl D out rc pos l
  up_ok "$B" --net isolated --monitor 1080x1920 || { no "up" "$UP_OUT"; return; }
  D=$(ob path -b "$B")
  ob click -b "$B" 2400 900 >/dev/null   # the second monitor: the terminal opens there
  ob run -b "$B" -d -q -- foot -T K sh -c 'cat > /tmp/typed'
  ob wait -b "$B" window 'title:^K$' >/dev/null 2>&1
  check_eq "the terminal is on the second monitor" true "$(ob windows -b "$B" --json | jq '.[] | select(.title == "K") | .at[0] >= 1920')"
  ob click -b "$B" 960 540 >/dev/null
  ob keys -b "$B" super+space >/dev/null
  if ! ob wait -b "$B" layer omarchy-menu >/dev/null 2>&1; then no "the launcher opens (super+space)" "no omarchy-menu layer"; ob down "$B" >/dev/null; return; fi
  pos=$(ob hyprctl -b "$B" cursorpos)
  out=$(ob keys -b "$B" --window 'title:^K$' -t 'echo hi' Return 2>&1); rc=$?
  check_eq "keys --window with the launcher open: refused, exit 1" 1 "$rc"
  check_match "...said: the launcher's layer has the keyboard, nothing sent" \
    "keys --window: a layer \(omarchy-menu\) has the keyboard: the keys would go to it, not to 0x[0-9a-f]+ foot \"K\"; nothing sent" "$out"
  check_eq "...the terminal not focused (a focus would have moved the pointer to it)" "$pos" "$(ob hyprctl -b "$B" cursorpos)"
  ob keys -b "$B" Escape >/dev/null
  # With text in its field, the first Escape only clears it.
  check "...the launcher's field untouched: one Escape closes it" ob wait -b "$B" --timeout 3s layer omarchy-menu --gone
  check "...then keys --window to the terminal, still the active window, goes on" ob keys -b "$B" --window 'title:^K$' -t hi Return
  check_eq "...the pointer left where it was" "$pos" "$(ob hyprctl -b "$B" cursorpos)"
  # An overlay with the keyboard on demand, given it by a click; the terminal stays the active window.
  cat > "$D/home/t201.qml" <<'QML'
import QtQuick
import Quickshell
import Quickshell.Wayland
PanelWindow {
  anchors { top: true; left: true }
  implicitWidth: 300; implicitHeight: 80
  WlrLayershell.layer: WlrLayer.Overlay
  WlrLayershell.namespace: "t201-od"
  WlrLayershell.keyboardFocus: WlrKeyboardFocus.OnDemand
  TextInput { anchors.fill: parent; focus: true; font.pixelSize: 30 }
}
QML
  ob run -b "$B" -d -q -- qs -p /home/sbx/t201.qml >/dev/null 2>&1
  if ob wait -b "$B" layer t201-od >/dev/null 2>&1; then
    l=$(ob hyprctl -b "$B" -j layers | jq -r '[.[].levels[][] | select(.namespace == "t201-od")][0] | "\(.x + 150) \(.y + 40)"')
    # shellcheck disable=SC2086 # X Y
    ob click -b "$B" $l >/dev/null
    check_eq "an on-demand layer clicked: the terminal is still the active window" K "$(ob hyprctl -b "$B" -j activewindow | jq -r .title)"
    check "...keys --window to it goes on" ob keys -b "$B" --window 'title:^K$' -t od Return ctrl+d
  else no "an on-demand layer maps" "no t201-od layer"; ob keys -b "$B" --window 'title:^K$' ctrl+d >/dev/null 2>&1; fi
  check "with the launcher closed, keys --window types into the terminal" until_ok 5 ob run -b "$B" -- test -s /tmp/typed
  check_eq "...what was typed: nothing from the refused run, both texts after it in the terminal" $'hi\nod' "$(ob run -b "$B" -- cat /tmp/typed)"
  ob down "$B" >/dev/null
}

# An action's --wait says what changed on the desktop (#274), in a box: a window run -d opens, one a
# key opens, a layer a click opens; a 124 says where the keys and the click went and that nothing moved.
t_wait_facts() {
  local B=$P-wf D out rc l
  up_ok "$B" --no-shell --net isolated || { no "up" "$UP_OUT"; return; }
  D=$(ob path -b "$B")
  out=$(ob run -b "$B" -d -q --wait -- foot -T F sh -c 'read x; exec foot -T G sleep 600' 2>&1); rc=$?
  check_eq "run -d --wait: settled" 0 "$rc"
  check_match "...said: its window opened, focused" '^satisfied: settled after .*; window opened, focused: foot "F"$' "$out"
  out=$(ob keys -b "$B" --window 'title:^F$' --wait Return 2>&1); rc=$?
  check_eq "keys --wait that opens a window: settled" 0 "$rc"
  check_match "...said: the window it opened, focused" '^satisfied: settled after .*; window opened, focused: foot "G"$' "$out"
  out=$(ob keys -b "$B" --wait --timeout 1s --json shift 2>/dev/null); rc=$?
  check_eq "keys --wait that changes nothing: 124" 124 "$rc"
  check_match "...says where the keys went and that nothing moved" \
    '^nothing changed in 1\.[0-9]+s.*; the keys went to foot "G" \(focused\); no window, layer or focus changed$' "$(jq -r .message <<<"$out")"
  check_eq "...--json: no changes, the target window" '[] window G' "$(jq -r '"\(.changes) \(.target.kind) \(.target.window.title)"' <<<"$out")"
  check "...and where the events from before the keys are" jq -e '.events_since | numbers' <<<"$out"
  out=$(ob keys -b "$B" --wait --timeout 1s shift 2>&1 >/dev/null)
  check_eq "...stderr: look before sending again" "omabox: the keys were sent all the same (124 is about the screen): look before sending anything again" "$out"
  # A layer surface (a button) that opens another (its menu) when clicked.
  cat > "$D/home/t274.qml" <<'QML'
import QtQuick
import Quickshell
import Quickshell.Wayland
ShellRoot {
  PanelWindow {
    anchors { top: true; left: true }
    implicitWidth: 200; implicitHeight: 80
    WlrLayershell.layer: WlrLayer.Top
    WlrLayershell.namespace: "t274-button"
    Rectangle { anchors.fill: parent; color: "steelblue" }
    MouseArea { anchors.fill: parent; onClicked: menu.visible = true }
  }
  PanelWindow {
    id: menu
    visible: false
    anchors { top: true; left: true }
    margins { top: 100; left: 0 }
    implicitWidth: 300; implicitHeight: 300
    WlrLayershell.layer: WlrLayer.Top
    WlrLayershell.namespace: "t274-menu"
    Rectangle { anchors.fill: parent; color: "darkorange" }
  }
}
QML
  ob run -b "$B" -d -q -- qs -p /home/sbx/t274.qml >/dev/null 2>&1
  if ob wait -b "$B" layer t274-button >/dev/null 2>&1; then
    l=$(ob hyprctl -b "$B" -j layers | jq -r '[.[].levels[][] | select(.namespace == "t274-button")][0] | "\(.x + 100) \(.y + 40)"')
    # shellcheck disable=SC2086 # X Y
    out=$(ob click -b "$B" --wait $l 2>"$TMP/wf.err"); rc=$?
    check_eq "click --wait that opens a menu layer: settled" 0 "$rc"
    check_match "...said: the layer opened" '^satisfied: settled after .*; layer t274-menu opened$' "$out"
    check_match "...the button layer said over the window before the click (#361)" \
      "a layer surface \"t274-button\" \(top 200x80 at [0-9]+,[0-9]+\) is over the screen's ${l/ /,}, on window 0x[0-9a-f]+ foot \"F\"" "$(cat "$TMP/wf.err")"
    # shellcheck disable=SC2086 # X Y
    out=$(ob click -b "$B" --wait --timeout 1s $l 2>/dev/null); rc=$?
    check_eq "click --wait that changes nothing: 124" 124 "$rc"
    check_match "...says what was under the click and that nothing moved" \
      "^unsatisfied: nothing changed in 1\.[0-9]+s.*; the click at ${l/ /,} was on layer t274-button \(over foot \"F\"\); no window, layer or focus changed$" "$out"
  else no "the button layer maps" "no t274-button layer"; fi
  ob down "$B" >/dev/null
}

# A layer surface over the point a --window click aims at (#263): the Omarchy shell's notification
# toasts sit in a layer that spans the screen and takes input on the toasts only (findings 398, 421):
# possibly over the points it spans, said as a may, never refused, the click sent (on the toast it
# lands there, which closes it); `windows` and a 124 name it as possible. Omarchy 4.0's is a
# full-screen overlay, up while a toast shows; 4.5's a 465 px column at the right, mapped while idle
# beside a dock along the bottom (the same kind of layer). A smaller layer (a panel stub) is over the
# point for certain, even under a spanning one: refused under --no-raise. Without one, nothing is said.
t_click_layer() {
  local B=$P-cl D out rc w at x y px py fx fy live
  up_ok "$B" --net isolated --stock-bar "${OM[@]}" || { no "up" "$UP_OUT"; return; }
  D=$(ob path -b "$B")
  live=$D/home/.local/state/omarchy/notifications/live.json
  ob run -b "$B" -d -q -- foot -T L sh -c 'cat > /dev/null'
  ob wait -b "$B" window 'title:^L$' >/dev/null 2>&1
  out=$(ob click -b "$B" --window 'title:^L$' --no-raise 20 20 2>&1); rc=$?
  check_eq "no toast: --no-raise clicks, nothing said" "0 " "$rc $out"
  at=$(ob windows -b "$B" --json | jq -r '.[] | select(.title == "L") | "\(.at[0]) \(.at[1])"')
  out=$(ob click -b "$B" $((${at% *} + 20)) $((${at#* } + 20)) 2>&1); rc=$?
  check_eq "...a click at the screen's X Y on it: nothing said either (#361)" "0 " "$rc $out"
  ob run -b "$B" -- notify-send -t 120000 T263 "a toast over the window"
  if ! ob wait -b "$B" layer omarchy-notifications >/dev/null 2>&1; then no "the toast shows" "no omarchy-notifications layer"; ob down "$B" >/dev/null; return; fi
  # 4.5 keeps the layer mapped with no toast: its toasts on screen are in live.json.
  if omarchy45; then check "the toast shows (live.json)" until_ok 5 jq -e 'length == 1' "$live"; fi
  # The toast sits at the screen's top right: window coordinates of a point in it (x y), and of one
  # far below it that the layer still spans (fx fy: 1700,600 on the screen).
  w=$(ob windows -b "$B" --json | jq -c '.[] | select(.title == "L")')
  at=$(jq -r '"\(.at[0]) \(.at[1])"' <<<"$w")
  x=$((1700 - ${at% *})) y=$((40 - ${at#* }))
  fx=$((1700 - ${at% *})) fy=$((600 - ${at#* }))
  out=$(ob windows -b "$B")
  check_match "windows names the spanning layer as possibly over the window" \
    "layer \"omarchy-notifications\" \(overlay [0-9]+x1080 at [0-9]+,0 on [A-Z]+-[0-9]+\) spans the screen, possibly over $(jq -r .address <<<"$w"): input goes to it only where one of its items \(a toast, a dock icon\) is" "$out"
  check_eq "...--json: certain false" false \
    "$(ob windows -b "$B" --json | jq -r '.[] | select(.title == "L") | .layers[] | select(.namespace == "omarchy-notifications") | .certain')"
  out=$(ob click -b "$B" --window 'title:^L$' --no-raise "$fx" "$fy" 2>&1); rc=$?
  check_eq "--no-raise far from the toast: clicked, exit 0" 0 "$rc"
  check_match "...said: the input may go to the layer" \
    "a layer spanning the screen, \"omarchy-notifications\" \(overlay [0-9]+x1080 at [0-9]+,0\), is up over window 0x[0-9a-f]+ foot \"L\": input at $fx,$fy may go to it if one of its items \(a toast, a dock icon\) is there; elsewhere it goes to the window \(omabox run -- omarchy-shell notifications dismissAll clears the toasts\)" "$out"
  out=$(ob click -b "$B" 1700 600 2>&1); rc=$?
  check_eq "a click at the screen's 1700,600, under the spanning layer only: clicked, nothing said (#361)" "0 " "$rc $out"
  if omarchy45; then check "...the toast is still up" jq -e 'length == 1' "$live"
  else check "...the toast is still up" ob wait -b "$B" --timeout 1s layer omarchy-notifications; fi   # omarchy<4.5
  px=$((fx + ${at% *})) py=$((fy + ${at#* }))
  out=$(ob click -b "$B" --window 'title:^L$' --wait --timeout 1s "$fx" "$fy" 2>&1); rc=$?
  check_eq "click --wait that changes nothing there: 124" 124 "$rc"
  check_match "...on the window, possibly on the layer" \
    "the click at $px,$py was on foot \"L\" \(its $fx,$fy\), or possibly on layer omarchy-notifications \(it spans the screen: if one of its items, a toast, is there\)" "$out"
  out=$(ob pointer -b "$B" --window 'title:^L$' move "$fx" "$fy" 2>&1); rc=$?
  check_eq "pointer --window: moved (exit 0)" 0 "$rc"
  check_match "...the layer said as a may" "a layer spanning the screen, \"omarchy-notifications\" .* input at $fx,$fy may go to it" "$out"
  # A layer smaller than its output (a panel) over the point: certain, refused under --no-raise, and
  # it wins over a spanning one above it (4.0's full-screen notifications).
  cat > "$D/home/t263.qml" <<'QML'
import QtQuick
import Quickshell
import Quickshell.Wayland
ShellRoot {
  PanelWindow {
    anchors { top: true; left: true }
    margins { top: 200; left: 300 }
    implicitWidth: 300; implicitHeight: 150
    exclusionMode: ExclusionMode.Ignore
    WlrLayershell.layer: WlrLayer.Top
    WlrLayershell.namespace: "t263-panel"
    color: "#4060c0"
  }
}
QML
  ob run -b "$B" -d -q -- qs -p /home/sbx/t263.qml >/dev/null 2>&1
  if ob wait -b "$B" layer t263-panel >/dev/null 2>&1; then
    w=$(ob windows -b "$B" --json | jq -c '.[] | select(.title == "L")')
    at=$(jq -r '"\(.at[0]) \(.at[1])"' <<<"$w")
    out=$(ob click -b "$B" --window 'title:^L$' --no-raise $((400 - ${at% *})) $((250 - ${at#* })) 2>&1); rc=$?
    check_eq "--no-raise under a panel layer, the toast up too: refused, exit 1" 1 "$rc"
    check_match "...naming the panel, certain, and the way out" \
      "a layer surface \"t263-panel\" \(top 300x150 at 300,200\) is over [0-9]+,[0-9]+ of window 0x[0-9a-f]+ foot \"L\": .*refused under --no-raise.*omabox wait layer t263-panel --gone" "$out"
    out=$(ob click -b "$B" 400 250 2>&1); rc=$?
    check_eq "a click at the screen's 400,250, under the panel: clicked, exit 0 (#361)" 0 "$rc"
    check_match "...the panel named, certain, before the click" \
      "a layer surface \"t263-panel\" \(top 300x150 at 300,200\) is over the screen's 400,250, on window 0x[0-9a-f]+ foot \"L\": where it takes input .*omabox wait layer t263-panel --gone" "$out"
    out=$(ob scroll -b "$B" 400 250 15 2>&1)
    check_match "...a scroll there too" "a layer surface \"t263-panel\" .* is over the screen's 400,250" "$out"
    out=$(ob drag -b "$B" 400 250 410 260 2>&1)
    check_match "...a drag from there too" "a layer surface \"t263-panel\" .* is over the screen's 400,250" "$out"
    check_match "windows: the panel is over the window" "layer \"t263-panel\" \(top 300x150 at 300,200 on [A-Z]+-[0-9]+\) is over $(jq -r .address <<<"$w"): where it takes input" "$(ob windows -b "$B")"
  else no "the panel layer maps" "no t263-panel layer"; fi
  out=$(ob click -b "$B" --window 'title:^L$' "$x" "$y" 2>&1); rc=$?
  check_eq "click --window on the toast: clicked (exit 0)" 0 "$rc"
  check_match "...said on stderr as a may" "a layer spanning the screen, \"omarchy-notifications\" .* may go to it" "$out"
  if omarchy45; then
    check "...the click went to the toast, which closed (live.json empty; the layer stays)" until_ok 3 jq -e 'length == 0' "$live"
    # 4.5's layers stay mapped while idle (finding 421): with no toast, under the column and over
    # the dock, --no-raise still clicks (it was refused: "input there goes to it").
    out=$(ob click -b "$B" --window 'title:^L$' --no-raise "$fx" "$fy" 2>&1); rc=$?
    check_eq "...then --no-raise under the idle column: clicked, exit 0" 0 "$rc"
    check_match "...said as a may" "a layer spanning the screen, \"omarchy-notifications\" .* may go to it" "$out"
    if ob wait -b "$B" --timeout 1s layer omarchy-dock >/dev/null 2>&1; then
      out=$(ob click -b "$B" --window 'title:^L$' --no-raise $((400 - ${at% *})) $((1000 - ${at#* })) 2>&1); rc=$?
      check_eq "--no-raise over the idle dock: clicked, exit 0" 0 "$rc"
      check_match "...said as a may" "a layer spanning the screen, \"omarchy-dock\" \(top 1920x[0-9]+ at 0,[0-9]+\), is up over window .* may go to it" "$out"
    else skip "--no-raise over the idle dock" "no omarchy-dock layer in this box"; fi
  else   # omarchy<4.5: the layer goes with its last toast
    check "...the click went to the toast, which closed" ob wait -b "$B" --timeout 3s layer omarchy-notifications --gone
  fi
  out=$(ob click -b "$B" --window 'title:^L$' --no-raise 20 20 2>&1); rc=$?
  check_eq "...then a --no-raise click away from them goes on, nothing said" "0 " "$rc $out"
  ob down "$B" >/dev/null
}

# A box whose Hyprland is alive but does not answer (stopped here; in use, a plugin under test's
# deadlock): what asks it ends, saying so in words (#124, #125, findings 181-182). Continued, it
# answers again.
t_hung() {
  local B=$P-hung out rc t0 took
  up_ok "$B" --no-shell --net isolated || { no "up" "$UP_OUT"; return; }
  ob run -b "$B" -d -q -- foot -T F sleep 600
  ob wait -b "$B" window 'title:^F$' >/dev/null
  ob run -b "$B" -- pkill -STOP -x Hyprland
  # #166: the first call to a Hyprland just stopped, its listen backlog still empty, is not left
  # waiting in connect: hyprctl gives up by itself after 5 s, exit 6, and printed its own "IPC didn't
  # respond in time" on stdout (#139 caught only the 124 of a full backlog, which the calls below fill).
  t0=$(now_ms); out=$(timeout 40 "$CLI" hyprctl -b "$B" clients 2>&1); rc=$?; took=$(($(now_ms) - t0))
  check_eq "hyprctl clients, the first call to a stopped Hyprland: exit 1 (#166)" 1 "$rc"
  check_match "...said in words" "^omabox: box '$B': its Hyprland did not answer( in 10 s)? \(hung\? omabox log -b $B; omabox down $B\)$" "$out"
  check "...within 12 s ($took ms)" test "$took" -lt 12000
  # The tool `wait` runs, in the box: its first round trip has a deadline (on 0.4.8 it never returned).
  t0=$(now_ms); out=$(timeout 40 "$CLI" run -b "$B" -- /opt/omabox/bin/omabox-still still --timeout 3000 2>&1); rc=$?
  took=$(($(now_ms) - t0))
  check_eq "omabox-still on a stopped Hyprland: unknown, exit 1 (not timeout's 124)" 1 "$rc"
  check_match "...hung" "^unknown hung " "$out"
  check "...in about 10 s ($took ms)" test "$took" -lt 16000
  t0=$(now_ms); out=$(timeout 40 "$CLI" wait -b "$B" still --timeout 3s 2>&1); rc=$?; took=$(($(now_ms) - t0))
  check_eq "wait still --timeout 3s: exit 1, not timeout's 124" 1 "$rc"
  check_match "...said in words" "box '$B': its Hyprland did not answer( in 10 s)? \(hung\? omabox log -b $B; omabox down $B\)$" "$out"
  check "...within 9 s ($took ms; its first hyprctl's 5 s, finding 182)" test "$took" -lt 9000
  # Each of these ends in a few seconds with those words, never a line of jq's (#125, finding 182):
  # on 0.4.8 windows printed jq's usage after 15 s, shot -g "grim failed" after 10, and ls said up.
  hung_says() {
    local n=$1 t0 out rc took; shift
    t0=$(now_ms); out=$(timeout 40 "$CLI" "$@" 2>&1); rc=$?; took=$(($(now_ms) - t0))
    if [ "$rc" != 0 ] && [ "$rc" != 124 ] && [[ $out == *"box '$B': its Hyprland did not answer"* ]] && [[ $out != *jq:* ]] &&
       [ "$took" -lt "${HUNG_MAX:-9000}" ]; then ok "$n ($took ms)"; else no "$n" "exit $rc after $took ms: $out"; fi
  }
  hung_says "keys --wait: said, within 9 s" keys -b "$B" --wait a
  hung_says "windows: said, no jq line, within 9 s" windows -b "$B"
  hung_says "click --window: said" click -b "$B" --window foot 1 1
  hung_says "shot -g: said, not \"grim failed\"" shot -b "$B" -g "0,0 100x100"
  hung_says "shot: said" shot -b "$B"
  hung_says "wait window: said" wait -b "$B" window foot
  hung_says "wait layer: said" wait -b "$B" layer omarchy-bar
  # #139: these two passed straight to hyprctl, which then waited in connect for good (on 804f2d5 the
  # outer timeout ended them). Their limit is 10 s.
  HUNG_MAX=16000 hung_says "hyprctl clients: said, within 16 s" hyprctl -b "$B" clients
  HUNG_MAX=16000 hung_says "lua 'return 1': said, within 16 s" lua -b "$B" 'return 1'
  check_match "ls: hung, not up" "^$B +headless +[^ ]+ +hung " "$(ob ls | grep "^$B ")"
  check_eq "ls --json: hung, its state still up (the bar widget offers Down for any other)" "up true" \
    "$(ob ls --json | jq -r --arg n "$B" '.[] | select(.name == $n) | "\(.state) \(.hung)"')"
  ob run -b "$B" -- pkill -CONT -x Hyprland
  check_match "continued: wait still is satisfied again" "^satisfied: still" "$(ob wait -b "$B" still --timeout 5s 2>&1)"
  check_match "...ls says up" "^$B +headless +[^ ]+ +up " "$(ob ls | grep "^$B ")"
  check_eq "...ls --json: not hung" "up false" "$(ob ls --json | jq -r --arg n "$B" '.[] | select(.name == $n) | "\(.state) \(.hung)"')"
  check "...and windows answers" ob windows -b "$B"
  check_eq "...hyprctl and lua answer as before" "1" "$(ob lua -b "$B" 'return 1')"
  # ...and what follows is not cut at hyprctl's limit: still following past it, ended from outside.
  out=$(timeout 13 "$CLI" hyprctl -b "$B" rollinglog -f 2>&1); rc=$?
  check_eq "hyprctl rollinglog -f still follows past the 10 s limit (#139)" 124 "$rc"
  check_fails "...and is not called hung" grep -q "did not answer" <<<"$out"
  ob down "$B" >/dev/null
}

# (shell_pid, shell_crash and shell_crash_text, #126, findings 183, 248, 255, 258: ready.rs
# shell_crash_as_bash, an #[ignore] test t_unit_rust_ignored runs, and crash_words; #324 wave 6-suite.)

# shell_segv BOX [PID]: a SIGSEGV for box BOX's shell (PID, or the one recorded there), aimed at one of
# its threads waiting in poll (#200, finding 280). A plain `kill -SEGV` is taken by whichever thread
# runs, at start-up often the main one inside an allocation: Quickshell's crash handler then fork()s,
# jemalloc's fork handler waits for the lock that thread holds, and the shell hangs for good (no report,
# its bar still mapped; 1 in 40 under load, every later check of t_shell_crash failed with it). A
# thread in poll holds no allocator lock. (None there: the plain kill, said.)
shell_segv() {
  ob run -b "$1" -- python3 -c '
import ctypes, os, signal, sys
pid = int(sys.argv[1] or open(os.environ["XDG_RUNTIME_DIR"] + "/omabox-shell.pid").read())
for t in sorted(os.listdir(f"/proc/{pid}/task"), key=int):
    try: idle = open(f"/proc/{pid}/task/{t}/wchan").read().startswith("poll_schedule")
    except OSError: continue
    if t != str(pid) and idle and ctypes.CDLL(None).syscall(234, pid, int(t), signal.SIGSEGV) == 0: sys.exit(0)
print("shell_segv: no thread of", pid, "in poll: a plain kill", file=sys.stderr)
os.kill(pid, signal.SIGSEGV)' "${2:-}"
}
# A shell that crashes as restart-shell starts it (#126, finding 183): no "restarted", exit 1, the
# report named; Quickshell's crash dialog, which took the box's keys, closed as it opens (the box's
# Hyprland does it), the report kept. Also past 10 s, when Quickshell restarts the shell itself.
t_shell_crash() {
  local B=$P-crash D H out rc old p i rs rep
  up_ok "$B" --net isolated || { no "up" "$UP_OUT"; return; }
  D=$XDG_RUNTIME_DIR/omabox/$B H=$(ob path "$B")/home
  old=$(cat "$D/run/omabox-shell.pid")
  ob restart-shell -b "$B" > "$TMP/crash.out" 2>&1 & rs=$!
  # The new shell (its pid written, its log started), crashed once its config has loaded.
  p=""; for i in $(seq 300); do
    p=$(cat "$D/run/omabox-shell.pid" 2>/dev/null)
    [ -n "$p" ] && [ "$p" != "$old" ] && grep -aq 'Configuration Loaded' "$H/shell.log" 2>/dev/null && break
    sleep 0.05
  done
  shell_segv "$B" "$p"
  wait "$rs"; rc=$?; out=$(cat "$TMP/crash.out")
  check_eq "restart-shell, the new shell crashing: exit 1 (was 0)" 1 "$rc"
  check_fails "...never \"shell restarted\"" grep -q "shell restarted" <<<"$out"
  check_match "...says it crashed, naming the report" \
    "(warning|omabox): the shell crashed (while|after) starting \(report: $H/\.cache/quickshell/crashes/[A-Za-z0-9_.-]+/report\.txt; omabox log -b $B shell\)" "$out"
  rep=$(sed -n 's/.*(report: \([^;]*\);.*/\1/p' <<<"$out")
  check "...which is there (${rep##*/crashes/})" test -s "$rep"
  check "the crash dialog is closed as it opens (said in shell.log)" until_ok 10 grep -q "closed the shell's crash dialog" "$H/shell.log"
  # #151: as on a user's desktop, Omarchy's launcher starts it again (Quickshell does not, so soon after
  # its start): the box had no bar left.
  check "...the bar back: Omarchy's launcher started the shell again (#151)" until_ok 20 ob wait -b "$B" layer omarchy-bar
  check "...a new shell, its pid recorded" until_ok 5 bash -c "p=\$(cat '$D/run/omabox-shell.pid'); [ -n \"\$p\" ] && [ \"\$p\" != '$p' ]"
  check "...the launcher's reason in shell.log (the box's logger)" grep -q "omarchy-shell: Omarchy shell exited with status [0-9]*; relaunching" "$H/shell.log"
  check_eq "...no org.quickshell window is left to take keys" 0 "$(ob windows -b "$B" --json | jq '[.[] | select(.class == "org.quickshell")] | length')"
  out=$(ob restart-shell -b "$B" 2>&1); rc=$?
  check_eq "a restart that works: exit 0, \"restarted\" (the earlier report is not a new crash)" "0 yes" "$rc $(grep -q 'shell restarted' <<<"$out" && echo yes)"
  # Past 10 s Quickshell restarts the shell itself; its dialog came all the same.
  p=$(cat "$D/run/omabox-shell.pid"); sleep 11
  ob windows -b "$B" >/dev/null 2>&1   # (any crash before is said by now)
  shell_segv "$B" "$p"
  check "a crash past 10 s: Quickshell restarts the shell" until_ok 15 grep -q "Quickshell has been restarted" "$H/shell.log"
  # #147: it keeps its pid, so nothing else would tell; the next command says it, once (its report,
  # what tells it, written).
  until_ok 5 bash -c "[ \$(ls '$H/.cache/quickshell/crashes' | wc -l) -ge 2 ]" >/dev/null
  check_match "...the next command says it crashed (#147)" "warning: the shell crashed since the last command and was started again" \
    "$(ob windows -b "$B" 2>&1 >/dev/null)"
  check_fails "...once" grep -q "crashed since" <<<"$(ob windows -b "$B" 2>&1 >/dev/null)"
  check "...its dialog closed too" until_ok 10 grep -q "closed the shell's crash dialog" "$H/shell.log"
  check "...the bar back" ob wait -b "$B" layer omarchy-bar
  check_eq "...no org.quickshell window" 0 "$(ob windows -b "$B" --json | jq '[.[] | select(.class == "org.quickshell")] | length')"
  check_match "ls: the shell running, and its crashes since up (#147)" "^$B +headless +[^ ]+ +up +running\+2 " "$(ob ls | grep "^$B ")"
  # #147: a box with no shell left read as healthy to every command. Its launcher stopped, it is gone.
  # shellcheck disable=SC2329 # called through until_ok
  shell_is() { [ "$(ob ls --json | jq -r --arg n "$B" '.[] | select(.name == $n) | .shell_state')" = "$1" ]; }
  ob run -b "$B" -- pkill -f '[o]marchy-launch-shell'
  check "the launcher stopped, the shell with it: ls --json says gone" until_ok 10 shell_is gone
  check_match "...ls too" "^$B +headless +[^ ]+ +up +gone\+2 " "$(ob ls | grep "^$B ")"
  check_match "...and shot warns" "warning: box '$B' has no shell \(gone after 2 crash\(es\); omabox log -b $B shell; omabox restart-shell -b $B\)" \
    "$(ob shot -b "$B" -o "$TMP/gone.png" 2>&1 >/dev/null)"
  check_eq "...every time" 1 "$(ob shot -b "$B" -o "$TMP/gone.png" 2>&1 >/dev/null | grep -c 'has no shell')"
  check "restart-shell brings it back" ob restart-shell -b "$B"
  check "...running" shell_is running
  check_fails "...shot warns no more" grep -q shell <<<"$(ob shot -b "$B" -o "$TMP/back.png" 2>&1 >/dev/null)"
  ob down "$B" >/dev/null
}

# #303 (finding 408): another Quickshell in the box (a project's own, crashed on purpose to test its
# crash handling) is not the box's shell: its crash is not said as the shell's, and its dialog is left to
# it. The box's shell killed outright (no report) and started again by its launcher is said, once; and
# a `run` command killed by a signal is said in words, not by bash's job-control line.
t_shell_other_crash() {
  local B=$P-ocrash D H out rc qp dp sp i
  up_ok "$B" --net isolated || { no "up" "$UP_OUT"; return; }
  D=$XDG_RUNTIME_DIR/omabox/$B H=$(ob path "$B")/home
  ob run -b "$B" -- sh -c 'mkdir -p /tmp/qt && printf "import Quickshell\nShellRoot {}\n" > /tmp/qt/shell.qml'
  ob run -b "$B" -q -d -- /usr/bin/quickshell -p /tmp/qt
  qp=""; for i in $(seq 100); do
    qp=$(ob run -b "$B" -- /usr/bin/quickshell list -j -p /tmp/qt --any-display 2>/dev/null | jq -r 'first(.[].pid) // empty')
    [ -n "$qp" ] && grep -aq 'Configuration Loaded' "$H"/run-*.log 2>/dev/null && break
    sleep 0.1
  done
  [ -n "$qp" ] || { no "a Quickshell of the test's own started" "$(cat "$H"/run-*.log 2>/dev/null | tail -n 5)"; ob down "$B" >/dev/null; return; }
  sp=$(cat "$D/run/omabox-shell.pid")
  ob windows -b "$B" >/dev/null 2>&1
  shell_segv "$B" "$qp"
  check "the test's Quickshell crashed: its report written" until_ok 10 bash -c "grep -qx 'Config Path: /tmp/qt/shell.qml' '$H'/.cache/quickshell/crashes/*/report.txt"
  # shellcheck disable=SC2016 # jq's
  check "...its dialog opens" until_ok 10 bash -c "'$CLI' windows -b '$B' --json 2>/dev/null | jq -e 'any(.[]; .class == \"org.quickshell\")'"
  sleep 1.5   # (omabox's closer would have taken it by now: it did within ms)
  dp=$(ob windows -b "$B" --json 2>/dev/null | jq -r 'first(.[] | select(.class == "org.quickshell") | .pid) // empty')
  check "...and stays: not the box shell's to close (#303)" test -n "$dp"
  check_fails "...shell.log says no dialog closed" grep -q "closed the shell's crash dialog" "$H/shell.log"
  out=$(ob windows -b "$B" 2>&1 >/dev/null)
  check_fails "...the next command says no shell crash (was: \"the shell crashed since the last command\")" grep -q "shell" <<<"$out"
  check_match "...ls: the shell running, no crash counted" "^$B +headless +[^ ]+ +up +running " "$(ob ls | grep "^$B ")"
  check_eq "...the shell untouched" "$sp" "$(cat "$D/run/omabox-shell.pid")"
  [ -z "$dp" ] || ob run -b "$B" -- kill "$dp"
  # The box's shell killed outright: no crash handler, no report; Omarchy's launcher starts it again.
  ob run -b "$B" -- kill -KILL "$sp"
  check "the shell killed (SIGKILL): its launcher starts it again" until_ok 15 bash -c "p=\$(cat '$D/run/omabox-shell.pid'); [ -n \"\$p\" ] && [ \"\$p\" != '$sp' ]"
  out=$(ob windows -b "$B" 2>&1 >/dev/null)
  check_match "...the next command says so (it said nothing)" \
    "warning: the shell was killed by SIGKILL \(137\) since the last command and was started again( \(it is starting\))? \(omabox log -b $B shell\)" "$out"
  check_fails "...once" grep -q "shell" <<<"$(ob windows -b "$B" 2>&1 >/dev/null)"
  check "...the bar back" ob wait -b "$B" layer omarchy-bar
  # A run whose command is killed: run's words and its status, not bash's "line N: PID Killed prlimit ...".
  out=$(ob run -b "$B" -- sh -c 'kill -KILL $$' 2>&1); rc=$?
  check_eq "run, its command killed: exit 137, said in words (was bash's job-control line)" "137 omabox: the command was killed by SIGKILL (137)" "$rc $out"
  ob down "$B" >/dev/null
}

# #209 (finding 289): a shell whose pid lives but which answers nothing (a crash whose handler waits
# forever in fork() for an allocator lock, finding 280; here a stopped one, which answers nothing either)
# read as running: `ls` said so, every command drove its frozen bar, and restart-shell waited 10 s on it
# before its SIGKILL. Now it is `hung`. A shell busy starting is not: polled through a restart.
t_shell_hung() {
  local B=$P-shhung D p p2 out rc t0 seen
  # shellcheck disable=SC2329 # called through until_ok
  shell_is() { [ "$(ob ls --json | jq -r --arg n "$B" '.[] | select(.name == $n) | .shell_state')" = "$1" ]; }
  up_ok "$B" --net isolated || { no "up" "$UP_OUT"; return; }
  D=$XDG_RUNTIME_DIR/omabox/$B
  check "just up: running, not hung" shell_is running
  # A shell starting: never read as hung while restart-shell brings it up (polled all along).
  ob restart-shell -b "$B" >/dev/null 2>&1 & rc=$!
  seen=""; while kill -0 "$rc" 2>/dev/null; do seen+=" $(ob ls --json | jq -r --arg n "$B" '.[] | select(.name == $n) | .shell_state')"; done
  wait "$rc"
  check_fails "...nor while restart-shell starts it (seen:$seen)" grep -qw hung <<<"$seen"
  sleep 10.5   # past its first 10 s, under which a shell that does not answer may still be loading
  p=$(cat "$D/run/omabox-shell.pid")
  ob run -b "$B" -- kill -STOP "$p"
  check_match "stopped: ls says hung" "^$B +headless +[^ ]+ +up +hung " "$(ob ls | grep "^$B ")"
  check "...ls --json too" shell_is hung
  check_eq "...the box itself up, its Hyprland answering" "up false" "$(ob ls --json | jq -r --arg n "$B" '.[] | select(.name == $n) | "\(.state) \(.hung)"')"
  check_match "...and a command warns" "warning: the shell of box '$B' does not answer \(hung: its bar is frozen; omabox log -b $B shell; omabox restart-shell -b $B\)" \
    "$(ob windows -b "$B" 2>&1 >/dev/null)"
  t0=$(now_ms); out=$(ob restart-shell -b "$B" 2>&1); rc=$?
  check_eq "restart-shell: exit 0" 0 "$rc"
  check_match "...says it killed the hung one" "box '$B': its shell \(pid $p\) did not answer \(hung\): killed" "$out"
  check "...under 10 s ($(( ($(now_ms) - t0) / 1000 )) s; it waited 10 s on it before)" test $(($(now_ms) - t0)) -lt 10000
  p2=$(cat "$D/run/omabox-shell.pid")
  check "...a new shell ($p2), the old one gone" bash -c "[ -n '$p2' ] && [ '$p2' != '$p' ] && ! '$CLI' run -b '$B' -- test -d /proc/$p"
  check "...the bar back" ob wait -b "$B" layer omarchy-bar
  check "...running" shell_is running
  check_fails "...no warning" grep -q shell <<<"$(ob windows -b "$B" 2>&1 >/dev/null)"
  ob down "$B" >/dev/null
}

# finding 248 (#192): restart-shell right after edits to shell.json and a plugin, the shell having died
# of a signal as they landed (a crash, a kill): Omarchy's launcher starts it again a second later.
# shell.sh stopped only the recorded shell, so the new one met that relaunch ("An instance of this
# configuration is already running"), or the relaunch met it, and restart-shell said the shell exited
# (exit 1) with one up; the pid it then recorded was a dead one, and every restart after failed alike.
# Rounds with the kill 0-1.3 s before restart-shell (on the old code each failed), then plain ones.
t_shell_restart_race() {
  local B=$P-rr F=$TMP/rr D H S d out rc pids rec side=left badrc="" badone="" baddup=""
  mkdir -p "$F/w"
  jq -n --arg id "$P.rr" '{schemaVersion: 1, id: $id, name: $id, version: "0.1.0", kinds: ["bar-widget"],
    entryPoints: {barWidget: "W.qml"}, barWidget: {displayName: $id, defaultSection: "right"}}' > "$F/w/manifest.json"
  printf 'import QtQuick\nimport qs.Ui\nBarWidget {\n  id: root\n  implicitWidth: b.implicitWidth\n  implicitHeight: b.implicitHeight\n  WidgetButton { id: b; bar: root.bar; text: "rr" }\n}\n' > "$F/w/W.qml"
  up_ok "$B" --net isolated --plugin "$F/w" || { no "up" "$UP_OUT"; return; }
  D=$XDG_RUNTIME_DIR/omabox/$B H=$(ob path "$B")/home; S=$H/.config/omarchy/shell.json
  for d in 0 0.3 0.6 0.9 1.0 1.1 1.3 - - -; do   # (-: no kill)
    side=$([ "$side" = left ] && echo right || echo left)
    jq --arg s "$side" --arg id "$P.rr" '.bar.layout.left = [] | .bar.layout.right = [] | .bar.layout[$s] = [{id: $id}]' "$S" > "$TMP/rr.json" &&
      cp "$TMP/rr.json" "$S"
    echo "// $d" >> "$F/w/W.qml"
    if [ "$d" != - ]; then ob run -b "$B" -- kill -KILL "$(cat "$D/run/omabox-shell.pid")" 2>/dev/null; sleep "$d"; fi
    out=$(ob restart-shell -b "$B" 2>&1); rc=$?
    sleep 1.5   # (past the old launcher's relaunch, had one been left)
    pids=$(ob run -b "$B" -- pgrep -x quickshell | tr '\n' ' ') rec=$(cat "$D/run/omabox-shell.pid" 2>/dev/null)
    { [ "$rc" = 0 ] && grep -q "shell restarted" <<<"$out"; } || badrc+="[$d: exit $rc, ${out:0:100}] "
    [ "$pids" = "$rec " ] || badone+="[$d: running $pids, recorded $rec] "
    ! grep -aq "already running" "$H/shell.log" || baddup+="[$d] "
  done
  check_eq "edits, the shell killed 0-1.3 s before restart-shell (or not): exit 0, \"restarted\", every time (#192)" "" "$badrc"
  check_eq "...one shell after each, the one recorded" "" "$badone"
  check_eq "...none started as a duplicate" "" "$baddup"
  check_eq "...ls: running, the plugin loaded" "running loaded" \
    "$(ob ls --json | jq -r --arg n "$B" --arg i "$P.rr" '.[] | select(.name == $n) | "\(.shell_state) \(.plugin_status[$i].state)"')"
  ob down "$B" >/dev/null
}

# finding 248: a shell something else starts just as restart-shell starts its own (an `omarchy restart
# shell` at the same moment) is the box's shell, and restart-shell's own exits as its duplicate: it
# said the shell exited (exit 1) with that one up. Made certain here: the tree's launcher starts its
# shell a second late, and a racer in the box starts one as soon as shell.sh has stopped the old one.
t_shell_restart_dup() {
  local B=$P-rd T=$TMP/rd-tree D H out rc rec
  copy_omarchy "$T"
  rm -f "$T/bin/omarchy-launch-shell"
  # shellcheck disable=SC2016 # the launcher's
  printf '#!/bin/bash\n[ ! -e "$HOME/rd-late" ] || sleep 1\nexec /usr/bin/omarchy-launch-shell "$@"\n' > "$T/bin/omarchy-launch-shell"
  chmod +x "$T/bin/omarchy-launch-shell"
  up_ok "$B" --net isolated --omarchy "$T" || { no "up --omarchy" "$UP_OUT"; return; }
  D=$XDG_RUNTIME_DIR/omabox/$B H=$(ob path "$B")/home
  # (shell.sh removes the old pid once that shell is stopped, before it starts the launcher.)
  # shellcheck disable=SC2016 # the box's
  ob run -b "$B" -d -- bash -c 'f=$XDG_RUNTIME_DIR/omabox-shell.pid; while [ -e "$f" ]; do sleep 0.01; done
    QS_DISABLE_FILE_WATCHER=1 QS_NO_RELOAD_POPUP=1 exec systemd-cat -t omarchy-shell -- quickshell -n -p "$OMARCHY_PATH/shell"' >/dev/null 2>&1
  touch "$H/rd-late"
  out=$(ob restart-shell -b "$B" 2>&1); rc=$?
  check_eq "restart-shell, another start's shell up first, its own a duplicate: exit 0 (was 1)" 0 "$rc"
  check_match "...says so" "another start of the shell came first; that one \(pid [0-9]+\) is up" "$out"
  check_match "...and restarted" "shell restarted in box '$B'" "$out"
  check "...its own did exit as a duplicate" grep -aq "An instance of this configuration is already running" "$H/shell.log"
  sleep 1
  rec=$(cat "$D/run/omabox-shell.pid" 2>/dev/null)
  check_eq "...one shell, the one now recorded" "$rec" "$(ob run -b "$B" -- pgrep -x quickshell)"
  check_eq "...ls: running" running "$(ob ls --json | jq -r --arg n "$B" '.[] | select(.name == $n) | .shell_state')"
  rm -f "$H/rd-late"
  check "a restart after it: as usual" ob restart-shell -b "$B"
  check_eq "...one shell" 1 "$(ob run -b "$B" -- pgrep -cx quickshell)"
  ob down "$B" >/dev/null
}

# Accent pixels (#ff3cc8, peek's marks) in the screen of box $B (the caller's) within X0 Y0 X1 Y1:
# "COUNT CX CY", the centre of their bounding box. With ACCENT_KEEP set, in the screen the last call
# captured (two regions of one frame).
# shellcheck disable=SC2329 # called through accent_ok and no_accent
accent() {
  [ -n "${ACCENT_KEEP:-}" ] || ob run -b "$B" -- grim -t ppm - > "$TMP/peek-$B.ppm"
  python3 - "$TMP/peek-$B.ppm" "$@" <<'PY'
import re, sys
d = open(sys.argv[1], "rb").read()
m = re.match(rb"P6\s+(\d+)\s+(\d+)\s+255\s", d)
w, px = int(m[1]), d[m.end():]
x0, y0, x1, y1 = map(int, sys.argv[2:])
hits = [(x, y) for y in range(y0, y1) for x in range(x0, x1)
        if px[(y * w + x) * 3] > 200 and px[(y * w + x) * 3 + 1] < 110 and px[(y * w + x) * 3 + 2] > 150]
if not hits: print(0, 0, 0)
else: print(len(hits), (min(x for x, _ in hits) + max(x for x, _ in hits)) // 2, (min(y for _, y in hits) + max(y for _, y in hits)) // 2)
PY
}
# shellcheck disable=SC2329 # called through until_ok and holds
# For until_ok: at least MIN accent pixels there (centred within 8 px of CX,CY when given); prints them.
accent_ok() {
  local n=$1 a; shift; read -ra a <<< "$(accent "$1" "$2" "$3" "$4")"; echo "${a[*]}"
  [ "${a[0]}" -ge "$n" ] || return 1
  [ $# -lt 6 ] || (( a[1] - $5 >= -8 && a[1] - $5 <= 8 && a[2] - $6 >= -8 && a[2] - $6 <= 8 ))
}
# shellcheck disable=SC2329
no_accent() { local a; read -ra a <<< "$(accent "$@")"; echo "${a[*]}"; [ "${a[0]}" = 0 ]; }

# peek, run inside a box on that box's own screen (never on the host): it draws, and hidden on another
# workspace it stops capturing (finding 64; the old one scaled 30 frames a second nobody saw).
# Marks (finding 85): what `click`/`keys` did, drawn by that peek over its view. The CLI writes them
# only for a host peek of the box, so a stand-in named like one relays them to the peek in the box.
t_peek() {
  local B=$P-peek
  up_ok "$B" --no-shell --net isolated || { no "up" "$UP_OUT"; return; }
  local D; D=$(ob path "$B")
  local wd; wd=$(ob run -b "$B" -- sh -c 'echo $WAYLAND_DISPLAY')
  ob run -b "$B" -d -- "$ROOT/tools/peek/omabox-peek" --box "/run/user/$UID/$wd" --fps 30 --marks "/run/user/$UID/marks-in" >/dev/null 2>&1
  check "peek opens a window" until_ok 10 bash -c "'$CLI' hyprctl -b '$B' -j clients | jq -e '.[] | select(.class == \"omabox-peek\")'"
  local pid; pid=$(ob hyprctl -b "$B" -j clients | jq '.[] | select(.class == "omabox-peek") | .pid')
  ticks() { ob run -b "$B" -- sh -c "a=\$(cut -d' ' -f14,15 /proc/$pid/stat | tr ' ' +); sleep 2; b=\$(cut -d' ' -f14,15 /proc/$pid/stat | tr ' ' +); echo \$(( (b) - (a) ))"; }
  local shown; shown=$(ticks)
  check "peek draws while shown (CPU ticks: $shown)" test "$shown" -gt 5
  # A quarter of the screen, bottom right: a box point X,Y is at 940 + X/2, 520 + Y/2 in the view, and
  # the view's copy of itself (it shows its own screen) lies well away from any mark.
  ob hyprctl -b "$B" dispatch "hl.dsp.window.float({ window = 'class:omabox-peek' })" >/dev/null
  ob hyprctl -b "$B" dispatch "hl.dsp.window.resize({ window = 'class:omabox-peek', x = 960, y = 540 })" >/dev/null
  ob hyprctl -b "$B" dispatch "hl.dsp.window.move({ window = 'class:omabox-peek', x = 940, y = 520 })" >/dev/null
  check "peek floats at 940,520 960x540" until_ok 5 bash -c "'$CLI' hyprctl -b '$B' -j clients | jq -e '.[] | select(.class == \"omabox-peek\") | .at == [940, 520] and .size == [960, 540]'"
  sleep 0.5; local base; base=$(ticks)   # at this size, before any mark
  HELD=$B   # (a peek of yours at this box would get these marks too: held)
  ob click -b "$B" 100 100 >/dev/null
  check "no marks file without a peek window" test ! -e "$D/marks"
  # The stand-in: a process named as `omabox peek` runs it, relaying $D/marks into the box.
  (exec -a "$ROOT/tools/peek/omabox-peek --box $D/run/stand-in" tail -n +1 -F "$D/marks" >> "$D/run/marks-in" 2>/dev/null) & local relay=$!
  until_ok 5 pgrep -f "^$ROOT/tools/peek/omabox-peek --box $D/run/stand-in"
  ob click -b "$B" 700 400 >/dev/null
  check_eq "click writes a mark" "ptr 1920x1080 move 700 400 click left" "$(cat "$D/marks" 2>&1)"
  check_eq "the marks file is the user's only" 600 "$(stat -c %a "$D/marks")"
  until_ok 5 grep -q "move 700 400" "$D/run/marks-in"
  check "a ring where the click went" until_ok 3 accent_ok 21 1230 660 1350 780 1290 720
  T_PW="pw-$P" "$CLI" keys -b "$B" -t hi --pass T_PW >/dev/null
  until_ok 5 grep -q "^secret" "$D/run/marks-in"
  check_eq "keys marks: text, and a secret as its length only" "text hi|secret $((3 + ${#P}))|" "$(grep -v ^ptr "$D/marks" | tr '\n' '|')"
  check_fails "...never its value" grep -q "pw-$P" "$D/marks"
  check "a key caption at the bottom" until_ok 3 accent_ok 51 1100 990 1740 1060
  { head -c 70000 /dev/zero | tr '\0' x; echo; } >> "$D/marks"
  ob click -b "$B" 700 400 >/dev/null
  check_eq "past 64 KB the marks file starts over" "ptr 1920x1080 move 700 400 click left" "$(cat "$D/marks")"
  check "marks gone ~3 s after the last one" until_ok 10 no_accent 940 520 1900 1060
  # Junk is ignored whole (and does not stop what follows): unknown kinds, out-of-range and bad
  # numbers, control characters, a line too long to be one, then a good line.
  printf '%s\n' 'junk' 'ptr 1920x1080 move 1920 10' 'ptr 1920x1080 move 10' 'ptr 0x1080 click' 'ptr 1920x1080 hover 1 1' \
    'combo a b' 'secret -1' 'text' "text $(printf 'x%.0s' {1..201})" "$(printf 'y%.0s' {1..2000})" $'text a\tb' >> "$D/run/marks-in"
  check "junk marks draw nothing" holds 1 no_accent 940 520 1900 1060
  printf 'ptr 1920x1080 move 300 200 click\n' >> "$D/run/marks-in"
  check "...and a good line after it still does" until_ok 3 accent_ok 21 1030 560 1150 680   # around 1090,620
  printf 'ptr 1920x1080 move 1500 200 click back\n' >> "$D/run/marks-in"   # (#216: a thumb button's name)
  check "...a click back draws its ring too" until_ok 3 accent_ok 21 1630 560 1820 700   # around 1690,620
  check "peek is still running" kill -0 "$(pgrep -f "omabox-peek --box /run/user/$UID/$wd" | head -1)"
  kill "$relay" 2>/dev/null; wait "$relay" 2>/dev/null
  ob click -b "$B" 10 10 >/dev/null
  check "the marks file goes with the peek window" test ! -e "$D/marks"
  HELD=""
  sleep 3.2
  local after; after=$(ticks)
  check "marks cost nothing once gone (CPU ticks: $after, before any: $base)" test "$after" -le $((base + base / 2 + 3))
  ob hyprctl -b "$B" dispatch "hl.dsp.window.move({ workspace = '5', follow = false })" >/dev/null; sleep 0.5
  printf 'combo super+space\nptr 1920x1080 move 5 5 click\n' >> "$D/run/marks-in"   # nothing to show them on
  local hidden; hidden=$(ticks)
  check "peek idles while hidden (CPU ticks: $hidden)" test "$hidden" -le 2
  check_fails "peek refuses junk --fps" "$ROOT/tools/peek/omabox-peek" --box /nonexistent --fps abc
  ob down "$B" >/dev/null
}

# #164, finding 233: `omabox peek` of a box with two monitors, a window each, in a box standing in for
# the host (finding 26: peek is a host window). Marks are in layout coordinates: each window draws the
# ones on its own monitor, at that monitor's place and scale; both windows get them (a second peek
# made the marks file anew, lost to the first); `down` closes every one (it closed the first).
t_peek_monitors() {
  local n S=$P-pkm C=$P-pkmc
  n=$(gpu_node other)
  [ -n "$n" ] || { skip "peek with monitors" "no render node here but NVIDIA's (a stand-in there is not tried; finding 234)"; return; }
  OMABOX_RENDER_NODE="$n" up_ok "$S" --no-shell --net isolated || { no "up the stand-in" "$UP_OUT"; return; }
  local in=("$CLI" run -b "$S" -- "${GUARDED[@]}" "$CLI")
  # (The stand-in renders on that node, and so does a box in it.) The second monitor is 1280x720
  # logical, 1600x900 pixels, at 1920,0.
  check "up a box with a second monitor at scale 1.25 in the stand-in" "${in[@]}" up "$C" --no-shell --idle 0 --monitor 1600x900,scale=1.25
  check_eq "...right of the main screen" "1.25 1920 0" \
    "$("${in[@]}" monitor -b "$C" list --json | jq -r '.[] | select(.name == "HEADLESS-3") | "\(.scale) \(.x) \(.y)"')"
  check "peek of the main screen in the stand-in" "${in[@]}" peek "$C"
  check "peek --monitor HEADLESS-3" "${in[@]}" peek "$C" --monitor HEADLESS-3
  # shellcheck disable=SC2329 # called through until_ok
  peeks() { [ "$(ob hyprctl -b "$S" -j clients | jq '[.[] | select(.class == "omabox-peek")] | length')" = "$1" ]; }
  check "two peek windows" until_ok 10 peeks 2
  # Floated where the views map simply: the main screen's at half size at 20,20 (layout X,Y at
  # 20 + X/2, 20 + Y/2), HEADLESS-3's at half its logical size at 1000,600 (1000 + (X-1920)/2, 600 + Y/2).
  local a1 a2
  a1=$(ob hyprctl -b "$S" -j clients | jq -r '.[] | select(.class == "omabox-peek" and (.title | endswith("HEADLESS-3") | not)) | .address')
  a2=$(ob hyprctl -b "$S" -j clients | jq -r '.[] | select(.class == "omabox-peek" and (.title | endswith("HEADLESS-3"))) | .address')
  ob hyprctl -b "$S" dispatch "hl.dsp.focus({ workspace = '9' })" >/dev/null
  place() {   # ADDRESS W H X Y
    ob hyprctl -b "$S" dispatch "hl.dsp.window.float({ window = 'address:$1' })" >/dev/null
    ob hyprctl -b "$S" dispatch "hl.dsp.window.resize({ window = 'address:$1', x = $2, y = $3 })" >/dev/null
    ob hyprctl -b "$S" dispatch "hl.dsp.window.move({ window = 'address:$1', x = $4, y = $5 })" >/dev/null
  }
  place "$a1" 960 540 20 20; place "$a2" 640 360 1000 600
  check_eq "...placed" "[20,20] [960,540] [1000,600] [640,360]" \
    "$(ob hyprctl -b "$S" -j clients | jq -r --arg a "$a1" --arg b "$a2" '[(.[] | select(.address == $a)), (.[] | select(.address == $b))] | map("\(.at | tojson) \(.size | tojson)") | join(" ")')"
  local B=$S   # (accent's box: the stand-in's screen)
  # One frame of the stand-in: a ring around CX,CY in one window, no accent in the other (MIN X0 Y0
  # X1 Y1 CX CY, then the other's X0 Y0 X1 Y1); a caption in both.
  # shellcheck disable=SC2329 # called through until_ok
  ring_only() { accent_ok "$1" "$2" "$3" "$4" "$5" "$6" "$7" && ACCENT_KEEP=1 no_accent "$8" "$9" "${10}" "${11}"; }
  # shellcheck disable=SC2329
  captions() { accent_ok 51 20 440 980 560 && ACCENT_KEEP=1 accent_ok 51 1000 840 1640 960; }
  sleep 0.5
  "${in[@]}" click -b "$C" 700 400 >/dev/null
  check "a click on the main screen: a ring in its peek where it went, none in HEADLESS-3's" \
    until_ok 3 ring_only 21 310 160 430 280 370 220 1000 600 1640 960
  check "...nor after" holds 1 no_accent 1000 600 1640 960
  sleep 3.5
  "${in[@]}" click -b "$C" 2240 360 >/dev/null
  # (The pointer glides 120 ms from the main screen: its ring shows there until it leaves.)
  check "a click on HEADLESS-3: a ring in its peek at its place and scale, none in the main screen's" \
    until_ok 3 ring_only 21 1100 720 1220 840 1160 780 20 20 980 560
  check "...nor after" holds 1 no_accent 20 20 980 560
  sleep 3.5
  "${in[@]}" keys -b "$C" -t hi >/dev/null
  check "keys: a caption in both peeks" until_ok 3 captions
  # #200: HEADLESS-3 dropped (its global removed), its peek stays and says so: " (gone)" in its title,
  # a dark view with a caption (accent-edged, in the middle); the main screen's goes on. Back (a new
  # global of that name), it shows HEADLESS-3 again: the caption gone, and the box's background made
  # accent pink after it shows there (frames flow).
  # shellcheck disable=SC2329 # called through until_ok
  title_is() { [ "$(ob hyprctl -b "$S" -j clients | jq -r --arg a "$1" '.[] | select(.address == $a) | .title')" = "$2" ]; }
  until_ok 5 no_accent 20 20 1640 960 >/dev/null   # the captions faded
  "${in[@]}" output -b "$C" drop HEADLESS-3 >/dev/null 2>&1
  check "output drop HEADLESS-3: its peek's title says so" until_ok 5 title_is "$a2" "omabox peek: $C · HEADLESS-3 (gone)"
  check "...its window too: a caption in the middle" until_ok 3 accent_ok 200 1000 600 1640 960 1320 780
  check "...the peek still there, the main screen's untouched" title_is "$a1" "omabox peek: $C"
  check "...both windows" peeks 2
  "${in[@]}" output -b "$C" back HEADLESS-3 >/dev/null 2>&1
  check "output back: HEADLESS-3's peek titled as before" until_ok 5 title_is "$a2" "omabox peek: $C · HEADLESS-3"
  check "...shows it again (the caption gone)" until_ok 3 no_accent 1000 600 1640 960
  "${in[@]}" lua -b "$C" 'hl.config({ misc = { background_color = 0xffff3cc8 } })' >/dev/null 2>&1
  check "...and what it shows after: frames flow" until_ok 3 accent_ok 150000 1000 600 1640 960
  # down closes every peek window of the box: a process named as a third one (a later pid than the
  # two) goes too, though nothing ties it to the box's socket.
  local d; d=$("${in[@]}" path "$C")
  ob run -b "$S" -d -- bash -c 'exec -a "$1" sleep 300' _ "$ROOT/tools/peek/omabox-peek --box $d/run/x --output HEADLESS-9 --fps 1" >/dev/null 2>&1
  check "a process named as a third peek of the box: there" until_ok 5 ob run -b "$S" -- pgrep -f "^$ROOT/tools/peek/omabox-peek --box $d/run/x "
  "${in[@]}" down "$C" >/dev/null 2>&1
  check "down closes both peek windows" until_ok 5 peeks 0
  # shellcheck disable=SC2329 # called through until_ok
  none_left() { ! ob run -b "$S" -- pgrep -f "^$ROOT/tools/peek/omabox-peek --box $d/run/"; }
  check "...and every peek process of the box" until_ok 3 none_left
  ob down "$S" >/dev/null
}

# A throwaway whose run is gone and whose box died before the reaper saw it (a teardown that gave up
# under load left one): the reaper clears it rather than leave a dead box in ls.
t_throwaway_dead() {
  local repo; repo=$(tmp_repo td)
  (cd "$repo" && exec env -u OMABOX "$CLI" run -- sleep 300) & local r=$!
  until_ok 30 bash -c "'$CLI' ls --json | jq -e '.[] | select(.name | startswith(\"$P-td-run\")) | select(.state == \"up\")'"
  local n; n=$(ob ls --json | jq -r ".[] | select(.name | startswith(\"$P-td-run\")) | .name")
  # Its reaper starts with the box (#137), so its `up` may still be waiting for the bar: the box must go
  # within 15 s that way too (#157: up waited out READY_TIMEOUT on a dead box, holding its lock).
  until_ok 30 pgrep -f "omabox _reap $n "
  # The box's PID 1 as the CLI finds it: behind pasta, info.json's child-pid is pasta's numbering (2,
  # which on the host is kthreadd), and the box would stay up for the reaper's "run is gone" branch.
  local pid; pid=$(probe box_pid "$n")
  kill -KILL "$r"; wait "$r" 2>/dev/null   # reaped here: no "Killed" job line from bash later
  check "its box is killed before the reaper sees it" kill -KILL "$pid"
  check "the dead box goes within 15 s" until_ok 15 bash -c "! '$CLI' ls --json | jq -e '.[] | select(.name == \"$n\")'"
}

# (settle_end and settle_begin reading an answer or a ready line split across a read's second, a
# space included, finding 217, #310: settle.rs split_answers_read_whole; #324 wave 6-suite.)

# (up's waits on a box that died meanwhile, #157, finding 216: ready.rs bar_settle_on_a_dead_box,
# #324 wave 6-suite.)

# install.sh with a temporary HOME and stubs first on PATH (sudo refuses, so it never installs a
# package): failures stop it with a message (finding 64), and it links, never nests.
t_unit_install() {
  # install.sh is a checkout's (it builds the tools into ROOT): a package builds them itself.
  [ "$INSTALLED" = 0 ] || { skip "install.sh" "an installed omabox has no install.sh to run"; return; }
  local h=$TMP/ih stub=$TMP/ih-stub out
  # The XDG dirs too: the session sets them, and install.sh's `setup --aquamarine` builds under the
  # data dir when ROOT is no checkout (it once did so in the user's own, from an --installed run).
  local -x XDG_DATA_HOME=$h/.local/share XDG_CACHE_HOME=$h/.cache XDG_CONFIG_HOME=$h/.config XDG_STATE_HOME=$h/.local/state
  # install.sh builds into its ROOT: here a copy of this checkout's tracked files, never the checkout
  # under test, whose tools the other tests use (#187, finding 253: built there, the tests before this
  # one had failed on a fresh checkout). Its aquamarine step finds this omabox's build there, a
  # stand-in (the soname Hyprland links, the commit omabox builds), as in a checkout that has run
  # install.sh: nothing to build, no clone (the copy is no checkout: it would build into $h).
  local c=$TMP/ic-root so tools0
  mkdir -p "$c/build/prefix/lib"
  git -C "$ROOT" ls-files -z | (cd "$ROOT" && tar --null -cf - -T -) | tar -xf - -C "$c"
  so=$(probe hypr_aq_soname) && : > "$c/build/prefix/lib/$so"
  probe aq_const AQ_BUILD > "$c/build/prefix/.omabox-commit"
  tools0=$(stat -c '%n %.9Y' "$ROOT"/tools/*/omabox-* 2>&1)
  mkdir -p "$h" "$stub"
  printf '#!/bin/sh\necho "$*" >> "%s/sudo-called"; exit 1\n' "$stub" > "$stub/sudo"
  # The packages as present whatever this machine has (finding 369: one removed by hand failed every
  # check below); pacman -T names those in $stub/missing as missing.
  printf '#!/bin/sh\n[ "$1" = -T ] || exec /usr/bin/pacman "$@"\n[ -s "%s/missing" ] || exit 0\ncat "%s/missing"; exit 127\n' \
    "$stub" "$stub" > "$stub/pacman"
  printf '#!/bin/sh\ncase "$*" in *tools/keyboard*) exit 1 ;; esac\nexec /usr/bin/make "$@"\n' > "$stub/make"
  # Never the user's shell: setup's widget question (finding 133) would reach the running one, which
  # is the real desktop's whatever HOME says. Answered no up front, and these fail if called.
  printf '#!/bin/sh\necho "$0 $*" >> "%s/shell-called"; exit 1\n' "$stub" > "$stub/omarchy"
  cp "$stub/omarchy" "$stub/omarchy-shell"
  mkdir -p "$h/.config/omabox"; date -Is > "$h/.config/omabox/widget-declined"
  # cargo under this HOME has no toolchain (rustup's, or mise's shim, which refuses a config it has
  # not been told to trust): its build (#324) is this checkout's binary put where cargo would leave
  # it (CARGO_TARGET_DIR, as cargo takes it).
  # (--version: the stand-in's, or a rustup's with no toolchain while $stub/notoolchain is there)
  printf '#!/bin/sh\nif [ "$1" = --version ]; then [ ! -e "%s/notoolchain" ] || { echo "error: rustup could not choose a version of cargo to run" >&2; exit 1; }; echo "cargo (stand-in)"; exit 0; fi\nwhile [ $# -gt 0 ]; do [ "$1" = --manifest-path ] && m=$2; shift; done\nd=${CARGO_TARGET_DIR:-$(dirname "$m")/target}/release\nb=%s/build/omabox; [ ! -e "%s/omabox-bin" ] || b=%s/omabox-bin\nmkdir -p "$d" && cp "$b" "$d/omabox"\n' \
    "$stub" "$ROOT" "$stub" "$stub" > "$stub/cargo"   # ($stub/omabox-bin while there: a stand-in, for --check)
  chmod +x "$stub/sudo" "$stub/pacman" "$stub/make" "$stub/omarchy" "$stub/omarchy-shell" "$stub/cargo"
  local tty=(env SHELL=/bin/bash script -qec "$(printf %q "$c/install.sh")" /dev/null)
  echo omabox-no-such-package > "$stub/missing"
  # #395: with no terminal, sudo can only fail (in words of its own, which vary): the command to run.
  out=$(HOME=$h PATH=$stub:$PATH "$c/install.sh" 2>&1 </dev/null); local rc=$?
  check_eq "a missing package, no terminal: install.sh stops, without sudo (#395)" "1 " "$rc $(cat "$stub/sudo-called" 2>/dev/null)"
  check_match "...naming it" "missing: omabox-no-such-package" "$out"
  check_match "...and the command to run, then install.sh again" \
    "no terminal for sudo's password: run this, then $c/install.sh again: sudo pacman -S --needed omabox-no-such-package" "$(tr '\n' ' ' <<<"$out")"
  out=$(HOME=$h PATH=$stub:$PATH "${tty[@]}" 2>&1 </dev/null); rc=$?
  check_eq "...in a terminal: install.sh installs it with sudo pacman, and stops when that fails" \
    "1 pacman -S --needed omabox-no-such-package" "$rc $(cat "$stub/sudo-called" 2>&1)"
  rm -f "$stub/sudo-called"
  # #395: a render node that renders in software only (virtio-gpu without virgl, a VM's) passed, and
  # the box died "while starting". Its virtio features (one 0/1 per bit) say so: bit 0 virgl, 4
  # context types (venus). Every render node here, as the test's sysfs has them, laid out as an
  # omavm guest's (virtio-vga, 2026-10-27): device/ is the PCI device (virtio-pci, no features), its
  # child virtio0 the virtio_gpu device; its features as read there (without accel3d, then with).
  local sysdrm=$TMP/ih-sysdrm n dv nogl=0100000000000000000000000000110010000000100000000000000000000000
  local gl=1100100000000000000000000000110010000000100000000000000000000000
  rm -rf "$sysdrm"; mkdir -p "$TMP/ih-drivers/virtio_gpu" "$TMP/ih-drivers/virtio-pci" "$TMP/ih-drivers/amdgpu"
  for n in /dev/dri/renderD*; do
    dv=$sysdrm/${n##*/}/device; mkdir -p "$dv/virtio0"
    ln -s "$TMP/ih-drivers/virtio-pci" "$dv/driver"; ln -s "$TMP/ih-drivers/virtio_gpu" "$dv/virtio0/driver"
    printf '%s\n' "$nogl" > "$dv/virtio0/features"
  done
  out=$(HOME=$h PATH=$stub:$PATH OMABOX_TEST_SYSDRM=$sysdrm "$c/install.sh" 2>&1 </dev/null); rc=$?
  check_match "a render node that renders in software only (virtio-gpu, no virgl): said (#395)" \
    "every render node renders in software only \(renderD[0-9]+.*: virtio-gpu without virgl\).*a box needs GPU rendering" "$(tr '\n' ' ' <<<"$out")"
  check_eq "...stopping install.sh before the packages" "1 0" "$rc $(grep -c '==> Packages' <<<"$out")"
  for n in "$sysdrm"/*/device/virtio0/features; do printf '%s\n' "$gl" > "$n"; done
  out=$(HOME=$h PATH=$stub:$PATH OMABOX_TEST_SYSDRM=$sysdrm "$c/install.sh" 2>&1 </dev/null)
  check_fails "...virtio-gpu with virgl renders on the GPU" grep -q "software" <<<"$out"
  check_match "...on to the packages" "missing: omabox-no-such-package" "$out"
  for n in "$sysdrm"/*/device/virtio0/features; do printf '%s\n' "${nogl:0:4}1${nogl:5}" > "$n"; done
  check_fails "...and with context types only (venus)" grep -q "software" <<<"$(HOME=$h PATH=$stub:$PATH OMABOX_TEST_SYSDRM=$sysdrm "$c/install.sh" 2>&1 </dev/null)"
  # virtio-gpu not on PCI (virtio-mmio): device/ is the virtio device itself.
  for n in "$sysdrm"/*/device; do rm -r "$n/virtio0" "$n/driver"; ln -s "$TMP/ih-drivers/virtio_gpu" "$n/driver"; printf '%s\n' "$nogl" > "$n/features"; done
  check_match "...virtio-mmio's, device/ itself: said too" "renders in software only" \
    "$(HOME=$h PATH=$stub:$PATH OMABOX_TEST_SYSDRM=$sysdrm "$c/install.sh" 2>&1 </dev/null)"
  for n in "$sysdrm"/*/device; do rm "$n/driver" "$n/features"; ln -s "$TMP/ih-drivers/amdgpu" "$n/driver"; done
  check_fails "...another driver: no virtio features to read" grep -q "software" <<<"$(HOME=$h PATH=$stub:$PATH OMABOX_TEST_SYSDRM=$sysdrm "$c/install.sh" 2>&1 </dev/null)"
  rm "$stub/missing"
  out=$(HOME=$h PATH=$stub:$PATH "$c/install.sh" 2>&1); rc=$?
  check_match "a failed tool build stops install.sh" "building tools/keyboard failed" "$out"
  check_eq "...with a failure" 1 "$rc"
  check_fails "...before anything ran omabox (built first: its aquamarine step comes after)" grep -q "nothing to build" <<<"$out"
  rm "$stub/make"
  : > "$stub/notoolchain"
  out=$(HOME=$h PATH=$stub:$PATH "$c/install.sh" 2>&1); rc=$?
  check_match "a cargo that cannot build (rustup, no toolchain): said, how to set one" \
    "cargo is there but cannot build: error: rustup could not choose.*rustup default stable" "$out"
  check_eq "...stopping install.sh before the tools" "1 0" "$rc $(grep -c '^tools/' <<<"$out")"
  rm "$stub/notoolchain"
  mkdir -p "$h/.claude/skills/omabox"
  check_match "a real dir where a link goes is refused" "is not a link" "$(HOME=$h PATH=$stub:$PATH "$c/install.sh" 2>&1)"
  rmdir "$h/.claude/skills/omabox"
  check "install.sh in a clean HOME" env HOME="$h" PATH="$stub:$PATH" "$c/install.sh"
  check_eq "...built every tool in its own ROOT" "$(cd "$c/tools" && printf '%s\n' */Makefile | sed 's|\(.*\)/Makefile|\1/omabox-\1|')" \
    "$(cd "$c/tools" && for f in */omabox-*; do [ -x "$f" ] && echo "$f"; done)"
  check "...and omabox, at build/omabox" cmp -s "$ROOT/build/omabox" "$c/build/omabox"
  # finding 66's successor (#324 wave 6-flip): build/omabox is replaced by a rename, so a command
  # running from it keeps its file (the one open here) and no caller runs a half-written one.
  local ino0 fd; ino0=$(stat -c %i "$c/build/omabox"); exec {fd}< "$c/build/omabox"
  printf '#!/bin/sh\necho "$*" >> "%s/install-called"\nexec /usr/bin/install "$@"\n' "$stub" > "$stub/install"; chmod +x "$stub/install"
  check "...run again: built again" env HOME="$h" PATH="$stub:$PATH" "$c/install.sh"
  check_eq "...written as build/omabox.new (never build/omabox itself)" "-Dm755 $c/target/release/omabox $c/build/omabox.new" \
    "$(grep -F target/release/omabox "$stub/install-called")"
  check_fails "...then renamed: a new file at build/omabox, not one rewritten in place" test "$(stat -c %i "$c/build/omabox")" = "$ino0"
  rm "$stub/install"
  check_eq "...the file a running command has stays whole" "$(stat -c %s "$ROOT/build/omabox")" "$(stat -L -c %s "/proc/$BASHPID/fd/$fd")"
  check_fails "...no temp file left" test -e "$c/build/omabox.new"
  exec {fd}<&-
  check_eq "...and nothing in the checkout under test (#187)" "$tools0" "$(stat -c '%n %.9Y' "$ROOT"/tools/*/omabox-* 2>&1)"
  # finding 525: a user's CARGO_TARGET_DIR (or build.target-dir in cargo's config, which it overrides)
  # put the build elsewhere, and install.sh installed a stale target/release/omabox (or died, none).
  printf 'stale\n' > "$c/target/release/omabox"
  check "a CARGO_TARGET_DIR of the user's: install.sh still builds into its ROOT's target/" \
    env HOME="$h" PATH="$stub:$PATH" CARGO_TARGET_DIR="$TMP/ic-target" "$c/install.sh"
  check "...and installs that build, not a stale one" cmp -s "$ROOT/build/omabox" "$c/build/omabox"
  check_fails "...leaving the user's target dir alone" test -e "$TMP/ic-target"
  check_eq "the skill is a link" "$c/skill" "$(readlink "$h/.claude/skills/omabox")"
  check_fails "...not the feedback skill: opt-in (finding 326)" test -L "$h/.claude/skills/omabox-feedback"
  check "...of the directory: the reference SKILL.md points to comes with it, for every agent" \
    bash -c "grep -q 'reference.md' '$h/.agents/skills/omabox/SKILL.md' && test -f '$h/.agents/skills/omabox/reference.md' && test -f '$h/.claude/skills/omabox/reference.md'"
  check_fails "no dir for an agent that is not installed" test -e "$h/.codex"
  check_fails "the agent guard is never turned on without asking" test -e "$h/.claude/settings.json"
  printf '#!/bin/sh\necho "  -g <geometry>   Set the region to capture."\n' > "$stub/grim"; chmod +x "$stub/grim"
  check_match "a grim with no -T (window capture, finding 81) stops it" "no -T" "$(HOME=$h PATH=$stub:$PATH "$c/install.sh" 2>&1)"
  rm "$stub/grim"
  # finding 92: an older hook of ours is an update to offer, even after a "no" to turning it on.
  jq -n '{hooks: {SessionStart: [{hooks: [{type: "command", command: "echo old omabox-guard"}]}]}}' > "$h/.claude/settings.json"
  date -Is > "$h/.config/omabox/guard-declined"
  out=$(HOME=$h PATH=$stub:$PATH "$c/install.sh" 2>&1)
  check_match "an outdated guard: install.sh offers to update it" "guard there is outdated.*not asked \(no terminal\)" "$(tr '\n' ' ' <<<"$out")"
  check_eq "...and changes nothing without a terminal" "echo old omabox-guard" "$(jq -r '.hooks.SessionStart[0].hooks[0].command' "$h/.claude/settings.json")"
  # One from a checkout that is gone reads outdated too, though no older omabox wrote it.
  local old; old=$(cat "$h/.claude/settings.json")
  jq --arg c 'echo x omabox-guard PATH="/nonexistent/co/share/guard:$PATH"' '.hooks.SessionStart[0].hooks[0].command = $c' \
    <<<"$old" > "$h/.claude/settings.json"
  check_match "...and one from a checkout that is gone, in words that fit it too" \
    "/nonexistent/co/share/guard is gone.*The guard there is outdated.*not asked \(no terminal\): omabox guard on claude" \
    "$(HOME=$h PATH=$stub:$PATH "$c/install.sh" 2>&1 | tr '\n' ' ')"
  printf '%s\n' "$old" > "$h/.claude/settings.json"
  # ...for the agents that have it, whatever the others' guard (Codex off here) and an earlier "no".
  # "Turn it on?" is for the others, and only a "no" to that is remembered.
  local guard=(env HOME="$h" "$c/bin/omabox" guard)
  mkdir -p "$h/.codex"; rm "$h/.config/omabox/guard-declined"
  out=$(HOME=$h PATH=$stub:$PATH "$c/install.sh" 2>&1)
  check_match "Claude Code outdated, Codex off: an update for Claude Code, turning it on for Codex" \
    "guard there is outdated.*not asked \(no terminal\): omabox guard on claude .*not asked \(no terminal\): omabox guard on codex" "$(tr '\n' ' ' <<<"$out")"
  date -Is > "$h/.config/omabox/guard-declined"
  out=$(HOME=$h PATH=$stub:$PATH "$c/install.sh" 2>&1)
  check_match "...the update even after a no to turning it on" \
    "guard there is outdated.*not asked \(no terminal\): omabox guard on claude .*you said no before.*: omabox guard on codex" "$(tr '\n' ' ' <<<"$out")"
  printf 'y\n' | HOME=$h PATH=$stub:$PATH "${tty[@]}" >/dev/null 2>&1
  check_match "...in a terminal, yes updates Claude Code's and leaves Codex off" "Claude Code .*: on Codex .*: off" \
    "$("${guard[@]}" | grep -iE '^(Claude Code|Codex)' | tr '\n' ' ')"
  rm "$h/.config/omabox/guard-declined"; printf '%s\n' "$old" > "$h/.claude/settings.json"
  printf 'n\ny\n' | HOME=$h PATH=$stub:$PATH "${tty[@]}" >/dev/null 2>&1
  check_match "...no to the update and yes to turning it on: only Codex's changes" "Claude Code .*: outdated Codex .*: on" \
    "$("${guard[@]}" | grep -iE '^(Claude Code|Codex)' | tr '\n' ' ')"
  check_fails "...and the no to the update is not remembered" test -e "$h/.config/omabox/guard-declined"
  rm -rf "$h/.codex"
  rm -f "$h/.claude/settings.json" "$h/.config/omabox/guard-declined"
  # #395: --check's failure named the box's logs, which the down on exit had removed. A stand-in
  # omabox (built as install.sh builds it) whose up dies as a box does, leaving its folder; setup passes.
  local rt=$h/run kept=$h/.local/state/omabox/install-check
  mkdir -p "$rt"
  cat > "$stub/omabox-bin" <<EOF
#!/bin/sh
d=\$XDG_RUNTIME_DIR/omabox/\$2
case "\$1" in
up) [ ! -e "$stub/up-ok" ] || { mkdir -p "\$d"; exit 0; }
  mkdir -p "\$d/home"; echo "session.sh: labwc ended" > "\$d/box.log"
  echo "Software rendering detected" > "\$d/home/labwc.log"; echo hl > "\$d/home/hyprland.log"
  echo "omabox: box '\$2' died while starting; logs: \$d/home/*.log \$d/box.log" >&2; exit 1 ;;
shot) echo /tmp/shot.png ;;
down) echo "down \$2" >> "$stub/omabox-called"; rm -rf "\$d" ;;
esac
EOF
  chmod +x "$stub/omabox-bin"
  out=$(HOME=$h PATH=$stub:$PATH XDG_RUNTIME_DIR=$rt "$c/install.sh" --check 2>&1 </dev/null); rc=$?
  check_match "install.sh --check, its box dead while starting: where its logs are kept (#395)" \
    "the check box failed; its logs are kept in $kept" "$out"
  check_eq "...with a failure" 1 "$rc"
  check_eq "...those logs, out of the box's folder" \
    "box.log:session.sh: labwc ended home/hyprland.log:hl home/labwc.log:Software rendering detected" \
    "$(cd "$kept" 2>/dev/null && grep -r . box.log home | sort | tr '\n' ' ' | sed 's/ $//')"
  check_eq "...and the box taken down" "down install-check-" "$(sed 's/[0-9]*$//' "$stub/omabox-called" 2>&1)"
  check_eq "...its folder gone" "" "$(ls -A "$rt/omabox" 2>&1)"
  : > "$stub/up-ok"; rm -f "$stub/omabox-called"
  out=$(HOME=$h PATH=$stub:$PATH XDG_RUNTIME_DIR=$rt "$c/install.sh" --check 2>&1 </dev/null); rc=$?
  check_eq "...a box that comes up: its screenshot, taken down, the old logs gone" "0 screenshot: /tmp/shot.png 1 no" \
    "$rc $(grep -o 'screenshot: .*' <<<"$out") $(grep -c '^down install-check-' "$stub/omabox-called" 2>&1) $(test -e "$kept" && echo kept || echo no)"
  rm -f "$stub/omabox-bin" "$stub/up-ok" "$stub/omabox-called"
  printf '#!/bin/sh\necho Hyprland dev build\n' > "$stub/Hyprland"; chmod +x "$stub/Hyprland"
  check_match "an unreadable Hyprland version says so (was silent)" "too old" "$(HOME=$h PATH=$stub:$PATH "$c/install.sh" 2>&1)"
  check_fails "...and none of it reached a shell (omarchy, omarchy-shell)" test -e "$stub/shell-called"
}

# The session's Omarchy defaults, and the uwsm-app stand-in's terminal options and desktop files
# (finding 64).
t_uwsm_app() {
  local B=$P-uw
  up_ok "$B" --no-shell --net isolated || { no "up" "$UP_OUT"; return; }
  check_eq "session TERMINAL is Omarchy's" xdg-terminal-exec "$(ob run -b "$B" -- sh -c 'echo $TERMINAL')"
  check_eq "session EDITOR is Omarchy's" "omarchy-launch-editor --inline" "$(ob run -b "$B" -- sh -c 'echo $EDITOR')"
  # Whether the terminal applies it is xdg-terminal-exec's business (foot's entry has no
  # TerminalArgAppId, so neither it nor real uwsm passes it on); the stand-in must hand it over.
  ob run -b "$B" -- uwsm-app -T --app-id=omabox.term -- sleep 60 >/dev/null
  check_match "uwsm-app -T hands --app-id to xdg-terminal-exec" "uwsm-app: xdg-terminal-exec --app-id=omabox.term sleep 60" "$(ob run -b "$B" -- cat /home/sbx/apps.log)"
  ob run -b "$B" -- sh -c 'printf "[Desktop Entry]\nType=Application\nName=t\nExec=foot --app-id=omabox.desk sleep 60\n" > /tmp/t.desktop'
  ob run -b "$B" -- uwsm-app -- /tmp/t.desktop >/dev/null
  check "uwsm-app launches a desktop file by path" until_ok 10 bash -c "'$CLI' hyprctl -b '$B' -j clients | jq -e '.[] | select(.class == \"omabox.desk\")'"
  check_fails "uwsm-app fails on a missing command" ob run -b "$B" -- uwsm-app -- no-such-command-omabox
  check_eq "the theme's browser policy step is a quiet no-op (finding 75: pkexec)" "" "$(ob run -b "$B" -- omarchy-theme-set-browser-policy 1a1b26 2>&1)"
  # systemd-run and systemd-cat stand-ins (finding 131): the browser bind's shape, with foot for the browser.
  ob run -b "$B" -- systemd-run --user --quiet --collect --unit=omarchy-browser-1 --property=StandardOutput=null \
    uwsm-app -- foot --app-id=omabox.sdrun sleep 60 >/dev/null
  check "systemd-run --user without a user manager starts the app (the browser bind)" until_ok 10 \
    bash -c "'$CLI' hyprctl -b '$B' -j clients | jq -e '.[] | select(.class == \"omabox.sdrun\")'"
  check_eq "...--wait runs it in the foreground, its exit code passed on" "out 3" \
    "$(ob run -b "$B" -- sh -c 'o=$(systemd-run --user --wait -E V=out sh -c "echo \$V; exit 3"); echo "$o $?"')"
  check_match "...a timer says it needs --systemd" "omabox up --systemd" "$(ob run -b "$B" -- systemd-run --user --on-active=1m true 2>&1)"
  check_eq "systemd-cat -t ID writes to ~/ID.log" "hi" "$(ob run -b "$B" -- sh -c 'echo hi | systemd-cat -t omabox-t; cat ~/omabox-t.log')"
  check_eq "...--level-prefix VALUE spaced: VALUE is not the command (#113)" "lp" \
    "$(ob run -b "$B" -- sh -c 'systemd-cat -t omabox-lp --level-prefix false echo lp; cat ~/omabox-lp.log' 2>&1)"
  check_match "systemd-run --shell: not supported, said (#113)" "--shell is not supported in a box" \
    "$(ob run -b "$B" -- systemd-run --user --shell 2>&1)"
  ob run -b "$B" -- sh -c 'printf "[Desktop Entry]\nType=Application\nName=t2\nExec=foot --app-id=omabox.desk2 sleep 60\nActions=x;\n[Desktop Action x]\nName=x\nExec=true\n" > /tmp/t2.desktop'
  ob run -b "$B" -- uwsm-app -- /tmp/t2.desktop:x >/dev/null
  check "uwsm-app launches a desktop file by path with an action (dropped) (#113)" until_ok 10 \
    bash -c "'$CLI' hyprctl -b '$B' -j clients | jq -e '.[] | select(.class == \"omabox.desk2\")'"
  # omarchy-version (finding 137): Omarchy's asks pacman, which a box has no database for (exit 1).
  local ov; ov=$(pacman -Q omarchy-dev 2>/dev/null || pacman -Q omarchy 2>/dev/null) || ov=${OMABOX_OMARCHY_VERSION:-}
  check_eq "omarchy-version says the installed Omarchy's version" "${ov#* }" "$(ob run -b "$B" -- omarchy-version)"
  check_eq "...in a terminal's bash too (Omarchy's bin is on its PATH)" "${ov#* }" "$(ob run -b "$B" -- bash -ic omarchy-version 2>/dev/null)"
  check_eq "...and ls --json has it (finding 139)" "${ov#* }" "$(ob ls --json | jq -r --arg n "$B" '.[] | select(.name == $n) | .omarchy_version')"
  # #238: the installed Hyprland's version too, as the box's says it; `hyprland` (a build's path) null.
  local hj; hj=$(ob ls --json | jq -c --arg n "$B" '.[] | select(.name == $n) | [.hyprland, .hyprland_version]')
  check_eq "ls --json has the installed Hyprland's version line, hyprland null (#238)" \
    "$(jq -nc --arg v "$(ob hyprctl -b "$B" version | head -n 1)" '[null, $v]')" "$hj"
  check_fails "...and ls says no Hyprland line for it" bash -c "'$CLI' ls | grep -A1 '^$B ' | grep -q '^  Hyprland:'"
  ob down "$B" >/dev/null
}

# #140: a box keeps the config it started with: an update of omabox (share/ is live) reloaded every
# running box. `omabox reload` is the way to a newer one.
t_config_kept() {
  local B=$P-cfg E n0 out want
  up_ok "$B" --no-shell --net isolated || { no "up" "$UP_OUT"; return; }
  want=$(md5sum < "$ROOT/share/hyprland.lua")
  # shellcheck disable=SC2016 # the box's XDG_RUNTIME_DIR
  local copy=(ob run -b "$B" -- sh -c 'md5sum < "$XDG_RUNTIME_DIR/omabox-hyprland.lua"')
  check_match "its Hyprland runs the box's own copy of the config (#140)" "--config /run/user/[0-9]+/omabox-hyprland\.lua$" \
    "$(ob run -b "$B" -- pgrep -ax Hyprland)"
  check_eq "...a copy of omabox's" "$want" "$("${copy[@]}")"
  ob lua -b "$B" 'omabox_t140 = 1' >/dev/null
  # shellcheck disable=SC2016
  ob run -b "$B" -- sh -c 'echo "-- changed" >> "$XDG_RUNTIME_DIR/omabox-hyprland.lua"'
  sleep 2
  check_eq "a change to that file reloads nothing (autoreload off): the Lua state stays" 1 "$(ob lua -b "$B" 'return omabox_t140')"
  E=$(ob path -b "$B")/home/events.log; n0=$(grep -c ' configreloaded' "$E")
  out=$(ob reload -b "$B" 2>&1)
  check_eq "omabox reload: said" "omabox: box '$B': config reloaded from $ROOT/share/hyprland.lua (binds, rules and Lua state added since are gone)" "$out"
  check_eq "...the copy is omabox's again" "$want" "$("${copy[@]}")"
  check_eq "...the Lua state fresh" nil "$(ob lua -b "$B" 'return omabox_t140')"
  sleep 2
  check_eq "...one reload, not two (the file's change is not one)" 1 "$(($(grep -c ' configreloaded' "$E") - n0))"
  # (...a jailed agent's, as restart-shell is: broker_side.rs's broker_check_allows_and_refuses)
  check_match "up --autoreload on it: refused, it has autoreload off (finding 207)" "--autoreload \(its autoreload is off\)" \
    "$(ob up "$B" --autoreload 2>&1)"
  ob down "$B" >/dev/null 2>&1
}

# Finding 207: `up --autoreload` keeps Hyprland's autoreload on, as on a desktop, so a project
# can see what a file change does (a helper that rewrites a file the config loads reloads for ever).
t_autoreload() {
  local B=$P-are E n0 n1
  up_ok "$B" --no-shell --net isolated --autoreload || { no "up --autoreload" "$UP_OUT"; return; }
  check_eq "up --autoreload: its Hyprland's autoreload is on (finding 207)" false \
    "$(ob hyprctl -b "$B" -j getoption misc:disable_autoreload | jq .bool)"
  check_eq "...ls --json says so" true "$(ob ls --json | jq -r --arg n "$B" '.[] | select(.name == $n) | .autoreload')"
  check_match "...up --autoreload again takes it as it is" "box '$B' is already up$" "$(ob up "$B" --autoreload 2>&1)"
  E=$(ob path -b "$B")/home/events.log
  # (a read-only install's share/ too: a copy of its mode was refused the write below, finding 528)
  check "the box's copy of the config is its to change" ob run -b "$B" -- sh -c 'test -w "$XDG_RUNTIME_DIR/omabox-hyprland.lua"'
  ob lua -b "$B" 'omabox_t74 = 1' >/dev/null
  n0=$(grep -c ' configreloaded' "$E")
  # shellcheck disable=SC2016
  ob run -b "$B" -- sh -c 'echo "-- changed" >> "$XDG_RUNTIME_DIR/omabox-hyprland.lua"'
  check "a change to a file its config loaded reloads it" until_ok 10 \
    bash -c "[ \"\$(grep -c ' configreloaded' '$E')\" -gt $n0 ]"
  check_eq "...a fresh Lua state" nil "$(ob lua -b "$B" 'return omabox_t74')"
  check_eq "...and autoreload is still on after it" false "$(ob hyprctl -b "$B" -j getoption misc:disable_autoreload | jq .bool)"
  ob reload -b "$B" >/dev/null 2>&1   # the copy is omabox's again (a write: maybe two reloads)
  sleep 2
  n1=$(grep -c ' configreloaded' "$E")
  ob reload -b "$B" >/dev/null 2>&1
  sleep 2
  check_eq "omabox reload with the copy unchanged: one reload, no write to set off another" 1 \
    "$(($(grep -c ' configreloaded' "$E") - n1))"
  ob down "$B" >/dev/null 2>&1
}

# #128: the box's own compositor is not a test's to end by name, and a box ended from inside is said so.
t_own_processes() {
  local B=$P-own out rc
  up_ok "$B" --no-shell --net isolated || { no "up" "$UP_OUT"; return; }
  check_eq "the box's labwc is named omabox-labwc (#128)" 1 "$(ob run -b "$B" -- pgrep -cx omabox-labwc)"
  check_fails "...so nothing in it is named labwc" ob run -b "$B" -- pgrep -x labwc
  check_eq "a --no-shell box: its shell none in ls --json, - in ls (#147)" "none -" \
    "$(ob ls --json | jq -r --arg n "$B" '.[] | select(.name == $n) | .shell_state') $(ob ls | awk -v n="$B" '$1 == n { print $5 }')"
  ob run -b "$B" -- pkill -x labwc >/dev/null 2>&1
  # shellcheck disable=SC2329 # called through holds
  is_up() { [ "$("$CLI" ls --json | jq -r --arg n "$B" '[.[] | select(.name == $n) | .state][0] // "gone"')" = up ]; }
  check "pkill -x labwc in a box leaves it up" holds 2 is_up
  check "...its Hyprland answering" ob hyprctl -b "$B" version
  out=$(ob run -b "$B" -- sh -c 'pkill -x Hyprland; sleep 10' 2>&1); rc=$?
  check_match "a box ended from inside: said in words" "box '$B' went down while this command ran" "$out"
  check_eq "...exit 125, run's own: the command's status was the box's end (#273)" 125 "$rc"
  # #166: instead of nsenter's line or bash's "Killed" one for it, not after them.
  check_eq "...in those words alone" 1 "$(grep -c . <<<"$out")"
  ob down "$B" >/dev/null 2>&1
}

# `up` itself on a box name of its own, taken down before each case (#324: what wave 5a compared with
# bash's up, each now stated): what it says (durations evened out) and what it leaves in the box dir,
# launch.sh, box.json and the files there; then ls, save, saves, brief, reload, restart-shell and down
# on the box up.
t_cli_up() {
  local U=$P-rpu r=$TMP/rpu
  rm -rf "$r"; mkdir -p "$r/td/rp-theme" "$r/norepo"; echo seeded > "$r/seed.txt"; echo 'name = "rp"' > "$r/td/rp-theme/colors.toml"
  # A HOME of the test's own, so the user's own ~/.config/omabox/config (protect-ports, a gpu) cannot
  # change what up does: its theme the user's current one, its config empty.
  local h=$r/home st=${XDG_STATE_HOME:-$HOME/.local/state}/omarchy/current
  mkdir -p "$h/.config/omabox" "$h/.local/state/omarchy/current"; : > "$h/.config/omabox/config"
  ln -s "$(readlink -f "$st/theme")" "$h/.local/state/omarchy/current/theme"
  cp "$st/theme.name" "$h/.local/state/omarchy/current/" 2>/dev/null
  # (and the user's bar, as up seeds it from the desk)
  mkdir -p "$h/.config/omarchy"; cp "$HOME/.config/omarchy/shell.json" "$HOME/.config/omarchy/shell.toml" "$h/.config/omarchy/" 2>/dev/null
  rpu_down() { HOME=$h ob down "$U" >/dev/null 2>&1; true; }
  # (what each up made: its launch script, box.json and files, the seeds in its HOME)
  rpu_state() {
    local d=$XDG_RUNTIME_DIR/omabox/$U
    echo "== launch.sh"; sed -E "s/omabox-$U-[0-9]+/omabox-$U-PID/" "$d/launch.sh" 2>/dev/null
    echo "== box.json"; jq -S 'del(.created, .pidns, .starter.pid, .starter.start, .starter.command)' "$d/box.json" 2>/dev/null
    echo "== files"; (cd "$d" 2>/dev/null && command find . -maxdepth 1 -printf '%p %y\n' | LC_ALL=C sort)
    echo "== home"; (cd "$d/home" 2>/dev/null && command find .config/rp .config/omarchy/themes/rp-theme -maxdepth 0 -printf '%p %y %l\n' 2>/dev/null)
  }
  cx_rt=$XDG_RUNTIME_DIR cx_dir=$r/norepo cx_env=("HOME=$h") cx_snap=0 cx_prep=rpu_down cx_also=rpu_state
  cx_sed='s/\b[0-9]+(\.[0-9]+)? ?(s|ms)\b/T/g; s/"created":"[^"]*"/"created":T/'
  # (each up's line on stderr, said after the bar's seeding, when the desk has a bar to seed)
  local qr; qr=$(printf '%s' "$XDG_RUNTIME_DIR/omabox/$U" | sed -E 's/[][\\.*^$()+?{}|]/\\&/g')
  rpu_said() { echo "err~^omabox: box '$U' up \\($1\\) in $qr\$"; }
  cx_want=(rc=0 out= "$(rpu_said 1920x1080@60)" 'state~^  "net": "isolated",$' 'state~^  "shell": false,$' 'state~^  "size": "1920x1080@60",$')
  cx_case "up: headless, no shell, isolated" up "$U" --no-shell --net isolated
  cx_want=(rc=0 "out~^\\{\"name\":\"$U\",\"mode\":\"headless\",\"size\":\"1920x1080@60\",\"scale\":1,\"created\":T,.*\"net\":\"isolated\"" "$(rpu_said 1920x1080@60)" 'state~^  "shell": true,$')
  cx_case "up --json: with its shell" up "$U" --net isolated --json
  cx_want=(rc=0 out= "$(rpu_said 1920x1080@60)" 'state~^  "net": "connected",$')
  cx_case "up: connected" up "$U" --no-shell
  cx_want=(rc=0 out= "$(rpu_said 1920x1080@60)" "err~^omabox: clean: Omarchy's bar, theme tokyo-night, wallpaper #ff00ff .*, no network, animations off$" 'state~^  "bar": "stock",$' 'state~^  "clean": \{$' 'state~^  "net": "isolated",$')
  cx_case "up --clean" up "$U" --clean
  cx_want=(rc=0 out= "$(rpu_said 1920x1080@60)" 'state~^  "bar": "stock",$' 'state~^  "xwayland": true$' 'state~^\./pointer f$')
  cx_case "up --stock-bar --no-pointer --xwayland" up "$U" --stock-bar --no-pointer --xwayland --net isolated
  cx_want=(rc=0 out= "$(rpu_said '1920x1080@60 \+ 800x600@60 \+ 1024x768@60')" 'state~^      "name": "HEADLESS-3",$' 'state~^      "name": "HEADLESS-4",$' 'state~^    "1024x768,below"$')
  cx_case "up --monitor: two more, placed" up "$U" --no-shell --net isolated --monitor 800x600 --monitor 1024x768,below
  cx_want=(rc=0 out= "$(rpu_said 1920x1080@60)" 'state~^\.config/rp d $' "state~^\\.config/omarchy/themes/rp-theme l $r/td/rp-theme\$")
  cx_case "up --seed and --theme-dir" up "$U" --no-shell --net isolated --seed "$r/seed.txt:.config/rp/seed.txt" --theme-dir "$r/td/rp-theme"
  cx_want=(rc=0 out= "$(rpu_said 1920x1080@60)" 'state~^  "allow": "18080,18081",$' 'state~^    "192\.0\.2\.7",?$' 'state~^    "2001:db8::7",?$' 'state~ -T 18080\\,18081 ')
  cx_case "up --addr and --allow" up "$U" --no-shell --net isolated --addr 192.0.2.7 --addr 2001:db8::7 --allow 18081,18080
  cx_want=(rc=0 out= "err~^omabox: note: box '$U' has no idle limit and goes with no agent: nothing takes it down but omabox down $U; " 'state~^  "idle": 0,$')
  cx_case "up --idle 0: an orphan to be, said" up "$U" --no-shell --net isolated --idle 0
  # (its size's scale rounded to whole pixels, as Hyprland takes it: finding 510)
  cx_want=(rc=0 out= "$(rpu_said '1280x720@60,scale=1\.6')" 'state~^  "scale": 1\.5,$' 'state~^  "size": "1280x720@60",$' 'state~ --setenv RPV 1 ')
  cx_case "up --env and --size with a scale" up "$U" --no-shell --net isolated --env RPV=1 --size 1280x720,scale=1.5
  cx_want=(rc=0 out= "$(rpu_said 1920x1080@60)" 'state~^  "no_seed": \[$')
  cx_case "up --no-seed fonts,extensions" up "$U" --no-shell --net isolated --no-seed fonts,extensions
  # A save whose HOME has a link where --clean writes its wallpaper (finding 461): the PNG is written
  # in the box HOME, never through the link onto the host file it leads to.
  mkdir -p "$r/data/omabox/saves/rp-save/home/.config/omabox"; ln -s "$r/victim" "$r/data/omabox/saves/rp-save/home/.config/omabox/clean-wallpaper.png"
  rpu_victim() { rpu_state; echo "== victim"; head -c 4 "$r/victim" | od -An -c | tr -s ' '; echo victim > "$r/victim"; }
  echo victim > "$r/victim"
  cx_env=("HOME=$h" "XDG_DATA_HOME=$r/data") cx_also=rpu_victim
  cx_want=(rc=0 "$(rpu_said 1920x1080@60)" 'state~^ v i c t$')
  cx_case "up --from a save with a link at the clean wallpaper's place (finding 461)" up "$U" --no-shell --clean --from rp-save
  cx_env=("HOME=$h") cx_also=rpu_state
  # A desk with no shell.json: an empty bar, nothing said of a file not there (finding 462).
  mkdir -p "$r/desk-empty"
  cx_env=("HOME=$h" "OMABOX_DESK_CONFIG=$r/desk-empty")
  cx_want=(rc=0 "$(rpu_said 1920x1080@60)" 'err!~No such file or directory')
  cx_case "up with a desk that has no shell.json (finding 462)" up "$U" --no-shell --net isolated; cx_env=("HOME=$h")
  # protect-ports set (finding 459): a connected box starts with the port left out of pasta's host rules.
  local pp; pp=$(free_port); echo "protect-ports=$pp" > "$h/.config/omabox/config"
  cx_want=(rc=0 "$(rpu_said 1920x1080@60)" "state~ -T \\\\~$pp\\\\,auto ")
  cx_case "up of a connected box with protect-ports set (finding 459)" up "$U" --no-shell
  : > "$h/.config/omabox/config"
  # Up already: said, or refused for what it lacks.
  cx_prep=""
  cx_want=(rc=0 out= "err=omabox: box '$U' is already up")
  cx_case "up of the box up already" up "$U"
  cx_want=(rc=0 "out~^\\{\"name\":\"$U\",\"mode\":\"headless\",.*\"net\":\"connected\"" "err=omabox: box '$U' is already up")
  cx_case "up --json of the box up already" up "$U" --json
  cx_want=(rc=1 out= "err=omabox: box '$U' is already up, without what you asked for: --size 800x600@60 (it is 1920x1080@60); --stock-bar (it has your bar). omabox down $U first, or omabox up --new for a box of your own")
  cx_case "up of the box up already, without what is asked" up "$U" --size 800x600 --net connected --stock-bar
  # On the box up: ls (its own line or entry; other boxes come and go), save and saves (in a data dir
  # of the test's own; sizes evened out: its HOME moves), then down.
  # (cx_check: its stdout, its entry of the box alone)
  rpu_json() { jq -c --arg n "$U" '[.[] | select(.name == $n)]' "$2" > "$2.t" && mv "$2.t" "$2"; }
  cx_also="" cx_check="" cx_sed="/^$U /!d; s/ [0-9]+m\/2h / Nm\/2h /"
  cx_want=(rc=0 "out~^$U +headless +1920x1080@60 +up +- +connected +Nm/2h *\$" err=)
  cx_case "ls: the box up" ls
  cx_sed="" cx_check=rpu_json
  cx_want=(rc=0 "out~^\\[\\{\"name\":\"$U\",\"mode\":\"headless\",\"size\":\"1920x1080@60\",.*\"net\":\"connected\"" err=)
  cx_case "ls --json: the box up" ls --json
  cx_check="" cx_env=("XDG_DATA_HOME=$r/data5b")
  rpu_nosave() { rm -rf "$r/data5b"; }
  cx_prep=rpu_nosave cx_sed='s/\(([0-9.,]+[KMG]?)(, keyring secrets included)?\)/(SIZE\2)/; s/ is [0-9.,]+[KMG]?: / is SIZE: /'
  cx_want=(rc=0 out= "err=omabox: saved box '$U' as 'rp5b-save' (SIZE); start from it: omabox up --from rp5b-save (or run --from rp5b-save)")
  cx_case "save of the box up" save rp5b-save -b "$U"
  cx_prep="" cx_sed='s/^(rp5b-save +)[0-9.,]+[KMG]? /\1SIZE /; s/"size":"[^"]*","size_kb":[0-9]+/"size":S,"size_kb":K/; s/"saved":"[^"]*"/"saved":T/'
  cx_want=(rc=0 'out~^NAME +SIZE +SAVED +FROM +KEYRING$' "out~^rp5b-save +SIZE +[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2} +$U +no\$" err=)
  cx_case "saves: that save" saves
  cx_want=(rc=0 "out=[{\"name\":\"rp5b-save\",\"box\":\"$U\",\"saved\":T,\"size\":S,\"size_kb\":K,\"keyring\":false}]" err=)
  cx_case "saves --json" saves --json
  cx_sed=""; rpu_resave() { rpu_nosave; XDG_DATA_HOME=$r/data5b ob save rp5b-save -b "$U" >/dev/null 2>&1; }
  cx_prep=rpu_resave cx_snap=0
  rpu_saves() { find "$r/data5b/omabox/saves" -mindepth 1 -maxdepth 1 -printf '%f\n' 2>/dev/null; }
  cx_also=rpu_saves cx_want=(rc=0 out= "err=omabox: save 'rp5b-save' removed" 'state=')
  cx_case "saves rm" saves rm rp5b-save
  cx_also=""
  # brief names the box, reload gives its Hyprland the config again; restart-shell on a box with its
  # shell, below.
  cx_env=("HOME=$h") cx_prep="" cx_sed="" cx_check=""
  cx_want=(rc=0 "out~^You drive omabox box '$U' \\(1920x1080, scale 1\\): a private Omarchy desktop, not the user's\\. " "out~^  none yet \\(omabox -b $U run -d --wait -- APP opens one\\)\$" err=)
  cx_case "brief -b: the box up, no windows" brief -b "$U"
  local reloaded="err~^omabox: box '$U': config reloaded from .*/share/hyprland\\.lua \\(binds, rules and Lua state added since are gone\\)\$"
  cx_want=(rc=0 out= "$reloaded"); cx_case "reload: the box up" reload -b "$U"
  cx_want=(rc=0 out= "$reloaded"); cx_case "reload by its name" reload "$U"
  cx_want=(rc=2 out= "err=omabox: restart-shell: one box name, got $U and x (omabox help restart-shell)")
  cx_case "restart-shell -b with a name too" restart-shell -b "$U" x
  cx_env=() cx_prep=""
  rpu_up() { ob up "$U" --no-shell --net isolated >/dev/null 2>&1; probe box_pid "$U" > "$r/rpu-pid1"; }
  # (its PID 1 recorded before the down, in rpu_up: gone after it)
  rpu_gone() { echo "== dir $(test -e "$XDG_RUNTIME_DIR/omabox/$U" && echo there || echo gone)"; echo "== reaper $(pgrep -fc "omabox _reap $U " || true)"
    echo "== HOME $(test -e "${XDG_CACHE_HOME:-$HOME/.cache}/omabox/$U" && echo there || echo gone)"
    echo "== PID 1 $(kill -0 "$(cat "$r/rpu-pid1" 2>/dev/null)" 2>/dev/null && echo up || echo gone)"; }
  cx_prep=rpu_up cx_also=rpu_gone
  cx_want=(rc=0 out= "err=omabox: box '$U' down" $'state=== dir gone\n== reaper 0\n== HOME gone\n== PID 1 gone')
  cx_case "down of the box up" down "$U"
  rpu_down
  # restart-shell on a box with its shell: it restarts it, then brief and reload see the box as it is.
  cx_prep="" cx_also="" cx_env=("HOME=$h")
  if HOME=$h ob up "$U" --net isolated >/dev/null 2>&1; then
    cx_want=(rc=0 out= "err=omabox: shell restarted in box '$U'")
    cx_case "restart-shell: the box's shell restarted" restart-shell -b "$U"
    cx_want=(rc=0 "out~^You drive omabox box '$U' \\(1920x1080, scale 1\\)" err=)
    cx_case "brief -b: the box with its bar" brief -b "$U"
    cx_want=(rc=0 out= "$reloaded"); cx_case "reload: the box with its shell" reload -b "$U"
  else
    no "up of a box with its shell for restart-shell"
  fi
  rpu_down
  # A down of a box not up, then an up of it at once (a few ms each): the down's .down- marker, its
  # start in clock ticks, ties with the up's start, and that up was cancelled as one the down came
  # during (finding 506). Never now, a few times over.
  local i out bad=""
  for i in 1 2 3; do
    HOME=$h ob down "$U" >/dev/null 2>&1
    out=$(HOME=$h ob up "$U" --no-shell --net isolated 2>&1) || bad+="[$out] "
    HOME=$h ob down "$U" >/dev/null 2>&1
  done
  check_eq "down then up at once: the up not cancelled (finding 506)" "" "$bad"
  cx_prep="" cx_also="" cx_sed="" cx_rt="" cx_snap=0 cx_dir=/ cx_check="" cx_env=()
}

# The CLI on a real box (#324: what parity compared with bash's omabox on a live box until the port
# ended, wave 6b-end, each case now stated): its own processes, logs, runtime dir, windows, input,
# shots, monitors, gdb, check and record. What a box's run gives every time is stated whole; what
# hangs on the moment (times, addresses, pids, the desk's bar) is evened out or left to a pattern.
t_cli_box() {
  local B=$P-rp sp="" p ns
  up_ok "$B" --net isolated || { no "up" "$UP_OUT"; return; }
  ns=$(jq -r '.pidns // empty' "$XDG_RUNTIME_DIR/omabox/$B/box.json")
  for p in $(pgrep -x quickshell); do [ "$(readlink "/proc/$p/ns/pid" 2>/dev/null)" != "$ns" ] || sp=$p; done
  cx_rt=$XDG_RUNTIME_DIR cx_dir=/ cx_env=() cx_prep="" cx_snap=0
  # (the box's socket, hard-linked into its dir, which only the host writes: finding 493)
  cx_want=(rc=0 "out=export WAYLAND_DISPLAY=$XDG_RUNTIME_DIR/omabox/$B/wayland"$'\n''unset DISPLAY WAYLAND_SOCKET HYPRLAND_INSTANCE_SIGNATURE' err=)
  cx_case "env of a box up" env -b "$B"
  cx_want=(rc=0 "out=$XDG_RUNTIME_DIR/omabox/$B" err=)
  cx_case "path" path -b "$B"
  cx_want=(rc=0 "out=$XDG_RUNTIME_DIR/omabox/$B/home" err=)
  cx_case "path --home" path --home "$B"
  cx_want=(rc=0 "out=$XDG_RUNTIME_DIR/omabox/$B/run" err=)
  cx_case "path --run" path -b "$B" --run
  cx_want=(rc=0 "out~^hyprland  $XDG_RUNTIME_DIR/omabox/$B/run/hypr/[^/]+/hyprland\\.log\$" "out~^journal   $XDG_RUNTIME_DIR/omabox/$B/home/journal\\.log\$" err=)
  cx_case "path --logs" path --logs -b "$B"
  cx_want=(rc=0 "out~^\\{\"hyprland\":\"$XDG_RUNTIME_DIR/omabox/$B/run/hypr/[^/]+/hyprland\\.log\",\"shell\":\"$XDG_RUNTIME_DIR/omabox/$B/home/shell\\.log\",\"events\":\"$XDG_RUNTIME_DIR/omabox/$B/home/events\\.log\"," err=)
  cx_case "path --logs --json" path --logs --json -b "$B"
  check_eq "which names the box by its shell (what the next two compare)" "$B" "$(ob which "${sp:-0}" 2>/dev/null)"
  cx_want=(rc=0 "out=$B" err=)
  cx_case "which: its shell's host pid" which "${sp:-0}"
  cx_want=(rc=0 "out={\"pid\":${sp:-0},\"box\":\"$B\",\"by\":\"pidns\"}" err=)
  cx_case "which --json: the same" which --json "${sp:-0}"
  cx_want=(rc=1 'out=not in a box' err=)
  cx_case "which: the host shell" which $$
  # Wave 2: events first (a reload below is an event), then hyprctl, lua, run, log.
  cx_want=(rc=0 'out~^[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3} [a-z0-9]+>>' err=)
  cx_case "events -n 3" events -b "$B" -n 3
  cx_want=(rc=0 'out~^\{"time":[0-9]+\.[0-9]+,"event":"[a-z0-9]+","data":".*"\}$' err=)
  cx_case "events --json -n 2" events -b "$B" --json -n 2
  cx_want=(rc=0 'out~^[0-9:.]+ [a-z0-9]+>>.*(monitor|workspace)' 'out!~^[0-9:.]+ [a-z0-9]+>>[^mw]*$' err=)
  cx_case "events --grep" events -b "$B" --grep 'monitor|workspace' -n 2
  cx_want=(rc=0 'out~^[0-9]+$' "err~^omabox: events: mark 'rp' at byte [0-9]+ \\(--since rp\\)\$")
  cx_case "events --mark" events -b "$B" --mark rp
  cx_want=(rc=0 'out~^\{"mark":"rp","offset":[0-9]+\}$' "err~^omabox: events: mark 'rp' at byte [0-9]+ \\(--since rp\\)\$")
  cx_case "events --mark --json" events -b "$B" --mark rp --json
  cx_want=(rc=0 out= err=)
  cx_case "events --since the mark: nothing since" events -b "$B" --since rp
  cx_want=(rc=124 out= 'err=omabox: events: no event matching rp-never in 0.30s')
  cx_case "events --until: none in time, 124" events -b "$B" --until 'rp-never' --timeout 300ms
  cx_wrap=(timeout -s TERM 1); cx_want=(rc=124 out= err=)
  cx_case "events -f: ended by TERM" events -b "$B" -f
  cx_want=(rc=124 out= err=)
  cx_case "log -f box: ended by TERM" log -b "$B" -f box; cx_wrap=()
  cx_want=(rc=0 'out~^Hyprland [0-9.]+ built from branch ' err=)
  cx_case "hyprctl version" hyprctl -b "$B" version
  cx_want=(rc=0 'out~^\[\{$' 'out~^\}\]$' 'out~"name": "(WAYLAND|HEADLESS)-[0-9]+"' err=)
  cx_case "hyprctl -j monitors" hyprctl -b "$B" -j monitors
  cx_want=(rc=7 'out~^error: ' err=)
  cx_case "hyprctl: a bad dispatch, hyprctl's own status" hyprctl -b "$B" dispatch rp-bogus
  cx_want=(rc=0 'out=no such option' err=)
  cx_case "hyprctl getoption of none" hyprctl -b "$B" getoption rp:none
  cx_want=(rc=0 'out=ok' err=)
  cx_case "hyprctl reload: its config errors (none)" hyprctl -b "$B" reload
  cx_want=(rc=1 'out~^usage: hyprctl \[flags\] <command> \[args\.\.\.\|--help\]$' err=)
  cx_case "hyprctl alone: its usage, its status" hyprctl -b "$B"
  cx_want=(rc=0 'out=2' err=)
  cx_case "lua" lua -b "$B" 1+1
  # (a number in standard form, where bash's jq wrote decNumber's 1E+300: finding 449)
  cx_want=(rc=0 $'out="a"\nnull\n{"x":1.5}\n960.0\n1e+300' err=)
  cx_case "lua --json: its values" lua -b "$B" --json 'return "a", nil, {x = 1.5}, 960.0, 1e300'
  cx_want=(rc=0 'out~^a$' 'out~^true$' 'out~^ÿx$' err=)
  cx_case "lua: values as text" lua -b "$B" 'return "a", nil, {1, 2}, true, "\255x"'
  cx_want=(rc=1 out= 'err=lua: lua:1: boom')
  cx_case "lua: an error" lua -b "$B" 'error("boom")'
  cx_want=(rc=0 $'out=]]\n]=]' err=)
  cx_case "lua: a source with ]] in it" lua -b "$B" 'return "]]", "]=]"'
  cx_want=(rc=0 'out~^function: 0x[0-9a-f]+$' 'err=omabox: lua: a function, returned and not called')
  cx_case "lua: a function returned" lua -b "$B" 'return print'
  cx_sed='s/0x[0-9a-f]+/0xADDR/g'; cx_want=(rc=0 'out=HL.Dispatcher' "err=omabox: lua: a dispatcher, returned and not run: omabox lua 'hl.dispatch(EXPR)' (or omabox hyprctl dispatch 'EXPR')")
  cx_case "lua: a dispatcher returned" lua -b "$B" 'hl.dsp.window.close()'; cx_sed=""
  echo 'return 6 * 7' > "$TMP/rp-lua"; cx_in=$TMP/rp-lua; cx_want=(rc=0 'out=42' err=)
  cx_case "lua -: the source on stdin" lua -b "$B" -; cx_in=/dev/null
  cx_want=(rc=3 'out=out' 'err=err')
  cx_case "run: its output, its status" run -b "$B" -- sh -c 'echo out; echo err >&2; exit 3'
  cx_want=(rc=0 "out=/home/sbx"$'\n'"none 1 $B" err=)
  cx_case "run: the box HOME from /, the session's marker left out (finding 424)" run -b "$B" -- sh -c 'pwd; echo "${OMABOX_OWN_SESSION:-none} $OMABOX $OMABOX_NAME"'
  cx_want=(rc=127 out= 'err~exec: rp-no-such-command: not found$')
  cx_case "run: a command not there" run -b "$B" -- rp-no-such-command
  cx_want=(rc=137 out= 'err=omabox: the command was killed by SIGKILL (137)')
  cx_case "run: killed by SIGKILL" run -b "$B" -- sh -c 'kill -KILL $$'
  # (bash's own "Terminated" job line was counted as nsenter's, after a 2 s wait for the box: finding 440)
  cx_want=(rc=143 out= 'err=omabox: the command was killed by SIGTERM (143)')
  cx_case "run: by SIGTERM" run -b "$B" -- sh -c 'kill -TERM $$'
  cx_want=(rc=139 out= 'err=omabox: the command was killed by SIGSEGV (139)')
  cx_case "run: by SIGSEGV" run -b "$B" -- sh -c 'kill -SEGV $$'
  cx_want=(rc=0 out= err=)
  cx_case "run: by SIGINT" run -b "$B" -- sh -c 'kill -INT $$'
  printf 'A=1\nexport B="b b"\n' > "$TMP/rp-env"
  cx_env=(RPP=p1); cx_want=(rc=0 'out=2 b b p1' err=)
  cx_case "run --env-file, --env, --pass" run -b "$B" --env-file "$TMP/rp-env" --env A=2 --pass RPP -- sh -c 'echo "$A $B $RPP"'; cx_env=()
  cx_in=$TMP/rp-env; cx_want=(rc=0 $'out=A=1\nexport B="b b"' err=)
  cx_case "run: stdin passed through" run -b "$B" -- cat; cx_in=/dev/null
  cx_sed='s/run-[0-9]+\.log/run-N.log/g; s/stopped the earlier job \(0 windows\) in [0-9.]+s/stopped the earlier job (0 windows) in Ts/; s/pid [0-9]+/pid P/g'
  cx_want=(rc=4 out= "err~^omabox: the command exited with status 4 at once in box '$B', and left nothing running \\(log: $XDG_RUNTIME_DIR/omabox/$B/home/run-N\\.log\\)\$" "err~^omabox: its log ends \\(omabox log -b $B run\\):\$" 'err~^  said$')
  cx_case "run -d: a job that exits at once, its status" run -b "$B" -d -- sh -c 'echo said; exit 4'
  cx_want=(rc=0 out= err=)
  cx_case "run -d -q: a 0 at once is not said" run -b "$B" -d -q -- true
  cx_want=(rc=2 out= "err~^omabox: note: $TMP is not in box '$B' " "err~^omabox: the command exited with status 2 at once in box '$B', and left nothing running " "err~^  ls: cannot access '.*': No such file or directory\$")
  cx_case "run -d: a host path the box has not" run -b "$B" -d -- ls "$TMP"
  cx_want=(rc=0 "out=$XDG_RUNTIME_DIR/omabox/$B/home/run-N.log" "err=omabox: started in box '$B' (pid P, log: $XDG_RUNTIME_DIR/omabox/$B/home/run-N.log, /home/sbx/run-N.log in the box)")
  cx_case "run -d --print-log: started" run -b "$B" -d --print-log -- sleep 610
  cx_jobs() { ob run -b "$B" -- sh -c 'pkill -x sleep; true' >/dev/null 2>&1; ob run -b "$B" -d -q -- sleep 611 >/dev/null 2>&1; }
  cx_prep=cx_jobs
  cx_want=(rc=0 out= 'err~^omabox: --replace: stopped the earlier job \(0 windows\) in Ts$' "err~^omabox: started in box '$B' ")
  cx_case "run -d --replace: the earlier job stopped" run -b "$B" -d --replace -- sleep 611
  cx_want=(rc=0 out= "err~^omabox: --replace: no earlier job with these arguments, none stopped; sleep \\(pid P, 611\\) still runs, and the new job starts beside it \\(omabox -b $B stop [0-9]+ stops it\\)\$" "err~^omabox: started in box '$B' ")
  cx_case "run -d --replace: another job of the program named" run -b "$B" -d --replace -- sleep 612
  cx_want=(rc=0 out= err=)
  cx_case "run -d --replace -q: none of this command" run -b "$B" -d --replace -q -- true
  cx_prep="" cx_sed=""
  ob run -b "$B" -- sh -c 'pkill -x sleep; true' >/dev/null 2>&1
  cx_want=(rc=0 out= err=)
  cx_case "log box" log -b "$B" box
  cx_want=(rc=0 out= err=)
  cx_case "log: a --grep that matches nothing" log -b "$B" shell --grep 'rp-never-said'
  cx_want=(rc=1 out= "err=omabox: box '$B' has no gdb log yet ($XDG_RUNTIME_DIR/omabox/$B/home/gdb.log)")
  cx_case "log gdb: none yet" log -b "$B" gdb
  cx_want=(rc=0 out= err=)
  cx_case "log run -n 1: the latest run -d's" log -b "$B" run -n 1
  # Wave 3a: wait, windows, tree, pixel, run -d --wait. Times, frame counts and the events log's size
  # differ from call to call (sed); so do the pixels the screen settled on (animation frames: where
  # the last change was, what was ignored), which only the tool's timing decides.
  cx_sed='s/\b[0-9]+\.[0-9]+s\b/Ts/g; s/"(elapsed|first_change|last_change)":[0-9.]+/"\1":T/g; s/"frames":[0-9]+/"frames":N/; s/"events_since":[0-9]+/"events_since":N/; s/run-[0-9]+\.log/run-N.log/g'
  cx_want=(rc=0 'out~^ADDRESS +PID +WORKSPACE +STATE +GEOMETRY +CLASS +TITLE$' 'out!~^0x' err=)
  cx_case "windows: none yet" windows -b "$B"
  cx_want=(rc=0 'out=[]' err=)
  cx_case "windows --json: none" windows -b "$B" --json
  cx_want=(rc=0 'out~^satisfied: layer omarchy-bar after Ts: at ' err=)
  cx_case "wait layer: the bar" wait -b "$B" layer omarchy-bar
  cx_want=(rc=0 'out={"result":"satisfied","condition":"layer","message":"layer rp-none gone after Ts","elapsed":T,"detail":null}' err=)
  cx_case "wait layer --gone --json: none such" wait -b "$B" layer rp-none --gone --json
  cx_want=(rc=124 'out=unsatisfied: no layer rp-none after Ts' err=)
  cx_case "wait layer: none such, 124" wait -b "$B" layer rp-none --timeout 300ms
  cx_want=(rc=124 'out={"result":"unsatisfied","condition":"window","message":"no window rp-none after Ts","elapsed":T,"detail":null}' err=)
  cx_case "wait window --json: none such, 124" wait -b "$B" window rp-none --timeout 300ms --json
  cx_want=(rc=0 'out=satisfied: command succeeded after Ts' err=)
  cx_case "wait until: a command that succeeds" wait -b "$B" until -- true
  cx_want=(rc=124 'out=unsatisfied: command still failing after Ts (exit 1)' err=)
  cx_case "wait until: one still failing, 124" wait -b "$B" until --timeout 400ms -- false
  # (#400: a command not in the box: at once, unknown, 1, its own words said; one failing: its last
  # words; one that names this box's folder here: said before waiting, a `!` of it satisfied at once)
  cx_want=(rc=1 'out=unknown: command not found in the box (exit 127) after Ts' "err~^omabox: wait until: the command's last words \\(stderr\\):\$" "err~^  .*rp-none-cmd")
  cx_case "wait until: a command not in the box: at once, 1, its words" wait -b "$B" until --timeout 20s -- /rp-none-cmd
  cx_want=(rc=124 'out=unsatisfied: command still failing after Ts (exit 2)' "err~^omabox: wait until: the command's last words" 'err~^  boom$')
  cx_case "wait until: one still failing: its last words" wait -b "$B" until --timeout 300ms -- sh -c 'echo boom >&2; exit 2'
  cx_want=(rc=0 'out=satisfied: command succeeded after Ts' "err~^omabox: wait until: the command names .*/$B/home/\\.\\.\\., this box's HOME as the host has it: in the box it is /home/sbx/\\.\\.\\.\$")
  cx_case "wait until: a ! of the box's HOME path here: said before" wait -b "$B" until -- sh -c "! $XDG_RUNTIME_DIR/omabox/$B/home/left.sh"
  cx_want=(rc=0 'out=satisfied: still after Ts (no change)' err=)
  cx_case "wait still: a part of the background" wait -b "$B" still -g '900,300 40x40' --quiet 200ms
  cx_want=(rc=124 'out=unsatisfied: nothing changed in Ts' err=)
  cx_case "wait change: nothing changed, 124" wait -b "$B" change -g '900,300 40x40' --timeout 400ms
  cx_want=(rc=0 'out~^\{"result":"satisfied","condition":"still","message":"still after Ts \(no change\)",' 'err~^omabox: wait: --ignore "0,0 10x10" is outside the region watched: it leaves nothing out')
  cx_case "wait still --json, an --ignore outside the region (said)" wait -b "$B" still --json -g '900,300 40x40' --quiet 200ms --ignore '0,0 10x10'
  cx_want=(rc=0 'out~^#[0-9a-f]{6}$' err=)
  cx_case "pixel: one point" pixel -b "$B" 920 320
  cx_want=(rc=0 'out~^\{"x":920,"y":320,"hex":"#[0-9a-f]{6}","r":[0-9]+,"g":[0-9]+,"b":[0-9]+\}$' 'out~^\{"x":10,"y":10,"hex":"#[0-9a-f]{6}",' err=)
  cx_case "pixel --json: several" pixel -b "$B" --json 920 320 10 10
  cx_want=(rc=1 out= 'err~^omabox: pixel: 5000,1 is outside the screen \([0-9]+x[0-9]+\)$')
  cx_case "pixel: off the screen" pixel -b "$B" 5000 1
  cx_want=(rc=2 out= "err=omabox: tree: the box has no window; the shell's bar, panels and menus are layers: tree --layer NAMESPACE (omabox hyprctl layers)")
  cx_case "tree: no window" tree -b "$B"
  cx_want=(rc=1 out= 'err~^omabox: tree: layer "omarchy-bar" \(pid [0-9]+, [0-9]+x[0-9]+ at [0-9]+,[0-9]+\): the layer publishes no accessible items')
  cx_case "tree --layer: the bar" tree -b "$B" --layer omarchy-bar
  cx_want=(rc=2 out= "err~^omabox: no layer matches rp-none \\(a namespace, address:0x\\.\\.\\. or pid:PID\\); the box's layers:\$" 'err~"omarchy-bar"')
  cx_case "tree --layer: none such, 2" tree -b "$B" --layer rp-none
  # Windows of its own, the same for both sides: two of one class.
  ob run -b "$B" -d -q -- foot -a rp-a -T 'rp "one"' sleep 600 >/dev/null 2>&1
  ob run -b "$B" -d -q -- foot -a rp-a -T 'rp two' sleep 600 >/dev/null 2>&1
  ob wait -b "$B" window rp-a title:two >/dev/null 2>&1; ob wait -b "$B" window 'title:"one' >/dev/null 2>&1
  ob wait -b "$B" still --quiet 500ms >/dev/null 2>&1
  cx_want=(rc=0 'out~^ADDRESS +PID +WORKSPACE +STATE +GEOMETRY +CLASS +TITLE$' 'out~^0x[0-9a-f]+ .* rp-a +"rp \\"one\\""$' 'out~^0x[0-9a-f]+ .* rp-a +"rp two"$' err=)
  cx_case "windows: two of a class and the layers over them" windows -b "$B"
  cx_want=(rc=0 'out~^\[\{"address":"0x[0-9a-f]+",.*"class":"rp-a","title":"rp \\"one\\"",.*\{"address":"0x[0-9a-f]+",.*"class":"rp-a","title":"rp two"' err=)
  cx_case "windows --json" windows -b "$B" --json
  cx_want=(rc=0 'out~^satisfied: window rp-a after Ts: 2 windows: 0x[0-9a-f]+ rp-a "rp \\"one\\"" at [0-9]+,[0-9]+ [0-9]+x[0-9]+; 0x[0-9a-f]+ rp-a "rp two" at [0-9]+,[0-9]+ [0-9]+x[0-9]+, focused$' err=)
  cx_case "wait window: two match, both named" wait -b "$B" window rp-a
  cx_want=(rc=0 'out~^\{"result":"satisfied","condition":"window","message":"window rp-a focused after Ts: 0x[0-9a-f]+ rp-a \\"rp two\\" at [0-9]+,[0-9]+ [0-9]+x[0-9]+, focused \(1 of 2 matching\)",' err=)
  cx_case "wait window --focused --json: one of two" wait -b "$B" window rp-a --focused --json
  cx_want=(rc=124 'out=unsatisfied: window rp-a still there after Ts (2 matching)' err=)
  cx_case "wait window --gone: still there, 124" wait -b "$B" window rp-a --gone --timeout 300ms
  cx_want=(rc=2 out= 'err~^omabox: bad window selector \(class:\(\): ')
  cx_case "wait window: a bad selector, 2" wait -b "$B" window 'class:('
  cx_want=(rc=2 out= 'err~^omabox: rp-a matches 2 windows: name one by its address \(or add a selector\):$' 'err~^  0x[0-9a-f]+  rp-a  "rp two"  workspace [0-9]+$')
  cx_case "wait still --window: two match, 2" wait -b "$B" still --window rp-a
  cx_want=(rc=0 'out=satisfied: still after Ts (no change)' 'err~^omabox: wait: --ignore "5000,0 10x10" is outside window 0x[0-9a-f]+ rp-a "rp \\"one\\"" \([0-9]+x[0-9]+, in its own coordinates\): it leaves nothing out$')
  cx_case "wait still --window: --ignore in its own coordinates, one outside it" wait -b "$B" still --window 'title:"one' --quiet 200ms --ignore '0,0 10x10' --ignore '5000,0 10x10'
  cx_want=(rc=1 out= 'err~^omabox: tree: 0x[0-9a-f]+ rp-a "rp \\"one\\"": no accessibility tree: pid [0-9]+ is not on the box.s accessibility bus')
  cx_case "tree --window: a terminal has none" tree -b "$B" --window 'title:"one'
  cx_want=(rc=2 out= 'err~^omabox: rp-a matches 2 windows: name one by its address \(or add a selector\):$')
  cx_case "tree: two match, 2" tree -b "$B" --window rp-a
  cx_want=(rc=0 'out~^5,5 #[0-9a-f]{6}$' 'out~^20,20 #[0-9a-f]{6}$' err=)
  cx_case "pixel --window" pixel -b "$B" --window 'title:"one' 5 5 20 20
  cx_want=(rc=1 out= 'err~^omabox: pixel: 5000,5 is outside the window \(0x[0-9a-f]+ rp-a "rp \\"one\\""\) \([0-9]+x[0-9]+\)$')
  cx_case "pixel --window: outside it" pixel -b "$B" --window 'title:"one' 5000 5
  ob shot -b "$B" -o "$TMP/rp-s.png" >/dev/null 2>&1
  ob shot -b "$B" --window 'title:"one' -o "$TMP/rp-w.png" >/dev/null 2>&1
  cx_want=(rc=0 'out~^#[0-9a-f]{6}$' err=)
  cx_case "pixel --in: a shot's pixel" pixel -b "$B" --in "$TMP/rp-s.png" 920 320
  cx_want=(rc=0 'out~^#[0-9a-f]{6}$' err=)
  cx_case "pixel --in: a window shot's" pixel -b "$B" --in "$TMP/rp-w.png" 5 5
  cx_want=(rc=1 out= 'err~^omabox: --in: 99999,1 is outside the image \([0-9]+x[0-9]+\)$')
  cx_case "pixel --in: outside the image" pixel -b "$B" --in "$TMP/rp-s.png" 99999 1
  # run -d --wait: each case's window closed before the next opens (the same layout). Its own
  # addresses and pids differ, and the screen's settling is the tool's timing (above).
  cx_sed+='; s/\b0x[0-9a-f]+/0xA/g; s/pid [0-9]+/pid P/g; s/at -?[0-9]+,-?[0-9]+ [0-9]+x[0-9]+/at G/g; s/[0-9]+x[0-9]+ at -?[0-9]+,-?[0-9]+/G/g'
  cx_sed+='; s/"(change|late_changes|ignored)":\{[^}]*\}/"\1":OBJ/g'
  cx_sed+='; s/-?[0-9]+,-?[0-9]+ [0-9]+x[0-9]+/G/g'
  # A small part that never stops changing (a counter): 124, its place named for an --ignore, in the
  # screen's coordinates (-g) and in the window's (--window).
  ob run -b "$B" -d -q -- foot -a rp-tick -T tick sh -c 'while :; do printf "\r%s" "$(date +%N)"; sleep 0.03; done' >/dev/null 2>&1
  ob wait -b "$B" window rp-tick >/dev/null 2>&1
  local tg; tg=$(ob windows -b "$B" --json | jq -r '.[] | select(.class == "rp-tick") | "\(.at[0]),\(.at[1]) \(.size[0])x\(.size[1])"')
  # Each side's own words, before the sed evens the rectangles out: the part named for an --ignore is
  # inside the region watched, and in the window's coordinates it is that place less the window's.
  local tx ty tw th; IFS=', x' read -r tx ty tw th <<<"$tg"
  cx_rect() { sed -E 's/^(-?[0-9]+),(-?[0-9]+) ([0-9]+)x([0-9]+)$/\1 \2 \3 \4/' <<<"$1"; }
  cx_late_screen() {
    local m x y w h; m=$(grep -oE 'changed only at -?[0-9]+,-?[0-9]+ [0-9]+x[0-9]+: --ignore "[^"]*"' "$2") ||
      { no "$1: a part named for an --ignore" "$(cat "$2")"; return; }
    read -r x y w h <<<"$(cx_rect "$(sed -E 's/^changed only at ([^:]*):.*/\1/' <<<"$m")")"
    check_eq "$1: the --ignore is that part" "$x,$y ${w}x$h" "$(sed -E 's/.*--ignore "(.*)"$/\1/' <<<"$m")"
    check "$1: inside the region watched ($tg)" test "$x" -ge "$tx" -a "$y" -ge "$ty" -a $((x + w)) -le $((tx + tw)) -a $((y + h)) -le $((ty + th))
  }
  cx_late_window() {
    local m x y w h ox oy ow oh; m=$(grep -oE 'changed only at -?[0-9]+,-?[0-9]+ [0-9]+x[0-9]+ \(the window.s -?[0-9]+,-?[0-9]+ [0-9]+x[0-9]+\): --ignore \\"[^\\]*' "$2") ||
      { no "$1: a part named for an --ignore" "$(cat "$2")"; return; }
    read -r x y w h <<<"$(cx_rect "$(sed -E 's/^changed only at ([^ ]+ [^ ]+) .*/\1/' <<<"$m")")"
    read -r ox oy ow oh <<<"$(cx_rect "$(sed -E 's/.*the window.s ([^)]*)\).*/\1/' <<<"$m")")"
    check_eq "$1: the window's own place of it" "$((x - tx)) $((y - ty)) $w $h" "$ox $oy $ow $oh"
    check_eq "$1: the --ignore is that" "$ox,$oy ${ow}x$oh" "$(sed -E 's/.*--ignore \\"//' <<<"$m")"
    check_eq "$1: late_changes is the screen's place" "$x $y $w $h" "$(jq -r '.late_changes | "\(.x) \(.y) \(.w) \(.h)"' "$2")"
  }
  cx_check=cx_late_screen; cx_want=(rc=124 'out=unsatisfied: still changing after Ts (last change Ts at G); from Ts on it changed only at G: --ignore "G" if that is an animation' err=)
  cx_case "wait still: one part never still, 124, its place named for an --ignore" wait -b "$B" still -g "$tg" --timeout 1500ms
  cx_check=cx_late_window; cx_want=(rc=124 'out~^\{"result":"unsatisfied","condition":"still","message":"still changing after Ts \(last change Ts at G\); from Ts on it changed only at G \(the window.s G\): --ignore \\"G\\" if that is an animation",' err=)
  cx_case "...with --window: in the window's own coordinates (--json)" wait -b "$B" still --window rp-tick --timeout 1500ms --json
  cx_check=""
  ob run -b "$B" -- sh -c 'pkill -f rp-tick; true' >/dev/null 2>&1
  # (then the screen still: the window's close drawn, not left to the case. pkill's sh, which its -f
  # also kills, cost 2 s more before finding 440, which covered that)
  cx_w3_kill() { ob run -b "$B" -- sh -c 'pkill -f rp-w3; true' >/dev/null 2>&1; ob wait -b "$B" window rp-w3 --gone >/dev/null 2>&1; ob wait -b "$B" still --timeout 5s >/dev/null 2>&1; }
  # What each case's run -d left in the box dir: its job records, the ends it noted, run's marks (their
  # pids, times and log names aside).
  local jd=$XDG_RUNTIME_DIR/omabox/$B cx_noted=0
  cx_w3_prep() { cx_w3_kill; touch "$TMP/rp-mark"; cx_noted=$(cat "$jd/jobs-noted" 2>/dev/null | wc -l); }
  cx_w3_also() {
    local j; for j in "$jd"/jobs/*; do
      [ "$j" -nt "$TMP/rp-mark" ] && jq -c '.pid = "P" | .start = "S" | .log |= sub("run-[0-9]+"; "run-N")' "$j"
    done
    tail -n +$((cx_noted + 1)) "$jd/jobs-noted" 2>/dev/null | sed -E 's/run-[0-9]+/run-N/'
    find "$jd/runs" -newer "$TMP/rp-mark" -printf '%f\n' 2>/dev/null | sed -E 's/^(o|c)\.[0-9]+\.[0-9]+/\1.MARK/' | sort
  }
  cx_prep=cx_w3_prep cx_also=cx_w3_also
  cx_want=(rc=0 'out~^satisfied: settled after Ts \(last change Ts at G.*\); window opened, focused: rp-w3 "w3"$' "err~^omabox: started in box '$B' " 'state~"exe":"foot","argv":\["foot","-a","rp-w3","-T","w3","sleep","600"\]')
  cx_case "run -d --wait: its window opened, the screen settled" run -b "$B" -d --wait -- foot -a rp-w3 -T w3 sleep 600
  cx_want=(rc=0 'out~^\{"result":"satisfied","condition":"settle","message":"settled after Ts \(last change Ts at G.*\); window opened, focused: rp-w3 \\"w3\\"",' "err~^omabox: started in box '$B' " 'state~"exe":"foot"')
  cx_case "run -d --wait --json: what changed, its target" run -b "$B" -d --wait --json -- foot -a rp-w3 -T w3 sleep 600
  cx_want=(rc=3 'out=unsatisfied: nothing changed in Ts; no window from pid P yet; no window, layer or focus changed' 'err~^omabox: the command exited with status 3 before the screen settled, and left nothing running' 'state~^omabox\.run-N\.exit$')
  cx_case "run -d --wait: a command that exits 3, its end said (124)" run -b "$B" -d --wait --timeout 1s -- sh -c 'exit 3'
  cx_want=(rc=124 'out=unsatisfied: nothing changed in Ts; no window from pid P yet; no window, layer or focus changed' 'err~^omabox: the command exited with status 0 before the screen settled, and left nothing running' 'state~^omabox\.run-N\.exit$')
  cx_case "run -d --wait: one that exits 0 and changes nothing (124)" run -b "$B" -d --wait --timeout 1s -- true
  cx_want=(rc=0 'out~^satisfied: settled after Ts \(last change Ts at G\); window opened, focused: rp-w3 "w3"$' "err~^omabox: started in box '$B' " 'state~"exe":"foot"')
  cx_case "run -d --wait --strict --start 3s -g, an --ignore inside it" run -b "$B" -d --wait --strict --start 3s -g '0,0 1920x1080' --ignore '0,0 10x10' -- foot -a rp-w3 -T w3 sleep 600
  # Wave 3b: keys, click, scroll, pointer, drag, shot, calibrate on the real box, into a terminal of
  # its own that echoes what it gets. Each side's input lands on the same desktop: what both say is
  # compared (times, and the rectangles of the screen's settling, as above), the shots' records with
  # their stamps aside, and the images they wrote by their sizes (the bar's clock ticks between sides).
  ob run -b "$B" -d -q -- foot -a rp-k -T rpk cat >/dev/null 2>&1
  ob wait -b "$B" window rp-k >/dev/null 2>&1; ob wait -b "$B" still --quiet 500ms >/dev/null 2>&1
  local o3=$TMP/rp-out3 bd=$XDG_RUNTIME_DIR/omabox/$B
  local cx_shots0=0
  cx_live3_prep() { rm -rf "${o3:?}"; mkdir -p "$o3"; cx_shots0=$(cat "$bd/shots.tsv" 2>/dev/null | wc -l); }
  # (what each case's shots added to the box's record)
  cx_live3_also() {
    [ ! -f "$bd/shots.tsv" ] || tail -n +$((cx_shots0 + 1)) "$bd/shots.tsv" | sed -E 's/\t[0-9]+ [0-9]+\.[0-9]{9}\t/\tSTAMP\t/'
    [ ! -f "$bd/pointer" ] || sed -E 's/(hold shot) [0-9]+/\1 PID/' "$bd/pointer"
    (cd "$o3" && command find . -printf '%p %y\n' | LC_ALL=C sort)
    local f; for f in "$o3"/*.png "$o3"/*/*.png; do [ -f "$f" ] && echo "${f#"$o3"/} $(magick identify -format '%w %h' "$f")"; done
    return 0
  }
  cx_prep=cx_live3_prep cx_also=cx_live3_also cx_env=(RPSEC=rp-secret)
  cx_sed='s/\b[0-9]+\.[0-9]+s\b/Ts/g; s/"(elapsed|first_change|last_change)":[0-9.]+/"\1":T/g; s/"frames":[0-9]+/"frames":N/; s/"events_since":[0-9]+/"events_since":N/'
  cx_sed+='; s/\b0x[0-9a-f]+/0xA/g; s/pid [0-9]+/pid P/g; s/at -?[0-9]+,-?[0-9]+ [0-9]+x[0-9]+/at G/g; s/[0-9]+x[0-9]+ at -?[0-9]+,-?[0-9]+/G/g'
  cx_sed+='; s/"(change|late_changes|ignored)":\{[^}]*\}/"\1":OBJ/g; s/-?[0-9]+,-?[0-9]+ [0-9]+x[0-9]+/G/g'
  cx_want=(rc=0 out= err=)
  cx_case "keys -t into the active window" keys -b "$B" -t 'rp one' Return
  cx_want=(rc=0 out= err=)
  cx_case "keys --window --pass" keys -b "$B" --window rp-k --pass RPSEC Return
  cx_want=(rc=0 out= err= 'state!~^\./pointer')
  cx_case "keys down:/up: in one call (the holder in the box)" keys -b "$B" down:shift up:shift
  cx_want=(rc=0 'out~^satisfied: settled after Ts' err=)
  cx_case "keys --wait --window: what the keys did" keys -b "$B" --wait --window rp-k -t x
  cx_want=(rc=2 out= "err~^omabox: no window matches rp-none; the box's windows:\$" 'err~^  0xA  rp-k  "rpk"  workspace [0-9]+$')
  cx_case "keys --window: none such" keys -b "$B" --window rp-none a
  cx_want=(rc=0 out= 'err!~^omabox: [^a]')
  cx_case "click --window" click -b "$B" --window rp-k 20 20
  cx_want=(rc=0 out= 'err!~^omabox: [^a]')
  cx_case "click --steps --mod" click -b "$B" --steps 3 --mod ctrl --window rp-k 30 30
  # (the pointer from the same place: the click before left it at its point, so this one would make
  # no move and no cursor change to ignore)
  cx_ptr_home() { cx_live3_prep; ob pointer -b "$B" -- move 5 5 >/dev/null 2>&1; ob wait -b "$B" still --quiet 300ms >/dev/null 2>&1; }
  cx_prep=cx_ptr_home
  cx_want=('rc~^(0|124)$' 'out~^\{"result":"(satisfied|unsatisfied)","condition":"settle","message":".*the click at [0-9]+,[0-9]+ was on rp-k \\"rpk\\" \(its 40,40\)')
  cx_case "click --wait --json --window" click -b "$B" --wait --json --window rp-k 40 40
  cx_prep=cx_live3_prep
  cx_want=(rc=1 out= "err~^omabox: click: 99999,1 is off the [0-9]+x[0-9]+ screen of box '$B'\$")
  cx_case "click off the screen" click -b "$B" 99999 1
  cx_want=(rc=0 out= 'err!~^omabox: [^a]')
  cx_case "scroll --window" scroll -b "$B" --window rp-k 20 20 15
  cx_want=(rc=0 out= 'err~^omabox: scroll: a wheel turns in notches of 15: DY 20 is 1 notch \(15\), DX -7 is 1 notch \(-15\)$')
  cx_case "scroll --source wheel: notches" scroll -b "$B" --window rp-k 20 20 20 -7 --source wheel
  cx_want=(rc=0 out= err=)
  cx_case "pointer: a move and a click" pointer -b "$B" -- move 100 100 click
  cx_want=(rc=0 out= 'err!~^omabox: [^a]')
  cx_case "pointer --steps --window" pointer -b "$B" --steps 3 --window rp-k -- move 10 10 sleep 20ms
  cx_want=(rc=0 out= "err=omabox: pointer: hidden in box '$B' (shots, recordings, peek) until omabox pointer show; it still moves, and focus follows it" 'state~^hidden$')
  cx_case "pointer hide" pointer -b "$B" hide
  cx_want=(rc=0 out= "err=omabox: pointer: shown in box '$B'" 'state!~^hidden$')
  cx_case "pointer show" pointer -b "$B" show
  cx_want=(rc=0 out= 'err!~^omabox: [^a]')
  cx_case "drag" drag -b "$B" --window rp-k 10 10 60 60
  cx_want=('rc~^(0|124)$' 'out~^\{"result":"(satisfied|unsatisfied)","condition":"settle","message":".*the drag from [0-9]+,[0-9]+ started on rp-k \\"rpk\\" \(its 10,10\)')
  cx_case "drag --wait --json" drag -b "$B" --wait --json --window rp-k 10 10 60 60
  cx_want=(rc=0 "out=$o3/d.png" 'state~^\./d\.png f$' 'state~^d\.png 300 [0-9]+$')
  cx_case "drag --shot" drag -b "$B" --shot "$o3/d.png" --shot-fit 300 --window rp-k 10 10 60 60
  cx_want=(rc=0 "out=$o3/s.png" err= 'state~^s\.png [0-9]+ [0-9]+$' 'state~	screen 0,0	')
  cx_case "shot -o" shot -b "$B" -o "$o3/s.png"
  cx_want=(rc=0 "out={\"path\":\"$o3/g.png\",\"kind\":\"region\",\"region\":{\"x\":100,\"y\":100,\"w\":200,\"h\":100},\"image\":{\"w\":200,\"h\":100},\"scale\":1,\"window\":null,\"monitor\":null,\"fit\":null,\"zoom\":null,\"changed\":null}" "err=omabox: 200x100 image of the screen's G; click with --in $o3/g.png" 'state~^g\.png 200 100$')
  cx_case "shot --json -g" shot -b "$B" --json -g '100,100 200x100' -o "$o3/g.png"
  cx_want=(rc=0 "out~^\\{\"path\":\"$o3/w\\.png\",\"kind\":\"window\",.*\"window\":\\{\"address\":\"0xA\",\"class\":\"rp-k\",\"title\":\"rpk\"," 'state~^w\.png [0-9]+ [0-9]+$')
  cx_case "shot --window --json" shot -b "$B" --window rp-k --json -o "$o3/w.png"
  cx_want=(rc=0 "out=$o3/f.png" "err~^omabox: 500x[0-9]+ image of the screen's G \\(x[0-9.]+\\); click with --in $o3/f\\.png\$" 'state~^f\.png 500 [0-9]+$')
  cx_case "shot --fit --no-pointer" shot -b "$B" --fit 500 --no-pointer -o "$o3/f.png"
  cx_want=(rc=0 "out=$o3/z.png" "err=omabox: 160x120 image of the screen's G (zoomed 4 times); click with --in $o3/z.png" 'state~^z\.png 160 120$')
  cx_case "shot --zoom" shot -b "$B" --zoom 4 -g '0,0 40x30' -o "$o3/z.png"
  # (a headless box's screen is HEADLESS-2; NVIDIA's is WAYLAND-1, and it has no HEADLESS-2)
  if [ "$(ob mode -b "$B" 2>/dev/null | cut -d' ' -f1)" = HEADLESS-2 ]; then
    cx_want=(rc=0 "out~^\\{\"path\":\"$o3/m\\.png\",\"kind\":\"monitor\",.*\"monitor\":\"HEADLESS-2\"," 'state~^m\.png 1920 1080$')
  else cx_want=(rc=1 out= "err=omabox: shot: box '$B' has no monitor HEADLESS-2 (WAYLAND-1)"); fi
  cx_case "shot --monitor" shot -b "$B" --monitor HEADLESS-2 --json -o "$o3/m.png"
  cx_want=(rc=1 out= "err~^omabox: shot: box '$B' has no monitor rp-none \\((WAYLAND-1|HEADLESS-2)\\)\$")
  cx_case "shot --monitor: none such" shot -b "$B" --monitor rp-none -o "$o3/m.png"
  cx_live3_ref() { cx_live3_prep; ob shot -b "$B" --window rp-k -o "$o3/ref.png" >/dev/null 2>&1; cx_live3_prep_keep; }
  cx_live3_prep_keep() { cx_shots0=$(cat "$bd/shots.tsv" 2>/dev/null | wc -l); }
  cx_prep=cx_live3_ref
  cx_want=(rc=0 "out~^\\{\"path\":null,\"kind\":\"window\",.*\"changed\":\\{\"result\":\"nothing\",\"since\":\"$o3/ref\\.png\"" 'state!~^\./c\.png')
  cx_case "shot --changed --window: nothing changed" shot -b "$B" --changed --window rp-k --json -o "$o3/c.png"
  cx_want=(rc=0 out= "err~^omabox: --changed: nothing changed in window 0xA rp-k \"rpk\" since $o3/ref\\.png \\(Ts ago\\): no image\$" 'state!~^\./c\.png')
  cx_case "shot --changed --since" shot -b "$B" --changed --window rp-k --since "$o3/ref.png" -o "$o3/c.png"
  cx_prep=cx_live3_prep
  cx_want=(rc=0 "out~^$o3/b/frame-001\\.png Ts\$" "out~^$o3/b/frame-002\\.png Ts( same)?\$" "err~^omabox: 2 frames of [0-9]+x[0-9]+ \\(window 0xA\\) over Ts, Ts apart, in $o3/b; click with --in a frame\$" 'state~^\./b/frame-002\.png f$')
  cx_case "shot --burst --window --diff" shot -b "$B" --burst 2 --every 0 --window rp-k --diff -o "$o3/b"
  cx_want=(rc=0 "out=$o3/card.png" 'err~^omabox: a [0-9]+x[0-9]+ test card \(the size of a full shot of the box\): 6 marks, A to F,' 'state~^\./card\.png f$')
  cx_case "calibrate: the box's full-shot size" calibrate -b "$B" -o "$o3/card.png"
  cx_want=(rc=1 out= "err=omabox: keys-to-box: box '$B' is headless: it has no window on your desktop to type into (omabox keys sends it keys)")
  cx_case "keys-to-box: a headless box" keys-to-box -b "$B" on
  cx_prep="" cx_sed="" cx_also="" cx_env=()
  ob run -b "$B" -- sh -c 'pkill -x foot; true' >/dev/null 2>&1
  # Wave 4a: mode, monitor, output, gpu, cpu on a real box, each case from the same layout (put back
  # before it), what it left in box.json and the box's records after it. A box of its own with no
  # shell, checked alive after each group (a crash would make every case after it a dead box's).
  ob down "$B" >/dev/null 2>&1
  B=$P-rp4
  up_ok "$B" --no-shell --net isolated || { no "up (wave 4a)" "$UP_OUT"; return; }
  local mon_d=$XDG_RUNTIME_DIR/omabox/$B mn m2 nv=""
  # (its screen: HEADLESS-2 on a headless box, WAYLAND-1 on NVIDIA's, whose monitors are Wayland
  # outputs; the first monitor added is HEADLESS-3 or WAYLAND-2)
  mn=$(ob mode -b "$B" 2>/dev/null | cut -d' ' -f1)
  case $mn in WAYLAND-*) m2=WAYLAND-2 nv=1 ;; *) m2=HEADLESS-3 ;; esac
  cx_lay() {
    local n; for n in $(ob monitor -b "$B" list --json 2>/dev/null | jq -r '.[] | select(.name != "'"$mn"'") | .name'); do
      if [ "$(jq -r --arg n "$n" 'any(.[]; .name == $n and .dropped)' < <(ob monitor -b "$B" list --json))" = true ]; then ob output -b "$B" back "$n" >/dev/null 2>&1; fi
      ob monitor -b "$B" remove "$n" >/dev/null 2>&1
    done
    [ ! -s "$mon_d/output.dropped" ] || ob output -b "$B" back >/dev/null 2>&1
    [ "$(ob mode -b "$B" 2>/dev/null)" = "$mn 1920x1080@60" ] || ob mode -b "$B" 1920x1080 >/dev/null 2>&1
  }
  cx_lay_m() { cx_lay; ob monitor -b "$B" add 800x600 >/dev/null 2>&1; }
  cx_lay_also() {
    jq -c '{size, scale, monitors}' "$mon_d/box.json"; cat "$mon_d/run/omabox.monitors" "$mon_d/run/omabox.mode" "$mon_d/output.dropped" 2>/dev/null
    ob hyprctl -b "$B" -j monitors | jq -c '[.[] | {name, width, height, x, y, scale}]'
  }
  cx_prep=cx_lay cx_also=cx_lay_also
  cx_want=(rc=0 "out=$mn 1920x1080@60" err= 'state~^\{"size":"1920x1080@60","scale":1,')
  cx_case "mode" mode -b "$B"
  cx_want=(rc=0 "out={\"name\":\"$mn\",\"mode\":\"1920x1080@60\",\"scale\":1}" err=)
  cx_case "mode --json" mode -b "$B" --json
  cx_want=(rc=0 "out=$mn 1280x720@60" err= 'state~^\{"size":"1280x720@60","scale":1,' 'state~"width":1280,"height":720,')
  cx_case "mode WxH" mode -b "$B" 1280x720
  cx_want=(rc=0 "out~^$mn 2560x1440@30,scale=1\\.[56]\$" 'state~^\{"size":"2560x1440@30",' 'state~"width":2560,"height":1440,')
  cx_case "mode WxH@HZ,scale=S" mode -b "$B" 2560x1440@30,scale=1.5
  cx_want=(rc=0 'out~^NAME +MODE +SCALE +POSITION +WORKSPACE$' "out~^$mn +1920x1080@60 +1 +0,0 " err=)
  cx_case "monitor list" monitor -b "$B" list
  cx_want=(rc=0 "out=$m2" "err=omabox: box '$B' has a monitor $m2 800x600@60 1920x0 1" "state~\"name\":\"$m2\",\"mode\":\"800x600@60\",\"scale\":1,\"x\":1920,\"y\":0")
  cx_case "monitor add" monitor -b "$B" add 800x600
  # (a name of its own: a headless box's alone, NVIDIA's names are the outputs')
  if [ -n "$nv" ]; then cx_want=(rc=1 out= "err=omabox: monitor add: an NVIDIA box's monitors are Wayland outputs, WAYLAND-N as its screen is: no --name")
  else cx_want=(rc=0 'out=rp-side' 'state~"name":"rp-side","mode":"1024x768@60","scale":2,"x":0,"y":1080'); fi
  cx_case "monitor add below, scaled, named" monitor -b "$B" add 1024x768,scale=2,below --name rp-side
  check "...the box lived through them" ob hyprctl -b "$B" version
  cx_prep=cx_lay_m
  cx_want=(rc=0 "out~^\\[\\{\"name\":\"$mn\",\"mode\":\"1920x1080@60\",\"scale\":1,\"x\":0,\"y\":0,.*\\{\"name\":\"$m2\",\"mode\":\"800x600@60\",\"scale\":1,\"x\":1920,\"y\":0," err=)
  cx_case "monitor list --json: one made" monitor -b "$B" list --json
  cx_want=(rc=0 "out=$mn 1280x720@60" "err=omabox: mode: moved the monitors placed next to it: $m2 to 1280,0" "state~\"name\":\"$m2\",\"mode\":\"800x600@60\",\"scale\":1,\"x\":1280,\"y\":0")
  cx_case "mode: the monitor placed next to it moves" mode -b "$B" 1280x720
  cx_want=(rc=0 "state!~\"name\":\"$m2\"")
  cx_case "monitor remove" monitor -b "$B" remove "$m2"
  cx_want=(rc=0)
  cx_case "output drop: a monitor" output -b "$B" drop "$m2"
  cx_want=(rc=0)
  cx_case "output drop --for --cycles" output -b "$B" drop "$m2" --for 100ms --cycles 2
  check "...the box lived through them" ob hyprctl -b "$B" version
  cx_prep=cx_lay
  # (the figures are the window's: their numbers left out, the rows and what they are kept)
  cx_sed='s/[0-9]+\.[0-9]+(%|M|G)/N\1/g; s/: [0-9]+(\.[0-9]+)?(,?)$/: N\2/'
  # (NVIDIA: gpu reads `nvidia-smi pmon` through a stand-in on PATH that logs the words it was given
  # and passes the real one's table on, or, where nvidia-smi does not work, a fixed table for every
  # process named Hyprland, quickshell or omabox-labwc; a box not on NVIDIA never calls it. t_main's
  # gpu --json on NVIDIA has a live sampling's figures.)
  local rpnv=$TMP/rp-nv; mkdir -p "$rpnv"
  cat > "$rpnv/nvidia-smi" <<EOF
#!/bin/bash
echo "nvidia-smi \$*" >> $rpnv/log
[ "\${1:-}" = pmon ] || exec /usr/bin/nvidia-smi "\$@"
if [ -f $rpnv/pmon.rec ]; then
  [ "\$*" = "\$(cat $rpnv/pmon.args)" ] || { echo "stand-in: pmon replayed for other words: \$(cat $rpnv/pmon.args)"; exit 9; }
  cat $rpnv/pmon.rec; exit "\$(cat $rpnv/pmon.rc)"
fi
echo "\$*" > $rpnv/pmon.args
if [ -x /usr/bin/nvidia-smi ] && /usr/bin/nvidia-smi "\$@" > $rpnv/pmon.rec 2>&1; then
  echo 0 > $rpnv/pmon.rc
else
  n=1 a=("\$@"); for ((k = 0; k < \${#a[@]}; k++)); do [ "\${a[k]}" != -c ] || n=\${a[k + 1]}; done
  { echo "# gpu         pid   type     sm    mem    enc    dec    jpg    ofa    command "
    echo "# Idx           #    C/G      %      %      %      %      %      %    name "
    for i in \$(seq "\$n"); do
      for p in \$(pgrep -x 'Hyprland|quickshell|omabox-labwc' | sort -n); do
        case \$(cat /proc/\$p/comm 2>/dev/null) in
          Hyprland) v="     3      1      -      -      -      -";;
          quickshell) v="     \$i      -      0      -      -      -";;
          *) v="     -      -      -      -      -      -";;
        esac
        printf '    0 %10d     G %s    %s\\n' "\$p" "\$v" "\$(cat /proc/\$p/comm 2>/dev/null)"
      done
    done; } > $rpnv/pmon.rec
  echo 0 > $rpnv/pmon.rc
fi
cat $rpnv/pmon.rec; exit "\$(cat $rpnv/pmon.rc)"
EOF
  chmod +x "$rpnv/nvidia-smi"
  # (its words, the case's state; the recording dropped before each gpu case)
  cx_gpu_also() { cat "$rpnv/log" 2>/dev/null; rm -f "$rpnv/log"; }
  cx_gpu_fresh() { rm -f "$rpnv/pmon.rec" "$rpnv/pmon.args" "$rpnv/pmon.rc"; }
  cx_gpu_fresh
  cx_env=(PATH="$rpnv:$PATH") cx_also=cx_gpu_also
  cx_want=(rc=0 'out~^\{$' "out~^  \"box\": \"$B\",\$" "out~^  \"output\": \"$mn\",\$" err=)
  cx_case "gpu --json" gpu -b "$B" 500ms --json
  cx_env=() cx_also=cx_lay_also
  cx_check=""
  cx_want=(rc=0 "out~^box '$B': 1920x1080@60 on $mn, 0\\.3s, CPU as % of one core \\([0-9]+ cores\\), memory as last seen\$" 'out~^  total ' err=)
  cx_case "cpu --pid 1" cpu -b "$B" 300ms --pid 1
  # (--threads of a one-thread process of its own: PID 1's threads come in CPU order, which flakes)
  ob run -b "$B" -d -q -- sleep 600 >/dev/null 2>&1
  cx_want=(rc=0 'out~^\{$' "out~^  \"box\": \"$B\",\$" 'out~"threads"' err=)
  cx_case "cpu --app --threads --json" cpu -b "$B" 300ms --app sleep --threads --json
  cx_gpu_fresh
  cx_sed='s/^  [^ ]+ +[0-9]+\.[0-9]%$/  ROW/' cx_env=(PATH="$rpnv:$PATH") cx_also=cx_gpu_also
  cx_want=(rc=0 "out~^box '$B': 1920x1080@60 on $mn, " err=)
  cx_case "gpu: its rows" gpu -b "$B" 300ms
  cx_sed="" cx_env=() cx_also=cx_lay_also
  check "...the box lived through them" ob hyprctl -b "$B" version
  # (The main screen's drop and back are on the stand-in desktop of t_unit_monitor_add_window, and t_output's
  # on a real box: here the main screen dropped once more, after it was back, crashed this Hyprland
  # (0.56.2, SIGSEGV), with the shell up and without: every case after it would have been a dead
  # box's.)
  # Wave 4b, live: gdb with the real gdb (its attach chatter left out: the values it prints, its
  # status kept), --watch (the watcher ended before each case), check point/diff on the box's shots
  # and check run with clean boxes of its own (approve, then a check against that baseline).
  cx_sed='/^\$[0-9]+ = /!d'
  cx_want=(rc=0 'out=$1 = 42' err=)
  cx_case "gdb: a value printed from Hyprland" gdb -b "$B" -- -ex 'print 6*7'
  cx_want=(rc=0 'out=$1 = 2' err=)
  cx_case "gdb --pid 1: a value" gdb -b "$B" --pid 1 -- -ex 'print 1+1'
  cx_sed=""
  cx_want=(rc=1 out= "err=omabox: gdb: box '$B' has no process 999999 (omabox run -b $B -- ps -e)")
  cx_case "gdb --pid: not in the box" gdb -b "$B" --pid 999999
  cx_gdbw() { ob run -b "$B" -- sh -c 'pkill -TERM -x gdb; for i in $(seq 50); do pgrep -x gdb >/dev/null || exit 0; sleep 0.1; done' >/dev/null 2>&1 || true; }
  cx_prep=cx_gdbw
  cx_want=(rc=0 out= "err~^omabox: gdb watches Hyprland \\(pid [0-9]+ in box '$B'\\): on a crash, every thread's backtrace goes to omabox log -b $B gdb")
  cx_case "gdb --watch: attached" gdb -b "$B" --watch
  check "...its log has the header" grep -q '^== omabox gdb --watch ' "$XDG_RUNTIME_DIR/omabox/$B/home/gdb.log"
  cx_want=(rc=0 out= "err~^omabox: gdb watches Hyprland \\(pid [0-9]+ in box '$B'\\)")
  cx_case "gdb: traced already by the watcher" gdb -b "$B" --watch
  cx_gdbw; cx_prep=""
  local ck=$TMP/rp-check; rm -rf "$ck"; mkdir -p "$ck"
  local r_sig=$TMP/rp-sig-live; rp_sig_write "$r_sig"
  cx_ckp() { rm -rf "$ck/p"; mkdir -p "$ck/p"; }
  cx_ckls() { (cd "$ck" && command find . -printf '%p %y\n' | LC_ALL=C sort; for f in $(command find . -name '*.point' | LC_ALL=C sort); do echo "== $f"; cat "$f"; done); }
  cx_prep=cx_ckp cx_also=cx_ckls
  cx_want=(rc=0 "out=$ck/p/rp1.png" err= 'state~^of screen$' 'state~^settled yes$')
  cx_case "check point: the screen" check point -b "$B" rp1 -o "$ck/p"
  cx_want=(rc=0 "out=$ck/p/rp2.png" "err=omabox: check point rp2: --ignore \"900,900 5x5\" has nothing in the shot (the screen's coordinates; it covers 300x200 at 0,0): left out" 'state~^of region 0,0 300x200$' 'state~^ignore 10 10 20 20$' 'state!~^ignore 900 ')
  cx_case "check point -g, --ignore" check point -b "$B" rp2 -o "$ck/p" -g "0,0 300x200" --ignore "10,10 20x20" --ignore "900,900 5x5"
  # (decimal: 08 is 8, the region kept; bash's omabox ended at it, the region left out: finding 448)
  cx_want=(rc=0 "out=$ck/p/rp3.png" err= 'state~^ignore 8 0 10 10$')
  cx_case "check point --ignore 08: decimal, kept" check point -b "$B" rp3 -o "$ck/p" --ignore "08,0 10x10"
  # (one partly outside the shot: kept, cut, and what was kept said: #342)
  cx_want=(rc=0 "out=$ck/p/rp5.png" "err=omabox: check point rp5: --ignore \"290,190 20x20\" is partly outside the shot (the screen's coordinates; it covers 300x200 at 0,0): cut to 10x10 at 290,190" 'state~^ignore 290 190 10 10$')
  cx_case "check point --ignore partly outside -g: cut, said" check point -b "$B" rp5 -o "$ck/p" -g "0,0 300x200" --ignore "290,190 20x20"
  # (-g kept as read, decimal and grim's form, however it was typed: #384)
  cx_want=(rc=0 "out=$ck/p/rp4.png" err= 'state~^of region 0,10 300x200$')
  cx_case "check point -g 00,010 300,200: kept as read" check point -b "$B" rp4 -o "$ck/p" -g "00,010 300,200"
  # (its .point that cannot be written: said in omabox's words, 2, check's own failure: finding 442)
  cx_ckpd() { cx_ckp; mkdir -p "$ck/p/rpx.point"; }
  cx_prep=cx_ckpd; cx_want=(rc=2 out= "err=omabox: check: cannot write $ck/p/rpx.point: Is a directory")
  cx_case "check point: its .point cannot be written (2 in Rust)" check point -b "$B" rpx -o "$ck/p"; cx_prep=cx_ckp
  cx_ckp; ob check point -b "$B" s1 -o "$ck/p" >/dev/null 2>&1; ob check point -b "$B" s2 -o "$ck/p" -g "0,0 300x200" >/dev/null 2>&1
  cx_prep="" cx_sed='s/\(specks: [0-9]+, [0-9]+ px\)/(specks)/; s/^specks: [0-9]+, [0-9]+ px$/specks/'
  cx_want=(rc=0 'out=same (specks)' err=)
  cx_case "check diff: two shots of the box" check diff "$ck/p/s1.png" "$ck/p/s1.png"
  cx_want=(rc=1 'out={"result":"changed","size":{"from":"1920x1080","to":"300x200"},"regions":[],"specks":null,"marked":null,"report":null}' err=)
  cx_case "check diff: sizes" check diff --json "$ck/p/s1.png" "$ck/p/s2.png"
  # check run: a scenario that takes two checkpoints; its boxes named as the suite's.
  printf '#!/bin/sh\nomabox check point whole && omabox check point part -g "0,0 400x300"\n' > "$ck/scen"; chmod +x "$ck/scen"
  # (a checkpoint with -g and --ignore with zeros in front, 010 and 08, on a clean box: read as
  # decimal, its --ignore 010,010 is 0,0 of its region at 10,10 and 08,0 is outside it, finding 448)
  printf '#!/bin/sh\nomabox check point lz -g "010,010 400x300" --ignore "08,0 10x10" --ignore "010,010 20x20"; omabox check point lz8 -g "08,0 400x300"; omabox check point whole\n' > "$ck/lz"; chmod +x "$ck/lz"
  printf '#!/bin/sh\necho trying; exit 5\n' > "$ck/bad"; printf '#!/bin/sh\necho nothing\n' > "$ck/none"; chmod +x "$ck/bad" "$ck/none"
  cx_ckr() { rm -rf "$ck/base" "$ck/o"; }
  cx_prep=cx_ckr cx_env=(OMABOX_CHECK_NAME="$P-rpc") cx_also=cx_ckls
  cx_sed='s/box up in [0-9]+ s/box up in N s/; s/(the runs. largest stray part was) [0-9]+ px/\1 N px/; s/(under|was) [0-9]+ px/\1 N px/g'
  cx_want=(rc=0 'out~^baseline whole \(specks under N px left out: the runs agreed to the pixel\)$' 'out~^baseline part ' "err~^omabox: check: run 1 of 2: a clean box \\($P-rpc-1\\), then: $ck/scen\$" 'state~^\./base/whole\.point f$' 'state~^\./base/part\.png f$')
  cx_case "check run --approve --runs 2" check run --approve --runs 2 --base "$ck/base" -o "$ck/o" -- "$ck/scen"
  cx_ckr; OMABOX_CHECK_NAME="$P-rpc" ob check run --approve --runs 2 --base "$ck/base" -o "$ck/o" -- "$ck/scen" >/dev/null 2>&1
  rm -rf "$ck/base0"; cp -a "$ck/base" "$ck/base0"
  cx_ckc() { rm -rf "$ck/base" "$ck/o"; cp -a "$ck/base0" "$ck/base"; }
  cx_prep=cx_ckc
  cx_want=(rc=0 "out=same     whole"$'\n'"same     part"$'\n'"check: 2 of 2 same; shots in $ck/o/run1" "err~^omabox: check: run 1 of 1: a clean box \\($P-rpc-1\\), then: $ck/scen\$")
  cx_case "check run: against its baseline" check run --base "$ck/base" -o "$ck/o" -- "$ck/scen"
  cx_want=(rc=0 'out~^\{"result":"same",.*"counts":\{"checkpoints":2,"same":2,"changed":0,"as_another":0,"holes":0,"new":0,"missing":0\},')
  cx_case "check run --json: against its baseline" check run --json --base "$ck/base" -o "$ck/o" -- "$ck/scen"
  cx_want=(rc=3 out= "err~^omabox: check: the scenario failed in run 1 \\(exit 5\\): trying \\($ck/o/run1\\.log\\)\$")
  cx_case "check run: the scenario failed, exit 3" check run --base "$ck/base" -o "$ck/o" -- "$ck/bad"
  cx_want=(rc=3 "out={\"result\":\"failed\",\"exit\":0,\"log\":\"$ck/o/run1.log\",\"message\":\"the scenario took no checkpoint\"}" 'err~^omabox: check: the scenario took no checkpoint')
  cx_case "check run --json: no checkpoint taken" check run --json --base "$ck/base" -o "$ck/o" -- "$ck/none"
  # (a scenario not there, said in omabox's words: finding 441)
  cx_sed='s/box up in [0-9]+ s/box up in N s/'
  cx_want=(rc=3 out= "err~^omabox: check: the scenario failed in run 1 \\(exit 127\\): omabox: check: cannot run scenario rp-no-such-scenario: not found in PATH \\($ck/o/run1\\.log\\)\$")
  cx_case "check run: a scenario not there, 127" check run --base "$ck/base" -o "$ck/o" -- rp-no-such-scenario
  # (a scenario named like a function of bash's omabox: a program, and there is none, finding 451)
  cx_want=(rc=3 out= "err~^omabox: check: the scenario failed in run 1 \\(exit 127\\): omabox: check: cannot run scenario say: not found in PATH \\($ck/o/run1\\.log\\)\$")
  cx_case "check run: a scenario named like omabox's say" check run --base "$ck/base" -o "$ck/o" -- say
  cx_want=(rc=1 'out~^\{"result":"changed",.*"counts":\{"checkpoints":4,"same":1,"changed":0,"as_another":0,"holes":0,"new":2,"missing":1\},' 'state~^== \./o/run1/lz8\.point$' 'state~^ignore 0 0 20 20$' 'state!~^ignore 8 ')
  cx_case "check run --json: checkpoints with 010 and 08 in them" check run --json --base "$ck/base" -o "$ck/o" -- "$ck/lz"
  # Scenarios bash cannot run as they are: not executable, a dir, binary; one with no #! is a
  # script bash runs itself; a path to nothing.
  printf 'echo hi\n' > "$ck/noexec"; mkdir -p "$ck/adir"; printf '\000\001x' > "$ck/binary"; chmod +x "$ck/binary"
  printf 'omabox check point whole\n' > "$ck/nosb"; chmod +x "$ck/nosb"
  printf '#!/bin/sh\r\nomabox check point whole\r\n' > "$ck/crlf"; printf '#!/nonexistent/interp -x\n' > "$ck/badint"; chmod +x "$ck/crlf" "$ck/badint"
  cp /usr/bin/true "$ck/xonly"; chmod 0711 "$ck/xonly"
  # (an ELF whose loader is not there; a #! whose interpreter cannot be run; one with no newline,
  # bash's 80-byte sample less its last byte; a CR inside the name)
  python3 -c 'import sys; d = open("/usr/bin/true", "rb").read(); i = d.index(b"/lib64/ld-linux"); open(sys.argv[1], "wb").write(d[:i] + b"/nonexistent/ld.so\0".ljust(len(b"/lib64/ld-linux-x86-64.so.2"), b"\0") + d[i + len(b"/lib64/ld-linux-x86-64.so.2"):])' "$ck/noload"
  printf '#!/etc/passwd\n' > "$ck/eacces"; printf '#!/nonexistent/interp' > "$ck/nonl"; printf '#!/bin/s\rh x\n' > "$ck/midcr"
  chmod +x "$ck/noload" "$ck/eacces" "$ck/nonl" "$ck/midcr"
  # (what each gets, after "the scenario failed in run 1 (exit N): ", in omabox's words, finding 441;
  # nosb is a script bash runs, xonly runs: neither takes a checkpoint)
  local -A cx_scr=(
    [noexec]="126): omabox: check: cannot run scenario $ck/noexec: it is not executable (chmod +x)"
    [adir]="126): omabox: check: cannot run scenario $ck/adir: it is a directory"
    [binary]="126): omabox: check: cannot run scenario $ck/binary: it is a binary this system cannot run (Exec format error)"
    [nowhere]="127): omabox: check: cannot run scenario $ck/nowhere: no such file"
    [crlf]="126): omabox: check: cannot run scenario $ck/crlf: its #! interpreter '/bin/sh^M' is not there (CRLF line ends?)"
    [badint]="126): omabox: check: cannot run scenario $ck/badint: its #! interpreter '/nonexistent/interp' is not there"
    [noload]="127): omabox: check: cannot run scenario $ck/noload: a file it needs to start (its ELF loader) is not there"
    [eacces]="126): omabox: check: cannot run scenario $ck/eacces: its #! interpreter '/etc/passwd' cannot run: Permission denied"
    [nonl]="126): omabox: check: cannot run scenario $ck/nonl: its #! interpreter '/nonexistent/interp' is not there"
    [midcr]="126): omabox: check: cannot run scenario $ck/midcr: its #! interpreter '/bin/s^Mh' is not there (CRLF line ends?)")
  cx_q() { printf '%s' "$1" | sed -E 's/[][\\.*^$()+?{}|]/\\&/g'; }
  for i in noexec adir binary nosb nowhere crlf badint xonly noload eacces nonl midcr; do
    case $i in
      nosb) cx_want=(rc=1 out="same     whole"$'\n'"missing  part: in the baseline, not taken this run"$'\n'"check: 1 of 2 same, 1 missing; shots in $ck/o/run1") ;;
      xonly) cx_want=(rc=3 out= 'err~^omabox: check: the scenario took no checkpoint \(omabox check point ID in it\)$') ;;
      *) cx_want=(rc=3 out= "err~^omabox: check: the scenario failed in run 1 \\(exit $(cx_q "${cx_scr[$i]}") \\($(cx_q "$ck")/o/run1\\.log\\)\$") ;;
    esac
    cx_case "check run: a scenario that is $i" check run --base "$ck/base" -o "$ck/o" -- "$ck/$i"
  done
  # Signals during its box's up and during its scenario: the exit, and no check box left.
  printf '#!/bin/sh\n: > "%s/scen-started"; sleep 6; omabox check point whole\n' "$ck" > "$ck/slow"; chmod +x "$ck/slow"
  # (an up a signal left running finishes first, then what it left is listed, then taken down)
  cx_ckwait() { local k; for k in $(seq 60); do pgrep -f "bin/omabox up $P-rpc" >/dev/null || break; sleep 0.5; done; }
  cx_ckdown() { cx_ckwait; local b; for b in $(cd "$XDG_RUNTIME_DIR/omabox" && command find . -maxdepth 1 -name "$P-rpc*" -printf '%P\n'); do ob down "$b" >/dev/null 2>&1; done; }
  cx_cks() { cx_ckdown; cx_ckc; rm -f "$ck/scen-started"; }
  cx_ckleft() { cx_ckls; cx_ckwait; echo "== boxes"; (cd "$XDG_RUNTIME_DIR/omabox" && command find . -maxdepth 1 -name "$P-rpc*" -printf '%P\n'); }
  cx_prep=cx_cks cx_also=cx_ckleft
  cx_sed="$cx_sed"'; s/ line ([0-9]+): +[0-9]+ (Hangup|Terminated|Interrupt) / line N: PID \2 /'
  # (during the up: the up's step ends, the box goes, the signal's code; no box left)
  local -A cx_code=([TERM]=143 [HUP]=129 [group-INT]=130 [INT]=130)
  for i in TERM HUP; do
    cx_wrap=(env RP_LINGER=8 "$r_sig" "$i" "$ck/o/run1.up.log")
    cx_want=("rc=${cx_code[$i]}" out= "err~^omabox: check: run 1 of 1: a clean box \\($P-rpc-1\\), then: $ck/slow\$" 'state~^== boxes$' "state!~^$P-rpc")
    cx_case "check run and $i during its box's up" check run --base "$ck/base" -o "$ck/o" -- "$ck/slow"
  done
  # (during its scenario: a TERM or HUP to omabox alone waits for the scenario, here 6 s (10 at
  # most, then a TERM to it), so its point is taken, then the box goes, finding 453; an INT to
  # omabox alone stops it once the scenario is over, 130, nothing compared, finding 454; a group INT
  # ends the scenario and omabox, 130. The point's contents are left out: base's are the same lines.)
  cx_ckleft_np() { (cd "$ck" && command find . -printf '%p %y\n' | LC_ALL=C sort); cx_ckwait; echo "== boxes"; (cd "$XDG_RUNTIME_DIR/omabox" && command find . -maxdepth 1 -name "$P-rpc*" -printf '%P\n'); }
  for i in TERM HUP group-INT INT; do
    cx_wrap=(env RP_LINGER=8 "$r_sig" "$i" "$ck/scen-started")
    cx_want=("rc=${cx_code[$i]}" out= "err~^omabox: check: run 1 of 1: box up in N s\$" 'state~^== boxes$' "state!~^$P-rpc")
    case $i in TERM|HUP) cx_also=cx_ckleft_np; cx_want+=('state~^\./o/run1/whole\.(png|point) f$') ;; esac
    cx_case "check run and $i during its scenario" check run --base "$ck/base" -o "$ck/o" -- "$ck/slow"
    cx_also=cx_ckleft
  done
  # (a scenario a Ctrl-C kills: 130 at once, its boxes taken down)
  cx_wrap=(env RP_LINGER=8 "$r_sig" group-INT "$ck/o/run1.log")
  cx_want=(rc=130 out= "err~^omabox: check: run 1 of 1: a clean box \\($P-rpc-1\\), then: sleep 6\$" 'state~^== boxes$' "state!~^$P-rpc")
  cx_case "check run and group-INT killing a bare sleep scenario" check run --base "$ck/base" -o "$ck/o" -- sleep 6
  cx_wrap=() cx_also=cx_ckls; cx_ckdown
  # --approve into a base that cannot be made: mkdir's failure ends it, 1, its boxes gone.
  mkdir -p "$ck/ro"; chmod 555 "$ck/ro"
  cx_prep=cx_ckr
  cx_want=(rc=2 out= "err~^omabox: check: cannot make $ck/ro/base: Permission denied\$")
  cx_case "check run --approve: a base that cannot be made, 1 (2 in Rust, check's own failure)" check run --approve --runs 2 --base "$ck/ro/base" -o "$ck/o" -- "$ck/scen"
  chmod 755 "$ck/ro"
  check_eq "...every check box went down" "" "$(cd "$XDG_RUNTIME_DIR/omabox" && command find . -maxdepth 1 -name "$P-rpc*" -printf '%P\n')"
  cx_prep="" cx_env=() cx_also="" cx_sed=""
  # record on the box: wf-recorder and ffmpeg for real (the numbers of a take's length, its
  # times and sizes left out: they are the take's). Both are optional: skipped without them (#405).
  local rv=$TMP/rp-rec rvN
  if ! command -v wf-recorder >/dev/null || ! command -v ffmpeg >/dev/null; then
    skip "record on the box (8 cases)" "no wf-recorder or ffmpeg here"
  else
    rm -rf "$rv"; mkdir -p "$rv"
    # (its path as the cases' sed leaves it, every number an N)
    rvN=$(sed -E 's/[0-9]+(\.[0-9]+)?/N/g' <<<"$rv")
    cx_recx() { ob record -b "$B" stop >/dev/null 2>&1 || true; rm -rf "$rv"; mkdir -p "$rv"; }
    cx_recs() { cx_recx; ob record -b "$B" start -o "$rv/v.mp4" >/dev/null 2>&1; sleep 0.6; }
    cx_recm() { cx_recs; ob record -b "$B" mark 'scene one' >/dev/null 2>&1; }
    cx_recls() { (cd "$rv" && command find . -printf '%p %y\n' | LC_ALL=C sort; for f in *.tsv *.vtt; do [ -f "$f" ] && { echo "== $f"; sed -E 's/[0-9]+/N/g' "$f"; }; done 2>/dev/null); }
    cx_also=cx_recls
    cx_sed='s/[0-9]+(\.[0-9]+)?/N/g'
    cx_prep=cx_recx
    cx_want=(rc=0 "out=$rvN/v.mpN"$'\n'"$rvN/v.sheet.png" 'err~^omabox: record: a NxN contact sheet of N frames ' 'state~^\./v\.mp4 f$' 'state~^\./v\.sheet\.png f$')
    cx_case "record --for 1s --sheet --frames 2" record -b "$B" --for 1s --sheet --frames 2 -o "$rv/v.mp4"
    cx_want=(rc=0 "out=$rvN/v.mpN" 'err~^omabox: record: NxN, Ns at N fps$' 'state~^\./v\.mp4 f$')
    cx_case "record -- ACTION --hold 200ms" record -b "$B" --hold 200ms -o "$rv/v.mp4" -- keys a
    cx_want=(rc=0 "out~^box 't[N0-9]+-rpN': not recording\$" err=)
    cx_case "record status: not recording" record -b "$B" status
    cx_prep=cx_recs
    cx_want=(rc=0 "out~^\\{\"recording\":true,\"stopped\":false,\"monitors\":\\[\"[A-Z]+-N\"\\],\"fps\":N,\"file\":\"$rvN/v\\.mpN\",\"audio\":false,\"started\":N\\}\$" err=)
    cx_case "record status --json: recording" record -b "$B" status --json
    cx_want=(rc=0 'out=Ns scene two' err=)
    cx_case "record mark" record -b "$B" mark 'scene two'
    cx_want=(rc=0 'out=held Ns to Ns' err=)
    cx_case "record hold 300ms" record -b "$B" hold 300ms
    cx_prep=cx_recm
    cx_want=(rc=0 "out=$rvN/v.mpN" 'err~^omabox: record: N still stretch(es)? cut to Ns' "err~^omabox: record: N mark in $rvN/v\\.marks\\.tsv \\(ms in the video\\), and $rvN/v\\.vtt \\(captions\\)\$" 'state~^N	N\.N	scene one$' 'state~^WEBVTT$')
    cx_case "record stop --captions --cut-idle" record -b "$B" stop --captions --cut-idle
    # --no-pointer: the hold kept past start, given back at stop.
    cx_recptr() { cx_recls; echo "== pointer"; sed -E 's/[0-9]+/N/g' "$XDG_RUNTIME_DIR/omabox/$B/pointer" 2>/dev/null; }
    cx_also=cx_recptr cx_prep=cx_recx
    cx_want=(rc=0 out= "err~^omabox: record: recording [A-Z]+-N of box 't[N0-9]+-rpN' to $rvN/v\\.mpN \\(omabox record stop\\)\$" 'state~^hold record N$')
    cx_case "record start --no-pointer: the hold kept" record -b "$B" start --no-pointer -o "$rv/v.mp4"
    cx_recnp() { cx_recx; ob record -b "$B" start --no-pointer -o "$rv/v.mp4" >/dev/null 2>&1; sleep 0.6; }
    cx_prep=cx_recnp
    cx_want=(rc=0 "out=$rvN/v.mpN" 'err~^omabox: record: NxN, Ns at N fps$' 'state!~^hold record')
    cx_case "record stop: the --no-pointer hold given back" record -b "$B" stop
    cx_recx
  fi
  cx_prep="" cx_sed="" cx_also=""
  cx_prep="" cx_sed="" cx_also=""
  cx_lay
  cx_rt="" cx_snap=1
  ob down "$B" >/dev/null 2>&1
}

# omabox which PID (#172): a box's shell has the desktop's command line on the host; OMABOX_BOX in
# every process of its session and `which` tell them apart.
t_which() {
  local B=$P-which out rc sp="" p ns
  up_ok "$B" --net isolated || { no "up" "$UP_OUT"; return; }
  ns=$(jq -r '.pidns // empty' "$XDG_RUNTIME_DIR/omabox/$B/box.json")
  for p in $(pgrep -x quickshell); do [ "$(readlink "/proc/$p/ns/pid" 2>/dev/null)" != "$ns" ] || sp=$p; done
  [ -n "$sp" ] || { no "the box's shell on the host" "no quickshell in $ns"; ob down "$B" >/dev/null 2>&1; return; }
  check "the box shell's environment names its box" grep -qaFx "OMABOX_BOX=$B" <(tr '\0' '\n' < "/proc/$sp/environ")
  out=$(ob which "$sp" 2>&1); rc=$?
  check_eq "which: the box shell's host pid gives the box, exit 0" "$B 0" "$out $rc"
  check_eq "...what run starts in it carries the name too" "$B" "$(ob run -b "$B" -- sh -c 'echo "$OMABOX_BOX"')"
  # A pid namespace of its own inside the box (Chromium's sandbox, a nested box): its ancestor's.
  ob run -b "$B" -d -q -- unshare -Urpf --mount-proc --propagation slave sleep 61.72 >/dev/null 2>&1
  check "...a process in a pid namespace of its own in the box" until_ok 5 pgrep -fx 'sleep 61.72'
  p=$(pgrep -fx 'sleep 61.72' | head -1)
  check_eq "...is in the box, by its ancestors" "$B" "$(ob which "${p:-0}" 2>/dev/null)"
  check_fails "...not by its own pid namespace" test "$(readlink "/proc/${p:-0}/ns/pid" 2>/dev/null)" = "$ns"
  check_eq "...the host shell is not in it" "not in a box" "$(ob which $$ 2>/dev/null)"
  ob down "$B" >/dev/null 2>&1
}

# #271: the brief of a box that is up: its name, size, windows (each by a selector that finds it
# alone), the box HOME's host path, and the rules.
t_brief() {
  local B=$P-brief out
  up_ok "$B" --net isolated || { no "up" "$UP_OUT"; return; }
  out=$(ob brief -b "$B" 2>&1)
  check_match "brief: no windows yet" "none yet \\(omabox -b $B run -d --wait -- APP" "$out"
  ob run -b "$B" -d --wait -- foot --app-id t271 -T brief-one sleep 600 >/dev/null 2>&1
  out=$(ob brief -b "$B" 2>&1)
  check_match "...names the box, its size and scale" "^You drive omabox box '$B' \\(1920x1080, scale 1\\)" "$out"
  check_match "...its window, by the word that finds it" $'\n  t271  "brief-one"  [0-9]+x[0-9]+ at [0-9]+,[0-9]+  on-screen, active\n' "$out"
  check_match "...-b NAME in its rules" "omabox -b $B CMD" "$out"
  check_match "...the box HOME's host path" "/home/sbx is $XDG_RUNTIME_DIR/omabox/$B/home on the host" "$out"
  check_match "...the box is the parent's" "leave it up, and never down another box you did not start" "$out"
  check "...20 lines at most" test "$(wc -l <<<"$out")" -le 20
  ob run -b "$B" -d --wait -- foot --app-id t271 -T brief-two sleep 600 >/dev/null 2>&1
  out=$(ob brief -b "$B" 2>&1)
  check_eq "...two of one class: each by its address" 2 "$(grep -cE '^  0x[0-9a-f]+  "brief-(one|two)"' <<<"$out")"
  ob down "$B" >/dev/null 2>&1
}

# `omarchy restart shell` (Omarchy's own, finding 131) in a box: its launcher runs the bar under
# systemd-cat, which a box lacked, and the bar was gone. It and `omabox restart-shell`, in turns, leave
# one shell each time.
t_omarchy_restart() {
  local B=$P-or
  up_ok "$B" --net isolated || { no "up" "$UP_OUT"; return; }
  # shellcheck disable=SC2329 # called through check
  one_shell() { [ "$(ob run -b "$B" -- pgrep -cx quickshell)" = 1 ] && ob run -b "$B" -- omarchy-shell shell ping >/dev/null 2>&1; }
  check_eq "up runs the shell under omarchy-launch-shell, as Omarchy does (#151)" "1 1" \
    "$(ob run -b "$B" -- pgrep -cf '[o]marchy-launch-shell') $(ob run -b "$B" -- pgrep -cx quickshell)"
  # Finding 401: PipeWire's module-rt set the shell's RLIMIT_RTTIME to 0 (the Realtime portal's answer in
  # a box, with no RealtimeKit), and the kernel SIGKILLed it now and then under load. Once the shell's
  # PipeWire service has tried to connect (module-rt has loaded), the limit holds unlimited.
  # shellcheck disable=SC2329 # called through check
  rttime_unlimited() { [ "$(ob run -b "$B" -- sh -c 'awk "/^Max realtime timeout/ {print \$4 \$5}" "/proc/$(pgrep -xo quickshell)/limits"')" = unlimitedunlimited ]; }
  check "the shell's PipeWire service started" until_ok 10 grep -aq 'service\.pipewire' "$(ob path "$B")/home/shell.log"
  check "...and left the shell's RLIMIT_RTTIME unlimited (finding 401)" holds 2 rttime_unlimited
  check "omarchy-restart-shell succeeds in a box" timeout 30 "$CLI" run -b "$B" -- omarchy-restart-shell
  check "...one shell, answering" until_ok 5 one_shell
  check_eq "...its pid where omabox restart-shell looks" "$(ob run -b "$B" -- pgrep -x quickshell)" "$(ob run -b "$B" -- sh -c 'cat "$XDG_RUNTIME_DIR/omabox-shell.pid"')"
  check "omabox restart-shell after it" timeout 30 "$CLI" restart-shell -b "$B"
  check "...one shell, answering" until_ok 5 one_shell
  # Under one launcher, its own (#151): Omarchy's stopped with the shell it ran, none left to start another.
  check_eq "...under one omarchy-launch-shell" 1 "$(ob run -b "$B" -- pgrep -cf '[o]marchy-launch-shell')"
  check "omarchy-restart-shell again" timeout 30 "$CLI" run -b "$B" -- omarchy-restart-shell
  check "...one shell" until_ok 5 one_shell
  # #141: under the guard (an agent's shell, the box standing in for the host), `omarchy restart shell`
  # stopped the shell over Quickshell's IPC, then could not start it again (its hyprctl is guarded).
  local g=("$CLI" run -b "$B" -- "${GUARDED[@]}") qpid; qpid=$(ob run -b "$B" -- pgrep -x quickshell)
  check_fails "guarded omarchy-restart-shell fails" timeout 30 "${g[@]}" omarchy-restart-shell
  check_eq "...the shell still running, the same one" "$qpid" "$(ob run -b "$B" -- pgrep -x quickshell)"
  check_match "guarded quickshell kill --any-display refused" "omabox guard: not running quickshell kill" \
    "$("${g[@]}" sh -c 'quickshell kill -p "$OMARCHY_PATH/shell" --any-display' 2>&1)"
  check_match "guarded qs list --all still lists it" "$qpid" "$("${g[@]}" qs list --all 2>&1)"
  ob down "$B" >/dev/null
}

# Whether the box's keyboard panel (Omarchy's KeyboardPanel, the widget's) is open and takes keys
# (#116): a closing one stays mapped through its fade-out with no keyboard interactivity, so a layer
# there is not enough: keys sent then were lost, and a keyed row of the widget's flaked under load.
panel_takes_keys() {
  [ "$(ob lua -b "$1" 'for _, l in ipairs(hl.get_layers()) do
    if l.namespace == "omarchy-keyboard-panel" and l.mapped and l.interactivity > 0 then return true end
  end return false')" = true ]
}

# The bar widget (plugin/) in a box's own bar, against a stand-in omabox (a list from a file, actions
# logged) and an xdg-open that blocks like an image viewer left open (finding 64).
t_widget() {
  local B=$P-wg
  # Omarchy's stock bar, not the user's (finding 151): the crops below look for the widget at the top
  # right, and a user's own layout may have the bar on a side, or the widget in a plugin of theirs.
  up_ok "$B" --net isolated --stock-bar --plugin "$ROOT/plugin" || { no "up" "$UP_OUT"; return; }
  local H; H=$(ob path "$B")/home
  printf '#!/bin/sh\ncase "$1" in\n  ls) echo ls >> "$HOME/polls"; n=$(cat "$HOME/hang" 2>/dev/null || echo 0); if [ "$n" -gt 0 ]; then echo $((n - 1)) > "$HOME/hang"; [ ! -e "$HOME/hang-deaf" ] || trap "" TERM; x=$(sleep 600 | cat); fi; cat "$HOME/list.json" ;;\n  shot) echo "$*" >> "$HOME/actions"; echo "$HOME/x.png" ;;\n  config) echo "$*" >> "$HOME/actions"; cat "$HOME/config.json" 2>/dev/null || echo "{}" ;;\n  up) echo "$*" >> "$HOME/actions"; echo box-9 ;;\n  clip) echo "$*" >> "$HOME/actions"; echo "omabox: handed text (text/plain;charset=utf-8, 3 bytes) from your clipboard to box ia" >&2 ;;\n  *) echo "$*" >> "$HOME/actions" ;;\nesac\n' > "$H/.local/bin/omabox"
  printf '#!/bin/sh\necho "xdg-open $*" >> "$HOME/actions"; exec sleep 300\n' > "$H/.local/bin/xdg-open"
  printf '#!/bin/sh\necho "notify-send $*" >> "$HOME/actions"\n' > "$H/.local/bin/notify-send"
  chmod +x "$H/.local/bin/omabox" "$H/.local/bin/xdg-open" "$H/.local/bin/notify-send"
  local row='{"mode":"headless","size":"1920x1080@60","created":"2026-09-24T02:00:00-03:00","plugins":[],"net":"host","state":"up","peeking":false}'
  jq -n "[$row + {name: \"a\"}, $row + {name: \"b\"}]" > "$H/list.json"; : > "$H/actions"
  # shellcheck disable=SC2329 # called through until_ok and check_fails
  panel() { panel_takes_keys "$B"; }
  # shellcheck disable=SC2329 # called through until_ok
  lines_over() { [ "$(grep -c -- "$3" "$1" 2>/dev/null)" -gt "$2" ]; }
  # A list poll that started after this call: the stub logs each `ls` before it reads the list, so
  # that poll read the list as it is now (then a moment for the widget to take it in).
  polled() { local n; n=$(grep -c . "$H/polls" 2>/dev/null); until_ok 12 lines_over "$H/polls" "${n:-0}" .; sleep 0.3; }
  # The widget's own settings, in its shell.json entry (read live; finding 169): a poll each second,
  # and 2 s for an `ls --json` to answer (finding 170's checks below).
  local sj=$H/.config/omarchy/shell.json
  local n; n=$(grep -c . "$H/polls" 2>/dev/null)
  jq '.bar.layout[] |= map(if .id == "chaves.omabox" then . + {refreshIntervalSec: 1, listTimeoutSec: 2} else . end)' "$sj" > "$TMP/wg-shell.json" &&
    cat "$TMP/wg-shell.json" > "$sj"
  check "the widget reads its own settings: two polls in 4 s (finding 169; 5 s apart by default)" \
    until_ok 4 lines_over "$H/polls" "$((${n:-0} + 1))" .
  polled
  ob run -b "$B" -- omarchy-shell chaves.omabox open
  check "the panel opens" until_ok 3 panel
  check "...and reads the settings from the CLI (finding 70)" until_ok 3 grep -qx "config --json" "$H/actions"
  ob keys -b "$B" Down Down >/dev/null
  jq "[$row + {name: \"0new\"}] + ." "$H/list.json" > "$H/l" && mv "$H/l" "$H/list.json"
  polled   # (every 2 s while open) 0new is above b now
  ob keys -b "$B" s >/dev/null
  check "the selection follows its box (shot b, not a)" until_ok 3 grep -qx "shot -b b" "$H/actions"
  # The file itself, not <(...): a process substitution is read once, so a retry of until_ok saw an
  # empty pipe and the check failed whenever the viewer started after the first poll.
  check "the viewer is started" until_ok 3 grep -qx "xdg-open /home/sbx/x.png" "$H/actions"
  ob run -b "$B" -- omarchy-shell chaves.omabox open; until_ok 3 panel
  ob keys -b "$B" Down p >/dev/null
  check "an action runs while the viewer is open" until_ok 3 grep -q "^peek -b " "$H/actions"
  # n: a new interactive box under the name the CLI picks, then brought forward (finding 73)
  ob run -b "$B" -- omarchy-shell chaves.omabox open; until_ok 3 panel
  ob keys -b "$B" n >/dev/null
  check "one n starts nothing (a stray key; finding 74)" holds 1 bash -c "! grep -qx 'up --interactive --new' '$H/actions'"
  ob keys -b "$B" n >/dev/null
  check "n n starts a new interactive box (up --interactive --new)" until_ok 3 grep -qx "up --interactive --new" "$H/actions"
  check "...and shows the box it printed" until_ok 3 grep -qx "peek -b box-9 --focus" "$H/actions"
  # bar-icon (finding 72), read again whenever the settings file changes. always (the default):
  # the panel opens with no boxes, for its settings; auto: opened with none, it stays shut, and
  # does not pop up later when a box comes
  echo '[]' > "$H/list.json"; polled
  ob run -b "$B" -- omarchy-shell chaves.omabox open
  check "bar-icon always (default): the panel opens with no boxes" until_ok 3 panel
  ob keys -b "$B" Escape >/dev/null
  local reads; reads=$(grep -c "^config --json$" "$H/actions")
  # (an omabox from before 0.9 gives kebab-case keys: the widget takes them too, #273)
  echo '{"bar-icon":"auto"}' > "$H/config.json"; echo "bar-icon=auto" > "$H/.config/omabox/config"
  until_ok 5 lines_over "$H/actions" "$reads" "^config --json$"; sleep 0.3   # read again, taken in
  ob run -b "$B" -- omarchy-shell chaves.omabox open
  check "bar-icon auto: opened with no boxes, it stays shut" holds 1 bash -c "! '$CLI' hyprctl -b '$B' -j layers | grep -q omarchy-keyboard-panel"
  jq -n "[$row + {name: \"a\"}]" > "$H/list.json"; polled
  check "...and does not pop up when one comes" holds 1 bash -c "! '$CLI' hyprctl -b '$B' -j layers | grep -q omarchy-keyboard-panel"
  # clip (issue #23, finding 119): v pastes in, c copies out, on an interactive box's row only
  local irow='{"mode":"interactive","size":"window","created":"2026-09-24T02:00:00-03:00","plugins":[],"net":"connected","state":"up","peeking":false}'
  jq -n "[$irow + {name: \"ia\"}]" > "$H/list.json"; polled
  ob run -b "$B" -- omarchy-shell chaves.omabox open; until_ok 3 panel
  ob keys -b "$B" Down v >/dev/null
  check "v on an interactive box: clip -b NAME" until_ok 3 grep -qx "clip -b ia" "$H/actions"
  check "...what it handed over is notified (type and size)" until_ok 3 grep -q "^notify-send -a omabox omabox clip ia handed text (text/plain" "$H/actions"
  ob run -b "$B" -- omarchy-shell chaves.omabox open; until_ok 3 panel
  ob keys -b "$B" Down c >/dev/null
  check "c: clip --from-box" until_ok 3 grep -qx "clip -b ia --from-box" "$H/actions"
  jq -n "[$row + {name: \"hb\"}]" > "$H/list.json"; polled
  ob run -b "$B" -- omarchy-shell chaves.omabox open; until_ok 3 panel
  ob keys -b "$B" Down v c >/dev/null
  check "...neither on a headless box's" holds 1 bash -c "! grep -q 'clip -b hb' '$H/actions'"
  ob keys -b "$B" Escape >/dev/null
  # keys-to-box (finding 117): f turns it on or off for the selected interactive box; the icon is lit
  # while the host's Lua names a box in $XDG_RUNTIME_DIR/omabox/.keys (renamed into place, as it does).
  local irow='{"mode":"interactive","size":"window","created":"2026-09-24T02:00:00-03:00","plugins":[],"net":"host","state":"up","peeking":false}'
  jq -n "[$irow + {name: \"i\", keys_to_box: false}, $irow + {name: \"j\", keys_to_box: true}]" > "$H/list.json"; polled
  ob run -b "$B" -- omarchy-shell chaves.omabox open; until_ok 3 panel
  ob keys -b "$B" Down f >/dev/null
  check "f turns keys-to-box on for an interactive box" until_ok 3 grep -qx "keys-to-box -b i on" "$H/actions"
  ob keys -b "$B" Down f >/dev/null
  check "...and off for one that has it" until_ok 3 grep -qx "keys-to-box -b j off" "$H/actions"
  ob keys -b "$B" Escape >/dev/null
  # The bar's right side (the widget's section) as it is now, the same as FILE or not.
  # shellcheck disable=SC2329 # called through until_ok
  bar_is() { ob shot -b "$B" -g "1420,0 500x30" -o "$TMP/keys-now.png" >/dev/null 2>&1 && if [ "$1" = same ]; then cmp -s "$2" "$TMP/keys-now.png"; else ! cmp -s "$2" "$TMP/keys-now.png"; fi; }
  local run; run=$(ob path "$B")/run
  # No omabox dir when the shell started: the file is not watched then, and each poll reads it.
  mkdir -p "$run/omabox"
  ob wait -b "$B" still >/dev/null 2>&1
  ob shot -b "$B" -g "1420,0 500x30" -o "$TMP/keys-off.png" >/dev/null 2>&1
  echo i > "$run/omabox/.keys.tmp" && mv "$run/omabox/.keys.tmp" "$run/omabox/.keys"
  check "the icon is lit while keys go to a box (read at a poll)" until_ok 8 bar_is other "$TMP/keys-off.png"
  cp "$TMP/keys-now.png" "$TMP/keys-on.png"
  echo > "$run/omabox/.keys.tmp" && mv "$run/omabox/.keys.tmp" "$run/omabox/.keys"
  check "...and not once they are the desktop's again (watched)" until_ok 1.5 bar_is same "$TMP/keys-off.png"
  echo i > "$run/omabox/.keys.tmp" && mv "$run/omabox/.keys.tmp" "$run/omabox/.keys"
  check "...lit again at once (the file watched)" until_ok 1.5 bar_is same "$TMP/keys-on.png"
  echo gone > "$run/omabox/.keys.tmp" && mv "$run/omabox/.keys.tmp" "$run/omabox/.keys"
  check "...not for a box that is not up (a file a Hyprland left)" until_ok 1.5 bar_is same "$TMP/keys-off.png"
  # A widget older than the CLI (finding 133: the shell does not reload it after an upgrade) says to
  # restart the shell; one of the CLI's version, or a CLI that names none, says nothing.
  echo '[]' > "$H/list.json"; polled
  reads=$(grep -c "^config --json$" "$H/actions")
  echo '{}' > "$H/config.json"; : > "$H/.config/omabox/config"   # bar-icon always again: it opens with none
  until_ok 5 lines_over "$H/actions" "$reads" "^config --json$"; sleep 0.3
  local pv; pv=$(sed -n 's/.*pluginVersion: "\([^"]*\)".*/\1/p' "$ROOT/plugin/Panel.qml")
  # shellcheck disable=SC2329 # called through check
  panel_shot() {
    echo "$1" > "$H/config.json"
    local n; n=$(grep -c "^config --json$" "$H/actions")
    ob run -b "$B" -- omarchy-shell chaves.omabox open; until_ok 3 panel
    until_ok 3 lines_over "$H/actions" "$n" "^config --json$"; sleep 0.3   # read when opened, taken in
    ob pointer -b "$B" -- move 10 1000 >/dev/null; ob wait -b "$B" still >/dev/null 2>&1
    ob shot -b "$B" -g "1220,0 700x400" -o "$2" >/dev/null 2>&1
    ob keys -b "$B" Escape >/dev/null; until_ok 3 bash -c "! '$CLI' hyprctl -b '$B' -j layers | grep -q omarchy-keyboard-panel"
  }
  panel_shot '{}' "$TMP/wg-nover.png"
  panel_shot "{\"version\":\"$pv\"}" "$TMP/wg-same.png"
  panel_shot '{"version":"9.9.9"}' "$TMP/wg-newer.png"
  check "a widget of the CLI's version says nothing more than one told no version" cmp -s "$TMP/wg-nover.png" "$TMP/wg-same.png"
  check_fails "...an older one says to restart the shell (finding 133)" cmp -s "$TMP/wg-same.png" "$TMP/wg-newer.png"
  # Finding 170: an `ls --json` that never answers is stopped after the widget's limit (2 s, set at
  # the top) with all it started, and counted as one failed poll; the next poll runs. The stub hangs
  # as many polls as $H/hang says, in a $(... | ...) the way `head` on a FIFO did (#95).
  echo 3 > "$H/hang"
  check "an ls --json that hangs is stopped: three in a row are notified so (finding 170)" \
    until_ok 20 grep -qx "notify-send -a omabox omabox: cannot list boxes omabox ls --json did not answer in 2 s" "$H/actions"
  check "...with what it started (no sleep of its left)" until_ok 5 bash -c "! '$CLI' run -b '$B' -- pgrep -fx 'sleep 600'"
  until_ok 5 grep -qx 0 "$H/hang"; polled   # one that answered: the failures count from 0 again
  # One deaf to SIGTERM, its children too, is killed 2 s on; each counts once: two in a row (not
  # four, with a "cannot run" each) notify nothing, and the list the poll after reads is shown.
  jq -n "[$row + {name: \"after\"}]" > "$H/list.json"
  : > "$H/hang-deaf"; echo 2 > "$H/hang"
  until_ok 15 grep -qx 0 "$H/hang"   # the second one started (the first took 2 + 2 s)
  n=$(grep -c . "$H/polls")
  check "...one deaf to SIGTERM is killed, and the poll after it runs" until_ok 12 lines_over "$H/polls" "$n" .
  sleep 0.3; rm "$H/hang-deaf"
  check "...with what it started" until_ok 5 bash -c "! '$CLI' run -b '$B' -- pgrep -fx 'sleep 600'"
  check_eq "...two in a row are two failures, not a notification" 1 "$(grep -c "cannot list boxes" "$H/actions")"
  ob run -b "$B" -- omarchy-shell chaves.omabox open; until_ok 3 panel
  ob keys -b "$B" Down s >/dev/null
  check "...and the list after them is read (shot -b after)" until_ok 3 grep -qx "shot -b after" "$H/actions"
  # (Not with omabox installed on the host: the box sees its /usr/bin/omabox, so there is always one.)
  if [ ! -e /usr/bin/omabox ]; then
    # In a box (OMABOX_BOX) a list command that cannot run is no error (#207): the widget of a box
    # that mounts every plugin of the desk draws nothing and notifies nothing; one that runs again
    # brings it back. (bar-icon is always here: with a command it would open with no boxes.)
    mv "$H/.local/bin/omabox" "$H/.local/bin/omabox.off"
    check "in a box, a list command that cannot run is not notified (#207)" \
      holds 6 bash -c "! grep -q 'cannot list boxes.*cannot run' '$H/actions'"
    ob run -b "$B" -- omarchy-shell chaves.omabox open
    check "...and the widget draws nothing: opened, it stays shut" holds 1 bash -c "! '$CLI' hyprctl -b '$B' -j layers | grep -q omarchy-keyboard-panel"
    mv "$H/.local/bin/omabox.off" "$H/.local/bin/omabox"; polled
    ob run -b "$B" -- omarchy-shell chaves.omabox open
    check "...until one runs again" until_ok 3 panel
    ob keys -b "$B" Escape >/dev/null
  else
    skip "in a box, a list command that cannot run is not notified (#207)" "the box has the host's /usr/bin/omabox"
  fi
  ob down "$B" >/dev/null
}

# INK_RUNS PGM: the ink in a crop (pixels far from its top-left corner's grey), as runs of columns
# with ink: one "x y w h" line per run, its bounding box. The widget's mark is the first, its count the
# rest (#219).
INK_RUNS='
import sys
parts = open(sys.argv[1], "rb").read().split(None, 4)
w, h, px = int(parts[1]), int(parts[2]), parts[4]
ink = [[abs(px[y * w + x] - px[0]) > 60 for x in range(w)] for y in range(h)]
x = 0
while x < w:
    if not any(ink[y][x] for y in range(h)): x += 1; continue
    x0 = x
    while x < w and any(ink[y][x] for y in range(h)): x += 1
    ys = [y for y in range(h) if any(ink[y][x0:x])]
    print(x0, ys[0], x - x0, ys[-1] - ys[0] + 1)
'

# The bar mark beside the box count (#219): with 1, 2, 3 and 12 boxes listed, the mark is drawn the same
# size in the same place and the count beside it. A shell that fits every bar icon to one size
# (Omarchy's BarIconContent: omacom/omarchy#15065, after 4.0.4) scaled the count with the mark, and
# the mark shrank to about 7x8 px. OMABOX_TEST_OMARCHY=DIR runs the box on that tree (`up --omarchy`).
t_widget_mark() {
  local B=$P-wm o=${OMABOX_TEST_OMARCHY:-} om=() fitted=no
  [ -z "$o" ] || om=(--omarchy "$o")
  [ ! -f "${o:-/usr/share/omarchy}/shell/Ui/BarIconContent.qml" ] || fitted=yes
  note "Omarchy at ${o:-/usr/share/omarchy}, fitted bar icons: $fitted"
  up_ok "$B" --net isolated --stock-bar --plugin "$ROOT/plugin" "${om[@]}" || { no "up" "$UP_OUT"; return; }
  local H; H=$(ob path "$B")/home
  printf '#!/bin/sh\ncase "$1" in\n  ls) echo ls >> "$HOME/polls"; cat "$HOME/list.json" ;;\n  config) echo "{}" ;;\nesac\n' > "$H/.local/bin/omabox"
  chmod +x "$H/.local/bin/omabox"
  # shellcheck disable=SC2329 # called through until_ok
  lines_over() { [ "$(grep -c . "$1" 2>/dev/null)" -gt "$2" ]; }
  # shellcheck disable=SC2329 # called through until_ok
  slot_is() { ob run -b "$B" -- omarchy-shell shell debugBarGeometry 2>/dev/null |
    jq -e --argjson w "$1" '.[] | select(.id == "chaves.omabox") | .visible and .width == $w' >/dev/null; }
  # runs N: N boxes listed, a poll that read them, then the ink runs in the widget's slot.
  runs() {
    local n=$1 p g
    jq -n --argjson n "$n" '[range($n)] | map({name: "b\(.)", mode: "headless", size: "1920x1080@60",
      created: "2026-09-24T02:00:00-03:00", plugins: [], net: "host", state: "up", peeking: false})' > "$H/list.json"
    p=$(grep -c . "$H/polls" 2>/dev/null) || p=0
    until_ok 15 lines_over "$H/polls" "$p" || return 1
    until_ok 5 slot_is "$((n > 1 ? 54 : 27))" || return 1
    ob wait -b "$B" still >/dev/null 2>&1
    g=$(ob run -b "$B" -- omarchy-shell shell debugBarGeometry | jq -r '.[] | select(.id == "chaves.omabox") | "\(.x),\(.y) \(.width)x\(.height)"') || return 1
    ob shot -b "$B" -g "$g" -o "$TMP/wm-$n.png" >/dev/null 2>&1 && magick "$TMP/wm-$n.png" -colorspace gray "$TMP/wm-$n.pgm" || return 1
    python3 -c "$INK_RUNS" "$TMP/wm-$n.pgm"
  }
  local one n out first count last w
  out=$(runs 1) || { no "the widget with one box" "not shown, or not shot"; ob down "$B" >/dev/null; return; }
  one=$(head -1 <<<"$out")
  check_eq "one box: the mark alone" 1 "$(grep -c . <<<"$out")"
  read -r _ _ w _ <<<"$one"
  if [ "$fitted" = yes ]; then
    check_eq "...fitted to the shell's 12 px icon size" "12 12" "$(cut -d' ' -f3,4 <<<"$one")"
  else
    check_eq "...in the 16 px icon canvas" "16 16" "$(cut -d' ' -f3,4 <<<"$one")"
  fi
  for n in 2 3 12; do
    out=$(runs "$n") || { no "the widget with $n boxes" "not shown, or not shot"; continue; }
    first=$(head -1 <<<"$out"); count=$(sed -n '2,$p' <<<"$out"); last=$(tail -1 <<<"$out")
    check_eq "$n boxes: the mark the same size, at the same height as alone" "$(cut -d' ' -f2- <<<"$one")" "$(cut -d' ' -f2- <<<"$first")"
    check "...the count beside it, after a gap" test -n "$count" -a "$(awk '{print $1}' <<<"$count" | head -1)" -gt "$(awk '{print $1 + $3 + 1}' <<<"$first")"
    check "...$n's digits ($(grep -c . <<<"$count") ink runs, within the slot)" test "$(grep -c . <<<"$count")" -eq "${#n}" -a "$(awk '{print $1 + $3}' <<<"$last")" -lt 54
    if [ "$fitted" = yes ]; then
      # The shell centres the icon in the slot: the mark is there, the count to its right.
      check_eq "...the mark centred in the slot, as the shell puts it" "$(((54 - w) / 2))" "$(cut -d' ' -f1 <<<"$first")"
    else
      # Mark and count centred together, as before #219 (within a pixel: the count's ink is narrower
      # than its advance).
      local l r; l=$(cut -d' ' -f1 <<<"$first"); r=$((54 - $(awk '{print $1 + $3}' <<<"$last")))
      check "...mark and count centred together in the slot (left $l, right $r)" test $((l - r)) -ge -2 -a $((l - r)) -le 2
    fi
  done
  ob down "$B" >/dev/null
}

# The widget's box list with 20 made-up boxes (#117 the list held still under the pointer, #121 only
# the rows scroll, #120 the same action slots on every row and a confirm that a double-click does not
# give), read through the panel's inspect IPC: its rows, where each is on screen, their action slots.
t_widget_list() {
  local B=$P-wl
  up_ok "$B" --net isolated --stock-bar --plugin "$ROOT/plugin" || { no "up" "$UP_OUT"; return; }
  local H; H=$(ob path "$B")/home
  printf '#!/bin/sh\ncase "$1" in\n  ls) echo ls >> "$HOME/polls"; cat "$HOME/list.json" ;;\n  config) if [ "$2" = --json ]; then cat "$HOME/config.json" 2>/dev/null || echo "{}"; else echo "$*" >> "$HOME/actions"; fi ;;\n  *) echo "$*" >> "$HOME/actions" ;;\nesac\n' > "$H/.local/bin/omabox"
  chmod +x "$H/.local/bin/omabox"
  local row='{"mode":"headless","size":"1920x1080@60","created":"2026-09-24T02:00:00-03:00","plugins":[],"net":"host","state":"up","peeking":false}'
  local irow='{"mode":"interactive","size":"window","created":"2026-09-24T02:00:00-03:00","plugins":[],"net":"host","state":"up","peeking":false}'
  jq -n "[range(1; 21) as \$i | (if \$i % 3 == 0 then $irow else $row end) + {name: (\"box-\" + (\$i | tostring | if length < 2 then \"0\" + . else . end))}]" > "$H/list.json"
  : > "$H/actions"
  local sj=$H/.config/omarchy/shell.json
  jq '.bar.layout[] |= map(if .id == "chaves.omabox" then . + {refreshIntervalSec: 1} else . end)' "$sj" > "$TMP/wl-shell.json" &&
    cat "$TMP/wl-shell.json" > "$sj"
  # shellcheck disable=SC2329 # called through until_ok, holds and check
  insp() { ob run -b "$B" -- omarchy-shell chaves.omabox.panel inspect; }
  # shellcheck disable=SC2329
  q() { insp | jq -r "$1"; }
  # shellcheck disable=SC2329
  wl_polled() { local n; n=$(grep -c . "$H/polls" 2>/dev/null); until_ok 12 bash -c "[ \$(grep -c . '$H/polls') -gt $((${n:-0} + 1)) ]"; sleep 0.3; }
  # shellcheck disable=SC2329
  open_panel() { ob run -b "$B" -- omarchy-shell chaves.omabox open; until_ok 3 panel_takes_keys "$B"; }
  # shellcheck disable=SC2329
  no_down() { ! grep -q "^down " "$H/actions"; }
  # shellcheck disable=SC2329
  slot() { q ".rows[] | select(.name == \"$1\") | .slots.$2 | \"\(.x) \(.y)\""; }
  wl_polled
  ob pointer -b "$B" -- move 10 1000 >/dev/null
  open_panel
  check_eq "20 rows" 20 "$(q '.rows | length')"
  # #121: only the rows scroll; the New button and the hints stay on screen.
  check "the list scrolls (taller than the room it has; #121)" test "$(q '.list.contentHeight > .list.height')" = true
  check "...the New button and the hints stay on screen" test "$(q '.hintsBottom <= .screen and .newButton > 0')" = true
  check_eq "...the last row is out of view" false "$(q '.rows[-1].visible')"
  local x y; read -r x y < <(q '.rows[4] | "\(.x + 100) \(.y + 10)"')
  ob scroll -b "$B" "$x" "$y" 300 --source wheel >/dev/null
  check "the wheel over the list brings the last row into view" until_ok 3 bash -c "[ \"\$('$CLI' run -b '$B' -- omarchy-shell chaves.omabox.panel inspect | jq -r '.rows[-1].visible')\" = true ]"
  # Finding 237: a list scrolled with the wheel stays there once the pointer leaves the card; every poll
  # scrolled back to the selected row. Here the first row, selected by the pointer on it, then scrolled
  # out of view under the pointer.
  ob scroll -b "$B" "$x" "$y" -300 --source wheel >/dev/null
  until_ok 3 bash -c "[ \"\$('$CLI' run -b '$B' -- omarchy-shell chaves.omabox.panel inspect | jq -r '.list.contentY | round')\" = 0 ]"
  read -r x y < <(q '.rows[0] | "\(.x + 100 | round) \(.y + 10 | round)"')
  ob pointer -b "$B" -- move "$x" "$y" >/dev/null
  ob scroll -b "$B" "$x" "$y" 300 --source wheel >/dev/null
  until_ok 3 bash -c "[ \"\$('$CLI' run -b '$B' -- omarchy-shell chaves.omabox.panel inspect | jq -r '.list.contentY | round')\" != 0 ]"
  # (Until the wheel's scroll has ended: two reads 0.3 s apart the same.)
  # shellcheck disable=SC2329 # called through until_ok
  scroll_ended() { local a; a=$(q .list.contentY); sleep 0.3; [ "$a" = "$(q .list.contentY)" ]; }
  until_ok 5 scroll_ended >/dev/null
  local cy; cy=$(q '"\(.list.contentY | round) \(.selected as $s | .rows[] | select(.name == $s) | .visible)"')
  ob pointer -b "$B" -- move 10 1000 >/dev/null
  wl_polled; wl_polled
  check_eq "...scrolled away from the selected row, it stays there once the pointer leaves the card (finding 237)" "$cy" \
    "$(q '"\(.list.contentY | round) \(.selected as $s | .rows[] | select(.name == $s) | .visible)"')"
  check_match "...(the selected row was out of view)" " false$" "$cy"
  # #120: the same six slots on every row, in the same place; empty where they do not apply.
  check_eq "a headless and an interactive row have their slots at the same x (#120)" \
    "$(q '.rows[0].slots | [.[] | .x] | @text')" "$(q '.rows[2].slots | [.[] | .x] | @text')"
  check_eq "...a headless row's keys and clipboard slots are empty" "false false false" "$(q '.rows[0].slots | "\(.keys.applies) \(.clipIn.applies) \(.clipOut.applies)"')"
  : > "$H/actions"
  # shellcheck disable=SC2046 # X Y
  ob click -b "$B" $(slot box-20 clipIn) >/dev/null
  check "...a click in an empty slot runs nothing (not the row's peek)" holds 1 bash -c "[ ! -s '$H/actions' ]"
  # shellcheck disable=SC2046
  ob click -b "$B" --double $(slot box-20 down) >/dev/null
  check "a double-click on Down does not confirm it" holds 1 no_down
  # shellcheck disable=SC2046
  ob click -b "$B" $(slot box-20 down) >/dev/null
  check "...a click after it does (down box-20)" until_ok 3 grep -qx "down box-20" "$H/actions"
  check_eq "...once" 1 "$(grep -c "^down " "$H/actions")"
  ob pointer -b "$B" -- move 10 1000 >/dev/null
  open_panel; : > "$H/actions"
  ob keys -b "$B" Down d d >/dev/null
  check "d d with no gap does not confirm" holds 1 no_down
  open_panel
  ob keys -b "$B" Down d >/dev/null; sleep 0.5; ob keys -b "$B" d >/dev/null
  check "d, a pause, d does (one down)" until_ok 3 bash -c "[ \$(grep -c '^down ' '$H/actions') = 1 ]"
  open_panel; : > "$H/actions"
  ob keys -b "$B" n n >/dev/null
  check "n n with no gap starts nothing" holds 1 bash -c "! grep -q '^up ' '$H/actions'"
  # #121: ↑ from the first row selects the last, scrolled into view.
  open_panel
  ob keys -b "$B" Down >/dev/null   # the cursor on the selected row; Up to the first, then once more
  local i ups=(); i=$(q '.selected as $s | [.rows[].name] | index($s)')
  for ((; i >= 0; i--)); do ups+=(Up); done
  ob keys -b "$B" "${ups[@]}" >/dev/null
  check "Up from the first row selects the last, in view (#121)" until_ok 3 bash -c "[ \"\$('$CLI' run -b '$B' -- omarchy-shell chaves.omabox.panel inspect | jq -r '\"\(.selected) \(.rows[-1].visible)\"')\" = 'box-20 true' ]"
  # #117: with the pointer on a row, a box that sorts before it comes and one after it goes.
  open_panel
  read -r x y < <(q '.list as $l | .rows[4] | "\(.x + 100) \(.y + 10 + $l.contentY)"')   # where row 5 is unscrolled
  ob scroll -b "$B" "$x" "$y" -300 --source wheel >/dev/null
  until_ok 3 bash -c "[ \"\$('$CLI' run -b '$B' -- omarchy-shell chaves.omabox.panel inspect | jq -r .list.contentY)\" = 0 ]"
  read -r x y < <(q '.rows[1] | "\(.x + 100) \(.y + 10)"')
  ob pointer -b "$B" -- move "$x" "$y" >/dev/null
  check_eq "the row under the pointer is selected" box-02 "$(q .selected)"
  local before; before=$(q '[.rows[] | {name, y}] | @json')
  jq '[.[0] + {name: "box-00"}] + [.[] | select(.name != "box-04")]' "$H/list.json" > "$H/l" && mv "$H/l" "$H/list.json"
  wl_polled
  check_eq "held under the pointer, the rows do not move (#117)" "$before" "$(q '[.rows[] | {name, y}] | @json')"
  check_eq "...the selection stays" box-02 "$(q .selected)"
  check_eq "...the new box is counted, not shown" "true 1" "$(q '"\(.held) \(.newCount)"')"
  check_eq "...the gone one stays in its slot, marked" true "$(q '.rows[] | select(.name == "box-04") | .gone')"
  : > "$H/actions"
  read -r x y < <(q '.rows[] | select(.name == "box-04") | "\(.x + 100) \(.y + 10)"')
  ob click -b "$B" "$x" "$y" >/dev/null
  check "...a click on it does nothing" holds 1 bash -c "[ ! -s '$H/actions' ]"
  ob pointer -b "$B" -- move 10 1000 >/dev/null
  check "the pointer off the panel: the list as it is (box-00 in, box-04 out)" until_ok 3 bash -c \
    "[ \"\$('$CLI' run -b '$B' -- omarchy-shell chaves.omabox.panel inspect | jq -r '\"\(.held) \(.newCount) \([.rows[].name] | index(\"box-00\")) \([.rows[].name] | index(\"box-04\"))\"')\" = 'false 0 0 null' ]"
  jq -n "[$row + {name: \"a\"}, $irow + {name: \"b\"}]" > "$H/list.json"; wl_polled
  check "with two boxes the list is as tall as its rows" test "$(q '.list.height == .list.contentHeight and (.rows | length) == 2')" = true
  # #118: Settings has a GPU picker on a machine with two GPUs: Auto naming its GPU, each GPU (one bound
  # to vfio-pci: unavailable), the fallback said when the chosen one is not there; a pick runs config.
  local gpus='[{"pci":"0000:01:00.0","driver":"vfio-pci","kind":"nvidia","name":"GeForce RTX 5070 Ti","node":null,"available":false,"why":"bound to vfio-pci"},
    {"pci":"0000:7a:00.0","driver":"amdgpu","kind":"amd","name":"Radeon Graphics","node":"/dev/dri/renderD128","available":true}]'
  jq -n --argjson g "$gpus" '{gpu: "0000:01:00.0", gpus: $g, gpu_auto: "0000:7a:00.0", gpu_now: "0000:7a:00.0"}' > "$H/config.json"
  ob keys -b "$B" Escape >/dev/null
  ob run -b "$B" -- omarchy-shell chaves.omabox.panel face settings
  until_ok 3 panel_takes_keys "$B"
  check_eq "Settings shows the GPU picker with two GPUs (#118)" \
    '["Auto (now: Radeon Graphics)","GeForce RTX 5070 Ti · unavailable (bound to vfio-pci)","Radeon Graphics · amdgpu"]' \
    "$(until_ok 3 bash -c "'$CLI' run -b '$B' -- omarchy-shell chaves.omabox.panel inspect | jq -e '.gpu.shown' >/dev/null"; q '.gpu.options | tojson')"
  check_match "...the chosen one is not there: the fallback said" "^Not there now \(bound to vfio-pci\): new boxes render on Radeon Graphics" "$(q .gpu.line)"
  : > "$H/actions"
  # shellcheck disable=SC2046 # X Y
  ob click -b "$B" $(q '.gpu.at | "\(.x) \(.y)"') >/dev/null
  ob pointer -b "$B" -- move 10 1000 >/dev/null
  ob keys -b "$B" Down Return >/dev/null   # from the chosen one to the next: Radeon
  check "...a pick runs omabox config gpu SLOT" until_ok 3 grep -qx "config gpu 0000:7a:00.0" "$H/actions"
  # Finding 237: with gpu nvidia (a kind) the amber line gives the reason too, the vfio-bound card's kind
  # being NVIDIA's; a row's caption names its GPU as `ls` does: with one render node (the other GPU on
  # vfio-pci), only a fallback's, with its slot.
  local rr='{"node":"/dev/dri/renderD128","pci":"0000:7a:00.0","driver":"amdgpu"}'
  jq -n "[$row + {name: \"a\", render: ($rr + {fallback: true, wanted: \"nvidia\"})}, $row + {name: \"c\", render: ($rr + {fallback: false}), orphan: true}]" > "$H/list.json"
  jq -n --argjson g "$gpus" '{gpu: "nvidia", gpus: $g, gpu_auto: "0000:7a:00.0", gpu_now: "0000:7a:00.0"}' > "$H/config.json"
  ob keys -b "$B" Escape Escape >/dev/null
  ob run -b "$B" -- omarchy-shell chaves.omabox.panel face settings
  until_ok 3 bash -c "'$CLI' run -b '$B' -- omarchy-shell chaves.omabox.panel inspect | jq -e '.gpu.value == \"nvidia\"' >/dev/null"
  check_match "...gpu nvidia, its card on vfio-pci: the reason said too (finding 237)" "^Not there now \(bound to vfio-pci\): new boxes render on Radeon" "$(q .gpu.line)"
  ob keys -b "$B" Escape >/dev/null; wl_polled
  check_eq "a row names its GPU as ls does: with one render node a fallback's only, its slot too (finding 237)" "true false" \
    "$(q '[.rows[] | {(.name): .caption}] | add | "\(.a | test("^headless · amdgpu 7a:00.0 \\(fallback\\) · ")) \(.c | test("amdgpu"))"')"
  check_eq "...and says orphan for an orphan, as ls does (#220)" "false true" \
    "$(q '[.rows[] | {(.name): .caption}] | add | "\(.a | test("orphan")) \(.c | test(" · orphan"))"')"
  jq -n --argjson g "[$(jq -c '.[1]' <<<"$gpus")]" '{gpu: "auto", gpus: $g, gpu_auto: "0000:7a:00.0", gpu_now: "0000:7a:00.0"}' > "$H/config.json"
  ob keys -b "$B" Escape Escape >/dev/null
  ob run -b "$B" -- omarchy-shell chaves.omabox.panel face settings
  check "...not with one GPU and gpu auto" until_ok 3 bash -c "[ \"\$('$CLI' run -b '$B' -- omarchy-shell chaves.omabox.panel inspect | jq -r .gpu.shown)\" = false ]"
  check_eq "the widget logged no QML errors" "" "$(ob log -b "$B" shell -n all --grep "Panel.qml|TypeError|ReferenceError" | grep -v IpcHandler)"
  ob down "$B" >/dev/null
}

# Monitors beyond the first in a headless box (#122): up --monitor, monitor add/remove/list, kept over a
# reload, the shell's bar on each, the pointer and clicks across them, a shot of one. On a GPU other
# than NVIDIA's (headless outputs), and on NVIDIA's (Wayland outputs, #165) in t_monitors_nvidia.
# gpu_node other|nvidia: the first render node not on the nvidia driver, or the first on it.
gpu_node() {
  local n d
  for n in $(probe render_nodes); do
    d=$(probe render_driver "$n")
    if [ "$1" = nvidia ]; then [ "$d" != nvidia ] || { echo "$n"; return; }
    else [ "$d" = nvidia ] || { echo "$n"; return; }; fi
  done
}
# nvidia_ready: NVIDIA's render node, for the tests of what a box on it does; else why not, exit 1.
nvidia_ready() {
  local n; n=$(gpu_node nvidia)
  [ -n "$n" ] || { echo "no render node on the nvidia driver here"; return 1; }
  ! aq_unfixed "$CLI" || { echo "a headless box on NVIDIA needs aquamarine's fix (omabox setup --aquamarine)"; return 1; }
  echo "$n"
}
# The main screen at a scale (finding 296): --size WxH,scale=S, mode, shot, click --in, a reload, a
# monitor beside it; on a GPU other than NVIDIA's (HEADLESS-2) and on NVIDIA's (WAYLAND-1).
t_scale() {
  local n; n=$(gpu_node other)
  [ -n "$n" ] || { skip "a scaled main screen" "no render node here but NVIDIA's (t_scale_nvidia runs there)"; return; }
  scale_on "$n" "$P-sc" HEADLESS-2 HEADLESS-3
}
t_scale_nvidia() {
  local n; n=$(nvidia_ready) || { skip "a scaled main screen on NVIDIA" "$n"; return; }
  scale_on "$n" "$P-scnv" WAYLAND-1 WAYLAND-2
}
# burst_vs_shot BOX ARGS...: a 2-frame `shot --burst` with ARGS against a plain `shot` with the same, of a
# still scene (#196, finding 314): "WxH WxH AE" (the frame's size, the shot's, the pixels that differ).
# The burst's frames come from tools/burst, the shot from grim: the same image is the point.
burst_vs_shot() {
  local b=$1 d=$TMP/bvs-$1; shift
  rm -rf "$d"; mkdir -p "$d"
  ob shot -b "$b" "$@" --burst 2 -o "$d/b" >/dev/null 2>&1 || { echo "burst failed"; return; }
  ob shot -b "$b" "$@" -o "$d/s.png" >/dev/null 2>&1 || { echo "shot failed"; return; }
  echo "$(magick identify -format '%wx%h' "$d/b/frame-002.png" 2>&1) $(magick identify -format '%wx%h' "$d/s.png" 2>&1)" \
    "$(magick compare -metric AE "$d/s.png" "$d/b/frame-002.png" null: 2>&1 | cut -d' ' -f1)"
}
# The screencast events box B's Hyprland posted since line N of its events log (#196): screencast_since B N
screencast_since() { tail -n "+$(($2 + 1))" "$(ob path -b "$1")/home/events.log" 2>/dev/null | grep -c '^[0-9.]* screencast'; }

scale_on() {
  local n=$1 B=$2 m0=$3 m1=$4 out
  out=$(env OMABOX_RENDER_NODE="$n" "$CLI" up "$B" --size 2560x1440,scale=2 --net isolated 2>&1) || { no "up --size 2560x1440,scale=2" "failed: $out"; return; }
  check_match "up says the size with its scale" "box '$B' up \(2560x1440@60,scale=2\)" "$out"
  check_eq "mode: the main screen at scale 2" "$m0 2560x1440@60,scale=2" "$(ob mode -b "$B")"
  check_eq "...box.json keeps it" "2560x1440@60 2" "$(jq -r '"\(.size) \(.scale)"' "$(ob path -b "$B")/box.json")"
  check_match "...and ls" "^$B +headless +2560x1440@60,scale=2 " "$(ob ls | grep "^$B ")"
  local f=$TMP/$B.png err
  err=$(ob shot -b "$B" -o "$f" 2>&1 >/dev/null)
  check_eq "shot: the screen's pixels, 2560x1440" 2560x1440 "$(magick identify -format '%wx%h' "$f" 2>&1)"
  # calibrate's card (#188): the size of a full shot, asked of the box.
  ob calibrate -b "$B" -o "$TMP/$B-card.png" >/dev/null 2>&1
  check_eq "calibrate: a card the size of the shot" 2560x1440 "$(magick identify -format '%wx%h' "$TMP/$B-card.png" 2>&1)"
  check_match "...said: an image of the 1280x720 layout" "2560x1440 image of the screen's 1280x720 at 0,0 \(x0.5\)" "$err"
  check "click --in the shot: image pixels to the layout's" ob click -b "$B" --in "$f" 2000 1000
  check_eq "...the pointer at half of them" "1000, 500" "$(ob hyprctl -b "$B" cursorpos)"
  check_match "a point past the layout refused" "1300,100 is off the 1280x720 screen" "$(ob click -b "$B" 1300 100 2>&1)"
  # --fit against the image grim writes, not the layout (#227, finding 299): 2000 is above the
  # layout's 1280 and below the image's 2560.
  local ff=$TMP/$B-fit.png
  err=$(ob shot -b "$B" --fit 2000 -o "$ff" 2>&1 >/dev/null)
  check_eq "shot --fit 2000 of a scale-2 screen: 2000 px long" 2000x1125 "$(magick identify -format '%wx%h' "$ff" 2>&1)"
  check_match "...said: an image of the 1280x720 layout" "2000x1125 image of the screen's 1280x720 at 0,0 \(x0.64\)" "$err"
  check "...click --in it" ob click -b "$B" --in "$ff" 1000 500
  check_eq "...the pointer at the layout's point" "640, 320" "$(ob hyprctl -b "$B" cursorpos)"
  ob shot -b "$B" --fit 3000 -o "$ff" >/dev/null 2>&1
  check_eq "shot --fit 3000, above the image: full size" 2560x1440 "$(magick identify -format '%wx%h' "$ff" 2>&1)"
  ob shot -b "$B" -g "100,100 400x300" --fit 600 -o "$ff" >/dev/null 2>&1
  check_eq "shot -g 400x300 --fit 600 (an 800x600 image): 600 px long" 600x450 "$(magick identify -format '%wx%h' "$ff" 2>&1)"
  check "...click --in it" ob click -b "$B" --in "$ff" 300 225
  check_eq "...the pointer in the region's layout" "300, 250" "$(ob hyprctl -b "$B" cursorpos)"
  # A terminal with a red band (rows 20-35, 100 columns) under black: a window's pixels tell places apart.
  ob run -b "$B" -d --wait -- foot --app-id t227 sh -c \
    'r=20; while [ $r -le 35 ]; do printf "\033[%d;1H\033[41m%100s" $r ""; r=$((r+1)); done; printf "\033[0m"; sleep 600' >/dev/null 2>&1
  local wl; wl=$(ob windows -b "$B" --json | jq -r '.[] | select(.class == "t227") | "\(.size[0]) \(.size[1]) \(.at[0]) \(.at[1])"')
  if [ -n "$wl" ]; then
    local ww wh wx wy iw ih wlong fn; read -r ww wh wx wy <<<"$wl"; wlong=$((ww > wh ? ww : wh))
    for fn in 2000 1000; do
      ob shot -b "$B" --window class:t227 --fit "$fn" -o "$ff" >/dev/null 2>&1
      check_eq "shot --window --fit $fn of a ${wlong} px window at scale 2: $fn px long" "$fn" "$(magick identify -format '%[fx:max(w,h)]' "$ff" 2>&1)"
    done
    read -r iw ih < <(magick identify -format '%w %h\n' "$ff" 2>/dev/null) || iw=1 ih=1
    check "...click --in it" ob click -b "$B" --in "$ff" 100 50
    check_eq "...the pointer at the window's point" "$((wx + 201 * ww / (2 * iw))), $((wy + 101 * wh / (2 * ih)))" "$(ob hyprctl -b "$B" cursorpos)"
    # A window's -g and pixel in its own coordinates, which grim takes in its buffer's (finding 300).
    local wf=$TMP/$B-win.png wg=$TMP/$B-wing.png
    ob shot -b "$B" --window class:t227 --fit 0 -o "$wf" >/dev/null 2>&1
    ob shot -b "$B" --window class:t227 -g "300,250 200x200" -o "$wg" >/dev/null 2>&1
    check_eq "shot --window -g 200x200 at scale 2: a 400x400 image" 400x400 "$(magick identify -format '%wx%h' "$wg" 2>&1)"
    check_eq "...the window's 300,250 200x200 (across the band's top): its whole shot's 600,500 400x400" 0 \
      "$(magick "$wf" -crop 400x400+600+500 +repage "$wg" -alpha off -metric AE -compare -format '%[distortion]' info: 2>&1)"
    local px1 px2 px3; px1=$(magick "$wf" -alpha off -format '#%[hex:p{800,1000}]' info: | tr 'A-F' 'a-f')
    px3=$(magick "$wf" -alpha off -format '#%[hex:p{800,700}]' info: | tr 'A-F' 'a-f')
    px2=$(magick "$wf" -alpha off -format '#%[hex:p{400,200}]' info: | tr 'A-F' 'a-f')
    check_eq "pixel --window: the window's 400,500 (in the band) and 200,100, as its whole shot has them" "400,500 $px1 200,100 $px2" \
      "$(ob pixel -b "$B" --window class:t227 400 500 200 100 | tr '\n' ' ' | sed 's/ $//')"
    check_eq "pixel --in the -g shot: the window's 400,350" "$px3" "$(ob pixel -b "$B" --in "$wg" 200 200)"
    ob shot -b "$B" --window class:t227 -g "300,250 200x200" --fit 300 -o "$wg" >/dev/null 2>&1
    check_eq "shot --window -g 200x200 --fit 300 (a 400x400 image): 300 px long" 300x300 "$(magick identify -format '%wx%h' "$wg" 2>&1)"
    check "...click --in it" ob click -b "$B" --in "$wg" 150 150
    check_eq "...the pointer at the crop's point in the window" "$((wx + 300 + 100)), $((wy + 250 + 100))" "$(ob hyprctl -b "$B" cursorpos)"
    # -g past the window's corner (#240): cut in the window's coordinates, then scaled to its buffer.
    err=$(ob shot -b "$B" --window class:t227 -g "$((ww - 100)),$((wh - 50)) 200x200" -o "$wg" 2>&1 >/dev/null)
    check_match "shot --window -g past the corner at scale 2: said in the window's coordinates" \
      "clipped to $((ww - 100)),$((wh - 50)) 100x50 of window .*: 100 px past the right edge, 150 px past the bottom edge" "$err"
    check_eq "...its 100x50 a 200x100 image" 200x100 "$(magick identify -format '%wx%h' "$wg" 2>&1)"
    check_eq "...the whole shot's corner" 0 \
      "$(magick "$wf" -crop 200x100+$((2 * ww - 200))+$((2 * wh - 100)) +repage "$wg" -alpha off -metric AE -compare -format '%[distortion]' info: 2>&1)"
    # shot --burst through one client (#196, finding 314): frames the size and pixels of grim's shot,
    # at scale 2: the screen --fit, a -g --fit, a window, a window's -g --fit.
    local a r args; for a in "--fit|2000" "-g|100,100 400x300|--fit|600" "--window|class:t227" "--window|class:t227|-g|300,250 200x200|--fit|300"; do
      IFS='|' read -r -a args <<<"$a"
      r=$(burst_vs_shot "$B" "${args[@]}")
      check "shot --burst ${args[*]}: a frame is the shot's image ($r)" awk '{ exit !($1 == $2 && $3 + 0 <= 50) }' <<<"$r"
    done
    ob run -b "$B" -- pkill -x foot >/dev/null 2>&1 || true
  else no "a foot window for shot --window --fit" "none listed"; fi
  # record (finding 297): a video of the screen at its pixels, a steady frame rate, made in the box.
  if command -v wf-recorder >/dev/null && command -v ffmpeg >/dev/null; then
    local v=$TMP/$B.mp4 t0
    check_eq "record status: not recording" "box '$B': not recording" "$(ob record -b "$B" status)"
    t0=$SECONDS
    check "record start" ob record -b "$B" start -o "$v"
    check_match "...status says so" "^recording $m0 of box '$B' at 30 fps, to $v" "$(ob record -b "$B" status)"
    check_match "...a second start refused" "is recording already, to $v" "$(ob record -b "$B" start 2>&1)"
    ob keys -b "$B" super+Return >/dev/null; sleep 1.5
    check_eq "record stop prints the file" "$v" "$(ob record -b "$B" stop 2>/dev/null)"
    check_eq "...an H.264 video at the screen's pixels, 30 fps" "h264,2560,1440,30/1" \
      "$(ffprobe -v error -select_streams v:0 -show_entries stream=codec_name,width,height,r_frame_rate -of csv=p=0 "$v" 2>&1)"
    check "...as long as it ran, about (1.5 s to the wall time)" awk -v d="$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$v")" \
      -v w=$((SECONDS - t0 + 1)) 'BEGIN { exit !(d >= 1.5 && d <= w) }'
    check_match "record stop again: not recording" "is not recording" "$(ob record -b "$B" stop 2>&1)"
    check_eq "record -- ACTION: that action at --fps 60" "$v 60/1" \
      "$(ob record -b "$B" -o "$v" --fps 60 --hold 300ms -- keys -t x 2>/dev/null) $(ffprobe -v error -select_streams v:0 -show_entries stream=r_frame_rate -of csv=p=0 "$v")"
    check_eq "...and it stopped" "box '$B': not recording" "$(ob record -b "$B" status)"
    check_match "record --monitor of one it does not have" "has no monitor NOPE \($m0\)" "$(ob record -b "$B" start --monitor NOPE 2>&1)"
    check_eq "...nothing recording" "box '$B': not recording" "$(ob record -b "$B" status)"
    record_marks_on
    record_colours_on
  else
    skip "record" "no wf-recorder or ffmpeg here"
  fi
  ob reload -b "$B" >/dev/null 2>&1
  check_eq "a reload keeps the scale" "$m0 2560x1440@60,scale=2" "$(ob mode -b "$B")"
  check "monitor add beside it" ob monitor -b "$B" add 800x600
  check_eq "...placed right of the layout's 1280, not the mode's 2560" "1280,0" \
    "$(ob monitor -b "$B" list --json | jq -r --arg m "$m1" '.[] | select(.name == $m) | "\(.x),\(.y)"')"
  # A layout of scale 2 and 1 (#227): grim writes the whole at 2, a region of the scale-1 one at 1.
  ob shot -b "$B" --fit 3000 -o "$ff" >/dev/null 2>&1
  check_eq "shot --fit 3000 of 2080x720 at scale 2 and 1: 3000 px long" 3000x1038 "$(magick identify -format '%wx%h' "$ff" 2>&1)"
  ob shot -b "$B" --fit 0 -o "$ff" >/dev/null 2>&1; ob calibrate -b "$B" -o "$TMP/$B-card.png" >/dev/null 2>&1
  check_eq "calibrate: a card the size of that layout's full shot" "$(magick identify -format '%wx%h' "$ff" 2>&1)" \
    "$(magick identify -format '%wx%h' "$TMP/$B-card.png" 2>&1)"
  ob shot -b "$B" -g "1280,0 800x600" --fit 1000 -o "$ff" >/dev/null 2>&1
  check_eq "shot -g of the scale-1 monitor --fit 1000: its 800x600, as it is" 800x600 "$(magick identify -format '%wx%h' "$ff" 2>&1)"
  check "monitor remove" ob monitor -b "$B" remove "$m1"
  check_eq "mode WxH,scale=1.5" "$m0 1920x1080@60,scale=1.5" "$(ob mode -b "$B" 1920x1080,scale=1.5)"
  ob reload -b "$B" >/dev/null 2>&1
  check_eq "...kept over a reload" "$m0 1920x1080@60,scale=1.5" "$(ob mode -b "$B")"
  check_eq "mode WxH without a scale is 1" "$m0 1280x720@60" "$(ob mode -b "$B" 1280x720)"
  check_eq "...box.json 1" 1 "$(jq -r .scale "$(ob path -b "$B")/box.json")"
  check_match "up of it at another scale: refused, said" "--size 1280x720@60,scale=2 \(it is 1280x720@60\)" "$(ob up "$B" --size 1280x720,scale=2 2>&1)"
  # A down while it records takes its wf-recorder too: it runs in the box's pid namespace.
  if command -v wf-recorder >/dev/null && command -v ffmpeg >/dev/null && ob record -b "$B" start -o "$TMP/$B-down.mp4" >/dev/null 2>&1; then
    local wp="" p; for p in $(probe box_pids "$B"); do
      [ "$(cat "/proc/$p/comm" 2>/dev/null)" != wf-recorder ] || wp=$p; done
    check "a recording's wf-recorder is in the box's pid namespace" test -n "$wp"
    ob down "$B" >/dev/null 2>&1 || true
    check_fails "...gone with the box" test -n "$wp" -a -d "/proc/${wp:-0}"
  fi
  ob down "$B" >/dev/null 2>&1 || true
  check_match "an interactive box takes no scale" "takes no scale there" "$(ob up "$B-i" --interactive --size 1920x1080,scale=2 2>&1)"
  check_fails "...and none is left" test -e "$XDG_RUNTIME_DIR/omabox/$B-i/box.json"
}
# record mark and record sheet (#176, finding 306), in scale_on's box B (2560x1440 at scale 2): a
# terminal turns red at a time it notes, right after a mark. In the video, the first red frame is no
# more than a frame before that time (the fps pass shows a frame from the slot nearest its time),
# and within 250 ms after it (the terminal's drawing and Hyprland's).
record_marks_on() {
  local mv=$TMP/$B-marks.mp4 mo so flip m mt cv fr sh h px c
  check_match "record mark: not recording" "box '$B' is not recording" "$(ob record -b "$B" mark x 2>&1)"
  ob run -b "$B" -d --wait -- foot --app-id t176 bash -c \
    'rm -f /tmp/go176; mkfifo /tmp/go176; read -r _ < /tmp/go176; t=$EPOCHREALTIME; printf "\033]11;#ff0000\007"; echo "$t" > /tmp/flip176; sleep 600' >/dev/null 2>&1
  if ! ob wait -b "$B" window class:t176 >/dev/null 2>&1 || ! ob record -b "$B" start -o "$mv" >/dev/null 2>&1; then
    no "record mark" "no terminal t176, or record start failed"; return
  fi
  # 200x200 image pixels at its middle (scale 2; the terminal super+Return opened is beside it).
  c=$(ob windows -b "$B" --json | jq -r '.[] | select(.class == "t176") | "\(2 * (.at[0] + .size[0] / 2 | floor) - 100):\(2 * (.at[1] + .size[1] / 2 | floor) - 100)"')
  sleep 0.5
  mo=$(ob record -b "$B" mark "turns red" 2>&1)
  ob run -b "$B" -- sh -c 'echo > /tmp/go176'
  sleep 1
  ob record -b "$B" mark -- "-after, 100% <done>" >/dev/null 2>&1
  so=$(ob record -b "$B" stop --sheet --frames 6 2>"$TMP/$B-stop.err")
  check_match "record mark prints its time in the video" "^[0-9]+\.[0-9]{3}s turns red$" "$mo"
  check_eq "record stop --sheet prints the video, then its sheet" "$mv|${mv%.mp4}.sheet.png" "$(paste -sd '|' <<<"$so")"
  check_match "...says where the marks are" "2 marks in ${mv%.mp4}\.marks\.tsv .*and ${mv%.mp4}\.vtt \(captions\)" "$(cat "$TMP/$B-stop.err")"
  check_eq "...the marks' texts, after a header" "text|turns red|-after, 100% <done>" "$(cut -f3 "${mv%.mp4}.marks.tsv" | paste -sd '|')"
  check_eq "...WebVTT captions of them" "WEBVTT 2 &lt;done&gt;" \
    "$(head -n 1 "${mv%.mp4}.vtt") $(grep -c ' --> ' "${mv%.mp4}.vtt") $(grep -o '&lt;done&gt;' "${mv%.mp4}.vtt")"
  flip=$(ob run -b "$B" -- cat /tmp/flip176 | tr , .)
  read -r m mt < <(awk -F '\t' 'NR == 2 { print $1, $2 }' "${mv%.mp4}.marks.tsv")
  cv=$(awk -v m="$m" -v mt="$mt" -v c="$flip" 'BEGIN { printf "%d", m + (c - mt) * 1000 }')
  fr=$(ffmpeg -v error -i "$mv" -vf "crop=200:200:${c:-1180:620},scale=1:1" -f rawvideo -pix_fmt rgb24 - |
    od -An -tu1 -w3 -v | awk '$1 > 200 && $2 < 80 && $3 < 80 { print NR - 1; exit }')
  check "...a change right after a mark: its first frame no more than a frame early, at most 250 ms late (mark at $m ms, the change at $cv ms, first red frame ${fr:-none} at 30 fps)" \
    awk -v f="${fr:--1}" -v cv="$cv" 'BEGIN { t = f * 1000 / 30; exit !(f >= 0 && t >= cv - 1000 / 30 && t <= cv + 250) }'
  # The sheet: 6 tiles 320 px wide (2560x1440: 180 high), 5 a row, each cell 3 px around; frame 6 in
  # the second row, nothing beside it; text under the first.
  sh=${mv%.mp4}.sheet.png
  h=$(magick identify -format '%h' "$sh" 2>/dev/null) || h=0
  px=$(magick "$sh" -alpha off -format '%[hex:p{163,93}] %[hex:p{163,'$((h / 2 + 93))'}] %[hex:p{489,'$((h / 2 + 93))'}]' info: 2>/dev/null) || px=""
  check_match "...the sheet: 1630 wide, tiles 1 and 6 there, no 7th (white)" "^1630 [0-9A-F]{6} [0-9A-F]{6} FFFFFF$" "$(magick identify -format '%w' "$sh" 2>&1) $px"
  check_fails "...tiles 1 and 6 not white" grep -q FFFFFF <<<"${px% *}"
  check "...a label under tile 1" awk -v v="$(magick "$sh" -crop "326x$((h / 2 - 189))+0+186" -format '%[fx:minima]' info: 2>/dev/null)" 'BEGIN { exit !(v != "" && v < 0.5) }'
  so=$(ob record -b "$B" sheet "$mv" --every 500ms --fit 800 -o "$TMP/$B-s2.png" 2>/dev/null)
  check_eq "record sheet VIDEO --every 500ms --fit 800: the sheet, 800 px at most" "$TMP/$B-s2.png 800" \
    "$so $(magick identify -format '%[fx:max(w,h)]' "$TMP/$B-s2.png" 2>&1)"
  ob run -b "$B" -- pkill -x foot >/dev/null 2>&1 || true
}
# A recording's colours (finding 312), in scale_on's box B (2560x1440 at scale 2): an opaque terminal
# in four bands, #00ff00, #ffffff, #ff0000 and #000000, recorded a second; a frame from its middle,
# decoded as ffmpeg reads its tags, has each band's colour within 3 levels a channel (wf-recorder's
# limited-range values tagged full gave #0cea0d, #e8e8e8, #ea0d0e, #101010).
record_colours_on() {
  local cv=$TMP/$B-colours.mp4 g f dur y h i got="" want="" px tags
  ob hyprctl -b "$B" eval 'hl.window_rule({ name = "t312", match = { class = "t312" }, opacity = "1 1" })' >/dev/null 2>&1
  # shellcheck disable=SC2016 # the box's bash's
  ob run -b "$B" -d --wait -- foot --app-id t312 bash -c 'd() { printf "\033[H\033[?25l"; r=$(tput lines)
    for i in $(seq 1 "$r"); do case $(( (i - 1) * 4 / r )) in 0) c="0;255;0" ;; 1) c="255;255;255" ;; 2) c="255;0;0" ;; *) c="0;0;0" ;; esac
      printf "\033[48;2;%sm\033[K" "$c"; [ "$i" -lt "$r" ] && printf "\n"; done; }; trap d WINCH; d; while :; do sleep 600 & wait; done' >/dev/null 2>&1
  # The window's middle column and each band's middle row (an eighth of its height, three, five, seven).
  g=$(ob windows -b "$B" --json | jq -r '.[] | select(.class == "t312") | "\(.at[0] + (.size[0] / 2 | floor)) \(.at[1]) \(.size[1])"')
  if [ -z "$g" ] || ! ob wait -b "$B" still >/dev/null 2>&1 || ! ob record -b "$B" start -o "$cv" >/dev/null 2>&1; then
    no "record: the colours" "no terminal t312, or record start failed"; return
  fi
  sleep 1
  ob record -b "$B" stop >/dev/null 2>&1
  tags=$(ffprobe -v error -select_streams v:0 -show_entries stream=pix_fmt,color_range,color_space,color_primaries,color_transfer -of csv=p=0 "$cv" 2>&1)
  check_eq "record: a video players read alike: 4:2:0, limited range, BT.709, tagged so" "yuv420p,tv,bt709,bt709,bt709" "$tags"
  dur=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$cv" 2>/dev/null) || dur=1
  read -r f y h <<<"$g"
  for i in 1 3 5 7; do
    px=$(ob pixel -b "$B" "$f" $((y + i * h / 8)) 2>/dev/null | awk '{ print $NF }')
    want+="${px:-?} "
    got+=$(ffmpeg -v error -ss "$(awk -v d="$dur" 'BEGIN { printf "%.3f", d / 2 }')" -i "$cv" -frames:v 1 \
      -vf "crop=2:2:$((2 * f)):$((2 * (y + i * h / 8)))" -f rawvideo -pix_fmt rgb24 - 2>/dev/null | od -An -tu1 -w3 -v | head -n 1 | awk '{ printf "%d,%d,%d ", $1, $2, $3 }')
  done
  check_eq "...the screen: #00ff00, #ffffff, #ff0000, #000000 bands" "#00ff00 #ffffff #ff0000 #000000 " "$want"
  check "...a frame from its middle: each band within 3 a channel ($got)" awk -v g="$got" 'BEGIN {
    split("0,255,0 255,255,255 255,0,0 0,0,0", w, " "); if (split(g, a, " ") != 4) exit 1
    for (i = 1; i <= 4; i++) { split(a[i], x, ","); split(w[i], y, ",")
      for (c = 1; c <= 3; c++) { d = x[c] - y[c]; if (d > 3 || d < -3) exit 1 } } }'
  ob run -b "$B" -- pkill -x foot >/dev/null 2>&1 || true
}
t_monitors() {
  local n; n=$(gpu_node other)
  [ -n "$n" ] || { skip "monitors" "no render node here but NVIDIA's (t_monitors_nvidia runs there)"; return; }
  monitors_on "$n" "$P-mon" HEADLESS-2 HEADLESS-3 HEADLESS-4
}
# The same on NVIDIA (#165, finding 234): Wayland outputs, windows on the box's labwc, WAYLAND-N.
t_monitors_nvidia() {
  local n; n=$(nvidia_ready) || { skip "monitors on NVIDIA" "$n"; return; }
  monitors_on "$n" "$P-monnv" WAYLAND-1 WAYLAND-2 WAYLAND-3
}
# record --monitor all (#225): the whole layout as one video, on a GPU other than NVIDIA's (headless
# outputs) and on NVIDIA's (Wayland outputs).
t_record_layout() {
  local n; n=$(gpu_node other)
  [ -n "$n" ] || { skip "record --monitor all" "no render node here but NVIDIA's (t_record_layout_nvidia runs there)"; return; }
  record_layout_on "$n" "$P-rl" HEADLESS-2 HEADLESS-3 HEADLESS-4
}
t_record_layout_nvidia() {
  local n; n=$(nvidia_ready) || { skip "record --monitor all on NVIDIA" "$n"; return; }
  record_layout_on "$n" "$P-rlnv" WAYLAND-1 WAYLAND-2 WAYLAND-3
}
# record_layout_on NODE BOX MAIN SECOND THIRD: a 1280x720 main screen, the second portrait by its
# transform (720x1280 in the layout, right of it), the third at scale 2 below the main (640x360): the
# layout is 2000x1280, at scale 2 a 4000x2560 shot and video. A terminal of its own colour on each (two
# on the portrait one, tiled one above the other: turned wrong, they would not match), three of them
# turning white on one trigger. Compared: the video's size with the shot's, its last frame with a shot
# then (in 400x320 cells' mean colours, within 8 of 255: H.264 blurs edges; finding 312), and the frame each
# monitor's white first shows in (one trigger: the same frame, give or take one, each monitor drawing
# on its own clock; a recording out of step by the time its recorders started apart would be more).
record_layout_on() {
  local n=$1 B=$2 m0=$3 m1=$4 m2=$5
  if ! command -v wf-recorder >/dev/null || ! command -v ffmpeg >/dev/null; then skip "record --monitor all" "no wf-recorder or ffmpeg here"; return; fi
  OMABOX_RENDER_NODE="$n" up_ok "$B" --no-shell --net isolated --size 1280x720 --monitor 1280x720 \
    --monitor 1280x720,scale=2,0,720 || { no "up with two more monitors" "$UP_OUT"; return; }
  ob lua -b "$B" "hl.monitor({ output = \"$m1\", mode = \"1280x720@60\", position = \"1280x0\", scale = 1, transform = 1 })" >/dev/null 2>&1
  check "$m1 turned (transform 1)" until_ok 5 bash -c "'$CLI' hyprctl -b '$B' -j monitors | jq -e 'any(.[]; .name == \"$m1\" and .transform == 1)' >/dev/null"
  local spec x y c i
  for spec in "640 360 ff0000 1" "1640 300 00ff00 2" "320 900 0000ff 3" "1640 900 ffff00 4"; do
    read -r x y c i <<<"$spec"
    ob pointer -b "$B" -- move "$x" "$y" >/dev/null
    ob run -b "$B" -d --wait -- foot -T "L$i" sh -c "printf '\033]11;#$c\007'; rm -f /tmp/g$i; mkfifo /tmp/g$i; read -r _ < /tmp/g$i; printf '\033]11;#ffffff\007'; sleep 600" >/dev/null 2>&1
  done
  check_eq "four terminals: one each on $m0 and $m2, two on $m1" "1 2 1" \
    "$(ob hyprctl -b "$B" -j clients | jq -r --argjson m "$(ob hyprctl -b "$B" -j monitors)" --arg a "$m0" --arg b "$m1" --arg c "$m2" \
      '. as $w | [$a, $b, $c] | map(. as $n | ($m[] | select(.name == $n) | .id) as $id | [$w[] | select(.monitor == $id)] | length) | join(" ")' 2>/dev/null)"
  local v=$TMP/$B.mp4 out f=$TMP/$B.png sz
  out=$(ob record -b "$B" start --monitor all -o "$v" 2>&1)
  check_match "record start --monitor all: one video of the three, at the layout's highest scale" \
    "recording $m0, $m1, $m2 of box '$B' as one 4000x2560 video \(the layout at scale 2\)" "$out"
  check_match "...status says so" "^recording $m0, $m1, $m2 of box '$B' as one 4000x2560 video at 30 fps, to $v" "$(ob record -b "$B" status)"
  sleep 0.7
  ob record -b "$B" mark "white" >/dev/null 2>&1
  ob run -b "$B" -- sh -c 'echo > /tmp/g1 & echo > /tmp/g2 & echo > /tmp/g3; wait'
  sleep 0.8
  check_eq "record stop prints the video, then its sheet" "$v|${v%.mp4}.sheet.png" "$(ob record -b "$B" stop --sheet --frames 3 2>/dev/null | paste -sd '|')"
  ob shot -b "$B" -o "$f" >/dev/null 2>&1
  sz=$(magick identify -format '%wx%h' "$f" 2>&1)
  check_eq "...an H.264 video at 30 fps, the size of a shot of the screen ($sz)" "h264,4000,2560,30/1 4000x2560" \
    "$(ffprobe -v error -select_streams v:0 -show_entries stream=codec_name,width,height,r_frame_rate -of csv=p=0 "$v" 2>&1) $sz"
  # Its last frame and the shot, 10x8 cells' mean colours (the gaps transparent in the shot: black).
  local a b
  a=$(magick "$f" -background black -alpha remove -alpha off -scale '10x8!' -depth 8 txt:- 2>/dev/null | awk 'NR > 1 { print $2 }' | tr -d '()' | paste -sd ' ')
  b=$(ffmpeg -v error -sseof -0.2 -i "$v" -frames:v 1 -f image2pipe -c:v png - 2>/dev/null | magick - -scale '10x8!' -depth 8 txt:- 2>/dev/null | awk 'NR > 1 { print $2 }' | tr -d '()' | paste -sd ' ')
  check "...its last frame is the shot's layout: 80 cells' colours within 8 of 255 ($(paste -d / <(tr ' ' '\n' <<<"$a" | head -n 12) <(tr ' ' '\n' <<<"$b" | head -n 12) | paste -sd ' ') ...)" \
    awk -v a="$a" -v b="$b" 'BEGIN { na = split(a, x, "[ ,]"); nb = split(b, y, "[ ,]"); if (na != 240 || nb != 240) exit 1
      for (i = 1; i <= na; i++) { d = x[i] - y[i]; if (d > 8 || d < -8) exit 1 } }'
  # The trigger's white, in each of the three (the middles of L1 on m0, L3 on m2, L2 on m1).
  local fr=() cr
  for cr in 1180:620 540:1700 3180:500; do
    fr+=("$(ffmpeg -v error -i "$v" -vf "crop=200:200:$cr,scale=1:1" -f rawvideo -pix_fmt rgb24 - 2>/dev/null |
      od -An -tu1 -w3 -v | awk '$1 > 200 && $2 > 200 && $3 > 200 { print NR - 1; exit }')")
  done
  check "...one trigger on three monitors: white from the same frame, give or take one (frames ${fr[*]})" \
    awk -v a="${fr[0]:--9}" -v b="${fr[1]:--99}" -v c="${fr[2]:--999}" 'BEGIN { mn = a; mx = a; if (b < mn) mn = b; if (c < mn) mn = c; if (b > mx) mx = b; if (c > mx) mx = c; exit !(mn >= 0 && mx - mn <= 1) }'
  local m; m=$(awk -F '\t' 'NR == 2 { print $1 }' "${v%.mp4}.marks.tsv" 2>/dev/null)
  check "...the mark just before it in the video's clock: the first white at most a frame before it, 500 ms after at most (mark ${m:-none} ms)" \
    awk -v m="${m:--1}" -v f="${fr[0]:--1}" 'BEGIN { t = f * 1000 / 30; exit !(m >= 0 && f >= 0 && t >= m - 1000 / 30 && t <= m + 500) }'
  check_eq "...the sheet: 3 tiles 320 px wide" 978 "$(magick identify -format '%w' "${v%.mp4}.sheet.png" 2>&1)"
  check_eq "record --monitor all -- ACTION: the layout too" "$v 4000,2560" \
    "$(ob record -b "$B" -o "$v" --monitor all --hold 300ms -- pointer -- move 100 100 2>/dev/null) $(ffprobe -v error -select_streams v:0 -show_entries stream=width,height -of csv=p=0 "$v")"
  check_eq "...and it stopped, its folders gone from the box" "box '$B': not recording|" \
    "$(ob record -b "$B" status)|$(ob run -b "$B" -- sh -c 'ls -d /home/sbx/.cache/omabox-record/m* 2>/dev/null')"
  ob monitor -b "$B" remove "$m1" >/dev/null 2>&1; ob monitor -b "$B" remove "$m2" >/dev/null 2>&1
  out=$(ob record -b "$B" start --monitor all -o "$v" 2>&1)
  check_match "--monitor all with the main screen alone: its own recording" "recording $m0 of box '$B' to $v" "$out"
  ob record -b "$B" stop >/dev/null 2>&1
  check_eq "...at its pixels" "1280,720" "$(ffprobe -v error -select_streams v:0 -show_entries stream=width,height -of csv=p=0 "$v")"
  ob down "$B" >/dev/null
}
# The rest of #176 (finding 319): input drawn into a recording, a gliding pointer, idle stretches
# cut. In a 1280x720 box at scale 2 (a 2560x1440 video), over a terminal of one flat colour.
t_record_input() {
  local n; n=$(gpu_node other)
  [ -n "$n" ] || { skip "record --show-input" "no render node here but NVIDIA's"; return; }
  record_input_on "$n" "$P-ri"
}
# The colour at video pixel X Y of VIDEO at SEC seconds: "R G B". ri_rgb VIDEO SEC X Y
ri_rgb() {
  ffmpeg -v error -ss "$2" -i "$1" -frames:v 1 -vf "crop=2:2:$3:$4" -f rawvideo -pix_fmt rgb24 - 2>/dev/null |
    od -An -tu1 -w3 -v | head -n 1 | awk '{ print $1, $2, $3 }'
}
# Within 60 a channel of peek's accent, #ff3cc8 (H.264 blurs a thin ring's colour).
ri_accent() { awk -v c="$1" 'BEGIN { split(c, a, " "); exit !(a[1] > 195 && a[2] < 120 && a[3] > 140) }'; }
# A video's frame at SEC seconds as a PNG. ri_frame VIDEO SEC PNG
ri_frame() { ffmpeg -v error -y -ss "$2" -i "$1" -frames:v 1 -update 1 "$3" 2>/dev/null; }
# A mark's ms in a recording's marks.tsv, by its text. ri_ms TSV TEXT
ri_ms() { awk -F '\t' -v t="$2" '$3 == t { print $1; exit }' "$1"; }
# Time in a recording (#259, #280): `record --for` is that long a video, no action; `record hold` in a
# take puts DURATION into the video between two marks, and, the recorder frozen (no frames for 1.5 s,
# a box slow to give them), waits for the frames past its end, so a stop right after it keeps them.
t_record_hold() {
  local n; n=$(gpu_node other)
  [ -n "$n" ] || { skip "record --for and record hold" "no render node here but NVIDIA's"; return; }
  if ! command -v wf-recorder >/dev/null || ! command -v ffmpeg >/dev/null; then skip "record --for and record hold" "no wf-recorder or ffmpeg here"; return; fi
  local B=$P-rh v=$TMP/$P-rh-for.mp4 w=$TMP/$P-rh-take.mp4 out rc=0 t0 t1 a b c h e d
  OMABOX_RENDER_NODE="$n" up_ok "$B" --no-shell --net isolated || { no "up for record hold" "$UP_OUT"; return; }
  out=$(ob record -b "$B" hold 1s 2>&1) || rc=$?
  check_match "record hold with nothing recording: exit 2, naming record start" "^2 omabox: record hold: box '$B' is not recording \(omabox record start" "$rc $out"
  check_eq "record --for 2s prints the file" "$v" "$(ob record -b "$B" -o "$v" --for 2s 2>/dev/null)"
  d=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$v" 2>/dev/null) || d=0
  check "...2 s of video, the stop's frame or two more (${d:-none} s)" awk -v d="$d" 'BEGIN { exit !(d >= 1.99 && d <= 2.25) }'
  check_eq "...and it stopped" "box '$B': not recording" "$(ob record -b "$B" status)"
  ob record -b "$B" start -o "$w" >/dev/null 2>&1 || { no "record start for record hold" "failed"; ob down "$B" >/dev/null 2>&1; return; }
  ob record -b "$B" mark a >/dev/null 2>&1
  h=$(ob record -b "$B" hold 2s 2>&1)
  ob record -b "$B" mark b >/dev/null 2>&1
  out=$(ob record -b "$B" mark c --hold 500ms 2>&1)
  check_match "record hold prints its span in the video" "^held [0-9]+\.[0-9]{3}s to [0-9]+\.[0-9]{3}s$" "$h"
  check_match "record mark TEXT --hold: the mark, then a hold from its time" "^([0-9]+\.[0-9]{3})s c held ([0-9]+\.[0-9]{3})s to " "$(paste -sd ' ' <<<"$out")"
  check_eq "...the same time" "${BASH_REMATCH[1]:-x}" "${BASH_REMATCH[2]:-y}"
  # shellcheck disable=SC2016 # the box's sh's
  ob run -b "$B" -d -- sh -c 'p=$(pgrep -x wf-recorder); kill -STOP $p; sleep 1.5; kill -CONT $p' >/dev/null 2>&1
  t0=$EPOCHREALTIME; e=$(ob record -b "$B" hold 500ms 2>&1); t1=$EPOCHREALTIME
  ob record -b "$B" stop >/dev/null 2>&1
  a=$(ri_ms "${w%.mp4}.marks.tsv" a); b=$(ri_ms "${w%.mp4}.marks.tsv" b)
  check "...a 2 s hold between two marks: 2 to 2.4 s apart in the video (${a:-none} to ${b:-none} ms)" test $((${b:-0} - ${a:-0})) -ge 2000 -a $((${b:-0} - ${a:-0})) -le 2400
  c=$(awk -v a="$t0" -v b="$t1" 'BEGIN { printf "%.2f", b - a }')
  check "a 500ms hold while the recorder gives no frame for 1.5 s: waits for its frames (${c} s; $e)" awk -v c="$c" 'BEGIN { exit !(c >= 1.0 && c <= 4) }'
  d=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$w" 2>/dev/null) || d=0
  [[ $e =~ to\ ([0-9.]+)s$ ]] || true
  check "...a stop right after it keeps them: the video ($d s) reaches the hold's end (${BASH_REMATCH[1]:-none} s)" \
    awk -v d="$d" -v h="${BASH_REMATCH[1]:-99}" 'BEGIN { exit !(d >= h - 0.034) }'
  ob down "$B" >/dev/null 2>&1 || true
}
record_input_on() {
  local n=$1 B=$2 D v1=$TMP/$2-input.mp4 v2=$TMP/$2-glide.mp4 v3=$TMP/$2-cut.mp4 out m1 m2 c
  if ! command -v wf-recorder >/dev/null || ! command -v ffmpeg >/dev/null; then skip "record --show-input" "no wf-recorder or ffmpeg here"; return; fi
  OMABOX_RENDER_NODE="$n" up_ok "$B" --no-shell --net isolated --size 2560x1440,scale=2 || { no "up for record --show-input" "$UP_OUT"; return; }
  D=$(ob path -b "$B")
  # A terminal of one colour all over (no caret, no echo), turning red on a trigger.
  ob run -b "$B" -d --wait -- foot --app-id t319 bash -c 'stty -echo; printf "\033]11;#203040\007\033[?25l\033[2J"
    rm -f /tmp/go319; mkfifo /tmp/go319; read -r _ < /tmp/go319; t=$EPOCHREALTIME; printf "\033]11;#ff0000\007"; echo "$t" > /tmp/flip319; sleep 600' >/dev/null 2>&1
  ob wait -b "$B" window class:t319 >/dev/null 2>&1 || { no "record --show-input: a terminal" "none"; ob down "$B" >/dev/null 2>&1; return; }
  ob pointer -b "$B" -- move 200 150 >/dev/null 2>&1; ob wait -b "$B" still >/dev/null 2>&1 || true
  # --show-input and --captions: a click, then keys with a --pass, each after a mark.
  ob record -b "$B" start -o "$v1" >/dev/null 2>&1 || { no "record start" "failed"; ob down "$B" >/dev/null 2>&1; return; }
  sleep 0.5; ob record -b "$B" mark "click" >/dev/null 2>&1
  ob click -b "$B" 900 500 >/dev/null 2>&1; sleep 0.6
  export T319PASS=sesame7
  ob keys -b "$B" -t abc --pass T319PASS >/dev/null 2>&1
  check "while it records, the box dir has the input: a --pass as its length alone" grep -q ' secret 7$' "$D/record.input"
  check_fails "...never its value" grep -q sesame7 "$D/record.input"
  sleep 1; ob record -b "$B" mark "keys" >/dev/null 2>&1; sleep 0.3
  out=$(ob record -b "$B" stop --show-input --captions 2>&1)
  check_match "record stop --show-input --captions makes the video" "$v1" "$out"
  check_fails "...the input goes with the recording" test -e "$D/record.input"
  m1=$(ri_ms "${v1%.mp4}.marks.tsv" click) m2=$(ri_ms "${v1%.mp4}.marks.tsv" keys)
  if [[ $m1 =~ ^[0-9]+$ && $m2 =~ ^[0-9]+$ ]]; then
    # The ring around the click point (900,500: video 1801,1001), 12 layout px out: 24 at scale 2.
    c=$(ri_rgb "$v1" "$(awk -v m="$m1" 'BEGIN { printf "%.3f", m / 1000 + 0.4 }')" 1825 1000)
    check "...a frame just after the click: the ring at the click point, peek's accent ($c)" ri_accent "$c"
    c=$(ri_rgb "$v1" "$(awk -v m="$m1" 'BEGIN { printf "%.3f", (m > 150 ? m - 150 : 0) / 1000 }')" 1825 1000)
    check_fails "...not before it ($c)" ri_accent "$c"
    # The caption: the frame at the second mark against the frame before the click with the caption
    # drawn on it as record_overlay draws "abc *******", and as it would draw the secret in clear.
    local fa=$TMP/$B-a.png fb=$TMP/$B-b.png ass=$TMP/$B-ref.ass ref=$TMP/$B-ref.png bad=$TMP/$B-bad.png crop="1200x110+680+1320" good wrong
    ri_frame "$v1" "$(awk -v m="$m2" 'BEGIN { printf "%.3f", m / 1000 }')" "$fa"
    ri_frame "$v1" "$(awk -v m="$m1" 'BEGIN { printf "%.3f", (m > 150 ? m - 150 : 0) / 1000 }')" "$fb"
    printf '%s\n' "1000 2000 text abc" "1000 2000 secret 7" > "$TMP/$B-ri"
    probe record_overlay "$TMP/$B-ri" "" 0 0 0 2 2560 1440 5000 1 0 > "$ass"
    ffmpeg -v error -y -loop 1 -i "$fb" -vf "ass=$ass" -ss 0.5 -frames:v 1 -update 1 "$ref" 2>/dev/null
    printf '%s\n' "1000 2000 text abc sesame7" > "$TMP/$B-ri"
    probe record_overlay "$TMP/$B-ri" "" 0 0 0 2 2560 1440 5000 1 0 > "$ass"
    ffmpeg -v error -y -loop 1 -i "$fb" -vf "ass=$ass" -ss 0.5 -frames:v 1 -update 1 "$bad" 2>/dev/null
    good=$(magick "$fa" "$ref" -crop "$crop" +repage -fuzz 12% -metric AE -compare -format '%[distortion]' info: 2>&1)
    wrong=$(magick "$fa" "$bad" -crop "$crop" +repage -fuzz 12% -metric AE -compare -format '%[distortion]' info: 2>&1)
    check "...the keys' caption at the bottom, the --pass as * (pixels off: $good; drawn in clear it would be $wrong)" \
      awk -v g="$good" -v w="$wrong" 'BEGIN { exit !(g ~ /^[0-9.e+-]+$/ && w ~ /^[0-9.e+-]+$/ && g < 0.001 && w > 10 * g + 0.001) }'
    # --captions: the mark's text at the top, from its time.
    c=$(magick "$fa" -crop 900x110+830+0 +repage -fx 'r > 0.75 && g < 0.45 && b > 0.55' -format '%[fx:mean*w*h]' info: 2>/dev/null)
    check "...the mark as a caption at the top, its plate's accent edge ($c px)" awk -v c="$c" 'BEGIN { exit !(c > 200) }'
  else no "record --show-input: the marks" "none in ${v1%.mp4}.marks.tsv"; fi
  # --glide: record start --glide 1s, then a plain pointer move glides: the pointer travels, its x in
  # the frames between start and end rising, over about a second. The pointer's x a frame: the mean
  # of the pixels off the terminal's colour in a band around its path (a quarter of the size).
  ob pointer -b "$B" --steps 1 -- move 200 300 >/dev/null 2>&1; ob wait -b "$B" still >/dev/null 2>&1 || true
  ob record -b "$B" start -o "$v2" --glide 1s >/dev/null 2>&1 || { no "record start --glide" "failed"; ob down "$B" >/dev/null 2>&1; return; }
  check_eq "...the box knows the glide while it records" 1000 "$(cat "$D/record.glide" 2>&1)"
  sleep 0.4; local g0=$SECONDS; ob pointer -b "$B" -- move 1100 300 >/dev/null 2>&1; sleep 0.4
  ob record -b "$B" stop >/dev/null 2>&1
  check_fails "...and not after it (click, pointer and drag jump again)" test -e "$D/record.glide"
  local xs
  xs=$(ffmpeg -v error -i "$v2" -vf "crop=1840:80:340:560,scale=460:20,format=gray" -f rawvideo - 2>/dev/null |
    od -An -tu1 -w9200 -v | awk '{ s = 0; c = 0; for (i = 1; i <= NF; i++) { v = $i - 45; if (v > 40 || v < -40) { s += (i - 1) % 460; c++ } }
      if (c >= 3) printf "%d ", s / c; else printf "- " }')
  check "...the pointer's x in the frames rises (never back by more than 2), and 15 or more frames on the way over 0.6 s or more ($xs)" \
    awk -v xs="$xs" 'BEGIN { n = split(xs, x, " "); p = -1; mid = 0; f = 0; l = 0
      for (i = 1; i <= n; i++) { if (x[i] == "-") continue; if (p >= 0 && x[i] < p - 2) exit 1; p = x[i]
        if (x[i] > 40 && x[i] < 410) { mid++; if (!f) f = i; l = i } }
      exit !(mid >= 15 && (l - f) / 30 >= 0.6) }'
  [ $((SECONDS - g0)) -lt 10 ] || no "...the glide took its time" "$((SECONDS - g0)) s"
  # --cut-idle 1s: a 5 s still gap cut to 1 s; a mark after it, just before the terminal turns red,
  # still lands on that change, within a frame (finding 306's check).
  ob record -b "$B" start -o "$v3" >/dev/null 2>&1 || { no "record start (cut)" "failed"; ob down "$B" >/dev/null 2>&1; return; }
  sleep 0.3; ob keys -b "$B" -t x >/dev/null 2>&1
  sleep 5; ob record -b "$B" mark red >/dev/null 2>&1
  ob run -b "$B" -- sh -c 'echo > /tmp/go319'
  sleep 0.5
  out=$(ob record -b "$B" stop --cut-idle 1s 2>&1)
  local cutms; cutms=$(sed -n 's/.*cut to 1\.00s (\([0-9.]*\)s out).*/\1/p' <<<"$out")
  check "record stop --cut-idle 1s: the 5 s gap cut to 1 s, about 4 s out ($cutms s)" awk -v c="$cutms" 'BEGIN { exit !(c != "" && c >= 3.4 && c <= 4.9) }'
  local flip mt cv fr
  flip=$(ob run -b "$B" -- cat /tmp/flip319 | tr , .)
  read -r m1 mt < <(awk -F '\t' '$3 == "red" { print $1, $2 }' "${v3%.mp4}.marks.tsv")
  cv=$(awk -v m="$m1" -v mt="$mt" -v c="$flip" 'BEGIN { printf "%d", m + (c - mt) * 1000 }')
  fr=$(ffmpeg -v error -i "$v3" -vf "crop=200:200:1180:620,scale=1:1" -f rawvideo -pix_fmt rgb24 - 2>/dev/null |
    od -An -tu1 -w3 -v | awk '$1 > 200 && $2 < 80 && $3 < 80 { print NR - 1; exit }')
  check "...the mark after the gap moved with it: the change's first frame no more than a frame early, at most 250 ms late (mark at ${m1:-?} ms, the change at $cv ms, first red frame ${fr:-none} at 30 fps)" \
    awk -v f="${fr:--1}" -v cv="$cv" -v m="${m1:-99999}" 'BEGIN { t = f * 1000 / 30; exit !(f >= 0 && m < 4000 && t >= cv - 1000 / 30 && t <= cv + 250) }'
  record_stuck_on
  ob down "$B" >/dev/null 2>&1
}
# A stuck ffmpeg (finding 356: ffmpeg 9.0.1 deadlocks now and then), in record_input_on's box B: the
# stop's encode stopped (SIGSTOP, by a watcher in the box) once, then twice; its bound lowered to 3 s
# (OMABOX_RECORD_FF_SECS). Once: killed and run again, a video. Twice: said, raw.mkv kept, none left.
# The watcher, in the box: the first N ffmpeg processes it sees stopped.
RS_STOPPER='seen=" "; n=0
while [ "$n" -lt "$1" ]; do
  for p in $(pgrep -x ffmpeg); do
    case $seen in *" $p "*) continue ;; esac
    kill -STOP "$p" && seen="$seen$p " && n=$((n + 1))
  done
  sleep 0.02
done'
record_stuck_on() {
  local v=$TMP/$B-stuck.mp4 out rc k t0
  for k in 1 2; do
    ob record -b "$B" start -o "$v" >/dev/null 2>&1 || { no "record start (a stuck ffmpeg)" "failed"; return; }
    ob run -b "$B" -d -- timeout 60 sh -c "$RS_STOPPER" t356 "$k" >/dev/null 2>&1
    sleep 1.5
    t0=$SECONDS; rc=0
    out=$(env OMABOX_RECORD_FF_SECS=3 "$CLI" record -b "$B" stop 2>&1) || rc=$?
    if [ "$k" = 1 ]; then
      check_match "record stop, its ffmpeg stuck once: killed in its bound, run once more, said" \
        "ffmpeg did not finish in 3 s \(stuck: finding 356\): killed, run once more" "$out"
      check_eq "...and the video made" "0 $v" "$rc $(tail -n 1 <<<"$out")"
      check "...a video" test "$(ffprobe -v error -select_streams v:0 -count_packets -show_entries stream=nb_read_packets -of csv=p=0 "$v" 2>/dev/null)" -gt 10
    else
      check_match "record stop, stuck twice: said, and what is kept" \
        "ffmpeg did not finish in 3 s again: killed.*record: ffmpeg could not make the video \(/home/sbx/.cache/omabox-record/raw.mkv in box '$B' is kept\)" "$(paste -sd ' ' <<<"$out")"
      check_eq "...it failed" 1 "$rc"
      check "...raw.mkv kept in the box" ob run -b "$B" -- test -s /home/sbx/.cache/omabox-record/raw.mkv
    fi
    check "...in its two bounds ($((SECONDS - t0)) s)" test $((SECONDS - t0)) -le 30
    check_fails "...no ffmpeg left in the box" ob run -b "$B" -- pgrep -x ffmpeg
    ob run -b "$B" -- pkill -f t356 >/dev/null 2>&1 || true
  done
}
# Audio in a box (#226, finding 313): up --audio's own PipeWire, its only devices a speaker nobody
# hears and a silent mic, nothing of the host's audio in it (no /dev/snd, its own sockets; your
# PipeWire, asked read-only, has no client from it); `audio` tells silence from a tone; `record
# --audio` (one monitor, then --monitor all) muxes the sound in step with the picture: a paced stream
# (pw-cat, started before) turns from silence to a tone as its terminal turns red, and the tone is in
# the video within 50 ms of that moment in the video's clock (a mark just before it gives it) and of
# the first red frame (give or take a frame). A tone from a player started then (pw-play) comes ~60
# ms later than its terminal's red: the player's own start, not the recording's.
# The paced stream: s16le 48 kHz stereo, silence for ARGV[0] s, then a 1 kHz tone for 1 s; as the
# tone starts, the terminal's background red (its tty) and the time to /tmp/flip226.
T226_GEN='use IO::Handle; use Time::HiRes qw(time sleep); my $s = shift; my ($r, $c, $n, $f) = (48000, 480, 0, 0);
open(my $tty, ">", "/dev/tty"); $tty->autoflush(1); my $t0 = time;
while (1) { my $t = $n * $c / $r; last if $t > $s + 1.2; my $w = $t0 + $t - time; sleep($w) if $w > 0;
  if ($t >= $s && !$f) { print $tty "\033]11;#ff0000\007"; open(my $o, ">", "/tmp/flip226"); print $o time, "\n"; close $o; $f = 1 }
  my $b = ""; for my $i (0 .. $c - 1) { my $v = ($t >= $s && $t < $s + 1) ? int(16000 * sin(6.2831853 * 1000 * ($n * $c + $i) / $r)) : 0; $b .= pack("s<s<", $v, $v) }
  syswrite(STDOUT, $b); $n++ }'
t_audio() {
  local B=$P-audio b
  for b in pipewire wireplumber pipewire-pulse pactl wf-recorder ffmpeg perl pw-cat; do
    command -v "$b" >/dev/null || { skip "up --audio" "no $b here"; return; }
  done
  check "up --audio" "$CLI" up "$B" --audio --no-shell --net isolated --size 1280x720
  check_eq "ls --json: audio" true "$("$CLI" ls --json | jq -r --arg b "$B" '.[] | select(.name == $b) | .audio')"
  check_match "...up again with it: already up" "box '$B' is already up$" "$(ob up "$B" --audio 2>&1)"
  check_eq "its default output omabox-speaker, input omabox-mic, and no other device" "omabox-speaker omabox-mic|omabox-speaker|omabox-mic" \
    "$(ob run -b "$B" -- sh -c 'echo "$(pactl get-default-sink) $(pactl get-default-source)"; pactl list short sinks | cut -f2; pactl list short sources | cut -f2 | grep -v "[.]monitor$"' | paste -sd '|')"
  check_fails "...no /dev/snd in it" ob run -b "$B" -- test -e /dev/snd
  local hs bs
  hs=$(stat -c %d:%i "${XDG_RUNTIME_DIR:-/nonexistent}/pipewire-0" 2>/dev/null) || hs=none
  # shellcheck disable=SC2016 # the box's sh's
  bs=$(ob run -b "$B" -- sh -c 'stat -c %d:%i "$XDG_RUNTIME_DIR/pipewire-0"' 2>/dev/null) || bs=""
  check "...its PipeWire socket its own (${bs:-none}; yours ${hs})" test -n "$bs" -a "$bs" != "$hs"
  check_match "audio: silence while nothing plays" "^silence for 0.5s: nothing played to the speaker of box '$B'$" "$(ob audio -b "$B" 0.5 2>&1)"
  ob run -b "$B" -- ffmpeg -v error -y -f lavfi -i "sine=f=1000:d=1:sample_rate=48000" -ac 2 /home/sbx/tone.wav
  # (#324: what wave 4a compared with bash's, now stated: silence as JSON, a tone said in words; its
  # levels and when it sounded are the window's timing, their numbers left out)
  cx_rt=$XDG_RUNTIME_DIR cx_dir=/ cx_env=() cx_prep="" cx_also="" cx_snap=0 cx_sed="" cx_wrap=()
  cx_want=(rc=0 "out~^\\{\"box\":\"$B\",\"seconds\":0\\.3,\"sound\":false,\"floor_db\":-70,\"sound_s\":0\\.0,\"peak_db\":null,\"rms_db\":null,\"spans\":\\[\\],\"levels\":\\[\\{\"t\":0\\.0," err=)
  cx_case "audio --json: silence" audio -b "$B" 300ms --json
  cx_tone() { ob run -b "$B" -d -q -- sh -c 'sleep 0.3; pw-play ~/tone.wav' >/dev/null 2>&1; }
  cx_prep=cx_tone cx_sed='s/-?[0-9]+\.[0-9]+|null/N/g'
  cx_want=(rc=0 'out~^sound for Ns of 2s: peak N dBFS, RMS N dBFS while it sounded; at N' err=)
  cx_case "audio: a tone, said" audio -b "$B" 2
  cx_prep="" cx_sed="" cx_rt=""
  sleep 2.5
  ob run -b "$B" -d -- sh -c 'sleep 0.3; pw-play ~/tone.wav' >/dev/null 2>&1
  local aj; aj=$(ob audio -b "$B" 2 --json 2>&1)
  check "audio 2 --json: a 1 s tone, -40 to -10 dBFS, heard 0.8 to 1.3 s, 20 windows" \
    jq -e '.sound and .peak_db > -40 and .peak_db < -10 and .sound_s >= 0.8 and .sound_s <= 1.3 and (.levels | length) == 20 and (.spans | length) == 1' <<<"$aj"
  audio_take_on "$B" ""
  ob monitor -b "$B" add 1280x720,right >/dev/null 2>&1
  audio_take_on "$B" all
  check_match "record stop --audio refused" "record stop: --audio goes with start, -- ACTION or --for" "$(ob record -b "$B" stop --audio 2>&1)"
  ob down "$B" >/dev/null
}
# audio_take_on BOX MONITOR: one take of t_audio's paced tone and red terminal, recorded with --audio
# (MONITOR all: the whole layout), checked in the video.
audio_take_on() {
  local B=$1 mon=$2 v=$TMP/$1-${2:-main}.mp4 out flip m mt cv on fr hp p inbox="" margs=()
  [ -z "$mon" ] || margs=(--monitor "$mon")
  ob run -b "$B" -- pkill -x foot >/dev/null 2>&1 || true
  # shellcheck disable=SC2016 # the box's bash's
  ob run -b "$B" -d --wait -- foot --app-id t226 bash -c '[ -p /tmp/go226 ] || mkfifo /tmp/go226; read -r _ < /tmp/go226
    perl -e "$1" 1 | pw-cat -p --raw --format s16 --rate 48000 --channels 2 --latency 480 -; sleep 600' t226 "$T226_GEN" >/dev/null 2>&1
  if ! ob wait -b "$B" window class:t226 >/dev/null 2>&1 || ! ob wait -b "$B" still >/dev/null 2>&1; then no "record --audio ${margs[*]}" "no terminal t226"; return; fi
  out=$(ob record -b "$B" start --audio "${margs[@]}" -o "$v" 2>&1)
  check_match "record start --audio ${margs[*]}: its sound too, said" "of box '$B' and its sound (as one|to $v)" "$out"
  check_match "...status says so" "of box '$B' and its sound (as one|at 30 fps)" "$(ob record -b "$B" status 2>&1)"
  sleep 0.5
  ob record -b "$B" mark go >/dev/null 2>&1
  ob run -b "$B" -- sh -c 'echo > /tmp/go226'
  sleep 1
  # Your PipeWire, asked once and only read (pw-cli ls Client): none of its clients is in the box.
  if [ -z "$mon" ] && command -v pw-cli >/dev/null && [ -S "${XDG_RUNTIME_DIR:-/nonexistent}/pipewire-0" ]; then
    hp=$(timeout 5 pw-cli ls Client 2>/dev/null | sed -n 's/.*pipewire.sec.pid = "\{0,1\}\([0-9]*\).*/\1/p' | sort -u) || hp=""
    for p in $hp; do [ "$(ob which "$p" 2>/dev/null)" != "$B" ] || inbox+=" $p"; done
    check "...your PipeWire has no client from the box while it plays (${hp//$'\n'/ })" test -n "$hp" -a -z "$inbox"
  fi
  sleep 1.5
  out=$(ob record -b "$B" stop 2>&1 >/dev/null)
  check_match "record stop: with sound, said" "at 30 fps, with sound$" "$out"
  check_eq "...the MP4 has H.264 and AAC" "h264|aac" "$(ffprobe -v error -show_entries stream=codec_name -of csv=p=0 "$v" 2>&1 | paste -sd '|')"
  flip=$(ob run -b "$B" -- cat /tmp/flip226 2>/dev/null | tr , .)
  read -r m mt < <(awk -F '\t' 'NR == 2 { print $1, $2 }' "${v%.mp4}.marks.tsv" 2>/dev/null)
  cv=$(awk -v m="${m:-0}" -v mt="${mt:-0}" -v c="${flip:-0}" 'BEGIN { printf "%d", m + (c - mt) * 1000 }')
  # The tone's first sample above -40 dBFS, in ms; the first frame whose middle is red.
  on=$(ffmpeg -v error -i "$v" -map 0:a:0 -ac 1 -ar 48000 -f s16le - 2>/dev/null | od -An -td2 -w2 -v |
    awk '{ v = $1 < 0 ? -$1 : $1; if (v > 328) { printf "%d", (NR - 1) / 48; exit } }')
  fr=$(ffmpeg -v error -i "$v" -vf "crop=100:100:200:200,scale=1:1" -f rawvideo -pix_fmt rgb24 - 2>/dev/null |
    od -An -tu1 -w3 -v | awk '$1 > 200 && $2 < 80 && $3 < 80 { print NR - 1; exit }')
  check "...the tone within 50 ms of when it started, in the video's clock (started at $cv ms, heard from ${on:-never} ms)" \
    awk -v o="${on:--1}" -v c="$cv" 'BEGIN { exit !(o >= 0 && o - c <= 50 && c - o <= 50) }'
  check "...and of the first red frame, give or take one (frame ${fr:-none} at 30 fps)" \
    awk -v o="${on:--1}" -v f="${fr:--1}" 'BEGIN { t = f * 1000 / 30; exit !(o >= 0 && f >= 0 && o - t <= 84 && t - o <= 84) }'
}
# Turned monitors (finding 311): extent, shot --monitor, click --in and pixel took a monitor's mode over
# its scale as its size in the layout, landscape for a portrait monitor.
t_monitors_turned() {
  local n; n=$(gpu_node other)
  [ -n "$n" ] || { skip "turned monitors" "no render node here but NVIDIA's (t_monitors_turned_nvidia runs there)"; return; }
  monitors_turned_on "$n" "$P-turn" HEADLESS-2 HEADLESS-3 HEADLESS-4
}
t_monitors_turned_nvidia() {
  local n; n=$(nvidia_ready) || { skip "turned monitors on NVIDIA" "$n"; return; }
  monitors_turned_on "$n" "$P-turnnv" WAYLAND-1 WAYLAND-2 WAYLAND-3
}
# monitors_turned_on NODE BOX MAIN SECOND THIRD: a 1280x720 main screen; the second 1280x720 turned by
# transform 1 right of it (720x1280 at 1280,0); the third 1280x720 at scale 2 turned by transform 3
# right of that (360x640 at 2000,0): the layout is 2360x1280, a whole shot 4720x2560 at scale 2.
# A terminal of its own colour on the main and third, two on the second (green above, yellow below).
monitors_turned_on() {
  local n=$1 B=$2 m0=$3 m1=$4 m2=$5
  OMABOX_RENDER_NODE="$n" up_ok "$B" --no-shell --net isolated --size 1280x720 --monitor 1280x720 \
    --monitor 1280x720,scale=2 || { no "up with two more monitors" "$UP_OUT"; return; }
  ob lua -b "$B" "hl.monitor({ output = \"$m1\", mode = \"1280x720@60\", position = \"1280x0\", scale = 1, transform = 1 })" >/dev/null 2>&1
  ob lua -b "$B" "hl.monitor({ output = \"$m2\", mode = \"1280x720@60\", position = \"2000x0\", scale = 2, transform = 3 })" >/dev/null 2>&1
  check "$m1 turned by transform 1, $m2 by 3, side by side" until_ok 5 bash -c "'$CLI' hyprctl -b '$B' -j monitors |
    jq -e 'any(.[]; .name == \"$m1\" and .transform == 1 and .x == 1280) and any(.[]; .name == \"$m2\" and .transform == 3 and .x == 2000)' >/dev/null"
  local spec x y c i
  for spec in "640 360 ff0000 1" "1640 300 00ff00 2" "1640 300 ffff00 3" "2180 320 0000ff 4"; do
    read -r x y c i <<<"$spec"
    ob pointer -b "$B" -- move "$x" "$y" >/dev/null
    ob run -b "$B" -d --wait -- foot -T "L$i" sh -c "printf '\033]11;#$c\007'; sleep 600" >/dev/null 2>&1
  done
  check_eq "four terminals: one each on $m0 and $m2, two on $m1" "1 2 1" \
    "$(ob hyprctl -b "$B" -j clients | jq -r --argjson m "$(ob hyprctl -b "$B" -j monitors)" --arg a "$m0" --arg b "$m1" --arg c "$m2" \
      '. as $w | [$a, $b, $c] | map(. as $n | ($m[] | select(.name == $n) | .id) as $id | [$w[] | select(.monitor == $id)] | length) | join(" ")' 2>/dev/null)"
  local f=$TMP/$B.png fa=$TMP/$B-a.png fb=$TMP/$B-b.png out
  out=$(ob shot -b "$B" --no-pointer -o "$f" 2>&1 >/dev/null)
  check_match "shot: the screen is 2360x1280, the portrait monitors upright" "4720x2560 image of the screen's 2360x1280 at 0,0 \(x0.5\)" "$out"
  check_eq "...grim's image is that size" 4720x2560 "$(magick identify -format '%wx%h' "$f" 2>&1)"
  out=$(ob shot -b "$B" --no-pointer --monitor "$m1" -o "$fa" 2>&1 >/dev/null)
  check_match "shot --monitor $m1 (transform 1): 720x1280 at 1280,0" "screen's 720x1280 at 1280,0" "$out"
  out=$(ob shot -b "$B" --no-pointer --monitor "$m2" -o "$fb" 2>&1 >/dev/null)
  check_match "shot --monitor $m2 (transform 3, scale 2): 360x640 at 2000,0, a 720x1280 image" "720x1280 image of the screen's 360x640 at 2000,0" "$out"
  # Each monitor's shot against its part of the whole one, in 6x10 cells' mean colours.
  local a b sh
  turned_cells() { magick "$@" -background black -alpha remove -alpha off -scale '6x10!' -depth 8 txt:- 2>/dev/null | awk 'NR > 1 { print $2 }' | tr -d '()' | paste -sd ' '; }
  for sh in "$m1 $fa 1440x2560+2560+0" "$m2 $fb 720x1280+4000+0"; do
    read -r x a b <<<"$sh"
    local w h; w=$(turned_cells "$a"); h=$(turned_cells "$f" -crop "$b" +repage)
    check "...$x's shot is its part of the whole shot ($b): 60 cells within 24 of 255" \
      awk -v a="$w" -v b="$h" 'BEGIN { na = split(a, x, "[ ,]"); nb = split(b, y, "[ ,]"); if (na != 180 || nb != 180) exit 1
        for (i = 1; i <= na; i++) { d = x[i] - y[i]; if (d > 24 || d < -24) exit 1 } }'
  done
  # click --in a --monitor shot: the lower terminal on the portrait monitor, below the old 720 px.
  ob pointer -b "$B" -- move 1640 300 >/dev/null
  ob click -b "$B" --in "$fa" 360 960 >/dev/null 2>&1
  check_eq "click --in $m1's shot at 360,960: 1640,960, the lower terminal focused" "1640, 960 L3" \
    "$(ob hyprctl -b "$B" cursorpos) $(ob hyprctl -b "$B" -j activewindow | jq -r .title)"
  ob click -b "$B" --in "$fb" 360 640 >/dev/null 2>&1
  check_eq "click --in $m2's shot at 360,640: its middle, 2180,320, its terminal focused" "2180, 320 L4" \
    "$(ob hyprctl -b "$B" cursorpos) $(ob hyprctl -b "$B" -j activewindow | jq -r .title)"
  # shot --burst through one client (#196, finding 314): the turned layout as grim takes it, whole and
  # a monitor at a time, a -g across them, and a window on the turned scale-2 monitor. (The screen
  # still first: the clicks above moved the focus, and the fade of the windows it left was still
  # ending, a level a pixel, when the binary's burst came: finding 517.)
  ob wait -b "$B" still --timeout 10s >/dev/null 2>&1 || true
  local a args r; for a in "--no-pointer" "--no-pointer|--monitor|$m1" "--no-pointer|--monitor|$m2" "--no-pointer|-g|1000,100 1200x300" "--window|L4" "--window|L4|--fit|300"; do
    IFS='|' read -r -a args <<<"$a"
    r=$(burst_vs_shot "$B" "${args[@]}")
    check "shot --burst ${args[*]}: a frame is the shot's image ($r)" awk '{ exit !($1 == $2 && $3 + 0 <= 50) }' <<<"$r"
  done
  # Four screencast events a session for the whole burst, not four a frame: the window's, and a copy of
  # each monitor that makes it render (a region of a scaled monitor was a session a frame: whole ones).
  sleep 0.8   # (the bursts before: their sessions' last events, 500 ms after their last frames)
  local e0; e0=$(wc -l < "$(ob path -b "$B")/home/events.log")
  ob shot -b "$B" --window L4 --burst 20 --every 0 -o "$TMP/$B-wb" >/dev/null 2>&1
  sleep 0.8   # (Hyprland says a session stopped 500 ms after its last frame.)
  local ne; ne=$(screencast_since "$B" "$e0")
  check "a 20-frame window burst on three monitors: at most 16 screencast events, four a session ($ne)" \
    test "$ne" -gt 0 -a "$ne" -le 16 -a $((ne % 4)) = 0
  ob pointer -b "$B" -- move 1640 1200 >/dev/null
  check_eq "pointer move 1640,1200: low on the portrait monitor" "1640, 1200" "$(ob hyprctl -b "$B" cursorpos)"
  # pixel: yellow low on the portrait monitor, blue low on the other.
  out=$(ob pixel -b "$B" 1640 1100 2200 600 2>&1)
  check "pixel 1640,1100 (yellow) and 2200,600 (blue): read there ($(paste -sd ' ' <<<"$out"))" \
    awk -v s="$out" 'BEGIN { if (split(s, l, "\n") != 2) exit 1
      for (i = 1; i <= 2; i++) { split(l[i], p, " #"); r = strtonum("0x" substr(p[2], 1, 2)); g = strtonum("0x" substr(p[2], 3, 2)); b = strtonum("0x" substr(p[2], 5, 2))
        if (i == 1 && !(r > 200 && g > 200 && b < 80)) exit 1; if (i == 2 && !(r < 80 && g < 80 && b > 200)) exit 1 } }'
  check_match "pixel in the gap below the main screen: not on any monitor, the portrait one 720x1280" \
    "640,1000 is not on any monitor \(.*$m1 1280,0 720x1280, $m2 2000,0 360x640" "$(ob pixel -b "$B" 640 1000 2>&1)"
  ob down "$B" >/dev/null
}
# monitors_on NODE BOX MAIN SECOND THIRD: a box on NODE with two more monitors, by their names there.
monitors_on() {
  local n=$1 B=$2 m0=$3 m1=$4 m2=$5
  check "up --monitor 1080x1920 --monitor 2560x1440,scale=1.6,below" env OMABOX_RENDER_NODE="$n" "$CLI" up "$B" --stock-bar \
    --monitor 1080x1920 --monitor 2560x1440,scale=1.6,below
  local ml; ml=$(ob monitor -b "$B" list --json)
  check_eq "three monitors: modes, scales, positions" \
    "$m0 1920x1080@60 1 0 0|$m1 1080x1920@60 1 1920 0|$m2 2560x1440@60 1.6 1920 1920" \
    "$(jq -r 'map("\(.name) \(.mode) \(.scale) \(.x) \(.y)") | join("|")' <<<"$ml")"
  check_eq "ls --json has them" 3 "$("$CLI" ls --json | jq --arg b "$B" '.[] | select(.name == $b) | .monitors | length')"
  check_match "ls says 3 monitors" "^$B +headless +3 monitors " "$("$CLI" ls | grep "^$B ")"
  check "the shell has a bar on each" until_ok 10 bash -c "[ \"\$('$CLI' hyprctl -b '$B' -j layers | jq -r '[to_entries[] | select([.value.levels[][] | .namespace] | index(\"omarchy-bar\")) | .key] | sort | join(\" \")')\" = '$m0 $m1 $m2' ]"
  # wait layer names the monitor each layer is on, --monitor waits on one (#316, finding 590).
  local L='[0-9]+,[0-9]+ [0-9]+x[0-9]+' out rc
  check_match "wait layer omarchy-bar: one on each monitor, each named" \
    "^satisfied: layer omarchy-bar after [0-9.]+s: 3 layers: at $L on $m0; at $L on $m1; at $L on $m2$" \
    "$(ob wait -b "$B" layer omarchy-bar 2>&1)"
  check_match "...--monitor $m1 --json: that one, its monitor in detail" "^satisfied layer at $L on $m1$" \
    "$(ob wait -b "$B" layer omarchy-bar --monitor "$m1" --json | jq -r '"\(.result) \(.condition) \(.detail)"')"
  out=$(ob wait -b "$B" layer omarchy-bar --monitor HEADLESS-9 --timeout 300ms 2>&1); rc=$?
  check_match "...--monitor of one the box does not have: 124, saying which it has" \
    "^124 unsatisfied: no layer omarchy-bar on HEADLESS-9 after [0-9.]+s \(no monitor HEADLESS-9 in the box \($m0, $m1, $m2\)\)$" "$rc $out"
  check_eq "-b NAME before monitor (#161)" "$ml" "$(ob -b "$B" monitor list --json 2>&1)"
  # A point in the gap below the main screen, left of the others (#161): grim alone failed, and beside
  # a point on a monitor it read black.
  check_match "pixel in a gap between monitors: refused, saying so" "100,1500 is not on any monitor \(.*$m1 1920,0 1080x1920" "$(ob pixel -b "$B" 100 1500 2>&1)"
  check_match "...with a point on a monitor too" "100,1500 is not on any monitor" "$(ob pixel -b "$B" 10 10 100 1500 2>&1)"
  check_match "...a point on the third: its colour" "^#[0-9a-f]{6}$" "$(ob pixel -b "$B" 2000 2000 2>&1)"
  ob pointer -b "$B" -- move 2500 2400 >/dev/null
  check_eq "the pointer onto the third: its workspace is the active one" "$m2" "$(ob hyprctl -b "$B" -j activeworkspace | jq -r .monitor)"
  ob click -b "$B" 2400 900 >/dev/null
  check_eq "a click on the second lands there" "2400, 900" "$(ob hyprctl -b "$B" cursorpos)"
  check_eq "...and its workspace is active" "$m1" "$(ob hyprctl -b "$B" -j activeworkspace | jq -r .monitor)"
  ob shot -b "$B" --monitor "$m1" -o "$TMP/mon3.png" >/dev/null 2>&1
  check_match "shot --monitor $m1: that monitor, 1080x1920" "1080 x 1920" "$(file "$TMP/mon3.png")"
  check_match "...said, for --in" "screen's 1080x1920 at 1920,0|^omabox: .*1920,0" "$(ob shot -b "$B" --monitor "$m1" -o "$TMP/mon3b.png" 2>&1 >/dev/null)"
  check_match "shot --monitor of one it does not have: refused" "has no monitor HEADLESS-9" "$(ob shot -b "$B" --monitor HEADLESS-9 2>&1)"
  reload_landed "$(ob path -b "$B")/home/events.log" ob hyprctl -b "$B" reload
  check_eq "a config reload keeps them" "$(jq -c 'map({name, mode, scale, x, y})' <<<"$ml")" "$(ob monitor -b "$B" list --json | jq -c 'map({name, mode, scale, x, y})')"
  # mode (#161): the ones placed right of (and below) it move with it, out of the larger main screen.
  local out; out=$(ob mode -b "$B" 2560x1440 2>&1 >/dev/null)
  check_eq "mode 2560x1440: the monitor right of it moves, and the one below that" "$m0 0 0|$m1 2560 0|$m2 2560 1920" \
    "$(ob monitor -b "$B" list --json | jq -r 'map("\(.name) \(.x) \(.y)") | join("|")')"
  check_match "...said" "moved the monitors placed next to it: $m1 to 2560,0, $m2 to 2560,1920" "$out"
  ob mode -b "$B" 1920x1080 >/dev/null 2>&1
  check_eq "...and back with mode 1920x1080, every mode as it was" "$(jq -c 'map({name, mode, scale, x, y})' <<<"$ml")" "$(ob monitor -b "$B" list --json | jq -c 'map({name, mode, scale, x, y})')"
  local ev0; ev0=$(ob log -b "$B" events -n all | grep -c monitorremoved)
  check "monitor remove $m1" ob monitor -b "$B" remove "$m1"
  check_eq "...gone from the list; the one placed below it goes below the main screen now" "$m0 0 0|$m2 0 1080" \
    "$(ob monitor -b "$B" list --json | jq -r 'map("\(.name) \(.x) \(.y)") | join("|")')"
  check "...an unplug the box's events saw" until_ok 3 bash -c "[ \$('$CLI' log -b '$B' events -n all | grep -c 'monitorremoved>>$m1') -gt $ev0 ]"
  check_match "...wait layer omarchy-bar --monitor $m1 --gone: its bar went with it, the box's monitors said (#316)" \
    "^satisfied: layer omarchy-bar on $m1 gone after [0-9.]+s: no monitor $m1 in the box \($m0, $m2\)$" \
    "$(ob wait -b "$B" layer omarchy-bar --monitor "$m1" --gone 2>&1)"
  check_eq "monitor add again: the free name" "$m1" "$(ob monitor -b "$B" add 800x600,0,3000 2>/dev/null)"
  check_match "...wait layer omarchy-bar --monitor $m1: the shell put a bar on it (#316)" \
    "^satisfied: layer omarchy-bar on $m1 after [0-9.]+s: at $L on $m1$" \
    "$(ob wait -b "$B" layer omarchy-bar --monitor "$m1" 2>&1)"
  check_eq "...at X,Y" "800x600@60 0 3000" "$(ob monitor -b "$B" list --json | jq -r --arg n "$m1" '.[] | select(.name == $n) | "\(.mode) \(.x) \(.y)"')"
  check_eq "...the others' modes as they were" "$m0 1920x1080@60|$m2 2560x1440@60" \
    "$(ob monitor -b "$B" list --json | jq -r --arg n "$m1" 'map(select(.name != $n) | "\(.name) \(.mode)") | join("|")')"
  check_match "output drop with other monitors: the main screen off, the others on (#161)" \
    "has its main screen \($m0\) off now, ($m2, $m1|$m1, $m2) still on" "$(ob output -b "$B" drop 2>&1)"
  ob output -b "$B" back >/dev/null 2>&1
  check_match "the main screen is not removed" "is the box's main screen" "$(ob monitor -b "$B" remove "$m0" 2>&1)"
  check_match "a monitor it does not have" "has no monitor HEADLESS-9" "$(ob monitor -b "$B" remove HEADLESS-9 2>&1)"
  if [ "$m0" = WAYLAND-1 ]; then
    check_match "NVIDIA: monitor add --name refused, saying why" "WAYLAND-N as its screen is: no --name" "$(ob monitor -b "$B" add 800x600 --name X 2>&1)"
    check_match "...labwc's config has each monitor's window size" "title=\"aquamarine - $m2\"><action name=\"ResizeTo\" width=\"2560\" height=\"1440\"/>" \
      "$(cat "$(ob path "$B")/run/labwc/rc.xml")"
  fi
  # A headless output the program under test makes itself (#213): on NVIDIA it is listed 0x0, and
  # monitor list and shot --monitor say why; elsewhere it takes its mode and nothing is said.
  ob hyprctl -b "$B" output create headless ZTEST >/dev/null
  ob lua -b "$B" 'hl.monitor({ output = "ZTEST", mode = "1280x720@60", position = "0x5000", scale = 1 })' >/dev/null 2>&1
  if [ "$m0" = WAYLAND-1 ]; then
    check "NVIDIA: a headless output of the program's own is listed 0x0" until_ok 5 bash -c \
      "'$CLI' hyprctl -b '$B' -j monitors | jq -e 'any(.[]; .name == \"ZTEST\" and .width == 0)' >/dev/null"
    check_match "...monitor list says why, and where to test it" "ZTEST listed 0x0: this box draws on NVIDIA.*monitor add makes one" "$(ob monitor -b "$B" list 2>&1 >/dev/null)"
    check_match "...shot --monitor of it: the same, not grim's error" "^omabox: shot: ZTEST listed 0x0" "$(ob shot -b "$B" --monitor ZTEST 2>&1)"
  else
    check "elsewhere it takes its mode" until_ok 5 bash -c \
      "'$CLI' hyprctl -b '$B' -j monitors | jq -e 'any(.[]; .name == \"ZTEST\" and .width == 1280 and .height == 720)' >/dev/null"
    check_eq "...and monitor list says nothing of it" "" "$(ob monitor -b "$B" list 2>&1 >/dev/null)"
  fi
  ob hyprctl -b "$B" output remove ZTEST >/dev/null
  check_match "up again without them: already up, said" "is already up, without what you asked for: --monitor" "$(OMABOX_RENDER_NODE=$n ob up "$B" --monitor 800x600 2>&1)"
  ob down "$B" >/dev/null
}

# wait and --wait on a box with more monitors (#162, finding 231): the screen watched is all of them,
# in layout coordinates. One at scale 1.6 holds a cell that never stops changing, a terminal to type
# into is on the third; the same again after the main screen is dropped and back (it is advertised
# last then: the old tool watched the first output advertised, and named its pixels as the screen's).
t_monitors_wait() {
  local n; n=$(gpu_node other)
  [ -n "$n" ] || { skip "monitors wait" "no render node here but NVIDIA's (t_monitors_wait_nvidia runs there)"; return; }
  monitors_wait_on "$n" "$P-monw"
}
# The same on NVIDIA (#165, finding 234): its monitors are windows on the box's labwc.
t_monitors_wait_nvidia() {
  local n; n=$(nvidia_ready) || { skip "monitors wait on NVIDIA" "$n"; return; }
  monitors_wait_on "$n" "$P-monwnv"
}
monitors_wait_on() {
  local n=$1 B=$2 out rc g w when c gx gy gw gh i gn tx ty
  OMABOX_RENDER_NODE="$n" up_ok "$B" --no-shell --net isolated --monitor 1280x720,scale=1.6 \
    --monitor 1080x1920,below || { no "up with two more monitors" "$UP_OUT"; return; }
  check_match "up's line names every monitor, a scale where it is not 1 (#308)" \
    "box '$B' up \(1920x1080@60 \+ 1280x720@60,scale=1.6 \+ 1080x1920@60\) in " "$UP_OUT"
  # (#379, finding 510: up once kept the second at scale 2, read before its rule applied; every check
  # below hangs on the layout, so the box's own word for it first)
  check_eq "...and the box has them so, the third below the second at 1920,450 (#379)" "0,0 1 1920,0 1.6 1920,450 1" \
    "$(ob hyprctl -b "$B" monitors -j | jq -r '[sort_by(.id)[] | "\(.x),\(.y) \(.scale)"] | join(" ")')"
  ob pointer -b "$B" -- move 2300 200 >/dev/null
  ob run -b "$B" -d -q -- foot -T N sh -c 'i=0; while :; do printf "\r%s" $((i++ % 10)); sleep 0.05; done'
  ob wait -b "$B" window 'title:^N$' >/dev/null
  w=$(ob windows -b "$B" --json | jq -r '.[] | select(.title == "N") | "\(.at[0]) \(.at[1]) \(.at[0] + .size[0]) \(.at[1] + .size[1])"')
  for when in "" " (after output drop and back)"; do
    # Until the window has settled (its border's colour, its first frames) the change named is more than
    # the cell: under load a full run once read the window's border too (#200). Looked at again until it
    # is the cell, 3 times at most.
    for i in 1 2 3; do
      out=$(ob wait -b "$B" still --timeout 2s); rc=$?
      g=$(sed -n 's/.*--ignore "\([^"]*\)".*/\1/p' <<<"$out")
      [ "$rc" != 124 ] || ! cell_in "$g" "$w" || break
      [ "$i" = 3 ] || note "wait still named $g (rc $rc): the window not settled yet, looked again"
    done
    check_eq "a cell changing on the second monitor: wait still 124$when" 124 "$rc"
    check "...named as an --ignore in the layout, a cell inside its window ($g in $w)$when" cell_in "$g" "$w"
    check_eq "...--ignore it: still$when" 0 "$(ob wait -b "$B" still --ignore "$g" >/dev/null; echo $?)"
    # (#287, F8: beside --window, --ignore is the window's own; the 124 names it so)
    out=$(ob wait -b "$B" still --window 'title:^N$' --timeout 1500ms); rc=$?
    gn=$(sed -n 's/.*(the window.s \([^)]*\)): --ignore "\([^"]*\)".*/\2/p' <<<"$out")
    read -r gx gy gw gh <<<"${g//[,x]/ }"
    check_eq "...--window on it: 124, naming the --ignore in the window's coordinates$when" \
      "124 $((gx - ${w%% *})),$((gy - $(cut -d' ' -f2 <<<"$w"))) ${gw}x${gh}" "$rc $gn"
    check_eq "...still with that --ignore$when" 0 "$(ob wait -b "$B" still --window 'title:^N$' --ignore "$gn" >/dev/null; echo $?)"
    # One digit to the next, inside $g (all the digits over 2 s): a narrow pair is a pixel narrower.
    out=$(ob wait -b "$B" change -g "1920,0 800x450" --json)
    c=$(jq -r '"\(.result) \(.change.x),\(.change.y) \(.change.w)x\(.change.h)"' <<<"$out")
    read -r gx gy gw gh <<<"${g//[,x]/ }"
    check "...wait change -g on that monitor: changed there, in $g ($c)$when" \
      cell_in "${c#satisfied }" "$gx $gy $((gx + gw)) $((gy + gh))"
    check_eq "...-g on the main screen only: still$when" 0 "$(ob wait -b "$B" still -g "0,0 1920x1080" >/dev/null; echo $?)"
    check_eq "...-g across the main screen and that one: 124$when" 124 "$(ob wait -b "$B" still -g "1800,0 300x300" --timeout 1s >/dev/null; echo $?)"
    if [ -z "$when" ]; then
      ob pointer -b "$B" -- move 2400 1500 >/dev/null
      check_eq "run -d --wait of a window on the third monitor: settled" 0 \
        "$(ob run -b "$B" -d --wait --ignore "$g" -- foot -T T sh -c 'cat > /tmp/typed' >/dev/null 2>&1; echo $?)"
    fi
    # Beside --window T, --wait's --ignore and -g are T's own coordinates (F8): N's cell and the
    # third monitor, moved by T's place.
    read -r tx ty < <(ob windows -b "$B" --json | jq -r '.[] | select(.title == "T") | "\(.at[0]) \(.at[1])"')
    out=$(ob keys -b "$B" --window 'title:^T$' --wait --ignore "$((gx - tx)),$((gy - ty)) ${gw}x${gh}" -t x); rc=$?
    check_eq "keys --wait into a window on the third monitor: settled$when" 0 "$rc"
    check_match "...on a change there (from 1920,450)$when" "last change .* at (19[2-9][0-9]|2[0-9]{3}),(4[5-9][0-9]|[5-9][0-9]{2}|[0-9]{4}) " "$out"
    check_eq "...with -g on that monitor: settled$when" 0 \
      "$(ob keys -b "$B" --window 'title:^T$' --wait -g "$((1920 - tx)),$((450 - ty)) 1080x1920" -t y >/dev/null; echo $?)"
    [ -n "$when" ] || ob output -b "$B" drop --for 500ms >/dev/null
  done
  ob keys -b "$B" --window 'title:^T$' Return >/dev/null
  check "what was typed reached it" until_ok 5 bash -c "[ \"\$('$CLI' run -b '$B' -- cat /tmp/typed)\" = xyxy ]"
  check_match "wait --window --ignore outside the window: said, in its own coordinates" \
    "--ignore \"5000,10 8x11\" is outside window .* \([0-9]+x[0-9]+, in its own coordinates\): it leaves nothing out" \
    "$(ob wait -b "$B" still --window 'title:^N$' --ignore "5000,10 8x11" --timeout 500ms 2>&1 >/dev/null)"
  check_eq "...one inside it (its own 10,10): nothing said" "" \
    "$(ob wait -b "$B" still --window 'title:^N$' --ignore "10,10 8x11" --timeout 500ms 2>&1 >/dev/null)"
  ob down "$B" >/dev/null
}
# cell_in "X,Y WxH" "X0 Y0 X1 Y1": the rectangle is inside, and the size of a terminal cell.
cell_in() {
  [[ $1 =~ ^([0-9]+),([0-9]+)\ ([0-9]+)x([0-9]+)$ ]] || return 1
  local x=${BASH_REMATCH[1]} y=${BASH_REMATCH[2]} cw=${BASH_REMATCH[3]} ch=${BASH_REMATCH[4]} x0 y0 x1 y1
  read -r x0 y0 x1 y1 <<<"$2"
  [ "$x" -ge "$x0" ] && [ "$y" -ge "$y0" ] && [ $((x + cw)) -le "$x1" ] && [ $((y + ch)) -le "$y1" ] && [ "$cw" -le 20 ] && [ "$ch" -le 30 ]
}

# An interactive box's monitors (#123), each a window on the "desktop": all in a box standing in for
# the host (finding 26), with a terminal focused on its workspace 1 and the box on 9.
t_monitors_window() {
  # The stand-in at the size of the screen #174 was found on (3440x1440, scale 1).
  local S=$P-monh
  up_ok "$S" --size 3440x1440 --no-shell --net isolated || { no "up the stand-in" "$UP_OUT"; return; }
  local in=("$CLI" run -b "$S" -- "${GUARDED[@]}" "$CLI")
  if aq_unfixed "${in[@]}"; then skip "monitors as windows" "the stand-in's aquamarine lacks the fix"; ob down "$S" >/dev/null; return; fi
  # (finding 429: a monitor's window needs a class of its own, which only omabox's build gives)
  if ! "${in[@]}" --version 2>/dev/null | grep -q '^aquamarine: a private build, .*+appid'; then
    skip "monitors as windows" "not omabox's aquamarine build with +appid (omabox setup --aquamarine)"; ob down "$S" >/dev/null; return
  fi
  ob run -b "$S" -d -- foot >/dev/null 2>&1
  ob wait -b "$S" window foot >/dev/null 2>&1
  local out
  out=$("${in[@]}" up wm --interactive --no-shell --monitor 1080x1920 --monitor 1280x720,below 2>&1)
  check_match "up --interactive --monitor 1080x1920 --monitor 1280x720,below in the stand-in (#174's)" "box 'wm' up" "$out"
  check_match "...the windows: the layout at 53% of its size, said" "its layout at 53% of its size" "$out"
  # shellcheck disable=SC2329 # called through until_ok
  mons() { [ "$("${in[@]}" monitor -b wm list --json | jq -r "$1")" = "$2" ]; }
  # shellcheck disable=SC2329 # called through check
  boxwins() { ob hyprctl -b "$S" -j clients | jq -c '[.[] | select(.class | startswith("aquamarine")) | {ws: .workspace.name, floating, at, size}] | sort_by(.at)'; }
  # How many pairs of the box's windows on the stand-in overlap.
  # shellcheck disable=SC2329 # called through check
  overlaps() { ob hyprctl -b "$S" -j clients | jq '[.[] | select(.class | startswith("aquamarine"))] as $w | [range(0; $w | length) as $i | range($i + 1; $w | length) as $j
    | select($w[$i].at[0] < $w[$j].at[0] + $w[$j].size[0] and $w[$j].at[0] < $w[$i].at[0] + $w[$i].size[0]
      and $w[$i].at[1] < $w[$j].at[1] + $w[$j].size[1] and $w[$j].at[1] < $w[$i].at[1] + $w[$i].size[1])] | length'; }
  # Each monitor's mode, scale, its size in the layout (the mode over the scale) and place.
  # shellcheck disable=SC2329 # called through check_eq
  layout() { "${in[@]}" monitor -b wm list --json | jq -r 'map(. as $m | ($m.mode | split("@")[0] | split("x") | map(tonumber)) as $p
    | "\($m.name) \($m.mode) \($m.scale) \($p[0] / $m.scale | round)x\($p[1] / $m.scale | round) \($m.x),\($m.y)") | join("|")'; }
  # The box's layout scaled as a whole (#174): 1920x1080 at 0,0, 1080x1920 right of it, 1280x720
  # below that, at 63/120 (each window whole pixels), with the stand-in's gap (10 + border 2) between
  # windows that touch in the box, the picture centred in the free area.
  check_eq "its windows: on workspace 9, floating, the box's layout scaled to 0.525 and centred" \
    '[{"ws":"9","floating":true,"at":[874,21],"size":[1008,567]},{"ws":"9","floating":true,"at":[1894,21],"size":[567,1008]},{"ws":"9","floating":true,"at":[1894,1041],"size":[672,378]}]' "$(boxwins)"
  check_eq "...none over another" 0 "$(overlaps)"
  check_eq "...the stand-in's focus and workspace unchanged" "foot 1" "$(ob hyprctl -b "$S" -j activewindow | jq -r .class) $(ob hyprctl -b "$S" -j activeworkspace | jq -r .id)"
  check_eq "...each monitor a view: its window's pixels at 0.525, so the size asked for, placed as asked" \
    "WAYLAND-1 1008x567@60 0.525 1920x1080 0,0|WAYLAND-2 567x1008@60 0.525 1080x1920 1920,0|WAYLAND-3 672x378@60 0.525 1280x720 1920,1920" "$(layout)"
  # (finding 429: each monitor's window a class of its own, for a rule of its own; the main one aquamarine)
  check_eq "...each monitor's window a class of its own, the main one aquamarine (finding 429)" "1 2" \
    "$(ob hyprctl -b "$S" -j clients | jq -r '"\(map(select(.class == "aquamarine")) | length) \(map(.initialClass | select(test("^aquamarine-omabox-[0-9a-f]{16}$"))) | unique | length)"')"
  local wmrun; wmrun=$(ob run -b "$S" -- ls "$("${in[@]}" path wm)/run" 2>/dev/null) || wmrun=""
  check_eq "...their class tokens gone from the box's runtime dir" "" "$(grep '^omabox\.appid\.' <<<"$wmrun")"
  check_eq "...its mark that its Hyprland was given AQ_WAYLAND_APP_ID_FILES there (start-hyprland.sh)" omabox.appid-files "$(grep -x 'omabox\.appid-files' <<<"$wmrun")"
  # The layout file the box's Lua writes for its aquamarine (finding 238; #200) against `monitors`:
  # each monitor's place and its size in the layout (its pixels over its scale, the sides swapped by a
  # 90/270 transform), rounded.
  local wmd; wmd=$("${in[@]}" path wm)
  # shellcheck disable=SC2329 # called through until_ok and check
  layout_file() { ob run -b "$S" -- cat "$wmd/run/omabox.layout" | paste -sd'|'; }
  # shellcheck disable=SC2329
  file_matches() { local f w; f=$(layout_file) w=$("${in[@]}" hyprctl -b wm -j monitors | jq -r 'map((.width / .scale | round) as $w
    | (.height / .scale | round) as $h | "\(.name) \(.x) \(.y) \(if .transform % 2 == 1 then "\($h) \($w)" else "\($w) \($h)" end)") | join("|")')
    echo "$f"; [ -n "$f" ] && [ "$f" = "$w" ]; }
  # shellcheck disable=SC2329
  file_is() { [ "$(layout_file)" = "$1" ]; }
  local rows="WAYLAND-1 0 0 1920 1080|WAYLAND-2 1920 0 1080 1920|WAYLAND-3 1920 1920 1280 720"
  check "its layout file: the three views, as placed" until_ok 3 file_is "$rows"
  check "...as \`monitors\` has them" file_matches
  # WAYLAND-2 at a scale that gives no whole size (1069.81x1901.89), WAYLAND-3 turned 90 degrees and
  # auto-placed right of it (at 1920 + 1069.81; Hyprland 0.56.2 hands Lua whole positions).
  "${in[@]}" hyprctl -b wm eval "hl.monitor({ output = 'WAYLAND-2', mode = 'preferred', position = '1920x0', scale = 0.53 })" >/dev/null 2>&1
  "${in[@]}" hyprctl -b wm eval "hl.monitor({ output = 'WAYLAND-3', mode = 'preferred', position = 'auto-right', scale = 0.525, transform = 1 })" >/dev/null 2>&1
  check "...written anew at a layout change: a size rounded, a turned one's sides swapped, a place after a fraction" \
    until_ok 3 file_is "WAYLAND-1 0 0 1920 1080|WAYLAND-2 1920 0 1070 1902|WAYLAND-3 2990 0 720 1280"
  check "...as \`monitors\` has them" file_matches
  "${in[@]}" hyprctl -b wm eval "hl.monitor({ output = 'WAYLAND-3', mode = 'preferred', position = '1920x1920', scale = 0.525, transform = 0 })" >/dev/null 2>&1
  "${in[@]}" hyprctl -b wm eval "omabox_place_monitors()" >/dev/null 2>&1
  check "...placed again as before (the rest of this test lays out by it)" until_ok 3 file_is "$rows"
  # The stand-in's pointer in each window, at its middle (on workspace 9 now, where the windows are):
  # the box's pointer in the middle of that monitor. aquamarine reports a point of the window; Hyprland
  # 0.56 placed it over the whole layout, so every middle was (1600, 1079); omabox's build places it.
  ob hyprctl -b "$S" dispatch "hl.dsp.focus({ workspace = '9' })" >/dev/null
  if ob --version 2>/dev/null | grep -q '^aquamarine: a private build, .*+layout'; then
    local at="" shown="" x y
    # Each window, then back to the first two: a window entered again is where the cursor went (a
    # first visit gets a cursor set a frame later, which showed it again).
    for p in "1378 304" "2177 525" "2230 1230" "2177 525" "1378 304"; do
      # shellcheck disable=SC2086 # X Y
      ob pointer -b "$S" -- move $p >/dev/null 2>&1
      sleep 0.4
      at+="$("${in[@]}" hyprctl -b wm cursorpos 2>/dev/null)|"
      # The stand-in's cursor there (its headless screen draws it into its frames): more than the
      # box's plain background in a crop at the pointer.
      read -r x y <<<"$p"
      ob shot -b "$S" -g "$((x - 4)),$((y - 4)) 24x24" -o "$TMP/monh-cursor.png" >/dev/null 2>&1
      shown+="$(magick "$TMP/monh-cursor.png" -unique-colors -format %w info: 2>/dev/null || echo 0) "
    done
    # Each within a pixel of the middle (the window's pixel rounds).
    check_eq "the pointer in a monitor's window: on that monitor, where it is in the window (finding 238; $at)" ok \
      "$(awk -F'|' '{ split("960 540 2460 960 2560 2280", w, " "); bad = 0
        for (i = 1; i <= 3; i++) { split($i, p, ", "); if ((p[1] - w[2 * i - 1]) ^ 2 > 1 || (p[2] - w[2 * i]) ^ 2 > 1) bad = 1 }
        print bad ? "off" : "ok" }' <<<"$at")"
    # Crossing into another monitor's window hid the cursor: aquamarine hid it for the window the
    # pointer had left with a set_cursor the stand-in took for the one it entered (#175, finding 239).
    if ob --version 2>/dev/null | grep -q '^aquamarine: a private build, .*+cursor'; then
      check_eq "...and the cursor shown in each window, crossing from one to another and back (finding 239; colours at it: $shown)" ok \
        "$(awk '{ for (i = 1; i <= 5; i++) if ($i < 2) { print "hidden"; exit } print "ok" }' <<<"$shown")"
    else
      skip "the cursor shown after crossing monitor windows" "not omabox's aquamarine build with +cursor (omabox setup --aquamarine)"
    fi
  else
    skip "the pointer in a monitor's window lands on that monitor" "not omabox's aquamarine build (omabox setup --aquamarine)"
  fi
  ob hyprctl -b "$S" dispatch "hl.dsp.focus({ workspace = '1' })" >/dev/null
  out=$("${in[@]}" monitor -b wm add 800x600,0,1080 2>&1)
  check_match "monitor add 800x600,0,1080: a view too" "a monitor WAYLAND-4 420x315@60 0x1080 0.525" "$out"
  check_eq "...the picture laid out again with it, below the main window as in the box" \
    '[{"ws":"9","floating":true,"at":[874,15],"size":[1008,567]},{"ws":"9","floating":true,"at":[874,594],"size":[420,315]},{"ws":"9","floating":true,"at":[1894,15],"size":[567,1008]},{"ws":"9","floating":true,"at":[1894,1047],"size":[672,378]}]' "$(boxwins)"
  check_eq "...none over another" 0 "$(overlaps)"
  "${in[@]}" up wm2 --interactive --no-shell >/dev/null 2>&1
  check_eq "a box started after: its window is not taken for a monitor (tiled)" 1 \
    "$(ob hyprctl -b "$S" -j clients | jq '[.[] | select(.class == "aquamarine" and .floating == false)] | length')"
  "${in[@]}" down wm2 >/dev/null 2>&1
  out=$("${in[@]}" monitor -b wm remove WAYLAND-3 2>&1)
  check_match "monitor remove WAYLAND-3: the picture laid out again without it" "its layout at 73% of its size" "$out"
  check_eq "...bigger now" '[{"ws":"9","floating":true,"at":[626,24],"size":[1392,783]},{"ws":"9","floating":true,"at":[626,819],"size":[580,435]},{"ws":"9","floating":true,"at":[2030,24],"size":[783,1392]}]' "$(boxwins)"
  check "...the views at 0.725, the sizes as asked" until_ok 3 mons 'map("\(.name) \(.mode) \(.scale)") | join("|")' \
    "WAYLAND-1 1392x783@60 0.725|WAYLAND-2 783x1392@60 0.725|WAYLAND-4 580x435@60 0.725"
  check_eq "...the stand-in's focus and workspace unchanged" "foot 1" "$(ob hyprctl -b "$S" -j activewindow | jq -r .class) $(ob hyprctl -b "$S" -j activeworkspace | jq -r .id)"
  # A window the user resizes: its view's scale follows, the monitor keeps its size and place; a
  # window of another shape shows the monitor smaller along the side that does not fit.
  local a; a=$(ob hyprctl -b "$S" -j clients | jq -r '.[] | select((.class | startswith("aquamarine")) and .size == [783, 1392]) | .address')
  ob hyprctl -b "$S" dispatch "hl.dsp.window.resize({ window = 'address:$a', x = 810, y = 1440 })" >/dev/null
  check "resizing a monitor's window to 810x1440: its view at 0.75, the monitor still 1080x1920 at 1920,0" until_ok 3 mons \
    '.[] | select(.name == "WAYLAND-2") | "\(.mode) \(.scale) \(.x),\(.y)"' "810x1440@60 0.75 1920,0"
  ob hyprctl -b "$S" dispatch "hl.dsp.window.resize({ window = 'address:$a', x = 700, y = 700 })" >/dev/null
  check "...to 700x700: at 0.64815, the monitor 1080x1080" until_ok 3 mons '.[] | select(.name == "WAYLAND-2") | "\(.mode) \(.scale)"' "700x700@60 0.64815"
  check_eq "...its size in the layout" "1080x1080" "$(layout | tr '|' '\n' | awk '$1 == "WAYLAND-2" { print $4 }')"
  reload_landed "$(ob path -b "$S")/home/.cache/omabox/wm/home/events.log" "${in[@]}" hyprctl -b wm reload
  check_eq "a config reload keeps its monitors and views" "WAYLAND-1 0.725 WAYLAND-2 0.64815 WAYLAND-4 0.725" \
    "$("${in[@]}" monitor -b wm list --json | jq -r 'map("\(.name) \(.scale)") | join(" ")')"
  ob hyprctl -b "$S" dispatch "hl.dsp.window.close({ window = 'address:$a' })" >/dev/null
  check "closing a monitor's window: that monitor goes" until_ok 3 mons 'map(.name) | join(" ")' "WAYLAND-1 WAYLAND-4"
  check_match "...the box stays up" " up " "$("${in[@]}" ls | grep '^wm ')"
  "${in[@]}" monitor -b wm remove WAYLAND-4 >/dev/null 2>&1
  # (read at once: the remove waits for the screens' new scales, #382, finding 519; bash's does not)
  check_eq "...the main screen at scale 1 as the remove returns" 1 "$("${in[@]}" monitor -b wm list --json | jq -r '.[] | select(.name == "WAYLAND-1") | .scale')"
  check_eq "removing the last monitor: the main window tiles again, filling the workspace" '[{"ws":"9","floating":false,"at":[12,12],"size":[3416,1416]}]' "$(boxwins)"
  check "...its screen its window's size again, at scale 1" until_ok 3 mons 'map("\(.name) \(.mode) \(.scale)") | join("|")' "WAYLAND-1 3416x1416@60 1"
  # (its table too, the main screen alone: add, remove and list --json are checked above; #324, what
  # wave 4a compared with bash's)
  check_match "monitor list, interactive: its table, the main screen alone" "^NAME +MODE +SCALE +POSITION +WORKSPACE"$'\n'"WAYLAND-1 +3416x1416@60 +1 +0,0 " \
    "$("${in[@]}" monitor -b wm list 2>&1)"
  "${in[@]}" monitor -b wm add 800x600 >/dev/null 2>&1
  local main; main=$(ob hyprctl -b "$S" -j clients | jq -r '.[] | select(.class == "aquamarine" and .floating and .size[0] > 1000) | .address')
  ob hyprctl -b "$S" dispatch "hl.dsp.window.close({ window = 'address:$main' })" >/dev/null
  check "closing its first window with another open: it stays up on that one" until_ok 3 mons 'map(.name) | join(" ")' "WAYLAND-2"
  check_match "...up" " up " "$("${in[@]}" ls | grep '^wm ')"
  # Two adds at once on one box (its lock: one after the other) and one on another box meanwhile
  # (finding 429): each window by its class, with a rule of its own, on 9, floating; the stand-in's
  # focus and workspace unchanged.
  "${in[@]}" down wm >/dev/null 2>&1
  "${in[@]}" up wa --interactive --no-shell >/dev/null 2>&1; "${in[@]}" up wb --interactive --no-shell >/dev/null 2>&1
  local f0; f0=$(ob hyprctl -b "$S" -j activewindow | jq -r '"\(.address) \(.workspace.name)"')
  "${in[@]}" monitor -b wa add 640x480 > "$TMP/monh-two.1" 2>&1 & local j1=$!
  "${in[@]}" monitor -b wa add 640x480 > "$TMP/monh-two.2" 2>&1 & local j2=$!
  "${in[@]}" monitor -b wb add 640x480 > "$TMP/monh-two.3" 2>&1; wait "$j1" "$j2"
  check_eq "two adds at once on one box, one on another: each its own monitor" "WAYLAND-2 WAYLAND-3|WAYLAND-2" \
    "$(tail -qn1 "$TMP/monh-two.1" "$TMP/monh-two.2" | sort | paste -sd' ')|$(tail -n1 "$TMP/monh-two.3")"
  check_eq "...three windows, each a class of its own, on 9, floating" "3 3 9 true" \
    "$(ob hyprctl -b "$S" -j clients | jq -r '[.[] | select(.class | startswith("aquamarine-omabox-"))] | "\(length) \(map(.initialClass) | unique | length) \(map(.workspace.name) | unique | join(",")) \(map(.floating) | unique | map(tostring) | join(","))"')"
  check_eq "...the stand-in's focus and workspace unchanged" "$f0" "$(ob hyprctl -b "$S" -j activewindow | jq -r '"\(.address) \(.workspace.name)"')"
  "${in[@]}" down --all >/dev/null 2>&1
  ob down "$S" >/dev/null
}

# The agent guard (finding 65): the fake display agents' shells get, and omabox still finding the
# user's session from such a shell. Sessions are faked in a runtime dir of our own where it matters.
GUARDED=(env WAYLAND_DISPLAY=omabox-guard HYPRLAND_INSTANCE_SIGNATURE=omabox-guard DISPLAY= QT_QPA_PLATFORMTHEME= QT_FORCE_STDERR_LOGGING=1
  BROWSER="$ROOT/share/guard/xdg-open" GH_BROWSER="$ROOT/share/guard/xdg-open" PATH="$ROOT/share/guard:$PATH")
t_unit_host_session() {
  # On a stand-in session (#372), never the user's desktop.
  local hrt=$TMP/hs-host STANDIN_PID found; stand_in_host "$hrt" a_8_8
  local hg=("${GUARDED[@]}" XDG_RUNTIME_DIR="$hrt")
  check_fails "hyprctl under the guard fails" "${hg[@]}" hyprctl -j version
  found=$("${hg[@]}" "$PROBE" _rust probe host_session)
  check_eq "under the guard omabox finds the live session" "a_8_8 $hrt/wayland-sti" "$found"
  check_match "...which hyprctl reaches under its signature" '"tag": "stand-in"' \
    "$(XDG_RUNTIME_DIR=$hrt HYPRLAND_INSTANCE_SIGNATURE=${found%% *} hyprctl -j version)"
  check_eq "and reaches it (read-only hyprctl -j monitors, --size host's): its focused monitor" "$STANDIN_MODE" \
    "$("${hg[@]}" "$PROBE" _rust probe parse_mode host)"
  check_eq "--size host under the guard is the same monitor" "$(XDG_RUNTIME_DIR=$hrt probe parse_mode host)" "$("${hg[@]}" "$PROBE" _rust probe parse_mode host)"
  check "...the stand-in heard monitors asked" grep -qx j/monitors "$hrt/requests.log"
  kill "$STANDIN_PID" 2>/dev/null; wait "$STANDIN_PID" 2>/dev/null || true
  local rt=$TMP/rt n
  fake() { mkdir -p "$rt/hypr/$1"; printf '%s\n%s\n' $$ "$2" > "$rt/hypr/$1/hyprland.lock"; }
  sock() { python3 -c 'import socket,sys; socket.socket(socket.AF_UNIX).bind(sys.argv[1])' "$1"; }
  hs() { XDG_RUNTIME_DIR=$rt "$@" "$PROBE" _rust probe host_session 2>&1; }
  mkdir -p "$rt"
  check_match "no session: says so" "no Hyprland session" "$(hs "${GUARDED[@]}")"
  fake a_1_1 wayland-8
  check_match "a session without its Wayland socket: says so" "no Wayland socket" "$(hs "${GUARDED[@]}")"
  sock "$rt/wayland-8"
  check_eq "the only session and its socket" "a_1_1 $rt/wayland-8" "$(hs "${GUARDED[@]}")"
  fake b_2_2 wayland-9; sock "$rt/wayland-9"
  check_match "several sessions, none named: refused" "several Hyprland sessions" "$(hs "${GUARDED[@]}")"
  sock "$rt/hypr/b_2_2/.socket.sock"
  check_eq "several, the environment names a live one: that one" "b_2_2 $rt/wayland-9" "$(hs env HYPRLAND_INSTANCE_SIGNATURE=b_2_2)"
  n=$(hs env HYPRLAND_INSTANCE_SIGNATURE=gone_3_3)
  check_match "several, the environment names a dead one: refused" "several Hyprland sessions" "$n"
  mkdir -p "$rt/hypr/stale_4_4"; sock "$rt/hypr/stale_4_4/.socket.sock"
  check_match "...a crashed one whose socket file stayed: not taken (finding 74)" "several Hyprland sessions" "$(hs env HYPRLAND_INSTANCE_SIGNATURE=stale_4_4)"
  check_eq "...nor a HOST_SIG from the caller" "b_2_2 $rt/wayland-9" "$(hs env HYPRLAND_INSTANCE_SIGNATURE=b_2_2 HOST_SIG=x)"
}

# `omabox guard` edits Claude Code's settings.json: merged, never overwritten, reversible, a backup
# per change, a link stays a link, a file that is not JSON is left alone.
t_unit_guard_settings() {
  local h=$TMP/gh s out
  mkdir -p "$h/.claude"; s=$h/.claude/settings.json
  g() { HOME=$h "$CLI" guard "$@" 2>&1; }
  # #152: Codex's config is read with the system's python, not PATH's (Omarchy's mise puts its shims
  # first, and one can fail: an untrusted config once the XDG dirs change).
  local ph=$TMP/gh-py; mkdir -p "$ph/.codex" "$TMP/badpy"
  printf '#!/bin/sh\necho "mise ERROR stub" >&2\nexit 1\n' > "$TMP/badpy/python3"; chmod +x "$TMP/badpy/python3"
  check_match "Codex's state with a failing python3 first on PATH (#152)" "^Codex \(.*\): off$" \
    "$(HOME=$ph PATH="$TMP/badpy:$PATH" "$CLI" guard 2>&1 | grep -i '^codex')"
  check_match "no file: off, and shows what on does" "off.*omabox guard on" "$(g | tr '\n' ' ')"
  g on >/dev/null
  check_eq "on creates it with our hook" 1 "$(jq '[.hooks.SessionStart[].hooks[] | select(.command | contains("omabox-guard"))] | length' "$s")"
  check_match "the state reads on" ": on$" "$(g | head -1)"
  jq -n '{model: "x", hooks: {SessionStart: [{matcher: "*", hooks: [{type: "command", command: "mine.sh"}]}], Stop: [{hooks: [{type: "command", command: "stop.sh"}]}]}, theme: "dark"}' > "$s"
  chmod 600 "$s"; local orig; orig=$(cat "$s")
  rm -f "$s".bak-*
  g on >/dev/null
  check_eq "on keeps everything else" "$(jq -S 'del(.hooks.SessionStart[1])' <<<"$orig")" "$(jq -S 'del(.hooks.SessionStart[1])' "$s")"
  check_eq "...and backs up the old file" "$orig" "$(cat "$s".bak-*)"
  check_eq "...keeping its mode" 600 "$(stat -c %a "$s")"
  check_match "on again: nothing to do" "already on" "$(g on)"
  check_eq "...and no second backup" 1 "$(compgen -G "$s.bak-*" | wc -l)"
  : > "$s.bak-1.000000001"; : > "$s.bak-2.000000002"
  check_match "on again with an older version's backups: they go (#398)" "already on.*2 older backup" "$(g on)"
  check_eq "...keeping the newest" "1|$orig" "$(compgen -G "$s.bak-*" | wc -l)|$(cat "$s".bak-*)"
  : > "$s.bak-mine"
  g off >/dev/null
  check_eq "off gives back the same file" "$orig" "$(cat "$s")"
  check_eq "...keeping one backup of ours and the user's own (#398)" "1 yes" \
    "$(compgen -G "$s.bak-[0-9]*" | wc -l) $([ -e "$s.bak-mine" ] && echo yes)"
  rm -f "$s.bak-mine"
  jq '.hooks.SessionStart += [{hooks: [{type: "command", command: "echo old omabox-guard"}]}]' <<<"$orig" > "$s"
  check_match "an older hook of ours reads outdated" "outdated" "$(g | head -1)"
  jq --arg c 'echo x omabox-guard PATH="/nonexistent/co/share/guard:$PATH"' '.hooks.SessionStart[-1].hooks[0].command = $c' "$s" > "$s.new" && mv "$s.new" "$s"
  check_match "...and one from a checkout that is gone says so (finding 92)" "outdated: its /nonexistent/co/share/guard is gone" "$(g | head -1)"
  g on >/dev/null
  check_eq "on replaces it" 1 "$(jq '[.hooks.SessionStart[].hooks[] | select(.command | contains("omabox-guard"))] | length' "$s")"
  mv "$s" "$h/real.json"; ln -s "$h/real.json" "$s"
  g off >/dev/null
  check "a linked settings file stays a link" test -L "$s"
  check_eq "...and its target changes" "$orig" "$(cat "$h/real.json")"
  rm "$s"; echo '{"broken":' > "$s"; rm -f "$s".bak-*
  out=$(g on); local rc=$?
  check_match "a file that is not JSON is refused" "not a JSON object" "$out"
  check_eq "...with a failure" 1 "$rc"
  check_eq "...and left alone" '{"broken":' "$(cat "$s")"
  check_fails "...with no backup" compgen -G "$s.bak-*"
  mkdir -p "$h/alt"
  CLAUDE_CONFIG_DIR=$h/alt HOME=$h "$CLI" guard on >/dev/null 2>&1
  check "CLAUDE_CONFIG_DIR is honoured" jq -e '.hooks.SessionStart' "$h/alt/settings.json"
  # The hooks of an omabox at $co (a copy of the CLI, as a checkout or package would have it), as its
  # `guard on` writes them in a HOME of their own (#324 wave 6-suite, D5: they were bin/omabox's
  # GUARD_* sourced): Claude Code's, Codex's, and Codex's config block.
  local co=$TMP/guard-co hook chook f=$TMP/envfile
  mkdir -p "$co/bin" "$co/share/guard"
  mkdir -p "$co/build"; cp -L "$CLI" "$co/build/omabox"; ln -s ../build/omabox "$co/bin/omabox"
  # gh_hooks: the three texts, a line between the last two, after `guard on` and `guard on codex`.
  gh_hooks() {
    local hh; hh=$(mktemp -d "$TMP/gh.XXXX")
    HOME=$hh "$co/bin/omabox" guard on >/dev/null 2>&1; HOME=$hh "$co/bin/omabox" guard on codex >/dev/null 2>&1
    local q='.hooks.SessionStart[].hooks[] | select(.command | contains("omabox-guard")) | .command'
    jq -r "$q" "$hh/.claude/settings.json"; printf '\0'
    jq -r "$q" "$hh/.codex/hooks.json"; printf '\0'
    sed -n '/^# >>> omabox guard/,/^# <<< omabox guard/p' "$hh/.codex/config.toml"
  }
  local -a gh
  # Finding 346: share/guard/hook-version is a hash of what `guard on` writes for each agent, its
  # path and stamps left out (here: a copy with no stamps, its ROOT made a placeholder), so a change to
  # the hook that does not bump it fails here.
  mapfile -d '' -t gh < <(gh_hooks)
  local stamps; stamps=$(for t in "${gh[0]%$'\n'}" "${gh[1]%$'\n'}"$'\n'"${gh[2]%$'\n'}"; do printf %s "${t//"$co"/@ROOT@}" | sha256sum | cut -c1-12; done | paste -sd' ')
  check_match "...the hooks read from what guard on wrote" "^if .*omabox-guard.*# >>> omabox guard.*# <<< omabox guard$" "$(printf %s "${gh[*]}" | tr '\n' ' ' | sed 's/ $//')"
  check_eq "share/guard/hook-version is the hash of what guard on writes (changed the hook? write [$stamps] there)" \
    "$stamps" "$(cat "$ROOT/share/guard/hook-version")"
  # (writable, as the stamps below are written over it: --installed's tree is read-only, and cp kept
  # its 444, so the "outdated" cases read the real stamps, #381)
  install -m 644 "$ROOT/share/guard/hook-version" "$co/share/guard/"
  mapfile -d '' -t gh < <(gh_hooks)
  hook=${gh[0]%$'\n'} chook=${gh[1]%$'\n'}
  check_eq "the hooks carry the stamps" 2 "$(grep -cF -e "= '${stamps% *}' ]" -e "= '${stamps#* }' ]" <<<"$hook
$chook")"
  local stale='omabox guard: this hook is outdated \(omabox changed it\): tell the user to run omabox guard on to renew it$'
  check_eq "a current stamp: the hook's note alone" "1 1" "$(CLAUDE_ENV_FILE=$f sh -c "$hook" | wc -l) $(sh -c "$chook" | wc -l)"
  echo "0123456789ab ba9876543210" > "$co/share/guard/hook-version"
  check_match "an upgrade that changed the hook: it says it is outdated, after the note" "omabox host -- CMD"$'\n'"$stale" \
    "$(CLAUDE_ENV_FILE=$f sh -c "$hook")"
  check_match "...when it cannot apply the guard too" "NOT applied.*"$'\n'"$stale" "$(env -u CLAUDE_ENV_FILE sh -c "$hook")"
  check_match "...and Codex's" "omabox host -- CMD"$'\n'"$stale" "$(sh -c "$chook")"
  echo "${stamps% *} ba9876543210" > "$co/share/guard/hook-version"
  check_eq "...each by its own stamp" "1 2" "$(CLAUDE_ENV_FILE=$f sh -c "$hook" | wc -l) $(sh -c "$chook" | wc -l)"
  mv "$co/share/guard/hook-version" "$co/hook-version"
  check_eq "...no stamp there (ai-jail: no checkout, #203): nothing extra" "1 1" "$(CLAUDE_ENV_FILE=$f sh -c "$hook" | wc -l) $(sh -c "$chook" | wc -l)"
  mv "$co/hook-version" "$co/share/guard/hook-version"; cp "$ROOT/share/guard/hook-version" "$co/share/guard/"; rm -f "$f"
  check_match "the hook says so when it cannot apply the guard (finding 74)" "NOT applied" "$(env -u CLAUDE_ENV_FILE sh -c "$hook")"
  check_eq "...and applies it when it can" 1 "$(CLAUDE_ENV_FILE=$f sh -c "$hook" >/dev/null; grep -c 'WAYLAND_DISPLAY=omabox-guard' "$f")"
  check_eq "...with the guard's xdg-open first on PATH (finding 92)" "$co/share/guard" \
    "$(bash -c '. "$1"; echo "${PATH%%:*}"' _ "$f")"
  check_match "Codex's hook gives the note" "^omabox guard: shell commands here have no display" "$(sh -c "$chook")"
  CLAUDE_ENV_FILE=$f sh -c "$hook" >/dev/null
  check_eq "...a second session start: the guard's dir once on PATH (#113)" 1 \
    "$(bash -c '. "$1"; tr : "\n" <<<"$PATH" | grep -cxF "$2"' _ "$f" "$co/share/guard")"
  # #243: SessionStart fires on resume and compact too; the line went in once per start.
  check_eq "...and its line once in the env file (#243)" 1 "$(grep -c 'WAYLAND_DISPLAY=omabox-guard' "$f")"
  local hline; hline=$(grep -F 'WAYLAND_DISPLAY=omabox-guard' "$f")
  printf 'export OTHER=1\nexport WAYLAND_DISPLAY=omabox-guard DISPLAY=; prlimit --pid $$ --core=1: 2>/dev/null || true\nexport MORE=2\n' > "$f"
  CLAUDE_ENV_FILE=$f sh -c "$hook" >/dev/null
  check_eq "...an older omabox's line replaced by this one, the file's other lines kept" "export OTHER=1|export MORE=2|$hline" \
    "$(paste -sd'|' "$f")"
  # #142: the note says `!` commands are guarded, and gets through whole (it sits in the hooks'
  # single-quoted echo, so a ' in it would cut it short or break the hook).
  check_match "...whole, saying the user's ! commands are guarded (#142)" \
    "! commands the user runs are under this guard too.*omabox host -- CMD$" "$(sh -c "$chook")"
  check_match "...and so does Claude Code's" "! commands the user runs are under this guard too.*omabox host -- CMD$" \
    "$(CLAUDE_ENV_FILE=$f sh -c "$hook")"
  # Issue #51: omabox deleted without `guard off` (a checkout removed, a package uninstalled).
  # Gone means no omabox on PATH either (#203), so these run with none there.
  rm -rf "$co" "$f"; mkdir -p "$TMP/guard-nopath"
  hk() { env PATH="$TMP/guard-nopath" /bin/sh -c "$1"; }
  check_match "omabox gone: the hook says so, in one line" "^omabox guard: omabox is gone \($co/bin/omabox\), so the guard is not applied" "$(CLAUDE_ENV_FILE=$f hk "$hook")"
  check_eq "...one line" 1 "$(CLAUDE_ENV_FILE=$f hk "$hook" | wc -l)"
  check_fails "...and leaves the session's environment untouched" test -e "$f"
  check_match "...Codex's says how to take its guard out" "omabox is gone .*Codex still applies its guard.*# >>> omabox guard" "$(hk "$chook")"
  # #203: in ai-jail the broker maps omabox to ~/.local/bin/omabox, never at the checkout's path. The
  # agent there was told omabox was gone and the hook could go, and offered to remove it.
  local jb=$TMP/guard-jailbin; mkdir -p "$jb"; printf '#!/bin/sh
' > "$jb/omabox"; chmod +x "$jb/omabox"
  check_match "an omabox on PATH, not at the checkout's path (ai-jail): the note, not gone (#203)" \
    "^omabox guard: shell commands here have no display" "$(CLAUDE_ENV_FILE=$f env PATH="$jb" /bin/sh -c "$hook")"
  check_eq "...and the guard applied" 1 "$(grep -c 'WAYLAND_DISPLAY=omabox-guard' "$f")"
  check_match "...Codex's gives the note too" "^omabox guard: shell commands here have no display" "$(env PATH="$jb" /bin/sh -c "$chook")"
  rm -f "$f"
  check_fails "guard junk refused" g maybe
  check_fails "guard on for an unknown agent refused" g on vim
  # Codex (finding 67): a marked block in config.toml, checked as TOML; only when Codex is installed.
  local c=$h/.codex/config.toml
  check_fails "no Codex dir: Codex not listed" grep -q Codex <<<"$(g)"
  mkdir -p "$h/.codex"; printf 'model = "x"\n\n[features]\nhooks = true\n' > "$c"; orig=$(cat "$c"; echo .)
  local hj=$h/.codex/hooks.json
  jq -n '{hooks: {SessionStart: [{hooks: [{type: "command", command: "herdr.sh session", timeout: 10}]}]}}' > "$hj"
  out=$(g on codex)
  check_eq "Codex: on sets the variables for its commands" omabox-guard \
    "$(python3 -c 'import tomllib, sys; print(tomllib.load(open(sys.argv[1], "rb"))["shell_environment_policy"]["set"]["WAYLAND_DISPLAY"])' "$c")"
  check_eq "...adds its hook (issue #51), keeping the others" "herdr.sh session|omabox" \
    "$(jq -r '[.hooks.SessionStart[].hooks[].command | if contains("omabox-guard") then "omabox" else . end] | join("|")' "$hj")"
  check_match "...says Codex asks you to trust it" "trust its new hook once: /hooks" "$out"
  check_match "...and reads on" "Codex .*: on$" "$(g | grep '^Codex')"
  check_fails "...on again: no trust to ask for" grep -q trust <<<"$(g on codex)"
  jq '.hooks.SessionStart |= map(select(any(.hooks[]; .command | contains("omabox-guard")) | not))' "$hj" > "$hj.new" && mv "$hj.new" "$hj"
  check_match "Codex: the block without its hook (an install from before #51) reads outdated" "Codex .*: outdated \(its hook in .*hooks.json: off\)" "$(g | grep '^Codex')"
  g on codex >/dev/null
  check_match "...and on adds it" "Codex .*: on$" "$(g | grep '^Codex')"
  echo '{"hooks":' > "$hj"
  check_match "Codex: a hooks.json that is not JSON is refused" "hooks.json is not a JSON object" "$(g off codex >/dev/null; g on codex)"
  check_fails "...before anything is written" grep -q omabox "$c"
  echo '{}' > "$hj"; g on codex >/dev/null
  check_match "a broken Claude Code file is reported, not fatal for the rest" "claude: .*not a JSON object" "$(g | grep claude)"
  rm "$s"
  check_match "on codex leaves Claude Code alone" "Claude Code .*: off$" "$(g | grep '^Claude')"
  g off codex >/dev/null
  check_eq "Codex: off gives back the same file (trailing newline too)" "$(printf 'model = "x"\n\n[features]\nhooks = true\n.')" "$(cat "$c"; echo .)"
  check_eq "...and takes its hook out" '{}' "$(jq -c . "$hj")"
  # Codex keeps its file's last comment, our end marker, last: a table it adds lands inside the block
  # (finding 74: off deleted MCP servers).
  g on codex >/dev/null
  sed -i 's/^# <<< omabox guard$/\n[mcp_servers.x]\ncommand = "true"\n# <<< omabox guard/' "$c"
  check_match "Codex: a table added inside the block still reads on" "Codex .*: on$" "$(g | grep '^Codex')"
  check_match "...on again leaves it" "already on" "$(g on codex)"
  g off codex >/dev/null
  check_eq "...and off keeps it" true "$(python3 -c 'import tomllib, sys; print(tomllib.load(open(sys.argv[1], "rb"))["mcp_servers"]["x"]["command"])' "$c")"
  check_fails "...with nothing of the guard left" grep -q omabox "$c"
  printf '%s\n' "$(cat "$c")" "" "# >>> omabox guard" "[shell_environment_policy.set]" 'MINE = "1"' "# <<< omabox guard" > "$c"
  check_match "Codex: a key of someone else's inside the block: refused" "added inside" "$(g off codex)"
  printf 'model = "x"\n\n[features]\nhooks = true\n' > "$c"
  printf 'shell_environment_policy = { inherit = "core" }\n' > "$c"; orig=$(cat "$c"; echo .)
  out=$(g on codex)
  check_match "Codex: its own inline shell_environment_policy is refused, with the keys to add" "clashes.*WAYLAND_DISPLAY" "$(tr '\n' ' ' <<<"$out")"
  check_eq "...untouched" "$orig" "$(cat "$c"; echo .)"
  printf '[shell_environment_policy]\ninherit = "core"\n' > "$c"
  g on codex >/dev/null
  check_eq "Codex: its own [shell_environment_policy] is kept, the guard added" "core omabox-guard" \
    "$(python3 -c 'import tomllib, sys; p = tomllib.load(open(sys.argv[1], "rb"))["shell_environment_policy"]; print(p["inherit"], p["set"]["HYPRLAND_INSTANCE_SIGNATURE"])' "$c")"
  printf '%s\n' "# >>> omabox guard (\`omabox guard off\` removes this block)" "[shell_environment_policy.set]" \
    'WAYLAND_DISPLAY = "omabox-guard"' 'BROWSER = "/nonexistent/co/share/guard/xdg-open"' "# <<< omabox guard" > "$c"
  check_match "Codex: a block from a checkout that is gone says so (finding 92)" "outdated: its /nonexistent/co/share/guard is gone" "$(g | grep '^Codex')"
  printf 'x = \n' > "$c"
  check_match "Codex: a file that is not TOML is refused" "not valid TOML" "$(g on codex)"
  check_eq "...untouched" 'x = ' "$(cat "$c")"
}

# #221: a Codex config with its own shell_environment_policy.set. The guard's keys go into that table,
# marked, instead of a second [shell_environment_policy.set] (a TOML error, so `on` refused); keys
# merged there by hand, as omabox once told people to, read as on.
t_unit_guard_codex_merge() {
  local h=$TMP/gcm c keys out orig
  c=$h/.codex/config.toml; mkdir -p "$h/.codex"
  g() { HOME=$h CODEX_HOME=$h/.codex "$CLI" guard "$@" 2>&1; }
  st() { g | sed -n 's/^Codex (.*): //p'; }
  val() { python3 -c 'import tomllib, sys; p = tomllib.load(open(sys.argv[1], "rb"))["shell_environment_policy"]; print(" ".join(str(p["set"].get(k)) for k in sys.argv[2:]))' "$c" "$@"; }
  : > "$c"; g on codex >/dev/null   # the guard's keys, as a table of its own gives them
  keys=$(sed '1,2d;$d' "$c"); g off codex >/dev/null
  # The user's table first, other tables after it.
  printf 'model = "x"\n\n[shell_environment_policy]\ninherit = "core"\n\n[shell_environment_policy.set]\nMY_KEY = "1"\n\n[features]\nhooks = true\n' > "$c"
  orig=$(cat "$c"; echo .)
  check_eq "Codex, its own [shell_environment_policy.set]: off" off "$(st)"
  out=$(g on codex)
  check_match "...on merges the guard into it (#221)" "guard on in .*config.toml" "$out"
  check_eq "...the guard's keys and the user's in one table" "omabox-guard 1" "$(val WAYLAND_DISPLAY MY_KEY)"
  check_eq "...marked, right under its header" "$(printf '%s\n' '[shell_environment_policy.set]' "# >>> omabox guard (\`omabox guard off\` removes this block)" "$keys" '# <<< omabox guard' 'MY_KEY = "1"')" \
    "$(sed -n '/^\[shell_environment_policy.set\]/,/^MY_KEY/p' "$c")"
  check_eq "...and reads on" on "$(st)"
  check_match "...on again leaves it" "already on in .*config.toml" "$(g on codex)"
  g off codex >/dev/null
  check_eq "...off gives back the same file, the user's keys kept" "$orig" "$(cat "$c"; echo .)"
  # The user's table last: Codex adds its tables after it (finding 74).
  printf 'model = "x"\n\n[shell_environment_policy.set]\nMY_KEY = "1"\n' > "$c"; orig=$(cat "$c"; echo .)
  g on codex >/dev/null
  printf '\n[mcp_servers.x]\ncommand = "true"\n' >> "$c"
  check_eq "its table last, then a table of Codex's after it: on" on "$(st)"
  g off codex >/dev/null
  check_eq "...off keeps both" "$(printf 'model = "x"\n\n[shell_environment_policy.set]\nMY_KEY = "1"\n\n[mcp_servers.x]\ncommand = "true"\n.')" "$(cat "$c"; echo .)"
  # An empty table last: our end marker is the file's last comment, which Codex keeps at the very end
  # when it adds a table (as codex 0.162.1's `mcp add` writes it).
  printf 'model = "x"\n\n[shell_environment_policy.set]\n' > "$c"
  g on codex >/dev/null
  sed -i 's/^# <<< omabox guard$/\n[mcp_servers.x]\ncommand = "true"\n# <<< omabox guard/' "$c"
  check_eq "an empty table of its own, Codex's table inside our markers: on" on "$(st)"
  g off codex >/dev/null
  check_eq "...off keeps Codex's table, apart from the user's" "$(printf 'model = "x"\n\n[shell_environment_policy.set]\n\n[mcp_servers.x]\ncommand = "true"\n.')" "$(cat "$c"; echo .)"
  # Merged by hand, unmarked (the state #221 was found in): on, and `on` adds the markers.
  printf '[shell_environment_policy.set]\nMY_KEY = "1"\n%s\n\n[features]\nhooks = true\n' "$keys" > "$c"
  g on codex >/dev/null; g off codex >/dev/null   # the hook in hooks.json: on and off, and the keys gone
  printf '[shell_environment_policy.set]\nMY_KEY = "1"\n%s\n\n[features]\nhooks = true\n' "$keys" > "$c"
  check_match "keys merged by hand, no markers: on but for its hook" "outdated \(its hook in .*: off\)" "$(st)"
  g on codex >/dev/null
  check_eq "...on adopts them: marked once, no key twice" "1 1 $(wc -l <<<"$keys")" \
    "$(grep -c '^# >>> omabox guard' "$c") $(grep -c '^# <<< omabox guard' "$c") $(grep -cE '^[A-Z_]+ = ' "$c" | awk '{print $1 - 1}')"
  check_eq "...reads on" on "$(st)"
  g off codex >/dev/null
  check_eq "...off leaves the user's" "$(printf '[shell_environment_policy.set]\nMY_KEY = "1"\n\n[features]\nhooks = true\n.')" "$(cat "$c"; echo .)"
  printf '[shell_environment_policy.set]\nMY_KEY = "1"\n%s\n' "$keys" > "$c"
  g off codex >/dev/null
  check_eq "keys merged by hand: off takes them out too" "$(printf '[shell_environment_policy.set]\nMY_KEY = "1"\n.')" "$(cat "$c"; echo .)"
  check_eq "...and reads off" off "$(st)"
  # A value of the user's own for one of the guard's keys: theirs, not overwritten.
  printf '[shell_environment_policy.set]\nBROWSER = "firefox"\n' > "$c"; orig=$(cat "$c"; echo .)
  out=$(g on codex)
  check_match "its own value for a key of the guard's: refused, naming it" "has BROWSER = \"firefox\", the guard needs BROWSER = .*not touched" "$out"
  check_eq "...untouched" "$orig" "$(cat "$c"; echo .)"
  check_eq "...and reads off" off "$(st)"
  # The same value: the user's too, left where it is; ours are the others.
  printf '[shell_environment_policy.set]\nDISPLAY = ""\n' > "$c"
  g on codex >/dev/null
  check_eq "its own DISPLAY with the guard's value: on, kept outside our block" "on 1" "$(st) $(sed -n '/^# <<< omabox guard/,$p' "$c" | grep -c '^DISPLAY = ""')"
  g off codex >/dev/null
  check_eq "...and kept by off" "$(printf '[shell_environment_policy.set]\nDISPLAY = ""\n.')" "$(cat "$c"; echo .)"
  # Dotted keys, under [shell_environment_policy] and at the top.
  printf '[shell_environment_policy]\ninherit = "core"\nset.MY_KEY = "1"\n\n[x]\ny = 1\n' > "$c"; orig=$(cat "$c"; echo .)
  g on codex >/dev/null
  check_eq "dotted set.KEY under [shell_environment_policy]: merged as set.KEY, on" "omabox-guard 1 on" "$(val WAYLAND_DISPLAY MY_KEY) $(st)"
  g off codex >/dev/null
  check_eq "...off gives it back" "$orig" "$(cat "$c"; echo .)"
  printf 'model = "x"\nshell_environment_policy.set.MY_KEY = "1"\n\n[x]\ny = 1\n' > "$c"; orig=$(cat "$c"; echo .)
  g on codex >/dev/null
  check_eq "dotted keys at the top: merged as such, on" "omabox-guard 1 on" "$(val WAYLAND_DISPLAY MY_KEY) $(st)"
  g off codex >/dev/null
  check_eq "...off gives it back" "$orig" "$(cat "$c"; echo .)"
  # An inline table cannot take more keys.
  printf '[shell_environment_policy]\nset = { MY_KEY = "1" }\n' > "$c"; orig=$(cat "$c"; echo .)
  check_match "an inline set table: refused, with the keys to add by hand" "could not merge .*not touched; add these to it by hand: WAYLAND_DISPLAY" "$(g on codex | tr '\n' ' ')"
  check_eq "...untouched" "$orig" "$(cat "$c"; echo .)"
}

# guard exec (any agent, whole) and host (one command on the real desktop, from a guarded shell).
t_unit_guard_exec_host() {
  check_eq "guard exec: the guard's display" omabox-guard "$("$CLI" guard exec -- sh -c 'echo $WAYLAND_DISPLAY')"
  check_eq "guard exec: a core limit of 1 byte (no crash notification)" 1 "$("$CLI" guard exec -- sh -c 'prlimit --pid $$ --core -o SOFT --noheadings | tr -d " "')"
  # finding 92: no links or files opened on the desktop, however they are asked for. xdg-open runs
  # only when `command -v` under guard exec gives the guard's: were a dir with the real one put ahead
  # of it, xdg-open would open a tab on the desktop. A stub right after the guard's on PATH is a
  # second net, should the lookup that runs xdg-open ever differ from `command -v`'s: the checks
  # then reach the stub and fail.
  local gx=(env PATH="$TMP/fakeopen:$PATH" "$CLI" guard exec --) xo
  mkdir -p "$TMP/fakeopen"
  printf '#!/bin/sh\necho "real xdg-open reached"\n' > "$TMP/fakeopen/xdg-open"; chmod +x "$TMP/fakeopen/xdg-open"
  xo=$("${gx[@]}" sh -c 'command -v xdg-open')
  check_eq "guard exec: xdg-open is the guard's" "$ROOT/share/guard/xdg-open" "$xo"
  if [ "$xo" = "$ROOT/share/guard/xdg-open" ]; then
    check_match "...which refuses" "omabox guard: not opening https://example.invalid" \
      "$("${gx[@]}" xdg-open https://example.invalid 2>&1)"
    check_eq "...with exit 4, as xdg-open for a failed action" 4 "$("${gx[@]}" xdg-open https://example.invalid >/dev/null 2>&1; echo $?)"
  else
    no "...which refuses, with exit 4" "not run: xdg-open under guard exec is [$xo], not the guard's"
  fi
  check_eq "...and BROWSER, GH_BROWSER name it" "$ROOT/share/guard/xdg-open $ROOT/share/guard/xdg-open" \
    "$("$CLI" guard exec -- sh -c 'echo $BROWSER $GH_BROWSER')"
  # #141: Quickshell's IPC needs no display, so under the guard `kill` and `ipc` reached the desktop's
  # shell. The guard's quickshell and qs refuse them; the rest goes on to the next quickshell on PATH,
  # here a stub (so a refusal that failed would reach it, never the real one).
  printf '#!/bin/sh\necho "real quickshell reached: $*"\n' > "$TMP/fakeopen/quickshell"; chmod +x "$TMP/fakeopen/quickshell"
  local qs; qs=$("${gx[@]}" sh -c 'command -v quickshell; command -v qs' | xargs)
  check_eq "guard exec: quickshell and qs are the guard's" "$ROOT/share/guard/quickshell $ROOT/share/guard/qs" "$qs"
  if [ "$qs" = "$ROOT/share/guard/quickshell $ROOT/share/guard/qs" ]; then
    check_match "...quickshell kill --any-display refused" "omabox guard: not running quickshell kill here" \
      "$("${gx[@]}" quickshell kill -p /usr/share/omarchy/shell --any-display 2>&1)"
    check_eq "...with exit 4" 4 "$("${gx[@]}" quickshell kill --any-display >/dev/null 2>&1; echo $?)"
    check_match "...qs ipc call refused, after an option with a value" "not running quickshell ipc here" \
      "$("${gx[@]}" qs -p /usr/share/omarchy/shell ipc --any-display call shell ping 2>&1)"
    check_match "...qs msg (ipc call's old name) refused" "not running quickshell msg here" "$("${gx[@]}" qs msg -i abc x y 2>&1)"
    check_eq "...list goes on, its arguments whole" "real quickshell reached: list --all --json" "$("${gx[@]}" qs list --all --json 2>&1)"
    check_eq "...so does --version" "real quickshell reached: --version" "$("${gx[@]}" quickshell --version 2>&1)"
    check_eq "...and a config whose path is a subcommand's name" "real quickshell reached: -p /tmp/kill log" "$("${gx[@]}" qs -p /tmp/kill log 2>&1)"
    # #166: quickshell's parser bundles short options (`quickshell -np PATH list` runs), and the guard
    # read -np as a flag and PATH as the subcommand, so kill and ipc after it reached the real one.
    local f a
    for f in -np -dp -pn -vnp -npX --path=/x; do
      a=("$f"); case $f in -npX|--path=*) ;; *) a+=(/usr/share/omarchy/shell) ;; esac
      check_match "...qs ${a[*]} kill refused (bundled options)" "not running quickshell kill here" "$("${gx[@]}" qs "${a[@]}" kill --any-display 2>&1)"
      check_match "...qs ${a[*]} ipc refused" "not running quickshell ipc here" "$("${gx[@]}" qs "${a[@]}" ipc --any-display call shell ping 2>&1)"
      check_eq "...qs ${a[*]} list goes on, whole" "real quickshell reached: ${a[*]} list --all" "$("${gx[@]}" qs "${a[@]}" list --all 2>&1)"
    done
    check_eq "...exit 4 for a bundled kill" 4 "$("${gx[@]}" quickshell -dp /x kill >/dev/null 2>&1; echo $?)"
    check_eq "...a value that is a subcommand's name, bundled, is a value" "real quickshell reached: -np kill list" \
      "$("${gx[@]}" qs -np kill list 2>&1)"
    check_match "...an unknown word before kill does not hide it" "not running quickshell kill here" "$("${gx[@]}" qs --unknown-opt value kill 2>&1)"
  else
    no "...which refuse kill and ipc" "not run: quickshell under guard exec is [$qs], not the guard's"
  fi
  # host's session, a stand-in one (#372, stand_in_host): no check below reaches the user's desktop,
  # and each one sees the session omabox finds there, not $HYPRLAND_INSTANCE_SIGNATURE (under the
  # guard, an agent running the suite, that is the guard's).
  local hrt=$TMP/ghost-rt hsig=a_7_7 STANDIN_PID; stand_in_host "$hrt" "$hsig"
  check_eq "the stand-in session is the only one there" "$hsig wayland-sti" \
    "$(XDG_RUNTIME_DIR=$hrt hyprctl -j instances | jq -r '.[] | "\(.instance) \(.wl_socket)"' | paste -sd '|')"
  local GUARDED=("${GUARDED[@]}" XDG_RUNTIME_DIR="$hrt")
  check_eq "host from a guarded shell: the session's Wayland display and signature" "wayland-sti $hsig" \
    "$("${GUARDED[@]}" "$CLI" host -- sh -c 'echo $WAYLAND_DISPLAY $HYPRLAND_INSTANCE_SIGNATURE' 2>/dev/null)"
  check_match "host: and hyprctl reaches it" '"tag": "stand-in"' "$("${GUARDED[@]}" "$CLI" host -- hyprctl -j version 2>/dev/null)"
  check "...the stand-in heard it" grep -qx j/version "$hrt/requests.log"
  local open; open=$("${GUARDED[@]}" "$CLI" host -- sh -c 'command -v xdg-open; echo "${BROWSER-unset}"' 2>/dev/null)
  check_match "host: the real xdg-open (finding 92)" '^/' "$(head -1 <<<"$open")"
  check_fails "...not the guard's" grep -q share/guard <<<"$open"
  check_fails "host: the real quickshell and qs, not the guard's (#141)" grep -q share/guard \
    <<<"$("${GUARDED[@]}" "$CLI" host -- sh -c 'command -v quickshell; command -v qs' 2>/dev/null)"
  check_fails "...nor another checkout's" grep -q elsewhere <<<"$("${GUARDED[@]}" PATH="/elsewhere/share/guard:$PATH" BROWSER=/elsewhere/share/guard/xdg-open "$CLI" host -- sh -c 'echo "$PATH ${BROWSER-}"' 2>/dev/null)"
  # (...nor one written with a trailing slash, up and run leaving it out too: exec.rs
  # caller_path_as_bash; #324 wave 6-suite.)
  # (A host's `omarchy dev link` puts its checkout's bin first, finding 149: kept for host, not in a
  # box: exec.rs caller_path_as_bash.)
  check_eq "host: a BROWSER the guard did not set stays (Omarchy sets it in the shell)" firefox \
    "$("${GUARDED[@]}" BROWSER=firefox "$CLI" host -- sh -c 'echo "${BROWSER-unset}"' 2>/dev/null)"
  # The user manager's, through a stand-in systemctl: a plain value is taken, one it quotes is not.
  mkdir -p "$TMP/sysenv"
  cat > "$TMP/sysenv/systemctl" <<'EOF'
#!/bin/sh
[ "$*" = "--user show-environment" ] || exit 1
echo "BROWSER=\$'/opt/my browser'"
echo GH_BROWSER=firefox
EOF
  chmod +x "$TMP/sysenv/systemctl"
  check_eq "host: the stand-in gives way to the user manager's GH_BROWSER, not to a quoted BROWSER" "unset firefox" \
    "$("${GUARDED[@]}" PATH="$TMP/sysenv:$ROOT/share/guard:$PATH" "$CLI" host -- sh -c 'echo "${BROWSER-unset} ${GH_BROWSER-unset}"' 2>/dev/null)"
  check_eq "host: Qt logging as usual" unset "$("${GUARDED[@]}" "$CLI" host -- sh -c 'echo ${QT_FORCE_STDERR_LOGGING-unset}' 2>/dev/null)"
  check_match "host says what it runs" "on your real desktop: true" "$("${GUARDED[@]}" "$CLI" host -- true 2>&1)"
  # The record shortens only long arguments (#150): an expanded PATH, a long word.
  local hl long; long=$(printf '/opt/long/install/dir/bin:%.0s' {1..30})
  hl=$("${GUARDED[@]}" "$CLI" host -- env "PATH=$long$PATH" true 2>&1)
  check_match "host: a long NAME=value is cut, env, PATH= and true still there" "on your real desktop: env PATH=/opt/long/install/dir/bin:/opt/long/inst…\(\+[0-9]+ chars\) true$" "$hl"
  check_match "...one line under 200 characters" "^1 ([0-9]|[0-9][0-9]|1[0-9][0-9])$" "$(wc -l <<<"$hl") ${#hl}"
  check_eq "...a short command exactly as it is" "omabox: on your real desktop: printf %s A=b x" "$("${GUARDED[@]}" "$CLI" host -- printf %s A=b x 2>&1 >/dev/null)"
  # (...a long word cut too: host.rs the_record_cuts_long_words.)
  check_fails "host with nothing to run refused" "${GUARDED[@]}" "$CLI" host
  kill "$STANDIN_PID" 2>/dev/null; wait "$STANDIN_PID" 2>/dev/null || true
}

# #290: Omarchy 4.5's omarchy-shell takes the newest wayland-N when $WAYLAND_DISPLAY names no socket, and
# then talks to the desktop shell's own socket over socat, past the guard's qs. Here in a runtime dir of
# its own, with a stand-in display wayland-1, a listener on the socket the shell would have for it, and
# a stub qs after the guard's. The installed omarchy-shell (OMABOX_TEST_OMARCHY's, for a 4.5 tree) runs
# by its path, as `omarchy shell` runs it: under guard exec, which makes the guard's file, the listener
# hears nothing. Without the file a 4.5 one is heard (so the check can fail); 4.0.6's is not.
t_unit_guard_omarchy_shell() {
  if ! command -v python3 >/dev/null; then skip "the guard and omarchy-shell (#290)" "no python3"; return; fi
  local d=$TMP/g290 o=${OMABOX_TEST_OMARCHY:-/usr/share/omarchy} os
  mkdir -p "$d/rt" "$d/om/shell" "$d/stub"; chmod 700 "$d/rt"; : > "$d/om/shell/shell.qml"
  printf '#!/bin/sh\necho "real $(basename "$0") reached: $*" >> %s/stub.log\n' "$d" > "$d/stub/qs"
  chmod +x "$d/stub/qs"; cp "$d/stub/qs" "$d/stub/quickshell"; cp "$d/stub/qs" "$d/stub/omarchy-shell"
  local id; id=$(printf '%s\n%s' "$d/om/shell" wayland-1 | md5sum)
  # The display's socket, and the shell's for it: whatever connects is written down.
  python3 - "$d/rt/wayland-1" "$d/rt/omarchy-shell-${id:0:16}.sock" "$d/heard" <<'PY' &
import os, socket, sys
w = socket.socket(socket.AF_UNIX); w.bind(sys.argv[1]); w.listen(4)
s = socket.socket(socket.AF_UNIX); s.bind(sys.argv[2]); s.listen(4)
open(sys.argv[3] + ".ready", "w").close()
while True:
    c, _ = s.accept(); data = c.recv(4096)
    with open(sys.argv[3], "ab") as f: f.write(data + b"\n")
    c.close()
PY
  local L=$! i
  for i in $(seq 50); do [ -e "$d/heard.ready" ] && break; sleep 0.1; done
  local env=(env XDG_RUNTIME_DIR="$d/rt" OMARCHY_PATH="$d/om" PATH="$d/stub:$PATH")
  local gx=("${env[@]}" "$CLI" guard exec --)
  os=$o/bin/omarchy-shell
  if [ -x "$os" ]; then
    "${env[@]}" WAYLAND_DISPLAY=omabox-guard timeout 3 "$os" shell ping >/dev/null 2>&1 || true
    if [ -s "$d/heard" ]; then
      check_match "control: without the guard's file, $os reaches the shell's socket" ping "$(cat "$d/heard")"
    else
      skip "control: $os reaching the shell's socket without the guard's file" "it does not recover a display that names no socket (Omarchy before 4.5)"   # omarchy<4.5
    fi
    : > "$d/heard"
    "${gx[@]}" timeout 3 "$os" shell ping >/dev/null 2>&1 || true
    check "guard exec makes the guard's file" test -f "$d/rt/omabox-guard"
    check_eq "...and omarchy-shell, run by its path, never reaches the shell's socket" "" "$(cat "$d/heard")"
  else
    skip "omarchy-shell under the guard (#290)" "no $os (OMABOX_TEST_OMARCHY names a tree)"
  fi
  # By name: the guard's, which refuses while the display names no socket, and passes a real one on.
  rm -f "$d/rt/omabox-guard" "$d/stub.log"
  check_eq "guard exec: omarchy-shell is the guard's" "$ROOT/share/guard/omarchy-shell" "$("${gx[@]}" sh -c 'command -v omarchy-shell')"
  check_match "...which refuses" "omabox guard: not running omarchy-shell here" "$("${gx[@]}" omarchy-shell shell ping 2>&1)"
  check_eq "...with exit 4" 4 "$("${gx[@]}" omarchy-shell shell ping >/dev/null 2>&1; echo $?)"
  check_eq "...and 0 for -q (best effort), as omarchy-shell's own failures" 0 "$("${gx[@]}" omarchy-shell -q shell ping >/dev/null 2>&1; echo $?)"
  check_match "...also with no guard's file and no display at all" "not running omarchy-shell here" \
    "$("${env[@]}" WAYLAND_DISPLAY= "$ROOT/share/guard/omarchy-shell" shell ping 2>&1)"
  # (#332: one of Omarchy's commands calling it by name, from a `$(...)`, as omarchy-plugin-list does: named)
  mkdir -p "$d/om-bin"
  printf '#!/bin/bash\nplugins=$(omarchy-shell shell listPlugins)\necho "listed: $plugins"\n' > "$d/om-bin/omarchy-plugin-list"
  chmod +x "$d/om-bin/omarchy-plugin-list"
  check_match "...an Omarchy command that calls it is named, with where its plugins are (#332)" \
    "^omabox guard: not running omarchy-plugin-list here: it asks the user's desktop shell .* through omarchy-shell\. For a box's: omabox run -- omarchy-plugin-list \.\.\. The plugins installed are the folders in ~/\.config/omarchy/plugins\." \
    "$("${gx[@]}" env PATH="$ROOT/share/guard:$d/om-bin:$PATH" omarchy-plugin-list 2>&1 >/dev/null)"
  check_eq "...nothing got past it" "" "$(cat "$d/stub.log" 2>/dev/null)"
  check_eq "a display that is a socket goes on to the next omarchy-shell, its words whole" "real omarchy-shell reached: -q shell ping" \
    "$("${env[@]}" WAYLAND_DISPLAY=wayland-1 "$ROOT/share/guard/omarchy-shell" -q shell ping >/dev/null 2>&1; cat "$d/stub.log")"
  # Any omabox command run under the guard makes the file too (a session whose hook is older).
  rm -f "$d/rt/omabox-guard"
  "${env[@]}" WAYLAND_DISPLAY=omabox-guard "$CLI" --version >/dev/null 2>&1 || true
  check "an omabox command under the guard makes the guard's file" test -f "$d/rt/omabox-guard"
  rm -f "$d/rt/omabox-guard"
  "${env[@]}" WAYLAND_DISPLAY=wayland-1 "$CLI" --version >/dev/null 2>&1 || true
  check_fails "...not one outside it" test -e "$d/rt/omabox-guard"
  kill "$L" 2>/dev/null; wait "$L" 2>/dev/null || true
}

# Under the guard, with a box standing in for the host (finding 26): box commands work, an app run
# straight fails instead of opening a window, and omabox's own host windows (interactive, peek) and
# --size host still find the session. Never on the real desktop.
t_guard() {
  local B=$P-gd
  UP_OUT=$("${GUARDED[@]}" "$CLI" up "$B" --no-shell --net isolated 2>&1) || { no "up under the guard" "$UP_OUT"; return; }
  check_match "run under the guard gets the box's display" '^wayland-' "$("${GUARDED[@]}" "$CLI" run -b "$B" -- sh -c 'echo $WAYLAND_DISPLAY')"
  check "hyprctl under the guard" "${GUARDED[@]}" "$CLI" hyprctl -b "$B" -j version
  check "shot under the guard" "${GUARDED[@]}" "$CLI" shot -b "$B" -o "$TMP/guard.png"
  # finding 92: the guard's xdg-open stays out of a box (this repo is mounted in it, so it could be seen).
  check_match "a box's xdg-open is its own" '^/usr/' "$("${GUARDED[@]}" "$CLI" run -b "$B" -- sh -c 'command -v xdg-open')"
  # (Its PATH line first: a failed read would have no share/guard in it either.)
  local spath; spath=$("$CLI" run -b "$B" -- sh -c 'tr "\0" "\n" < /proc/$(pgrep -x Hyprland)/environ | grep "^PATH="')
  check_match "...and the box session's PATH" '^PATH=/' "$spath"
  check_fails "...lacks the guard's" grep share/guard <<<"$spath"
  # Inside the stand-in host: the guard as an agent's shell there would have it.
  local in=("$CLI" run -b "$B" -- "${GUARDED[@]}")
  # A Wayland client says so too, and exits cleanly.
  check_match "a Wayland client under the guard fails with no display" "Failed to connect to a Wayland server" \
    "$("${in[@]}" wl-paste 2>&1)"
  check_fails "hyprctl under the guard fails there too" "${in[@]}" hyprctl -j version
  # Qt offscreen (what ctest sets) under the guard: runs, because the guard also blanks Omarchy's
  # QT_QPA_PLATFORMTHEME=gtk3, which starts GTK and needs a display. Run under a name
  # omarchy-crash-watch never announces, with no core file, in case it ever aborts.
  local qt='cp /usr/lib/qt6/bin/qml /tmp/omarchy-crash-omabox-qt
    printf "import QtQuick\nWindow { visible: true; Component.onCompleted: Qt.quit() }\n" > /tmp/q.qml
    exec timeout 10 /tmp/omarchy-crash-omabox-qt /tmp/q.qml'
  check "offscreen Qt runs under the guard" "${in[@]}" QT_QPA_PLATFORM=offscreen bash -c "$qt"
  check_match "...which needs the theme blanked (gtk3: GTK wants a display)" "cannot open display" \
    "$("${in[@]}" QT_QPA_PLATFORM=offscreen QT_QPA_PLATFORMTHEME=gtk3 bash -c "$qt" 2>&1)"
  # A Qt program with no display aborts: the reason reaches the caller (QT_FORCE_STDERR_LOGGING), and
  # the box's core limit keeps the abort out of the journal, so no crash notification (finding 67).
  local since; since=$(date '+%Y-%m-%d %H:%M:%S')
  check_match "a Qt app under the guard says why it fails" "could not connect to display" \
    "$("${in[@]}" QT_QPA_PLATFORM='wayland;xcb' bash -c "${qt//exec timeout/timeout}" 2>&1)"
  sleep 1
  check_eq "...and its abort is not a journaled crash" 0 "$(journalctl --since "$since" MESSAGE_ID=fc2e22bc6ee647b6b90729ab34a250b1 -o json --no-pager 2>/dev/null | grep -c omarchy-crash-omabox)"
  check "up --interactive under the guard" "${in[@]}" "$CLI" up inner --interactive --no-shell
  check_box_safety inner "${in[@]}" "$CLI"
  # finding 95: it renders on the GPU its host names, so it gets every render node the host has (and
  # an NVIDIA one's userspace nodes), not just the one a headless box would pick.
  local gpu_nodes='ls /dev/dri/renderD* /dev/nvidiactl /dev/nvidia[0-9]* 2>/dev/null; true'
  check_eq "...with every GPU node of its host" "$("$CLI" run -b "$B" -- sh -c "$gpu_nodes")" \
    "$("${in[@]}" "$CLI" run -b inner -- sh -c "$gpu_nodes")"
  check_eq "...its window is on workspace 9" 9 "$(ob hyprctl -b "$B" -j clients | jq -r '.[] | select(.class == "aquamarine") | .workspace.name')"
  check_eq "...without focus" null "$(ob hyprctl -b "$B" -j activewindow | jq -r '.class')"
  # render_unfocused (finding 90): shots while its window is hidden; the stand-in's workspace and
  # focused window stay as they were. The first shot right after `up` gets a frame even from a box
  # that is not drawn while hidden, so a window opened in the box must show in a second one.
  local aw0; aw0=$(ob hyprctl -b "$B" -j activewindow | jq -r '.address // ""')
  check "...shot while its window is hidden" "${in[@]}" "$CLI" shot -b inner -o /tmp/hidden-inner.png
  local app=foot; command -v es2gears_wayland >/dev/null && app=es2gears_wayland
  "${in[@]}" "$CLI" run -b inner -d -- "$app" >/dev/null 2>&1
  # shellcheck disable=SC2329 # called through until_ok
  mapped() { "${in[@]}" "$CLI" hyprctl -b inner -j clients | jq -e 'length > 0' >/dev/null; }
  check "...a window opens in it" until_ok 10 mapped
  check "...shot again, still hidden" "${in[@]}" "$CLI" shot -b inner -o /tmp/hidden-inner2.png
  check "...which shows that window: the box is drawn while hidden" \
    "${in[@]}" sh -c '! cmp -s /tmp/hidden-inner.png /tmp/hidden-inner2.png && test -s /tmp/hidden-inner2.png'
  check_eq "...the host's workspace unchanged" 1 "$(ob hyprctl -b "$B" -j activeworkspace | jq -r '.name')"
  check_eq "...and its focused window" "$aw0" "$(ob hyprctl -b "$B" -j activewindow | jq -r '.address // ""')"
  # ...so wait sees it too (finding 82: it said "not rendered" before finding 90). Its answer depends
  # on the app (animated gears never hold still: 124), but it is never "unknown".
  local out rc=0; out=$("${in[@]}" "$CLI" wait -b inner still --timeout 3s 2>&1) || rc=$?
  # (run's notes of the host paths in the guard's words, #301, go before it: wait's answer is the rest)
  check_match "wait on a hidden interactive box sees it drawn (an answer, not unknown)" "^(satisfied|unsatisfied): " \
    "$(grep -v '^omabox: note: ' <<<"$out")"
  check_match "...exit 0 or 124, never 1" "^(0|124)$" "$rc"
  "${in[@]}" "$CLI" down inner >/dev/null 2>&1
  # The workspace setting (finding 70): a number, the scratchpad; neither takes focus
  check "up --interactive --workspace 3" "${in[@]}" "$CLI" up ws3 --interactive --no-shell --workspace 3
  check "up --interactive on the scratchpad (config)" "${in[@]}" bash -c "'$CLI' config workspace special >/dev/null && '$CLI' up wsp --interactive --no-shell; '$CLI' config workspace default >/dev/null"
  check_eq "...on workspace 3 and the scratchpad" "3 special:scratchpad" "$(ob hyprctl -b "$B" -j clients | jq -r '[.[] | select(.class == "aquamarine") | .workspace.name] | sort | join(" ")')"
  check_eq "...without focus" null "$(ob hyprctl -b "$B" -j activewindow | jq -r '.class')"
  local b; for b in ws3 wsp; do
    check "...shot of $b while hidden" "${in[@]}" "$CLI" shot -b "$b" -o "/tmp/hidden-$b.png"
  done
  check_eq "...the host's workspace unchanged" 1 "$(ob hyprctl -b "$B" -j activeworkspace | jq -r '.name')"
  check_eq "...and its focused window" "$aw0" "$(ob hyprctl -b "$B" -j activewindow | jq -r '.address // ""')"
  "${in[@]}" "$CLI" down ws3 >/dev/null 2>&1; "${in[@]}" "$CLI" down wsp >/dev/null 2>&1
  # confirm-close: the first close opens a new window and asks, a second one ends the box; off, one
  # close ends it; `omabox config` changes a running box that took it from the config
  local cl=(ob hyprctl -b "$B" dispatch "hl.dsp.window.close({ window = 'class:aquamarine' })")
  state() { "${in[@]}" "$CLI" ls --json | jq -r --arg n "$1" '[.[] | select(.name == $n) | .state][0] // "gone"'; }
  # shellcheck disable=SC2329 # called through until_ok and holds
  gone() { [ "$(state "$1")" = gone ]; }
  # shellcheck disable=SC2329
  is() { [ "$(state "$1")" = "$2" ]; }
  if aq_unfixed "${in[@]}" "$CLI"; then
    # finding 125: without aquamarine's fix the box cannot open its window again
    check_match "no aquamarine fix: --confirm-close refused, saying why" "--confirm-close .*needs aquamarine's fix" \
      "$("${in[@]}" "$CLI" up cc --interactive --no-shell --confirm-close 2>&1)"
    check_eq "...before anything started" gone "$(state cc)"
    "${in[@]}" "$CLI" config confirm-close on >/dev/null 2>&1
    check_match "...on in the settings: off for the box, saying so" "confirm-close is on in your settings, but it needs" \
      "$("${in[@]}" "$CLI" up lv --interactive --no-shell 2>&1)"
    "${cl[@]}" >/dev/null
    check "...so one close ends it, cleared" until_ok 8 gone lv
    "${in[@]}" "$CLI" config confirm-close off >/dev/null
    # The flag on all the same (the library changed under a running box): confirm-close.sh finds no
    # new window and ends the box rather than leave it with none.
    "${in[@]}" "$CLI" up fb --interactive --no-shell >/dev/null 2>&1
    "${in[@]}" sh -c "echo on > '$("${in[@]}" "$CLI" path fb)/run/omabox.confirm-close'"
    "${cl[@]}" >/dev/null
    check "...and a box whose flag is on anyway ends when no window comes" until_ok 12 gone fb
  else
    "${in[@]}" "$CLI" up cc --interactive --no-shell --confirm-close >/dev/null 2>&1
    # issue #24: a window on 1 and one on 2, 2 shown: the new window must show 2 again, not a new one
    local cch=("${in[@]}" "$CLI" hyprctl -b cc)
    # shellcheck disable=SC2329 # called through until_ok
    ccwins() { "${cch[@]}" -j clients | jq -e --argjson n "$1" 'length == $n' >/dev/null; }
    "${in[@]}" "$CLI" run -b cc -d -- foot >/dev/null 2>&1
    until_ok 10 ccwins 1
    "${cch[@]}" dispatch 'hl.dsp.focus({ workspace = "2" })' >/dev/null
    "${in[@]}" "$CLI" run -b cc -d -- foot >/dev/null 2>&1
    until_ok 10 ccwins 2
    "${cl[@]}" >/dev/null
    check "confirm-close: the box stays after a close" holds 2 is cc up
    check_eq "...showing the workspace it showed (issue #24)" 2 "$("${cch[@]}" -j activeworkspace | jq -r .name)"
    check_eq "...its window focused" "foot 2" "$("${cch[@]}" -j activewindow | jq -r '"\(.class) \(.workspace.name)"')"
    check_eq "...its windows where they were, no empty workspace left" "1:1 2:1" \
      "$("${cch[@]}" -j workspaces | jq -r '[.[] | "\(.name):\(.windows)"] | sort | join(" ")')"
    # finding 90: that window has no render_unfocused; the box says so for `shot`'s message
    check "...marked as not drawn while hidden" "${in[@]}" test -f "$("${in[@]}" "$CLI" path cc)/run/omabox.reopened"
    "${cl[@]}" >/dev/null
    check "...and a second close ends it, cleared: no dead box left (finding 71)" until_ok 8 gone cc
    "${in[@]}" "$CLI" up lv --interactive --no-shell >/dev/null 2>&1
    "${in[@]}" "$CLI" config confirm-close on >/dev/null
    # (a class token `monitor add` left for that window's name: an add still in flight, or one cut
    # short; finding 429)
    local lvd; lvd=$("${in[@]}" "$CLI" path lv)
    "${in[@]}" sh -c "echo omabox-0123456789abcdef > '$lvd/run/omabox.appid.WAYLAND-1'"
    "${cl[@]}" >/dev/null
    check "config confirm-close on reaches a running box" holds 2 is lv up
    check_eq "...its new window of class aquamarine with a class token left for the closed one's name (finding 429)" 1 \
      "$(ob hyprctl -b "$B" -j clients | jq '[.[] | select(.class == "aquamarine")] | length')"
    check_eq "...under another name, one with no token" WAYLAND-2 \
      "$("${in[@]}" "$CLI" hyprctl -b lv -j monitors | jq -r '[.[] | select(.name != "FALLBACK") | .name] | join(" ")')"
    check "...the token kept (an add in flight may need it)" "${in[@]}" test -e "$lvd/run/omabox.appid.WAYLAND-1"
    "${in[@]}" "$CLI" config confirm-close off >/dev/null
    "${cl[@]}" >/dev/null
    check "...and off again: one close ends it, cleared" until_ok 8 gone lv
    # #111: --no-confirm-close wins over the setting
    "${in[@]}" "$CLI" config confirm-close on >/dev/null
    "${in[@]}" "$CLI" up nc --interactive --no-shell --no-confirm-close >/dev/null 2>&1
    "${in[@]}" "$CLI" config confirm-close off >/dev/null
    "${cl[@]}" >/dev/null
    check "up --no-confirm-close with the setting on: one close ends it" until_ok 8 gone nc
  fi
  # A box that dies without being closed stays dead, logs kept, until `down`
  "${in[@]}" "$CLI" up cr --interactive --no-shell >/dev/null 2>&1
  "${in[@]}" "$CLI" run -b cr -- pkill -KILL -x Hyprland >/dev/null 2>&1
  until_ok 10 is cr dead
  # its reaper's first poll after that decides, then it goes
  until_ok 10 bash -c "! '$CLI' run -b '$B' -- pgrep -f 'omabox _reap cr '"
  check_eq "an interactive box that crashed stays dead" dead "$(state cr)"
  "${in[@]}" "$CLI" down cr >/dev/null 2>&1
  check "up --size host under the guard" "${in[@]}" "$CLI" up inner2 --size host --no-shell --idle 0
  check_eq "...the stand-in's monitor" "$(ob mode -b "$B")" "$("${in[@]}" "$CLI" mode -b inner2)"
  check "peek under the guard" "${in[@]}" "$CLI" peek inner2
  check "...its window appears" until_ok 10 bash -c "'$CLI' hyprctl -b '$B' -j clients | jq -e '.[] | select(.class == \"omabox-peek\") | select(.workspace.name == \"9\")'"
  "${in[@]}" pkill -x omabox-peek >/dev/null 2>&1
  check "peek --workspace 4 (#111)" "${in[@]}" "$CLI" peek inner2 --workspace 4
  check "...its window on 4" until_ok 10 bash -c "'$CLI' hyprctl -b '$B' -j clients | jq -e '.[] | select(.class == \"omabox-peek\") | select(.workspace.name == \"4\")'"
  "${in[@]}" "$CLI" down --all >/dev/null 2>&1
  ob down "$B" >/dev/null
}

# special:omabox (#292, finding 423), the widget's "Its own", in a box standing in for the host (finding
# 26): an interactive box's window there is full size (not the half-height panel Omarchy 4.5's
# scratchpad, its Quake console, makes of a lone window), opens with no focus and no workspace change,
# is opened by the widget's Show (peek --focus) and hidden by a workspace switch, and keeps drawing
# while hidden and after it is shown again; a peek window goes there too.
t_special_ws() {
  local B=$P-sw out; local in=("$CLI" run -b "$B" --)
  up_ok "$B" --no-shell --net isolated || { no "up (the stand-in host)" "$UP_OUT"; return; }
  # shellcheck disable=SC2329 # called through until_ok
  shown() { [ "$(ob hyprctl -b "$B" -j monitors | jq -r '.[0].specialWorkspace.name')" = "$1" ]; }
  out=$("${in[@]}" "$CLI" up sw --interactive --no-shell --workspace special:omabox 2>&1) || { no "up --interactive --workspace special:omabox" "$out"; ob down "$B" >/dev/null; return; }
  check_match "up --interactive --workspace special:omabox: says how it shows and hides" \
    "is a window on special workspace omabox, which the bar widget's Show opens and a workspace switch hides" "$out"
  check_eq "...its window on special:omabox" special:omabox "$(ob hyprctl -b "$B" -j clients | jq -r '.[] | select(.class == "aquamarine") | .workspace.name')"
  check "...full size (not a half-height panel)" bash -c "'$CLI' hyprctl -b '$B' -j clients | jq -e '.[] | select(.class == \"aquamarine\") | .size[0] > 1800 and .size[1] > 1000'"
  check "...not shown, nothing focused, the stand-in still on 1" bash -c "'$CLI' hyprctl -b '$B' -j monitors | jq -e '.[0].specialWorkspace.name == \"\" and .[0].activeWorkspace.name == \"1\"' && '$CLI' hyprctl -b '$B' -j activewindow | jq -e '.class == null'"
  "${in[@]}" "$CLI" run -b sw -d -- foot -T clock sh -c 'while :; do date +%T.%N; sleep 0.2; done' >/dev/null 2>&1
  "${in[@]}" "$CLI" wait -b sw window clock >/dev/null 2>&1
  # shellcheck disable=SC2329 # called through check
  drawn() { "${in[@]}" "$CLI" shot -b sw -o /tmp/sw-a.png >/dev/null 2>&1 && sleep 1 && "${in[@]}" "$CLI" shot -b sw -o /tmp/sw-b.png >/dev/null 2>&1 &&
    "${in[@]}" sh -c '! cmp -s /tmp/sw-a.png /tmp/sw-b.png'; }
  check "...drawn while hidden: two shots a second apart differ" drawn
  "${in[@]}" "$CLI" peek -b sw --focus >/dev/null 2>&1
  check "Show (peek --focus) opens special:omabox" until_ok 5 shown special:omabox
  check_eq "...and focuses the box's window" aquamarine "$(ob hyprctl -b "$B" -j activewindow | jq -r .class)"
  ob hyprctl -b "$B" dispatch "hl.dsp.focus({ workspace = '2' })" >/dev/null
  check "a workspace switch hides it" until_ok 5 shown ""
  check "...still drawn while hidden" drawn
  "${in[@]}" "$CLI" peek -b sw --focus >/dev/null 2>&1
  check "Show again: shown over workspace 2" until_ok 5 shown special:omabox
  # The stand-in's own screen, where the window is: it moves with the clock (frames reach the host).
  ob shot -b "$B" -g "0,0 960x1080" -o "$TMP/sw-1.png" >/dev/null 2>&1; sleep 1
  ob shot -b "$B" -g "0,0 960x1080" -o "$TMP/sw-2.png" >/dev/null 2>&1
  check "...and up to date there: two shots of the stand-in a second apart differ" bash -c "! cmp -s '$TMP/sw-1.png' '$TMP/sw-2.png'"
  ob hyprctl -b "$B" dispatch "hl.dsp.focus({ workspace = '1' })" >/dev/null
  "${in[@]}" "$CLI" down sw >/dev/null 2>&1
  # A peek window there too: full size, hidden until shown.
  "${in[@]}" "$CLI" up swp --no-shell --idle 0 >/dev/null 2>&1
  out=$("${in[@]}" "$CLI" peek -b swp --workspace special:omabox 2>&1)
  check_match "peek --workspace special:omabox: says how it shows and hides" "on special workspace omabox, which the bar widget's Show opens" "$out"
  check "...its window on special:omabox, full size" until_ok 10 bash -c "'$CLI' hyprctl -b '$B' -j clients | jq -e '.[] | select(.class == \"omabox-peek\") | .workspace.name == \"special:omabox\" and .size[0] > 1800 and .size[1] > 1000'"
  check "...not shown" shown ""
  "${in[@]}" "$CLI" down --all >/dev/null 2>&1
  ob down "$B" >/dev/null
}

# `omabox clip` (issue #23, finding 119) with a box standing in for the host (finding 26) and interactive
# boxes nested in it: the clipboard is the stand-in's, never the user's. No agent runs in the box, so
# what clip refuses there is what it refuses, not the suite's own caller.
t_clip() {
  local B=$P-cl
  up_ok "$B" --net isolated --stock-bar --plugin "$ROOT/plugin" || { no "up (the stand-in host)" "$UP_OUT"; return; }
  local in=("$CLI" run -b "$B" --) H; H=$(ob path "$B")/home
  UP_OUT=$("${in[@]}" "$CLI" up ib --interactive --no-shell 2>&1) || { no "up --interactive in the stand-in" "$UP_OUT"; ob down "$B" >/dev/null; return; }
  local inb=("${in[@]}" "$CLI" run -b ib --) out rc
  local wins0 aw0; wins0=$(ob hyprctl -b "$B" -j clients | jq length); aw0=$(ob hyprctl -b "$B" -j activewindow | jq -r '.address // ""')
  "${in[@]}" sh -c 'printf "p4ss w\303\266rd\n" | wl-copy'
  out=$("${in[@]}" "$CLI" clip -b ib 2>&1)
  check_eq "clip: text into an interactive box, said by type and size" "omabox: handed text (text/plain;charset=utf-8, 11 bytes) from your clipboard to box 'ib'" "$out"
  check_eq "...on its clipboard byte for byte (the newline too)" "$(printf 'p4ss w\303\266rd\n' | od -An -c)" "$("${inb[@]}" sh -c 'wl-paste -n | od -An -c')"
  check_eq "...offered as text by its usual names" "STRING TEXT UTF8_STRING text/plain text/plain;charset=utf-8" "$("${inb[@]}" wl-paste --list-types | LC_ALL=C sort -u | xargs)"
  "${in[@]}" sh -c 'printf "pw" | wl-copy --sensitive'
  check_match "clip: a password manager's secret stays marked" "\(text/plain;charset=utf-8, 2 bytes, marked sensitive\)" "$("${in[@]}" "$CLI" clip -b ib 2>&1)"
  check "...for the box's clipboard history to leave out" "${inb[@]}" sh -c 'wl-paste --list-types | grep -qx x-kde-passwordManagerHint'
  "${in[@]}" sh -c 'printf "second" | wl-copy'
  check_match "with no -b: the only interactive box" "to box 'ib'$" "$("${in[@]}" "$CLI" clip 2>&1)"
  check_eq "...which has it" second "$("${inb[@]}" wl-paste -n)"
  # An image, by its type; a PNG of the stand-in's screen
  "${in[@]}" sh -c 'grim /tmp/clip.png && wl-copy --type image/png < /tmp/clip.png'
  check_match "clip: an image" "handed an image \(image/png, [0-9.]+ [KM]iB\)" "$("${in[@]}" "$CLI" clip -b ib 2>&1)"
  check_eq "...the same bytes, as image/png" "image/png $("${in[@]}" sh -c 'md5sum < /tmp/clip.png' | xargs)" "$("${inb[@]}" sh -c 'wl-paste --list-types | xargs; wl-paste -n | md5sum' | xargs)"
  "${in[@]}" sh -c 'wl-copy --type image/jpeg < /tmp/clip.png'
  "${in[@]}" "$CLI" clip -b ib >/dev/null 2>&1
  check_eq "...a JPEG as image/jpeg" image/jpeg "$("${inb[@]}" wl-paste --list-types)"
  # What is refused: nothing to hand over, a type that is neither text nor an image
  "${in[@]}" sh -c 'printf x | wl-copy --type application/x-omabox-test'
  out=$("${in[@]}" "$CLI" clip -b ib 2>&1); rc=$?
  check_match "clip: another type refused" "holds application/x-omabox-test : only text and images go into a box" "$out"
  check_eq "...exit 1, the box's clipboard as it was" "1 image/jpeg" "$rc $("${inb[@]}" wl-paste --list-types)"
  "${in[@]}" wl-copy --clear
  check_match "clip: an empty clipboard" "your clipboard is empty: nothing handed over" "$("${in[@]}" "$CLI" clip -b ib 2>&1)"
  "${in[@]}" sh -c 'printf "" | wl-copy'
  check_match "clip: an empty item" "the item is empty: nothing handed over" "$("${in[@]}" "$CLI" clip -b ib 2>&1)"
  # --from-box: the mirror
  "${inb[@]}" sh -c 'printf "from the box" | wl-copy'
  check_eq "clip --from-box: text" "omabox: handed text (text/plain;charset=utf-8, 12 bytes) from box 'ib' to your clipboard" "$("${in[@]}" "$CLI" clip --from-box -b ib 2>&1)"
  check_eq "...on the host's clipboard" "from the box" "$("${in[@]}" wl-paste -n)"
  "${inb[@]}" sh -c 'printf "box secret" | wl-copy --sensitive'
  "${in[@]}" "$CLI" clip --from-box -b ib >/dev/null 2>&1
  check "clip --from-box: a secret stays marked on the host" "${in[@]}" sh -c 'wl-paste --list-types | grep -qx x-kde-passwordManagerHint'
  local hist=$H/.local/state/omarchy/clipboard-history.json
  check "...the host's clipboard history (Omarchy's) has the box's text" until_ok 5 grep -q "from the box" "$hist"
  check_fails "...not its secret" grep -q "box secret" "$hist"
  "${inb[@]}" sh -c 'grim /tmp/b.png && wl-copy --type image/png < /tmp/b.png'
  "${in[@]}" "$CLI" clip --from-box -b ib >/dev/null 2>&1
  check_eq "clip --from-box: an image, the same bytes" "image/png $("${inb[@]}" sh -c 'md5sum < /tmp/b.png' | xargs)" "$("${in[@]}" sh -c 'wl-paste --list-types | xargs; wl-paste -n | md5sum' | xargs)"
  "${inb[@]}" wl-copy --clear
  check_match "clip --from-box: an empty clipboard" "box 'ib''s clipboard is empty" "$("${in[@]}" "$CLI" clip --from-box -b ib 2>&1)"
  # One shot: on the host only the wl-copy serving the item (its own session, the fds of no file of
  # clip's), no wl-paste or omabox left; the host's windows and focus as they were.
  # shellcheck disable=SC2329 # called through until_ok
  one_server() { [ "$("${in[@]}" sh -c 'for p in $(pgrep -x wl-copy); do [ "$(readlink /proc/$p/ns/pid)" != "$(readlink /proc/self/ns/pid)" ] || echo $p; done' | wc -l)" = 1 ]; }
  check "clip left one wl-copy on the host: the one serving the item" until_ok 5 one_server
  # (the stand-in's shell watches its clipboard for Omarchy's history: wl-paste --watch)
  check_eq "...no wl-paste and no clip running, in the stand-in or its boxes" "" "$("${in[@]}" sh -c 'pgrep -a wl-paste | grep -v -- " --watch "; pgrep -af "omabox cli[p]"; true')"
  check_eq "...no process holds the item's file (wl-copy's stderr file: its own)" 0 "$("${in[@]}" sh -c 'ls -l /proc/[0-9]*/fd 2>/dev/null | grep -c omabox-clip-item')"
  check_eq "...the host's windows" "$wins0" "$(ob hyprctl -b "$B" -j clients | jq length)"
  check_eq "...and its focus unchanged" "$aw0" "$(ob hyprctl -b "$B" -j activewindow | jq -r '.address // ""')"
  # The bar widget's rows (Paste in, Copy out) run the real CLI in the stand-in
  printf '#!/bin/sh\nexec %q "$@"\n' "$CLI" > "$H/.local/bin/omabox"; chmod +x "$H/.local/bin/omabox"
  "${in[@]}" sh -c 'printf "via the widget" | wl-copy'
  # shellcheck disable=SC2329 # called through until_ok
  panel() { panel_takes_keys "$B"; }
  # shellcheck disable=SC2329 # called through until_ok
  has() { [ "$("${inb[@]}" wl-paste -n 2>/dev/null)" = "$1" ]; }
  # shellcheck disable=SC2329 # called through until_ok
  opens() { ob run -b "$B" -- omarchy-shell chaves.omabox open >/dev/null 2>&1; until_ok 1 panel >/dev/null; }
  # The stand-in had no omabox until now, so its widget draws nothing (#207) until a poll runs the
  # one just written: opened before that, it stays shut (and polls).
  listed() { until_ok 10 opens >/dev/null && ob keys -b "$B" Escape >/dev/null && sleep 2.5; }
  listed   # (the panel polls every 2 s while open: ib is in its list after that)
  ob run -b "$B" -- omarchy-shell chaves.omabox open; until_ok 3 panel
  ob keys -b "$B" Down v >/dev/null
  check "the widget's v pastes your clipboard into the box" until_ok 10 has "via the widget"
  "${inb[@]}" sh -c 'printf "out via the widget" | wl-copy'
  ob run -b "$B" -- omarchy-shell chaves.omabox open; until_ok 3 panel
  ob keys -b "$B" Down c >/dev/null
  check "...its c copies the box's out" until_ok 10 bash -c "[ \"\$('$CLI' run -b '$B' -- wl-paste -n)\" = 'out via the widget' ]"
  # Refused: a headless box (an agent's); several interactive ones and none focused; an agent
  "${in[@]}" "$CLI" up hb --no-shell >/dev/null 2>&1
  check_match "clip: a headless box refused" "box 'hb' is headless: clip is for interactive boxes only" "$("${in[@]}" "$CLI" clip -b hb 2>&1)"
  "${in[@]}" "$CLI" down hb >/dev/null 2>&1
  local pids0 pid2
  pids0=$(ob hyprctl -b "$B" -j clients | jq '[.[] | select(.class == "aquamarine") | .pid]')
  "${in[@]}" "$CLI" up ib2 --interactive --no-shell >/dev/null 2>&1
  pid2=$(ob hyprctl -b "$B" -j clients | jq --argjson o "$pids0" '[.[] | select(.class == "aquamarine") | .pid] - $o | .[0]')
  ob hyprctl -b "$B" dispatch "hl.dsp.focus({ window = 'class:^foot\$' })" >/dev/null 2>&1   # nothing there: no focus change
  check_match "with no -b, several interactive boxes and none focused: which one?" "interactive boxes ib ib2 are up and none has focus" "$("${in[@]}" "$CLI" clip 2>&1)"
  ob hyprctl -b "$B" dispatch "hl.dsp.focus({ window = 'pid:$pid2' })" >/dev/null
  "${in[@]}" sh -c 'printf "to the focused one" | wl-copy'
  check_match "...the one whose window has focus" "to box 'ib2'$" "$("${in[@]}" "$CLI" clip 2>&1)"
  check_eq "...which has it" "to the focused one" "$("${in[@]}" "$CLI" run -b ib2 -- wl-paste -n)"
  "${in[@]}" sh -c 'printf "secret" | wl-copy'; "${inb[@]}" wl-copy --clear
  # (the process named is omabox, the binary: bash's omabox named its own comm, bash, finding 441)
  check_match "clip refused to an agent's shell" "not for agents \(CLAUDECODE set for omabox, pid [0-9]+\)" "$("${in[@]}" env CLAUDECODE=1 "$CLI" clip -b ib 2>&1)"
  check_match "...with the variable dropped (env -u) under that shell" "not for agents \(CLAUDECODE set for bash" \
    "$("${in[@]}" env CLAUDECODE=1 bash -c 'env -u CLAUDECODE "$0" clip -b ib; true' "$CLI" 2>&1)"
  check_match "...under a program named claude, whatever the environment" "not for agents \(claude, pid" \
    "$("${in[@]}" sh -c 'cp /usr/bin/bash /tmp/claude && /tmp/claude -c "env -i PATH=/usr/bin HOME=\$HOME XDG_RUNTIME_DIR=\$XDG_RUNTIME_DIR \$0 clip -b ib; true" "$0"' "$CLI" 2>&1)"
  check_match "...under the guard" "not for agents" "$("${in[@]}" "${GUARDED[@]}" "$CLI" clip -b ib 2>&1)"
  check_match "...under guard exec" "not for agents" "$("${in[@]}" "$CLI" guard exec -- "$CLI" clip -b ib 2>&1)"
  check_match "...through omabox host" "not for agents" "$("${in[@]}" "${GUARDED[@]}" CLAUDECODE=1 "$CLI" host -- "$CLI" clip -b ib 2>&1)"
  check_eq "...and the box's clipboard got nothing" "" "$("${inb[@]}" wl-paste -n 2>/dev/null)"
  "${in[@]}" "$CLI" down --all >/dev/null 2>&1
  ob down "$B" >/dev/null
}

# keys-to-box and the passthrough indicator (issue #22, finding 117), in a stand-in host (finding 26):
# its Hyprland runs the host side (share/passthrough.lua), two interactive boxes are windows in it, and
# the stand-in's own keyboard presses the keys. Nothing reaches the real desktop.
t_keys_to_box() {
  local B=$P-kb
  up_ok "$B" --no-shell --net isolated || { no "up (the stand-in host)" "$UP_OUT"; return; }
  local in=("$CLI" run -b "$B" -- "$CLI")
  check_match "keys-to-box refuses a headless box" "is headless" "$(ob keys-to-box -b "$B" on 2>&1)"
  if ! UP_OUT=$("${in[@]}" up ka --interactive --no-shell 2>&1) || ! UP_OUT=$("${in[@]}" up kb --interactive --no-shell 2>&1); then
    no "up --interactive twice in the stand-in" "$UP_OUT"; ob down "$B" >/dev/null; return
  fi
  ob run -b "$B" -d -q -- foot
  # shellcheck disable=SC2329 # called through until_ok
  has_foot() { ob hyprctl -b "$B" -j clients | jq -e 'any(.class == "foot")' >/dev/null; }
  until_ok 10 has_foot
  # Each box's window by its client's pid: the box's outer bwrap, whose command line binds its run dir
  # (the first such bwrap; the one it forks has the same command line).
  local pa pb
  pa=$(ob run -b "$B" -- sh -c 'for p in $(pgrep -x bwrap); do tr "\0" " " < /proc/$p/cmdline | grep -q "/omabox/$1/run " && { echo "$p"; break; }; done' _ ka)
  pb=$(ob run -b "$B" -- sh -c 'for p in $(pgrep -x bwrap); do tr "\0" " " < /proc/$p/cmdline | grep -q "/omabox/$1/run " && { echo "$p"; break; }; done' _ kb)
  check_eq "...each box's window found by its pid" "aquamarine aquamarine" \
    "$(ob hyprctl -b "$B" -j clients | jq -r --argjson a "${pa:-0}" --argjson b "${pb:-0}" '[.[] | select(.pid == $a or .pid == $b) | .class] | join(" ")')"
  # shellcheck disable=SC2329 # called through check
  focus() { ob hyprctl -b "$B" dispatch "hl.dsp.focus({ window = '$1' })" >/dev/null; }
  # The stand-in's state: submap|focused class|border (our tag on it)|the box .keys names.
  # shellcheck disable=SC2329
  kstate() {
    printf '%s|%s' "$(ob lua -b "$B" 'local w = hl.get_active_window()
      local t = w and table.concat(w.tags, ",") or ""
      return hl.get_current_submap() .. "|" .. (w and w.class or "none") .. "|" .. (t:find("omabox%-keys") and "border" or "plain")')" \
      "$(ob run -b "$B" -- sh -c 'cat "$XDG_RUNTIME_DIR/omabox/.keys" 2>/dev/null')"
  }
  # shellcheck disable=SC2329
  kis() { local s; s=$(kstate); [ "$s" = "$1" ] || { echo "$s"; return 1; }; }
  # shellcheck disable=SC2329
  kre() { local s; s=$(kstate); [[ $s =~ $1 ]] || { echo "$s"; return 1; }; }
  # shellcheck disable=SC2329
  box_ws() { [ "$("${in[@]}" hyprctl -b "$1" -j activeworkspace | jq -r .name)" = "$2" ]; }
  # shellcheck disable=SC2329
  host_ws() { [ "$(ob hyprctl -b "$B" -j activeworkspace | jq -r .name)" = "$1" ]; }
  # The stand-in's pointer to the middle of its window pid:N.
  # shellcheck disable=SC2329
  to_mid() {
    local xy; xy=$(ob hyprctl -b "$B" -j clients | jq -r --arg s "$1" '[.[] | select("pid:\(.pid)" == $s)][0]
      | "\(.at[0] + (.size[0] / 2 | floor)) \(.at[1] + (.size[1] / 2 | floor))"')
    ob pointer -b "$B" -- move "${xy% *}" "${xy#* }" >/dev/null
  }
  local red; red=$(sed -n 's/^red *= *"#\([0-9a-fA-F]\{6\}\)".*/\1/p' "$(ob path "$B")/home/.local/state/omarchy/current/theme/colors.toml" | tr 'A-F' 'a-f')
  red=ff${red:-ff5555}
  check_eq "keys-to-box is off by default" off "$("${in[@]}" keys-to-box -b ka)"
  check "keys-to-box -b ka on" "${in[@]}" keys-to-box -b ka on
  check_eq "...ls --json says so, for that box only" "ka:true kb:false" \
    "$("${in[@]}" ls --json | jq -r '[.[] | "\(.name):\(.keys_to_box)"] | join(" ")')"
  focus "pid:$pa"
  check "focusing its window enters the submap, border and widget file on" until_ok 5 kis "omabox|aquamarine|border|ka"
  check_eq "...its border the theme's red" "$red 0deg" "$(ob hyprctl -b "$B" getprop "pid:$pa" active_border_color)"
  focus class:foot
  check "focus elsewhere leaves it, border and file back" until_ok 5 kis "|foot|plain|"
  check_fails "...its border no longer red" grep -q "^$red" <<<"$(ob hyprctl -b "$B" getprop "pid:$pa" active_border_color)"
  focus "pid:$pa"
  check "...focused again: the submap again" until_ok 5 kis "omabox|aquamarine|border|ka"
  ob keys -b "$B" super+2 >/dev/null
  check "SUPER+2 goes to the box" until_ok 5 box_ws ka 2
  check_eq "...not to the host" 9 "$(ob hyprctl -b "$B" -j activeworkspace | jq -r .name)"
  ob keys -b "$B" super+alt+Escape >/dev/null
  check "SUPER+ALT+ESCAPE gets the keys back, the box still focused" until_ok 5 kis "|aquamarine|plain|"
  ob pointer -b "$B" -- move 2 2 >/dev/null; to_mid "pid:$pa"
  check "...the pointer leaving the box and coming back does not undo that" holds 1 kis "|aquamarine|plain|"
  ob keys -b "$B" super+1 >/dev/null
  check "...SUPER+1 is the host's then" until_ok 5 host_ws 1
  focus "pid:$pa"
  check "...until the box loses focus and gets it back" until_ok 5 kis "omabox|aquamarine|border|ka"
  focus "pid:$pb"
  check "a box without keys-to-box: focus does not enter it" until_ok 5 kis "|aquamarine|plain|"
  # One-shot, as before, with the indicator too.
  ob keys -b "$B" super+alt+Escape >/dev/null
  check "one-shot (SUPER+ALT+ESCAPE on kb): submap, border and file" until_ok 5 kis "omabox|aquamarine|border|kb"
  ob pointer -b "$B" -- move 2 2 >/dev/null   # the stand-in's corner: off every box window
  ob keys -b "$B" a >/dev/null
  check "...a key with the pointer off the box ends it (finding 29)" until_ok 5 kis "|aquamarine|plain|"
  # issue #55: in keys-to-box the pointer decides too. The box alone on a workspace of the stand-in's
  # (5): the pointer on an empty corner (where a bar would be) gives the keys back, keys-to-box on.
  ob hyprctl -b "$B" dispatch "hl.dsp.window.move({ workspace = '5', window = 'pid:$pa' })" >/dev/null
  focus "pid:$pa"; to_mid "pid:$pa"
  check "keys-to-box, the box alone on its workspace, the pointer over it: the submap" until_ok 5 kis "omabox|aquamarine|border|ka"
  ob pointer -b "$B" -- move 2 2 >/dev/null
  check "...the pointer off it: submap, border and file off, the box still focused" until_ok 5 kis "|aquamarine|plain|"
  check_eq "...keys-to-box still on" on "$("${in[@]}" keys-to-box -b ka)"
  ob keys -b "$B" super+1 >/dev/null
  check "...SUPER+1 switches the stand-in's workspace, on the first press" until_ok 5 host_ws 1
  check "...not the box's" box_ws ka 2
  focus "pid:$pa"; ob pointer -b "$B" -- move 2 2 >/dev/null
  until_ok 5 kis "|aquamarine|plain|" >/dev/null
  to_mid "pid:$pa"
  check "...the pointer back over the box: the submap, border and file again" until_ok 5 kis "omabox|aquamarine|border|ka"
  ob keys -b "$B" super+3 >/dev/null
  check "...SUPER+3 goes to the box" until_ok 5 box_ws ka 3
  check_eq "...not to the stand-in" 5 "$(ob hyprctl -b "$B" -j activeworkspace | jq -r .name)"
  # The key pressed right after the pointer moved, before the timer has looked: the key hook runs
  # before Hyprland looks the key up in the binds, so it decides for that very key (the timer off here).
  ob lua -b "$B" 'omabox_pass_timer:set_enabled(false)' >/dev/null
  ob pointer -b "$B" -- move 2 2 >/dev/null
  check "...with no timer the submap is still on" holds 0.5 kis "omabox|aquamarine|border|ka"
  ob keys -b "$B" super+1 >/dev/null
  check "...and SUPER+1 still switches the stand-in's workspace, on the first press" until_ok 5 host_ws 1
  focus "pid:$pa"; ob pointer -b "$B" -- move 2 2 >/dev/null
  until_ok 5 kis "|aquamarine|plain|" >/dev/null
  ob lua -b "$B" 'omabox_pass_timer:set_enabled(false)' >/dev/null
  to_mid "pid:$pa"
  ob keys -b "$B" super+4 >/dev/null
  check "...the other way: SUPER+4 goes to the box" until_ok 5 box_ws ka 4
  check_eq "...not to the stand-in" 5 "$(ob hyprctl -b "$B" -j activeworkspace | jq -r .name)"
  focus class:foot; focus "pid:$pa"   # the timer back (focus starts it again)
  check "...focus starts the timer again" until_ok 3 test "$(ob lua -b "$B" 'return omabox_pass_timer:is_enabled()')" = true
  focus class:foot
  check "focus off the box stops it" until_ok 3 test "$(ob lua -b "$B" 'return omabox_pass_timer:is_enabled()')" = false
  focus "pid:$pa"; to_mid "pid:$pa"
  # A config reload drops the hooks, the binds and the rule; the box's reaper puts them back.
  ob hyprctl -b "$B" reload >/dev/null
  # shellcheck disable=SC2329
  reinstalled() { [ "$(ob lua -b "$B" 'return omabox_pass_version')" = 5 ]; }
  check "after a host reload the hooks come back (the reaper)" until_ok 6 reinstalled
  check "...with the submap, border and file as focus says" until_ok 3 kis "omabox|aquamarine|border|ka"
  check_eq "...one toggle bind in each submap" "omabox:1 :1" "$(ob hyprctl -b "$B" -j binds |
    jq -r '[.[] | select(.description | startswith("omabox:"))] | group_by(.submap) | map("\(.[0].submap):\(length)") | reverse | join(" ")')"
  focus class:foot; focus "pid:$pa"
  check "...and focus still drives it" until_ok 5 kis "omabox|aquamarine|border|ka"
  # A newer passthrough over an older one with no reload between (#113): the reaper installs it again;
  # its unbind takes the toggle out of both submaps.
  ob lua -b "$B" 'omabox_pass_version = 4' >/dev/null
  check "a newer passthrough over an older one: installed again" until_ok 6 reinstalled
  check_eq "...still one toggle bind in each submap" "omabox:1 :1" "$(ob hyprctl -b "$B" -j binds |
    jq -r '[.[] | select(.description | startswith("omabox:"))] | group_by(.submap) | map("\(.[0].submap):\(length)") | reverse | join(" ")')"
  focus class:foot; focus "pid:$pa"
  check "...focus drives it" until_ok 5 kis "omabox|aquamarine|border|ka"
  check "keys-to-box off with the box focused: the keys are the host's at once" "${in[@]}" keys-to-box -b ka off
  check "...submap, border and file off" until_ok 5 kis "|aquamarine|plain|"
  if aq_unfixed "${in[@]}"; then
    skip "a confirm-close keep keeps the keys-to-box box (issue #24)" "aquamarine without the fix for nested Wayland outputs: no keep (t_guard checks that)"
  else
    # issue #24: a confirm-close keep recreates the box's output (a new window, the same client).
    "${in[@]}" keys-to-box -b ka on >/dev/null 2>&1
    "${in[@]}" config confirm-close on >/dev/null
    ob hyprctl -b "$B" dispatch "hl.dsp.window.close({ window = 'pid:$pa' })" >/dev/null
    # shellcheck disable=SC2329
    reopened() { "${in[@]}" path ka >/dev/null && ob run -b "$B" -- test -f "$("${in[@]}" path ka)/run/omabox.reopened"; }
    check "confirm-close keeps the box, with a new window (issue #24)" until_ok 8 reopened
    "${in[@]}" config confirm-close off >/dev/null
    focus class:foot; focus "pid:$pa"
    check "after a confirm-close keep, its new window is still the keys-to-box box" until_ok 5 kis "omabox|aquamarine|border|ka"
  fi
  "${in[@]}" down ka >/dev/null 2>&1
  check "down with the box focused: nobody is left in the submap" until_ok 5 kre '^\|[a-z]*\|plain\|$'
  "${in[@]}" down --all >/dev/null 2>&1
  ob down "$B" >/dev/null
}

# Keys held when focus leaves an interactive box (finding 132), in a stand-in host (finding 26): SUPER
# held down in the box while the stand-in's focus moves to its foot, released there. aquamarine never
# heard the release, so the box's Hyprland kept SUPER down and a later W was SUPER+W (closed the window).
# omabox's aquamarine build releases what is held when the keyboard leaves.
# keys down:KEY / up:KEY (#230, finding 343): a key held across other commands by a holder the keyboard
# tool forks off in the box. The issue's case: a press bind and a release bind on one key, the pointer
# moved in between, each bind fired once and in order; modifiers held join another keyboard's keys
# (binds and the app); the release reaches the app (a held letter stops repeating); a key still held
# goes with the box.
t_keys_down_up() {
  local B=$P-kdu
  up_ok "$B" --no-shell --net isolated || { no "up" "$UP_OUT"; return; }
  check_box_safety "$B"
  ob lua -b "$B" 'hl.bind("XF86Tools", hl.dsp.event("tools-press"))
    hl.bind("XF86Tools", hl.dsp.event("tools-release"), { release = true })
    hl.bind("SUPER + A", hl.dsp.event("super-a"))' >/dev/null
  ob events -b "$B" --mark kdu >/dev/null 2>&1
  # shellcheck disable=SC2329 # called through until_ok and $(...)
  evs() { ob events -b "$B" --since kdu --grep '^custom>>' | awk '{ printf "%s%s", (NR > 1 ? " " : ""), $2 }'; }
  # shellcheck disable=SC2329
  evs_are() { [ "$(evs)" = "$1" ]; }
  check "keys down:XF86Tools" ob keys -b "$B" down:XF86Tools
  check "...its press bind fires" until_ok 5 evs_are custom'>>'tools-press
  check "...the holder runs in the box (its pid namespace)" ob run -b "$B" -- pgrep -f 'omabox-keyboard .*down:XF86Tools'
  check "pointer move with the key held" ob pointer -b "$B" -- move 100 100 move 400 300
  check_eq "...no release yet" "custom>>tools-press" "$(evs)"
  check_match "a second down: of it: refused" "down:XF86Tools: held already \(up:XF86Tools lets go\)" "$(ob keys -b "$B" down:XF86Tools 2>&1)"
  check "keys up:XF86Tools" ob keys -b "$B" up:XF86Tools
  check "...its release bind fires, once, after the press, and nothing else" until_ok 5 evs_are "custom>>tools-press custom>>tools-release"
  check_fails "...the holder is gone with the last held key" ob run -b "$B" -- pgrep -f 'omabox-keyboard .*down:'
  local out; out=$(ob keys -b "$B" up:XF86Tools 2>&1); local rc=$?
  check_eq "up: of a key not held: exit 1" 1 "$rc"
  check_match "...said" "up:XF86Tools: no key is held" "$out"
  check_match "a combo refused" "down:ctrl\+c: one key each" "$(ob keys -b "$B" down:ctrl+c 2>&1)"
  check_match "...no key refused" "down:: which key" "$(ob keys -b "$B" down: 2>&1)"
  check_match "...--pass with them refused" "down:/up: and --pass in calls of their own" "$(T_X=x "$CLI" keys -b "$B" --pass T_X down:a 2>&1)"
  # SUPER held by the holder, a from another keyboard: Hyprland joins them (SUPER+A).
  ob keys -b "$B" down:super >/dev/null
  ob keys -b "$B" a >/dev/null
  check_match "up:KEY not held, with another held: names what is" "up:shift: not held \(held: Super_L\)" "$(ob keys -b "$B" up:shift 2>&1)"
  ob keys -b "$B" up:super >/dev/null
  check "down:super, then keys a: SUPER+A" until_ok 5 evs_are "custom>>tools-press custom>>tools-release custom>>super-a"
  # A holder killed outright (finding 347): its key let go once, by the next keys, never twice.
  local e0="custom>>tools-press custom>>tools-release custom>>super-a" tp="custom>>tools-press custom>>tools-release"
  # shellcheck disable=SC2329
  kill_holder() { ob run -b "$B" -- sh -c 'kill -KILL $(pgrep -f "^/opt/omabox/bin/omabox-keyboard")'; }
  ob keys -b "$B" down:XF86Tools >/dev/null; kill_holder
  out=$(ob keys -b "$B" up:XF86Tools 2>&1); rc=$?
  check_eq "up: of a killed holder's key: exit 0 (the release is its)" 0 "$rc"
  check_match "...said" "killed with XF86Tools down: let go" "$out"
  check "...its release bind fires once" until_ok 5 evs_are "$e0 $tp"
  ob keys -b "$B" down:XF86Tools >/dev/null; kill_holder
  ob keys -b "$B" down:XF86Tools >/dev/null 2>&1; ob keys -b "$B" up:XF86Tools >/dev/null
  check "a killed holder's key pressed again: one release each" until_ok 5 evs_are "$e0 $tp $tp $tp"
  sleep 0.3
  check_eq "...and no more" "$e0 $tp $tp $tp" "$(evs)"
  # The app: shift held types capitals; a held letter repeats in it, and stops once let go.
  ob run -b "$B" -d -q -- foot --app-id=omabox.typed sh -c 'stty raw -echo; exec cat > /tmp/typed'
  until_ok 10 bash -c "'$CLI' hyprctl -b '$B' -j activewindow | jq -e '.class == \"omabox.typed\"'" >/dev/null
  # shellcheck disable=SC2329
  typed() { [ "$(ob run -b "$B" -- cat /tmp/typed 2>/dev/null)" = "$1" ]; }
  ob keys -b "$B" down:shift a >/dev/null; ob keys -b "$B" b up:shift c >/dev/null
  check "down:shift a, b, up:shift c: ABc" until_ok 5 typed ABc
  out=$(ob keys -b "$B" d up:super 2>&1); rc=$?
  check_eq "keys d up:super with nothing held: exit 1" 1 "$rc"
  check_match "...said" "up:super: no key is held" "$out"
  sleep 0.3
  check "...before typing the d" typed ABc
  # shellcheck disable=SC2329
  size() { ob run -b "$B" -- stat -c %s /tmp/typed; }
  # shellcheck disable=SC2329
  grown() { [ "$(size)" -ge "$1" ]; }
  ob keys -b "$B" down:x >/dev/null
  check "a held x repeats in the app" until_ok 5 grown 8
  ob keys -b "$B" up:x >/dev/null
  sleep 0.3; local n1 n2; n1=$(size); sleep 1; n2=$(size)
  check_eq "...and stops once let go (the release reaches it)" "$n1" "$n2"
  # Held at down: gone with the box; the next box of that name has none.
  ob keys -b "$B" down:XF86Tools >/dev/null
  local hp; hp=$(pgrep -f 'omabox-keyboard .*down:XF86Tools' | head -1)
  check "a key held at down: its holder seen" test -n "$hp"
  ob down "$B" >/dev/null
  check_fails "...gone with the box" test -e "/proc/${hp:-0}"
  up_ok "$B" --no-shell --net isolated || { no "up again" "$UP_OUT"; return; }
  check_match "...the next box of that name holds nothing" "up:XF86Tools: no key is held" "$(ob keys -b "$B" up:XF86Tools 2>&1)"
  ob down "$B" >/dev/null
}

t_held_keys() {
  local B=$P-hk
  up_ok "$B" --no-shell --net isolated || { no "up (the stand-in host)" "$UP_OUT"; return; }
  local in=("$CLI" run -b "$B" -- "$CLI")
  # (Asked of this omabox: the stand-in's own sees the build it binds at /opt/omabox/lib, not its name.)
  if ! ob --version 2>/dev/null | grep -q '^aquamarine: a private build, .*+keys'; then
    skip "a key held when focus leaves an interactive box is released there" "not omabox's aquamarine build (omabox setup --aquamarine)"
    ob down "$B" >/dev/null; return
  fi
  UP_OUT=$("${in[@]}" up hk --interactive --no-shell 2>&1) || { no "up --interactive in the stand-in" "$UP_OUT"; ob down "$B" >/dev/null; return; }
  ob run -b "$B" -d -q -- foot
  # What the box's foot is given, byte by byte, in its /tmp.
  "${in[@]}" run -b hk -d -q -- foot --app-id=omabox.typed sh -c 'stty raw -echo; dd bs=1 of=/tmp/typed 2>/dev/null'
  # shellcheck disable=SC2329 # called through until_ok
  ready() { ob hyprctl -b "$B" -j clients | jq -e 'any(.class == "foot")' >/dev/null &&
    "${in[@]}" hyprctl -b hk -j clients | jq -e 'any(.class == "omabox.typed")' >/dev/null; }
  until_ok 10 ready
  local pa
  pa=$(ob run -b "$B" -- sh -c 'for p in $(pgrep -x bwrap); do tr "\0" " " < /proc/$p/cmdline | grep -q "/omabox/hk/run " && { echo "$p"; break; }; done')
  # shellcheck disable=SC2329
  focus() { ob hyprctl -b "$B" dispatch "hl.dsp.focus({ window = '$1' })" >/dev/null; }
  # shellcheck disable=SC2329
  typed() { [ "$("${in[@]}" run -b hk -- cat /tmp/typed 2>/dev/null)" = "$1" ]; }
  focus "pid:$pa"
  ob keys -b "$B" -t a >/dev/null
  check "the box's foot gets a key typed in its window" until_ok 5 typed a
  # SUPER down in the box (-m), the stand-in's focus moved off it while held (-p waits), released there.
  ob run -b "$B" -- sh -c 'sleep 3 | /opt/omabox/bin/omabox-keyboard -m super -p 2000' >/dev/null 2>&1 &
  local kb=$!
  sleep 0.5; focus class:foot; wait "$kb"
  focus "pid:$pa"
  ob keys -b "$B" -t w >/dev/null
  check "...after SUPER was held while focus left: W is a W, not SUPER+W" until_ok 5 typed aw
  check "...and the window is still there" bash -c "'$CLI' run -b '$B' -- '$CLI' hyprctl -b hk -j clients | jq -e 'any(.class == \"omabox.typed\")' >/dev/null"
  "${in[@]}" down --all >/dev/null 2>&1
  ob down "$B" >/dev/null
}

# `up` on a box that is up (finding 134): the options given that it lacks are refused, saying which;
# a bare up, or one with what it has, is fine. --json prints it as ls --json lists it.
t_up_again() {
  local B=$P-ua out
  up_ok "$B" --net isolated --no-shell || { no "up" "$UP_OUT"; return; }
  check "up again, no options: fine" ob up "$B"
  check "...with the options it has" ob up "$B" --net isolated --no-shell
  out=$(ob up "$B" --size 1280x720 --systemd 2>&1); local rc=$?
  check_eq "...with others: refused" 1 "$rc"
  check_match "...saying what it lacks" "--size 1280x720@60 \(it is 1920x1080@60\); --systemd \(it has no user manager\)" "$out"
  check_match "...and what to do" "omabox down $B first, or omabox up --new" "$out"
  check_match "--net connected on an isolated box: refused" "--net connected \(it is isolated\)" "$(ob up "$B" --net connected 2>&1)"
  check_match "--plugin it has not: refused, naming plugin add (#345)" "--plugin $ROOT/plugin \(not mounted: omabox plugin add $ROOT/plugin -b $B adds it\)" "$(ob up "$B" --plugin "$ROOT/plugin" 2>&1)"
  check_eq "up --json: the box as ls --json has it" "$B up isolated" "$(ob up "$B" --json 2>/dev/null | jq -r '"\(.name) \(.state) \(.net)"')"
  check_eq "...the same object" "$(ob ls --json | jq -c --arg n "$B" '.[] | select(.name == $n)')" "$(ob up "$B" --json 2>/dev/null)"
  # #264: an app's read-only folder in the box HOME (a walk testing a destination it cannot write).
  local h; h=$(readlink -f "$(ob path -b "$B")/home/..") || h=""
  ob run -b "$B" -- sh -c 'mkdir -p ~/locked/dest && touch ~/locked/dest/f && chmod a-w ~/locked/dest ~/locked'
  out=$(ob down "$B" 2>&1)
  check_eq "down removes a HOME an app left read-only dirs in (#264)" "absent|omabox: box '$B' down" \
    "$([ -n "$h" ] && [ ! -e "$h" ] && echo absent || echo "left: $h")|$out"
}

# up --theme-dir (#170, finding 240): a theme under development goes in live, not as a copy made at
# `up`. One in the repo up runs from (in the box at its own path already), one elsewhere (mounted
# read-only at its own path); the box HOME's themes/ links to each, and omarchy-theme-set applies one.
t_theme_dir() {
  local B=$P-td r o=$TMP/$P-td-out/b D
  r=$(tmp_repo td-repo); mkdir -p "$r/themes/td-a" "$o"
  cp "$HOME/.local/state/omarchy/current/theme/colors.toml" "$r/themes/td-a/colors.toml"
  echo one > "$o/marker"
  (cd "$r" && up_ok "$B" --no-shell --theme-dir themes/td-a --theme-dir "$o") || { no "up --theme-dir" "$UP_OUT"; return; }
  D=$(ob path -b "$B")
  check_eq "box.json has the theme dirs, resolved" "[\"$r/themes/td-a\",\"$o\"]" "$(jq -c .theme_dirs "$D/box.json")"
  check_eq "the box HOME's themes/ links to the one in the repo" "$r/themes/td-a" "$(ob run -b "$B" -- readlink /home/sbx/.config/omarchy/themes/td-a)"
  check_eq "...and to the one elsewhere" "$o" "$(ob run -b "$B" -- readlink /home/sbx/.config/omarchy/themes/b)"
  check_eq "...which is in the box at its own path" one "$(ob run -b "$B" -- cat "$o/marker")"
  echo two > "$o/marker"; echo '# edited after up' >> "$r/themes/td-a/colors.toml"
  check_eq "an edit after up reaches the box: live" two "$(ob run -b "$B" -- cat /home/sbx/.config/omarchy/themes/b/marker)"
  check_eq "...in the repo's too" "# edited after up" "$(ob run -b "$B" -- tail -1 /home/sbx/.config/omarchy/themes/td-a/colors.toml)"
  check_fails "...read-only there" ob run -b "$B" -- sh -c "echo x > '$o/marker'"
  check "omarchy-theme-set applies the linked theme" ob run -b "$B" -- sh -c 'omarchy-theme-set td-a >/dev/null 2>&1'
  check_eq "...as it is now" "td-a # edited after up" \
    "$(ob run -b "$B" -- sh -c 'echo "$(cat ~/.local/state/omarchy/current/theme.name) $(tail -1 ~/.local/state/omarchy/current/theme/colors.toml)"')"
  check_match "up again with other theme dirs: refused, saying which it has" "already up, without what you asked for: --theme-dir \(it has $r/themes/td-a, $o\)" \
    "$(cd "$r" && ob up "$B" --theme-dir themes/td-a 2>&1)"
  check "...with the same ones: fine" bash -c "cd '$r' && '$CLI' up '$B' --theme-dir themes/td-a --theme-dir '$o'"
  ob down "$B" >/dev/null 2>&1
}

# The desk's look as the desk has it (#184), on a fake desk (HOME and the XDG dirs a folder of the
# test's): a background of the user's own (~/.config/omarchy/backgrounds/THEME) is the box's, as a copy
# its link leads to, the shell starting on it; with --theme NAME, NAME's own; a theme cloned from git
# is still one to omarchy-theme-set (its Lua ignored).
t_desk_backgrounds() {
  local B=$P-db fh=$TMP/$P-db-home c u cur=/home/sbx/.local/state/omarchy/current D
  c=$fh/.local/state/omarchy/current u=$fh/.config/omarchy/backgrounds
  rm -rf "$fh"; mkdir -p "$c" "$u/tokyo-night" "$u/nord" "$fh/.config/omarchy/themes/gitty/.git" "$fh/.config/omarchy/themes/mine"
  cp -r /usr/share/omarchy/themes/tokyo-night "$c/theme"; echo tokyo-night > "$c/theme.name"
  magick -size 64x64 xc:'#ff00ff' "$u/tokyo-night/zz-mine.png"; magick -size 64x64 xc:'#00ffff' "$u/nord/zz-mine.png"
  ln -s "$u/tokyo-night/zz-mine.png" "$c/background"
  for t in gitty mine; do
    cp /usr/share/omarchy/themes/nord/colors.toml "$fh/.config/omarchy/themes/$t/"
    echo 'hl.config({ general = { gaps_out = 77 } })' > "$fh/.config/omarchy/themes/$t/hyprland.lua"
  done
  echo '[core]' > "$fh/.config/omarchy/themes/gitty/.git/config"
  # shellcheck disable=SC2329 # called below
  fake() { env HOME="$fh" XDG_CONFIG_HOME="$fh/.config" XDG_DATA_HOME="$fh/.local/share" XDG_CACHE_HOME="$fh/.cache" \
    XDG_STATE_HOME="$fh/.local/state" "$CLI" "$@"; }
  UP_OUT=$(fake up "$B" --net isolated --stock-bar 2>&1) || { no "up on a fake desk" "$UP_OUT"; return; }
  check_eq "the desk's background one of the user's: the box's link leads to its copy" \
    "/home/sbx/.config/omarchy/backgrounds/tokyo-night/zz-mine.png" "$(ob run -b "$B" -- readlink -e "$cur/background")"
  check "...which is the user's image" cmp "$u/tokyo-night/zz-mine.png" "$(ob path -b "$B")/home/.config/omarchy/backgrounds/tokyo-night/zz-mine.png"
  check "...the box shows it" until_ok 15 bash -c "[ \"\$('$CLI' pixel -b '$B' 900 500)\" = '#ff00ff' ]"
  # Omarchy since omacom/omarchy#9639 starts the shell with the link resolved; an older one does not.
  if ob run -b "$B" -- sh -c 'grep -qs OMARCHY_STARTUP_BACKGROUND "$OMARCHY_PATH/bin/omarchy-launch-shell"'; then
    check_eq "...the shell started on it (OMARCHY_STARTUP_BACKGROUND)" "/home/sbx/.config/omarchy/backgrounds/tokyo-night/zz-mine.png" \
      "$(ob run -b "$B" -- sh -c 'tr "\0" "\n" < /proc/$(pgrep -xo quickshell)/environ | sed -n "s/^OMARCHY_STARTUP_BACKGROUND=//p"')"
  fi
  check "a theme cloned from git: an empty .git in the box's copy" ob run -b "$B" -- sh -c '[ -d ~/.config/omarchy/themes/gitty/.git ] && [ -z "$(ls -A ~/.config/omarchy/themes/gitty/.git)" ]'
  check_fails "...none in the user's own" ob run -b "$B" -- test -e /home/sbx/.config/omarchy/themes/mine/.git
  check_match "...omarchy-theme-set ignores its Lua, as on the desk" "Ignored in /home/sbx/.config/omarchy/themes/gitty: hyprland.lua" \
    "$(ob run -b "$B" -- omarchy-theme-set gitty 2>&1)"
  check_fails "...not in the theme it made" ob run -b "$B" -- grep -q gaps_out "$cur/theme/hyprland.lua"
  ob run -b "$B" -- omarchy-theme-set mine >/dev/null 2>&1
  check "...the user's own theme's Lua taken" ob run -b "$B" -- grep -q gaps_out "$cur/theme/hyprland.lua"
  fake down "$B" >/dev/null 2>&1
  UP_OUT=$(fake up "$B" --net isolated --stock-bar --theme nord 2>&1) || { no "up --theme nord on a fake desk" "$UP_OUT"; return; }
  D=$(ob path -b "$B")
  check_eq "up --theme nord: the user's own for nord, first of what omarchy-theme-set finds" \
    "/home/sbx/.config/omarchy/backgrounds/nord/zz-mine.png" "$(ob run -b "$B" -- readlink -e "$cur/background")"
  check_fails "...the desk's theme's not copied" test -e "$D/home/.config/omarchy/backgrounds/tokyo-night"
  check "...the box shows it" until_ok 15 bash -c "[ \"\$('$CLI' pixel -b '$B' 900 500)\" = '#00ffff' ]"
  fake down "$B" >/dev/null 2>&1
}

# up --theme NAME (finding 245): the box on that theme, not the desk's current one (a theme the desk is
# not on: tokyo-night, or nord on a desk on tokyo-night); over a save's look; refused when there is no
# such theme, before anything is made; a box whose omarchy-theme-set fails ends, saying why.
t_theme() {
  local B=$P-th B2=$P-th2 B3=$P-th3 S=$P-ths t=tokyo-night o=nord desk D H bg c T=$TMP/$P-th-tree
  desk=$(head -n 1 "$HOME/.local/state/omarchy/current/theme.name" 2>/dev/null) || desk=""
  [ "$desk" != "$t" ] || { t=nord; o=tokyo-night; }
  local cur=/home/sbx/.local/state/omarchy/current
  # The first background omarchy-theme-set finds for theme $1: the desk user's own first (seeded, #184),
  # else the theme's.
  # shellcheck disable=SC2329 # called below
  first_bg() {
    local f; f=$({ find "$HOME/.config/omarchy/backgrounds/$1/" -maxdepth 1 -type f ! -name '.*' \
      -iregex '.*\.\(jpe?g\|png\|gif\|bmp\|webp\)' 2>/dev/null || true; } | sort | head -n 1)
    if [ -n "$f" ]; then echo "/home/sbx/.config/omarchy/backgrounds/$1/${f##*/}"; return; fi
    f=$(cd "/usr/share/omarchy/themes/$1/backgrounds" && find . -maxdepth 1 -type f | sort | head -n 1)
    echo "$cur/theme/backgrounds/${f#./}"
  }
  check_match "an unknown theme: refused" "--theme: no theme $P-nope in " "$(ob up "$B" --theme "$P-nope" 2>&1)"
  check_fails "...before the box dir is made" test -e "$XDG_RUNTIME_DIR/omabox/$B"
  up_ok "$B" --net isolated --stock-bar --theme "$t" || { no "up --theme $t" "$UP_OUT"; return; }
  check_box_safety "$B"
  D=$(ob path -b "$B"); H=$D/home
  check_eq "box.json has the theme" "$t" "$(jq -r .theme "$D/box.json")"
  check_eq "...the box's theme.name is it, not the desk's ($desk)" "$t" "$(cat "$H/.local/state/omarchy/current/theme.name")"
  check "...its colors.toml the theme's" cmp "$H/.local/state/omarchy/current/theme/colors.toml" "/usr/share/omarchy/themes/$t/colors.toml"
  check "...its templates made (hyprland.lua)" test -s "$H/.local/state/omarchy/current/theme/hyprland.lua"
  check_eq "...its background the first omarchy-theme-set finds" "$(first_bg "$t")" "$(readlink "$H/.local/state/omarchy/current/background")"
  bg=$(sed -n 's/^background *= *"\(#[0-9a-fA-F]\{6\}\)".*/\1/p' "/usr/share/omarchy/themes/$t/colors.toml" | tr 'A-F' 'a-f')
  check "...the bar in the theme's background ($bg)" until_ok 15 bash -c "[ \"\$('$CLI' pixel -b '$B' 400 12)\" = '$bg' ]"
  check_eq "...ls --json says so" "$t" "$(ob ls --json | jq -r --arg n "$B" '.[] | select(.name == $n) | .theme')"
  check_match "up again with another theme: refused, saying which it has" "already up, without what you asked for: --theme $o \(it started on $t\)" \
    "$(ob up "$B" --theme "$o" 2>&1)"
  check "...with the same one: fine" ob up "$B" --theme "${t^}"
  # --from SAVE: the flag wins over the save's look.
  check "a save of it" sv save "$S" -b "$B"
  ob down "$B" >/dev/null 2>&1
  UP_OUT=$(sv up "$B2" --from "$S" --net isolated --no-shell --theme "$o" 2>&1) || { no "up --from with --theme" "$UP_OUT"; sv saves rm "$S" >/dev/null 2>&1; return; }
  H=$(ob path -b "$B2")/home
  check_eq "up --from a save on $t with --theme $o: on $o" "$o" "$(cat "$H/.local/state/omarchy/current/theme.name")"
  check "...its colors.toml $o's" cmp "$H/.local/state/omarchy/current/theme/colors.toml" "/usr/share/omarchy/themes/$o/colors.toml"
  check_eq "...its background $o's first" "$(first_bg "$o")" "$(readlink "$H/.local/state/omarchy/current/background")"
  ob down "$B2" >/dev/null 2>&1
  # Without the flag nothing changes: the desk's theme, from a save too.
  UP_OUT=$(sv up "$B2" --from "$S" --net isolated --no-shell 2>&1) || { no "up --from without --theme" "$UP_OUT"; sv saves rm "$S" >/dev/null 2>&1; return; }
  D=$(ob path -b "$B2")
  check_eq "up --from without --theme: the desk's theme, as before" "$desk" "$(cat "$D/home/.local/state/omarchy/current/theme.name")"
  check "...its colors.toml the desk's" cmp "$D/home/.local/state/omarchy/current/theme/colors.toml" "$HOME/.local/state/omarchy/current/theme/colors.toml"
  check_eq "...no theme in box.json" null "$(jq .theme "$D/box.json")"
  ob down "$B2" >/dev/null 2>&1
  sv saves rm "$S" >/dev/null 2>&1
  # Omarchy 4.5's intros (#291, finding 415; #293, finding 417): a theme with one (catppuccin's
  # wallpapers have intros/) kept a black start-up cover over the box for ~5 s after `up`, and
  # omarchy-theme-set to another reloaded Hyprland ~1 s after it returned.
  local it=catppuccin it2=everforest B4=$P-th4
  if [ -d "/usr/share/omarchy/themes/$it/backgrounds/intros" ] && [ -d "/usr/share/omarchy/themes/$it2/backgrounds/intros" ] &&
     grep -qsF background-intro.session-id /usr/share/omarchy/shell/services/BackgroundIntro.qml; then
    up_ok "$B4" --net isolated --stock-bar --theme "$it" || { no "up --theme $it" "$UP_OUT"; return; }
    check_fails "up --theme $it (it has intros): no start-up cover once up is back" bash -c "'$CLI' hyprctl -b '$B4' -j layers | jq -e '[.[].levels[\"3\"][]? | select(.namespace == \"omarchy-background\")] | length > 0'"
    check_eq "...the session marked as had (share/shell.sh)" \
      "$(ob run -b "$B4" -- sh -c 'echo "$HYPRLAND_INSTANCE_SIGNATURE"' 2>&1)" \
      "$(cat "$(ob path -b "$B4")/home/.local/state/omarchy/background-intro.session-id" 2>&1)"
    ob events -b "$B4" --mark "$P-ts" >/dev/null 2>&1
    ob run -b "$B4" -- omarchy-theme-set "$it2" >/dev/null 2>&1
    check "...omarchy-theme-set $it2 (intros too): Hyprland reloaded before it returned (no OWE in a box: no intro)" \
      ob events -b "$B4" --since "$P-ts" --until configreloaded --timeout 300ms
    ob down "$B4" >/dev/null 2>&1
  else
    skip "the start-up cover and intros of Omarchy 4.5 (#291)" "this Omarchy has no intro themes, or no start-up cover"   # omarchy<4.5
  fi
  # An omarchy-theme-set that fails in the box ends it, saying why.
  copy_omarchy "$T"
  rm -f "$T/bin/omarchy-theme-set"; printf '#!/bin/sh\necho "broken on purpose" >&2\nexit 3\n' > "$T/bin/omarchy-theme-set"; chmod +x "$T/bin/omarchy-theme-set"
  check_match "a failing omarchy-theme-set: up fails, saying why" "died while starting \(up --theme: omarchy-theme-set $t failed: broken on purpose" \
    "$(ob up "$B3" --net isolated --no-shell --omarchy "$T" --theme "$t" 2>&1)"
  check "...its dir kept for the logs it points at, unlike a signal's stop (finding 163, #388)" test -f "$(ob path "$B3")/box.json"
  ob down "$B3" >/dev/null 2>&1
}

# The host's submap after the last interactive box goes (finding 134), in a stand-in host (finding
# 26): a config reload there drops passthrough's hooks and keeps the submap, and only a box's reaper
# puts the hooks back. With that reaper gone too, `down` resets the submap, or the host's binds
# would stay dead.
t_submap_release() {
  local B=$P-sr
  up_ok "$B" --no-shell --net isolated || { no "up (the stand-in host)" "$UP_OUT"; return; }
  local in=("$CLI" run -b "$B" -- "$CLI")
  # Another tool's host rule (finding 136): every aquamarine window floating, on a workspace of its own.
  ob hyprctl -b "$B" eval 'hl.window_rule({ name = "nested-float", match = { class = "aquamarine" }, float = true, workspace = "name:nested silent" })' >/dev/null
  UP_OUT=$("${in[@]}" up sa --interactive --no-shell 2>&1) || { no "up --interactive in the stand-in" "$UP_OUT"; ob down "$B" >/dev/null; return; }
  check_eq "under a host rule for every aquamarine window, the box's is still tiled on workspace 9" "9 false" \
    "$(ob hyprctl -b "$B" -j clients | jq -r '.[] | select(.class == "aquamarine") | "\(.workspace.name) \(.floating)"')"
  local pa
  pa=$(ob run -b "$B" -- sh -c 'for p in $(pgrep -x bwrap); do tr "\0" " " < /proc/$p/cmdline | grep -q "/omabox/sa/run " && { echo "$p"; break; }; done')
  ob hyprctl -b "$B" dispatch "hl.dsp.focus({ window = 'pid:$pa' })" >/dev/null
  # shellcheck disable=SC2329 # called through until_ok
  submap_is() { [ "$(ob lua -b "$B" 'return hl.get_current_submap()')" = "$1" ]; }
  ob keys -b "$B" super+alt+Escape >/dev/null
  check "SUPER+ALT+ESCAPE: the stand-in in the omabox submap" until_ok 5 submap_is omabox
  ob run -b "$B" -- sh -c 'pkill -f "_reap sa "'
  ob hyprctl -b "$B" reload >/dev/null
  check "a reload with the box's reaper gone: still in it, the hooks gone" holds 2.5 bash -c \
    "[ \"\$('$CLI' lua -b '$B' 'return hl.get_current_submap() .. \",\" .. tostring(omabox_pass_version)')\" = omabox,nil ]"
  "${in[@]}" down sa >/dev/null 2>&1
  check "down of the last interactive box resets it" until_ok 3 submap_is ""
  ob keys -b "$B" super+1 >/dev/null
  check "...and the stand-in's SUPER+1 works again" until_ok 3 bash -c "[ \"\$('$CLI' hyprctl -b '$B' -j activeworkspace | jq -r .name)\" = 1 ]"
  ob down "$B" >/dev/null
}

# setup's questions answered through a terminal (script(1)), in a box with the shell (finding 133):
# the widget put in the box's bar, a "no" remembered; under a system install, a ~/.local/bin/omabox
# left from a checkout offered to go.
t_setup_prompts() {
  local B=$P-sp
  up_ok "$B" --net isolated || { no "up" "$UP_OUT"; return; }
  local H; H=$(ob path "$B")/home
  # shellcheck disable=SC2329
  in_tty() { printf '%s' "$1" | ob run -b "$B" -- script -qec "$CLI setup" /dev/null 2>&1; }
  local answers=$'y\n' sys=0
  if [[ $ROOT == /usr/* ]]; then
    sys=1; answers=$'y\ny\n'; mkdir -p "$H/.local/bin"; ln -sfn /nowhere/omabox/bin/omabox "$H/.local/bin/omabox"
  fi
  # finding 539 (#397): without a terminal, the widget's line works as soon as setup is done. The box's
  # shell does not watch its plugins dir (finding 196), so without setup's rescan the widget stayed
  # unknown to it ("is not known"), as a desktop's shell is for the moment its watcher takes.
  local out; out=$(ob run -b "$B" -- "$CLI" setup </dev/null 2>&1)
  check_match "setup without a terminal: the widget's line" "bar widget: not asked \(no terminal\): omarchy plugin enable chaves\.omabox" "$out"
  check "...which works right away (#397)" ob run -b "$B" -- omarchy plugin enable chaves.omabox
  check "...the widget in the box's bar" until_ok 5 grep -q '"chaves.omabox"' "$H/.config/omarchy/shell.json"
  ob run -b "$B" -- omarchy plugin disable chaves.omabox >/dev/null 2>&1
  until_ok 5 bash -c "! grep -q '\"chaves.omabox\"' '$H/.config/omarchy/shell.json'"
  out=$(in_tty "$answers")
  check_match "setup in a terminal asks to show the widget" "Show the omabox widget in your bar\? \[Y/n\]" "$out"
  check "...yes: it is in the box's bar" until_ok 5 grep -q '"chaves.omabox"' "$H/.config/omarchy/shell.json"
  if [ "$sys" = 1 ]; then
    check_match "...a checkout's ~/.local/bin/omabox: said" "links to /nowhere/omabox/bin/omabox, which is gone" "$out"
    check_fails "...yes: removed" test -L "$H/.local/bin/omabox"
  else
    skip "a checkout's ~/.local/bin/omabox under a system install: said and removed" "a checkout run (--installed checks it)"
  fi
  check_match "setup again: on, not asked" "bar widget: on in your bar" "$(in_tty "")"
  ob run -b "$B" -- omarchy plugin disable chaves.omabox >/dev/null 2>&1
  until_ok 5 bash -c "! grep -q '\"chaves.omabox\"' '$H/.config/omarchy/shell.json'"
  # (#373: the end of input at the question, Ctrl-D: a no, said; not remembered, so asked again)
  out=$(in_tty "")
  check_match "...Ctrl-D at the question: a no, said (#373)" "end of input: no, to this and any question after it" "$out"
  check "...not in the bar, and not remembered" bash -c "! grep -q '\"chaves.omabox\"' '$H/.config/omarchy/shell.json' && ! test -e '$H/.config/omabox/widget-declined'"
  out=$(in_tty $'n\n')
  check "...no: not in the bar, and remembered" bash -c "! grep -q '\"chaves.omabox\"' '$H/.config/omarchy/shell.json' && test -e '$H/.config/omabox/widget-declined'"
  check_match "...then not asked again" "bar widget: not asked \(you said no before" "$(in_tty "")"
  ob down "$B" >/dev/null
}

# `up --omarchy DIR` (finding 135): a box on another Omarchy tree, a copy of the installed one with a
# marker in its bin and its Hyprland bootstrap. The session, the bar, `run` and a terminal's bash (its
# /etc/omarchy.conf) all use it; a box started inside that one, without --omarchy, does not follow the
# outer box's /etc/omarchy.conf (as a box does not follow the host's dev link).
# copy_omarchy DIR: the installed Omarchy as a tree of files of our own (themes linked: the bulk).
copy_omarchy() {
  local T=$1 f
  mkdir -p "$T"
  for f in /usr/share/omarchy/*; do
    case ${f##*/} in themes) ln -s "$f" "$T/themes" ;; *) cp -a "$f" "$T/" ;; esac
  done
  chmod -R u+w "$T"
}

t_omarchy_tree() {
  local B=$P-ot T=$TMP/omarchy-tree
  copy_omarchy "$T"
  # (The package's bin/ links to /usr/bin: a file of its own in the link's place.)
  rm -f "$T/bin/omarchy-version"; printf '#!/bin/sh\necho omabox-tree\n' > "$T/bin/omarchy-version"; chmod +x "$T/bin/omarchy-version"
  printf '\nomabox_tree_marker = "tree"\n' >> "$T/default/hypr/bootstrap.lua"
  # Its own xkb files (#293, finding 420), as a 4.5 checkout has them in etc/xkb, unlike this host's.
  local xk=/etc/xkb/symbols/omarchy
  mkdir -p "$T/etc/xkb/symbols" "$T/etc/xkb/rules"
  { cat "$xk" 2>/dev/null; printf '// omabox-tree-xkb\n'; } > "$T/etc/xkb/symbols/omarchy"
  [ ! -f /etc/xkb/rules/evdev ] || cp /etc/xkb/rules/evdev "$T/etc/xkb/rules/evdev"
  check_match "--omarchy refuses a folder that is not an Omarchy tree" "not an Omarchy tree \(no bin\)" "$(ob up "$B" --omarchy "$TMP" 2>&1)"
  up_ok "$B" --net isolated --omarchy "$T" || { no "up --omarchy" "$UP_OUT"; return; }
  check_box_safety "$B"
  check_eq "the box's Hyprland loaded the tree's config" tree "$(ob lua -b "$B" 'return omabox_tree_marker')"
  check_eq "...run has it as OMARCHY_PATH" "$T" "$(ob run -b "$B" -- sh -c 'echo "$OMARCHY_PATH"')"
  check_eq "...and its bin first" omabox-tree "$(ob run -b "$B" -- omarchy-version)"
  check_match "...the bar runs from it" "quickshell --log-times -n -p $T/shell" "$(ob run -b "$B" -- pgrep -a quickshell)"
  check_eq "...a terminal's bash too (the box's /etc/omarchy.conf)" "$T omabox-tree" "$(ob run -b "$B" -- bash -ic 'echo "$OMARCHY_PATH $(omarchy-version)"' 2>/dev/null)"
  check_eq "...its etc/xkb over the host's /etc/xkb (finding 420)" "// omabox-tree-xkb" "$(ob run -b "$B" -- tail -n 1 "$xk" 2>&1)"
  check_eq "...the keymap compiled (a keyboard with it)" true \
    "$(ob hyprctl -b "$B" -j devices | jq '[.keyboards[]? | select(.active_keymap != "")] | length > 0')"
  check_eq "ls --json names it" "$T" "$(ob ls --json | jq -r --arg n "$B" '.[] | select(.name == $n) | .omarchy')"
  check_eq "...and its version as dev (no git: no commit)" dev "$(ob ls --json | jq -r --arg n "$B" '.[] | select(.name == $n) | .omarchy_version')"
  # Committed, then edited, after up: restart-shell records it as it is now.
  local ov; ov() { ob ls --json | jq -r --arg n "$B" '.[] | select(.name == $n) | .omarchy_version'; }
  git -C "$T" init -q && git -C "$T" add -A && git -C "$T" -c user.name=t -c user.email=t@t commit -qm t
  ob restart-shell -b "$B" >/dev/null 2>&1
  check_eq "...its commit after restart-shell" "dev $(git -C "$T" rev-parse --short HEAD)" "$(ov)"
  echo '-- edited' >> "$T/default/hypr/bootstrap.lua"; ob restart-shell -b "$B" >/dev/null 2>&1
  check_eq "...+dirty once edited" "dev $(git -C "$T" rev-parse --short HEAD)+dirty" "$(ov)"
  check_match "up again with another tree: refused" "--omarchy /usr/share/omarchy" "$(ob up "$B" --omarchy /usr/share/omarchy 2>&1)"
  # A box in that box, on the installed Omarchy: the outer /etc/omarchy.conf names the tree.
  local in=("$CLI" run -b "$B" -- "$CLI")
  if UP_OUT=$("${in[@]}" up oi --no-shell 2>&1); then
    check_eq "a box started where /etc/omarchy.conf names another tree runs the installed Omarchy" "/usr/share/omarchy" \
      "$("${in[@]}" run -b oi -- bash -ic 'echo "$OMARCHY_PATH"' 2>/dev/null)"
    "${in[@]}" down oi >/dev/null 2>&1
  else
    no "up inside the --omarchy box" "$UP_OUT"
  fi
  ob down "$B" >/dev/null
}

# The shell's lock screen in a box (finding 186): the system menu's Lock takes a real session lock,
# keys go to the lock and not the window under it, a wrong password keeps it, the right one gives the
# desktop back with that window focused. A box cannot read /etc/shadow, so the tree's lock asks a
# PAM config of the test's (pam_exec, a test password) instead of /etc/pam.d's.
t_lock() {
  local B=$P-lk T=$TMP/lock-tree K=$TMP/lockpam addr svc
  copy_omarchy "$T"
  svc=$T/shell/plugins/lock/Service.qml
  if ! grep -q '^    config: "omarchy-lock-password"$' "$svc"; then
    no "the lock's PamContext is where the test expects it" "no 'config: \"omarchy-lock-password\"' line in $svc"; return
  fi
  sed -i 's|^    config: "omarchy-lock-password"$|&\n    configDirectory: "/opt/omabox-lockpam"|' "$svc"
  mkdir -p "$K"
  printf '%s' omabox-lock-pw > "$K/password"
  printf '#!/bin/bash\nIFS= read -r -d "" pw || true\n[ "$pw" = "$(cat /opt/omabox-lockpam/password)" ]\n' > "$K/check"
  chmod +x "$K/check"
  printf 'auth required pam_exec.so expose_authtok quiet /opt/omabox-lockpam/check\naccount required pam_permit.so\n' \
    > "$K/omarchy-lock-password"
  up_ok "$B" --net isolated --omarchy "$T" --ro-bind "$K:/opt/omabox-lockpam" || { no "up with the lock's test PAM" "$UP_OUT"; return; }
  check_box_safety "$B"
  # A terminal whose input goes to a file: anything typed into it while locked would land there.
  ob run -b "$B" -d -q --wait -- foot sh -c 'cat > "$HOME/typed"' >/dev/null 2>&1
  addr=$(ob hyprctl -b "$B" -j activewindow | jq -r .address)
  ob keys -b "$B" super+escape >/dev/null
  check "SUPER+ESCAPE opens the system menu" ob wait -b "$B" --timeout 5s layer omarchy-menu
  ob keys -b "$B" -t Lock Return >/dev/null
  check "its Lock takes a session lock" ob wait -b "$B" --timeout 5s until -- omarchy-hyprland-session-locked
  ob wait -b "$B" --timeout 5s still --quiet 300ms >/dev/null
  OMABOX_T_PW=wrong-pw ob keys -b "$B" --pass OMABOX_T_PW Return >/dev/null
  ob wait -b "$B" --timeout 5s still --quiet 300ms >/dev/null
  check "a wrong password keeps it locked" ob run -b "$B" -- omarchy-hyprland-session-locked
  check_match "...the lock asked the test's PAM config" 'with config "omarchy-lock-password" in dir "/opt/omabox-lockpam"' "$(ob log -b "$B" shell -n all)"
  ob wait -b "$B" --timeout 10s still --quiet 1s >/dev/null
  OMABOX_T_PW=omabox-lock-pw ob keys -b "$B" --pass OMABOX_T_PW Return >/dev/null
  check "the right password unlocks it" ob wait -b "$B" --timeout 10s until -- sh -c '! omarchy-hyprland-session-locked'
  check_eq "...the window from before is focused again" "$addr" "$(ob hyprctl -b "$B" -j activewindow | jq -r .address)"
  check_eq "...and got none of the keys typed while locked" "" "$(ob run -b "$B" -- cat /home/sbx/typed 2>&1)"
  ob keys -b "$B" -t unlocked Return >/dev/null
  check "...though it gets them now (the check above can see a leak)" ob wait -b "$B" --timeout 5s until -- grep -qx unlocked /home/sbx/typed
  ob down "$B" >/dev/null
}

# Window selectors and what covers what (finding 81), on hyprctl JSON made up for it: floats above
# tiled windows whatever their order, later above earlier otherwise, fullscreen and a shown special
# workspace above the rest; off-screen workspaces, inactive group tabs and unmapped windows.
t_unit_window_select() {
  local c m m_sp act='{"address":"0xb"}'
  # windows' table (#105, finding 174): a title's quotes escaped once, as in --json; an empty class
  # keeps its column (the title starts at the 99th character, after the six padded ones).
  local rows; rows=$(probe windows_table <<<'[
    {"address":"0xa","pid":7,"workspace":1,"onscreen":true,"cover":[],"active":true,"size":[10,20],"at":[1,2],"class":"foot","title":"say \"hi\" \\ x"},
    {"address":"0xb","pid":8,"workspace":2,"onscreen":false,"cover":[],"active":false,"size":[3,4],"at":[5,6],"class":"","title":"no class"}]')
  check_eq "windows: a quoted title escaped once" '"say \"hi\" \\ x"' "$(sed -n 1p <<<"$rows" | cut -c99-)"
  check_eq "...an empty class keeps its column" '"no class"' "$(sed -n 2p <<<"$rows" | cut -c99-)"
  check_match "...the rest in theirs" '^0xb +8 +2 +off-screen +3x4 at 5,6 +"no class"$' "$(sed -n 2p <<<"$rows")"
  c=$(jq -nc '
    def w($a; $cl; $t; $ws; $x; $y; $w; $h; $fl): {address: $a, stableId: "1", class: $cl, title: $t,
      initialClass: $cl, initialTitle: $t, pid: 10, workspace: {id: $ws, name: ($ws | tostring)}, at: [$x, $y],
      size: [$w, $h], floating: $fl, fullscreen: 0, xwayland: false, mapped: true, hidden: false};
    [w("0xf"; "zenity"; "Question"; 1; 100; 100; 300; 200; true),
     w("0xa"; "foot"; "A"; 1; 0; 0; 1000; 1000; false) + {pid: 42, initialTitle: "first"},
     w("0xb"; "foot"; "B"; 1; 1000; 0; 900; 1000; false),
     w("0xg"; "foot"; "B tab"; 1; 1000; 0; 900; 1000; false) + {hidden: true},
     w("0x2"; "zenity"; "Other"; 1; 450; 350; 100; 100; true),
     w("0xc"; "Chromium"; "Docs - Chromium"; 5; 0; 0; 1900; 1000; false),
     w("0xh"; "org.gnome.Nautilus"; "Home"; 3; 0; 0; 800; 600; false),
     w("0xd"; "foot"; "scratch"; -98; 500; 500; 200; 200; true),
     w("0xe"; "foot"; "gone"; 1; 0; 0; 10; 10; false) + {mapped: false}]')
  m='[{"activeWorkspace":{"id":1},"specialWorkspace":{"id":0}}]'
  m_sp='[{"activeWorkspace":{"id":1},"specialWorkspace":{"id":-98}}]'
  local W Wsp; W=$(probe win_annotate "$c" "$m" "$act") Wsp=$(probe win_annotate "$c" "$m_sp" "$act")
  sel() { probe win_select "$W" "$@" 2>/dev/null | jq -r .address; }
  check_eq "title:RE" 0xa "$(sel 'title:^A$')"
  check_eq "a word: part of the title, any case" 0xc "$(sel docs)"
  check_eq "a word: the class, any case" 0xc "$(sel chromium)"
  check_eq "a word: a reverse-DNS class's last part (#20)" 0xh "$(sel nautilus)"
  check_eq "...whole, not a prefix of it" 2 "$(probe win_select "$W" naut >/dev/null 2>&1; echo $?)"
  check_eq "...the whole class still works" 0xh "$(sel org.gnome.nautilus)"
  check_eq "pid:N and a word, ANDed" 0xa "$(sel pid:42 foot)"
  check_eq "an address, any case" 0xa "$(sel 0xA)"
  check_eq "address:0x..." 0xa "$(sel address:0xa)"
  check_eq "active" 0xb "$(sel active)"
  check_eq "initialTitle:RE" 0xa "$(sel initialTitle:^first)"
  check_eq "class:RE ANDed with title:RE" 0x2 "$(sel class:zen 'title:^oth')"
  check_eq "several matches: exit 2" 2 "$(probe win_select "$W" foot >/dev/null 2>&1; echo $?)"
  check_match "...listing them" "matches 4 windows.*0xa.*0xb.*0xg.*0xd" "$(probe win_select "$W" foot 2>&1 | tr '\n' ' ')"
  check_eq "none: exit 2" 2 "$(probe win_select "$W" nope >/dev/null 2>&1; echo $?)"
  check_match "...listing the box's windows" "no window matches nope.*0xf" "$(probe win_select "$W" nope 2>&1 | tr '\n' ' ')"
  check_eq "an unmapped window is not a window" 2 "$(probe win_select "$W" 'title:^gone$' >/dev/null 2>&1; echo $?)"
  check_match "a bad regex: exit 2, said" "bad window selector" "$(probe win_select "$W" 'title:(' 2>&1; echo " rc=$?")"
  check_match "...rc 2" "rc=2" "$(probe win_select "$W" 'title:(' 2>&1; echo " rc=$?")"
  # A hyphen-separated part of the class (#244), only when nothing matches the word otherwise.
  local hc='[{"address":"0xp","class":"xdg-desktop-portal-gtk","title":"Back up","onscreen":true,"active":false,"workspace":"1"},
    {"address":"0xk","class":"xdg-desktop-portal-kde","title":"Open","onscreen":true,"active":false,"workspace":"1"},
    {"address":"0xn","class":"org.gnome.Nautilus","title":"Home","onscreen":true,"active":false,"workspace":"1"}]'
  hsel() { probe win_select "$1" "${@:2}" 2>/dev/null | jq -r .address; }
  check_eq "a word: a hyphen-separated part of the class (#244)" 0xp "$(hsel "$hc" gtk)"
  check_eq "...one in the middle" 0xk "$(hsel "$hc" kde)"
  check_match "...several: refused, each named" "matches 2 windows.*0xp.*0xk" "$(probe win_select "$hc" portal 2>&1 | tr '\n' ' ')"
  check_eq "...whole, not part of a part" 2 "$(probe win_select "$hc" port >/dev/null 2>&1; echo $?)"
  check_eq "...narrowed by another selector" 0xp "$(hsel "$hc" portal 'title:^back')"
  check_eq "...a whole class wins over it" 0xg "$(hsel "$(jq -c '. + [{"address":"0xg","class":"gtk","title":"x","onscreen":true,"active":false,"workspace":"2"}]' <<<"$hc")" gtk)"
  check_eq "...so does a title" 0xt "$(hsel "$(jq -c '. + [{"address":"0xt","class":"foot","title":"gtk notes","onscreen":true,"active":false,"workspace":"2"}]' <<<"$hc")" gtk)"
  check_eq "...wait window counts the same" "yes 2" "$(probe win_answer present "$hc" portal | cut -d' ' -f1-2)"
  # wait window (#37): any of several matching windows is an answer, and all are named.
  check_match "wait window: several match, satisfied, each named" '^yes 4 windows: 0xa foot "A" at 0,0 1000x1000; 0xb foot "B" at 1000,0 900x1000, focused; 0xg .*; 0xd ' "$(probe win_answer present "$W" foot)"
  check_match "...one: as before" '^yes 0xh org.gnome.Nautilus "Home" at 0,0 800x600$' "$(probe win_answer present "$W" nautilus)"
  check_eq "...none" no "$(probe win_answer present "$W" nope)"
  check_eq "--focused: the focused one of several" 'yes 0xb foot "B" at 1000,0 900x1000, focused (1 of 4 matching)' "$(probe win_answer focused "$W" foot)"
  check_eq "...several, none focused" "no 2 matching, none focused" "$(probe win_answer focused "$W" zenity)"
  check_eq "...one, not focused" 'no 0xa foot "A" is there' "$(probe win_answer focused "$W" 'title:^A$')"
  check_eq "--gone: several still there" "no 4 matching" "$(probe win_answer gone "$W" foot)"
  check_eq "a bad regex: exit 2 (never answerable)" 2 "$(probe win_answer present "$W" 'title:(' >/dev/null 2>&1; echo $?)"
  cov() { jq -r --arg a "$2" '.[] | select(.address == $a) | [.cover[].address] | join(" ")' <<<"$1"; }
  on() { jq -r --arg a "$2" '.[] | select(.address == $a) | .onscreen' <<<"$1"; }
  check_eq "floats cover the tiled window under them, though one is earlier in the list" "0xf 0x2" "$(cov "$W" 0xa)"
  check_eq "...a tiled window never covers a float" "" "$(cov "$W" 0xf)"
  check_eq "...a later float covers an earlier one" "0x2" "$(jq -r '.[] | select(.address == "0xf") | .cover[0].address // ""' <<<"$(probe win_annotate "$(jq -c 'map(if .address == "0x2" then .at = [150, 150] else . end)' <<<"$c")" "$m" "$act")")"
  check_eq "...and not the other way" "" "$(cov "$W" 0x2)"
  check_eq "another workspace is off screen" false "$(on "$W" 0xc)"
  check_eq "an inactive group tab is off screen" false "$(on "$W" 0xg)"
  check_eq "...and covers nothing" "" "$(cov "$W" 0xb)"
  check_eq "a hidden special workspace is off screen" false "$(on "$W" 0xd)"
  check_eq "a shown one is on screen" true "$(on "$Wsp" 0xd)"
  check_eq "...above the workspace under it" "0xf 0x2 0xd" "$(cov "$Wsp" 0xa)"
  local Wfs; Wfs=$(probe win_annotate "$(jq -c 'map(if .address == "0xa" then .fullscreen = 1 else . end)' <<<"$c")" "$m" "$act")
  check_eq "a fullscreen window: nothing covers it" "" "$(cov "$Wfs" 0xa)"
  check_eq "...it covers the rest" 0xa "$(cov "$Wfs" 0xf | tr ' ' '\n' | grep -x 0xa)"
  local A; A=$(jq -c '.[] | select(.address == "0xa")' <<<"$W")
  check_match "a point under the float is covered, named" "covered there by 0xf zenity" "$(probe win_blocked "$A" 150 150)"
  check_eq "a point beside it is not" "" "$(probe win_blocked "$A" 900 900)"
  check_match "off screen says so" "not on screen \(workspace 5\)" "$(probe win_blocked "$(jq -c '.[] | select(.address == "0xc")' <<<"$W")" 1 1)"
  # Layer surfaces over windows (#263): top and overlay only, bottom to top, not 1x1 hidden menus,
  # not over an off-screen window, not a top one over a workspace with a real fullscreen window.
  local l Wl
  l='{"M":{"levels":{"0":[{"namespace":"bg","pid":1,"x":0,"y":0,"w":1920,"h":1080}],"1":[],
    "2":[{"namespace":"bar","pid":1,"x":0,"y":0,"w":42,"h":1080},{"namespace":"panel","pid":1,"x":1000,"y":500,"w":50,"h":50}],
    "3":[{"namespace":"toast","pid":1,"x":1500,"y":0,"w":400,"h":100},{"namespace":"menu","pid":1,"x":0,"y":0,"w":1,"h":1},
         {"namespace":"osd","pid":1,"x":20,"y":500,"w":100,"h":100}]}}}'
  lay() { jq -r --arg a "$2" '.[] | select(.address == $a) | [.layers[] | "\(.namespace):\(.layer)"] | join(" ")' <<<"$1"; }
  check_eq "no LAYERS: no layers field" null "$(jq -c '.[0].layers' <<<"$W")"
  Wl=$(probe win_annotate "$c" "$m" "$act" "$l")
  check_eq "layers over a tiled window: the bar (top) and an overlay, bottom to top; not the background nor a 1x1 menu" "bar:top osd:overlay" "$(lay "$Wl" 0xa)"
  check_eq "...a top panel and a toast over the other one" "panel:top toast:overlay" "$(lay "$Wl" 0xb)"
  check_eq "...none over an off-screen window" "" "$(lay "$Wl" 0xc)"
  check_eq "...none over a float clear of them" "" "$(lay "$Wl" 0x2)"
  local Wf2 Wf1
  Wf2=$(probe win_annotate "$(jq -c 'map(if .address == "0xa" then .fullscreen = 2 else . end)' <<<"$c")" "$m" "$act" "$l")
  check_eq "a real fullscreen window (2): top layers pass it by, overlays not" "osd:overlay" "$(lay "$Wf2" 0xa)"
  check_eq "...nor over another window on its workspace" "toast:overlay" "$(lay "$Wf2" 0xb)"
  Wf1=$(probe win_annotate "$(jq -c 'map(if .address == "0xa" then .fullscreen = 1 else . end)' <<<"$c")" "$m" "$act" "$l")
  check_eq "...a maximized one (1): they count" "bar:top osd:overlay" "$(lay "$Wf1" 0xa)"
  A=$(jq -c '.[] | select(.address == "0xa")' <<<"$Wl")
  check_eq "win_layer: the one over the point" 'certain "osd" overlay 100x100 at 20,500' "$(probe win_layer "$A" 50 550)"
  check_eq "...the bar's" 'certain "bar" top 42x1080 at 0,0' "$(probe win_layer "$A" 10 10)"
  check_eq "...nothing beside them" "" "$(probe win_layer "$A" 500 500)"
  check_eq "...the topmost of two (an overlay over the bar)" 'certain "osd" overlay 100x100 at 20,500' "$(probe win_layer "$A" 30 550)"
  check_eq "...the edge is outside (x + w)" "" "$(probe win_layer "$A" 120 550)"
  check_eq "...a window without the field: nothing" "" "$(probe win_layer "$(jq -c '.[] | select(.address == "0xa")' <<<"$W")" 10 10)"
  check_eq "windows: one line per layer, naming the windows under it" \
    'layer "toast" (overlay 400x100 at 1500,0 on M) is over 0xb: where it takes input, input there goes to it' \
    "$(probe windows_layers <<<"$Wl" | grep toast)"
  check_eq "...nothing without layers" "" "$(probe windows_layers <<<"$W")"
  check_eq "...each layer certain while the monitors have no geometry" "true" \
    "$(jq -c '[.[] | .layers[]? | .certain] | unique | map(tostring) | join(",")' -r <<<"$Wl")"
  check_eq "...each names its monitor (#316)" "M" "$(jq -r '[.[] | .layers[]? | .monitor] | unique | join(",")' <<<"$Wl")"
  # A full-screen layer (#263, finding 398: Omarchy's notifications, input on their toasts only) is
  # possibly over a point; one smaller than its output for certain, and a certain one wins.
  local mg ln Wn
  mg='[{"name":"M","x":0,"y":0,"width":1920,"height":1080,"scale":1,"transform":0,"activeWorkspace":{"id":1},"specialWorkspace":{"id":0}}]'
  ln=$(jq -c '.M.levels["3"] += [{"namespace":"notif","pid":2,"x":0,"y":0,"w":1920,"h":1080}]' <<<"$l")
  Wn=$(probe win_annotate "$c" "$mg" "$act" "$ln")
  check_eq "a full-screen overlay: certain false; the smaller ones true" "bar:true osd:true notif:false" \
    "$(jq -r '.[] | select(.address == "0xa") | [.layers[] | "\(.namespace):\(.certain)"] | join(" ")' <<<"$Wn")"
  A=$(jq -c '.[] | select(.address == "0xa")' <<<"$Wn")
  check_eq "win_layer: only the full-screen one there: possible" 'possible "notif" overlay 1920x1080 at 0,0' "$(probe win_layer "$A" 500 500)"
  check_eq "...a smaller one under it: that one, certain (certain wins over possible)" 'certain "osd" overlay 100x100 at 20,500' "$(probe win_layer "$A" 50 550)"
  check_eq "...a top one (the bar) under it: certain too" 'certain "bar" top 42x1080 at 0,0' "$(probe win_layer "$A" 10 10)"
  check_eq "windows: a full-screen layer spans the screen, possibly over the windows" \
    'layer "notif" (overlay 1920x1080 at 0,0 on M) spans the screen, possibly over 0xf, 0xa, 0xb, 0x2: input goes to it only where one of its items (a toast, a dock icon) is, elsewhere to the window' \
    "$(probe windows_layers <<<"$Wn" | grep notif)"
  check_eq "...a smaller one still is over them" \
    'layer "toast" (overlay 400x100 at 1500,0 on M) is over 0xb: where it takes input, input there goes to it' "$(probe windows_layers <<<"$Wn" | grep '^layer "toast"')"
  whole() { jq -r --argjson m "$1" --arg mon "${3:-M}" "$("$PROBE" _rust-jq LAYER_SPAN_JQ) ($2 | spans(\$m; \$mon))" -n; }
  check_eq "whole: the output's size at scale 2 (3840x2160 mode, 1920x1080 logical)" true \
    "$(whole "$(jq -c '.[0] += {width: 3840, height: 2160, scale: 2}' <<<"$mg")" '{x: 0, y: 0, w: 1920, h: 1080}')"
  check_eq "...turned (transform 1): 1080x1920" "true false" \
    "$(whole "$(jq -c '.[0].transform = 1' <<<"$mg")" '{x: 0, y: 0, w: 1080, h: 1920}') $(whole "$(jq -c '.[0].transform = 1' <<<"$mg")" '{x: 0, y: 0, w: 1920, h: 1080}')"
  check_eq "...a second output's origin" "true false" \
    "$(whole "$(jq -c '.[0] += {x: 1920}' <<<"$mg")" '{x: 1920, y: 0, w: 1920, h: 1080}') $(whole "$(jq -c '.[0] += {x: 1920}' <<<"$mg")" '{x: 0, y: 0, w: 1920, h: 1080}')"
  check_eq "...a layer short of the output, or an output not found: false" "false false" \
    "$(whole "$mg" '{x: 0, y: 0, w: 1920, h: 1046}') $(whole "$mg" '{x: 0, y: 0, w: 1920, h: 1080}' N)"
  # A strip as tall or wide as its output (#311, finding 421: Omarchy 4.5's notifications column and
  # dock, mapped while idle, input on their items only) spans it unless it reserves the edge it sits
  # on (a bar); with the reserved edges unknown, only a whole one.
  local mr; mr=$(jq -c '.[0].reserved = [0, 26, 0, 0]' <<<"$mg")
  check_eq "spans: a full-height column at the right, a full-width strip at the bottom, nothing reserved there" "true true" \
    "$(whole "$mr" '{x: 1455, y: 0, w: 465, h: 1080}') $(whole "$mr" '{x: 0, y: 873, w: 1920, h: 207}')"
  check_eq "...a full-width bar at the top that reserves it, and a left bar that reserves its edge: no" "false false" \
    "$(whole "$mr" '{x: 0, y: 0, w: 1920, h: 26}') $(whole "$(jq -c '.[0].reserved = [42, 0, 0, 0]' <<<"$mg")" '{x: 0, y: 0, w: 42, h: 1080}')"
  check_eq "...one under the bar (the height it leaves), and 4.5's dock beside a vertical bar (the width it leaves): yes" "true true" \
    "$(whole "$mr" '{x: 1455, y: 26, w: 465, h: 1054}') $(whole "$(jq -c '.[0].reserved = [42, 0, 0, 0]' <<<"$mg")" '{x: 42, y: 835, w: 1878, h: 245}')"
  check_eq "...a column shorter than that, or a strip narrower: no" "false false" \
    "$(whole "$mr" '{x: 1455, y: 26, w: 465, h: 900}') $(whole "$mr" '{x: 100, y: 873, w: 1820, h: 207}')"
  check_eq "...the reserved edges unknown: only a whole one" "false true" \
    "$(whole "$mg" '{x: 1455, y: 0, w: 465, h: 1080}') $(whole "$mg" '{x: 0, y: 0, w: 1920, h: 1080}')"
  local Wc; Wc=$(probe win_annotate "$c" "$mr" "$act" "$(jq -c '.M.levels["3"] += [{"namespace":"col","pid":2,"x":1455,"y":0,"w":465,"h":1080}]' <<<"$l")")
  check_eq "win_layer: under an idle column (4.5's notifications): possible" 'possible "col" overlay 465x1080 at 1455,0' \
    "$(probe win_layer "$(jq -c '.[] | select(.address == "0xb")' <<<"$Wc")" "$((1600 - $(jq -r '.[] | select(.address == "0xb") | .at[0]' <<<"$Wc")))" 500)"
  # Omarchy 4.5.0-rc2's bar surface spans the screen, input on its strip only (#407): the strip along
  # the edge its output reserves; with no edge known, as before (possible). (0xb: 1000,0 900x1000)
  local lb Wb; lb=$(jq -c '.M.levels["2"] = [{"namespace":"omarchy-bar","pid":1,"x":0,"y":0,"w":1920,"h":1080}] | .M.levels["3"] = []' <<<"$l")
  Wb=$(probe win_annotate "$c" "$mr" "$act" "$lb" | jq -c '.[] | select(.address == "0xb")')
  check_eq "rc2's screen-sized bar: nothing over a point below its strip (#407)" "" "$(probe win_layer "$Wb" 100 500)"
  check_eq "...its strip, the top 26 px its output reserves: certain there" 'certain "omarchy-bar" top 1920x26 at 0,0' "$(probe win_layer "$Wb" 100 10)"
  Wb=$(probe win_annotate "$c" "$(jq -c '.[0].reserved = [0, 0, 0, 30]' <<<"$mg")" "$act" "$lb" | jq -c '.[] | select(.address == "0xb")')
  check_eq "...at the bottom: the strip there, over no point of the window" "|" "$(probe win_layer "$Wb" 100 10)|$(probe win_layer "$Wb" 100 990)"
  Wb=$(probe win_annotate "$c" "$mg" "$act" "$lb" | jq -c '.[] | select(.address == "0xb")')
  check_eq "...no edge known: the whole screen, possibly (as before)" 'possible "omarchy-bar" top 1920x1080 at 0,0' "$(probe win_layer "$Wb" 100 500)"
  # --in (finding 81): image pixel -> screen pixel under its centre: screen.rs img_px_as_bash.
}

# Window-targeted shot, click and keys, and --in (finding 81), with the box's own windows: two
# tiled terminals, a float over one, others on hidden workspaces.
t_window() {
  local B=$P-win
  up_ok "$B" --no-shell --net isolated || { no "up" "$UP_OUT"; return; }
  term() { ob run -b "$B" -d -- foot -T "$1" sh -c "$2" >/dev/null; until_ok 10 bash -c "'$CLI' hyprctl -b '$B' -j clients | jq -e '.[] | select(.title == \"$1\")'"; }
  win() { ob windows -b "$B" --json | jq -c --arg t "$1" '.[] | select(.title == $t)'; }
  addr() { win "$1" | jq -r .address; }
  at() { win "$1" | jq -r '"\(.at[0] + ('"${2:-0}"')), \(.at[1] + ('"${3:-0}"'))"'; }
  size() { win "$1" | jq -r '"\(.size[0]) x \(.size[1])"'; }
  disp() { ob hyprctl -b "$B" dispatch "$1" >/dev/null; }
  pos() { ob hyprctl -b "$B" cursorpos; }
  term A 'sleep 600'; term B 'sleep 600'
  ob wait -b "$B" still >/dev/null   # A shrinks as B opens: its buffer is the window's size once that settles
  local o=$TMP/win
  mkdir -p "$o"
  check_eq "an ambiguous selector: exit 2" 2 "$(ob shot -b "$B" -w foot >/dev/null 2>&1; echo $?)"
  check_eq "0xdead: exit 2" 2 "$(ob shot -b "$B" -w 0xdead >/dev/null 2>&1; echo $?)"
  check_eq "click --window, ambiguous: exit 2 too" 2 "$(ob click -b "$B" --window foot 10 10 >/dev/null 2>&1; echo $?)"
  check_eq "click --window, no match: exit 2" 2 "$(ob click -b "$B" --window 0xdead 10 10 >/dev/null 2>&1; echo $?)"
  check_match "...no window matches, the windows listed" "no window matches 0xdead.*\"A\"" "$(ob shot -b "$B" -w 0xdead 2>&1 | tr '\n' ' ')"
  ob shot -b "$B" -w 'title:^A$' -o "$o/a.png" >/dev/null 2>&1
  check_match "shot --window: the window's size" "$(size A)," "$(file "$o/a.png")"
  check_match "windows lists them" "foot +\"B\"" "$(ob windows -b "$B")"
  # A float over A: A's own pixels still, and said to be covered
  term C 'sleep 600'
  local c; c=$(addr C)
  disp "hl.dsp.window.float({ action = 'enable', window = 'address:$c' })"
  disp "hl.dsp.window.resize({ x = 400, y = 300, window = 'address:$c' })"
  disp "hl.dsp.window.move({ x = 100, y = 100, window = 'address:$c' })"
  until_ok 5 bash -c "'$CLI' windows -b '$B' --json | jq -e '.[] | select(.title == \"A\") | .cover != []'"
  local err; err=$(ob shot -b "$B" -w 'title:^A$' -o "$o/a2.png" 2>&1 >/dev/null)
  check_match "a covered window: its full size" "$(size A)," "$(file "$o/a2.png")"
  check_match "...stderr says what covers it" "covered by $c foot \"C\"" "$err"
  ob click -b "$B" --window 'title:^A$' 10 10 >/dev/null 2>&1
  check_eq "click --window: window coordinates" "$(at A 10 10)" "$(pos)"
  check_match "a point under another window is refused, naming it" "covered there by $c" "$(ob click -b "$B" --window 'title:^A$' 150 150 2>&1)"
  check_fails "a point outside the window is refused" ob click -b "$B" --window B 5000 5
  # Another workspace: B moves to 5; a click raises it
  local b; b=$(addr B)
  disp "hl.dsp.window.move({ workspace = '5', follow = false, window = 'address:$b' })"
  until_ok 5 bash -c "'$CLI' windows -b '$B' --json | jq -e '.[] | select(.title == \"B\") | .onscreen == false'"
  check_fails "--no-raise refuses a window off screen" ob click -b "$B" --window B --no-raise 1 1
  check_eq "...and switches nothing" 1 "$(ob hyprctl -b "$B" -j activeworkspace | jq .id)"
  ob click -b "$B" --window B 20 30 >/dev/null 2>&1
  check_eq "click on a window on workspace 5 shows 5" 5 "$(ob hyprctl -b "$B" -j activeworkspace | jq .id)"
  check_eq "...and lands in it" "$(at B 20 30)" "$(pos)"
  err=$(ob shot -b "$B" --active -o "$o/act.png" 2>&1 >/dev/null)
  check_match "--active is the active window" "window $b " "$err"
  check_match "...its size" "$(size B)," "$(file "$o/act.png")"
  ob click -b "$B" --in "$o/act.png" 0 0 >/dev/null 2>&1
  check_eq "click --in a window shot: 0,0 is its corner" "$(at B)" "$(pos)"
  # Priming (finding 81): a window off screen that keeps redrawing stops getting frames; the first
  # capture after a while is from long ago. Its colour comes from a file.
  term P 'while :; do printf "\033[4%sm\033[2J" "$(cat /tmp/col 2>/dev/null || echo 1)"; sleep 0.05; done'
  disp "hl.dsp.window.move({ workspace = '6', follow = false, window = 'address:$(addr P)' })"
  sleep 0.5
  ob shot -b "$B" -w 'title:^P$' -o "$o/p1.png" >/dev/null 2>&1
  ob run -b "$B" -- sh -c 'echo 4 > /tmp/col'; sleep 1
  ob shot -b "$B" -w 'title:^P$' -o "$o/p2.png" >/dev/null 2>&1
  check_fails "a window off screen: the shot is fresh, not an old frame" cmp -s "$o/p1.png" "$o/p2.png"
  check_eq "...and shooting it switched nothing" 5 "$(ob hyprctl -b "$B" -j activeworkspace | jq .id)"
  # keys --window: focus, then type
  term K 'cat > /tmp/typed'
  disp "hl.dsp.window.move({ workspace = '7', follow = false, window = 'address:$(addr K)' })"
  ob keys -b "$B" --window 'title:^K$' -t hi Return ctrl+d >/dev/null 2>&1
  check "keys --window types into it" until_ok 5 ob run -b "$B" -- test -s /tmp/typed
  check_eq "...what was typed" hi "$(ob run -b "$B" -- cat /tmp/typed)"
  # --fit and --in on the screen
  err=$(ob shot -b "$B" -o "$o/full.png" 2>&1 >/dev/null)
  check_eq "a 1:1 shot says nothing extra" "" "$err"
  err=$(ob shot -b "$B" --fit 1000 -o "$o/fit.png" 2>&1 >/dev/null)
  check_match "--fit 1000: 1000 wide" "1000 x 562," "$(file "$o/fit.png")"
  check_match "...stderr names the factor and --in" "1000x562 image of the screen's 1920x1080 at 0,0 \(x1.92\); click with --in $o/fit.png" "$err"
  ob click -b "$B" --in "$o/fit.png" 500 270 >/dev/null 2>&1
  check_eq "click --in a scaled shot" "960, 519" "$(pos)"
  ob pointer -b "$B" --in "$o/fit.png" -- move 250 100 >/dev/null 2>&1
  check_eq "pointer --in" "480, 193" "$(pos)"
  err=$(ob shot -b "$B" -g "300,200 400x100" -o "$o/g.png" 2>&1 >/dev/null)
  check_match "-g says it is cropped" "400x100 image of the screen's 400x100 at 300,200" "$err"
  ob click -b "$B" --in "$o/g.png" 7 9 >/dev/null 2>&1
  check_eq "click --in a -g shot: from its origin" "307, 209" "$(pos)"
  # Past the screen (#240): cut to it, as a window's (grim padded the image with transparent pixels).
  err=$(ob shot -b "$B" -g "1900,1000 50x100" -o "$o/gc.png" 2>&1 >/dev/null)
  check_match "-g past the screen: the part on it" "20 x 80," "$(file "$o/gc.png")"
  check_match "...said, by edge" "-g clipped to 1900,1000 20x80 of the screen \(1920x1080\): 30 px past the right edge, 20 px past the bottom edge" "$err"
  check_match "-g with nothing on the screen refused in words" "has nothing on the screen \(1920x1080\)" "$(ob shot -b "$B" -g "1920,0 10x10" 2>&1)"
  check_match "--in a file that is not a shot: refused" "not a shot of box" "$(ob click -b "$B" --in /etc/hostname 1 1 2>&1)"
  check_match "--in outside the image: refused" "outside the image" "$(ob click -b "$B" --in "$o/g.png" 400 1 2>&1)"
  touch "$o/g.png"
  check_match "--in a file changed since: refused" "changed since" "$(ob click -b "$B" --in "$o/g.png" 1 1 2>&1)"
  # A window shot follows its window: C moved after the shot
  ob shot -b "$B" -w 'title:^C$' -o "$o/c.png" >/dev/null 2>&1
  disp "hl.dsp.window.move({ x = 700, y = 300, window = 'address:$c' })"
  until_ok 5 bash -c "'$CLI' windows -b '$B' --json | jq -e '.[] | select(.title == \"C\") | .at == [700, 300]'"
  ob click -b "$B" --in "$o/c.png" 5 6 >/dev/null 2>&1
  check_eq "click --in a window shot after the window moved: where it is now" "705, 306" "$(pos)"
  # -g inside --window (#27): in the window's coordinates, and --in maps from the crop's origin.
  err=$(ob shot -b "$B" -w 'title:^C$' -g "10,20,100,50" -o "$o/new/dir/cg.png" 2>&1 >/dev/null)
  check_match "shot -w -g: the crop's size (X,Y,W,H taken too; -o's folder made)" "100 x 50," "$(file "$o/new/dir/cg.png")"
  check_match "...stderr says where in the window" "100x50 of it at 10,20" "$err"
  ob click -b "$B" --in "$o/new/dir/cg.png" 5 6 >/dev/null 2>&1
  check_eq "click --in a window crop: from the crop's origin in the window" "715, 326" "$(pos)"
  # -g past the window (#240): cut to it and said so, exit 0; only one with nothing inside is refused.
  err=$(ob shot -b "$B" -w 'title:^C$' -g "390,10 20x20" -o "$o/cl.png" 2>&1 >/dev/null)
  check_eq "shot -w -g 10 px past the right edge: exit 0" 0 "$?"
  check_match "...the image is the part inside" "10 x 20," "$(file "$o/cl.png")"
  check_match "...said on stderr, with the edge and how far past" "-g clipped to 390,10 10x20 of window .* \(400x300; -g is in the window's coordinates\): 10 px past the right edge" "$err"
  ob click -b "$B" --in "$o/cl.png" 5 6 >/dev/null 2>&1
  check_eq "...click --in it: from the clipped crop's origin" "1095, 316" "$(pos)"
  check_match "-g with nothing inside the window refused" "has nothing inside window" "$(ob shot -b "$B" -w 'title:^C$' -g "400,10 20x20" 2>&1)"
  # --zoom's 2000 px on what is left once clipped (#240): 300 px wide as typed, 10 once cut to C.
  err=$(ob shot -b "$B" -w 'title:^C$' -g "390,10 300x10" --zoom 8 -o "$o/cz.png" 2>&1 >/dev/null)
  check_match "shot -w -g --zoom 8 that fits once clipped: taken (80x80)" "80 x 80," "$(file "$o/cz.png")"
  check_match "...said clipped" "-g clipped to 390,10 10x10 of window" "$err"
  check_match "shot --zoom past 2000 px refused, on the region inside" "of 300x10 is 2400x80: at most 2000 px" \
    "$(ob shot -b "$B" -w 'title:^C$' -g "0,0 300x10" --zoom 8 2>&1)"
  # pointer --window (#25): moves in the window's coordinates; --hold is omabox's own.
  ob pointer -b "$B" --window 'title:^C$' -- move 3 4 >/dev/null 2>&1
  check_eq "pointer --window: window coordinates" "703, 304" "$(pos)"
  check_match "pointer --hold refused" "omabox's own" "$(ob pointer -b "$B" -- --hold 2>&1)"
  # drag (#25): foot selects the text it is dragged across, into the primary selection.
  term T 'echo DRAGME-12345-67890; sleep 600'
  disp "hl.dsp.window.float({ action = 'enable', window = 'address:$(addr T)' })"
  disp "hl.dsp.window.move({ x = 50, y = 600, window = 'address:$(addr T)' })"
  until_ok 5 bash -c "'$CLI' windows -b '$B' --json | jq -e '.[] | select(.title == \"T\") | .at == [50, 600] and .cover == []'"
  ob wait -b "$B" still >/dev/null   # the move is animated: input goes where the window is drawn
  ob drag -b "$B" --window 'title:^T$' 2 10 300 10 --shot "$o/mid.png" >/dev/null 2>&1
  check_match "drag --window: the text dragged across is selected" "^DRAGME-12345" "$(ob run -b "$B" -- wl-paste -p -n 2>&1)"
  check_match "...--shot while the button was down" "PNG image" "$(file "$o/mid.png")"
  ob pointer -b "$B" --window 'title:^T$' -- move 2 10 down move 60 10 up >/dev/null 2>&1
  check_match "pointer down/up with no button: left" "^DRAGME$|^DRAGME-" "$(ob run -b "$B" -- wl-paste -p -n 2>&1)"
  check_match "drag --shot with --wait refused" "not both" "$(ob drag -b "$B" 1 1 5 5 --shot "$o/x.png" --wait 2>&1)"
  check_match "drag needs two points" "need X1 Y1 X2 Y2" "$(ob drag -b "$B" 1 1 5 2>&1)"
  ob mode -b "$B" 1280x720 >/dev/null
  check_match "--in after a mode change: refused" "mode is 1280x720@60" "$(ob click -b "$B" --in "$o/full.png" 1 1 2>&1)"
  ob down "$B" >/dev/null
}

# window (#362, finding 591): one window floated and sized by the box's own Hyprland (the run's
# watcher fails any of it reaching the host's, S8), centred, what it took said; tiled again.
t_window_size() {
  local B=$P-wsz out err rc
  up_ok "$B" --no-shell --net isolated || { no "up" "$UP_OUT"; return; }
  ob run -b "$B" -d -- foot -T A sleep 600 >/dev/null
  ob run -b "$B" -d -- foot -T B sleep 600 >/dev/null
  until_ok 10 bash -c "'$CLI' windows -b '$B' --json | jq -e 'length == 2'"
  ob wait -b "$B" still >/dev/null
  win() { ob windows -b "$B" --json | jq -c '.[] | select(.title == "A")'; }
  check_eq "two foot windows, A tiled" false "$(win | jq .floating)"
  check_eq "window with nothing to do: exit 2" 2 "$(ob window -b "$B" -w 'title:^A$' >/dev/null 2>&1; echo $?)"
  check_match "...saying what it takes" "--size WxH, --float or --tile" "$(ob window -b "$B" -w 'title:^A$' 2>&1)"
  check_match "--size not WxH: exit 2" "rc=2 .*--size is WxH .*got 760" "$(out=$(ob window -b "$B" --size 760 2>&1); echo "rc=$? $out")"
  check_match "--size and --tile: exit 2" "rc=2 .*not both" "$(out=$(ob window -b "$B" --size 760x500 --tile 2>&1); echo "rc=$? $out")"
  check_eq "a selector matching both: exit 2" 2 "$(ob window -b "$B" -w foot --size 760x500 >/dev/null 2>&1; echo $?)"
  out=$(ob window -b "$B" -w 'title:^A$' --size 760x540 2>"$TMP/wsz-err"); rc=$?
  check_eq "--size 760x540: exit 0, nothing on stderr" "0 " "$rc $(cat "$TMP/wsz-err")"
  check_match "...prints the window, floating, at its size" "^0x[0-9a-f]+ foot \"A\" floating at [0-9]+,[0-9]+ 760x540$" "$out"
  check_eq "...the box has it so" "true [760,540]" "$(win | jq -r '"\(.floating) \(.size | tojson)"')"
  # Centred on the free area: B tiles alone across it, so the centres meet (to a pixel of rounding).
  local cb ca
  cb=$(ob windows -b "$B" --json | jq -r '.[] | select(.title == "B") | "\(.at[0] + .size[0] / 2) \(.at[1] + .size[1] / 2)"')
  ca=$(win | jq -r '"\(.at[0] + .size[0] / 2) \(.at[1] + .size[1] / 2)"')
  check "...centred where the tiled window is ($ca; $cb)" awk -v a="$ca" -v b="$cb" 'BEGIN { split(a, p, " "); split(b, q, " "); d = p[1] - q[1]; e = p[2] - q[2]; exit !(d * d <= 4 && e * e <= 4) }'
  out=$(ob -b "$B" window -w 'title:^A$' --size 540x400 --json); rc=$?
  check_eq "again at 540x400, -b before it, --json: windows --json's object" "0 540 400 true" "$rc $(jq -r '"\(.w) \(.h) \(.floating)"' <<<"$out")"
  ob shot -b "$B" -w 'title:^A$' -o "$TMP/wsz.png" >/dev/null 2>&1
  check_match "...a shot of it is that size" "540 x 400," "$(file "$TMP/wsz.png")"
  err=$(ob window -b "$B" -w 'title:^A$' --size 5x5 2>&1 >/dev/null); rc=$?
  check_eq "a size below the app's smallest: exit 1" 1 "$rc"
  check_match "...saying the size it took" "asked for 5x5, the window took [0-9]+x[0-9]+: its app's smallest" "$err"
  out=$(ob window -b "$B" -w 'title:^A$' --tile); rc=$?
  check_match "--tile: tiled again" "^0 0x[0-9a-f]+ foot \"A\" tiled at " "$rc $out"
  check_eq "...the box has it so" false "$(win | jq .floating)"
  out=$(ob window -b "$B" -w 'title:^A$' --float); rc=$?
  check_match "--float: floated, at the size it last floated at" "^0 .* floating at [0-9]+,[0-9]+ [0-9]+x[0-9]+$" "$rc $out"
  ob window -b "$B" -w 'title:^A$' --tile >/dev/null 2>&1
  ob hyprctl -b "$B" dispatch "hl.dsp.window.fullscreen({ mode = 'fullscreen', window = 'address:$(win | jq -r .address)' })" >/dev/null
  until_ok 5 bash -c "'$CLI' windows -b '$B' --json | jq -e '.[] | select(.title == \"A\") | .fullscreen'"
  err=$(ob window -b "$B" -w 'title:^A$' --size 600x400 2>&1); rc=$?
  check_match "a fullscreen window: refused, exit 1" "^1 omabox: window: .* is fullscreen" "$rc $err"
  check_eq "...and left as it was (not floated)" false "$(win | jq .floating)"
  ob down "$B" >/dev/null
}

# pixel and shot --zoom (#133, finding 209): what is refused before any box is asked (--zoom's size:
# t_window, on the region once clipped).
# Multi-monitor edges (#161) that need no box.
t_unit_monitors() {
  # Every command whose usage takes -b NAME takes it before the command too: monitor was left out.
  local bcmds missing="" c n=0 out d=$TMP/maw
  bcmds=$(probe box_cmds)
  for c in $(ob help 2>&1 | sed -nE 's/^  omabox ([a-z-]+) .*-b NAME.*/\1/p' | sort -u); do
    n=$((n + 1)); [[ $bcmds == *" $c "* ]] || missing+=" $c"
  done
  check_eq "every command whose usage takes -b NAME is one -b NAME before it reaches ($n of them)" "" "$missing"
  check "...the usage has them" test "$n" -gt 20
  # An interactive box's layout as a picture on the host (#174): one scale for all, whole pixels when
  # a scale near gives them, the gap between windows that touch in the box, centred; never enlarged.
  pic() { printf '%s\n' "$@" | probe desk_picture | paste -sd'|'; }
  check_eq "picture: #174's layout on a 3440x1440 screen, at 63/120" "0.525 1|main 862 9 1008 567|WAYLAND-2 1882 9 567 1008|WAYLAND-3 1882 1029 672 378" \
    "$(pic '3416 1416 12' 'main 0 0 1920 1080' 'WAYLAND-2 1920 0 1080 1920' 'WAYLAND-3 1920 1920 1280 720')"
  check_eq "picture: its first two" "0.73333 1|main 602 4 1408 792|WAYLAND-2 2022 4 792 1408" \
    "$(pic '3416 1416 12' 'main 0 0 1920 1080' 'WAYLAND-2 1920 0 1080 1920')"
  check_eq "picture: no scale near gives 1366x768 whole pixels: rounded" "0.56667 1|main 11 222 1088 612|WAYLAND-2 1111 222 774 435" \
    "$(pic '1896 1056 12' 'main 0 0 1920 1080' 'WAYLAND-2 1920 0 1366 768')"
  check_eq "picture: an X,Y one below the main window, a tall one right of it (60/120: whole pixels for 800x600)" "0.5 1|main 380 24 960 540|WAYLAND-3 380 576 400 300|WAYLAND-2 1352 24 540 960" \
    "$(pic '2272 1008 12' 'main 0 0 1920 1080' 'WAYLAND-3 0 1080 800 600' 'WAYLAND-2 1920 0 1080 1920')"
  check_eq "picture: a lone monitor smaller than the area is not enlarged" "1 1|main 1308 408 800 600" "$(pic '3416 1416 12' 'main 0 0 800 600')"
  check_eq "picture: too big even at Hyprland's smallest scale (1/4): laid out at it, said" "0.25 0|main 0 15 480 270|WAYLAND-2 492 15 480 270|WAYLAND-3 984 15 480 270" \
    "$(pic '500 300 12' 'main 0 0 1920 1080' 'WAYLAND-2 1920 0 1920 1080' 'WAYLAND-3 3840 0 1920 1080')"
  # (An interactive monitor that fails in `up`: the add's undo leaves up's, which takes the box down:
  # trap.rs a_nested_undo_leaves_the_outer; up stops at the add's Err (up_box's `?`), its failure
  # then t_failed_up's. #324 wave 6-suite.)
  # An output listed 0x0 in an NVIDIA box (#213): one a program made with `output create headless`.
  local zm='[{"name":"WAYLAND-1","width":1920,"height":1080,"disabled":false},{"name":"MINE","width":0,"height":0,"disabled":false},{"name":"OFF","width":0,"height":0,"disabled":true}]'
  out=$(probe zero_note "$zm" true "renderD128 amdgpu")
  check_match "zero_note: the 0x0 one named, why, and a box on the other GPU" \
    "^MINE listed 0x0: this box draws on NVIDIA, .*output create headless.*monitor add makes one that works.*OMABOX_RENDER_NODE=/dev/dri/renderD128 omabox up --new \(renderD128 is amdgpu\)$" "$out"
  check_fails "...a disabled one is not" grep -q OFF <<<"$out"
  check_match "...no other GPU: said" "a machine with a GPU other than NVIDIA's \(this one has none\)" "$(probe zero_note "$zm" true "")"
  check_eq "...nothing in a box not drawing on NVIDIA" "" "$(probe zero_note "$zm" false "renderD128 amdgpu")"
  check_eq "...nothing when every output has a size" "" "$(probe zero_note '[{"name":"WAYLAND-1","width":1920,"height":1080,"disabled":false}]' true "")"
  check_eq "...nothing (and no failure) for what is not a monitor list" "" "$(probe zero_note 'nope' true "")"
}

t_unit_pixel() {
  check_match "pixel: X Y needed" "need X Y" "$(ob pixel -b "$P-x" 5 2>&1)"
  check_match "pixel: a bad coordinate" "bad argument" "$(ob pixel -b "$P-x" 1 x 2>&1)"
  check_match "pixel: --in or --window" "not both" "$(ob pixel -b "$P-x" --in a.png -w x 1 1 2>&1)"
  check_match "pixel: at most 32 points" "at most 32" "$(ob pixel -b "$P-x" $(seq 66) 2>&1)"
  # (pixel is a jailed agent's: broker_side.rs's broker_check_allows_and_refuses)
  # (tree is a jailed agent's (#178): broker_side.rs's broker_check_allows_and_refuses)
  check_match "shot --zoom needs -g" "goes with -g" "$(ob shot -b "$P-x" --zoom 4 2>&1)"
  check_match "shot --zoom 2-16" "takes 2-16" "$(ob shot -b "$P-x" -g "0,0 9x9" --zoom 17 2>&1)"
  check_match "shot --zoom or --fit" "not both" "$(ob shot -b "$P-x" -g "0,0 9x9" --zoom 4 --fit 100 2>&1)"
  # shot --burst (#132, finding 212)
  check_match "shot --every without --burst refused" "go with --burst" "$(ob shot -b "$P-x" --every 1s 2>&1)"
  # #191, finding 249: --every 0 is back to back (the default is 100 ms apart); a stray unit is not 0.
  check_match "...--every 0 too (it is a pace: back to back)" "go with --burst" "$(ob shot -b "$P-x" --every 0 2>&1)"
  check_match "shot --every 0x refused" "takes a duration .*0: back to back" "$(ob shot -b "$P-x" --burst 3 --every 0x 2>&1)"
  check_match "shot --burst 1 refused" "takes 2-200" "$(ob shot -b "$P-x" --burst 1 2>&1)"
  check_match "shot --burst with --zoom refused" "--burst or --zoom" "$(ob shot -b "$P-x" --burst 3 --zoom 2 -g "0,0 9x9" 2>&1)"
  check_match "shot --after: an omabox command that acts" "got ls" "$(ob shot -b "$P-x" --burst 3 --after -- ls 2>&1)"
  check_match "...scroll and monitor are (#167)" "no box '$P-x' is up.*"$'\n'"omabox: no box '$P-x' is up" "$(ob shot -b "$P-x" --burst 3 --after -- scroll 1 1 15 2>&1; ob shot -b "$P-x" --burst 3 --after -- monitor add 800x600 2>&1)"
  check_match "...on the burst's box" "no -b" "$(ob shot -b "$P-x" --burst 3 --after -- keys -b other a 2>&1)"
  check_match "shot --after needs --" "--after -- ACTION" "$(ob shot -b "$P-x" --burst 3 --after keys a 2>&1)"
  # shot --changed (#145, finding 243): what it refuses before any box is asked.
  local a
  for a in '-g 0,0,9,9' '--fit 100' '--zoom 4' '--burst 3' '--monitor HEADLESS-2'; do
    # shellcheck disable=SC2086 # the option and its value
    check_match "shot --changed with $a refused" "crops by itself" "$(ob shot -b "$P-x" --changed $a 2>&1)"
  done
  check_match "...--since is --changed" "crops by itself" "$(ob shot -b "$P-x" --since x.png -g 0,0,9,9 2>&1)"
  check_match "shot --ignore without --changed refused" "goes with --changed" "$(ob shot -b "$P-x" --ignore "0,0 9x9" 2>&1)"
  check_match "shot --ignore takes a region" 'is "X,Y WxH"' "$(ob shot -b "$P-x" --changed --ignore 9 2>&1)"
  # (shot --since from a jail refused, a path of the jail's: t_unit_jailed_caller's)
  # diff_box: the box around what differs, a corner too (--burst --diff read a change there as none,
  # or as the box of what did not change); none when the same; a mask leaves a change out.
  local d=$TMP/diffbox; mkdir -p "$d"
  magick -size 100x80 xc:'#102030' "$d/a.png"
  magick "$d/a.png" -fill '#102031' -draw 'point 0,0' "$d/corner.png"
  magick "$d/a.png" -fill white -draw 'rectangle 0,0 99,40' "$d/half.png"
  magick "$d/a.png" -fill white -draw 'rectangle 10,10 19,19' -draw 'rectangle 80,60 89,69' "$d/two.png"
  check_eq "diff_box: the same image: nothing" "" "$(probe diff_box "$d/a.png" "$d/a.png")"
  check_eq "...one corner pixel, one level of blue" "0 0 1 1" "$(probe diff_box "$d/a.png" "$d/corner.png")"
  check_eq "...the top half" "0 0 100 41" "$(probe diff_box "$d/a.png" "$d/half.png")"
  check_eq "...two squares apart: one box around both" "10 10 80 60" "$(probe diff_box "$d/a.png" "$d/two.png")"
  check_eq "...one masked: the other" "10 10 10 10" "$(probe diff_box "$d/a.png" "$d/two.png" 75,55,20,20)"
  check_eq "diff_parts: each square, to 8 px outwards" $'8 8 16 16\n80 56 16 16' "$(probe diff_parts "$d/a.png" "$d/two.png" | sort -n)"
}

# shot --burst (#132, finding 212) in a box: frames at their times, a contact sheet, an action after the
# first frame and what it changed, and click --in a frame.
t_burst() {
  local B=$P-burst o=$TMP/burst out err rc
  up_ok "$B" --no-shell --net isolated || { no "up" "$UP_OUT"; return; }
  ob run -b "$B" -d -q --wait -- foot -T A cat >/dev/null 2>&1
  out=$(ob shot -b "$B" --burst 5 --every 100ms -g "0,0 200x200" -o "$o/a" 2>"$TMP/burst.err"); rc=$?; err=$(cat "$TMP/burst.err")
  check_eq "shot --burst 5 --every 100ms: exit 0, a line a frame" "0 5" "$rc $(grep -c "^$o/a/frame-00[1-5]\.png [0-9.]*s$" <<<"$out")"
  check_eq "...five 200x200 PNGs" 5 "$(file "$o"/a/frame-*.png | grep -c '200 x 200,')"
  # The pace is a schedule (frame N at (N-1) x 100 ms, or as soon as the grab before it is done): a slow
  # grab under load shortens the next gap, so gaps are no measure (#200). None ahead of it, in order, the
  # last within 2 s of its time.
  check "...on a 100 ms pace: none ahead of it, in order" awk '{ t = $2 + 0; if (t < (NR - 1) * 0.1 - 0.01 || (NR > 1 && t <= p)) bad = 1; p = t }
    END { exit bad || NR != 5 || p > 0.4 + 2 }' <<<"$out"
  check_match "...said, with --in" "5 frames of 200x200 \(screen 0,0\) over .*click with --in a frame" "$err"
  # (Frames for 2.4 s, 100 ms apart: the keys, a command of its own started after the first, land later
  # under load.)
  out=$(ob shot -b "$B" --burst 25 --every 100ms --diff --sheet -g "0,0 600x200" -o "$o/b" --after -- keys -t xyz 2>/dev/null); rc=$?
  check_eq "--after -- keys, --diff, --sheet: exit 0" 0 "$rc"
  check_match "...the first frame before the keys, a later one changed" "frame-001\.png 0\.[0-4][0-9]s"$'\n'".*changed [0-9]+,[0-9]+ [0-9]+x[0-9]+" "$out"
  check_match "...one contact sheet, last" "^$o/b/sheet\.png$" "$(tail -n 1 <<<"$out")"
  check_match "...a PNG" "PNG image data" "$(file "$o/b/sheet.png")"
  ob click -b "$B" --in "$o/a/frame-003.png" 10 20 >/dev/null 2>&1
  check_eq "click --in a frame" "10, 20" "$(ob hyprctl -b "$B" cursorpos)"
  # #167, finding 236. --diff in the screen's coordinates: a crop at 60,30, halved by --fit, and the
  # pointer moved into it after the first frame (screen shots show it): its box holds 400,90 (its
  # tip; a few pixels' slack for the rounding), not the frame's 170,30.
  out=$(ob shot -b "$B" --burst 20 --every 100ms --diff -g "60,30 400x80" --fit 200 -o "$o/d" --after -- pointer -- move 400 90 2>/dev/null)
  check "--diff with -g and --fit: the change in screen coordinates, inside the crop" awk '
    $3 == "changed" { split($4, p, ","); split($5, s, "x"); n++
      if (p[1] < 60 || p[2] < 30 || p[1] + s[1] > 460 || p[2] + s[2] > 110) bad = 1
      if (p[1] > 403 || p[1] + s[1] < 397 || p[2] > 93 || p[2] + s[2] < 87) bad = 1 }
    END { exit bad || n < 1 }' <<<"$out"
  # --after -- scroll (and monitor) are actions; scroll was refused.
  ob shot -b "$B" --burst 3 -g "0,0 200x200" -o "$o/s" --after -- scroll 500 95 15 >/dev/null 2>&1; rc=$?
  check_eq "--after -- scroll: taken, the pointer there" "0 500, 95" "$rc $(ob hyprctl -b "$B" cursorpos)"
  # A folder used again: the 12 frames and sheet of $o/b go, a file of the caller's stays.
  echo mine > "$o/b/notes.txt"
  ob shot -b "$B" --burst 2 -g "0,0 200x200" -o "$o/b" >/dev/null 2>&1
  check_eq "-o a folder used before: only this burst's frames, the caller's file kept" "frame-001.png frame-002.png notes.txt" \
    "$(cd "$o/b" && echo *)"
  # Two bursts at once with no -o: a folder each (the default was the second's name).
  mkdir -p "$o/tmp"
  TMPDIR=$o/tmp ob shot -b "$B" --burst 2 -g "0,0 200x200" >/dev/null 2>"$TMP/burst1.err" & local b1=$!
  TMPDIR=$o/tmp ob shot -b "$B" --burst 2 -g "0,0 200x200" >/dev/null 2>"$TMP/burst2.err"
  wait "$b1"
  check_eq "two bursts started together: two folders of 2 frames" "2 2 2" \
    "$(find "$o/tmp" -mindepth 1 -maxdepth 1 -type d | wc -l) $(for d in "$o"/tmp/*/; do find "$d" -name 'frame-*.png' | wc -l; done | xargs)"
  # #196, finding 314: a burst is one capture client in the box (tools/burst), not a grim a frame. Of
  # a still scene, its frames are grim's shots: the screen, a crop, a window, a window's crop scaled.
  local a args r; for a in "" "-g|300,300 400x200" "--window|A" "--window|A|-g|10,10 200x100|--fit|100"; do
    IFS='|' read -r -a args <<<"$a"
    r=$(burst_vs_shot "$B" "${args[@]}")
    check "shot --burst ${args[*]:-(the screen)}: a frame of a still scene is the shot's image ($r)" \
      awk '{ exit !($1 == $2 && $3 + 0 <= 50) }' <<<"$r"
  done
  out=$(ob shot -b "$B" --burst 5 -g "300,300 100x100" -o "$o/still" 2>&1 >/dev/null)
  check_match "...repeated frames said as nothing new drawn, no longer the grabs (#191)" \
    "4 of 4 frames identical to the one before: nothing new drawn between them$" "$out"
  # Hyprland's screencast events (on: screencast, screencastv2; off 500 ms after the last frame): four
  # for a whole burst. A grim a frame was four a frame (finding 249).
  sleep 0.8   # (the bursts before: their sessions' last events, 500 ms after their last frames)
  local e0 ne; e0=$(wc -l < "$(ob path -b "$B")/home/events.log")
  ob shot -b "$B" --burst 20 --every 0 -g "0,0 200x200" -o "$o/ev" >/dev/null 2>&1
  sleep 0.8
  ne=$(screencast_since "$B" "$e0")
  check_eq "a 20-frame burst back to back: four screencast events, not four a frame" 4 "$ne"
  # #191, finding 249: those events held up a client that works on each one, its timers with it: a 40
  # ms Timer beside a 10 ms handler of Hyprland's events showed a step or two in a whole back-to-back
  # burst. The square's colour is the Timer's count (red + 256 green); over a burst it moves about one
  # step per 40 ms of the burst's span.
  local D st sp; D=$(ob path -b "$B")
  cat > "$D/home/t191.qml" <<'QML'
import QtQuick
import Quickshell
import Quickshell.Wayland
import Quickshell.Hyprland
ShellRoot {
  PanelWindow {
    anchors { top: true; left: true }
    implicitWidth: 100; implicitHeight: 100
    WlrLayershell.layer: WlrLayer.Overlay
    Rectangle {
      id: r; anchors.fill: parent
      property int n: 0
      color: Qt.rgba((n % 256) / 255, (Math.floor(n / 256) % 256) / 255, 0.5, 1)
    }
    Timer { interval: 40; running: true; repeat: true; onTriggered: r.n++ }
    Connections {
      target: Hyprland
      function onRawEvent(e) { var t = Date.now(); while (Date.now() - t < 10) {} }
    }
  }
}
QML
  ob run -b "$B" -d -q -- qs -p /home/sbx/t191.qml >/dev/null 2>&1
  until_ok 10 sh -c '"$1" pixel -b "$2" 50 50 | grep -qiE "(7f|80)$"' _ "$CLI" "$B" >/dev/null
  # The Timer's steps between a burst's first and last frame (DIR), and the burst's span in ms (DIR.out).
  burst_steps() {
    local f v first="" last=""
    for f in "$1"/frame-*.png; do
      v=$(magick "$f" -format '%[fx:int(p{50,50}.r*255+0.5)+256*int(p{50,50}.g*255+0.5)]' info: 2>/dev/null) || v=0
      first=${first:-$v} last=$v
    done
    echo "$(((last - first + 65536) % 65536)) $(awk 'END { sub(/s$/, "", $2); printf "%d", $2 * 1000 }' "$1.out")"
  }
  # Measured against the Timer's own pace just before, two frames 2 s apart (#200): under load the client
  # is slower by itself. A 30-frame burst back to back (~0.5 s) at half that pace or more (the grims
  # showed 0 or 1 step, finding 249); 3 tries, as load comes and goes. Each after the events of the
  # one before had their 10 ms.
  local ist isp i
  for i in 1 2 3; do
    ob shot -b "$B" --burst 2 --every 2s -g "0,0 100x100" -o "$o/i" >"$o/i.out" 2>/dev/null
    read -r ist isp < <(burst_steps "$o/i")
    sleep 1
    ob shot -b "$B" --burst 30 --every 0 -g "0,0 100x100" -o "$o/t" >"$o/t.out" 2>/dev/null
    read -r st sp < <(burst_steps "$o/t")
    [ "$ist" -le 0 ] || [ $((st * isp * 2)) -lt $((ist * sp)) ] || [ "$st" -lt 3 ] || break
    [ "$i" = 3 ] || note "try $i: $st steps in $sp ms, $ist in $isp ms without a burst"
    sleep 1
  done
  check "--every 0 beside a client busy on each Hyprland event: its 40 ms Timer at half its own pace or more ($st steps in $sp ms; $ist in $isp ms with none)" \
    test "$ist" -gt 0 -a $((st * isp * 2)) -ge $((ist * sp)) -a "$st" -ge 3
  ob down "$B" >/dev/null 2>&1
}

# shot --changed (#145, finding 243) in a box: the first one whole, then nothing changed (no image,
# nothing on stdout, exit 0), typed text cropped and `click --in` mapping the crop, the pointer's old
# place on the screen left out, --since, a resized window shot whole, a blinking block cursor left out
# by --ignore, a blinking beam caret alone not a change.
# shot-fit (#188): a shot given no --fit takes the setting's (or $OMABOX_SHOT_FIT's) wherever --fit
# goes, and click --in maps it as it maps --fit's; --fit N wins, --fit 0 is full size; --changed is
# not scaled, and says why it has nothing to compare with.
t_shot_fit() {
  local B=$P-sfit o=$TMP/sfit err
  up_ok "$B" --no-shell --net isolated || { no "up" "$UP_OUT"; return; }
  mkdir -p "$o/home/.config/omabox"; echo shot-fit=1000 > "$o/home/.config/omabox/config"
  pos() { ob hyprctl -b "$B" cursorpos; }
  err=$(OMABOX_SHOT_FIT='' HOME=$o/home "$CLI" shot -b "$B" -o "$o/set.png" 2>&1 >/dev/null)
  check_match "config shot-fit 1000: the shot 1000 wide" "1000 x 562," "$(file "$o/set.png")"
  check_match "...said, for --in" "1000x562 image of the screen's 1920x1080 at 0,0 \(x1.92\); click with --in $o/set.png" "$err"
  ob shot -b "$B" --fit 1000 -o "$o/flag.png" >/dev/null 2>&1
  ob click -b "$B" --in "$o/flag.png" 500 270 >/dev/null 2>&1
  local want; want=$(pos)
  ob pointer -b "$B" -- move 10 10 >/dev/null 2>&1
  ob click -b "$B" --in "$o/set.png" 500 270 >/dev/null 2>&1
  check_eq "click --in it lands where it does on a --fit 1000 shot" "$want" "$(pos)"
  check_eq "...the screen's point" "960, 519" "$want"
  OMABOX_SHOT_FIT=640 ob shot -b "$B" -o "$o/env.png" >/dev/null 2>&1
  check_match "OMABOX_SHOT_FIT=640: 640 wide" "640 x 360," "$(file "$o/env.png")"
  err=$(OMABOX_SHOT_FIT=200 ob shot -b "$B" -g "100,100 400x100" -o "$o/g.png" 2>&1 >/dev/null)
  check_match "...a -g crop scaled too" "200 x 50," "$(file "$o/g.png")"
  ob click -b "$B" --in "$o/g.png" 50 20 >/dev/null 2>&1
  check_eq "...click --in maps it" "201, 141" "$(pos)"
  local out; out=$(OMABOX_SHOT_FIT=300 ob shot -b "$B" --burst 2 --every 0 -o "$o/burst" 2>/dev/null)
  check_match "...--burst frames too" "300 x 168," "$(file "$o/burst/frame-001.png")"
  OMABOX_SHOT_FIT=640 ob shot -b "$B" --fit 800 -o "$o/wins.png" >/dev/null 2>&1
  check_match "--fit 800 wins over it" "800 x 450," "$(file "$o/wins.png")"
  # --changed is never scaled; the shots before were, so they left nothing to compare with.
  err=$(OMABOX_SHOT_FIT=640 ob shot -b "$B" --changed -o "$o/chg.png" 2>&1 >/dev/null)
  check_match "--changed: full size" "1920 x 1080," "$(file "$o/chg.png")"
  check_match "...a scaled shot left no baseline, said with what does" "a shot scaled by shot-fit leaves none: shot --fit 0" "$err"
  err=$(OMABOX_SHOT_FIT=640 ob shot -b "$B" --fit 0 -o "$o/full.png" 2>&1 >/dev/null)
  check_match "--fit 0: full size" "1920 x 1080," "$(file "$o/full.png")"
  check_eq "...said nothing extra (1:1)" "" "$err"
  ob down "$B" >/dev/null 2>&1
}

t_changed() {
  local B=$P-chg o=$TMP/chg out err rc W='title:^C$'
  up_ok "$B" --no-shell --net isolated || { no "up" "$UP_OUT"; return; }
  mkdir -p "$o"
  ob run -b "$B" -d -q --wait -- foot -T C -o cursor.blink=no cat >/dev/null 2>&1
  local wx wy ww wh
  read -r wx wy ww wh < <(ob windows -b "$B" --json | jq -r '.[] | select(.title == "C") | "\(.at[0]) \(.at[1]) \(.size[0]) \(.size[1])"')
  shoot() { out=$(ob shot -b "$B" "$@" 2>"$o/err"); rc=$?; err=$(cat "$o/err"); }
  shoot --changed -w "$W" -o "$o/a.png"
  check_eq "the first --changed: a whole shot, its path" "0 $o/a.png" "$rc $out"
  check_match "...said why" "no earlier shot of it to compare with: a whole shot of window" "$err"
  check_match "...the window's size" "$ww x $wh," "$(file "$o/a.png")"
  shoot --changed -w "$W" -o "$o/b.png"
  check_eq "nothing changed: exit 0, nothing on stdout, no image" "0||no" "$rc|$out|$([ -e "$o/b.png" ] && echo yes || echo no)"
  check_match "...said, since the last shot" "nothing changed in window .* since $o/a\.png \([0-9.]+s ago\): no image" "$err"
  ob keys -b "$B" --wait -t "hello" >/dev/null 2>&1
  shoot --changed -w "$W" -o "$o/c.png"
  check_eq "typed text: a crop" "0 $o/c.png" "$rc $out"
  local cw=0 ch=0 cx=-1 cy=-1
  [[ $err =~ since\ $o/a\.png\ .*:\ ([0-9]+)x([0-9]+)\ at\ ([0-9]+),([0-9]+)\ of\ window\ .*\(its\ coordinates\).*click\ with\ --in ]] &&
    cw=${BASH_REMATCH[1]} ch=${BASH_REMATCH[2]} cx=${BASH_REMATCH[3]} cy=${BASH_REMATCH[4]}
  check "...said where, in the window's coordinates: its top left, a tenth of it at most" \
    test "$cx" -ge 0 -a "$cx" -lt 60 -a "$cy" -ge 0 -a "$cy" -lt 60 -a "$((cw * ch * 10))" -lt "$((ww * wh))"
  check_match "...the image that size" "$cw x $ch," "$(file "$o/c.png")"
  ob click -b "$B" --in "$o/c.png" 5 6 >/dev/null 2>&1
  check_eq "click --in the crop: that point of the window" "$((wx + cx + 5)), $((wy + cy + 6))" "$(ob hyprctl -b "$B" cursorpos)"
  # The screen: where the pointer was is not a change, where it is now is drawn. An evidence shot of the
  # box first (another test failing meanwhile) is not the screen's last shot (#195).
  ev_shot -b "$B" -o "$o/ev.png" >/dev/null 2>&1
  check "an evidence shot of the screen taken" test -s "$o/ev.png"
  shoot --changed -o "$o/s1.png"
  check_match "the screen's first --changed: whole, after an evidence shot too" "no earlier shot of it.*a whole shot of the screen" "$err"
  ob pointer -b "$B" -- move $((wx + 300)) $((wy + 300)) >/dev/null 2>&1
  shoot --changed -o "$o/s2.png"
  local px=-1 py=-1 pw=0 ph=0
  [[ $err =~ :\ ([0-9]+)x([0-9]+)\ at\ ([0-9]+),([0-9]+)\ of\ the\ screen ]] &&
    pw=${BASH_REMATCH[1]} ph=${BASH_REMATCH[2]} px=${BASH_REMATCH[3]} py=${BASH_REMATCH[4]}
  check "the pointer moved: a crop around where it is now, not where it was" \
    test "$px" -le $((wx + 300)) -a $((px + pw)) -gt $((wx + 300)) -a "$py" -le $((wy + 300)) -a $((py + ph)) -gt $((wy + 300)) -a "$pw" -lt 120 -a "$ph" -lt 120
  check_match "...said: perhaps the pointer alone" "perhaps the pointer alone" "$err"
  # --since: an earlier whole shot; never a crop, nor the screen's for a window.
  shoot --since "$o/a.png" -o "$o/d.png"
  check_match "--since a whole shot of the window: what changed since it" "^0 $o/d\.png .*--changed since $o/a\.png .* of window .*\(its coordinates\)" "$rc $out $err"
  check_match "--since a crop refused" "is a crop" "$(ob shot -b "$B" --since "$o/c.png" 2>&1)"
  check_match "--since the screen's for a window refused" "is a shot of the screen, not of a window" "$(ob shot -b "$B" --since "$o/s1.png" -w "$W" 2>&1)"
  # A blinking block cursor in a second window (C is resized: its next --changed is whole, said why).
  ob run -b "$B" -d -q --wait -- foot -T K -o cursor.blink=yes cat >/dev/null 2>&1
  shoot --changed -w "$W" -o "$o/e.png"
  check_match "a resized window: a whole shot, said why" "^0 $o/e\.png .*it was ${ww}x$wh at the last shot of it: a whole shot" "$rc $out $err"
  ob shot -b "$B" -w 'title:^K$' -o "$o/k.png" >/dev/null 2>&1
  local i crops=0 none=0
  for i in 1 2 3 4 5 6; do
    sleep 0.35; shoot --changed -w 'title:^K$' -o "$o/k$i.png"
    if [ -n "$out" ]; then crops=$((crops + 1)); fi
  done
  check "a blinking block cursor: a change (crops: $crops of 6)" test "$crops" -ge 1
  for i in 1 2 3 4 5 6; do
    sleep 0.35; shoot --changed -w 'title:^K$' --ignore "0,0 80x80" -o "$o/ki$i.png"
    if [ -z "$out" ] && [ "$rc" = 0 ]; then none=$((none + 1)); fi
  done
  check_eq "...left out by --ignore (the window's coordinates): nothing changed each time" 6 "$none"
  # A blinking beam: a caret alone, not a change.
  ob run -b "$B" -d -q --wait -- foot -T L -o cursor.blink=yes -o cursor.style=beam cat >/dev/null 2>&1
  ob shot -b "$B" -w 'title:^L$' -o "$o/l.png" >/dev/null 2>&1
  local carets=0; none=0
  for i in 1 2 3 4 5 6; do
    sleep 0.35; shoot --changed -w 'title:^L$' -o "$o/l$i.png"
    if [ -z "$out" ] && [ "$rc" = 0 ]; then none=$((none + 1)); fi
    if [[ $err == *"a caret? "*" left out: no image"* ]]; then carets=$((carets + 1)); fi
  done
  check_eq "a blinking beam caret alone: nothing changed each time" 6 "$none"
  check "...the caret said (at least once: $carets of 6)" test "$carets" -ge 1
  ob down "$B" >/dev/null 2>&1
}

# pixel and shot --zoom (#133, finding 209) in a box: a known background, a terminal of a known colour.
t_pixel() {
  local B=$P-pix o=$TMP/pix out
  up_ok "$B" --no-shell --net isolated || { no "up" "$UP_OUT"; return; }
  mkdir -p "$o"
  ob lua -b "$B" 'hl.config({ misc = { background_color = 0xff345678 } })' >/dev/null
  check_eq "pixel X Y: the screen's colour there" "#345678" "$(ob pixel -b "$B" 3 3)"
  ob run -b "$B" -d -q --wait -- foot -T K -o colors-dark.background=123456 -o colors-dark.alpha=1.0 sleep 600 >/dev/null 2>&1
  check_eq "pixel --window: the window's own pixels" $'0,0 #123456\n40,30 #123456' "$(ob pixel -b "$B" -w 'title:^K$' 0 0 40 30)"
  check_eq "...--json, a line each" '{"x":40,"y":30,"hex":"#123456","r":18,"g":52,"b":86}' "$(ob pixel -b "$B" -w 'title:^K$' --json 40 30)"
  check_match "a point off the screen refused" "outside the screen" "$(ob pixel -b "$B" 5000 1 2>&1)"
  check_match "...off the window too" "outside the window" "$(ob pixel -b "$B" -w 'title:^K$' 5000 1 2>&1)"
  # --zoom: a crop across the window's corner, each pixel 8x8 and no colour blended between them.
  local ax ay; read -r ax ay < <(ob windows -b "$B" --json | jq -r '.[] | select(.title == "K") | "\(.at[0]) \(.at[1])"')
  ob pointer -b "$B" -- move 900 900 >/dev/null 2>&1
  local err; err=$(ob shot -b "$B" -g "$((ax - 4)),$((ay - 4)) 10x10" --zoom 8 -o "$o/z.png" 2>&1 >/dev/null)
  check_match "shot --zoom 8 of 10x10: 80x80" "80 x 80," "$(file "$o/z.png")"
  check_match "...said, with --in" "80x80 image of the screen's 10x10 at .*\(zoomed 8 times\); click with --in" "$err"
  ob shot -b "$B" -g "$((ax - 4)),$((ay - 4)) 10x10" -o "$o/z1.png" >/dev/null 2>&1
  check_eq "...the colours of the plain crop, none blended" "$(magick "$o/z1.png" -unique-colors -format %w info:)" "$(magick "$o/z.png" -unique-colors -format %w info:)"
  local px; px=$(ob pixel -b "$B" --in "$o/z.png" 44 44)
  check_match "pixel --in the zoomed shot: a colour" "^#[0-9a-f]{6}$" "$px"
  check_eq "...the screen's pixel there" "$(ob pixel -b "$B" $((ax + 1)) $((ay + 1)))" "$px"
  ob click -b "$B" --in "$o/z.png" 44 44 >/dev/null 2>&1
  check_eq "click --in the zoomed shot" "$((ax + 1)), $((ay + 1))" "$(ob hyprctl -b "$B" cursorpos)"
  ob down "$B" >/dev/null 2>&1
}

# #273 part C: the --json shapes that need a box, each a jq check of the fields a script reads:
# shot (screen, region, window, fit, --changed), windows (x, y, w, h; one line), ls (scale, allowed,
# dir), mode, record status, events --mark, path --logs (ports' addresses: t_ports).
t_json() {
  local B=$P-json o=$TMP/json j
  mkdir -p "$o"
  up_ok "$B" --no-shell --net isolated --allow 8093 || { no "up" "$UP_OUT"; return; }
  local W H; read -r W H < <(ob mode -b "$B" --json | jq -r '.mode | sub("@.*"; "") | split("x") | "\(.[0]) \(.[1])"')
  check_eq "mode --json: {name, mode, scale}" "HEADLESS-2 true 1" \
    "$(ob mode -b "$B" --json | jq -r '"\(.name | sub("WAYLAND-1"; "HEADLESS-2")) \(.mode | test("^[0-9]+x[0-9]+@")) \(.scale)"')"
  j=$(ob ls --json | jq -c --arg b "$B" '.[] | select(.name == $b)')
  check_eq "ls --json: scale, allowed (numbers), dir; allow (0.9's string) gone since 1.0" "1 [8093] false $PWD" "$(jq -r '"\(.scale) \(.allowed | tojson) \(has("allow")) \(.dir)"' <<<"$j")"
  j=$(ob shot -b "$B" --json -o "$o/s.png")
  check_eq "shot --json: path, kind screen, region the layout, image, scale 1" "$o/s.png screen 0 0 $W $H $W $H 1 null null" \
    "$(jq -r '"\(.path) \(.kind) \(.region.x) \(.region.y) \(.region.w) \(.region.h) \(.image.w) \(.image.h) \(.scale) \(.window) \(.changed)"' <<<"$j")"
  check "...the file is there" test -s "$o/s.png"
  check_eq "...-g: kind region, its place" "region 10 20 100 50" "$(ob shot -b "$B" --json -g "10,20 100x50" -o "$o/g.png" | jq -r '"\(.kind) \(.region | "\(.x) \(.y) \(.w) \(.h)")"')"
  check_eq "...--fit: the scale an image pixel is" "$(awk -v w="$W" 'BEGIN { printf "%.4f", 400 / w }' | sed 's/0*$//; s/\.$//')" \
    "$(ob shot -b "$B" --json --fit 400 -o "$o/f.png" | jq -r '.scale')"
  ob run -b "$B" -d -q --wait -- foot -T J sleep 600 >/dev/null 2>&1
  j=$(ob windows -b "$B" --json)
  check_eq "windows --json: one line, x y w h as at and size" "1 true" \
    "$(wc -l <<<"$j") $(jq '.[] | select(.title == "J") | .x == .at[0] and .y == .at[1] and .w == .size[0] and .h == .size[1]' <<<"$j")"
  local ww; ww=$(jq -r '.[] | select(.title == "J") | "\(.size[0]) \(.size[1]) \(.address)"' <<<"$j")
  check_eq "shot --window --json: kind window, its own coordinates, the window named" "window 0 0 $ww" \
    "$(ob shot -b "$B" --json -w 'title:^J$' -o "$o/w.png" | jq -r '"\(.kind) \(.region.x) \(.region.y) \(.region.w) \(.region.h) \(.window.address)"')"
  ob shot -b "$B" --fit 0 -o "$o/base.png" >/dev/null 2>&1
  ob pointer -b "$B" -- move 5 5 >/dev/null 2>&1
  j=$(ob shot -b "$B" --changed --json -o "$o/c.png" 2>/dev/null)
  check_match "shot --changed --json: changed {result, since}" "^(nothing|changed) $o/base.png$" "$(jq -r '"\(.changed.result) \(.changed.since)"' <<<"$j")"
  j=$(ob shot -b "$B" --changed --json -o "$o/c2.png" 2>/dev/null)
  check_eq "...nothing changed since: path null, result nothing" "null nothing" "$(jq -r '"\(.path) \(.changed.result)"' <<<"$j")"
  check_eq "record status --json: not recording" '{"recording":false,"stopped":false,"monitors":[],"fps":null,"file":null,"audio":false,"started":null}' \
    "$(ob record -b "$B" status --json)"
  check_match "events --mark M --json: {mark, offset}" '^\{"mark":"M","offset":[0-9]+\}$' "$(ob events -b "$B" --mark M --json 2>/dev/null)"
  check_eq "path --logs --json: {NAME: PATH}" "true" "$(ob path -b "$B" --logs --json | jq '.hyprland | type == "string"')"
  ob down "$B" >/dev/null 2>&1
}

# output drop/back (#146, finding 210; #163, finding 232): a screen gone and back, under its name,
# mode, place and scale: the main screen, or a monitor by name, never one taken for the other (a
# second drop took the monitor, `mode` named it); a config reload while one is away does not bring it
# back; the shell sees it go (its log) and survives; the refusals. On a box with a monitor below the
# main screen at scale 1.6, on a GPU other than NVIDIA's (its boxes refuse both).
t_output() {
  local B=$P-out n
  check_match "output: drop or back" "drop or back" "$(ob output -b "$P-x" 2>&1)"
  check_match "output back takes no --for" "takes no --for" "$(ob output -b "$P-x" back --for 1s 2>&1)"
  check_match "output --for junk" "takes a duration" "$(ob output -b "$P-x" drop --for soon 2>&1)"
  check_match "output --cycles 0" "takes 1-999" "$(ob output -b "$P-x" drop --cycles 0 2>&1)"
  check_match "output drop of two names" "one output's name, got A and B" "$(ob output -b "$P-x" drop A B 2>&1)"
  check_match "output drop of a name that is none" "not an output's name" "$(ob output -b "$P-x" drop 'a b' 2>&1)"
  # (output is a jailed agent's: broker_side.rs's broker_check_allows_and_refuses)
  n=$(gpu_node other)
  [ -n "$n" ] || { skip "output drop and back" "no render node here but NVIDIA's (t_output_nvidia runs there)"; return; }
  output_on "$n" "$B" HEADLESS-2 HEADLESS-3
}
# The same on NVIDIA (#165, finding 234), whose screens are Wayland outputs, windows on its labwc: one
# dropped is that window closed, one back a window again, sized by labwc's rule for it.
t_output_nvidia() {
  local n; n=$(nvidia_ready) || { skip "output drop and back on NVIDIA" "$n"; return; }
  output_on "$n" "$P-outnv" WAYLAND-1 WAYLAND-2
}
# output_on NODE BOX MAIN MONITOR: drop and back on a box on NODE with a monitor below the main screen.
output_on() {
  local n=$1 B=$2 m0=$3 m1=$4 out rc ml before
  out=$(env OMABOX_RENDER_NODE="$n" "$CLI" up "$B" --size 1280x720 --net isolated --monitor 1280x800,scale=1.6,below 2>&1) ||
    { no "up with a monitor" "failed: $out"; return; }
  # Its apps' renderer (#204, findings 290, 294): on the GPU, NVIDIA's too since its card placeholder;
  # nothing said.
  if ! command -v eglinfo >/dev/null; then skip "apps' renderer said" "no eglinfo (mesa-utils) here"
  else
    check_eq "up on $(probe render_driver "$n"): nothing said of its apps' renderer" "" "$(grep 'in software' <<<"$out")"
    check_eq "...ls --json: client_render on the GPU" false "$("$CLI" ls --json | jq -r --arg b "$B" '.[] | select(.name == $b) | .client_render.software')"
    check_eq "...no apps line in ls" "" "$("$CLI" ls | awk -v b="$B" '$1 == b { on = 1; next } /^[^ ]/ { on = 0 } on && /apps:/')"
  fi
  local list='map({name, mode, scale, x, y}) | sort_by(.name)'
  ml=$(ob monitor -b "$B" list --json | jq -c "$list")
  check_eq "two monitors, the second below at 1.6" "[{\"name\":\"$m0\",\"mode\":\"1280x720@60\",\"scale\":1,\"x\":0,\"y\":0},{\"name\":\"$m1\",\"mode\":\"1280x800@60\",\"scale\":1.6,\"x\":0,\"y\":720}]" "$ml"
  # Omarchy 4.5's per-monitor workspaces (#292, finding 416): the main screen on 1-10 (FALLBACK, the
  # stand-in output at the start, took that block), the monitor on its own block (11-20).
  if [ -f /usr/share/omarchy/default/hypr/monitor-workspaces.lua ]; then
    check_eq "per-monitor workspaces: the main screen on 1, the monitor on 11" "$m0 1|$m1 11" \
      "$(ob hyprctl -b "$B" -j monitors | jq -r '[.[] | select(.name != "FALLBACK") | "\(.name) \(.activeWorkspace.id)"] | sort | join("|")')"
  else skip "per-monitor workspaces (#292)" "this Omarchy has none"; fi
  before=$(ob mode -b "$B")
  check_match "output back with nothing dropped: refused" "has its screen" "$(ob output -b "$B" back 2>&1)"
  out=$(ob output -b "$B" drop 2>&1); rc=$?
  check_eq "output drop: exit 0" 0 "$rc"
  check_match "...the main screen off, the monitor still on, said" "has its main screen \($m0\) off now, $m1 still on: omabox output back $m0" "$out"
  check_eq "...the box lists the monitor only" "[\"$m1\"]" "$(ob hyprctl -b "$B" -j monitors | jq -c '[.[] | select(.name != "FALLBACK") | .name]')"
  check_match "mode while the main screen is away: said, not the monitor's mode (#163)" "main screen \($m0\) is away" "$(ob mode -b "$B" 2>&1)"
  check_match "...nor set on the monitor" "main screen \($m0\) is away" "$(ob mode -b "$B" 1024x768 2>&1)"
  check_match "a second drop: refused, the main screen is away already (#163)" "main screen \($m0\) is dropped already" "$(ob output -b "$B" drop 2>&1)"
  check_eq "...the monitor still on, as it was" "[\"$m1 1280x800 0 720\"]" \
    "$(ob hyprctl -b "$B" -j monitors | jq -c '[.[] | select(.name != "FALLBACK") | "\(.name) \(.width)x\(.height) \(.x) \(.y)"]')"
  check_match "monitor list: the main screen there, marked dropped" "$m0 +1280x720@60 +1 +0,0 +\(dropped\)" "$(ob monitor -b "$B" list)"
  reload_landed "$(ob path -b "$B")/home/events.log" ob hyprctl -b "$B" reload
  check_eq "a config reload while it is away: not made again, the monitor where it was" "[\"$m1 1280x800 0 720\"]" \
    "$(ob hyprctl -b "$B" -j monitors | jq -c '[.[] | select(.name != "FALLBACK") | "\(.name) \(.width)x\(.height) \(.x) \(.y)"]')"
  out=$(ob output -b "$B" back); rc=$?
  check_eq "output back: the same name and mode ($before)" "0 $before" "$rc $out"
  check_eq "...every monitor as before" "$ml" "$(ob monitor -b "$B" list --json | jq -c "$list")"
  # A monitor by its name (#163): its mode, place and scale kept, its omabox.monitors line too.
  out=$(ob output -b "$B" drop "$m1" 2>&1); rc=$?
  check_eq "output drop $m1: exit 0" 0 "$rc"
  check_match "...said" "has its monitor $m1 off now, $m0 still on: omabox output back $m1" "$out"
  check_eq "...the main screen on, its mode as before" "$before" "$(ob mode -b "$B" 2>&1)"
  check_match "...dropped again: refused" "$m1 is dropped already" "$(ob output -b "$B" drop "$m1" 2>&1)"
  check_match "...monitor remove of it: refused, said" "$m1 is dropped" "$(ob monitor -b "$B" remove "$m1" 2>&1)"
  if [ "$m0" = HEADLESS-2 ]; then
    check_match "...monitor add under its name: refused" "already has a monitor $m1, dropped" "$(ob monitor -b "$B" add 800x600 --name "$m1" 2>&1)"
  else
    check_match "...monitor add: not under its name, the next free one" "^WAYLAND-3$" "$(ob monitor -b "$B" add 800x600 2>/dev/null)"
    ob monitor -b "$B" remove WAYLAND-3 >/dev/null 2>&1
  fi
  check_match "output back of one not dropped: refused" "$m0 is not dropped \(dropped: $m1\)" "$(ob output -b "$B" back "$m0" 2>&1)"
  check_match "output drop of one it does not have" "has no monitor HEADLESS-9" "$(ob output -b "$B" drop HEADLESS-9 2>&1)"
  reload_landed "$(ob path -b "$B")/home/events.log" ob hyprctl -b "$B" reload
  check_eq "a config reload while it is away: not made again" "[\"$m0\"]" "$(ob hyprctl -b "$B" -j monitors | jq -c '[.[] | select(.name != "FALLBACK") | .name]')"
  out=$(ob output -b "$B" back "$m1"); rc=$?
  check_eq "output back $m1: its name and mode" "0 $m1 1280x800@60" "$rc $out"
  check_eq "...its place and scale as before" "$ml" "$(ob monitor -b "$B" list --json | jq -c "$list")"
  # Both away: no screen; back brings both, the main screen first.
  ob output -b "$B" drop "$m1" >/dev/null 2>&1
  check_match "both dropped: no screen, said" "has no screen now \($m1, $m0 dropped\)" "$(ob output -b "$B" drop 2>&1)"
  check_eq "...none listed" "[]" "$(ob hyprctl -b "$B" -j monitors | jq -c '[.[] | select(.name != "FALLBACK")]')"
  out=$(ob output -b "$B" back); rc=$?
  check_eq "output back: both, the main screen first" "0 $before"$'\n'"$m1 1280x800@60" "$rc $out"
  check_eq "...modes, places and scales as before" "$ml" "$(ob monitor -b "$B" list --json | jq -c "$list")"
  check_match "...and nothing left to bring back" "nothing to bring back" "$(ob output -b "$B" back 2>&1)"
  out=$(ob output -b "$B" drop "$m1" --for 200ms --cycles 2); rc=$?
  check_eq "drop $m1 --for 200ms --cycles 2: that one, back each time" \
    "0 $(for i in 1 2; do echo "cycle $i/2: gone for 0.20s, back as $m1 1280x800@60; shell running"; done)" "$rc $out"
  check_eq "...every monitor as before" "$ml" "$(ob monitor -b "$B" list --json | jq -c "$list")"
  # One back while the main screen is away goes below it by its mode as `mode` set it, not as the
  # config was loaded with (1280x720: it went to 0,720, inside the main screen once that was back).
  ob mode -b "$B" 1600x900 >/dev/null 2>&1
  ob output -b "$B" drop >/dev/null 2>&1; ob output -b "$B" drop "$m1" >/dev/null 2>&1; ob output -b "$B" back "$m1" >/dev/null 2>&1
  check_eq "after mode 1600x900, both dropped, the monitor back alone: below the main screen's 900" "0,900" \
    "$(ob monitor -b "$B" list --json | jq -r --arg n "$m1" '.[] | select(.name == $n) | "\(.x),\(.y)"')"
  ob output -b "$B" back >/dev/null 2>&1; ob mode -b "$B" 1280x720 >/dev/null 2>&1
  check_eq "...the main screen back, mode 1280x720: all as before" "$ml" "$(ob monitor -b "$B" list --json | jq -c "$list")"
  if [ "$m0" = WAYLAND-1 ]; then
    # Finding 279 (#200): labwc's first configure of the window came after the mode was set (seen under
    # load; made certain here by stopping labwc a while) and left it at 1280x720; back failed, kept it as
    # dropped, and the box listed it twice. (The sleep is the point: labwc late by over a second.)
    local lp lt; ob mode -b "$B" 1600x900 >/dev/null 2>&1; ob output -b "$B" drop >/dev/null 2>&1
    lp=$(ob run -b "$B" -- pgrep -xo omabox-labwc)
    ob run -b "$B" -- kill -STOP "$lp"
    ob output -b "$B" back > "$TMP/late.out" 2>&1 & lt=$!
    sleep 1.2; ob run -b "$B" -- kill -CONT "$lp"
    wait "$lt"; rc=$?
    check_eq "labwc late to configure the main screen's window: back at its mode all the same (finding 279)" "0 $m0 1600x900@60" "$rc $(cat "$TMP/late.out")"
    check_eq "...listed once, not dropped" "[\"$m0 1600x900@60\"]" \
      "$(ob monitor -b "$B" list --json | jq -c --arg n "$m0" '[.[] | select(.name == $n) | "\(.name) \(.mode)\(if .dropped then " dropped" else "" end)"]')"
    ob mode -b "$B" 1280x720 >/dev/null 2>&1
  fi
  out=$(ob output -b "$B" drop --for 300ms --cycles 3); rc=$?
  check_eq "drop --for 300ms --cycles 3: exit 0" 0 "$rc"
  check_eq "...three cycles, each back as before, the shell running" \
    "$(for i in 1 2 3; do echo "cycle $i/3: gone for 0.30s, back as $before; shell running"; done)" "$out"
  check_eq "...the box's mode as before" "$before" "$(ob mode -b "$B")"
  check "...the shell saw the screen go (its log)" until_ok 5 bash -c "'$CLI' log -b '$B' shell | grep -q 'There are no outputs'"
  check "...a shot of the main screen is the size it was" bash -c "'$CLI' shot -b '$B' --monitor '$m0' -o '$TMP/out.png' >/dev/null 2>&1 && file '$TMP/out.png' | grep -q '1280 x 720,'"
  # A shell crash ends the cycles, its report named (a SIGSEGV stands in for a plugin's crash).
  ( sleep 2.5; shell_segv "$B" ) & local k=$!
  out=$(ob output -b "$B" drop --for 1s --cycles 8 2>&1); rc=$?
  wait "$k"
  check_eq "a shell crash during the cycles: exit 1" 1 "$rc"
  check_match "...said, with its report" "shell crashed"$'\n'"omabox: output: the shell crashed in cycle [1-8] \(report: $(ob path "$B")/home/\.cache/quickshell/crashes/[^/]+/report\.txt;" "$out"
  check_eq "...the screen is back all the same" "$before" "$(ob mode -b "$B")"
  ob down "$B" >/dev/null 2>&1
}

# gpu release (t_unit_gpu's) on boxes of a runtime dir of the test's own (never the real ones: it
# takes boxes down), up while their info.json names a stand-in for a box's PID 1 (a process in a pid
# namespace of its own), taken down for real: headless boxes on that GPU only, by kind or slot; a box
# with no record by the render node its process holds open (this machine's first usable one; none
# here: that case skipped).
gpu_release_cases() {
  local rt=$TMP/gpu-rel bx k other none dv="" sl="" node b
  mkdir -p "$rt/omabox"; chmod 700 "$rt"; bx=$rt/omabox
  node=$(probe render_node 2>/dev/null) || node=""
  if [ -n "$node" ]; then dv=$(probe render_driver "$node"); sl=$(readlink -f "/sys/class/drm/${node##*/}/device"); sl=${sl##*/}; fi
  case $dv in nvidia|nouveau) k=nvidia ;; amdgpu|radeon) k=amd ;; i915|xe) k=intel ;; *) k=nvidia node="" ;; esac
  [ -n "$dv" ] && [ -n "$node" ] || dv=nvidia
  case $k in nvidia) other=amd none=intel ;; amd) other=nvidia none=intel ;; *) other=nvidia none=amd ;; esac
  local -A odv=([nvidia]=nvidia [amd]=amdgpu [intel]=i915)
  # live NAME JSON [HOLD]: box NAME up on a stand-in (holding HOLD open), box.json JSON plus its pidns
  live() {
    local u p="" i
    if [ -n "${3:-}" ]; then u=$(unshare -Urpf --mount-proc --propagation slave sh -c 'exec 3<"$0"; exec sleep 600' "$3" >/dev/null 2>&1 & echo $!)
    else u=$(unshare -Urpf --mount-proc --propagation slave sleep 600 >/dev/null 2>&1 & echo $!); fi
    echo "$u" >> "$rt/pids"
    for i in $(seq 100); do p=$(pgrep -P "$u") && [ -n "$p" ] && { [ -z "${3:-}" ] || readlink "/proc/$p/fd/3" >/dev/null 2>&1; } && break; sleep 0.05; done
    mkdir -p "$bx/$1/home" "$bx/$1/run"
    jq --arg ns "$(readlink "/proc/$p/ns/pid")" '. + {pidns: $ns}' <<<"$2" > "$bx/$1/box.json"
    echo "{\"child-pid\": $p}" > "$bx/$1/info.json"
  }
  live a "{\"mode\": \"headless\", \"render\": {\"node\": \"/dev/dri/renderD200\", \"pci\": \"0000:01:00.0\", \"driver\": \"$dv\", \"fallback\": false}}"
  live b "{\"mode\": \"headless\", \"render\": {\"node\": \"/dev/dri/renderD201\", \"pci\": \"0000:0a:00.0\", \"driver\": \"${odv[$other]}\", \"fallback\": false}}"
  live c '{"mode": "interactive"}'
  [ -z "$node" ] || live d '{"mode": "headless"}' "$node"
  mkdir -p "$bx/e"; echo "{\"mode\": \"headless\", \"render\": {\"node\": \"/dev/dri/renderD200\", \"pci\": \"0000:01:00.0\", \"driver\": \"$dv\", \"fallback\": false}}" > "$bx/e/box.json"
  rel() { XDG_RUNTIME_DIR=$rt ob gpu release "$@" 2>&1; }
  local out; out=$(rel "$k")
  check_match "gpu release $k: the live headless boxes on it taken down, each said" "taking box 'a' down \(it renders on $dv 0000:01:00\.0\)" "$out"
  if [ -n "$node" ]; then
    check_match "...one with no record by what it holds" "taking box 'd' down \(it renders on $dv $sl\)" "$out"
  else
    skip "gpu release: a box with no record, by the node it holds" "no usable render node here"
  fi
  check_eq "...those gone; the other GPU's, the interactive and the dead one kept" "b c e" "$(command find "$bx" -mindepth 1 -maxdepth 1 -type d -printf '%f\n' | LC_ALL=C sort | xargs)"
  check_eq "...by slot, written short" "1" "$(rel 0a:00.0 | grep -c "taking box 'b' down")"
  check "...and gone" test ! -e "$bx/b"
  check_match "...none on it: said, exit 0" "no headless box renders on $none" "$(rel "$none"; echo "rc=$?")"
  check_match "...junk refused" "not a GPU: geforce" "$(rel geforce)"
  check_match "...refused to a jailed agent" "not a jailed agent's" "$(OMABOX_JAIL='{"id":"x"}' XDG_RUNTIME_DIR=$rt ob gpu release "$k" 2>&1)"
  # An `up` in progress (its lock held, no box.json yet) is waited for (finding 237): here box f's up
  # writes its box.json, on that GPU, and lets go of the lock a second on.
  local fu fp
  fu=$(unshare -Urpf --mount-proc --propagation slave sleep 600 >/dev/null 2>&1 & echo $!); echo "$fu" >> "$rt/pids"
  for b in $(seq 100); do fp=$(pgrep -P "$fu") && [ -n "$fp" ] && break; sleep 0.05; done
  : > "$bx/.lock-f"
  flock "$bx/.lock-f" bash -c "sleep 1; mkdir -p '$bx/f/home' '$bx/f/run'
    jq -n --arg ns '$(readlink "/proc/$fp/ns/pid")' '{mode: \"headless\", pidns: \$ns, render: {node: \"/dev/dri/renderD200\", pci: \"0000:01:00.0\", driver: \"$dv\", fallback: false}}' > '$bx/f/box.json'
    echo '{\"child-pid\": $fp}' > '$bx/f/info.json'" &
  local holder=$!
  until_ok 5 bash -c "! flock -n '$bx/.lock-f' true"
  out=$(rel "$k"); wait "$holder"
  check_match "gpu release waits for an up in progress, said" "waiting for box 'f' \(an up or down in progress\)" "$out"
  check_match "...and takes its box down too" "taking box 'f' down" "$out"
  check "...gone" test ! -e "$bx/f"
  local u; while read -r u; do pkill -KILL -P "$u" 2>/dev/null; done < "$rt/pids"
  true
}

# omabox cpu (#205, finding 277) in a box: a busy loop is ~one core, by --pid (the box's number or the
# host's) and --app; an idle box is near 0; --json has gpu's shape plus processes and a total.
t_cpu() {
  local B=$P-cpu out j bp hp t0 t1 w0 w1 own got
  up_ok "$B" --no-shell --net isolated || { no "up" "$UP_OUT"; return; }
  j=$(ob cpu -b "$B" 2 --json)
  check "cpu --json parses, with gpu's fields and its own" jq -e '.box and .output and .mode and (.seconds == 2) and (.percent | type == "object")
    and (.processes | length > 0) and (.total | has("cpu") and has("rss_kb") and has("pss_kb")) and (.cores > 0) and has("render")' <<<"$j"
  check "...every process with pid, host_pid, name, cpu, rss_kb, pss_kb, started, exited" \
    jq -e '[.processes[] | keys == ["cpu","exited","host_pid","name","pid","pss_kb","rss_kb","started"]] | all' <<<"$j"
  check "...the box's own: Hyprland at its pid in the box" jq -e --argjson p "$(ob run -b "$B" -- pgrep -xo Hyprland)" \
    '[.processes[] | select(.name == "Hyprland" and .pid == $p)] | length == 1' <<<"$j"
  check "an idle box: under 30% of one core in all" jq -e '.total.cpu < 30' <<<"$j"
  check "...RSS read, PSS too, no larger" jq -e '.total.rss_kb > 10000 and .total.pss_kb > 0 and .total.pss_kb <= .total.rss_kb' <<<"$j"
  ob run -b "$B" -d -q -- sh -c 'while :; do :; done' >/dev/null 2>&1
  until_ok 5 ob run -b "$B" -- pgrep -x sh >/dev/null
  bp=$(ob run -b "$B" -- pgrep -xn sh) || bp=0
  hp=$(ob cpu -b "$B" 0.2 --pid "$bp" --json | jq -r '.processes[0].host_pid // 0')
  # A busy loop gets one core only on an idle machine (a full parallel run gave it 64%): cpu's figure
  # is checked against the loop's own ticks over the same window, read from the host's /proc.
  # own_ticks HOSTPID: utime + stime (fields 14, 15; after the last `)`, as cpu reads them).
  own_ticks() { local st; st=$(cat "/proc/$1/stat" 2>/dev/null) || { echo 0; return; }; st=${st##*) }; awk '{print $12 + $13}' <<<"$st"; }
  t0=$(own_ticks "$hp"); w0=$(date +%s.%N)
  out=$(ob cpu -b "$B" 2 --pid "$bp")
  t1=$(own_ticks "$hp"); w1=$(date +%s.%N)
  own=$(awk -v d=$((t1 - t0)) -v hz="$(getconf CLK_TCK)" -v a="$w0" -v b="$w1" 'BEGIN { printf "%.0f", d / hz / (b - a) * 100 }')
  got=$(awk -v p="$bp" '$1 == "sh" && $2 == p { sub("%", "", $3); print $3 }' <<<"$out")
  check_match "cpu --pid: the busy loop's line" $'\n  sh +'"$bp"' +[0-9]+\.[0-9]%' "$out"
  check "...at its own share of a core (its ticks over the window: ${own}%, cpu: ${got:-none}%), more than a fifth" \
    awk -v g="${got:-0}" -v e="$own" 'BEGIN { exit !(g > 20 && g >= e - 20 && g <= e + 20) }'
  check_eq "...that process alone, and the total" 2 "$(grep -cE '^  (sh|total) ' <<<"$out")"
  j=$(ob cpu -b "$B" 1s --settle 500ms --app sh --json)
  hp=$(jq -r '.processes[0].host_pid' <<<"$j")
  check_eq "cpu 1s --settle 500ms: units read (#273), seconds in --json" "1 0.5" "$(jq -r '"\(.seconds) \(.settle)"' <<<"$j")"
  check_eq "cpu --app sh: the processes named sh only" "sh" "$(jq -r '[.processes[].name] | unique | join(" ")' <<<"$j")"
  check "...the busy one busy (more than a fifth of a core)" jq -e --argjson p "$bp" '.processes[] | select(.pid == $p) | .cpu > 20' <<<"$j"
  check "...its host pid is the box's (omabox which)" test "$(ob which "$hp" 2>/dev/null)" = "$B"
  check "cpu --pid HOSTPID: the same process" jq -e --argjson p "$bp" '.processes | length == 1 and .[0].pid == $p' \
    <<<"$(ob cpu -b "$B" 1 --pid "$hp" --json)"
  check_match "cpu --pid not in the box: refused before the window" "has no process 4999999" "$(ob cpu -b "$B" 5 --pid 4999999 2>&1)"
  check_match "cpu --app not there: said" "ran no process nope" "$(ob cpu -b "$B" 0.5 --app nope 2>&1)"
  ob run -b "$B" -- pkill -x sh >/dev/null 2>&1
  # --threads (#242): a python3 whose main thread sleeps, one thread busy and two idle of one name,
  # each naming itself through its own /proc comm (Thread(name=) sets none before 3.14).
  local prog='import threading, time
def named(n):
    open("/proc/self/task/%d/comm" % threading.get_native_id(), "w").write(n)
def burn():
    named("omaburn")
    while True: pass
def idle():
    named("omaidle")
    while True: time.sleep(1)
for f in (burn, idle, idle): threading.Thread(target=f, daemon=True).start()
while True: time.sleep(1)'
  ob run -b "$B" -d -q -- python3 -c "$prog" >/dev/null 2>&1
  until_ok 5 ob run -b "$B" -- sh -c 'grep -qx omaburn /proc/$(pgrep -xn python3)/task/*/comm'
  bp=$(ob run -b "$B" -- pgrep -xn python3) || bp=0
  j=$(ob cpu -b "$B" 2 --app python3 --threads --json)
  check "cpu --threads --json: python3's threads, each with tid, host_tid, name, cpu, started, exited" jq -e --argjson p "$bp" \
    '.processes | length == 1 and .[0].pid == $p and ([.[0].threads[] | keys == ["cpu","exited","host_tid","name","started","tid"]] | all)' <<<"$j"
  check_eq "...every thread, by the box's tids" "$(ob run -b "$B" -- ls "/proc/$bp/task" | sort -n | tr '\n' ' ')" \
    "$(jq -r '[.processes[0].threads[].tid] | sort | map(tostring + " ") | add' <<<"$j")"
  check "...the busy thread by its name, more than a fifth of a core" jq -e '[.processes[0].threads[] | select(.name == "omaburn" and .cpu > 20)] | length == 1' <<<"$j"
  check "...the main thread (tid = pid) apart from it, under a tenth" jq -e --argjson p "$bp" \
    '[.processes[0].threads[] | select(.tid == $p and .name == "python3" and .cpu < 10)] | length == 1' <<<"$j"
  check "...two threads of one name: two rows" jq -e '[.processes[0].threads[] | select(.name == "omaidle")] | length == 2' <<<"$j"
  check "...the threads add up to about the process" jq -e '.processes[0] | ([.threads[].cpu] | add) as $s | $s >= .cpu - 5 and $s <= .cpu + 5' <<<"$j"
  out=$(ob cpu -b "$B" 1 --pid "$bp" --threads)
  check_match "cpu --pid --threads: the table, threads under the process" $'\n  python3 +'"$bp"$' +[0-9.]+%.*\n    omaburn +[0-9]+ +[0-9.]+%\n' "$out"
  ob run -b "$B" -- pkill -x python3 >/dev/null 2>&1
  ob down "$B" >/dev/null 2>&1
}

# omabox gdb (#135, finding 211): a backtrace of the box's Hyprland, running or stopped, of a process
# of the box, and --watch catching a crash; a gdb of the box's own (run) is still refused.
t_gdb() {
  local B=$P-gdb out rc D i
  check_match "gdb: --watch and -- ARGS refused" "--watch runs its own" "$(ob gdb -b "$P-x" --watch -- -ex bt 2>&1)"
  check_match "gdb: --pid junk refused" "--pid takes a pid" "$(ob gdb -b "$P-x" --pid x 2>&1)"
  check_match "gdb: gdb's options after --" "after --" "$(ob gdb -b "$P-x" -ex bt 2>&1)"
  # (gdb is a jailed agent's: broker_side.rs's broker_check_allows_and_refuses)
  up_ok "$B" --no-shell --net isolated || { no "up" "$UP_OUT"; return; }
  D=$(ob path "$B")
  out=$(ob gdb -b "$B" 2>&1); rc=$?
  check_eq "gdb: exit 0" 0 "$rc"
  check_match "...every thread's backtrace, down to main" $'\n#[0-9]+ +0x[0-9a-f]+ in main \\(\\)' "$out"
  # Finding 345: a caller's own fd (7 here) is never one of gdb's steps in the box (pgrep, sed, cat):
  # FD_SEEN logs every box process fd that names a fdprobe file; the box's own one says it looks.
  echo caller > "$TMP/fdprobe-caller"
  ob run -b "$B" -d -q -- python3 -c "$FD_SEEN"
  ob run -b "$B" -d -q -- sh -c 'echo box > /tmp/fdprobe-box; exec 5</tmp/fdprobe-box; sleep 600'
  check "...(the box's own fd is seen: the watch works)" until_ok 5 ob run -b "$B" -- grep -q fdprobe-box /tmp/fdseen
  for i in 1 2 3 4 5; do ob gdb -b "$B" -- -ex 'info threads' 7<"$TMP/fdprobe-caller" >/dev/null 2>&1; done
  check_eq "gdb: a caller's fd 7 reaches no process in the box, in five runs" "" "$(ob run -b "$B" -- grep fdprobe-caller /tmp/fdseen)"
  check_match "a gdb run in the box itself is still refused (ptrace_scope)" "ptrace: Operation not permitted" \
    "$(ob run -b "$B" -- gdb -nx -batch -p "$(ob run -b "$B" -- pgrep -xo Hyprland)" 2>&1)"
  ob run -b "$B" -- pkill -STOP -xo Hyprland
  out=$(timeout 30 "$CLI" gdb -b "$B" 2>&1); rc=$?
  check_match "a stopped Hyprland: backtraced (exit $rc)" $'\n#[0-9]+ +0x[0-9a-f]+ in main \\(\\)' "$out"
  check_match "...and left stopped" "^State:.*stopped" "$(ob run -b "$B" -- grep State "/proc/$(ob run -b "$B" -- pgrep -xo Hyprland)/status")"
  ob run -b "$B" -- pkill -CONT -xo Hyprland
  check "...it answers again" until_ok 5 ob hyprctl -b "$B" version
  ob run -b "$B" -d -q -- sleep 600
  local sp="" i; for i in $(seq 50); do sp=$(ob run -b "$B" -- pgrep -xn sleep 2>/dev/null) && [ -n "$sp" ] && break; sleep 0.1; done
  check_match "gdb --pid: a process of the box" "in (clock_nanosleep|__GI___clock_nanosleep|nanosleep)|#0 " "$(ob gdb -b "$B" --pid "$sp" 2>&1)"
  check_match "...one it has not: refused" "has no process 99999" "$(ob gdb -b "$B" --pid 99999 2>&1)"
  check_match "gdb --shell with no shell: refused" "has no shell running" "$(ob gdb -b "$B" --shell 2>&1)"
  # finding 229: the box's gdb.log linked to a host file, and a process named with a newline and an
  # escape. The watch's header is written in the box: the host file untouched, the log a file again.
  echo keep > "$TMP/gdb-victim"
  ob run -b "$B" -- ln -sf "$TMP/gdb-victim" /home/sbx/gdb.log
  # (in one write: bash's printf writes up to the newline first, and each write replaces the name)
  ob run -b "$B" -d -q -- python3 -c 'import os, time
os.write(os.open("/proc/self/comm", os.O_WRONLY), b"x\x1b[1my\nz"); open("/tmp/t229.pid", "w").write(str(os.getpid())); time.sleep(600)'
  local wp; until_ok 5 ob run -b "$B" -- test -s /tmp/t229.pid >/dev/null; wp=$(ob run -b "$B" -- cat /tmp/t229.pid)
  out=$(ob gdb -b "$B" --pid "$wp" --watch 2>&1); rc=$?
  check_eq "gdb --watch over a gdb.log linked to a host file: exit 0" 0 "$rc"
  check_eq "...that file untouched" keep "$(cat "$TMP/gdb-victim")"
  check "...the box's gdb.log a file of its own" test -f "$D/home/gdb.log" -a ! -L "$D/home/gdb.log"
  check_match "...a name with a newline and an escape: printed tamed" "gdb watches x\?\?1my\?z \(pid $wp in box" "$out"
  check_match "...in the header too" "== omabox gdb --watch x\?\?1my\?z \(pid $wp in the box\)" "$(ob log -b "$B" gdb -n all 2>&1)"
  # (its caller at a core limit of 2 bytes, which nothing but omabox lowers to 1: the check below)
  out=$(prlimit --core=2: "$CLI" gdb -b "$B" --watch 2>&1); rc=$?
  check_eq "gdb --watch: exit 0" 0 "$rc"
  check_match "...said, with where the backtrace goes" "gdb watches Hyprland .*omabox log -b $B gdb" "$out"
  # ...from the box's network namespace (finding 229), not the host's: the gdb that is the box's
  # (its pid namespace) and traces.
  local bp g gn=""; bp=$(cat "$D/pid")
  for g in $(pgrep -x gdb); do
    [ "$(readlink "/proc/$g/ns/pid")" = "$(readlink "/proc/$bp/ns/pid")" ] && gn+="$(readlink "/proc/$g/ns/net") "
  done
  check_eq "...gdb in the box's network namespace" "$(readlink "/proc/$bp/ns/net") $(readlink "/proc/$bp/ns/net") " "$gn"
  # A crash of the watching gdb makes no notification on the desktop either (findings 67, 492).
  local gc=""
  for g in $(pgrep -x gdb); do
    [ "$(readlink "/proc/$g/ns/pid")" = "$(readlink "/proc/$bp/ns/pid")" ] && gc+="$(prlimit --pid "$g" --core -o SOFT --noheadings | tr -d ' ') "
  done
  check_eq "...its core limit 1 byte, its caller's 2" "1 1 " "$gc"
  check_match "...a second gdb: refused, naming the watch" "traced already, by pid [0-9]+" "$(ob gdb -b "$B" 2>&1)"
  # #233: the first watch's process killed, not crashed: gdb runs its crash commands all the same, and --crash finds none.
  ob run -b "$B" -- kill -KILL "$wp"
  check "the first watch's process killed: its gdb done" until_ok 10 bash -c "'$CLI' log -b '$B' gdb -n all | grep -q '^== omabox: end'"
  check_match "...log gdb --crash: no crash" "has no crash in its gdb log" "$(ob log -b "$B" gdb --crash 2>&1)"
  check_match "log --crash: the gdb log's alone" "the gdb log's alone" "$(ob log -b "$B" shell --crash 2>&1)"
  ob run -b "$B" -- pkill -SEGV -xo Hyprland
  check "...a crash: the box goes down as it would have" until_ok 15 bash -c "'$CLI' ls --json | jq -e '.[] | select(.name == \"$B\") | .state == \"dead\"'"
  out=$(ob log -b "$B" gdb -n all 2>&1)
  check_match "...the gdb log has the signal" "received signal SIGSEGV" "$out"
  check_match "...and every thread's backtrace, down to main" $'\n#[0-9]+ +0x[0-9a-f]+ in main \\(\\)' "$out"
  # #233: the thread the signal hit first, right under the signal, then every thread.
  check_match "...the thread it hit first, under the signal" \
    $'received signal SIGSEGV[^=]*\n== omabox: a fatal signal; the thread it hit:\n\\[Current thread is [0-9]+ [^\n]*\n#0 [^=]* in main \\(\\)\n\n== omabox: every thread:\n' "$out"
  out=$(ob log -b "$B" gdb --crash 2>&1)
  local th; th=$(sed -n 's/^Thread \([0-9]*\) .* received signal SIGSEGV.*/\1/p' <<<"$out")
  check_match "...log gdb --crash: the signal and that thread, down to main" \
    $'^== omabox gdb --watch Hyprland [^\n]*\nThread '"$th"$' [^\n]* received signal SIGSEGV[^\n]*\n\\[Current thread is '"$th"$' [^\n]*\n(#[0-9]+ [^\n]*\n)*#[0-9]+ +0x[0-9a-f]+ in main \\(\\)$' "$out"
  ob down "$B" >/dev/null 2>&1
}

# (hypr_lost, hung_text, hypr_gone and hypr_end, #232, findings 181-182, 350: hypr.rs
# hypr_lost_as_bash, its box's processes and states stand-ins; #324 wave 6-suite.)

# (hypr_errors_note, finding 353, hyprctl's answers stand-ins: hypr.rs hypr_errors_note_as_bash;
# #324 wave 6-suite.)

# log gdb --crash (#233) on a gdb log of two watches: one whose process was killed (gdb runs its crash
# commands anyway: no crash), one that crashed in thread 3. Only that one, without the other threads.
t_unit_gdb_crashes() {
  local log=$'\n== omabox gdb --watch sleep (pid 9 in the box), T1\n\nProgram terminated with signal SIGKILL, Killed.\n'
  log+=$'\n== omabox: a fatal signal; the thread it hit:\nNo thread selected\nNo stack.\n\n== omabox: every thread:\n== omabox: end\n'
  log+=$'\n== omabox gdb --watch Hyprland (pid 55 in the box), T2\n[New LWP 60]\n0x1 in ?? () from libc\n\n'
  log+=$'Thread 3 "worker" received signal SIGSEGV, Segmentation fault.\n0x2 in crash ()\n'
  log+=$'\n== omabox: a fatal signal; the thread it hit:\n[Current thread is 3 (LWP 60)]\n#0  0x2 in crash ()\n#1  0x3 in start ()\n'
  log+=$'\n== omabox: every thread:\n\nThread 3 (LWP 60):\n#0  0x2 in crash ()\n\nThread 1 (LWP 55):\n#0  0x4 in main ()\n== omabox: end\n'
  check_eq "gdb_crashes: the crash's header, signal and thread, nothing else" \
    $'== omabox gdb --watch Hyprland (pid 55 in the box), T2\nThread 3 "worker" received signal SIGSEGV, Segmentation fault.\n[Current thread is 3 (LWP 60)]\n#0  0x2 in crash ()\n#1  0x3 in start ()' \
    "$(probe gdb_crashes <<<"$log")"
  local one=$'== omabox gdb --watch a (pid 2 in the box), T3\nProgram received signal SIGABRT, Aborted.\n'
  one+=$'== omabox: a fatal signal; the thread it hit:\n#0  0x5 in abort ()\n== omabox: every thread:\n#0  0x5 in abort ()\n== omabox: end\n'
  check_eq "...a single-threaded one's (Program received signal), two crashes apart" \
    $'== omabox gdb --watch a (pid 2 in the box), T3\nProgram received signal SIGABRT, Aborted.\n#0  0x5 in abort ()\n\n== omabox gdb --watch a (pid 2 in the box), T3\nProgram received signal SIGABRT, Aborted.\n#0  0x5 in abort ()' \
    "$(probe gdb_crashes <<<"$one$one")"
}

# The gpu setting (#156, finding 214) on a stand-in tree the probe reads under (its ROOT word): an AMD
# and an NVIDIA GPU in ROOT/dev/dri, ROOT/sys/class/drm and ROOT/sys/bus/pci/devices. A render node
# keeps the system's path (/dev/dri/renderD*); only the reads are the tree's.
t_unit_gpu() {
  local f=$TMP/gpu
  local dri=$f/dev/dri drm=$f/sys/class/drm pci=$f/sys/bus/pci/devices cf=$f/home/.config/omabox/config
  mkdir -p "$dri" "$drm/renderD128" "$drm/renderD129" "$pci/0000:0a:00.0" "$pci/0000:01:00.0" "$f/drivers/amdgpu" "$f/drivers/nvidia" "${cf%/*}" "$f/bin"
  : > "$dri/renderD128"; : > "$dri/renderD129"
  ln -sfn "$pci/0000:0a:00.0" "$drm/renderD128/device"; ln -sfn "$pci/0000:01:00.0" "$drm/renderD129/device"
  ln -sfn "$f/drivers/amdgpu" "$pci/0000:0a:00.0/driver"; ln -sfn "$f/drivers/nvidia" "$pci/0000:01:00.0/driver"
  echo 0x030000 > "$pci/0000:0a:00.0/class"; echo 0x030200 > "$pci/0000:01:00.0/class"
  echo 0x1002 > "$pci/0000:0a:00.0/vendor"; echo 0x10de > "$pci/0000:01:00.0/vendor"
  # gv NAME VALUE ARGS...: the probe's NAME with the gpu setting VALUE in a HOME of its own (and no
  # OMABOX_RENDER_NODE), the tree its root.
  gv() { local n=$1; printf 'gpu=%s\n' "$2" > "$cf"; shift 2; HOME=$f/home OMABOX_RENDER_NODE='' probe "$n" "$@" 2>&1; }
  pick() { gv render_node "$1" "$f"; }
  check_eq "gpu auto: the first GPU" /dev/dri/renderD128 "$(pick auto)"
  check_eq "gpu nvidia: its render node" /dev/dri/renderD129 "$(pick nvidia)"
  check_eq "gpu amd" /dev/dri/renderD128 "$(pick amd)"
  check_eq "gpu by PCI slot" /dev/dri/renderD129 "$(pick 0000:01:00.0)"
  check_eq "gpu intel, none here: the first GPU, said, with why and which (finding 237)" \
    "omabox: gpu intel (omabox config gpu): none usable here (no intel GPU on this machine), so the first GPU: amdgpu 0000:0a:00.0 (renderD128)"$'\n'/dev/dri/renderD128 "$(pick intel)"
  rm "$dri/renderD129"; mkdir -p "$f/drivers/vfio-pci"; ln -sfn "$f/drivers/vfio-pci" "$pci/0000:01:00.0/driver"
  check_eq "gpu nvidia, the card on vfio-pci (no node): the first GPU, said, the card's reason given (finding 237)" \
    "omabox: gpu nvidia (omabox config gpu): none usable here (0000:01:00.0: bound to vfio-pci), so the first GPU: amdgpu 0000:0a:00.0 (renderD128)"$'\n'/dev/dri/renderD128 "$(pick nvidia)"
  check_match "...a slot that is no GPU: said" "none usable here \(no GPU at 0000:05:00.0\)" "$(pick 0000:05:00.0)"
  # The record a fallback leaves (box.json's render, as up writes it) and `ls`'s line for it, in a
  # runtime dir of the test's own; the GPU line shows for every box only with two usable GPUs here
  # (finding 237).
  local lb=$TMP/gpu-ls; mkdir -p "$lb/omabox/fb" "$lb/omabox/plain"; chmod 700 "$lb"
  jq -n '{mode: "headless", size: "1x1@60", net: "none", idle: 0, render: {node: "/dev/dri/renderD128", pci: "0000:0a:00.0", driver: "amdgpu", fallback: true, wanted: "nvidia", why: "0000:01:00.0: bound to vfio-pci"}}' > "$lb/omabox/fb/box.json"
  jq -n '{mode: "headless", size: "1x1@60", net: "none", idle: 0, render: {node: "/dev/dri/renderD128", pci: "0000:0a:00.0", driver: "amdgpu", fallback: false}}' > "$lb/omabox/plain/box.json"
  local lsout many=0; [ "$(probe render_nodes | wc -l)" -lt 2 ] || many=1
  lsout=$(XDG_RUNTIME_DIR=$lb ob ls 2>&1)
  check_match "ls: a fallback box's GPU line, with why" \
    $'\nfb [^\n]*\n  GPU: amdgpu 0000:0a:00.0 \\(renderD128\\), a fallback: gpu nvidia was not usable \\(0000:01:00.0: bound to vfio-pci\\)' "$lsout"
  if [ "$many" = 0 ]; then
    check_eq "...none for a box that is not one, with one usable GPU here" "" "$(grep -A1 '^plain ' <<<"$lsout" | sed -n 2p | grep GPU)"
  else
    check_match "...with two usable GPUs here, every box's" $'\nplain [^\n]*\n  GPU: amdgpu 0000:0a:00.0 \\(renderD128\\)($|\n)' "$lsout"
  fi
  # Apps on a software renderer (#204, finding 290): eglinfo's verdict as up keeps it, and what up,
  # ls and gpu say of it. Its output as seen in an NVIDIA box (warnings and all) and in an AMD one.
  local eg_nv eg_amd
  eg_nv=$'MESA-EGL: warning: egl: failed to create dri2 screen\nWayland platform:\nEGL vendor string: Mesa Project\nOpenGL core profile renderer: llvmpipe (LLVM 22.1.8, 256 bits)\nOpenGL ES profile vendor: Mesa\nOpenGL ES profile renderer: llvmpipe (LLVM 22.1.8, 256 bits)\nOpenGL ES profile version: OpenGL ES 3.2 Mesa 26.2.2'
  eg_amd=$'Wayland platform:\nOpenGL core profile renderer: AMD Radeon (radeonsi, raphael_mendocino, ACO)\nOpenGL ES profile renderer: AMD Radeon (radeonsi, raphael_mendocino, ACO)'
  check_eq "egl_render: llvmpipe is software" '{"renderer":"llvmpipe (LLVM 22.1.8, 256 bits)","software":true}' "$(probe egl_render <<<"$eg_nv")"
  check_eq "...radeonsi is not" '{"renderer":"AMD Radeon (radeonsi, raphael_mendocino, ACO)","software":false}' "$(probe egl_render <<<"$eg_amd")"
  check_eq "...the ES profile's first, else the first renderer named" "softpipe true" \
    "$(probe egl_render <<<$'OpenGL core profile renderer: softpipe' | jq -r '"\(.renderer) \(.software)"')"
  check_eq "...nothing when EGL did not initialise" "" "$(probe egl_render <<<'eglinfo: eglInitialize failed')"
  check_eq "...nor from no output (no eglinfo)" "" "$(probe egl_render </dev/null)"
  local soft='{"renderer":"llvmpipe (LLVM 22.1.8, 256 bits)","software":true}'
  check_match "soft_note: llvmpipe in an NVIDIA box, why, and a box on the other GPU" \
    "^its apps render on llvmpipe, in software \(NVIDIA's EGL did not initialise in it.*omabox gpu counts none of their drawing; for GPU rendering, a box on another GPU: OMABOX_RENDER_NODE=/dev/dri/renderD128 omabox up --new \(renderD128 is amdgpu\)$" \
    "$(probe soft_note "$soft" nvidia "renderD128 amdgpu")"
  check_match "...no other GPU: a baseline in the same box" "this machine has no other GPU: compare against a baseline measured in this same box$" "$(probe soft_note "$soft" nvidia "")"
  check_match "...an interactive box (no GPU of its own): a baseline" "omabox gpu counts none of their drawing; compare against a baseline" "$(probe soft_note "$soft" "")"
  check_eq "...nothing for a GPU renderer" "" "$(probe soft_note '{"renderer":"AMD Radeon (radeonsi)","software":false}' amdgpu "")"
  check_eq "...nor for no record" "" "$(probe soft_note "" nvidia "")"
  # (up's probe, box_exec's output and other_gpu given: ready.rs client_render_as_bash, #[ignore])
  # ls: an apps line for a box on software only.
  jq '.client_render = {renderer: "llvmpipe (LLVM 22.1.8, 256 bits)", software: true}' "$lb/omabox/fb/box.json" > "$lb/b" && mv "$lb/b" "$lb/omabox/fb/box.json"
  jq '.client_render = {renderer: "AMD Radeon (radeonsi)", software: false}' "$lb/omabox/plain/box.json" > "$lb/b" && mv "$lb/b" "$lb/omabox/plain/box.json"
  lsout=$(XDG_RUNTIME_DIR=$lb ob ls 2>&1)
  check_match "ls: apps on llvmpipe said under the box" $'\n  apps: llvmpipe, in software \\(cost measured here is software rendering\'s\\)' "$lsout"
  check_eq "...not for a box on a GPU renderer" "" "$(grep -A2 '^plain ' <<<"$lsout" | grep 'apps:')"
  check_eq "ls --json: the record" "true false" "$(XDG_RUNTIME_DIR=$lb ob ls --json 2>/dev/null | jq -r 'map(.client_render.software | tostring) | join(" ")')"
  check "render_fallback: gpu nvidia, the box on the AMD one" gv render_fallback nvidia /dev/dri/renderD128 "$f"
  check_eq "gpu_why_not: the reason up records" "0000:01:00.0: bound to vfio-pci" "$(gv gpu_why_not nvidia nvidia "$f")"
  ln -sfn "$f/drivers/nvidia" "$pci/0000:01:00.0/driver"
  printf 'gpu=nvidia\n' > "$cf"
  check_eq "OMABOX_RENDER_NODE still first" /dev/dri/renderD128 "$(HOME=$f/home OMABOX_RENDER_NODE=/dev/dri/renderD128 probe render_node "$f" 2>&1)"
  # config gpu VALUE: stdout the value as stored (a slot written short whole, a kind in any case);
  # a driver's name as its kind, junk refused: gpu.rs gpus_as_the_setting_takes_them.
  local h2=$TMP/gpu-home2; mkdir -p "$h2"
  check_eq "config gpu: a slot written short is stored whole" "gpu=0000:03:00.0" "$(HOME=$h2 ob config gpu 03:00.0 2>/dev/null)"
  check_eq "...a kind in any case" "gpu=nvidia" "$(HOME=$h2 ob config gpu NVIDIA 2>/dev/null)"
  check_eq "config gpu amdgpu: stored as amd" "gpu=amd" "$(HOME=$f/home ob config gpu amdgpu 2>/dev/null; rm -f "$cf")"
  check_match "config gpu junk: refused, saying what it takes" "bad gpu: geforce \(auto .*PCI slot" "$(HOME=$f/home ob config gpu geforce 2>&1)"
  check "...and nothing written" test ! -e "$cf"
  HOME=$f/home ob config gpu amd >/dev/null
  check_eq "config gpu amd: set" "amd" "$(HOME=$f/home ob config gpu)"
  check_eq "...in config --json" "amd" "$(HOME=$f/home ob config --json | jq -r .gpu)"
  # The list (config gpu, on stderr): every node, its driver and slot, what names it, * where boxes go.
  : > "$dri/renderD129"
  local list; list=$(gv gpu_list nvidia "$f")
  check_match "config gpu lists the GPUs" "^GPUs \(\* = where a headless box renders now" "$list"
  check_match "...the AMD one, with what names it" $'\n  renderD128 +amdgpu +0000:0a:00.0 +gpu amd or gpu 0000:0a:00.0' "$list"
  check_match "...the NVIDIA one marked: gpu nvidia is set" $'\n\\* renderD129 +nvidia +0000:01:00.0 +gpu nvidia or gpu 0000:01:00.0' "$list"
  # (OMABOX_RENDER_NODE cleared: a run that names a node, as an install's must here, gets its note first)
  check_match "...on stderr, through the CLI" "^GPUs \(\* = where a headless box renders now" "$(HOME=$f/home OMABOX_RENDER_NODE='' ob config gpu 2>&1 >/dev/null)"
  check_match "...after OMABOX_RENDER_NODE's note when it is set" $'^OMABOX_RENDER_NODE=/dev/dri/renderD128 overrides the setting here\nGPUs \\(\\* = ' \
    "$(HOME=$f/home OMABOX_RENDER_NODE=/dev/dri/renderD128 ob config gpu 2>&1 >/dev/null)"
  check_eq "...stdout stays the value" nvidia "$(HOME=$f/home ob config gpu 2>/dev/null)"
  check "config gpu intel with no Intel GPU: noted (the test)" bash -c '! "$0" _rust probe gpu_usable intel "$1"' "$PROBE" "$f"
  check "...none for one that is there" probe gpu_usable amd "$f"
  # (and its words through the CLI, where this machine has no usable Intel GPU)
  if ! probe gpu_usable intel; then
    check_match "config gpu intel with no Intel GPU here: a note" "note: no usable GPU here is intel now" "$(HOME=$h2 ob config gpu intel 2>&1 >/dev/null)"
  else
    skip "config gpu intel's note, through the CLI" "this machine has a usable Intel GPU"
  fi
  local rk; rk=$(probe render_driver "$(probe render_node 2>/dev/null)" 2>/dev/null) || rk=""
  case $rk in nvidia|nouveau) rk=nvidia ;; amdgpu|radeon) rk=amd ;; i915|xe) rk=intel ;; *) rk="" ;; esac
  if [ -n "$rk" ]; then
    check_eq "...none for one that is there ($rk), through the CLI" "" "$(HOME=$h2 ob config gpu "$rk" 2>&1 >/dev/null)"
  else
    skip "config gpu: no note for a GPU that is there, through the CLI" "no usable GPU of a known kind here"
  fi
  # #118: the GPUs on the bus for the widget's picker (config --json), a vfio-bound one (no render
  # node) too; lspci's name when there is one.
  mkdir -p "$pci/0000:02:00.0" "$pci/0000:00:1f.0" "$f/drivers/vfio-pci"
  echo 0x030000 > "$pci/0000:02:00.0/class"; echo 0x060100 > "$pci/0000:00:1f.0/class"
  ln -sfn "$f/drivers/vfio-pci" "$pci/0000:02:00.0/driver"; echo 0x8086 > "$pci/0000:02:00.0/vendor"
  printf '#!/bin/sh\ncase "$3" in\n  0000:01:00.0) echo "01:00.0 \\"3D controller\\" \\"NVIDIA Corporation\\" \\"GB203 [GeForce RTX 5070 Ti]\\" -ra1" ;;\n  0000:02:00.0) echo "02:00.0 \\"VGA compatible controller\\" \\"Vendor\\" \\"Plain Model\\"" ;;\nesac\n' > "$f/bin/lspci"
  chmod +x "$f/bin/lspci"
  local gj; gj=$(PATH=$f/bin:$PATH gv gpu_json 0000:02:00.0 "$f")
  check_eq "config --json lists the display GPUs on the bus, not other devices (#118)" "0000:01:00.0 0000:02:00.0 0000:0a:00.0" "$(jq -r '[.gpus[].pci] | join(" ")' <<<"$gj")"
  check_eq "...with lspci's bracketed name, or the whole model" "GeForce RTX 5070 Ti|Plain Model|" "$(jq -r '[.gpus[].name] | join("|")' <<<"$gj")"
  check_eq "...one bound to vfio-pci: no node, unavailable, why" 'null false "bound to vfio-pci"' \
    "$(jq -r '.gpus[] | select(.pci == "0000:02:00.0") | "\(.node) \(.available) \(.why | tojson)"' <<<"$gj")"
  check_eq "...each one's kind: by its driver, or its vendor when bound to vfio-pci (finding 237)" "nvidia intel amd" "$(jq -r '[.gpus[].kind] | join(" ")' <<<"$gj")"
  check_eq "...a usable one: its node" "/dev/dri/renderD129 true" "$(jq -r '.gpus[] | select(.pci == "0000:01:00.0") | "\(.node) \(.available)"' <<<"$gj")"
  check_eq "...gpu_auto, and gpu_now (the vfio one asked for: the fallback)" "0000:0a:00.0 0000:0a:00.0" "$(jq -r '"\(.gpu_auto) \(.gpu_now)"' <<<"$gj")"
  check_eq "...and through the CLI, the same keys" "gpu_auto gpu_now gpus" "$(HOME=$h2 ob config --json | jq -r '[keys[] | select(startswith("gpu_") or . == "gpus")] | join(" ")')"
  fb() { if gv render_fallback "$1" "/dev/dri/$2" "$f" >/dev/null; then echo yes; else echo no; fi; }
  check_eq "render_fallback: auto never, the GPU asked for no, another yes" "no no yes" "$(fb auto renderD128) $(fb nvidia renderD129) $(fb 0000:02:00.0 renderD128)"
  gpu_release_cases
  # gpu_rows (finding 298): no figures at all is a line saying so, exit 0 (it was 1, under pipefail).
  : > "$TMP/$P-gpu-none"; printf 'proc a 1.0\nproc b 5.5\nengine b sm 5.5\n' > "$TMP/$P-gpu-two"
  check_eq "gpu_rows: none, said, exit 0" "  (no GPU time) 0" "$(probe gpu_rows "$TMP/$P-gpu-none" | tr -d '\n'; echo " ${PIPESTATUS[0]}")"
  check_eq "...rows most first, engines left out" "b 5.5%|a 1.0%" "$(probe gpu_rows "$TMP/$P-gpu-two" | awk '{ print $1, $2 }' | paste -sd '|')"
  # pmon_figures (finding 295): NVIDIA's own per-process sampling, the box's processes only.
  local pc=$TMP/$P-pmon-pids; printf '100 Hyprland\n101 quickshell\n102 heavy\n' > "$pc"
  local pm='# gpu         pid   type     sm    mem    enc    dec    jpg    ofa    command
# Idx           #    C/G      %      %      %      %      %      %    name
    0       100     G     50      9      -      -      -      -    Hyprland
    0       102     G     90      1      -      -      -      -    heavy
    0       100     G      2     40      -      -      -      -    Hyprland
    0       101     G      -      -      -      -      -      -    quickshell
    0       102     G     98      1     10      -      -      -    heavy
    0       555     G     70      3      -      -      -      -    Hyprland
    0       100     G      4      1      -      -      -      -    Hyprland
    0       101     G      -      -      -      -      -      -    quickshell
    0       555     G     60      3      -      -      -      -    Hyprland
    1       102     G      -      -      -      -      -      -    heavy'
  local pf; pf=$(probe pmon_figures "$pc" <<<"$pm" | LC_ALL=C sort)
  check_eq "pmon_figures: the window's samples averaged, the second before left out, mem not counted" \
    "engine Hyprland sm 3.0|engine heavy enc 5.0|engine heavy sm 49.0|proc Hyprland 3.0|proc heavy 54.0|proc quickshell 0.0" "$(paste -sd '|' <<<"$pf")"
  check_eq "...a process not in the box (555, the host's Hyprland) is not counted" "" "$(grep -E '(proc|engine) Hyprland (sm )?(6|3[5-9]|4)' <<<"$pf")"
  check_eq "...no samples (only the header): nothing" "" "$(probe pmon_figures "$pc" <<<"$(head -2 <<<"$pm")")"
}

# omabox cpu (#205, finding 277): /proc read on a fake tree (cpu_sample), the arithmetic on injected
# samples (cpu_report), the table, and the refusals before any box is read.
t_unit_cpu() {
  local f=$TMP/cpu out
  mkdir -p "$f/10" "$f/11"
  # A name with blanks and parens (the box sets its own: prctl), NSpid's last its pid in the box.
  printf '10 (my (odd) app) S 1 10 10 0 -1 4194304 100 0 0 0 250 50 0 0 20 0 3 0 5000 1000000 300 18446744073709551615\n' > "$f/10/stat"
  printf 'Name:\tx\nVmRSS:\t  2048 kB\nNSpid:\t10\t7\n' > "$f/10/status"
  printf 'Rss:   2048 kB\nPss:   1024 kB\n' > "$f/10/smaps_rollup"
  printf '11 (sleep) S 1 10 10 0 -1 4194304 100 0 0 0 1 2 0 0 20 0 3 0 6000 1000000 300 18446744073709551615\n' > "$f/11/stat"
  check_eq "cpu_sample: pid, start, utime+stime, RSS, PSS, pid in the box, the name as one field" \
    $'10 5000 300 2048 1024 7 my_?odd?_app\n11 6000 3 0 - 11 sleep' "$(probe cpu_sample "$f" 10 11 12)"
  # Two samples 2 s apart at 100 ticks/s: pid 10 (box 7) used 100 ticks (50%), 11 exited, 12 started
  # with 50 ticks (25%); a pid reused by another process (start time) is another process.
  printf 'S 1000000000\n10 5000 300 2048 1024 7 a\n11 6000 3 0 - 11 b\n13 100 70 10 - 13 d\nS 3000000000\n10 5000 400 4096 1024 7 a\n12 7000 50 100 - 12 c\n13 900 10 10 - 13 d\n' > "$f/s"
  out=$(probe cpu_report 100 < "$f/s")
  check_eq "cpu_report: % of one core over the window, busiest first, a total" \
    $'p 10 7 a 50.0 4096 1024 0 0\np 12 12 c 25.0 100 - 1 0\np 13 13 d 5.0 10 - 1 0\np 11 11 b 0.0 0 - 0 1\np 13 13 d 0.0 10 - 0 1\ntotal 80.0 4216 1024' "$out"
  check_eq "...--pid: the box's number" $'p 10 7 a 50.0 4096 1024 0 0\ntotal 50.0 4096 1024' "$(probe cpu_report 100 7 < "$f/s")"
  check_eq "...or the host's" "p 10 7 a 50.0 4096 1024 0 0" "$(probe cpu_report 100 10 < "$f/s" | head -1)"
  check_eq "...a pid not there at the start: none" "total 0.0 0 -" "$(probe cpu_report 100 12 < "$f/s")"
  check_eq "...--app: by name" $'p 12 12 c 25.0 100 - 1 0\ntotal 25.0 100 -' "$(probe cpu_report 100 "" c < "$f/s")"
  check_eq "cpu_tame: as cpu_sample names" "my_?odd?_app" "$(probe cpu_tame 'my (odd) app')"
  out=$(probe cpu_report 100 < "$f/s" | probe cpu_table)
  check_match "cpu_table: a header, then the rows" $'^  PROCESS +PID +CPU +RSS +PSS\n  a +7 +50.0% +4.0M +1.0M\n' "$out"
  check_match "...one that started, and one that exited, said" $'\n  c +12 +25.0% +0.1M +-  \\(started in the window\\)\n.*\n  b +11 +0.0% +0.0M +-  \\(exited in the window\\)' "$out"
  check_match "...the total last" $'\n  total +80.0% +4.1M +1.0M$' "$out"
  # --threads (#242): each thread's own stat under task/, its tid in the box from its status.
  mkdir -p "$f/10/task/10" "$f/10/task/14"
  printf '10 (my (odd) app) S 1 10 10 0 -1 4194304 100 0 0 0 20 10 0 0 20 0 3 0 5000 1000000 300 18446744073709551615\n' > "$f/10/task/10/stat"
  printf 'Name:\tx\nNSpid:\t10\t7\n' > "$f/10/task/10/status"
  printf '14 (QSG Render) S 1 10 10 0 -1 4194304 100 0 0 0 200 20 0 0 20 0 3 0 5100 1000000 300 18446744073709551615\n' > "$f/10/task/14/stat"
  printf 'NSpid:\t14\t9\n' > "$f/10/task/14/status"
  check_eq "cpu_threads: the process's key, tid, start, utime+stime, tid in the box, the name as one field" \
    $'t 10 5000 10 5000 30 7 my_?odd?_app\nt 10 5000 14 5100 220 9 QSG_Render' "$(probe cpu_threads "$f" 10 12)"
  # Process 10's threads over the same 2 s: tid 14 60 ticks (30%), 16 started (10%), 15 exited, two
  # named R kept apart; they follow their process, busiest first, before the next process.
  printf '%s\n' 'S 1000000000' '10 5000 300 2048 1024 7 a' 't 10 5000 10 5000 100 7 a' 't 10 5000 14 5100 100 9 R' \
    't 10 5000 15 5200 50 10 R' '11 6000 3 0 - 11 b' 'S 3000000000' '10 5000 400 2048 1024 7 a' 't 10 5000 10 5000 110 7 a' \
    't 10 5000 14 5100 160 9 R' 't 10 5000 16 5300 20 11 R' '11 6000 4 0 - 11 b' > "$f/t"
  check_eq "cpu_report --threads: each thread under its process, busiest first, one that started or exited said" \
    $'p 10 7 a 50.0 2048 1024 0 0\nt 14 9 R 30.0 0 0\nt 16 11 R 10.0 1 0\nt 10 7 a 5.0 0 0\nt 15 10 R 0.0 0 1\np 11 11 b 0.5 0 - 0 0\ntotal 50.5 2048 1024' \
    "$(probe cpu_report 100 < "$f/t")"
  check_eq "...--pid: that process and its threads" 5 "$(probe cpu_report 100 7 < "$f/t" | grep -c '^[pt] ')"
  out=$(probe cpu_report 100 < "$f/t" | probe cpu_table)
  check_match "cpu_table: threads indented under their process, by the box's tid, no memory" \
    $'\n  a +7 +50.0% +2.0M +1.0M\n    R +9 +30.0%\n    R +11 +10.0%  \\(started in the window\\)\n    a +7 +5.0%\n    R +10 +0.0%  \\(exited in the window\\)\n  b +11 ' "$out"
  check_match "cpu --threads alone: refused, with what to name" "--threads is for one app's threads: name it with --pid PID or --app NAME" \
    "$(ob cpu -b "$P-x" --threads 2>&1)"
  check_match "cpu: a duration above 0" "cpu: how long to measure, like 5s or 500ms \(a bare number is seconds\), got 0" "$(ob cpu -b "$P-x" 0 2>&1)"
  check_match "...500ms and --settle 1.5s read (#273), so the box is asked" "no box .$P-x. is up" "$(ob cpu -b "$P-x" 500ms --settle 1.5s 2>&1)"
  check_match "gpu: 2x refused" "gpu: how long to measure, like 5s or 500ms.*got 2x" "$(ob gpu -b "$P-x" 2x 2>&1)"
  check_match "...1.5s read (#273)" "no box .$P-x. is up" "$(ob gpu -b "$P-x" 1.5s 2>&1)"
  check_match "cpu: --pid or --app" "--pid or --app, not both" "$(ob cpu -b "$P-x" --pid 1 --app x 2>&1)"
  check_match "cpu: --pid junk refused" "--pid takes a pid" "$(ob cpu -b "$P-x" --pid x 2>&1)"
  check_match "cpu: --settle junk refused" "--settle takes a duration, like 2s or 500ms" "$(ob cpu -b "$P-x" --settle 1x 2>&1)"
  check_match "...--settle 0 is none" "no box .$P-x. is up" "$(ob cpu -b "$P-x" --settle 0 2>&1)"
  # (cpu is a jailed agent's, as gpu: broker_side.rs's broker_check_allows_and_refuses)
  check_match "cpu takes -b first (a box command)" "no box .nope-$P. is up" "$(ob -b "nope-$P" cpu 2>&1)"
}

# Travel (#38, finding 111) and --mod (#25, finding 112): the pure parts and what is refused before
# any box is asked.
t_unit_pointer() {
  # #245: hardware cursors never through a CPU-mapped buffer (NVIDIA's GBM cannot map one), in
  # omabox's own hl.config, after the user modules.
  check "share/hyprland.lua sets cursor use_cpu_buffer = 0" grep -q '^  cursor = { use_cpu_buffer = 0 },$' "$ROOT/share/hyprland.lua"
  # omabox scroll (#134, finding 213)
  check_match "scroll: X Y DY needed" "need X Y DY" "$(ob scroll -b "$P-x" 1 2 2>&1)"
  check_match "scroll: not both 0" "not both 0" "$(ob scroll -b "$P-x" 1 2 0 0 2>&1)"
  check_match "scroll: a bad source" "--source is wheel" "$(ob scroll -b "$P-x" 1 2 3 --source mouse 2>&1)"
  check_match "scroll: --in or --window" "not both" "$(ob scroll -b "$P-x" --in a -w b 1 2 3 2>&1)"
  check_match "scroll: --quiet goes with --wait" "go with --wait" "$(ob scroll -b "$P-x" --quiet 1s 1 2 3 2>&1)"
  # (scroll is a jailed agent's: broker_side.rs's broker_check_allows_and_refuses)
  # (pointer marks: peek's words only; wheel_note's notches; steps_to; path_rects; --mod's names, each
  # once, added to earlier ones: input.rs pointer_cases_as_bash and options_as_bash_reads_them)
  # #167: scroll --mod as click's; a wheel's rounding to whole notches said.
  check_match "scroll --mod junk refused" "not a modifier" "$(ob scroll -b "$P-x" --mod meta 1 2 3 2>&1)"
  check_match "--mod: not a modifier, refused" "'hyper' is not a modifier" "$(probe mods_add "" ctrl+hyper 2>&1)"
  check_match "click --steps 0 refused" "--steps is 1-999" "$(ob click -b "$P-x" --steps 0 1 1 2>&1)"
  check_match "pointer --steps 1000 refused" "--steps is 1-999" "$(ob pointer -b "$P-x" --steps 1000 -- move 1 1 2>&1)"
  check_match "click --mod junk refused" "not a modifier" "$(ob click -b "$P-x" --mod meta 1 1 2>&1)"
  check_match "drag --mod junk refused" "not a modifier" "$(ob drag -b "$P-x" --mod ctrl,x 1 1 2 2 2>&1)"
  check_match "drag --hold 500 refused, saying the unit (#103)" "like 300ms or 2s \\(a bare number is seconds\\), got 500" "$(ob drag -b "$P-x" --hold 500 1 1 2 2 2>&1)"
  check_match "keys -m is omabox's own" "click, drag or pointer --mod" "$(ob keys -b "$P-x" -m ctrl a 2>&1)"
  # #216: the thumb buttons by either name; anything else still refused.
  local b; for b in back forward side extra; do
    check_match "click X Y $b taken (to the box lookup)" "no box '$P-x'" "$(ob click -b "$P-x" 1 1 "$b" 2>&1)"
  done
  check_match "...drag X1 Y1 X2 Y2 back too" "no box '$P-x'" "$(ob drag -b "$P-x" 1 1 2 2 back 2>&1)"
  check_match "...click thumb refused" "click: unexpected thumb \(X Y in whole pixels, then a button: left, right" "$(ob click -b "$P-x" 1 1 thumb 2>&1)"
  # The input tools refuse outside a box before they connect (SECURITY.md): run from a host shell they
  # would drive the real desktop. Checked in a sandbox with no /opt/omabox, no runtime dir, no display.
  local t out rc
  local arg
  for t in keyboard pointer still events tree; do
    arg=(); [ "$t" != events ] || arg=(/dev/null)   # (events wants its file first, or it says its usage)
    rc=0; out=$(bwrap --ro-bind / / --dev /dev --proc /proc --unshare-pid --unshare-net --tmpfs /opt --tmpfs /run \
      --die-with-parent env -i "$ROOT/tools/$t/omabox-$t" "${arg[@]}" 2>&1) || rc=$?
    check_eq "omabox-$t refuses outside a box" 2 "$rc"
    check_match "...and says so" "only runs inside an omabox box" "$out"
  done
  # (#108, finding 177) Not a directory test: a plain /opt/omabox/share (an install, a stray mkdir) is
  # no box, nor is a mount there where the system bus is (a stand-in file for its socket, never the bus).
  : > "$TMP/fakebus"
  for t in keyboard pointer; do
    rc=0; out=$(bwrap --ro-bind / / --dev /dev --proc /proc --unshare-pid --unshare-net --tmpfs /opt --dir /opt/omabox/share \
      --tmpfs /run --die-with-parent env -i "$ROOT/tools/$t/omabox-$t" 2>&1) || rc=$?
    check_eq "omabox-$t refuses where /opt/omabox/share is a plain dir" "2 yes" "$rc $(grep -q 'only runs inside' <<<"$out" && echo yes)"
    rc=0; out=$(bwrap --ro-bind / / --dev /dev --proc /proc --unshare-pid --unshare-net --tmpfs /opt --ro-bind "$ROOT/share" /opt/omabox/share \
      --tmpfs /run --dir /run/dbus --ro-bind "$TMP/fakebus" /run/dbus/system_bus_socket --die-with-parent env -i "$ROOT/tools/$t/omabox-$t" 2>&1) || rc=$?
    check_eq "...and where the system bus is, a mount there or not" "2 yes" "$rc $(grep -q 'only runs inside' <<<"$out" && echo yes)"
  done
  # pointer hide|show (#228, finding 305): alone, refused before any box is looked at.
  check_match "pointer hide with a move refused" "pointer hide: nothing else with it" "$(ob pointer -b "$P-x" hide move 1 1 2>&1)"
  check_match "...with --steps" "pointer show: nothing else with it" "$(ob pointer -b "$P-x" --steps 3 show 2>&1)"
  check_match "...with --mod" "pointer hide: nothing else with it" "$(ob pointer -b "$P-x" --mod ctrl hide 2>&1)"
}

# The pointer out of shots and recordings (#228, finding 305), at scale 2: `shot --no-pointer` and
# `record --no-pointer` (shown again after, also on Ctrl-C), `pointer hide` over a config reload and a
# theme switch, focus still following it; on a GPU other than NVIDIA's and on NVIDIA's.
t_no_pointer() {
  local n; n=$(gpu_node other)
  [ -n "$n" ] || { skip "the pointer hidden" "no render node here but NVIDIA's (t_no_pointer_nvidia runs there)"; return; }
  no_pointer_on "$n" "$P-np"
}
t_no_pointer_nvidia() {
  local n; n=$(nvidia_ready) || { skip "the pointer hidden on NVIDIA" "$n"; return; }
  no_pointer_on "$n" "$P-npnv"
}
# Hardware cursors on NVIDIA (#245, finding 340): Omarchy's screenshot (Print) forces them on, and
# Hyprland's CPU cursor path wrote through NVIDIA's NULL GBM mapping: the box died at the next cursor
# update. use_cpu_buffer = 0 draws them on the GPU; the box lives through both.
t_cursor_hw_nvidia() {
  local n; n=$(nvidia_ready) || { skip "hardware cursors on NVIDIA" "$n"; return; }
  local B=$P-curnv out sel=selection
  # Print's region selection: 4.5's Omasnap (#311), 4.0's slurp.
  omarchy45 && sel=omasnap   # omarchy<4.5: slurp's layer, selection
  out=$(env OMABOX_RENDER_NODE="$n" "$CLI" up "$B" --size 1280x720 --net isolated "${OM[@]}" 2>&1) || { no "up for hardware cursors on NVIDIA" "failed: $out"; return; }
  check_eq "cursor:use_cpu_buffer is 0" 0 "$(ob hyprctl -b "$B" -j getoption cursor:use_cpu_buffer | jq .int)"
  ob lua -b "$B" 'hl.config({cursor = {no_hardware_cursors = 0}})' >/dev/null 2>&1
  ob pointer -b "$B" move 300 200 >/dev/null 2>&1
  ob pointer -b "$B" move 600 400 >/dev/null 2>&1
  check "...hardware cursors forced on, two pointer moves: the box still answers" ob hyprctl -b "$B" monitors
  ob lua -b "$B" 'hl.config({cursor = {no_hardware_cursors = 2}})' >/dev/null 2>&1
  ob keys -b "$B" Print >/dev/null 2>&1
  check "Print: Omarchy's region selection (layer $sel)" ob wait -b "$B" --timeout 10s layer "$sel"
  ob keys -b "$B" Escape >/dev/null 2>&1
  check "...Escape: gone" ob wait -b "$B" --timeout 10s layer "$sel" --gone
  ob pointer -b "$B" move 320 240 >/dev/null 2>&1
  check "...and the box still answers (it died here)" ob hyprctl -b "$B" monitors
}
# The layout's 40x40 around 640,360 (80x80 image pixels at scale 2): np_crop BOX FILE [--no-pointer].
np_crop() { ob shot -b "$1" -g "620,340 40x40" -o "$2" ${3:+"$3"} >/dev/null 2>&1; }
# The share of two images' pixels that differ: np_diff A B [FUZZ%]; np_more A B SHARE [FUZZ] and np_less.
np_diff() { magick "$1" "$2" -alpha off -fuzz "${3:-0}%" -metric AE -compare -format '%[distortion]' info: 2>&1; }
np_more() { awk -v d="$(np_diff "$1" "$2" "${4:-0}")" -v s="$3" 'BEGIN { exit !(d + 0 > s) }'; }
np_less() { awk -v d="$(np_diff "$1" "$2" "${4:-0}")" -v s="$3" 'BEGIN { exit !(d ~ /^[0-9.e+-]+$/ && d + 0 < s) }'; }
np_live() { ob lua -b "$1" "return hl.get_config('cursor.invisible')" 2>&1; }
np_gone() { [ ! -e "$1/pointer" ] && [ ! -e "$1/run/omabox.pointer" ]; }
no_pointer_on() {
  local n=$1 B=$2 out D f=$TMP/$2
  out=$(env OMABOX_RENDER_NODE="$n" "$CLI" up "$B" --size 2560x1440,scale=2 --net isolated 2>&1) || { no "up for the pointer hidden" "failed: $out"; return; }
  D=$(ob path -b "$B")
  ob pointer -b "$B" move 640 360 >/dev/null 2>&1
  ob wait -b "$B" still --timeout 10s >/dev/null 2>&1 || true
  np_crop "$B" "$f-p1.png"; np_crop "$B" "$f-n1.png" --no-pointer
  check "a shot has the pointer, shot --no-pointer not: they differ there" np_more "$f-p1.png" "$f-n1.png" 0.02
  check_eq "...shown again after it (cursor:invisible)" false "$(np_live "$B")"
  check "...nothing left that keeps it hidden" np_gone "$D"
  np_crop "$B" "$f-p2.png"
  check "...and drawn again: the next shot has it" np_more "$f-p2.png" "$f-n1.png" 0.02
  # pointer hide: none in any shot until pointer show, over a reload and a theme switch.
  out=$(ob pointer -b "$B" hide 2>&1)
  check_match "pointer hide says until when" "hidden in box '$B' .* until omabox pointer show" "$out"
  np_crop "$B" "$f-h1.png"
  check_eq "...shots without it" 0 "$(np_diff "$f-h1.png" "$f-n1.png")"
  ob hyprctl -b "$B" reload >/dev/null 2>&1; sleep 1
  check_eq "...a config reload keeps it hidden" true "$(np_live "$B")"
  np_crop "$B" "$f-h2.png"
  check_eq "...and drawn nowhere after it" 0 "$(np_diff "$f-h2.png" "$f-n1.png")"
  local cur t mark
  cur=$(ob run -b "$B" -- omarchy-theme-current 2>/dev/null) || cur=""
  t=$(ob run -b "$B" -- omarchy-theme-list 2>/dev/null | grep -vxF -- "$cur" | head -n 1) || t=""
  if [ -n "$t" ]; then
    mark=$(ob events -b "$B" --mark 2>/dev/null) || mark=0
    ob run -b "$B" -- omarchy-theme-set "$t" >/dev/null 2>&1
    check_match "omarchy-theme-set $t reloads the box's config" configreloaded "$(ob events -b "$B" --since "$mark" --grep configreloaded 2>&1)"
    check_eq "...the pointer still hidden" true "$(np_live "$B")"
    ob wait -b "$B" still --timeout 10s >/dev/null 2>&1 || true
    np_crop "$B" "$f-t1.png"
    ob pointer -b "$B" show >/dev/null 2>&1
    np_crop "$B" "$f-t2.png"
    check "...pointer show draws it there" np_more "$f-t2.png" "$f-t1.png" 0.02
    ob pointer -b "$B" hide >/dev/null 2>&1
    np_crop "$B" "$f-t3.png"
    check_eq "...hidden again, the same pixels as before it showed" 0 "$(np_diff "$f-t3.png" "$f-t1.png")"
  else no "a theme to switch to" "omarchy-theme-list gave none but ${cur:-?}"; fi
  check_match "up --no-pointer of the box with it hidden: the box as it is" "is already up$" "$(ob up "$B" --no-pointer 2>&1)"
  # Hidden, it still moves, and focus follows it: two terminals side by side.
  ob run -b "$B" -d --wait -- foot --app-id np-left >/dev/null 2>&1
  ob run -b "$B" -d --wait -- foot --app-id np-right >/dev/null 2>&1
  ob pointer -b "$B" move 200 360 >/dev/null 2>&1
  check "a hidden pointer moved over the left terminal focuses it" until_ok 5 bash -c "'$CLI' hyprctl -b '$B' -j activewindow | jq -e '.class == \"np-left\"'"
  ob pointer -b "$B" move 1100 360 >/dev/null 2>&1
  check "...and over the right one, that" until_ok 5 bash -c "'$CLI' hyprctl -b '$B' -j activewindow | jq -e '.class == \"np-right\"'"
  check_eq "...where it was told" "1100, 360" "$(ob hyprctl -b "$B" cursorpos)"
  # (KILL: foot takes a TERM and exits 230, which the next box command says as a run -d job's early
  # end; whichever command that is depends on when foot is done, and the binary's `run` and `pointer
  # show` came before it, so np_live's 2>&1 got it. A KILL from `run` is not said: 137, finding 406.)
  ob run -b "$B" -- pkill -KILL -x foot >/dev/null 2>&1 || true
  ob pointer -b "$B" show >/dev/null 2>&1
  check_eq "pointer show: cursor:invisible false" false "$(np_live "$B")"
  check "...nothing left that keeps it hidden" np_gone "$D"
  check_match "up --no-pointer of the box with it shown: refused" "without what you asked for: --no-pointer \(its pointer shows: omabox pointer hide\)" \
    "$(ob up "$B" --no-pointer 2>&1)"
  # Stopped (TERM; a background job here ignores INT): shown again as the shot ends.
  local bp rc
  "$CLI" shot -b "$B" --no-pointer --burst 60 --every 200ms -o "$f-burst" >/dev/null 2>&1 & bp=$!
  check "shot --no-pointer --burst: hidden while it runs" until_ok 10 test -e "$D/pointer"
  kill -TERM "$bp"; wait "$bp"; rc=$?
  check_eq "...a TERM ends it (143), shown again" "143 false" "$rc $(np_live "$B")"
  check "...nothing left that keeps it hidden" np_gone "$D"
  # record --no-pointer: no pointer in its frames; a plain recording's have it.
  if command -v wf-recorder >/dev/null && command -v ffmpeg >/dev/null; then
    ob pointer -b "$B" move 640 360 >/dev/null 2>&1
    ob wait -b "$B" still --timeout 10s >/dev/null 2>&1 || true
    np_crop "$B" "$f-n2.png" --no-pointer
    local v np
    for v in np plain; do
      np=(); [ "$v" = plain ] || np=(--no-pointer)
      ob record -b "$B" -o "$f-$v.mp4" --hold 300ms ${np[@]+"${np[@]}"} -- pointer move 640 360 >/dev/null 2>&1
      ffmpeg -v error -y -sseof -0.1 -i "$f-$v.mp4" -frames:v 1 -vf crop=80:80:1240:680 "$f-$v.png" 2>/dev/null
    done
    check "record --no-pointer: its last frame has no pointer (as a --no-pointer shot)" np_less "$f-np.png" "$f-n2.png" 0.005 10
    check "...a plain recording's has it" np_more "$f-plain.png" "$f-n2.png" 0.01 10
    check_eq "...shown again after it" false "$(np_live "$B")"
    check "record start --no-pointer" ob record -b "$B" start --no-pointer -o "$f-rs.mp4"
    ob hyprctl -b "$B" reload >/dev/null 2>&1; sleep 0.5
    check_eq "...hidden past start, over a reload" true "$(np_live "$B")"
    ob record -b "$B" stop >/dev/null 2>&1
    check_eq "...record stop shows it again" false "$(np_live "$B")"
    check "...nothing left that keeps it hidden" np_gone "$D"
    # A `record --no-pointer -- ACTION` ended by a signal while the action runs (finding 320): the
    # recording is kept, and so is the hold, until `record stop`.
    ob record -b "$B" --no-pointer -o "$f-int.mp4" -- run -- sleep 20 >/dev/null 2>&1 & bp=$!
    for _ in $(seq 50); do [ -f "$D/record" ] && break; sleep 0.1; done
    sleep 0.3; kill -TERM "$bp"; wait "$bp" 2>/dev/null || true
    check_match "record --no-pointer -- ACTION ended by a TERM: still recording" "^recording .* to $f-int.mp4" "$(ob record -b "$B" status 2>&1)"
    check_eq "...the pointer still hidden" true "$(np_live "$B")"
    ob record -b "$B" stop >/dev/null 2>&1
    check_eq "...shown again by record stop" false "$(np_live "$B")"
  else
    skip "record --no-pointer" "no wf-recorder or ffmpeg here"
  fi
  ob down "$B" >/dev/null 2>&1
  # up --no-pointer: hidden from its first frame.
  out=$(env OMABOX_RENDER_NODE="$n" "$CLI" up "$B" --no-pointer --no-shell --net isolated 2>&1) || { no "up --no-pointer" "failed: $out"; return; }
  check_eq "up --no-pointer: hidden from the start" true "$(np_live "$B")"
  ob down "$B" >/dev/null 2>&1
}

# Travel and modifier clicks in a box (findings 111, 112): two floating terminals side by side on an
# empty desktop, the pointer resting on the left one (L). A jump past the right one (R) leaves focus
# on L; travel in steps passes over R, and focus follows the mouse (Omarchy's input:follow_mouse = 1)
# on the way. R reports what its pointer does (foot's SGR mouse mode 1003: ESC[<CODE;X;YM for a
# motion, CODE 32 and up, or a press, below that, with ctrl 16 and alt 8 added; a release ends in m;
# shift is foot's own, never reported).
t_pointer() {
  local B=$P-ptr
  up_ok "$B" --no-shell --net isolated || { no "up" "$UP_OUT"; return; }
  term() { ob run -b "$B" -d -- foot -T "$1" sh -c "$2" >/dev/null; until_ok 10 bash -c "'$CLI' hyprctl -b '$B' -j clients | jq -e '.[] | select(.title == \"$1\")'" >/dev/null; }
  addr() { ob hyprctl -b "$B" -j clients | jq -r --arg t "$1" '.[] | select(.title == $t) | .address'; }
  place() {   # place TITLE X Y: floating, 500x400 at X,Y
    local a; a=$(addr "$1")
    ob hyprctl -b "$B" dispatch "hl.dsp.window.float({ action = 'enable', window = 'address:$a' })" >/dev/null
    ob hyprctl -b "$B" dispatch "hl.dsp.window.resize({ x = 500, y = 400, window = 'address:$a' })" >/dev/null
    ob hyprctl -b "$B" dispatch "hl.dsp.window.move({ x = $2, y = $3, window = 'address:$a' })" >/dev/null
    until_ok 5 bash -c "'$CLI' hyprctl -b '$B' -j clients | jq -e '.[] | select(.address == \"$a\") | .at == [$2, $3] and .size == [500, 400]'" >/dev/null
  }
  active() { ob hyprctl -b "$B" -j activewindow | jq -r '.title // ""'; }
  pos() { ob hyprctl -b "$B" cursorpos; }
  reports() { ob run -b "$B" -- cat /tmp/mouse | grep -ao '<[0-9;]*M' | sed 's/^<\([0-9]*\);.*/\1/'; }   # (M: not releases)
  motions() { reports | awk '$1 >= 32' | wc -l; }
  presses() { reports | awk '$1 < 32' | tr '\n' ' '; }
  term L 'sleep 600'
  term R 'printf "\033[?1003h\033[?1006h"; stty raw -echo; exec cat > /tmp/mouse'
  place L 100 300; place R 700 300
  ob wait -b "$B" still >/dev/null   # the moves are animated: input goes where the windows are drawn
  check_eq "follow_mouse is on (what travel is for)" 1 "$(ob hyprctl -b "$B" -j getoption input:follow_mouse | jq .int)"
  ob pointer -b "$B" -- move 350 500 >/dev/null
  check_eq "resting on L focuses it" L "$(active)"
  local m0; m0=$(motions)
  ob pointer -b "$B" -- move 1500 500 >/dev/null
  check_eq "a jump past R to the empty desktop: the focus stays on L" L "$(active)"
  check_eq "...and R saw no motion" "$m0" "$(motions)"
  ob pointer -b "$B" -- move 350 500 >/dev/null
  ob pointer -b "$B" --steps 20 -- move 1500 500 >/dev/null
  check_eq "pointer --steps: the way passes over R, which takes the focus" R "$(active)"
  check "...and R saw the pointer cross it (hover)" test "$(motions)" -gt "$m0"
  check_eq "...ending on the target" "1500, 500" "$(pos)"
  ob pointer -b "$B" -- move 350 500 move 350 900 move 1500 900 --steps 10 >/dev/null
  check_eq "a path around R (move A move B --steps N): the focus stays on L" L "$(active)"
  ob pointer -b "$B" -- move 350 500 move 1500 500 --steps 20 >/dev/null
  check_eq "one move's own --steps crosses R" R "$(active)"
  ob pointer -b "$B" -- move 350 500 >/dev/null
  ob click -b "$B" --steps 20 1500 500 >/dev/null
  check_eq "click --steps travels there too" R "$(active)"
  # Modifiers held across the click (#25).
  ob click -b "$B" --window R 50 50 >/dev/null
  ob click -b "$B" --window R 50 50 --mod ctrl >/dev/null
  ob click -b "$B" --window R 50 50 --mod alt --mod ctrl >/dev/null
  ob pointer -b "$B" --window R --mod ctrl -- move 60 60 click >/dev/null
  ob drag -b "$B" --window R 50 50 150 50 --mod ctrl >/dev/null
  ob click -b "$B" --window R 50 50 --mod super >/dev/null
  ob click -b "$B" --window R 50 50 >/dev/null
  check_eq "click, --mod ctrl, alt+ctrl, pointer and drag --mod ctrl, --mod super (Hyprland's move bind: not for the app), then none held" \
    "0 16 24 16 16 0 " "$(presses)"
  check_eq "...SUPER+click moved nothing (no motion)" "700 300" "$(ob hyprctl -b "$B" -j clients | jq -r '.[] | select(.title == "R") | "\(.at[0]) \(.at[1])"')"
  # drag --hold is a duration (#103): 300ms holds 300 ms, not 300 s (nor is a bare 2 two ms).
  local t0 took; t0=$(now_ms)
  ob drag -b "$B" --window R 50 50 150 50 --hold 300ms >/dev/null
  took=$(( $(now_ms) - t0 ))
  check_eq "drag --hold 300ms: held 300 ms, under 2 s in all" yes "$( ((took >= 300 && took < 2000)) && echo yes || echo "took $took ms")"
  # Never left down: a pause that times out lets go; the tool killed outright leaves them down until
  # the next keyboard event, which omabox then sends.
  local out
  out=$(ob run -b "$B" -- sh -c 'sleep 2 | /opt/omabox/bin/omabox-keyboard -m ctrl -p 300; echo "rc=$?"' 2>&1)
  check_match "a pause with nothing on stdin times out, letting go" "letting go.*rc=1" "$(tr '\n' ' ' <<<"$out")"
  check_eq "-p and -T together refused" 2 "$(ob run -b "$B" -- /opt/omabox/bin/omabox-keyboard -m ctrl -p 300 -T </dev/null >/dev/null 2>&1; echo $?)"
  check_eq "the pointer tool's --extent: WxH with junk after it refused (#109)" 2 \
    "$(ob run -b "$B" -- /opt/omabox/bin/omabox-pointer --extent 1920x1080abc sleep 1 >/dev/null 2>&1; echo $?)"
  check_eq "...a sign refused" 2 "$(ob run -b "$B" -- /opt/omabox/bin/omabox-pointer --extent -1920x1080 sleep 1 >/dev/null 2>&1; echo $?)"
  check_eq "...WxH taken" 0 "$(ob run -b "$B" -- /opt/omabox/bin/omabox-pointer --extent 1920x1080 sleep 1 >/dev/null 2>&1; echo $?)"
  ob click -b "$B" --window R 50 50 >/dev/null
  check_match "...after it, a click has no modifier" " 0 $" "$(presses)"
  tree() { local c; for c in $(pgrep -P "$1"); do echo "$c"; tree "$c"; done; }
  ob pointer -b "$B" --window R --mod ctrl -- move 50 50 sleep 3s click >/dev/null 2>"$TMP/ptr.err" & local cp=$! kp="" i
  for i in $(seq 50); do
    for kp in $(tree "$cp"); do [ "$(cat "/proc/$kp/comm" 2>/dev/null)" = omabox-keyboard ] && break; kp=""; done
    [ -z "$kp" ] || break; sleep 0.2
  done
  if [ -n "$kp" ]; then
    kill -KILL "$kp"
    wait "$cp"; check_eq "the keyboard killed mid-click: omabox exits 1" 1 $?
    check_match "...saying it let go early" "let go of ctrl before the end" "$(cat "$TMP/ptr.err")"
    check_match "...the click in that run still had ctrl (SIGKILL cannot be caught)" " 16 $" "$(presses)"
    ob click -b "$B" --window R 50 50 >/dev/null
    check_match "...and the next click has none: omabox cleared it" " 0 $" "$(presses)"
  else wait "$cp"; no "pointer --mod: its keyboard tool found (to kill it)"; fi
  # #111, finding 180: what no check sent before. R's codes since a count: presses (0 left, 1 middle,
  # 2 right) and the wheel (64 up, 65 down); motions are 32 and up below 64 (32 + a held button).
  local n0
  # shellcheck disable=SC2329 # called below
  pr() { reports | tail -n +$((n0 + 1)) | awk '$1 < 32 || $1 >= 64' | tr '\n' ' '; }
  # shellcheck disable=SC2329
  dragged() { reports | tail -n +$((n0 + 1)) | awk '$1 == 32' | wc -l; }   # motions, left held
  n0=$(reports | wc -l); ob click -b "$B" --window R 50 50 right >/dev/null
  check_eq "click right: button 2" "2 " "$(pr)"
  n0=$(reports | wc -l); ob click -b "$B" --window R 50 50 middle >/dev/null
  check_eq "click middle: button 1" "1 " "$(pr)"
  n0=$(reports | wc -l); ob click -b "$B" --window R 50 50 --double >/dev/null
  check_eq "click --double: two presses" "0 0 " "$(pr)"
  n0=$(reports | wc -l); ob pointer -b "$B" --window R -- move 60 60 scroll 3 >/dev/null
  check_match "pointer scroll 3: the wheel down" '^(65 )+$' "$(pr)"
  n0=$(reports | wc -l); ob pointer -b "$B" --window R -- move 60 60 scroll -3 >/dev/null
  check_match "...scroll -3: up" '^(64 )+$' "$(pr)"
  # #134, finding 213: sideways, and a wheel's notches (foot reports each notch as several lines: its
  # scroll multiplier; the notches are counted by Hyprland's binds below).
  n0=$(reports | wc -l); ob scroll -b "$B" --window R 60 60 0 30 --source wheel >/dev/null
  check_match "scroll 0 30 --source wheel: right" '^(67 )+$' "$(pr)"
  n0=$(reports | wc -l); ob scroll -b "$B" --window R 60 60 0 -15 --source wheel >/dev/null
  check_match "...0 -15: left" '^(66 )+$' "$(pr)"
  n0=$(reports | wc -l); ob scroll -b "$B" --window R 60 60 45 --source wheel >/dev/null
  check_match "...45: down" '^(65 )+$' "$(pr)"
  n0=$(reports | wc -l); ob pointer -b "$B" --window R -- move 60 60 hscroll 15 >/dev/null
  check_match "pointer hscroll 15: right" '^(67 )+$' "$(pr)"
  n0=$(reports | wc -l); ob scroll -b "$B" --window R 60 60 0 30 --source tilt >/dev/null 2>&1
  check_match "scroll 0 30 --source tilt: right, the app sees it (#167)" '^(67 )+$' "$(pr)"
  n0=$(reports | wc -l); ob scroll -b "$B" --window R 60 60 -60 --source finger >/dev/null
  check_match "scroll -60 --source finger: up" '^(64 )+$' "$(pr)"
  # Hyprland's wheel binds: mouse_left/right too (with no delay between scroll events: binds take
  # one in 300 ms by default, a real wheel's too).
  ob lua -b "$B" 'hl.config({ binds = { scroll_event_delay = 0 } })
    for _, k in ipairs({ "mouse_left", "mouse_right", "mouse_down" }) do
      hl.bind(k, function() local f = io.open("/tmp/" .. k, "a"); f:write("x\n"); f:close() end)
    end' >/dev/null
  ob scroll -b "$B" 960 540 0 30 --source wheel >/dev/null; ob scroll -b "$B" 960 540 0 -15 >/dev/null
  ob scroll -b "$B" 960 540 45 --source wheel >/dev/null
  # #214, finding 287: Hyprland binds a wheel's events only; a tilt and a finger scroll reach none (they
  # did when their source was lost on the way: a finger scroll's 10 frames were 10 binds).
  ob scroll -b "$B" 960 540 0 45 --source tilt >/dev/null 2>&1; ob scroll -b "$B" 960 540 60 --source finger >/dev/null
  check_eq "Hyprland binds: mouse_right twice (two notches), mouse_left once (one plain event), mouse_down 3; none for a tilt or a finger (#214)" "2 1 3" \
    "$(ob run -b "$B" -- wc -l /tmp/mouse_right /tmp/mouse_left /tmp/mouse_down | awk 'NR <= 3 { printf "%s%s", (NR > 1 ? " " : ""), $1 }')"
  # scroll --mod (#167, finding 236): Omarchy's SUPER+wheel binds, held as click holds them; the plain
  # mouse_down bind does not fire under SUPER.
  ob lua -b "$B" 'hl.bind("SUPER + mouse_down", function() local f = io.open("/tmp/super_down", "a"); f:write("x\n"); f:close() end)' >/dev/null
  ob scroll -b "$B" 960 540 30 --source wheel --mod super >/dev/null 2>&1
  check_eq "scroll --mod super: SUPER+mouse_down twice (two notches), mouse_down still 3" "2 3" \
    "$(ob run -b "$B" -- wc -l /tmp/super_down /tmp/mouse_down | awk 'NR <= 2 { printf "%s%s", (NR > 1 ? " " : ""), $1 }')"
  check_match "...and a wheel's DY not in whole notches is said" "a wheel turns in notches of 15: DY 20 is 1 notch \(15\)" \
    "$(ob scroll -b "$B" 960 540 20 --source wheel --mod super 2>&1 >/dev/null)"
  n0=$(reports | wc -l); ob pointer -b "$B" --window R -- move 60 60 down right move 90 90 up right >/dev/null
  check_eq "pointer down right ... up right: button 2" "2 " "$(pr)"
  n0=$(reports | wc -l); ob drag -b "$B" --window R 50 50 150 50 middle >/dev/null
  check_eq "drag middle: button 1" "1 " "$(pr)"
  # #216, finding 284: the thumb buttons (BTN_SIDE, BTN_EXTRA), foot's 8 and 9 (128, 129): back, forward.
  n0=$(reports | wc -l)
  local b; for b in back forward side extra; do ob click -b "$B" --window R 50 50 "$b" >/dev/null; done
  check_eq "click back, forward, side, extra: buttons 8, 9, 8, 9" "128 129 128 129 " "$(pr)"
  n0=$(reports | wc -l); ob pointer -b "$B" --window R -- move 60 60 down forward up forward >/dev/null
  check_eq "pointer down forward ... up forward: button 9" "129 " "$(pr)"
  local d3 d12
  n0=$(reports | wc -l); ob drag -b "$B" --window R 50 100 250 100 --steps 3 >/dev/null; d3=$(dragged)
  n0=$(reports | wc -l); ob drag -b "$B" --window R 50 100 250 100 --steps 12 >/dev/null; d12=$(dragged)
  check "drag --steps: 3 steps move less often than 12 ($d3, $d12 motions)" test "$d3" -ge 3 -a "$d3" -lt "$d12"
  n0=$(reports | wc -l)
  check "click --mod altgr" ob click -b "$B" --window R 50 50 --mod altgr
  ob click -b "$B" --window R 50 50 >/dev/null
  check_eq "...and nothing held after it (the next click plain)" "0 0 " "$(pr)"
  check_match "env: the box's display to export (its socket, linked in the box dir: finding 493)" "^export WAYLAND_DISPLAY=$XDG_RUNTIME_DIR/omabox/$B/wayland$" "$(ob env -b "$B" | head -1)"
  # #214, finding 287: what a Qt Quick app gets. Left half: a WheelHandler as Qt makes it (a mouse's
  # only); right half: one taking any device, logging the event. Wheels go up: the binds above take
  # mouse_down.
  if [ -x /usr/lib/qt6/bin/qml ]; then
    printf '%s\n' 'import QtQuick' 'Window { width: 600; height: 400; visible: true; title: "qtwheel"' \
      '  Item { width: parent.width / 2; height: parent.height; WheelHandler { onWheel: e => console.log("t214 mouse-only", e.angleDelta.y) } }' \
      '  Item { x: parent.width / 2; width: parent.width / 2; height: parent.height' \
      '    WheelHandler { acceptedDevices: PointerDevice.AllDevices' \
      '      onWheel: e => console.log("t214", e.angleDelta.y, e.pixelDelta.y, e.phase, e.device.type === PointerDevice.TouchPad ? "touchpad" : e.device.type) } } }' \
      > "$(ob path -b "$B")/home/t214.qml"
    local qlog q0=0; qlog=$(ob run -b "$B" -d --wait -- /usr/lib/qt6/bin/qml /home/sbx/t214.qml 2>&1 >/dev/null | sed -n 's/.*[( ]log: \(\/[^,)]*\)[,)].*/\1/p')
    # shellcheck disable=SC2329 # called below
    qw() { grep -a '^qml: t214' "$qlog" | tail -n +$((q0 + 1)) | sed 's/^qml: t214 //' | tr '\n' ',' | sed 's/,$//'; }
    ob wait -b "$B" window title:qtwheel >/dev/null; ob wait -b "$B" still >/dev/null   # (its opening animated)
    local qx; qx=$(ob hyprctl -b "$B" -j clients | jq -r '.[] | select(.title == "qtwheel") | .size[0] * 3 / 4 | floor')
    ob scroll -b "$B" --window qtwheel "$qx" 100 -30 --source wheel >/dev/null
    check "Qt: --source wheel, two notches" until_ok 5 bash -c "grep -ac '^qml: t214 ' '$qlog' | grep -qx 2"
    # Pixels: none before Qt 6.12, the notch's 15 from it (finding 371).
    check_match "...each a wheel's (angle 120, pixels 0 or 15, no phase), from Qt's one pointing device, its touchpad (QTBUG-112432: if Mouse, help scroll's Qt note is stale)" \
      '^120 (0|15) 0 touchpad,120 (0|15) 0 touchpad$' "$(qw)"
    q0=$(grep -ac '^qml: t214' "$qlog"); ob scroll -b "$B" --window qtwheel "$qx" 100 30 --source finger >/dev/null
    until_ok 5 grep -aq ' 3 touchpad$' "$qlog" >/dev/null
    # (A scroll that comes within some 0.3 s of a wheel's notches, as the binary's does here, Qt opens
    # with its begin, 0 0 1, twice: 6 times in 6 on Qt 6.12; none 0.3 s on, nor between two finger
    # scrolls. A touchpad's phases all the same: finding 515.)
    check_match "Qt: --source finger is a touchpad's: pixel deltas in a scroll's updates (phase 2), then its end (3); it came as a wheel's notches before #214" \
      '^(0 0 1 touchpad,)*(-[0-9]+ -[0-9]+ 2 touchpad,)+0 0 3 touchpad$' "$(qw)"
    # The left half, then the right (its line says both have been delivered: they come in order).
    q0=$(grep -ac '^qml: t214' "$qlog"); ob scroll -b "$B" --window qtwheel 100 100 -30 --source wheel >/dev/null
    ob scroll -b "$B" --window qtwheel "$qx" 100 -15 --source wheel >/dev/null
    until_ok 5 bash -c "[ \$(grep -ac '^qml: t214' '$qlog') -gt $q0 ]" >/dev/null
    check_match "...a WheelHandler as Qt makes it takes none of it, a wheel's included (QTBUG-112432)" '^120 (0|15) 0 touchpad$' "$(qw)"
  else skip "Qt: what a Qt Quick app gets from scroll (#214)" "no /usr/lib/qt6/bin/qml"; fi
  ob down "$B" >/dev/null
}

# omabox wait and --wait (finding 82): the pure parts, and the tool's refusal outside a box, checked
# in a bare namespace with no /opt/omabox and no display (where a broken check could reach nothing).
t_unit_wait() {
  # -g (#27), geom_clip (#240), the duration grammar and the cursor's rectangle: settle.rs
  # wait_values_as_bash.
  # wait layer (finding 146): newer Omarchy keeps a hidden menu mapped at 1x1; that is not the menu.
  # ...: ready.rs layer_at_as_bash.
  check_match "wait --timeout over 10 min refused" "at most 10m" "$(ob wait -b "$P-x" --timeout 11m still 2>&1)"
  check_match "keys --timeout over 10 min refused" "at most 10m" "$(ob keys -b "$P-x" --wait --timeout 601s a 2>&1)"
  check_match "keys --quiet over 10 min refused" "--quiet is at most 10m" "$(ob keys -b "$P-x" --wait --quiet 20m a 2>&1)"
  check_match "click --start over 10 min refused" "--start is at most 10m" "$(ob click -b "$P-x" --wait --start 11m 1 1 2>&1)"
  check_match "wait --quiet over 10 min refused" "--quiet is at most 10m" "$(ob wait -b "$P-x" still --quiet 11m 2>&1)"
  check_match "wait for nothing: says what it can wait for" "still, change, window" "$(ob wait -b "$P-x" 2>&1)"
  check_match "an unknown condition refused" "unknown condition" "$(ob wait -b "$P-x" soon 2>&1)"
  check_match "--gone is for window, layer and job" "go with window, layer or job" "$(ob wait -b "$P-x" still --gone 2>&1)"
  # wait layer --monitor (#316): a monitor's name, with layer only. Its answers: wait.rs layer_answers.
  check_match "--monitor is for layer" "--monitor goes with layer" "$(ob wait -b "$P-x" window foot --monitor HEADLESS-2 2>&1)"
  check_match "...a monitor's name" "--monitor takes a monitor's name" "$(ob wait -b "$P-x" layer omarchy-bar --monitor 'a b' 2>&1)"
  check_match "...read (no box here)" "no box '$P-x'" "$(ob wait -b "$P-x" layer omarchy-bar --monitor HEADLESS-2 2>&1)"
  check_match "until needs a command" "nothing to run" "$(ob wait -b "$P-x" until -- 2>&1)"
  # #272: `wait until` is the name; `wait cmd` (refused by Claude Code's worktree check) was warned in
  # 0.9 and is refused since 1.0 (#287), whatever follows it.
  check_match "-- goes with until" "-- goes with until" "$(ob wait -b "$P-x" still -- true 2>&1)"
  local w out rc; for w in "cmd -- true" "cmd" "cmd --ignore 1,1,5,5 -- true"; do
    out=$(eval "ob wait -b $P-x $w" 2>&1); rc=$?
    check_eq "...wait $w: refused (2), one line naming wait until" \
      "2|omabox: wait cmd is refused since 1.0: write wait until -- CMD (the same flags) (omabox help wait)" "$rc|$out"
  done
  check_match "...wait until: read (no box here)" "no box '$P-x'" "$(ob wait -b "$P-x" until -- true 2>&1)"
  check_eq "...until" "omabox: wait until: --ignore goes with still and change (omabox help wait)" \
    "$(ob wait -b "$P-x" until --ignore "1,1 5x5" -- true 2>&1)"
  check_match "...help says until" "until -- CMD \[ARG\.\.\.\]" "$(ob help wait 2>&1)"
  check_match "path: one of --home, --run, --logs" "one of --home, --run and --logs" "$(ob path -b "$P-x" --home --logs 2>&1)"
  check_match "--quiet without --wait refused" "go with --wait" "$(ob keys -b "$P-x" --quiet 1s a 2>&1)"
  check_match "run --wait needs -d" "goes with -d" "$(ob run -b "$P-x" --wait -- true 2>&1)"
  # --ignore and -g (#131, finding 208)
  check_match "--ignore without --wait refused" "go with --wait" "$(ob keys -b "$P-x" --ignore "1,1 5x5" a 2>&1)"
  check_match "-g without --wait refused" "go with --wait" "$(ob click -b "$P-x" -g "1,1 5x5" 1 1 2>&1)"
  check_match "--ignore junk refused" '--ignore is "X,Y WxH"' "$(ob wait -b "$P-x" still --ignore 1,2,3 2>&1)"
  check_match "...on --wait too" '--ignore is "X,Y WxH"' "$(ob run -b "$P-x" -d --wait --ignore 1x2 -- true 2>&1)"
  check_match "-g twice on --wait refused" "-g once" "$(ob keys -b "$P-x" --wait -g "1,1 5x5" -g "2,2 5x5" a 2>&1)"
  check_match "wait window --ignore refused" "go with still and change" "$(ob wait -b "$P-x" window x --ignore "1,1 5x5" 2>&1)"
  check_match "--wait --ignore outside -g's region: said (#162)" 'ignore "100,100 5x5" is outside -g' \
    "$(ob keys -b "$P-x" --wait -g "0,0 10x10" --ignore "100,100 5x5" a 2>&1)"
  check_eq "...one inside it is not" "" "$(ob keys -b "$P-x" --wait -g "0,0 10x10" --ignore "5,5 5x5" a 2>&1 | grep outside)"
  local ig=() i; for i in $(seq 17); do ig+=(--ignore "$i,1 5x5"); done
  check_match "17 --ignore refused" "at most 16" "$(ob wait -b "$P-x" still "${ig[@]}" 2>&1)"
  # (The 124's hint, an --ignore named for a small region changing late, #131, #162, finding 231:
  # settle.rs hint_as_bash; #324 wave 6-suite.)
  check_match "help scroll and help drag have the --wait section (#162)" "take --wait.*take --wait" \
    "$(ob help scroll --long | tr '\n' ' ') $(ob help drag --long | tr '\n' ' ')"
  local out rc=0
  out=$(bwrap --ro-bind / / --dev /dev --proc /proc --unshare-pid --unshare-net --tmpfs /opt --die-with-parent \
        env -i "$ROOT/tools/still/omabox-still" still --timeout 100 2>&1) || rc=$?
  check_eq "omabox-still refuses outside a box" 2 "$rc"
  check_match "...and says so" "only runs inside an omabox box" "$out"
  rc=0; out=$(bwrap --ro-bind / / --dev /dev --proc /proc --unshare-pid --unshare-net --tmpfs /opt --die-with-parent \
        env -i "$ROOT/tools/burst/omabox-burst" -n 2 2>&1) || rc=$?
  check_eq "omabox-burst refuses outside a box (#196)" 2 "$rc"
  check_match "...and says so" "only runs inside an omabox box" "$out"
  # (#124, finding 181: a tool that never ends is killed after 2 s, a box not answering said so:
  # settle.rs a_tool_that_never_ends_is_killed, an #[ignore] test t_unit_rust_ignored runs; #324.)
}

# What an action's --wait says changed on the desktop (#274): DESK_FACTS_JQ on canned snapshots (as
# desk_snap reads them), DESK_TARGET_JQ's sentence for a 124, and settle_end's line and JSON with them.
# wf_snap JQ: a snapshot, the base one (foot "K" focused on workspace 1, the bar drawn, the launcher
# mapped at 1x1) changed by JQ.
wf_snap() {
  jq -c -n "{events: 100,
    clients: [{address: \"0xa\", mapped: true, hidden: false, class: \"foot\", title: \"K\", pid: 40, workspace: {id: 1, name: \"1\"},
      at: [0, 0], size: [960, 1080], floating: false, fullscreen: 0}],
    layers: {\"HEADLESS-2\": {levels: {\"0\": [{address: \"0x1\", namespace: \"omarchy-background\", x: 0, y: 0, w: 1920, h: 1080}], \"1\": [],
      \"2\": [{address: \"0x2\", namespace: \"omarchy-bar\", x: 0, y: 1046, w: 1920, h: 34}],
      \"3\": [{address: \"0x3\", namespace: \"omarchy-menu\", x: 0, y: 0, w: 1, h: 1}]}}},
    active: {address: \"0xa\", class: \"foot\", title: \"K\", workspace: {id: 1, name: \"1\"}},
    workspace: {id: 1, name: \"1\"},
    monitors: [{id: 0, activeWorkspace: {id: 1}, specialWorkspace: {id: 0}}]} | ${1:-.}"
}
# wf_line JQ_AFTER [JQ_BEFORE]: the facts' line from the base (or JQ_BEFORE's) snapshot to JQ_AFTER's.
wf_line() { probe desk_facts "$(wf_snap "${2:-.}")" "$(wf_snap "$1")" | jq -r .line; }
t_unit_wait_facts() {
  local zen='{address: "0xb", mapped: true, hidden: false, class: "zenity", title: "Save as", pid: 41, workspace: {id: 1, name: "1"},
    at: [960, 0], size: [960, 1080], floating: false, fullscreen: 0}'
  local zact='.active = {address: "0xb", class: "zenity", title: "Save as", workspace: {id: 1, name: "1"}}'
  check_eq "nothing changed: no words" "" "$(wf_line .)"
  check_eq "...and changes is []" "[]" "$(probe desk_facts "$(wf_snap)" "$(wf_snap)" | jq -c .changes)"
  check_eq "a window opened and focused: one fact (its focus folded in)" 'window opened, focused: zenity "Save as"' \
    "$(wf_line ".clients += [$zen] | $zact")"
  check_eq "...its changes: the window (focused) and the focus, from foot to zenity" \
    '[{"kind":"window_opened","window":{"address":"0xb","class":"zenity","title":"Save as","workspace":"1"},"focused":true},{"kind":"focus","from":{"address":"0xa","class":"foot","title":"K","workspace":"1"},"to":{"address":"0xb","class":"zenity","title":"Save as","workspace":"1"}}]' \
    "$(probe desk_facts "$(wf_snap)" "$(wf_snap ".clients += [$zen] | $zact")" | jq -c .changes)"
  check_eq "a window opened, not focused" 'window opened: zenity "Save as"' "$(wf_line ".clients += [$zen]")"
  check_eq "...on a workspace not shown: said" 'window opened on workspace 2: zenity "Save as"' \
    "$(wf_line ".clients += [$zen | .workspace = {id: 2, name: \"2\"}]")"
  check_eq "a window closed, focus to none" 'window closed: zenity "Save as"; focus: none' \
    "$(wf_line '.active = {}' ".clients += [$zen] | $zact")"
  check_eq "focus moved between two windows already there" 'focus: zenity "Save as"' "$(wf_line ".clients += [$zen] | $zact" ".clients += [$zen]")"
  local menu='.layers["HEADLESS-2"].levels["3"] = [{address: "0x4", namespace: "omarchy-menu", x: 660, y: 300, w: 600, h: 480}]'
  check_eq "the launcher drawn (from 1x1): layer opened" "layer omarchy-menu opened" "$(wf_line "$menu")"
  check_eq "...with where it is" '{"kind":"layer_opened","namespace":"omarchy-menu","at":{"x":660,"y":300,"w":600,"h":480}}' \
    "$(probe desk_facts "$(wf_snap)" "$(wf_snap "$menu")" | jq -c '.changes[0]')"
  check_eq "...back to 1x1, hidden (finding 146): layer closed" "layer omarchy-menu closed" "$(wf_line . "$menu")"
  check_eq "...unmapped: closed too" "layer omarchy-bar closed" "$(wf_line '.layers["HEADLESS-2"].levels["2"] = []')"
  check_eq "the focused window's title" 'foot title now "~/code/app"' \
    "$(wf_line '.clients[0].title = "~/code/app" | .active.title = "~/code/app"')"
  check_eq "the workspace" "workspace now 2" "$(wf_line '.workspace = {id: 2, name: "2"} | .monitors[0].activeWorkspace.id = 2')"
  check_eq "fullscreen" 'foot "K" now fullscreen' "$(wf_line '.clients[0].fullscreen = 2')"
  check_eq "...and back, floating" 'foot "K" out of fullscreen, now floating' "$(wf_line '.clients[0].floating = true' '.clients[0].fullscreen = 1')"
  check_eq "moved to another workspace" 'foot "K" moved to workspace 3' "$(wf_line '.clients[0].workspace = {id: 3, name: "3"}')"
  check_eq "a tiled window resized because another opened: not a change of its own" 'window opened: zenity "Save as"' \
    "$(wf_line ".clients += [$zen] | .clients[0].size = [960, 1080]" '.clients[0].size = [1920, 1080]')"
  local long; long=$(printf 'x%.0s' {1..200})
  check_eq "a long title cut to 40 characters" "window opened: zenity \"$(printf 'x%.0s' {1..39})…\"" \
    "$(wf_line ".clients += [$zen | .title = \"$long\"]")"
  check_eq "two windows of one class and title: the address says which" 'window closed: foot "K" (0xa)' \
    "$(wf_line '.clients = [.clients[0] | .address = "0xc"] | .active.address = "0xc"' '.clients += [.clients[0] | .address = "0xc"] | .active.address = "0xc"' |
      sed 's/; focus.*//')"
  # Six facts: three said, by weight (opened, closed, layer...), the rest counted, with where to read them.
  local six=".clients = [$zen, ($zen | .address = \"0xd\" | .title = \"B\")] | .active = {} | $menu | .workspace = {id: 2, name: \"2\"}
    | .layers[\"HEADLESS-2\"].levels[\"2\"] = []"
  check_eq "six facts: three said, then +N more and where to read them" \
    'window opened: zenity "Save as"; window opened: zenity "B"; window closed: foot "K"; +4 more (omabox events --since 100)' \
    "$(wf_line "$six")"
  check_eq "...every one in changes" 7 "$(probe desk_facts "$(wf_snap)" "$(wf_snap "$six")" | jq '.changes | length')"
  check_eq "a snapshot missing (the box did not answer): nothing" "" "$(probe desk_facts "$(wf_snap)" "")"
  # (desk_snap's own check of what hyprctl --batch printed: desk.rs snap_of_as_bash; #324.)

  # Where the input went (the 124's sentence).
  local s; s=$(wf_snap ".clients += [$zen | .floating = true | .at = [800, 400] | .size = [300, 200]]")
  check_eq "keys: the focused window" 'the keys went to foot "K" (focused)' \
    "$(probe desk_target keys "$s" "" | jq -r .text)"
  check_eq "...a layer with the keyboard (finding 276) first" "the keys went to layer omarchy-menu (it has the keyboard)|layer" \
    "$(probe desk_target keys "$s" omarchy-menu | jq -r '"\(.text)|\(.kind)"')"
  check_eq "...none focused" "the keys went to no window (none focused)|none" \
    "$(probe desk_target keys "$(wf_snap '.active = {}')" "" | jq -r '"\(.text)|\(.kind)"')"
  check_eq "click: the floating window over the tiled one, in its own coordinates" \
    'the click at 900,450 was on zenity "Save as" (its 100,50)|{"x":100,"y":50}' \
    "$(probe desk_target click "$s" "900 450" | jq -r '"\(.text)|\(.at | tojson)"')"
  check_eq "...beside it, the tiled one" 'the click at 100,450 was on foot "K" (its 100,450)' "$(probe desk_target click "$s" "100 450" | jq -r .text)"
  check_eq "...the bar (a top layer) before any window" 'the click at 30,1060 was on layer omarchy-bar (over foot "K")|layer' \
    "$(probe desk_target click "$s" "30 1060" | jq -r '"\(.text)|\(.kind)"')"
  check_eq "...a hidden 1x1 menu is not there" 'the click at 0,0 was on foot "K" (its 0,0)' "$(probe desk_target click "$s" "0 0" | jq -r .text)"
  check_eq "...no window: the background" 'the scroll at 1500,500 was on no window (layer omarchy-background)' \
    "$(probe desk_target scroll "$s" "1500 500" | jq -r .text)"
  check_eq "...a bottom layer there is over the background: it, not the background (finding 398)" \
    'the scroll at 1500,500 was on no window (layer waybar-like)' \
    "$(probe desk_target scroll "$(jq -c '.layers["HEADLESS-2"].levels["1"] = [{address: "0x6", namespace: "waybar-like", x: 1400, y: 400, w: 200, h: 200}]' <<<"$s")" "1500 500" | jq -r .text)"
  check_eq "...a window on a workspace not shown is not there" 'the drag from 100,450 started on no window or layer' \
    "$(probe desk_target drag "$(wf_snap '.clients[0].workspace = {id: 2, name: "2"} | .layers = {}')" "100 450" | jq -r .text)"
  check_eq "...certain" true "$(probe desk_target click "$s" "100 450" | jq -r .certain)"
  # A full-screen overlay (#263, finding 398: Omarchy's notifications) may have taken a click or not:
  # the target is what is under it, certain false; a layer smaller than its output still wins.
  local sn; sn=$(jq -c '.monitors[0] += {name: "HEADLESS-2", x: 0, y: 0, width: 1920, height: 1080, scale: 1, transform: 0}
    | .layers["HEADLESS-2"].levels["3"] += [{address: "0x5", namespace: "omarchy-notifications", x: 0, y: 0, w: 1920, h: 1080}]' <<<"$s")
  check_eq "a full-screen overlay over the point: the window under it, possibly the layer" \
    'the click at 100,450 was on foot "K" (its 100,450), or possibly on layer omarchy-notifications (it spans the screen: if one of its items, a toast, is there)|window|false|null' \
    "$(probe desk_target click "$sn" "100 450" | jq -r '"\(.text)|\(.kind)|\(.certain)|\(.namespace)"')"
  check_eq "...the bar (top, smaller) under it wins: certain" 'the click at 30,1060 was on layer omarchy-bar (over foot "K")|layer|true' \
    "$(probe desk_target click "$sn" "30 1060" | jq -r '"\(.text)|\(.kind)|\(.certain)"')"
  check_eq "...no window under it: the background, possibly the layer" \
    'the scroll at 1500,500 was on no window (layer omarchy-background), or possibly on layer omarchy-notifications (it spans the screen: if one of its items, a toast, is there)|layer|omarchy-background|false' \
    "$(probe desk_target scroll "$sn" "1500 500" | jq -r '"\(.text)|\(.kind)|\(.namespace)|\(.certain)"')"
  check_eq "...the same layer a toast's size: on it, certain" 'the click at 100,450 was on layer omarchy-notifications (over foot "K")|true' \
    "$(probe desk_target click "$(jq -c '.layers["HEADLESS-2"].levels["3"][-1] += {y: 400, h: 100}' <<<"$sn")" "100 450" | jq -r '"\(.text)|\(.certain)"')"
  # A window in real fullscreen (mode 2) covers the top level (#409, finding 561): the bar's strip
  # over its top edge takes none of the click (Hyprland passes top layers by there, and 4.5.0's bar
  # masks itself); an overlay still does, and a maximized window (mode 1) keeps the bar over it.
  local sf; sf=$(wf_snap '.clients[0] += {fullscreen: 2, size: [1920, 1080]}
    | .layers["HEADLESS-2"].levels["2"] = [{address: "0x2", namespace: "omarchy-bar", x: 0, y: 0, w: 1920, h: 34}]')
  check_eq "fullscreen: the bar's strip over its top edge is not where the click went (#409)" \
    'the click at 100,10 was on foot "K" (its 100,10)|window|true' \
    "$(probe desk_target click "$sf" "100 10" | jq -r '"\(.text)|\(.kind)|\(.certain)"')"
  check_eq "...an overlay there still is" 'the click at 100,10 was on layer t-toast (over foot "K")' \
    "$(probe desk_target click "$(jq -c '.layers["HEADLESS-2"].levels["3"] += [{address: "0x7", namespace: "t-toast", x: 0, y: 0, w: 300, h: 100}]' <<<"$sf")" "100 10" | jq -r .text)"
  check_eq "...maximized (mode 1): the bar still is" 'the click at 100,10 was on layer omarchy-bar (over foot "K")' \
    "$(probe desk_target click "$(jq -c '.clients[0].fullscreen = 1' <<<"$sf")" "100 10" | jq -r .text)"
  check_eq "...fullscreen on a workspace not shown: the bar is" 'the click at 100,10 was on layer omarchy-bar' \
    "$(probe desk_target click "$(jq -c '.clients[0].workspace = {id: 2, name: "2"}' <<<"$sf")" "100 10" | jq -r .text)"
  # A click at screen X Y (#361, finding 562) says a layer over the window there before it is sent,
  # as --window does, when it certainly covers the point (one smaller than its output); nothing for
  # one spanning it, with no layer there or no window under it (a click meant for the bar, the desktop).
  local toast='.layers["HEADLESS-2"].levels["3"] += [{address: "0x8", namespace: "omarchy-notifications", x: 600, y: 0, w: 300, h: 100}]'
  check_eq "screen click under a toast-sized layer over a window: said, certain (#361)" \
    'a layer surface "omarchy-notifications" (overlay 300x100 at 600,0) is over the screen'"'"'s 700,50, on window 0xa foot "K": where it takes input (a notification, a panel), input there goes to it, not to the window (omabox wait layer omarchy-notifications --gone waits it out)' \
    "$(probe screen_layer "$(wf_snap "$toast")" "700 50")"
  check_eq "...a full-screen one: nothing (it may not take the point; --window says the may)" "" \
    "$(probe screen_layer "$sn" "100 450")"
  check_eq "...the floating window's own point, under the toast-sized one: that window named" \
    'a layer surface "omarchy-notifications" (overlay 300x100 at 600,0) is over the screen'"'"'s 850,50, on window 0xb zenity "Save as": where it takes input (a notification, a panel), input there goes to it, not to the window (omabox wait layer omarchy-notifications --gone waits it out)' \
    "$(probe screen_layer "$(jq -c "$toast | .clients[1].at = [800, 0]" <<<"$s")" "850 50")"
  check_eq "...beside the layer: nothing" "" "$(probe screen_layer "$(wf_snap "$toast")" "100 450")"
  check_eq "...the bar with no window under it: nothing" "" "$(probe screen_layer "$(wf_snap '.clients[0].size = [960, 1000]')" "30 1060")"
  check_eq "...the bar's strip over a fullscreen window: nothing (#409)" "" "$(probe screen_layer "$sf" "100 10")"
  check_eq "...a snapshot missing: nothing" "" "$(probe screen_layer "" "700 50")"
  check_eq "run: no window with the job's pid" "no window from pid 99 yet|none" "$(probe desk_target run "$s" 99 | jq -r '"\(.text)|\(.kind)"')"
  check_eq "...its window" "window|0xb" "$(probe desk_target run "$s" 41 | jq -r '"\(.kind)|\(.window.address)"')"

  # (settle_end with them, the line's start kept, the facts after it, JSON's changes, target and
  # events_since: settle.rs facts_as_bash; #324 wave 6-suite.)
}

# omabox wait and --wait (finding 82) in a box of their own: two terminals side by side, one of them
# repainting 20 times a second.
# t_wait's thin-line checks: 124, and a last change 2 px high (the underline), or 3: under the full
# suite's load the box's Hyprland can draw the window a fraction of a pixel off its box (#222, finding
# 342), and every edge, the line's too, gets a one-level fringe (the row above it one level up, its
# last row one down). Still thin (THIN is 4), so it tests the same thing. Anything else: the frames
# before and after that change (the still tool's --dump, through OMABOX_STILL_DUMP) and the whole
# screen (where a window drawn off its box shows, at its borders) go to the evidence.
# thin_check DESC OUT RC DUMP (box $B)
thin_check() {
  local got; got="$3 $(jq -r '.change.h' <<<"$2" 2>/dev/null)"
  if [[ $got =~ ^124\ [23]$ ]]; then ok "$1"; return; fi
  # shellcheck disable=SC2031 # (the globals; only t_unit_parallel's fake run changed them, in its subshell)
  local e=$EVID/$CUR f; mkdir -p "$e"
  for f in before after; do ob run -b "$B" -- cat "$4/$f.ppm" > "$e/${4##*/}-$f.ppm" 2>/dev/null; done
  ob shot -b "$B" -o "$e/${4##*/}-screen.png" >/dev/null 2>&1 || true
  no "$1" "want [124 2] or [124 3] got [$got]; frames before and after the last change: $e/${4##*/}-{before,after}.ppm, the screen: $e/${4##*/}-screen.png; ${2:0:400}"
}
t_wait() {
  local B=$P-wait out rc
  up_ok "$B" --no-shell --net isolated || { no "up" "$UP_OUT"; return; }
  local D; D=$(ob path "$B")
  out=$(ob wait -b "$B" still); rc=$?
  check_eq "an idle screen is still: exit 0" 0 "$rc"
  check_match "...said on one line" "^satisfied: still after 0\.[0-9]+s" "$out"
  touch -d '-1 hour' "$D/used"
  ob wait -b "$B" still --quiet 100ms >/dev/null
  check "wait counts as use (idle expiry)" test "$(( $(date +%s) - $(stat -c %Y "$D/used") ))" -lt 60
  out=$(ob run -b "$B" -d --wait -- foot -T A sh -c 'cat > /tmp/typed' 2>/dev/null); rc=$?
  check_eq "run -d --wait: settled" 0 "$rc"
  check_match "...once the window was drawn" "^satisfied: settled after .*last change" "$out"
  check "wait window: it is there" ob wait -b "$B" window 'title:^A$' --focused
  out=$(ob keys -b "$B" --wait -t hello); rc=$?
  check_eq "keys --wait: typing settles" 0 "$rc"
  # omabox-still names the last thing it ignored: the cursor the key press hid, or foot's caret when a
  # later frame had it (#116: seen under load). Either way not a change that kept it from settling.
  check_match "...the cursor hidden by the key press (or the caret) is ignored, said" "ignored .*: (cursor|caret\?)" "$out"
  local err; out=$(ob keys -b "$B" --wait --start 1s shift 2>"$TMP/wait.err"); rc=$?; err=$(cat "$TMP/wait.err")
  check_eq "keys --wait of a key that changes nothing: 124" 124 "$rc"
  check_match "...nothing changed" "^unsatisfied: nothing changed in 1\.[0-9]+s" "$out"
  check_match "...and the keys were sent all the same" "keys were sent" "$err"
  out=$(ob keys -b "$B" --wait --json -t x)
  check_eq "--json" "satisfied settle" "$(jq -r '"\(.result) \(.condition)"' <<<"$out")"
  # A caret blinking (foot's beam) is not a change; --strict counts it
  ob run -b "$B" -d --wait -- foot -T C -o cursor.blink=yes -o cursor.style=beam sh -c 'sleep 600' >/dev/null 2>&1
  out=$(ob wait -b "$B" still --quiet 1500ms); rc=$?
  check_eq "a blinking caret is still" 0 "$rc"
  check_match "...said as a caret" "ignored 2x[0-9]+ at [0-9]+,[0-9]+: caret\?" "$out"
  check_eq "...--strict: it is a change (124)" 124 "$(ob wait -b "$B" still --quiet 1500ms --strict --timeout 2500ms >/dev/null; echo $?)"
  ob run -b "$B" -- pkill -f 'foot -T C' >/dev/null
  check "wait window --gone" ob wait -b "$B" window 'title:^C$' --gone
  ob wait -b "$B" still >/dev/null   # A takes the whole screen once C is gone
  # #180: a caret is 40 px long at most and blinks in place. A 2 px underline 60 cells long toggling,
  # and a one-cell one stepping along its line (each step 2 cells: caret-sized), are changes.
  ob run -b "$B" -d -q --wait -- foot -T U -o underline-thickness=2px sh -c \
    'printf "\033[?25l"; while :; do printf "\r\033[4m%60s\033[0m" ""; sleep 0.1; printf "\r%60s" ""; sleep 0.1; done' >/dev/null 2>&1
  out=$(OMABOX_STILL_DUMP=/tmp/still-U ob wait -b "$B" still --timeout 1500ms --window 'title:^U$' --json); rc=$?
  thin_check "a long thin line toggling: not a caret, still changing (124)" "$out" "$rc" /tmp/still-U
  check "...the change is that line (${out:0:300})" jq -e '.change.w > 100' <<<"$out"
  ob run -b "$B" -- pkill -f 'foot -T U' >/dev/null
  ob wait -b "$B" window 'title:^U$' --gone >/dev/null
  ob run -b "$B" -d -q --wait -- foot -T M -o underline-thickness=2px sh -c \
    'printf "\033[?25l"; i=0; while :; do printf "\r%*s\033[4m \033[0m%*s" $i "" $((30 - i)) ""; i=$(((i + 1) % 30)); sleep 0.08; done' >/dev/null 2>&1
  out=$(OMABOX_STILL_DUMP=/tmp/still-M ob wait -b "$B" still --timeout 1500ms --window 'title:^M$' --json); rc=$?
  thin_check "a short thin segment moving: not a caret, still changing (124)" "$out" "$rc" /tmp/still-M
  check "...the change is caret-sized (${out:0:300})" jq -e '.change.w <= 40' <<<"$out"
  ob run -b "$B" -- pkill -f 'foot -T M' >/dev/null
  ob wait -b "$B" window 'title:^M$' --gone >/dev/null
  ob wait -b "$B" still >/dev/null
  out=$(ob click -b "$B" --wait --start 1s --window 'title:^A$' 40 40 2>"$TMP/wait.err"); rc=$?
  check_eq "click --wait on what does nothing: 124" 124 "$rc"
  check_match "...said, and that the click was sent" "^unsatisfied: nothing changed.*click was sent" "$out $(cat "$TMP/wait.err")"
  check_eq "...it was: the pointer is there" "$(ob windows -b "$B" --json | jq -r '.[] | select(.title == "A") | "\(.at[0] + 40), \(.at[1] + 40)"')" "$(ob hyprctl -b "$B" cursorpos)"
  # A repaint loop: never still (124, naming where); a window beside it is
  ob run -b "$B" -d -- foot -T R sh -c 'while :; do printf "\033[4%sm\033[2J" $((RANDOM % 7)); sleep 0.05; done' >/dev/null 2>&1
  ob wait -b "$B" window 'title:^R$' >/dev/null
  local r; r=$(ob windows -b "$B" --json | jq -r '.[] | select(.title == "R") | "\(.at[0]) \(.at[0] + .size[0])"')
  out=$(ob wait -b "$B" still --timeout 1500ms); rc=$?
  check_eq "a repaint loop: 124 at the deadline" 124 "$rc"
  check_match "...naming where it changes" "^unsatisfied: still changing after 1\.[0-9]+s \(last change .* at [0-9]+,[0-9]+ [0-9]+x[0-9]+\)$" "$out"
  local x; x=$(sed -n 's/.* at \([0-9]*\),.*/\1/p' <<<"$out")
  check "...inside that window ($x in ${r% *}..${r#* })" test "${x:-0}" -ge "${r% *}" -a "${x:-0}" -lt "${r#* }"
  check "...a window beside it is still" ob wait -b "$B" still --window 'title:^A$'
  check_eq "wait change: the loop changes" 0 "$(ob wait -b "$B" change --window 'title:^R$' >/dev/null; echo $?)"
  # Absence and timeouts
  # (#110) The wait's own elapsed, not the clock around the CLI: its start-up under load took 1-2 s.
  local tw; tw=$(ob wait -b "$B" --timeout 1s --json window 'title:^nope$'); rc=$?
  check_eq "a window that never comes: 124" "124 unsatisfied" "$rc $(jq -r .result <<<"$tw")"
  check "...at the deadline (1 s asked, $(jq -r .elapsed <<<"$tw") s)" jq -e '.elapsed >= 1 and .elapsed < 3' <<<"$tw"
  # Several windows match (A and R): any is an answer, each named (#37).
  out=$(ob wait -b "$B" window foot); rc=$?
  check_eq "several windows match: satisfied (#37)" 0 "$rc"
  check_match "...each named" '^satisfied: window foot after [0-9.]+s: 2 windows: 0x[0-9a-f]+ foot "[AR]" at .*; 0x[0-9a-f]+ foot "[AR]" at ' "$out"
  out=$(ob wait -b "$B" window foot --focused --json); rc=$?
  check_eq "...--focused: the focused one of them" "0 satisfied" "$rc $(jq -r .result <<<"$out")"
  check_match "...named, with how many match" 'foot "[AR]" .*, focused \(1 of 2 matching\)$' "$(jq -r .detail <<<"$out")"
  check_eq "...--gone: 124 while they are there" 124 "$(ob wait -b "$B" --timeout 500ms window foot --gone >/dev/null; echo $?)"
  check_eq "...an action on one window still refuses several: exit 2" 2 "$(ob shot -b "$B" -w foot >/dev/null 2>&1; echo $?)"
  # until (#272; cmd up to 0.8.0, refused since 1.0): a condition inside the box, here one that becomes true a second later
  ob run -b "$B" -d -- sh -c 'sleep 1; touch /tmp/late' >/dev/null 2>&1
  out=$(ob wait -b "$B" until -- test -e /tmp/late); rc=$?
  check_eq "wait until: 0 once it succeeds" 0 "$rc"
  check_match "...after it did" "^satisfied: command succeeded after (0\.[5-9]|[1-9])" "$out"
  check_eq "wait until that keeps failing: 124" 124 "$(ob wait -b "$B" --timeout 500ms until -- false >/dev/null; echo $?)"
  out=$(ob wait -b "$B" --timeout 500ms --json until -- false); rc=$?
  check_eq "...--json: condition until, exit 124" "unsatisfied until exit 1 124" "$(jq -r '"\(.result) \(.condition) \(.detail)"' <<<"$out") $rc"
  # A steady animation (#131, finding 208): one cell that never stops changing. The 124 names it as an
  # --ignore; --ignore'd, wait still and keys --wait are satisfied; -g watches elsewhere.
  ob run -b "$B" -- pkill -x foot >/dev/null
  ob wait -b "$B" window foot --gone >/dev/null
  ob run -b "$B" -d -q -- foot -T N sh -c 'i=0; while :; do printf "\r%s" $((i++ % 10)); sleep 0.05; done'
  ob wait -b "$B" window 'title:^N$' >/dev/null
  out=$(ob wait -b "$B" still --timeout 2s); rc=$?
  check_eq "a cell that never stops changing: 124" 124 "$rc"
  check_match "...named as an --ignore" '; from 1\.[0-9]+s on it changed only at [0-9]+,[0-9]+ [0-9]+x[0-9]+: --ignore "[0-9]+,[0-9]+ [0-9]+x[0-9]+" if that is an animation$' "$out"
  local g; g=$(sed -n 's/.*--ignore "\([^"]*\)".*/\1/p' <<<"$out")
  out=$(ob wait -b "$B" still --ignore "$g"); rc=$?
  check_eq "wait still --ignore \"$g\": satisfied" 0 "$rc"
  check_match "...saying what it ignored" "ignored [0-9]+x[0-9]+ at [0-9]+,[0-9]+: --ignore\)$" "$out"
  out=$(ob wait -b "$B" still --ignore "$g" --strict --json); rc=$?
  check_eq "...--strict keeps an --ignore" "0 satisfied" "$rc $(jq -r .result <<<"$out")"
  out=$(ob keys -b "$B" --wait --timeout 2s -t x 2>/dev/null); rc=$?
  check_eq "keys --wait without it: 124" 124 "$rc"
  check_match "...still changing" "^unsatisfied: still changing" "$out"
  out=$(ob keys -b "$B" --wait --ignore "$g" -t y); rc=$?
  check_eq "keys --wait --ignore it: settled" 0 "$rc"
  out=$(ob keys -b "$B" --wait --start 1s -g "1000,600 200x200" --json shift 2>/dev/null); rc=$?
  check_eq "keys --wait -g elsewhere: nothing changed there (not still changing)" "124 unsatisfied nothing changed" \
    "$rc $(jq -r '"\(.result) \(.message | split(" in ")[0])"' <<<"$out")"
  check "wait --json: late_changes is the region" jq -e '.late_changes.w > 0' <<<"$(ob wait -b "$B" still --timeout 1s --json)"
  # drag --wait (#102, finding 172): its own cursor crossing the screen is not a change; what the drag
  # does beside it (foot's selection across several lines) is.
  ob run -b "$B" -- pkill -x foot >/dev/null
  ob wait -b "$B" window foot --gone >/dev/null; ob wait -b "$B" still >/dev/null
  out=$(ob drag -b "$B" --wait --json --start 1s 200 200 900 700 2>/dev/null); rc=$?
  check_eq "drag --wait across an empty screen: 124" "124 unsatisfied" "$rc $(jq -r .result <<<"$out")"
  ob run -b "$B" -d --wait -- foot -T D sh -c 'for i in $(seq 60); do echo "line $i: the quick brown fox jumps over the lazy dog"; done; exec sleep 600' >/dev/null 2>&1
  out=$(ob drag -b "$B" --wait 200 200 900 700); rc=$?
  check_eq "drag --wait selecting text: settled" 0 "$rc"
  check_match "...on a change that is not the cursor" "^satisfied: settled after .*last change" "$out"
  # A region off the screen watches nothing: unknown (1), never still
  out=$(ob wait -b "$B" still -g "5000,5000 10x10"); rc=$?
  check_eq "wait still -g off the screen: exit 1" 1 "$rc"
  check_match "...said" "^unknown: the region watched is not on the screen" "$out"
  # The box going down mid-wait is unknown (1), never satisfied
  ob wait -b "$B" still --quiet 30s > "$TMP/wait.out" 2>&1 & local w=$!
  sleep 1.5; ob down "$B" >/dev/null 2>&1
  wait "$w"; rc=$?
  check_eq "the box went down during wait: exit 1" 1 "$rc"
  check_match "...said" "^unknown: box '$B' went down after" "$(cat "$TMP/wait.out")"
}

# run -d -q / --print-log (issue #42, finding 109) and run -d --replace (issue #29, finding 110).
t_replace() {
  local B=$P-rep out err rc D old new
  up_ok "$B" --no-shell --net isolated || { no "up" "$UP_OUT"; return; }
  D=$(ob path "$B")
  out=$(ob run -b "$B" -d -q --print-log --wait -- foot -T R sh -c 'sleep 600' 2>"$TMP/rep.err"); rc=$?
  check_eq "run -d -q --print-log --wait: settled" 0 "$rc"
  check_eq "...-q: nothing on stderr" "" "$(cat "$TMP/rep.err")"
  check_match "...the log path first on stdout, then the wait's line" "^$D/home/run-[0-9]+\.log"$'\n'"satisfied: " "$out"
  check "...that log exists" test -f "$(head -1 <<<"$out")"
  old=$(ob windows -b "$B" --json | jq -r '.[] | select(.title == "R") | .pid')
  check "...its job is recorded" test -s "$D/jobs/$old"
  out=$(ob run -b "$B" -d --replace --wait -- foot -T R sh -c 'sleep 600' 2>"$TMP/rep.err"); rc=$?; err=$(cat "$TMP/rep.err")
  check_eq "--replace --wait: settled" 0 "$rc"
  check_match "...said: the earlier job stopped, its window gone" "stopped the earlier job \(1 window\)" "$err"
  check_match "...and the new one's pid and log" "started in box '$B' \(pid [0-9]+, log: " "$err"
  new=$(ob windows -b "$B" --json | jq -r '[.[] | select(.title == "R") | .pid] | join(" ")')
  check "...one window R, a new process ($old -> $new)" test -n "$new" -a "$new" != "$old" -a "${new// /}" = "$new"
  check_fails "...the old record is gone" test -e "$D/jobs/$old"
  # The issue's race: the old window still starting when the new launch comes
  ob run -b "$B" -d -q -- foot -T S sh -c 'sleep 600'
  ob run -b "$B" -d -q --replace --wait -- foot -T S sh -c 'sleep 600' >/dev/null
  check_eq "replaced while still starting: one window S" 1 "$(ob windows -b "$B" --json | jq '[.[] | select(.title == "S")] | length')"
  # A launcher that exits and leaves its app: the app is the job's (its session)
  ob run -b "$B" -d -q -- sh -c 'foot -T L sh -c "sleep 600" & exit'
  ob wait -b "$B" window 'title:^L$' >/dev/null
  old=$(ob windows -b "$B" --json | jq -r '.[] | select(.title == "L") | .pid')
  ob run -b "$B" -d -q --replace --wait -- sh -c 'foot -T L sh -c "sleep 600" & exit' >/dev/null
  new=$(ob windows -b "$B" --json | jq -r '[.[] | select(.title == "L") | .pid] | join(" ")')
  check "a launcher's app replaced ($old -> $new)" test -n "$new" -a "$new" != "$old" -a "${new// /}" = "$new"
  # Only what run -d started: the same command started otherwise is left alone
  ob run -b "$B" -- setsid -f sleep 601
  ob run -b "$B" -d -q -- sleep 601
  ob run -b "$B" -d -q --replace -- sleep 601
  check_eq "...one sleep 601 not run -d's, one new: both there" 2 "$(ob run -b "$B" -- pgrep -cxf 'sleep 601')"
  # Other arguments (#255): not replaced, as before, but the job of the same program still running named
  err=$(ob run -b "$B" -d --replace -- sleep 602 2>&1 >/dev/null)
  check_match "other arguments: the earlier job of the program named" \
    "no earlier job with these arguments, none stopped; sleep \(pid [0-9]+, 601\) still runs, and the new job starts beside it \(omabox -b $B stop [0-9]+ stops it\)" "$err"
  old=$(sed -n 's/.*sleep (pid \([0-9]*\),.*/\1/p' <<<"$err")
  check "...and left running ($old), beside the new one" test -n "$old" -a "$(ob run -b "$B" -- sh -c "kill -0 $old && pgrep -cxf 'sleep 602'")" = 1
  # Nothing to replace: said; a job that ended: its record dropped
  err=$(ob run -b "$B" -d --replace -- env sleep 609 2>&1 >/dev/null)
  check_match "no earlier job: said" "no earlier job of this command" "$err"
  out=$(ob run -b "$B" -d -q --print-log -- sh -c 'sleep 1.5')
  until_ok 5 bash -c "! '$CLI' run -b '$B' -- pgrep -fx '(sh -c )?sleep 1.5'" >/dev/null
  old=$(grep -l '"sleep 1.5"' "$D"/jobs/*)
  # (Its status kept, then said by a command of its own: an end within 30 s, finding 399.)
  until_ok 5 test -e "$D/run/omabox.$(basename "$out" .log).exit" >/dev/null; ob windows -b "$B" >/dev/null 2>&1
  err=$(ob run -b "$B" -d --replace -- sh -c 'sleep 1.5' 2>&1 >/dev/null)
  check_match "a job that exited: nothing to replace" "no earlier job" "$err"
  check_fails "...nor named" grep -q 'sleep 1.5' <<<"$err"
  check "...its record dropped (${old##*/})" test -n "$old" -a ! -e "$old"
  # #286, finding 399: a job that ends after run -d's first 0.3 s, within 30 s, is said by the box's
  # next command, once; one --replace stopped is not.
  out=$(ob run -b "$B" -d -q --print-log -- sh -c 'sleep 1; exit 3')
  check "a job that exits 3 after 1 s: its status kept" until_ok 5 test -e "$D/run/omabox.$(basename "$out" .log).exit"
  err=$(ob windows -b "$B" 2>&1 >/dev/null)
  check_match "...the next command says it, with its pid, status, time and log" \
    "omabox: warning: run -d job sh -c sleep 1; exit 3 \(pid [0-9]+\) exited with status 3 after 1\.[0-9]s, since the last command \(log: omabox log -b $B run\)" "$err"
  check_eq "...once: not the command after" "" "$(ob windows -b "$B" 2>&1 >/dev/null | grep 'run -d job')"
  ob run -b "$B" -d -q -- sh -c 'sleep 610'
  out=$(ob run -b "$B" -d -q --print-log --replace -- sh -c 'sleep 610')
  old=$(cd "$D/home" && printf '%s\n' run-*.log | sort | tail -n 2 | head -n 1)
  check "a job --replace stopped: its status kept (killed)" until_ok 5 test -e "$D/run/omabox.${old%.log}.exit"
  check_eq "...not said by the next command" "" "$(ob windows -b "$B" 2>&1 >/dev/null | grep 'run -d job')"
  # #300, finding 406: a job the agent stopped itself through `omabox run` is not said; one killed
  # otherwise (by itself, 3 s in: past the 2 s after that run) still is
  out=$(ob run -b "$B" -d -q --print-log -- sleep 611)
  ob run -b "$B" -- pkill -xf 'sleep 611'
  check "a job stopped by omabox run -- pkill: its status kept" until_ok 5 test -e "$D/run/omabox.$(basename "$out" .log).exit"
  check_eq "...not said by the next command" "" "$(ob windows -b "$B" 2>&1 >/dev/null | grep 'run -d job')"
  # (#329: one that traps SIGTERM and exits with a code of its own, as foot exits 230: not said either)
  out=$(ob run -b "$B" -d -q --print-log -- sh -c 'trap "exit 230" TERM; while :; do sleep 0.1; done; : trap230')
  ob run -b "$B" -- pkill -f 'trap230'
  check "a job that exits 230 on SIGTERM, stopped by omabox run -- pkill: its status kept" until_ok 5 test -e "$D/run/omabox.$(basename "$out" .log).exit"
  check_eq "...not said by the next command (#329)" "" "$(ob windows -b "$B" 2>&1 >/dev/null | grep 'run -d job')"
  out=$(ob run -b "$B" -d -q --print-log -- sh -c 'sleep 3; kill -TERM $$')
  check "a job killed otherwise: its status kept" until_ok 8 test -e "$D/run/omabox.$(basename "$out" .log).exit"
  check_match "...said" "run -d job sh -c sleep 3; kill -TERM .* was killed by SIGTERM \(143\) after 3\." "$(ob windows -b "$B" 2>&1 >/dev/null)"
  # A job that ignores SIGTERM: killed after 5 s
  ob run -b "$B" -d -q -- sh -c 'trap "" TERM; sleep 603'
  local t0=$SECONDS
  err=$(ob run -b "$B" -d --replace -- sh -c 'trap "" TERM; sleep 603' 2>&1 >/dev/null); rc=$?
  check_eq "SIGTERM ignored: replaced all the same" 0 "$rc"
  check_match "...killed, said" "ignored SIGTERM for 5 s: killed" "$err"
  check "...after about 5 s ($((SECONDS - t0)) s)" test $((SECONDS - t0)) -ge 4 -a $((SECONDS - t0)) -le 9
  check_eq "...one sleep 603 left" 1 "$(ob run -b "$B" -- pgrep -cxf 'sleep 603')"
  # #215: a command that ends before --wait gives up: said, with its status and its log, not as started
  echo probe > "$TMP/rep-probe.qml"
  out=$(ob run -b "$B" -d -q --wait --start 1s -- sh -c 'echo boom >&2; exit 3' "$TMP/rep-probe.qml" 2>"$TMP/rep.err"); rc=$?; err=$(cat "$TMP/rep.err")
  check_eq "run -d --wait of a command that exits 3 at once: exit 3" 3 "$rc"
  check_match "...the wait's line still on stdout" "^unsatisfied: " "$out"
  check_match "...said: exited with status 3, nothing left running" "the command exited with status 3 before the screen settled, and left nothing running" "$err"
  check_match "...with its log's last lines" "its log ends \(omabox log -b $B run\):"$'\n'"  boom" "$err"
  check_match "...the host path the box does not have named" "host paths box '$B' does not have: $TMP/rep-probe.qml " "$err"
  check_fails "...not 'started all the same'" grep -q 'all the same' <<<"$err"
  err=$(ob run -b "$B" -d -q --wait --start 1s -- sh -c 'kill -TERM $$' 2>&1 >/dev/null); rc=$?
  check_eq "a command killed by a signal: its status (143)" 143 "$rc"
  check_match "...said" "was killed by SIGTERM \(143\) before the screen settled" "$err"
  check_match "...an empty log said" "its log is empty" "$err"
  err=$(ob run -b "$B" -d -q --wait --start 1s -- true 2>&1 >/dev/null); rc=$?
  check_eq "a command that exits 0 at once: still 124 (the screen)" 124 "$rc"
  check_match "...said" "exited with status 0 before the screen settled, and left nothing running: what the screen shows is not its" "$err"
  err=$(ob run -b "$B" -d -q --wait --start 1s -- sleep 605 2>&1 >/dev/null); rc=$?
  check_eq "a command still running that draws nothing: 124" 124 "$rc"
  check_match "...started all the same, as before" "the command was started all the same \(124 is about the screen\)" "$err"
  # #297, finding 404: a job dead at once while another window closed: the screen settled on that,
  # and it said satisfied. Now unsatisfied, its end said, its status the exit's; a one-shot that
  # closes it and exits 0 is satisfied, as before.
  ob run -b "$B" -d -q -- foot -T K sh -c 'sleep 600'
  ob wait -b "$B" window 'title:^K$' >/dev/null
  out=$(ob run -b "$B" -d -q --wait -- sh -c 'pkill -f "^foot -T K "; echo gone >&2; exit 3' 2>"$TMP/rep.err"); rc=$?; err=$(cat "$TMP/rep.err")
  check_eq "run -d --wait of a job that died as another window closed: its status (3)" 3 "$rc"
  check_match "...unsatisfied: not its screen" "^unsatisfied: .*the command had ended by then: not its screen" "$out"
  check_match "...its end and log said" "the command exited with status 3 before the screen settled, and left nothing running.*"$'\n'"  gone" "$err"
  # (foot K's own end, killed, is said: it was a run -d job too)
  check_eq "...not said again by the next command" "" "$(ob windows -b "$B" 2>&1 >/dev/null | grep 'run -d job sh -c pkill')"
  ob run -b "$B" -d -q -- foot -T K sh -c 'sleep 600'
  ob wait -b "$B" window 'title:^K$' >/dev/null
  out=$(ob run -b "$B" -d -q --wait -- pkill -f "^foot -T K " 2>/dev/null); rc=$?
  check_match "...a one-shot that closes it and exits 0: satisfied" "^0 satisfied: " "$rc $out"
  ob windows -b "$B" >/dev/null 2>&1
  # A missing command still says so in its log
  out=$(ob run -b "$B" -d -q --print-log -- omabox-no-such-command)
  check "a missing command: said in its log" until_ok 5 grep -q 'setsid: failed to execute omabox-no-such-command' "$out"
  # finding 229: the log is opened in the box. A box that knows the name and links it to a host file:
  # that file untouched, the log a file of the box's. The name is the suite's: a stand-in `date` on
  # PATH for bash's half (--installed runs it), OMABOX_TEST_RUN_NS for the Rust half, which reads it
  # under OMABOX_SUITE only (finding 444).
  mkdir -p "$TMP/rep-bin"; echo keep > "$TMP/rep-victim"
  printf '#!/bin/sh\n[ "$1" = +%%s%%N ] && { echo 1229; exit; }\nexec /usr/bin/date "$@"\n' > "$TMP/rep-bin/date"; chmod +x "$TMP/rep-bin/date"
  ob run -b "$B" -- ln -sf "$TMP/rep-victim" /home/sbx/run-1229.log
  out=$(PATH=$TMP/rep-bin:$PATH OMABOX_TEST_RUN_NS=1229 ob run -b "$B" -d -q --print-log -- echo omabox-t229 2>&1)
  check_eq "run -d over a link the box put at its log's name: the path" "$D/home/run-1229.log" "$out"
  check "...the log is the box's, with the output" until_ok 5 bash -c "[ -f '$D/home/run-1229.log' ] && [ ! -L '$D/home/run-1229.log' ] && grep -qx omabox-t229 '$D/home/run-1229.log'"
  check_eq "...the link's target untouched" keep "$(cat "$TMP/rep-victim")"
  ob down "$B" >/dev/null 2>&1
}

# jobs, stop, wait job and wait log (#299, finding 587): a run -d job listed, stopped and waited for
# by its pid, with no host pgrep, kill or loop over its log.
t_jobs() {
  local B=$P-jobs out err rc pid wpid lpid D
  up_ok "$B" --no-shell --net isolated || { no "up" "$UP_OUT"; return; }
  D=$(ob path "$B")
  err=$(ob jobs -b "$B" 2>&1 >/dev/null)
  check_eq "jobs with none: said" "omabox: no run -d job runs in box '$B'" "$err"
  check_eq "...--json: []" "[]" "$(ob jobs -b "$B" --json)"
  err=$(ob run -b "$B" -d -- sleep 621 2>&1 >/dev/null)
  check_match "run -d says the job's pid" "^omabox: started in box '$B' \(pid [0-9]+, log: $D/home/run-[0-9]+\.log, /home/sbx/run-[0-9]+\.log in the box\)$" "$err"
  pid=$(sed -n 's/.*(pid \([0-9]*\),.*/\1/p' <<<"$err")
  out=$(ob jobs -b "$B")
  check_match "jobs: its pid, age, processes, log and command" "^PID +AGE +PROCS +LOG +COMMAND"$'\n'"$pid +[0-9]+s +1 +$D/home/run-[0-9]+\.log +sleep 621$" "$out"
  check_eq "...--json" "$pid 1 sleep,621" "$(ob jobs -b "$B" --json | jq -r '.[] | "\(.pid) \(.processes) \(.argv | join(","))"')"
  ob run -b "$B" -d -q --wait -- foot -T J sleep 622 >/dev/null
  wpid=$(ob windows -b "$B" --json | jq -r '.[] | select(.title == "J") | .pid')
  err=$(ob stop -b "$B" "$wpid" 2>&1); rc=$?
  check_eq "stop a job by its window's pid: 0" 0 "$rc"
  check_match "...said, with its window" "^omabox: stopped job $wpid \(foot -T J sleep 622\), 1 window, in [0-9.]+s$" "$err"
  check_eq "...its window gone" 0 "$(ob windows -b "$B" --json | jq '[.[] | select(.title == "J")] | length')"
  check_eq "...not said as an end by the next command" "" "$(ob jobs -b "$B" 2>&1 >/dev/null | grep 'run -d job')"
  check_eq "...jobs lists the other one only" "$pid" "$(ob jobs -b "$B" --json | jq -r '.[].pid')"
  # A process of the box that is no job's: refused, nothing stopped
  err=$(ob stop -b "$B" 1 2>&1); rc=$?
  check_eq "stop of a pid no job has: exit 1" 1 "$rc"
  check_match "...said, with what stops another process" "no run -d job of pid 1 runs in box '$B'.*run -- kill 1" "$err"
  check_eq "...the job still runs" "$pid" "$(ob jobs -b "$B" --json | jq -r '.[].pid')"
  check_eq "stop with no job: a usage error" 2 "$(ob stop -b "$B" >/dev/null 2>&1; echo $?)"
  # wait job: the latest job's end, with its status; at once once it ended
  ob run -b "$B" -d -q -- sh -c 'sleep 1; exit 3'
  out=$(ob wait -b "$B" job); rc=$?
  check_eq "wait job (the latest): satisfied" 0 "$rc"
  check_match "...with how it ended" "^satisfied: job [0-9]+ \(sh -c sleep 1; exit 3\) ended after [0-9.]+s: exited with status 3$" "$out"
  lpid=$(sed -n 's/^satisfied: job \([0-9]*\) .*/\1/p' <<<"$out")
  ob jobs -b "$B" >/dev/null 2>&1
  out=$(ob wait -b "$B" job "$lpid"); rc=$?
  check_eq "...asked again once it ended and was said: at once" 0 "$rc"
  check_match "...the same" "^satisfied: job $lpid \(sh -c sleep 1; exit 3\) ended after 0\.[0-9]+s: exited with status 3$" "$out"
  out=$(ob wait -b "$B" --timeout 1s job "$pid"); rc=$?
  check_eq "wait job of one still running: 124" 124 "$rc"
  check_match "...said" "^unsatisfied: job $pid \(sleep 621\) still running after" "$out"
  check_eq "wait job of a pid no job had: exit 1" 1 "$(ob wait -b "$B" job 2 >/dev/null 2>&1; echo $?)"
  # A launcher that leaves a process behind: ended at once, --gone once that one is gone too
  ob run -b "$B" -d -q -- sh -c 'sleep 2 & exit 0'
  out=$(ob wait -b "$B" job)
  check_match "a launcher: ended, what it started said" "exited with status 0; 1 process it started still run \(--gone waits for them\)$" "$out"
  out=$(ob wait -b "$B" --timeout 8s job --gone); rc=$?
  check_eq "...--gone: satisfied once that one ended" 0 "$rc"
  check_match "...said" "^satisfied: job [0-9]+ \(sh -c sleep 2 & exit 0\) gone after" "$out"
  # wait log: a line of the job's log, there already or to come
  ob run -b "$B" -d -q -- sh -c 'echo starting; sleep 1; echo "Ready on port 8099"; exec sleep 623'
  out=$(ob wait -b "$B" log 'ready on port [0-9]+' -i); rc=$?
  check_eq "wait log -i (the latest job's): satisfied" 0 "$rc"
  check_match "...with the line" "^satisfied: a line matching ready on port \[0-9\]\+ in the log of job [0-9]+ \(.*\) after [0-9.]+s: Ready on port 8099$" "$out"
  check_match "...one there already counts" "^satisfied: .*: starting$" "$(ob wait -b "$B" log '^start')"
  out=$(ob wait -b "$B" --timeout 1s log "$pid" 'never said'); rc=$?
  check_eq "wait log JOB of a line that does not come: 124" 124 "$rc"
  check_match "...said" "^unsatisfied: no line matching never said in the log of job $pid \(sleep 621\) after" "$out"
  ob run -b "$B" -d -q -- sh -c 'echo only this; sleep 0.5'
  out=$(ob wait -b "$B" --timeout 8s log 'not this'); rc=$?
  check_eq "wait log of a job that ended without the line: exit 1" 1 "$rc"
  check_match "...said" "^unknown: job [0-9]+ exited with status 0, and its log has no line matching not this \(job ended\) after" "$out"
  check_eq "wait log of a bad expression: 2" 2 "$(ob wait -b "$B" log '(' >/dev/null 2>&1; echo $?)"
  # stop --all
  err=$(ob stop -b "$B" --all 2>&1); rc=$?
  check_eq "stop --all: 0" 0 "$rc"
  check_match "...each said" "stopped job $pid \(sleep 621\), 0 windows" "$err"
  check_eq "...none left" "[]" "$(ob jobs -b "$B" --json)"
  check_eq "...the box's sleeps gone" 0 "$(ob run -b "$B" -- pgrep -c sleep)"
  ob down "$B" >/dev/null 2>&1
}

# lua, log and events (issues #40, #41, #39): what needs no box.
t_unit_inspect() {
  check_match "lua: nothing to evaluate" "nothing to evaluate" "$(ob lua -b "$P-x" ' ' 2>&1)"
  # No EXPR is refused, not read from stdin: an open stdin would otherwise hang it (and this suite did).
  # The stdin is held open by a sleep killed right after: with `sleep 30 |` the capture (and with a
  # bare process substitution the suite's end) waited out the sleep, 30 s every run.
  local in sl; exec {in}< <(exec sleep 30); sl=$!
  check_match "lua: no EXPR is refused, stdin left alone" "nothing to evaluate" "$(timeout 10 "$CLI" lua -b "$P-x" <&"$in" 2>&1)"
  exec {in}<&-; kill "$sl" 2>/dev/null
  check_match "lua: a source starting with - goes after --" "goes after --" "$(ob lua -b "$P-x" -1 2>&1)"
  # (lua is a jailed agent's, as hyprctl is: broker_side.rs's broker_check_allows_and_refuses)
  check_match "log: an unknown log named, with the ones there are" "unknown log nope \(hyprland shell" "$(ob log -b "$P-x" nope 2>&1)"
  check_match "log -n takes a number or all" "-n takes a number" "$(ob log -b "$P-x" -n 5x 2>&1)"
  check_match "log --grep: a bad expression said" "takes a regular expression" "$(ob log -b "$P-x" --grep '(' 2>&1)"
  # #130: `--grep -i RE` took -i as the expression, and RE as a log's name.
  check_fails "log --grep -i RE: -i is the flag, RE the expression (#130)" grep -q "no log called" \
    <<<"$(ob log -b "$P-x" --grep -i 'plugin|error' 2>&1)"
  check_match "log --grep -x: an option taken for the expression, refused" "--grep takes RE" "$(ob log -b "$P-x" --grep -x 2>&1)"
  # (log is a jailed agent's (its own boxes only: select_box): broker_side.rs's broker_check_allows_and_refuses)
  check_eq "events --since OFFSET" "123 0" "$(probe events_since 123)"
  check_match "events --since 30s: from then on" "^0 [0-9]{13}$" "$(probe events_since 30s)"
  mkdir -p "$TMP/ev"; printf 'm1 10\nm2 20\nm1 30\n' > "$TMP/ev/events.marks"
  check_eq "events --since MARK: its latest offset" "30 0" "$(probe events_since m1 "$TMP/ev" x)"
  check_match "...one there is not, said" "no mark 'm9'" "$(probe events_since m9 "$TMP/ev" x 2>&1)"
  check_match "events --since junk refused" "takes a mark's name" "$(probe events_since '-x' 2>&1)"
  check_match "events --mark: a tame name" "starts with a letter" "$(ob events -b "$P-x" --mark '9;x' 2>&1)"
  check_match "events --mark goes alone" "goes alone" "$(ob events -b "$P-x" --mark m --grep x 2>&1)"
  check_match "events --until or -f" "not both" "$(ob events -b "$P-x" --until x -f 2>&1)"
  check_match "events: a bad expression said" "not a regular expression" "$(ob events -b "$P-x" --until '(' 2>&1)"
  # (events is a jailed agent's (its own boxes only): broker_side.rs's broker_check_allows_and_refuses)
  local out rc=0
  # The checkout bound back over the empty /tmp (#194): one under /tmp had its tool hidden (exit 127).
  out=$(bwrap --ro-bind / / --dev /dev --proc /proc --unshare-pid --unshare-net --tmpfs /opt --tmpfs /tmp \
        --ro-bind "$ROOT" "$ROOT" --die-with-parent env -i "$ROOT/tools/events/omabox-events" /tmp/ev.log 2>&1) || rc=$?
  check_eq "omabox-events refuses outside a box" 2 "$rc"
  check_match "...and says so" "only runs inside an omabox box" "$out"
}

# lua, log and events (issues #40, #41, #39) in a box of their own.
t_inspect() {
  local B=$P-insp out rc
  up_ok "$B" --no-shell --net isolated || { no "up" "$UP_OUT"; return; }
  # lua (finding 106): the value, not hyprctl's "ok".
  check_eq "lua: an expression's value" 2 "$(ob lua -b "$B" '1 + 1')"
  check_eq "lua: statements, what they return, one line each" $'3\nb' "$(ob lua -b "$B" 'local a = 3; return a, "b"')"
  check_eq "lua: a table as JSON" '{"a":[1,2],"b":true}' "$(ob lua -b "$B" '{a = {1, 2}, b = true}')"
  check_eq "lua: nil" nil "$(ob lua -b "$B" 'nil')"
  check_eq "lua: a statement returning nothing prints nothing" "" "$(ob lua -b "$B" 'omabox_t = 1')"
  check_eq "...the global is there for the next call" 1 "$(ob lua -b "$B" 'omabox_t')"
  check_eq "lua: brackets, quotes and a newline in the source are not quoting" $'x]]\n]=]"\'' "$(ob lua -b "$B" '"x]]\n]=]\"'"'"'"')"
  check_eq "lua: a source that ends in ]" 5 "$(ob lua -b "$B" '({5})[1]')"
  check_eq "lua --json: strings quoted" $'"s"\n1' "$(ob lua -b "$B" --json '"s", 1')"
  check_eq "lua: a NUL survives the trip (JSON)" '"a\u0000b"' "$(ob lua -b "$B" --json '"a\0b"')"
  check_eq "lua: a byte that is not UTF-8 is \\u00XX (here as jq reads it), not U+FFFD (#113); UTF-8 stays" '"aÿbétéÃ"' \
    "$(ob lua -b "$B" --json '"a\xffb\xe9t\xc3\xa9\xc3"')"
  check_eq "...a stray byte after a 4-byte character" '"😀'$'\xc2\x80''"' "$(ob lua -b "$B" --json '"\xf0\x9f\x98\x80\x80"')"
  check_eq "lua: a Hyprland object's fields (from its stubs)" 1920 "$(ob lua -b "$B" 'hl.get_monitors()[1]' | jq .width)"
  check_match "...an object inside one is its name" '^"HL\.Workspace' "$(ob lua -b "$B" 'hl.get_monitors()[1]' | jq .active_workspace)"
  check_eq "lua: the source on stdin" 42 "$(echo 'return 40 + 2' | ob lua -b "$B" -)"
  out=$(ob lua -b "$B" 'error("boom")' 2>&1); rc=$?
  check_eq "lua: a Lua error is exit 1" 1 "$rc"
  check_eq "...with its message" "lua: lua:1: boom" "$out"
  check_match "lua: a syntax error too" "^lua: lua:1: .*near" "$(ob lua -b "$B" '1 +' 2>&1)"
  # #107, finding 176: a metamethod's error while encoding is a Lua error too; -1 after the source is source.
  check_eq "lua: an error in a value's metamethod is a Lua error" "1 lua: lua:1: boom" \
    "$(out=$(ob lua -b "$B" 'return setmetatable({}, {__len = function() error("boom") end})' 2>&1); echo "$? $out")"
  check_eq "lua return -1" -1 "$(ob lua -b "$B" return -1)"
  # #130: a dispatcher returned is not run, and agents read its value as "ran": said on stderr.
  ob run -b "$B" -- rm -f /tmp/omabox-t130
  out=$(ob lua -b "$B" 'hl.dsp.exec_cmd("touch /tmp/omabox-t130")' 2>&1 >/dev/null)
  check_match "lua: a dispatcher returned is said not run (#130)" "a dispatcher, returned and not run: omabox lua 'hl\.dispatch\(EXPR\)'" "$out"
  check_eq "...its value as before, exit 0" "0 HL.Dispatcher" "$(v=$(ob lua -b "$B" 'hl.dsp.exec_cmd("true")' 2>/dev/null); echo "$? $v")"
  sleep 0.5
  check_fails "...and it did not run" ob run -b "$B" -- test -e /tmp/omabox-t130
  check_match "lua: a function, said not called" "a function, returned and not called" "$(ob lua -b "$B" 'function() end' 2>&1 >/dev/null)"
  check_eq "...a plain value says nothing more" "" "$(ob lua -b "$B" '1, "HL.Dispatcher"' 2>&1 >/dev/null)"
  check_match "...a source starting with - still needs --" "unknown option -1" "$(ob lua -b "$B" -1 2>&1)"
  # Calls at once share nothing (no file between them).
  local i pids=(); for i in 1 2 3 4 5 6; do ob lua -b "$B" "$i * 11" > "$TMP/lua.$i" 2>&1 & pids+=($!); done
  wait "${pids[@]}"   # (not a bare wait: the suite's host watcher is a job too)
  check_eq "lua: six calls at once each get their own answer" "11 22 33 44 55 66" "$(cat "$TMP"/lua.[1-6] | paste -sd' ')"
  # events (finding 108): recorded from the box's start, stamped, marks as byte offsets.
  local E; E=$(ob path -b "$B")/home/events.log
  check_match "events: recorded from the start" '^[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3} omabox>>listening$' "$(ob events -b "$B" | head -1)"
  check "...each line stamped in the file" bash -c "! grep -qvE '^[0-9]+\.[0-9]{3} [^ ]' '$E'"
  local m1; m1=$(ob events -b "$B" --mark m1 2>/dev/null)
  check_match "events --mark prints the offset" '^[0-9]+$' "$m1"
  ob run -b "$B" -d --wait -- foot -T evt sleep 600 >/dev/null 2>&1
  check_match "events --since MARK --grep --json" ',evt$' "$(ob events -b "$B" --since m1 --grep '^openwindow>>' --json | jq -r .data)"
  # The same start: the first read is where the second begins (#116: the end of run -d --wait's
  # screen watch, screencast>>0, could be logged between the two reads).
  local e1 e2; e1=$(ob events -b "$B" --since m1); e2=$(ob events -b "$B" --since "$m1")
  check "...--since OFFSET reads from the same place" test -n "$e1" -a "${e2:0:${#e1}}" = "$e1"
  check_fails "...nothing from before the mark" bash -c "'$CLI' events -b '$B' --since m1 | grep -q 'omabox>>listening'"
  ob events -b "$B" --mark v1x0 >/dev/null 2>&1; ob events -b "$B" --mark v1.0 >/dev/null 2>&1
  check "events --mark v1.0 leaves the mark v1x0 (a name, not a regex)" ob events -b "$B" --since v1x0
  # #107, finding 176: the other small refusals, said in words.
  check_match "keys -T is omabox's own" "-T is omabox's own" "$(ob keys -b "$B" -T 2>&1)"
  check_match "keys ü: -t named for a character outside the layout" "no key for 'ü' in this layout \(omabox keys -t 'ü' types" "$(ob keys -b "$B" ü 2>&1)"
  check_match "click off the screen: said" "click: 99999,99999 is off the 1920x1080 screen" "$(ob click -b "$B" 99999 99999 2>&1)"
  check_match "...pointer and drag too" "pointer: 1920,5 is off.*drag: 5,5000 is off" "$(ob pointer -b "$B" -- move 1920 5 2>&1; ob drag -b "$B" 5 5 5 5000 2>&1)"
  check_match "shot -g off the screen: said (#240: nothing inside is refused before grim)" "shot: -g 5000,5000 10x10 has nothing on the screen \\(1920x1080\\)" "$(ob shot -b "$B" -g "5000,5000 10x10" 2>&1)"
  # #111, finding 180: shot FILE as an argument, events --grep -i, mode host on a box (then back).
  ob shot -b "$B" "$TMP/positional.png" >/dev/null 2>&1
  check_match "shot FILE (an argument, not -o)" "PNG image data, 1920 x 1080" "$(file "$TMP/positional.png")"
  check_match "events --grep -i: any case" "openwindow>>" "$(ob events -b "$B" --grep '^OPENWINDOW>>' -i)"
  check_eq "...without -i, the case as given" "" "$(ob events -b "$B" --grep '^OPENWINDOW>>')"
  ob mode -b "$B" host >/dev/null 2>&1
  check_eq "mode host: the box takes your focused monitor's mode" "$(probe parse_mode host)" "$(ob mode -b "$B" | awk '{print $2}')"
  ob mode -b "$B" 1920x1080 >/dev/null 2>&1
  ob events -b "$B" --mark m2 >/dev/null 2>&1
  (sleep 1; ob hyprctl -b "$B" dispatch "hl.dsp.focus({ workspace = '4' })" >/dev/null) & local d=$!
  out=$(ob events -b "$B" --until '^workspace>>4$' --timeout 5s); rc=$?
  wait "$d"
  check_eq "events --until: an event to come, exit 0" 0 "$rc"
  check_match "...printed" ' workspace>>4$' "$out"
  check_match "events --since MARK --until: one that came already" ' workspacev2>>4,4$' "$(ob events -b "$B" --since m2 --until '^workspacev2>>' --timeout 1s)"
  check_eq "events --until none in time: 124" 124 "$(ob events -b "$B" --until '^nothing' --timeout 500ms >/dev/null 2>&1; echo $?)"
  check_match "events --since 1m" 'workspace>>4' "$(ob events -b "$B" --since 1m)"
  # Marks taken while events are written fall between lines (each is one append, never padded).
  ob run -b "$B" -d -- sh -c 'for i in $(seq 40); do hyprctl dispatch "hl.dsp.focus({ workspace = \"$((i % 3 + 1))\" })"; done' >/dev/null 2>&1
  local marks=() k; for k in 1 2 3 4 5 6 7 8; do marks+=("$(ob events -b "$B" --mark 2>/dev/null)"); done
  sleep 1
  check_eq "marks taken during a burst are at line ends" "" "$(for k in "${marks[@]}"; do [ "$k" = 0 ] || [ "$(head -c "$k" "$E" | tail -c 1 | od -An -tx1 | tr -d ' ')" = 0a ] || echo "$k"; done)"
  check_eq "...and the file has no NUL" "$(wc -c < "$E")" "$(tr -d '\0' < "$E" | wc -c)"
  # ($CLI: $! is omabox itself, not a subshell running ob; prlimit execs it. A soft core limit of 2
  # bytes, which nothing here lowers to 1 but omabox, for the check below.)
  prlimit --core=2: "$CLI" events -b "$B" -f > "$TMP/ev.f" 2>&1 & local ef=$!
  local bpid; bpid=$(cat "$(ob path -b "$B")/pid")
  until_ok 5 pgrep -f "^tail -c [+][0-9]+ -F --pid=$bpid " >/dev/null   # (following)
  # A tool omabox runs in the box's namespaces never makes a crash notification either (finding 492).
  check_eq "...its tail, a tool in the box's namespaces: core limit 1 byte" 1 \
    "$(prlimit --pid "$(pgrep -n -f "^tail -c [+][0-9]+ -F --pid=$bpid ")" --core -o SOFT --noheadings 2>&1 | tr -d ' ')"
  kill -TERM "$ef"; wait "$ef" 2>/dev/null
  check "events -f stopped: its tail goes too" until_ok 3 bash -c "! pgrep -f '^tail -c [+][0-9]+ -F --pid=$bpid '"
  check_match "log events: the file as it is" '^[0-9]+\.[0-9]{3} ' "$(ob log -b "$B" events -n 1)"
  "$CLI" events -b "$B" -f > "$TMP/ev2.f" 2>&1 & ef=$!
  until_ok 5 pgrep -f "^tail -c [+][0-9]+ -F --pid=$bpid " >/dev/null
  ob hyprctl -b "$B" dispatch "hl.dsp.focus({ workspace = '5' })" >/dev/null
  # log (finding 107): Hyprland's by default, the others by name, followed until the box goes.
  check_eq "log: Hyprland's, -n lines" 5 "$(ob log -b "$B" -n 5 | wc -l)"
  check_match "log --grep" "^DEBUG \]: Creating the " "$(ob log -b "$B" --grep 'creating the' -i -n 1)"
  check_match "log --grep -i RE, as grep users type it (#130)" "^DEBUG \]: Creating the " "$(ob log -b "$B" --grep -i 'creating the' -n 1)"
  check_match "path --logs: where each is" "^hyprland +$(ob path -b "$B")/run/hypr/[^/]+/hyprland\.log$" "$(ob path -b "$B" --logs | grep '^hyprland')"
  # path --run (#208): the box's /run/user/$UID on the host, where what the box writes there is.
  check_eq "path --run: <dir>/run" "$(ob path -b "$B")/run" "$(ob path -b "$B" --run)"
  ob run -b "$B" -- sh -c 'echo omabox-run-$$ > "$XDG_RUNTIME_DIR/omabox-208"' >/dev/null 2>&1
  check_match "...a file the box wrote to \$XDG_RUNTIME_DIR is there" '^omabox-run-[0-9]+$' "$(cat "$(ob path -b "$B" --run)/omabox-208" 2>&1)"
  check_fails "path --logs --run: one or the other" ob path -b "$B" --logs --run
  # path --home (#272): the box's /home/sbx on the host, a literal path for an agent's file tools.
  check_eq "path --home: <dir>/home" "$(ob path -b "$B")/home" "$(ob path -b "$B" --home)"
  ob run -b "$B" -- sh -c 'echo omabox-home-$$ > /home/sbx/omabox-272' >/dev/null 2>&1
  check_match "...a file the box wrote to /home/sbx is there" '^omabox-home-[0-9]+$' "$(cat "$(ob path -b "$B" --home)/omabox-272" 2>&1)"
  ob run -b "$B" -d -- sh -c 'echo omabox-log-1; sleep 1.5; echo omabox-log-2; sleep 600' >/dev/null 2>&1
  check "log run: the latest run -d's" until_ok 5 bash -c "'$CLI' log -b '$B' run | grep -qx omabox-log-1"
  ob log -b "$B" -f -n all run keyring > "$TMP/log.f" 2>&1 & local lf=$!
  check "log -f: a line that comes later" until_ok 5 grep -qx omabox-log-2 "$TMP/log.f"
  check_match "...under the log's name (several followed)" "^==> run <==" "$(head -1 "$TMP/log.f")"
  # A log the box swapped for a link to a host file: read as the box sees it, or not at all.
  echo omabox-host-secret > "$TMP/log.secret"
  ob run -b "$B" -- ln -sf "$TMP/log.secret" /home/sbx/labwc.log
  check_fails "log: a link out of the box is not followed (box up)" bash -c "'$CLI' log -b '$B' labwc 2>&1 | grep -q omabox-host-secret"
  local t0=$SECONDS
  ob run -b "$B" -- pkill -x Hyprland >/dev/null 2>&1
  wait "$lf"; rc=$?
  check_eq "log -f ends when the box goes down: exit 0" 0 "$rc"
  check "...within seconds, said" test $((SECONDS - t0)) -le 5 -a -n "$(grep "box '$B' went down" "$TMP/log.f")"
  wait "$ef"; rc=$?
  check_eq "events -f too" 0 "$rc"
  check_match "...having seen the box's events" ' workspace>>5' "$(cat "$TMP/ev2.f")"
  check_eq "log: a dead box's logs are still read" omabox-log-1 "$(ob log -b "$B" run -n 2 | head -1)"
  check_fails "...a link out of it is not followed (box down)" bash -c "'$CLI' log -b '$B' labwc 2>&1 | grep -q omabox-host-secret"
  ob down "$B" >/dev/null 2>&1
}

# #235: a path in the repo reached through a link out of it (a build cache's target/ -> ~/.cache/...),
# which dangles in a box (HOME is not mounted). repo_link_out finds the link on a path's way, with where
# it leads and where the path is then; one that stays in the repo is walked through; one that dangles on
# the host too, or a path outside the repo, is nothing. link_note gives the mount, or a box's refusal.
t_unit_link_out() {
  local d=$TMP/ulo r o
  r=$d/repo o=$d/out; mkdir -p "$r/sub/in" "$o/debug" "$d/h/.ssh"; : > "$o/debug/app"; : > "$r/sub/in/f"
  ln -s "$o" "$r/target"; ln -s ../out "$r/rel"; ln -s sub "$r/inside"; ln -s "$o" "$r/sub/in/deep"
  ln -s "$d/nothing" "$r/gone"; ln -s "$d/h/.ssh" "$r/keys"
  check_eq "a path through a link out of the repo: the link, where it leads, the path resolved" \
    "$r/target"$'\t'"$o"$'\t'"$o/debug/app" "$(probe repo_link_out "$r" "$r/target/debug/app")"
  check_eq "...the link itself" "$r/target"$'\t'"$o"$'\t'"$o" "$(probe repo_link_out "$r" "$r/target")"
  check_eq "...a relative link out (../out)" "$r/rel"$'\t'"$o"$'\t'"$o/debug" "$(probe repo_link_out "$r" "$r/rel/debug")"
  check_eq "...through a link that stays in the repo first" "$r/inside/in/deep"$'\t'"$o"$'\t'"$o/debug" \
    "$(probe repo_link_out "$r" "$r/inside/in/deep/debug")"
  check_eq "...a path with .. in it, normalized" "$r/target"$'\t'"$o"$'\t'"$o/debug" "$(probe repo_link_out "$r" "$r/sub/../target/debug")"
  check_fails "a link that stays in the repo: nothing" probe repo_link_out "$r" "$r/inside/in/f"
  check_fails "a plain path in the repo: nothing" probe repo_link_out "$r" "$r/sub/in/f"
  check_fails "a link that dangles on the host too: nothing" probe repo_link_out "$r" "$r/gone"
  check_fails "a path not there on the host: nothing" probe repo_link_out "$r" "$r/target/debug/nope"
  check_fails "a path outside the repo: nothing" probe repo_link_out "$r" "$o/debug/app"
  check_fails "...nor the repo's own top" probe repo_link_out "$r" "$r"
  check_match "link_note: the mount that gives it" "^omabox: note: $r/target -> $o: outside the box, where the link dangles; up --ro-bind $o mounts it$" \
    "$(HOME=$d/h probe link_note "" "$r/target" "$o" up 2>&1)"
  check_match "...one a box may not mount: why, no mount offered" "^omabox: note: $r/keys -> $d/h/.ssh: outside the box, where the link dangles; a box may not mount it \(it is inside $d/h/.ssh/ " \
    "$(HOME=$d/h probe link_note "" "$r/keys" "$d/h/.ssh" up 2>&1)"
  # The repo may be anyone's: its link is offered a mount only to a cache, outside HOME, or in no hidden
  # folder of HOME; elsewhere (settings, logins) the note says so and offers none.
  # shellcheck disable=SC2329 # called below
  lmprobe() { env -u XDG_CACHE_HOME -u XDG_CONFIG_HOME -u XDG_DATA_HOME -u XDG_STATE_HOME HOME="$d/h" "$PROBE" _rust probe "$@"; }
  check "link_mountable: under ~/.cache (a build cache's targets)" lmprobe link_mountable "$d/h/.cache/cc/targets/ab12"
  check "...under HOME in no hidden folder (another checkout's target)" lmprobe link_mountable "$d/h/code/other/target"
  check "...outside HOME" lmprobe link_mountable "$o"
  check_fails "...not ~/.cache itself" lmprobe link_mountable "$d/h/.cache"
  check_fails "...not a dot-dir of HOME" lmprobe link_mountable "$d/h/.config/someapp"
  check_fails "...nor a hidden folder deeper in HOME" lmprobe link_mountable "$d/h/code/app/.secrets"
  check_fails "...nor XDG_CONFIG_HOME elsewhere" env HOME="$d/h" XDG_CONFIG_HOME="$d/cfg" "$PROBE" _rust probe link_mountable "$d/cfg/app"
  mkdir -p "$d/h/.config/someapp"
  check_match "link_note: a dot-dir of HOME is said outside the box, no mount offered" \
    "^omabox: note: $r/conf -> $d/h/.config/someapp: outside the box, where the link dangles; no mount is offered for it \(it is in a hidden folder of your HOME, where settings and keys live\)$" \
    "$(lmprobe link_note "" "$r/conf" "$d/h/.config/someapp" up 2>&1)"
  check_match "...an agent's store: refused, as a secret store" "^omabox: note: $r/ag -> $d/h/.claude: outside the box, where the link dangles; a box may not mount it \(it is inside $d/h/.claude/ " \
    "$(HOME=$d/h probe link_note "" "$r/ag" "$d/h/.claude" up 2>&1)"
  # Names as the repo has them: control characters printed as ?, and one with a tab or newline skipped.
  local esc=$'e\e[31mRED\e[0m'
  check_eq "link_note: a control character in a name or target printed as ?" \
    "omabox: note: w?x leads through $r/e?[31mRED?[0m -> $o/e?[0m: outside the box, where the link dangles; up --ro-bind $o/e?[0m mounts it" \
    "$(HOME=$d/h probe link_note $'w\ax leads through ' "$r/$esc" "$o/"$'e\e[0m' up 2>&1)"
  ln -s "$o" "$r/"$'new\nline'; ln -s "$o" "$r/"$'a\tb'
  check_fails "repo_link_out: a link with a newline in its name: nothing" probe repo_link_out "$r" "$r/"$'new\nline'
  check_fails "...a tab: nothing" probe repo_link_out "$r" "$r/"$'a\tb'
}

# #235: a link at the top of the repo out of it, to a scratch folder (not the real HOME), named by `up`
# with the --ro-bind that gives it, and by `run` for a word that goes through it (the command still runs);
# none for a link that stays in the repo, one that dangles on the host too, or once --ro-bind has it. A
# throwaway's up says it with run --ro-bind, once (not again for the word).
t_link_out() {
  local B=$P-lo repo out=$TMP/lo-out err rc
  repo=$(tmp_repo lo); mkdir -p "$out/debug" "$repo/sub"; printf 'app\n' > "$out/debug/app"; echo hi > "$repo/README"
  ln -s "$out" "$repo/target"; ln -s sub "$repo/inside"; ln -s "$TMP/lo-nothing" "$repo/gone"
  err=$(cd "$repo" && ob up "$B" --no-shell 2>&1 >/dev/null) || { no "up from a repo with a link out" "$err"; return; }
  check_match "up: the link out named, with the mount" "note: $repo/target -> $out: outside the box, where the link dangles; up --ro-bind $out mounts it" "$err"
  check_eq "...that link only (not one in the repo, nor one dangling on the host too)" 1 "$(grep -c 'outside the box' <<<"$err")"
  err=$(cd "$repo" && ob run -b "$B" -- cat target/debug/app 2>&1); rc=$?
  check_match "run: a word through it named" "note: target/debug/app leads through $repo/target -> $out: outside the box, where the link dangles; down, then up --ro-bind $out mounts it" "$err"
  check_match "...and the command still ran (cat's own error, its status)" "cat: target/debug/app: No such file or directory" "$err"
  check_eq "...its status" 1 "$rc"
  err=$(cd "$repo" && ob run -b "$B" -- cat "$repo/README" inside 2>&1 >/dev/null)
  check_fails "run: no note for words in the repo that stay in it" grep -q 'outside the box' <<<"$err"
  # A link's name as the repo has it: an escape sequence in it is not printed as one.
  ln -s "$out" "$repo/"$'e\e[31mRED'
  err=$(cd "$repo" && ob run -b "$B" -- true $'e\e[31mRED/debug/app' 2>&1)
  check_match "run: a link named with an escape: named, its control character as ?" "note: e\?\[31mRED/debug/app leads through $repo/e\?\[31mRED -> $out:" "$err"
  check_fails "...no escape character printed" grep -q $'\e' <<<"$err"
  rm -f -- "$repo/"$'e\e[31mRED'
  ob down "$B" >/dev/null 2>&1
  err=$(cd "$repo" && ob up "$B" --no-shell --ro-bind "$out" 2>&1 >/dev/null) || { no "up --ro-bind the link's target" "$err"; return; }
  check_fails "up --ro-bind the target: no note" grep -q 'outside the box' <<<"$err"
  check_eq "...run: it is there, no note" "app" "$(cd "$repo" && ob run -b "$B" -- cat target/debug/app 2>"$TMP/lo.err")"
  check_eq "...nothing said" "" "$(cat "$TMP/lo.err")"
  ob down "$B" >/dev/null 2>&1
  err=$(cd "$repo" && env -u OMABOX "$CLI" run --no-shell -- cat target/debug/app 2>&1)
  check_match "a throwaway: its up names it, with run --ro-bind" "note: $repo/target -> $out: outside the box, where the link dangles; run --ro-bind $out mounts it" "$err"
  check_eq "...once" 1 "$(grep -c 'outside the box' <<<"$err")"
  check_eq "a throwaway with --ro-bind: there, nothing said" "app" "$(cd "$repo" && env -u OMABOX "$CLI" run --no-shell --ro-bind "$out" -- cat target/debug/app 2>"$TMP/lo.err")"
  check_fails "...no note" grep -q 'outside the box' "$TMP/lo.err"
}

# #251: the word of a command that names a path in the caller's dir, and the note `run` says of it.
t_unit_run_cwd_note() {
  local d=$TMP/ucw; mkdir -p "$d/dir/tests" "$d/dir/.config" "$d/home/.config" "$d/h"
  : > "$d/dir/tests/x.py"; : > "$d/dir/run.sh"
  check_eq "cwd_path_word: a relative path there" tests/x.py "$(probe cwd_path_word "$d/dir" "$d/home" python3 tests/x.py)"
  check_eq "...a ./ path, the command itself" ./run.sh "$(probe cwd_path_word "$d/dir" "$d/home" ./run.sh --fast)"
  check_eq "...a word of a script (sh -c)" tests "$(probe cwd_path_word "$d/dir" "$d/home" sh -c 'cd tests && make')"
  check_eq "...one with .. in it" ../run.sh "$(probe cwd_path_word "$d/dir/tests" "$d/home" cat ../run.sh)"
  check_fails "...a plain app: none" probe cwd_path_word "$d/dir" "$d/home" foot --version
  # shellcheck disable=SC2088 # a literal ~/x, as a command's word has it
  check_fails "...absolute, an option, ~: none" probe cwd_path_word "$d/dir" "$d/home" cat "$d/dir/run.sh" --file=tests '~/x'
  check_fails "...one the box HOME has too: none" probe cwd_path_word "$d/dir" "$d/home" ls .config
  check_fails "...a glob is not expanded" probe cwd_path_word "$d/dir" "$d/home" 'ls *'
  # (#325: a word that only shares a folder's name is no path: an IPC target, a subcommand)
  mkdir -p "$d/dir/stash" "$d/dir/console"
  check_fails "...a subcommand named as a folder there: none (#325)" probe cwd_path_word "$d/dir" "$d/home" omarchy-shell stash modules
  check_fails "...nor in a script's arguments" probe cwd_path_word "$d/dir" "$d/home" sh -c 'omarchy-shell console get top.hint | jq .'
  check_eq "...a script's later command is one" tests/x.py "$(probe cwd_path_word "$d/dir" "$d/home" sh -c 'true && tests/x.py')"
  check_eq "...the command itself, bare" run.sh "$(probe cwd_path_word "$d/dir" "$d/home" run.sh --x)"
  check_eq "cwd_note: a throwaway outside any repo" \
    "omabox: note: tests/x.py is relative to $d/dir, which is in no repo, so not in this throwaway box: the command runs in the box HOME (/home/sbx); run --overlay $d/dir (or --ro-bind, read-only) mounts it" \
    "$(probe cwd_note bx run tests/x.py "$d/dir" 1 2>&1)"
  check_eq "...a box up that does not have the dir" \
    "omabox: note: tests/x.py is relative to $d/dir, which box 'bx' does not have: the command runs in the box HOME (/home/sbx); down, then up --overlay $d/dir (or --ro-bind, read-only) mounts it" \
    "$(probe cwd_note bx "down, then up" tests/x.py "$d/dir" 0 2>&1)"
  check_match "...a dir a box may not mount (HOME): why, no mount offered" "the command runs in the box HOME \(/home/sbx\); a box may not mount it \(it contains $d/h/\)$" \
    "$(HOME=$d/h probe cwd_note bx run x "$d/h" 1 2>&1)"
  check_match "...a control character printed as ?" "note: e\?\[31m is relative to" "$(probe cwd_note bx run $'e\e[31m' "$d/dir" 1 2>&1)"
}

# #251: a command whose words name a path in the caller's dir, run where the box does not have that
# dir (a throwaway outside any repo, a box up from elsewhere), is said with the mount that brings the
# dir in, and still runs, in the box HOME. Nothing said with the dir mounted, from the box's repo, for a
# plain command, or for a word the box HOME has too.
t_run_cwd() {
  # (not $P-cwd: t_up_cwd_unreadable's box, and the two run in parallel)
  local B=$P-rcwd repo s=$TMP/cwd-scratch err rc
  repo=$(tmp_repo cwd); mkdir -p "$s/tests" "$s/.config" "$repo/tests"; echo hi > "$s/tests/x"; echo repo > "$repo/tests/x"
  err=$(cd "$s" && env -u OMABOX "$CLI" run --no-shell -- cat tests/x 2>&1); rc=$?
  check_match "a throwaway outside a repo: said, with the mount" \
    "note: tests/x is relative to $s, which is in no repo, so not in this throwaway box: the command runs in the box HOME \(/home/sbx\); run --overlay $s \(or --ro-bind, read-only\) mounts it" "$err"
  check_match "...the command still ran, in the box HOME" "cat: tests/x: No such file or directory" "$err"
  check_eq "...its status" 1 "$rc"
  check_eq "a throwaway with run --overlay of it: there" hi "$(cd "$s" && env -u OMABOX "$CLI" run --no-shell --overlay "$s" -- cat tests/x 2>"$TMP/cwd.err")"
  check_fails "...nothing said" grep -q 'is relative to' "$TMP/cwd.err"
  err=$(cd "$repo" && ob up "$B" --no-shell 2>&1 >/dev/null) || { no "up $B" "$err"; return; }
  check_eq "a box up, run from its repo: there" repo "$(cd "$repo" && ob run -b "$B" -- cat tests/x 2>"$TMP/cwd.err")"
  check_fails "...nothing said" grep -q 'is relative to' "$TMP/cwd.err"
  err=$(cd "$s" && ob run -b "$B" -- sh -c 'cat tests/x' 2>&1)
  check_match "...from another dir: said for a script's word, with down, then up" \
    "note: tests/x is relative to $s, which box '$B' does not have: the command runs in the box HOME \(/home/sbx\); down, then up --overlay $s \(or --ro-bind, read-only\) mounts it" "$err"
  err=$(cd "$s" && ob run -b "$B" -- true 2>&1)
  check_fails "...a plain command: nothing said" grep -q 'is relative to' <<<"$err"
  err=$(cd "$s" && ob run -b "$B" -- ls -d .config 2>&1)
  check_fails "...a word the box HOME has too: nothing said" grep -q 'is relative to' <<<"$err"
  err=$(cd "$s" && ob run -b "$B" -d -q -- cat tests/x 2>&1)
  check_match "...run -d: said too" "note: tests/x is relative to $s, which box '$B' does not have" "$err"
  check "down" ob down "$B"
}

# --- runner --------------------------------------------------------------------------------------

