  t_unit_aquamarine t_unit_aq_worktree t_unit_setup t_unit_no_theme t_unit_hyprland t_unit_quickshell t_unit_registry t_unit_leak_scan t_unit_evidence t_unit_jail_policy t_unit_jail_covers t_unit_jail_paths t_unit_relay t_unit_broker_units t_unit_inspect t_unit_parallel t_unit_which t_unit_brief t_unit_run_job t_unit_replace_others t_unit_link_out t_unit_user_unit t_unit_run_cwd_note t_unit_check t_unit_standin_mounts)
BOX=(t_leak_control t_cli_up t_run_options t_run_stdio t_main t_window t_window_size t_json t_keys_to_box t_keys_layer t_wait_facts t_click_layer t_pointer t_pixel t_burst t_changed t_shot_fit t_output t_output_nvidia t_gdb t_cpu t_wait t_replace t_jobs t_dbus_user_app t_tree t_click_find t_tree_layer t_agent_session t_mode_lock t_new t_keys t_peek t_peek_monitors t_guard t_special_ws t_uwsm_app t_widget t_widget_list t_widget_mark t_monitors t_monitors_nvidia t_record_layout t_record_layout_nvidia t_record_input t_record_hold t_audio t_monitors_turned t_monitors_turned_nvidia t_monitors_window t_monitors_wait t_monitors_wait_nvidia t_scale t_scale_nvidia t_no_pointer t_no_pointer_nvidia t_cursor_hw_nvidia t_throwaway t_throwaway_home t_throwaway_killed t_throwaway_dead t_isolated t_isolated_addr t_connected t_protect_ports t_protect_ports_ns t_seat_check t_mount_replaced t_host_paths t_jail_held t_jail_record t_jail_recipe t_ports t_isolated_no_pidfile t_up_killed t_orphan t_idle t_reap_race t_run_idle t_log_rolling t_stock_bar t_saves t_save_killed
  t_clip t_systemd t_omarchy_restart t_own_processes t_config_kept t_autoreload t_keys_down_up t_held_keys t_up_again t_theme_dir t_theme t_desk_backgrounds t_plugin_check t_plugin_hosted t_desk_shell t_no_seed t_desk_fonts t_user_hypr t_hypr_notify t_plugin_link t_plugin_add t_submap_release t_setup_prompts t_omarchy_tree t_lock t_hostile t_race t_failed_up t_up_software t_hung t_shell_crash t_shell_other_crash t_shell_hung t_shell_restart_race t_shell_restart_dup t_up_aborted t_up_signals t_up_signals_window t_extensions_secret t_hyprland_dies t_hyprland_crash t_pasta_dies t_other_userns t_no_new_privs t_no_shell t_hyprland t_quickshell t_no_git_identity t_git_worktree t_up_cwd_unreadable t_stale_pid t_home_sweep t_jail t_jail_down_race t_inspect t_which t_cli_box t_brief t_link_out t_run_cwd t_clean t_check)

# Box tests run in parallel (-j N; issue #60): each in a subshell of its own, its output shown whole
# when it ends. By default half the CPUs, at most one per 2 GB available and 8 (on 16 CPUs: 8, a full
# run in ~1.5 min; -j 1: ~8.5 min). No test ran slower beside 7 others than alone. These run alone first: none so far (a test that cannot share the machine,
# with a reason, goes here). In parallel, the slowest start first, so the run ends with short ones.
SERIAL=()
default_jobs() {
  local n m; n=$(($(nproc) / 2)) m=$(awk '/^MemAvailable:/ {print int($2 / 2097152)}' /proc/meminfo)
  [ "$m" -ge "$n" ] || n=$m; [ "$n" -le 8 ] || n=8; [ "$n" -ge 1 ] || n=1; echo "$n"
}
SLOW=(t_check t_agent_session t_widget t_widget_list t_run_idle t_guard t_peek t_peek_monitors t_reap_race t_wait t_pointer t_clip t_replace t_idle)

# The host's session through the CLI's own lookup (HOST_SIG, main's: probe host_session), so the suite
# runs from a guarded shell too. hyprctl itself: the CLI's host_hyprctl is not a probe (it would pass a
# dispatch on to the real desktop). None found: fails, never a hyprctl left to pick a session.
hostctl() { [ -n "${HOST_SIG:-}" ] || return 1; HYPRLAND_INSTANCE_SIGNATURE=$HOST_SIG hyprctl "$@"; }

# What this run ran on, for comparing a failure with a run that passed: the checkout, the stack a box
# is made of (the Hyprland binary boxes start and the host's running one can differ after an upgrade),
# and the GPU.
provenance() {
  local sha dirty="" so aq rn drv
  sha=$(git -C "$ROOT" rev-parse --short HEAD 2>/dev/null) || sha=unknown
  [ -z "$(git -C "$ROOT" status --porcelain 2>/dev/null)" ] || dirty=+dirty
  so=$(ldd "$(command -v Hyprland)" 2>/dev/null | awk '/libaquamarine/ {print $1; exit}')
  aq=$(readlink -f "$ROOT/build/prefix/lib/$so" 2>/dev/null); aq=${aq##*.so.}
  rn=$(probe render_node 2>/dev/null); drv=$(readlink -f "/sys/class/drm/${rn##*/}/device/driver" 2>/dev/null)
  printf 'omabox %s %s%s, Hyprland %s (host session %s), aquamarine %s (system %s), quickshell %s, labwc %s, bwrap %s, %s (%s), kernel %s\n' \
    "$(cat "$ROOT/VERSION")" "$sha" "$dirty" "$(Hyprland --version 2>/dev/null | awk 'NR == 1 {print $2}')" \
    "$(hostctl -j version | jq -r '.tag // "?"')" "${aq:-?}" "$(pkg-config --modversion aquamarine 2>/dev/null || echo ?)" \
    "$(quickshell --version 2>/dev/null | awk 'NR == 1 {print $2}')" "$(labwc --version 2>/dev/null | awk 'NR == 1 {print $2}')" \
    "$(bwrap --version | awk '{print $2}')" "${rn:-no render node}" "${drv##*/}" "$(uname -r)"
}

# Each test's wall time (#324 wave 5a): `test_time TEST US` adds "SECONDS<TAB>TEST" to the run's
# times.tsv (written by the runner alone: the parallel tests hand theirs back), and slowest_tests
# prints the 10 slowest at the end. now_us: the wall clock in µs, whatever the locale's decimal point.
now_us() { local t=${EPOCHREALTIME/[.,]/}; echo "$((10#$t))"; }
test_time() { printf '%d.%03d\t%s\n' $(($2 / 1000000)) $(($2 % 1000000 / 1000)) "$1" >> "$EVID/times.tsv"; }
slowest_tests() {
  [ -s "$EVID/times.tsv" ] || return 0
  echo "slowest:"
  LC_ALL=C sort -t $'\t' -k1,1nr "$EVID/times.tsv" | head -n 10 | while IFS=$'\t' read -r s t; do printf '  %8ss %s\n' "$s" "${t#t_}"; done
}

# S8 (#355): the host's pointer, read (hyprctl cursorpos, a read: it moves nothing) at a box test's
# start and end; one that moved is noted on that test, said only then (a check that passes every test
# would change no test's count). Only a note by default: you moving the mouse during a run moves it too,
# and the suite runs while you work. OMABOX_TEST_CURSOR=strict fails the test instead (a run you keep
# your hands off), =off leaves the check out.
cursor_at() { [ "${OMABOX_TEST_CURSOR:-}" = off ] || hostctl cursorpos 2>/dev/null; }
cursor_same() {
  [ "${OMABOX_TEST_CURSOR:-}" != off ] || return 0
  local now; now=$(cursor_at)
  [ "$1" != "$now" ] || return 0
  if [ "${OMABOX_TEST_CURSOR:-}" = strict ]; then
    no "S8: the host's pointer is where it was (#355)" "it was at $1, now at $now (if you moved the mouse during the run, that is why: run again without touching it)"
  else
    note "S8: the host's pointer moved during this test, $1 to $now: you, or the test (#355; OMABOX_TEST_CURSOR=strict fails on it)"
  fi
}
# S2 (#355): the files of box HOME DIR that are, byte for byte, one of the files under SRC... (your
# secret stores), 32 bytes to 1 MiB: smaller ones are one-word files no secret fits in and a box writes
# itself (keyrings/default is "login", gnupg's common.conf "use-keyboxd"). Sizes in bytes: find's
# -size -1M rounds up to whole MiB, and took only empty files. home_copies DIR SRC...
home_copies() {
  local dir=$1 sec sums=""; shift
  for sec; do
    [ -e "$sec" ] || continue
    sums+=$(command find "$sec" -type f -size +31c -size -1048576c -readable -exec md5sum {} + 2>/dev/null | cut -d' ' -f1)$'\n'
  done
  (cd "$dir/" && command find . -type f -size +31c -size -1048576c -exec md5sum {} + 2>/dev/null |
    awk 'NR == FNR { if ($1 != "") s[$1] = 1; next } ($1 in s) { print substr($0, 35) }' <(printf '%s' "$sums") -)
}
# ...and those that hold a private key, a token's shape, or TOKEN. home_shapes DIR TOKEN
home_shapes() {
  (cd "$1/" && command grep -rlIE -- "$2|-----BEGIN ([A-Z]+ )?PRIVATE KEY-----|ghp_[A-Za-z0-9]{36}|github_pat_[A-Za-z0-9_]{22,}|sk-ant-[A-Za-z0-9_-]{20,}|xox[abprs]-[0-9A-Za-z-]{10,}|AKIA[0-9A-Z]{16}" . 2>/dev/null | head -n 5)
}
# S6 (#355, #370): the processes of this run's boxes still running, one a line. A box of the run is
# one named PREFIX*, so named in a process's command line (a box dir, a reaper) or its environment
# (OMABOX_BOX, the box session's; OMABOX_NAME, a run's); one whose dir is in a stand-in runtime dir
# under the run's $TMP, whatever its name; or one whose reaper the run started (OMABOX_SUITE), as
# `up --new` and a session's name make. Only the runner, this scan, the host's event watcher and the
# test servers are set aside: what a test left running under the runner counts too.
box_procs() {
  local p c e mine
  mine=" $$ $BASHPID ${WATCH_PID:-} ${SERVERS[*]} "
  for p in /proc/[0-9]*; do
    [[ $mine != *" ${p#/proc/} "* ]] || continue
    c=$(tr '\0' ' ' 2>/dev/null < "$p/cmdline") 2>/dev/null || continue
    e=$(tr '\0' '\n' 2>/dev/null < "$p/environ") 2>/dev/null || e=""
    if [[ $c == *"/omabox/$1"* || $c == *" _reap $1"* || $c == *"$TMP/"*"/omabox/"* ]] ||
      grep -qE "^OMABOX_(BOX|NAME)=$1" <<<"$e" ||
      { [[ $c == *" _reap "* ]] && grep -qxF "OMABOX_SUITE=$OMABOX_SUITE" <<<"$e"; }; then
      echo "${p#/proc/} ${c:0:200}"
    fi
  done
}

# par_run JOBS TEST...: the tests, JOBS at a time, t_leak_control and the SLOW ones first. Each runs
# in a subshell (par_test) with counts of its own, which it hands back in a file; the runner shows its
# output whole when it ends, adds its counts and scans the host's events of its time (host_scan: the
# tests beside it share them). Then the events no test's time holds (gap_events).
par_run() {
  local jobs=$1 left=() t pid; shift
  local -A run=()
  for t in t_leak_control "${SLOW[@]}"; do [[ " $* " != *" $t "* ]] || left+=("$t"); done
  for t; do [[ " ${left[*]} " == *" $t "* ]] || left+=("$t"); done
  mkdir -p "$TMP/par"
  printf '%s == parallel\n' "$(date +%s.%3N)" >> "$EVID/host-events.log"
  while [ ${#left[@]} -gt 0 ] || [ ${#run[@]} -gt 0 ]; do
    while [ ${#left[@]} -gt 0 ] && [ ${#run[@]} -lt "$jobs" ]; do
      t=${left[0]} left=("${left[@]:1}")
      printf '%s == %s\n' "$(date +%s.%3N)" "$t" >> "$EVID/host-events.log"
      par_test "$t" > "$TMP/par/$t.out" 2>&1 &
      run[$!]=$t
    done
    wait -n -p pid "${!run[@]}"
    t=${run[$pid]}; unset "run[$pid]"
    printf '%s == /%s\n' "$(date +%s.%3N)" "$t" >> "$EVID/host-events.log"
    par_done "$t"
  done
  printf '%s == /parallel\n' "$(date +%s.%3N)" >> "$EVID/host-events.log"
  CUR=between
  local out; out=$(gap_events | leak_scan "$P-" "$HWS")
  [[ $out != *leak:* ]] || no "nothing reached the host desktop between the parallel tests" "$(grep '^leak:' <<<"$out")"
}
# par_test TEST (in its subshell): runs it with counts, notes and waits of its own; stops the servers
# it started (cleanup, in the runner, never sees them); hands back its counts, also when it stops
# midway (an exit, an unset variable), saying whether it reached its end.
par_test() {
  CUR=$1 pass=0 fail=0 failed=() skips=() SERVERS=() HELD="" LEAK_PROVEN="" PAR_T0=$SECONDS PAR_END=0 PAR_US=$(now_us)
  NOTES=$TMP/par/$1.notes UNTIL=$TMP/par/$1.until
  trap par_handback EXIT
  local c0; c0=$(cursor_at)
  "$CUR"; notes
  cursor_same "$c0"; notes
  [ $((pass + fail + ${#skips[@]})) -gt 0 ] || no "the test ran checks" "none: it returned before its first"
  PAR_END=1
}
par_handback() {
  local _f=("${failed[@]}") _s=("${skips[@]}")
  [ ${#SERVERS[@]} = 0 ] || kill "${SERVERS[@]}" 2>/dev/null
  { echo "_rp=$pass _rf=$fail _rl=${LEAK_PROVEN:-} _rt=$((SECONDS - PAR_T0)) _re=$PAR_END _ru=$(($(now_us) - PAR_US))"; declare -p _f _s; } > "$TMP/par/$CUR.res"
}
# par_done TEST (in the runner): its output, its counts, its host scan.
par_done() {
  local _rp=0 _rf=0 _rl="" _rt="?" _re=0 _ru="" _f=() _s=()
  CUR=$1
  if [ -f "$TMP/par/$1.res" ]; then
    # shellcheck disable=SC1090 # written by par_test
    source "$TMP/par/$1.res"
  fi
  echo "${1#t_}"
  cat "$TMP/par/$1.out"
  echo "       (${1#t_}: ${_rt}s)"
  [ -z "$_ru" ] || test_time "$1" "$_ru"
  pass=$((pass + _rp)) fail=$((fail + _rf))
  failed+=("${_f[@]}") skips+=("${_s[@]}")
  [ -z "$_rl" ] || LEAK_PROVEN=$_rl
  [ "$_re" = 1 ] || no "the test ran to its end" "it stopped midway (an exit, an unset variable?): its output is above"
  host_scan "$1" "/$1"
}

# The runner as one function, read whole before it starts: an edit to this file during a run (another
# agent's, in the same checkout) cannot change what the rest of the run does (as finding 66 did for
# bin/omabox).
main() {
  # (Underscored: the tests run inside this function and see its locals.)
  local _a _pats=() _filtered=0 _t _p _sel=() _n _unit_n=0 _jobs=${OMABOX_TEST_JOBS:-$(default_jobs)} _next=""
  for _a; do
    if [ -n "$_next" ]; then _jobs=$_a _next=""; continue; fi
    case $_a in --strict) STRICT=1 ;; -j|--jobs) _next=1 ;; -j*) _jobs=${_a#-j} ;; *) _pats+=("$_a") ;; esac
  done
  [[ $_jobs =~ ^[1-9][0-9]?$ ]] || { echo "-j: a number of parallel tests, 1-99 (1: one at a time), got '$_jobs'"; exit 2; }
  tests=("${UNIT[@]}" "${BOX[@]}")
  if [ "${_pats[*]}" = unit ]; then tests=("${UNIT[@]}")
  elif [ ${#_pats[@]} -gt 0 ]; then
    _filtered=1
    for _t in "${tests[@]}"; do for _p in "${_pats[@]}"; do [[ $_t == *"$_p"* ]] && { _sel+=("$_t"); break; }; done; done
    # A mistyped pattern would run nothing and pass: each one must match a test.
    for _p in "${_pats[@]}"; do
      [[ " ${tests[*]} " == *"$_p"* ]] || { echo "no test matches '$_p' (tests: ${tests[*]#t_})"; exit 2; }
    done
    tests=("${_sel[@]}")
  fi

  if [ "$INSTALLED" = 1 ]; then tools_ready installed; else tools_ready; fi || exit 2
  # The host's session, as omabox finds it (the probe is the build tools_ready made).
  HOST_SIG=$(probe host_session 2>/dev/null) && HOST_SIG=${HOST_SIG%% *}
  hostctl -j version >/dev/null 2>&1 || { echo "run from the Hyprland session (read-only hyprctl)"; exit 2; }
  ws0=$(hostctl -j activeworkspace | jq .id) win0=$(hostctl -j activewindow | jq -r '.address // ""')
  # omabox's workspace coming up is a leak (from #13's watch), unless you were on it already.
  # (A special one, special:NAME, is shown over the focused monitor's workspace.)
  HWS=$("$CLI" config workspace 2>/dev/null) || HWS=9
  ! hostctl -j monitors | jq -e --arg w "$HWS" '.[] | select(.focused) | select(.activeWorkspace.name == $w or .specialWorkspace.name == $w)' >/dev/null || HWS=
  # The run's folder, and the newest runs' (prune_runs).
  (umask 077; mkdir -p "$EVID")
  prune_runs "${EVID%/*}"
  provenance > "$EVID/provenance"
  echo "provenance: $(cat "$EVID/provenance")"
  # The host's event socket, listened to for the whole run (finding 80).
  HYPRLAND_INSTANCE_SIGNATURE=$HOST_SIG python3 -c "$WATCHER" "$XDG_RUNTIME_DIR/hypr/$HOST_SIG/.socket2.sock" $$ >> "$EVID/host-events.log" 2>&1 &
  WATCH_PID=$!
  until_ok 5 grep -q ' == watching$' "$EVID/host-events.log" || { echo "cannot listen to the host's events: $(cat "$EVID/host-events.log")"; exit 2; }

  # One box first (finding 130): when none can start here (refused: a headless box on NVIDIA without
  # aquamarine's fix, no pasta, ...), say why once and run the unit tests only, instead of every box
  # test failing at its `up` (166 checks did, on NVIDIA from an install).
  local _box=0 _out
  for _t in "${tests[@]}"; do [[ $_t == t_unit_* ]] || _box=1; done
  if [ $_box = 1 ]; then
    if _out=$("$CLI" up "$P-probe" 2>&1); then "$CLI" down "$P-probe" >/dev/null 2>&1
    else
      echo probe; CUR=probe
      no "a box starts here" "$_out"
      echo "       (no box can start here: the box tests are not run)"
      # A linked worktree (#182, finding 271): its boxes use the main checkout's aquamarine build.
      if [ -f "$ROOT/.git" ] && [[ $_out == *"aquamarine's fix"* ]]; then
        echo "       (a git worktree: its boxes use the main checkout's build/prefix when it has none of its own;"
        echo "       omabox setup --aquamarine builds one, in the main checkout for every worktree, or here)"
      fi
      tests=(); for _t in "${UNIT[@]}"; do [[ " ${_sel[*]:-${UNIT[*]}} " == *" $_t "* ]] && tests+=("$_t"); done
    fi
  fi

  # One at a time: the unit tests, SERIAL, and everything with -j 1. The rest in parallel after them.
  local _one=() _par=()
  for _t in "${tests[@]}"; do
    if [ "$_jobs" = 1 ] || [[ $_t == t_unit_* ]] || [[ " ${SERIAL[*]} " == *" $_t "* ]]; then _one+=("$_t"); else _par+=("$_t"); fi
  done
  # The suite's own functions as they are now. These tests run in this shell, so a helper of a test's
  # under a name the suite uses (note, check, ...) stays redefined for every test after it, the parallel
  # ones forked later too (#189, finding 252: t_unit_theme_dir's note() failed every slow wait after it).
  # Each such test fails, and the suite's are put back.
  local _t0 _us _fns _fdefs _f _was _chg _c0
  mapfile -t _fns < <(compgen -A function)
  _fdefs=$(declare -f "${_fns[@]}")
  for CUR in "${_one[@]}"; do
    _n=$((pass + fail + ${#skips[@]})) _t0=$SECONDS _us=$(now_us)
    rm -f "$UNTIL"
    printf '%s == %s\n' "$(date +%s.%3N)" "$CUR" >> "$EVID/host-events.log"
    echo "${CUR#t_}"; HELD=""
    [[ $CUR == t_unit_* ]] || _c0=$(cursor_at)
    "$CUR"; notes
    [[ $CUR == t_unit_* ]] || { cursor_same "$_c0"; notes; }
    if [ "$(declare -f "${_fns[@]}")" != "$_fdefs" ]; then
      _was=() _chg=()
      for _f in "${_fns[@]}"; do _was+=("$(declare -f "$_f")"); done
      eval "$_fdefs"
      for _f in "${!_fns[@]}"; do [ "${_was[_f]}" = "$(declare -f "${_fns[_f]}")" ] || _chg+=("${_fns[_f]}"); done
      no "the test leaves the suite's functions as they were" "it redefined ${_chg[*]} (put back for the tests after it)"
    fi
    [[ $CUR == t_unit_* ]] || echo "       (${CUR#t_}: $((SECONDS - _t0))s)"
    test_time "$CUR" $(($(now_us) - _us))
    [ $((pass + fail + ${#skips[@]})) -gt "$_n" ] || no "the test ran checks" "none: it returned before its first"
    [[ $CUR != t_unit_* ]] || _unit_n=$((_unit_n + pass + fail + ${#skips[@]} - _n))
    host_scan "$CUR"
  done
  [ ${#_par[@]} = 0 ] || par_run "$_jobs" "${_par[@]}"

  echo "host"
  CUR=host
  printf '%s == host\n' "$(date +%s.%3N)" >> "$EVID/host-events.log"
  sleep 0.5   # the last test's events, still on their way
  host_scan host
  check "the host's event watcher ran to the end" kill -0 "$WATCH_PID"
  if [[ " ${tests[*]} " == *" t_leak_control "* ]]; then
    if [ "${LEAK_PROVEN:-0}" = 1 ]; then ok "the leak detector is proven (t_leak_control)"
    else no "the leak detector is proven (t_leak_control)" "it failed: a clean host log proves nothing this run"; fi
  else echo "       (the leak detector is unproven this run: t_leak_control did not run)"; fi
  host_same "host workspace untouched" "$ws0" "$(hostctl -j activeworkspace | jq .id)" workspace
  host_same "host focused window untouched" "$win0" "$(hostctl -j activewindow | jq -r '.address // ""')" window
  # S6 (#355): every box this run left up taken down (a test stopped midway), then nothing of any of
  # its boxes may still run.
  local _left _procs
  _left=$("$CLI" ls --json 2>/dev/null | jq -r '.[].name' | grep "^$P-" | xargs)
  for _t in $_left; do "$CLI" down "$_t" >/dev/null 2>&1; done
  [ -z "$_left" ] || echo "       (left up at the end, taken down here: $_left)"
  # (down sends TERM to a box's reaper and peeks without waiting for them: one still listed right
  # after the last down gets a while to end, #370)
  local _until=$((SECONDS + 15))
  _procs=$(box_procs "$P-")
  while [ -n "$_procs" ] && [ $SECONDS -lt $_until ]; do sleep 0.5; _procs=$(box_procs "$P-"); done
  if [ -z "$_procs" ]; then ok "S6: no process of this run's boxes is left (#355)"
  else no "S6: no process of this run's boxes is left (#355)" "$_procs"; fi
  if [ $_filtered = 0 ]; then
    [ ${#tests[@]} = ${#UNIT[@]} ] || [ $((pass + fail)) -ge $MIN_CHECKS ] ||
      no "a full run has at least $MIN_CHECKS checks" "$((pass + fail)) ran (a test stopped checking?)"
    [ $_unit_n -ge $MIN_UNIT ] || no "the unit tests have at least $MIN_UNIT checks" "$_unit_n ran"
  fi

  echo
  slowest_tests
  echo "$pass passed, $fail failed, ${#skips[@]} skipped"
  for f in "${skips[@]}"; do echo "  skip $f"; done
  for f in "${failed[@]}"; do echo "  FAIL $f"; done
  [ $fail = 0 ] || echo "evidence: $EVID"
  [ $fail = 0 ]
}

# exit: after main returns, bash would read on from where it was in this file, so an edit that grew
# it during the run would run what sits there now. With it, shellcheck takes every test (called by
# name, "$CUR") for dead code: SC2329 is off for the file (finding 124).
main "$@"; exit
